-- Sources: data/i18n/ukUA. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_ukUA")
P.entries["quest:439"] = {n="Сліди Гнилошкірих",s="Оглядаючи баржу з трупами на Озері Лордамер, розвідники знаходять на руці нещодавно померлої жінки перстень із гравіюванням. Доповідь про похмуру знахідку Верховному Екзекуторові Гадреку в Гробниці викриває тривожну справу: гнилошкірі гноли грабують братські могили Тірісфалю й переправляють тіла на Острів Фенріс.",h="Оглядаючи баржу з трупами на Озері Лордамер, розвідники знаходять на руці нещодавно померлої жінки перстень...",kw={"сліди гнилошкірих","гнилошкірі гноли","перстень делії","озеро лордамер","острів фенріс","тірісфаль","верховний екзекутор гадрек"},ang={["faction:Horde"]="Гадрек керує діями Орди з Гробниці, щоб убезпечити Срібнолісся від дедалі більших таборів чудовиськ на кшталт зграї гнилошкірих, що зайняла Острів Фенріс.",["race:Undead"]="Осквернення братських могил Тірісфалю болісно зачіпає Відступників: їхніх полеглих рідних і невоскреслих побратимів вивозять як сировину для гнолівських алхімічних жахіть."},sec={{t="Моторошний вантаж",b="Оглядаючи покинутий, навантажений трупами пором на березі Озера Лордамер, розвідники-Відступники виявляють, що не всі мерці — давні рештки. З купи мертвечини стирчить незагорнута, позначена чумою рука нещодавно вбитої жінки з простою обручкою, на якій вигравіювано: «Для Делії». Сам човен свідчить про злагоджене перевезення, а не про безглузде бенкетування падальників."},{t="Розкрадачі могил",b="Коли перстень Делії приносять Верховному Екзекуторові Гадреку в Гробницю, командир Відступників швидко складає докупи всі сліди. Таке свіже тіло могло взятися лише з величезних братських могил по той бік кордону, у Галявинах Тірісфалю. Гнилошкірі гноли, що заполонили Срібнолісся, не просто нишпорять лісом — вони методично розкопують людські трупи й переправляють їх через воду на Острів Фенріс для зловісних, невідомих цілей."}},faq={{q="Що таке Човен із трупами?",a="Це старий пором, пришвартований біля берегів Озера Лордамер у Срібноліссі. Гнилошкірі гноли використовують його, щоб перевозити викопані людські трупи через озеро до своєї твердині на Острові Фенріс.",al={"човен із трупами","човен ветхої переправи","човен на озері"}},{q="Хто така Делія?",a="Делія — людина, жертва чуми, яку нещодавно поховали в братських могилах Галявин Тірісфалю. Її тіло викрали гнилошкірі гноли, і лишився тільки її перстень із гравіюванням — зачіпка для слідства.",al={"лор делії","хто така делія","перстень для делії"}},{q="Навіщо гноли збирають мертві тіла?",a="Гнилошкірі — гноли-нежить на службі Погибелі. Вони не їдять тіла, а грабують братські могили Тірісфалю й переправляють трупи до твердині Погибелі на Острові Фенріс.",al={"навіщо гноли збирають тіла","трупи гнилошкірих","мертві тіла острова фенріса"}},{q="Хто такий Верховний Екзекутор Гадрек?",a="Верховний Екзекутор Гадрек — воєначальник Відступників у Гробниці в Срібноліссі. Він керує обороною від місцевих загроз — диких гнилошкірих гнолів, чарівників Даларану й воргенів.",al={"гадрек","командир могили","екзекутор гадрек"}},{q="Звідки взялися трупи на човні?",a="За словами Верховного Екзекутора Гадрека, свіжість тіл свідчить, що їх викопали з братських могил у сусідніх Галявинах Тірісфалю, де поспіхом ховали жертв Погибелі й чуми.",al={"походження трупів на човні","човен із могил тірісфаля"}},{q="Що буде, коли повідомити Гадрекові про цю знахідку?",a="Гадрек посилає агентів дати відсіч гнилошкірим просто на Острові Фенріс і роздобути зразки смердючої сукровиці, яку вони виготовляють, а також доручає з'ясувати, ким була Делія, і повернути її перстень.",al={"після слідів гнилошкірих","продовження персня делії"}}},fp="14,310,16.398.0,21.442.1,30.217.0,15.220.0,37.183.1,28.227.0,44.200.0,49.221.1"}
P.entries["quest:440"] = {n="Перстень із гравіюванням",s="Верховний Екзекутор Гадрек посилає шукача пригод до Брілла зі знайденою обручкою, на якій вигравіювано ім'я жінки — Делії. Магістрат Севрен звіряється з міськими записами, щоб з'ясувати, хто вона й звідки взявся перстень.",h="Верховний Екзекутор Гадрек посилає шукача пригод до Брілла зі знайденою обручкою, на якій вигравіювано ім'я...",kw={"перстень із гравіюванням","делія","брілл","магістрат севрен","верховний екзекутор гадрек","гнилошкірі гноли"},ang={["faction:Horde"]="Зупинити гнилошкірих гнолів, що оскверняють могили на підвладних Орді землях Тірісфалю, — справа і безпеки, і відплати.",["race:Undead"]="Для Відступників перстень Делії — тихе нагадування про тонкі ниточки, що пов'язують їхнє живе минуле з похмурою, холодною теперішністю в Лордероні."},sec={{t="Пам'ятка в Срібноліссі",b="Розслідуючи справи гнилошкірих гнолів, що заполонили північні околиці Срібнолісся, розвідники знайшли перстень із вигравіюваним ім'ям Делії. Замість викинути дрібничку, Верховний Екзекутор Гадрек велить вам віднести її назад через кордон, до Брілла. Магістрат Севрен веде міські записи й поховальні книги краю Тірісфаль, тож саме він найімовірніше впізнає, хто вона була, — хоча Гадрек глибоко сумнівається, чи комусь із Відступників це ще не байдуже."},{t="Викрадений із землі",b="Отримавши перстень у Бріллі, Магістрат Севрен підтверджує, що Делія справді жила тут, померла й була похована в міській братській могилі. Її прикраса серед гнилошкірих у Срібноліссі викриває зловісне осквернення: спотворені чумою гноли грабують братські могили й потай вивозять трупи на південь для дослідів Погибелі, — і Севрен хоче, щоб гнолів винищили."}},faq={{q="Хто така Делія?",a="Делія — ім'я, вигравіюване на знайденому персні. Гадрек просить вас звернутися до записів Магістрата Севрена в Бріллі, щоб дізнатися, хто вона.",al={"хто така делія","лор делії","перстень делії"}},{q="Чому перстень Делії знайшли в Срібноліссі?",a="Перстень знайшли під час розслідування щодо гнилошкірих гнолів. Записи Севрена можуть допомогти з'ясувати, чия це пам'ятка і як вона потрапила до Срібнолісся.",al={"чому гноли мають перстень","перстень гнилошкірих","як перстень потрапив у срібнолісся"}},{q="Чому Верховний Екзекутор Гадрек сумнівається, що перстень важливий?",a="Гадрек зауважує, що нежиття часто стирає смертні прив'язаності. Він припускає, що коханий Делії або мертвий, або, якщо повстав Відступником, цілком байдужий до смертних обітниць і спогадів.",al={"діалог гадрека","чому гадрек цинічний","почуття відступників"}},{q="Яку роль у цьому завданні відіграє Магістрат Севрен?",a="Як магістрат Брілла, Севрен веде місцеві міські записи й реєстри померлих, тож може підтвердити, хто така Делія і де її поховано.",al={"севрен брилл","роль магістрата севрена","хто такий севрен"}},{q="Чи гнилошкірі гноли в союзі з Погибеллю?",a="Так. Гнилошкірих гнолів Срібнолісся заразила чума Погибелі; вони діють під темним впливом і збирають трупи для некромантичних потреб.",al={"чи гнилошкірі погибель","гноли погибелі","гноли срібнолісся"}},{q="Куди веде це розслідування далі?",a="Магістрат Севрен переглядає записи Брілла, щоб установити, хто така Делія. Те, що він дізнається, дає наступний слід у розслідуванні.",al={"що далі після персня","наступне завдання","продовження делії"}}},fp="17,227,24.501.0,20.398.1,15.136.1,49.144.1,53.180.0,52.158.0,48.163.0,40.122.1"}
P.entries["quest:441"] = {n="Релі та Андерсіті",s="Це завдання переносить розслідування з Брілла до Андерсіті: шукач пригод має доставити знайдений родинний перстень удівцеві на ім'я Ралей. Прикрасу знайшли на викраденому тілі жінки, яке везли на Острів Фенріс, і вона вказує на трагедію серед колишніх мешканців Лордерона. Її доставка запускає темну погоню за помстою.",h="Це завдання переносить розслідування з Брілла до Андерсіті: шукач пригод має доставити знайдений родинний...",kw={"релі та андерсіті","ралей андреан","делайя","перстень","магістрат севрен","острів фенріс","андерсіті"},ang={["faction:Horde"]="Проносячи пам'ятки старого Лордерона крізь ворота Андерсіті, ви бачите похмуру правду життя ваших союзників-Відступників.",["race:Undead"]="Холодна реакція Ралея на трагічну загибель дружини відбиває глибоку душевну травму, спільну для Відступників: їхні смертні прив'язаності зотліли й обернулися на гіркий гнів."},sec={{t="Трагічна реліквія",b="У Бріллі Магістрат Севрен склав докупи зачіпки про викрадене тіло й гравірований перстень, що колись належав жінці на ім'я Делайя. Сподіваючись з'ясувати, звідки перстень, і повернути його родині, Севрен відіслав того, хто його знайшов, глибоко в підземні зали Андерсіті — шукати Делайїного чоловіка, Ралея, що лишився по ній."},{t="Холодні серця, гірка помста",b="Ралей Андреан, якого можна знайти в гамірному Торговому Кварталі Андерсіті, одразу впізнає перстень своєї колишньої дружини. Як і в багатьох Відступників, нежиття висушило в ньому здатність до смутку, скорботи чи каяття через смерть Делайї й наругу над її тілом. Та там, де ніжні почуття відмерли, лишилася незламна жага відплати — і Ралей замислює помсту тим, хто порушив її останній спочинок."}},faq={{q="Хто дає це завдання?",a="Завдання дає Магістрат Севрен у містечку Брілл у Галявинах Тірісфалю — одразу після того, як ви повертаєте йому Перстень Делії.",al={"де взяти релі та андерсіті","хто дає завдання","завдання магістрата севрена"}},{q="Де знайти Ралея Андреана?",a="Ралей Андреан — у Торговому Кварталі Андерсіті, серед купців і ремісників підземного міста.",al={"місце ралея","де ралей","торговий квартал ралей"}},{q="Чий перстень треба доставити?",a="Перстень належав Делії — жінці з Брілла, яка до падіння Лордерона була дружиною Ралея Андреана.",al={"перстень делії","хто була делія","чий це перстень"}},{q="Чому Ралей не оплакує загиблу дружину?",a="Як Відступник, Ралей визнає, що ніжні почуття — горе й любов — у його мертвому серці охололи. Натомість давні пристрасті скисли в холодну жагу помсти.",al={"реакція ралея","чи ралею шкода","чому ралей байдужий"}},{q="Що буде після цього завдання?",a="Віддавши перстень, ви одразу переходите до завдання «Чоловікова помста», де Ралей посилає вас помститися за осквернення дружини.",al={"наступне завдання","продовження ралея","що далі"}},{q="Як перстень Делії знайшли спочатку?",a="Перстень знайшли під час завдання «Сліди Гнилошкірих»: його зняли з руки Делії серед загорнутих трупів на човні біля Ветхої Переправи в Срібноліссі.",al={"походження персня","звідки перстень"}}},fp="25,342,17.328.0,29.425.1,22.131.0,33.129.0,30.110.0,40.199.0,30.130.1,38.162.0"}
P.entries["quest:443"] = {n="Сукровиця Гнилошкірого",s="«Сукровиця Гнилошкірого» — завдання Орди в Срібноліссі від Верховного Екзекутора Гадрека в Гробниці. Прагнучи збагнути неприродних гнилошкірих гнолів, що заполонили Острів Фенріс, перш ніж іти на штурм, верхівка Відступників доручає шукачам пригод добути мерзенну, загадкову рідину, що тече жилами цих створінь, для дослідження.",h="«Сукровиця Гнилошкірого» — завдання Орди в Срібноліссі від Верховного Екзекутора Гадрека в Гробниці.",kw={"сукровиця гнилошкірого","гнилошкірі гноли","острів фенріс","аптекар ренферрел","верховний екзекутор гадрек","срібнолісся"},ang={["faction:Horde"]="Острів Фенріс лежить на східному краю Срібнолісся, і без нагляду сил Орди, що вбезпечують навколишні землі, він лишається небезпечною зоною.",["race:Undead"]="Для Відступників розуміння біологічних жахіть і штучних хвороб — водночас наука й інстинкт виживання. Дослідивши рідину гнилошкірих, Королівське Аптекарське Товариство з'ясує, чи загрожує ця зараза їхнім власним володінням у Лордероні."},sec={{t="Неприродна будова",b="Гнилошкірі гноли Срібнолісся далеко не звичайні дикі гуманоїди. Гниючі, агресивні, що смердять скверною, вони займають стратегічні позиції — як-от Острів Фенріс на Озері Лордамер. Верховний Екзекутор Гадрек розуміє, що їхня неприродна витривалість походить від тієї дивної рідини, що тече в їхніх тілах, тож йому потрібні справжні зразки, перш ніж кидати вояків у дорогий штурм."},{t="Аналіз аптекарів",b="Королівське Аптекарське Товариство має в Гробниці діяльний осередок, а Аптекар Ренферрел знається на біологічних і хімічних аномаліях. Приносячи Ренферрелу зразки цієї смердючої сукровиці гнилошкірих, Відступники сподіваються з'ясувати походження гнолів, дізнатися, хто їх створює, і знайти слабкі місця, якими можна скористатися в бою."}},faq={{q="Що таке сукровиця гнилошкірих?",a="Це неприродна смердюча рідина, що тече в тілах гнилошкірих гнолів на Острові Фенріс. Замість звичайної крові це мерзенне вариво підтримує їхній напівмертвий, гниючий стан і дає їм незвичайну живучість.",al={"що таке сукровиця","рідина гнилошкірих","сукровиця гнолів"}},{q="Навіщо Верховному Екзекуторові Гадреку зразки сукровиці?",a="Гадрек готує штурм Острова Фенріс, але військова мудрість велить спершу пізнати ворога. Здобувши зразки рідини для Аптекаря Ренферрела, Відступники сподіваються з'ясувати, хто створив гнилошкірих, і знайти біологічну слабину.",al={"навіщо збирати сукровицю","мета гадрека","чому гадрек хоче сукровицю"}},{q="Де водяться гнилошкірі гноли?",a="Вони живуть на Острові Фенріс, на схід через Озеро Лордамер від Ветхої Переправи в Срібноліссі. Береги острова, табори й довколишні руїни заполонили різні гнилошкірі — зокрема громили й ткачі чуми.",al={"де гнилошкірі","місце гнилошкірих гнолів","гноли фенріса"}},{q="Хто такий Аптекар Ренферрел?",a="Ренферрел — дослідник Королівського Аптекарського Товариства, що працює біля крипти в Гробниці. Він вивчає місцеві пошесті, чуми й дивні біологічні загрози по всьому Срібноліссю на користь Відступників.",al={"хто такий ренферрел","роль аптекаря ренферрела"}},{q="Що буде, коли Ренферрел отримає сукровицю?",a="Отримавши зразки, Ренферрел береться аналізувати хімічний склад рідини, щоб простежити, звідки взялися гнилошкірі, — і це веде до завдання «Походження Гнилошкірих».",al={"наступне завдання після сукровиці","продовження сукровиці гнилошкірих"}},{q="Навіщо Відступникам гноли?",a="Гнилошкірі гноли тримають Острів Фенріс — важливу твердиню на Озері Лордамер, що межує із землями Відступників. До того ж їхній гниючий стан і схожі на чуму здібності вказують на втручання ззовні, а це потенційна пряма загроза безпеці Андерсіті.",al={"чому відступники б'ються з гнолами","загроза гнолів срібнолісся"}}},fp="14,339,17.384.0,19.349.0,23.228.0,56.260.0,38.245.0,28.226.0,48.167.0,38.259.0"}
P.entries["quest:444"] = {n="Походження Гнилошкірих",s="«Походження Гнилошкірих» — завдання Відступників, що поєднує дослідження Королівського Аптекарського Товариства в Срібноліссі з чародійським досвідом Андерсіті. Проаналізувавши гнилі рідини, взяті з гнолів, Аптекар Ренферрел посилає шукача пригод до Бетора Айсшарда, щоб з'ясувати, яка магія стоїть за цими гниючими звірами.",h="«Походження Гнилошкірих» — завдання Відступників, що поєднує дослідження Королівського Аптекарського...",kw={"походження гнилошкірих","гнилошкірі гноли","аптекар ренферрел","бетор айсшард","іхор","срібнолісся","магічний квартал"},ang={["class:Mage"]="Роль Бетора Айсшарда показує, що магічне провидіння й учене чарівництво лишаються життєво важливими знаряддями для розгадування темних таємниць, перед якими безсила звичайна алхімія.",["class:Warlock"]="Скверна й чорнокнижницька магія, переплетені з некромантією в іхорі гнилошкірих, вказують на навмисне заборонене чаклунство в нетрях Срібнолісся.",["race:Undead"]="Це завдання показує співпрацю Королівського Аптекарського Товариства з майстрами магії Андерсіті: наука й чаклунство разом стоять на сторожі Лордерона."},sec={{t="Суміш смерті й скверни",b="Досліджуючи рідину, взяту з гнилошкірих гнолів, що заполонили Срібнолісся, Аптекар Ренферрел зумів розкласти мерзенну речовину на основні елементи. Попередній аналіз показав щось куди дивніше, ніж звичайна гноляча хвороба: іхор несе безпомилковий подвійний відбиток некромантії й чорнокнижницького мистецтва. Розуміючи, що сама лише алхімія не розплутає всіх чарів, Ренферрел доручає агентові віднести зразок просто до столиці на таємне вивчення."},{t="Аудієнція в мага",b="Зразок несуть до Бетора Айсшарда, досвідченого мага-Відступника, що перебуває високо в Магічному Кварталі Андерсіті. Бетор не належить до Королівського Аптекарського Товариства, але глибоке знання магічних і темних дисциплін робить його неоціненним помічником у розшифруванні незвичних сплетінь сили. Отримавши мерзенну пляшечку, Бетор відчуває давні, могутні чари, яких не бачив уже багато років, і одразу готує заклинання провидіння, щоб дізнатися, хто сплів цю погань."}},faq={{q="Хто дає гравцеві це завдання?",a="Аптекар Ренферрел, алхімік Королівського Аптекарського Товариства з Гробниці в Срібноліссі, дає це доручення, оглянувши сукровицю, здобуту в сусідніх гнилошкірих гнолів.",al={"хто починає походження гнилошкірих","де взяти походження гнилошкірих"}},{q="Чому Ренферрел посилає зразок Беторові Айсшарду?",a="Ренферрел виявляє, що сукровиця гнилошкірих просякнута некромантією й магією чорнокнижників. Оскільки сама алхімія не може повністю пояснити ці чари, він звертається по тайну мудрість до Бетора Айсшарда в Андерсіті, щоб той розгадав їхнє магічне походження.",al={"чому до бетора айсшарда","чому віддати зразок магові"}},{q="Де знайти Бетора Айсшарда?",a="Бетор Айсшард мешкає в Магічному Кварталі Андерсіті, серед дослідників тайних мистецтв і наставників.",al={"місце бетора","де бетор айсшард"}},{q="Хто такі гнилошкірі?",a="Гнилошкірі — гноли-нежить, що никають Срібноліссям. На відміну від звичайних безтямних звірів, їхній гниючий стан штучно викликали мерзенні магічні досліди.",al={"що таке гнилошкірі","гнилошкірі гноли срібнолісся"}},{q="Що стається, коли доставити зразок Беторові?",a="Бетор упізнає в рідині стародавню й потужну магію й зауважує, що не стикався з такими закляттями дуже давно. Він одразу береться творити закляття віщування, щоб вистежити джерело магії.",al={"що робить бетор","реакція бетора айсшарда"}},{q="Яке завдання наступне?",a="Після доставки й Беторового віщування він посилає шукача пригод у завдання «Тул Рейвенклов» — розслідувати діяльність мага-ренегата, що спотворив гнолів.",al={"наступне завдання після походження гнилошкірих","продовження походження гнилошкірих"}}},fp="16,341,29.531.0,22.497.1,35.194.0,54.252.0,33.109.0,23.165.0,51.233.0,22.175.1"}
P.entries["quest:445"] = {n="Доставка до Срібнолісся",s="Це доручення — важлива поштова місія, що пов'язує дослідження Королівського Аптекарського Товариства в Бріллі з його роботою в Срібноліссі. На прохання Аптекаря Йогаана ви несете цінні висновки Аптекареві Ренферрелу в Гробницю, щоб допомогти створити Нову Чуму Темної Леді.",h="Це доручення — важлива поштова місія, що пов'язує дослідження Королівського Аптекарського Товариства в Бріллі...",kw={"доставка до срібнолісся","аптекар йогаан","аптекар ренферрел","брілл","нова чума","королівське аптекарське товариство"},ang={["faction:Horde"]="Алхімічні досліди Відступників часто змушують інших союзників Орди звести брови, але безпечний прохід і поштова служба на шляху через Срібнолісся тримають північні землі під захистом.",["race:Undead"]="Доставивши ці дослідження, ви прямо служите Леді Сильвані й виживанню Відступників, допомагаючи здійснити головну мету Королівського Аптекарського Товариства."},sec={{t="Товариство, об'єднане метою",b="Королівське Аптекарське Товариство діє під прямим наказом Леді Сильвани Віндраннер: йому доручено створити Нову Чуму, здатну знищити і живих, і Погибель. Відрізані одна від одної лабораторії на землях Відступників не можуть працювати поодинці — виживання й поступ вимагають постійного зв'язку. У Бріллі Аптекар Йогаан зібрав результати дослідів, які треба без зволікань передати іншим дослідникам на місцях."},{t="Застава на півдні",b="Срібнолісся — наступний рубіж розширення й досліджень Відступників. Аптекар Ренферрел, що працює в Гробниці, керує біохімічними випробуваннями серед місцевих загроз — воргенів Мунрейдж, свавільних людей і решток Погибелі. Отримавши нотатки Йогаана з Галявин Тірісфалю, Ренферрел вплітає нові алхімічні знахідки у власні досліди й просуває великий задум Товариства."}},faq={{q="Навіщо Аптекар Йогаан надсилає ці документи?",a="Від членів Королівського Аптекарського Товариства очікують, що вони ділитимуться відкриттями, щоб пришвидшити створення Нової Чуми. Йогаанові потрібно доставити свої останні знахідки з Галявин Тірісфалю на південь, щоб інші дослідники могли спертися на його роботу.",al={"навіщо йогаан надсилає документи","нотатки йогаана","навіщо слати дослідження"}},{q="Де розташована Гробниця?",a="Гробниця — головна застава Відступників у Срібноліссі. Вона лежить на південь від кордону з Галявинами Тірісфалю й на південний захід від Андерсіті, при головній дорозі, що в'ється лісом.",al={"де гробниця","знайти ренферрела","місце гробниці"}},{q="Хто такий Аптекар Ренферрел?",a="Ренферрел — визначний член Королівського Аптекарського Товариства, що працює в Гробниці. Він керує польовими випробуваннями й вивчає незвичайні складники зі Срібнолісся, звітуючи вищому проводу Товариства в Андерсіті.",al={"роль ренферрела","хто такий ренферрел","ренферрел срібнолісся"}},{q="Що таке Нова Чума, про яку згадує Йогаан?",a="Нова Чума — особлива алхімічна зараза, яку розробляє Королівське Аптекарське Товариство з наказу Леді Сильвани Віндраннер. Вона має знищити і живих ворогів, і нежить — прислужників Короля-Ліча.",al={"нова чума","чума сильвани","яка чума"}},{q="Що за Некрополь згадує Ренферрел?",a="Ренферрел каже, що має надіслати зразки «до Некрополя», але з цієї розмови не зрозуміло, який саме некрополь він має на увазі.",al={"некрополь ренферрела","зразки ренферрела","зразки до некрополя"}},{q="Чому доручення дають шукачеві пригод, а не офіційним гінцям?",a="Кур'єри Відступників ходять небезпечними дорогами, де кишать здичавілі воргени, агресивні звірі й ворожі вцілілі люди. Довіривши дослідження спроможному шукачеві пригод, Товариство певне, що тонкі алхімічні нотатки дійдуть до Гробниці цілими, — а заразом залучає ще одні руки до справ у краї.",al={"чому я кур'єр","чому шукач пригод гінець"}}},fp="29,303,26.443.0,20.420.0,49.239.0,31.198.0,28.249.0,43.230.0,42.132.0,53.277.0"}
P.entries["quest:448"] = {n="Доповісти Гадреку",s="«Доповісти Гадреку» — військове донесення Орди, що спрямовує поборників у Гробниці до польового командувача Срібнолісся. Після того як Аптекар Ренферрел і Бетор Айсшард розслідували присутність Погибелі на Озері Лордамер, Верховний Екзекутор Гадрек налагоджує військові приготування до штурму Острова Фенріс. Це перехід від магічної розвідки до прямої тактичної війни.",h="«Доповісти Гадреку» — військове донесення Орди, що спрямовує поборників у Гробниці до польового командувача...",kw={"доповісти гадреку","верховний екзекутор гадрек","тул рейвенклов","острів фенріс","бетор айсшард","аптекар ренферрел"},ang={["faction:Horde"]="Гробниця керує західною обороною Орди в Лордероні, захищаючи підступи до руїн Столичного міста і від застав Погибелі, і від уцілілих людей.",["race:Undead"]="Для Відступників Тул Рейвенклов — поневолювальна воля Короля-Ліча, що підступає до їхнього порога, тож його знищення — справа виживання всього народу."},sec={{t="Загострення в Срібноліссі",b="Аптекар Ренферрел і маг Бетор Айсшард доклали чимало зусиль, щоб розгадати загрозу від некроманта-ренегата Тула Рейвенклова, та самими вченими студіями не вибити твердиню Погибелі, що набирає сили. Рейвенклов уже прив'язує неспокійних мерців по всьому Острову Фенріс, і Ренферрел збагнув, що біда давно переросла алхімічні чи чарівні рішення. Щоб спинити цю дедалі ширшу заразу, потрібні були тверда сталь і дисципліновані сили війська Відступників — і справа перейшла зі столів аптекарів просто на стіл командувача."},{t="Арсенал Верховного Екзекутора",b="Верховний Екзекутор Гадрек зі склепів Гробниці керує всіма стратегічними діями в Срібноліссі від імені Темної Леді. Коли до нього дійшли похмурі застереження Бетора щодо Рейвенклова, Гадрек діяв без вагань, знаючи, що некромант, який окопався біля західного берега Лордамера, — смертельна загроза флангам Андерсіті. Щоб удар по острівній фортеці вдався, Гадрек відчиняє зброярню місцевої залоги й споряджає бійців авангарду, перш ніж кинути їх у бій."}},faq={{q="Хто такий Верховний Екзекутор Гадрек?",a="Верховний Екзекутор Гадрек — командир військових сил Відступників у Гробниці. Він керує обороною на передовій і наступальними діями по всьому Срібноліссю й звітує безпосередньо проводу Андерсіті.",al={"гадрек","хто такий гадрек","командир гробниці"}},{q="Чому Аптекар Ренферрел посилає мене до Гадрека?",a="Аптекар Ренферрел і Бетор Айсшард з'ясували, що Тул Рейвенклов зібрав на Острові Фенріс небезпечне військо Погибелі. Щоб знищити окопаного некроманта, потрібні військова сила й належне спорядження, а не сама алхімія, тож Ренферрел скеровує вас до командира гарнізону.",al={"чому звітувати гадреку","зв'язок ренферрела і гадрека"}},{q="Де розташована Гробниця?",a="Гробниця — укріплене поселення Відступників і комплекс усипальниць у центрі Срібнолісся, головний осередок Орди й плацдарм для дій у краї.",al={"де гробниця","місце гробниці"}},{q="Хто такий Тул Рейвенклов?",a="Тул Рейвенклов — могутній некромант Погибелі, що захопив Фортецю Фенріс на Острові Фенріс посеред Озера Лордамер і, піднімаючи мерців, облаштував діючий плацдарм просто біля східного берега Срібнолісся.",al={"тул рейвенклов","лор тула"}},{q="Що буде після доповіді Гадрекові?",a="Гадрек видає вам припаси зі збройової Гробниці й наказує негайно вдарити по Острову Фенріс, щоб знищити Тула Рейвенклова й зламати владу Погибелі над Озером Лордамер.",al={"що далі після гадрека","наступне завдання гадрека"}},{q="Хто такий Бетор, якого згадує Гадрек?",a="Бетор Айсшард — маг Відступників із Магічного Кварталу Андерсіті, чиє магічне віщування допомогло з'ясувати справжню природу й небезпеку обрядів Тула Рейвенклова.",al={"хто такий бетор","бетор айсшард"}}},fp="16,408,24.571.0,27.524.0,28.235.0,49.294.0,31.183.0,23.194.0,39.189.0,34.181.0"}
P.entries["quest:449"] = {n="Звіт Смертоловів",s="«Звіт Скрадачів смерті» — важливе військове доручення гінця: доставити звіт Верховному Екзекуторові Гадреку в Гробницю. Врятувавши поранених скрадачів смерті в північних нетрях, ви несете зібрані ними відомості про несподівану діяльність Погибелі назад до верховного командування Відступників. Це донесення змінює уявлення Відступників про те, наскільки міцно вони тримають Срібнолісся.",h="«Звіт Скрадачів смерті» — важливе військове доручення гінця: доставити звіт Верховному Екзекуторові Гадреку в...",kw={"звіт скрадачів смерті","верховний екзекутор гадрек","скрадачі смерті","квінн","погибель","срібнолісся"},ang={["class:Rogue"]="Скрадачі смерті — вершина шпигунства Відступників; доставляючи їхні важливі донесення, ви показуєте, що стоїте пліч-о-пліч із найкращими тіньовими агентами Темної Леді.",["faction:Horde"]="Боротьба Відступників за Срібнолісся проти Погибелі вкрай важлива, щоб Орда міцно закріпилася на півночі Лордерона.",["race:Undead"]="Доставивши ці відомості, ви прямо підтримуєте розширення Андерсіті й доводите свою надійність Верховному Екзекуторові Гадреку та мережі скрадачів смерті."},sec={{t="Відомості з передової",b="Скрадачі смерті — очі, вуха й кинджали Темної Леді, що заходять у дикі нетрі попереду звичайних військових загонів. Біля кордону Тірісфалю й Срібнолісся передовий патруль, складаючи мапу ворожих пересувань, наштовхнувся на нищівний опір. Хоч Скрадач Смерті Квінн ледве пережив свої рани, а Ерланд з боєм вирвався в безпечне місце, їхня розвідка дала відомості, без яких Відступникам не утвердитися в Срібноліссі."},{t="Чинник Погибелі",b="Коли Верховний Екзекутор Гадрек переглядає запечатаний польовий звіт, той підтверджує похмурі новини: бездумні сили Погибелі тримаються в Срібноліссі куди міцніше й агресивніше, ніж передбачали стратеги Андерсіті. Замість того щоб просто займати покинуті людські хутори й приборкувати свавільних звірів, командування Гробниці мусить готуватися до злагодженого опору Погибелі в боротьбі за край."}},faq={{q="Що таке Звіт Смертоловця?",a="Це польове донесення, яке скрадачка смерті Рейн Йорік написала від імені свого пораненого розвідзагону. У ньому зібрано їхні спостереження за ворожими загрозами — насамперед за несподіваною діяльністю Погибелі на півночі Срібнолісся, — і ці відомості йдуть просто до командувача краю в Гробниці.",al={"звіт скрадача смерті","що за звіт","що дав йорік"}},{q="Хто такий Верховний Екзекутор Гадрек?",a="Верховний Екзекутор Гадрек — воєначальник, що керує діями Відступників у Срібноліссі. Із Гробниці він координує розвідників, оборонні лінії й ширшу кампанію з витіснення з краю і Погибелі, і ворожих людей.",al={"гадрек","верховний екзекутор гадрек","командир гробниці"}},{q="Чому відомості зі звіту здивували Гадрека?",a="Провід Відступників вважав, що Погибель у Срібноліссі розпорошена й нечисленна порівняно із запеклими боями в Галявинах Тірісфалю й Чумних Землях. Утрати й знахідки скрадачів смерті довели, що прислужники Короля-Ліча навіть так далеко на півдні міцно окопалися й лишаються небезпечними.",al={"чому гадрек здивований","реакція гадрека","погибель у срібноліссі"}},{q="Хто такі скрадачі смерті?",a="Скрадачі смерті — добірний таємний орден Відступників: убивці, шпигуни й передові розвідники під безпосереднім командуванням Леді Сильвани Віндраннер. Вони діють на спірних землях, щоб викорінювати загрози ще до того, як туди вступить регулярне військо.",al={"скрадачі смерті","лор скрадачів смерті","розбійники відступників"}},{q="Де розташована Гробниця?",a="Гробниця — крипта й головний табір у центрі Срібнолісся, трохи на захід від головного шляху з півночі на південь. Це основний гарнізон і місце перепочинку для сил Відступників, що діють у краї.",al={"де гробниця","місце гробниці"}},{q="Що буде, коли Гадрек прочитає звіт?",a="Усвідомивши серйозність становища й дедалі більші загрози в Срібноліссі, Гадрек скеровує вас до інших фахівців у Гробниці — насамперед до Аптекаря Ренферрела, щоб допомогти розробити засоби проти місцевих загроз.",al={"наступне завдання","що тепер","після гадрека"}}},fp="25,369,22.462.0,18.412.0,32.304.0,28.257.0,54.284.0,26.262.0,31.240.0,43.254.0"}
P.entries["quest:4495"] = {n="Добрий друг",s="Діранія Сілвершайн непокоїться, коли її постійний гість Іверрон не з'являється вчасно в Алдрассилі. Знаючи, що він часто навідується на пагорби біля кишенної павуками Печери Тіньової Нитки на півночі, вона просить перехожих шукачів пригод розшукати його.",h="Діранія Сілвершайн непокоїться, коли її постійний гість Іверрон не з'являється вчасно в Алдрассилі.",kw={"іверрон","діранія сілвершайн","печера тіньової нитки","павуки","тінедол","алдрассил"},ang={["class:Druid"]="Друїди, що пильнують природну рівновагу, упізнають в агресивних павуках Вебвуда біля Печери Тіньової Нитки симптом ширшого зіпсуття, яке вразило велике гілля.",["race:NightElf"]="Для юних калдорей, що починають свій шлях під Алдрассилом, відгукнутися на прохання Діранії — ранній урок громадської відповідальності й знайомство із загрозами, що тривожать колись мирну долину."},sec={{t="Зниклий гість",b="У тихому гіллі Тінедола щоденний лад укорінений глибоко, тож будь-яке відхилення від звички одразу впадає в око. Діранія Сілвершайн, що порається у своїх справах під захисною кроною Алдрассила, звикла до відвідин Іверрона — щодня, як за годинником. Коли минають години, а від нього ні звістки, тривога змушує її шукати допомоги в тих, хто вирушає в дикі хащі курганного гілля."},{t="Небезпека біля Печери Тіньової Нитки",b="Усі знають, що Іверрон любить блукати біля північних западин Тінедола, попри дедалі ближчу загрозу павуків Вебвуда. Печера Тіньової Нитки кишить агресивними павуками, тож сходити з утоптаних стежок для необачних мандрівників стає все небезпечніше. Обшукавши кам'янисті схили на захід від входу до печери, можна знайти Іверрона, який сховався там і відчайдушно потребує допомоги."}},faq={{q="Хто така Діранія Сілвершайн?",a="Діранія Сілвершайн — нічна ельфійка, що мешкає в Тінедолі під Алдрассилом. Вона щодня приятелює з Іверроном і одразу помічає, коли той не приходить у звичну годину.",al={"діранія","діранія сілвершайн лор","хто починає добрий друг"}},{q="Хто такий Іверрон?",a="Іверрон — нічний ельф із Тінедолу, відомий тим, що блукає пагорбами біля Печери Тіньової Нитки. Коли він не приходить до Діранії Сілвершайн, як щодня, його знаходять у безпорадному стані на скелях трохи на захід від входу до печери.",al={"іверрон","де іверрон","хто зниклий друг"}},{q="Де знайти Іверрона?",a="Іверрон ховається серед каміння й чагарів на схилі просто на захід від входу до Печери Тіньової Нитки, на півночі Тінедолу.",al={"місце іверрона","знайти іверрона","печера тіньової нитки іверрон"}},{q="Чому північна печера вважається небезпечною?",a="Печеру Тіньової Нитки й довколишні схили заполонили отруйні павуки-тенетники. Скверна, що шириться Тельдрассилом, розлютила цих істот, і самотнім мандрівникам там небезпечно.",al={"чому печера небезпечна","павуки в тіньовому яру","павуча печера тельдрассил"}},{q="Що буде, коли Іверрона знайдено?",a="Знайдений Іверрон зізнається, що його пригода біля павучої печери закінчилася для нього вкрай погано, — і починаються пошуки ліків у наступному завданні «Друг у біді».",al={"завдання після доброго друга","наступний крок іверрона","друг у біді"}},{q="Чому Діранія так швидко занепокоїлася через Іверрона?",a="Іверрон навідує Діранію щодня в ту саму годину. Оскільки він спізнився на кілька годин, а до того ж частенько вештався біля небезпечних павучих нір, вона злякалася найгіршого.",al={"чому діранія занепокоїлась","звичка іверрона","чому діранія помітила"}}},fp="13,242,17.400.0,26.395.0,27.205.0,15.221.0,27.147.0,46.204.0,35.181.1,48.196.0"}
P.entries["quest:45"] = {n="З'ясуй долю Рольфа",s="«З'ясуй долю Рольфа» — завдання Альянсу в Лісі Елвінн, що йде слідом двох зниклих вартових Стормвінда. Знайшовши понівечені рештки вартового Малакая на березі Озера Кам'яного Кургану, ви рушаєте слідом перетинчастих відбитків на схід, у вороже селище мурлоків, щоб дізнатися, що сталося з його товаришем Рольфом.",h="«З'ясуй долю Рольфа» — завдання Альянсу в Лісі Елвінн, що йде слідом двох зниклих вартових Стормвінда.",kw={"рольф","малакай","мурлоки","озеро кам'яного кургану","вартовий томас","медальйон"},ang={["class:Warrior"]="Стояти над тілом Рольфа Гартфорда — суворе нагадування про криваву правду, з якою стикаються піхотинці передової, що служать королівству.",["faction:Alliance"]="Знайдений Рольф підтверджує вразливість сільських кордонів Стормвінда, де через нестачу людей у гарнізонах навіть звичайні патрулі беззахисні перед смертоносними нападами диких істот."},sec={{t="Слід перетинчастих лап",b="Вартовий Томас розіслав патрулі східним Лісом Елвінн, щоб стримати зростання загроз, але двоє вартових — Малакай і Рольф — зникли біля берегів Озера Кам'яного Кургану. Оглянувши напівз'їдені рештки Малакая, ви помічаєте перетинчасті сліди, вдавлені в багнюку: вони ведуть на схід уздовж води просто до занедбаного табору мурлоків."},{t="Кінець патруля",b="Сліди приводять вас у серце прибережного поселення мурлоків. Там лежить ще один труп, обібраний тварюками. На шиї полеглого солдата висить гравірований медальйон, що підтверджує його особу: піхотинець Рольф Гартфорд. Отже, жоден із вартових не пережив засідки."}},faq={{q="Хто такий Рольф?",a="Рольф Гартфорд — піхотинець Стормвінда, якого разом із вартовим Малакаєм призначили патрулювати схід Лісу Елвінн під командуванням Вартового Томаса. Обох вартових здолали й убили мурлоки біля Озера Кам'яного Кургану.",al={"хто такий рольф","піхотинець рольф","рольф гартфорд"}},{q="Де лежить тіло Рольфа?",a="Тіло Рольфа лежить далі на схід, на південному березі Озера Кам'яного Кургану, у мурлочому селищі на краю озера.",al={"місце тіла рольфа","де рольф","знайти рольфа"}},{q="Що вартові робили біля Озера Кам'яного Кургану?",a="Вартовий Томас розставив вартових уздовж річок і озер на сході Елвінна, щоб стежити за набігами мурлоків і гнолів, але нечисленні патрулі виявилися вразливими перед раптовими злагодженими нападами.",al={"чому стражники загинули","що робили стражники","патруль стражників елвінн"}},{q="Як переконатися, що це тіло Рольфа?",a="На шиї розтерзаного тіла висить металевий медальйон із чітким написом «Піхотинець Рольф Гартфорд».",al={"медальйон рольфа","як впізнати рольфа"}},{q="Що буде, коли Рольфа знайдено?",a="Коли трагічну долю і Малакая, і Рольфа підтверджено, вам треба повернутися на захід, до мосту біля Лісозаготівельного Табору Східної Долини, і передати Вартовому Томасу сумну звістку.",al={"наступне завдання після рольфа","що робити після рольфа"}},{q="Чи незвичайна загроза — мурлоки на Озері Кам'яного Кургану?",a="Мурлоки в Елвінні стали незвично агресивними й злагодженими: вони просуваються вглиб суходолу до Озера Кам'яного Кургану й річок, загрожуючи і місцевій торгівлі, і самотнім патрулям.",al={"мурлокська загроза елвінн","чому мурлоки нападають"}}},fp="20,314,24.348.0,17.298.1,13.206.1,29.137.1,46.199.0,46.115.1,32.168.1,54.175.0"}
P.entries["quest:450"] = {n="Рецепт смерті",s="Головний Аптекар Фаранелл доручає шукачам пригод Орди відшукати втрачені дослідження Аптекаря Берарда в Селі Пайрвуд. Берард став жертвою тіньової магії Архімага Аруґала й лишив по собі важливі нотатки про давню заразу, що колись знищила все живе у водах Озера Лордамер.",h="Головний Аптекар Фаранелл доручає шукачам пригод Орди відшукати втрачені дослідження Аптекаря Берарда в Селі...",kw={"рецепт смерті","аптекар берард","село пайрвуд","аруґал","озеро лордамер","аптекар ренферрел","щоденник"},ang={["faction:Horde"]="Допомагаючи Королівському Аптекарському Товариству в Срібноліссі, ви допомагаєте Відступникам укріпити кордони проти диких жахів, що їх напустив Аруґал.",["race:Undead"]="Королівське Аптекарське Товариство виявляє холодний прагматизм: коли такий здібний колега, як Берард, гине в безумстві, його особисту трагедію відкидають, аби тільки врятувати смертоносні дослідження."},sec={{t="Розум, утрачений у тіні",b="До свого падіння Аптекар Берард вважався одним із найперспективніших дослідників Королівського Аптекарського Товариства. Перебуваючи в Селі Пайрвуд, він вивчав давні природні катастрофи, щоб допомогти алхімічним пошукам Відступників. Та коли Архімаг Аруґал напустив своє темне чаклунство на Срібнолісся, Берард не витримав прокляття й перетворився на бездумного слугу під владою мага."},{t="Таємниці Озера Лордамер",b="Хоч Головний Аптекар Фаранелл вважає Берарда безнадійно втраченим, його дослідження для Товариства неоціненні. Берард описував прикмети забутої зарази, що колись давно винищила все живе в Озері Лордамер. Якщо знайти його щоденник у корчмі Села Пайрвуд і передати Аптекареві Ренферрелу в Склепі, Королівське Аптекарське Товариство зможе пристосувати ці смертоносні властивості для арсеналу Темної Леді."}},faq={{q="Хто такий Аптекар Берард?",a="Аптекар Берард колись був блискучим дослідником Королівського Аптекарського Товариства в Срібноліссі. Його багатообіцяльна кар'єра урвалася, коли Архімаг Аруґал наклав на край темне прокляття, що зламало розум Берарда й зробило його невільником у Селі Пайрвуд.",al={"лор берарда","хто був берард","аптекар берард пайрвуд"}},{q="Навіщо Королівському Аптекарському Товариству щоденник Берарда?",a="Перш ніж його розум занепав, Берард описував стародавню чуму, що колись давно знищила все живе у водах Озера Лордамер. Товариство прагне здобути ці записи, щоб зрозуміти лютого збудника й використати його смертоносні механізми у своїх дослідженнях.",al={"навіщо щоденник","мета щоденника берарда","нотатки про чуму озера лордамер"}},{q="Де лежить щоденник Берарда?",a="Щоденник зберігається в кабінеті Берарда на горішньому поверсі заїзду Села Пайрвуд, у глибині селища. Уражений аптекар досі стереже свої колишні покої.",al={"де щоденник","знайти щоденник берарда","щоденник у корчмі пайрвуду"}},{q="Хто отримує знайдений щоденник?",a="Щоденник треба доставити Аптекареві Ренферрелу, який керує польовою роботою Королівського Аптекарського Товариства з Гробниці в Срібноліссі.",al={"кому здати щоденник берарда","кому нести щоденник","куди віднести щоденник"}},{q="Що сталося із Селом Пайрвуд?",a="Село Пайрвуд потрапило під згубний вплив Архімага Аруґала, що вивільнив магію Тіні із сусідньої Фортеці Шадовфенг. Прокляття спотворило розум і тіла селян, підкоривши їх темній волі Аруґала.",al={"прокляття пайрвуду","що не так із пайрвудом","прокляття аруґала пайрвуд"}},{q="Хто такий Головний Аптекар Фаранелл?",a="Головний Аптекар Фаранелл — очільник Королівського Аптекарського Товариства, що працює з Апотекаріуму в Андерсіті. Він особисто наглядає за створенням нових пошестей і отрут, щоб захищати Відступників і винищувати їхніх ворогів.",al={"фаранелл","хто дає рецепт смерті","керівник аптекарів андерсіті"}}},fp="18,279,21.406.0,29.469.1,25.269.0,60.266.0,34.183.0,35.156.0,34.221.0,34.245.0"}
P.entries["quest:4512"] = {n="Маленький слиз — велика подорож",s="У гамірних залах Айронфорджа гномський дослідник Ларіс Ґірдавдл прагне розкрити еволюційні таємниці Азероту, вивчаючи слизунів і слиз. Його дивує, чому Королівське Аптекарське Товариство так цікавиться цими мерзенними калюжами, тож він доручає шукачам пригод Альянсу вирушити до отруєного Сквернолісся й набрати в пляшечки зразків.",h="У гамірних залах Айронфорджа гномський дослідник Ларіс Ґірдавдл прагне розкрити еволюційні таємниці Азероту...",kw={"ларіс ґірдавдл","слиз","слизуни","сквернолісся","ліга дослідників","аптекарське товариство"},ang={["faction:Alliance"]="Стежачи за тим, що збирає Королівське Аптекарське Товариство, Альянс отримує важливі відомості про те, які зловісні зілля можуть варити в Андерсіті.",["race:Dwarf"]="Хоч традиційні дворфійські копачі віддають перевагу каменю й металу, а не драглистій жижі, Ліга Дослідників однаково виграє від дивацького запалу Ларіса.",["race:Gnome"]="Ларіс утілює невтомний розумовий запал гномів, які відбудовують своє добре ім'я й гідність після болісної втрати Гномреґана."},sec={{t="Дивна пристрасть",b="Більшість учених Ліги Дослідників займаються давніми реліквіями титанів чи похованими родоводами дворфів, а от Ларіс Ґірдавдл спрямував свій допитливий розум на тему, що хлюпає: слизунів. Вони трапляються всюди — на болотах, у проклятих лісах, у вологих руїнах, — і ці живі калюжі не вкладаються в жодну звичну біологічну класифікацію. Побачивши, як аптекарі Відступників збирають зразки слизу по всьому Лордерону, Ларіс вирішив з'ясувати, чому ці драглисті страхіття так цікавлять алхіміків Андерсіті."},{t="Первісні виділення",b="Ларіс має сміливу теорію: слизуни — не просто протиприродна погань чи побічний продукт магії, а первісні виділення, тісно пов'язані з самим народженням Азероту. Щоб довести свою гіпотезу, він посилає відважних розвідників за океан, під отруєне листя Сквернолісся, ловити у спеціально виготовлені банки Проклятих і Заплямованих слизунів."},{t="Гномам є що довести",b="За науковим запалом Ларіса стоїть глибоко особиста причина, знайома багатьом його родичам-вигнанцям. Після нищівного радіоактивного падіння Гномреґана тисячі гномів знайшли притулок як біженці біля Великої Кузні Айронфорджа. Здобувши для Ліги Дослідників проривне відкриття, Ларіс сподівається присоромити дворфів-скептиків і довести, що прийняти гномів у гірське місто було не просто милосердям, а надбанням, яке назавжди збагатило науку Альянсу."}},faq={{q="Хто такий Ларіс Ґірдавдл?",a="Ларіс Ґірдавдл — гномівський дослідник і вчений, що мешкає в Айронфорджі. Працюючи разом із Лігою Дослідників, він присвятив себе вивченню біологічного походження слизів по всьому Азероту.",al={"ларіс ґірдавдл","хто дає завдання","гном зі слизами"}},{q="Чому Ларіса так цікавлять слизи?",a="Ларіс підозрює, що слизи можуть бути пов'язані з походженням самого Азерота — як первісні виділення планети. До того ж, помітивши, що Королівське Аптекарське Товариство Відступників завзято збирає зразки слизу, він прагне розгадати їхні таємні властивості раніше за Орду.",al={"чому вивчати слизи","чому банки зі слизом","теорія слизів"}},{q="Де збирати зразки слизу?",a="Зразки треба зібрати з проклятих і сплюндрованих слизів, що блукають зіпсованими лісами Сквернолісся на півночі Калімдору, у порожні скляні посудини, які дає Ларіс.",al={"де слизи","місце осквернених слизів","місце проклятих слизів"}},{q="Навіщо Відступники збирають слизи?",a="Королівське Аптекарське Товариство постійно експериментує з отрутами, пошестями й біологічними жахіттями, щоб розвивати алхімію Відступників. Їхній інтерес до сирих слизів підказує вченим Альянсу, що ці істоти містять заразні чи мутагенні речовини.",al={"слизи андерсіті","слиз аптекарського товариства","навіщо відступникам слиз"}},{q="Як це завдання пов'язане з падінням Гномреґана?",a="Ларіс відчуває тягар біженця в Айронфорджі після того, як Гномреґан утрачено через трогів і радіацію. Він вірить, що великий науковий тріумф для Ліги Дослідників доведе: дворфи-господарі недарма дали гномам притулок.",al={"зв'язок з гномереґаном","стосунки дворфів і гномів","біженці гноми айронфордж"}},{q="Що буде, коли доставити зразки?",a="Ларіс одразу береться випробовувати зразки у своїй лабораторії в Айронфорджі, розвиваючи теорії про класифікацію слизів і їхнє стихійне походження.",al={"продовження слизу","що далі після банок зі слизом"}}},fp="30,342,20.525.0,24.368.0,21.478.0,24.213.0,39.279.0,37.177.0,38.240.0,54.270.0,43.163.0"}
P.entries["quest:4513"] = {n="Маленький слиз — велика подорож",s="Вивчивши заражені зразки, гномський дослідник Ларіс Ґірдавдл шукає чистого слизу, щоб зрозуміти, як ці дивні істоти пристосовуються до довкілля. Збагнувши, що слизуни вбирають зіпсовану природу таких місць, як Сквернолісся, він посилає шукачів пригод розшукати й зібрати чисті, незаймані зразки по всьому Калімдору.",h="Вивчивши заражені зразки, гномський дослідник Ларіс Ґірдавдл шукає чистого слизу, щоб зрозуміти, як ці дивні...",kw={"ларіс ґірдавдл","слиз","слизуни","кратер ун'ґоро","калімдор","контрольна група"},ang={["faction:Alliance"]="Шукачі пригод Альянсу вирушають з Айронфорджа в неприборкані дикі землі Калімдору, щоб підтримати гномську науку.",["race:Gnome"]="Ларіс — утілення класичного гномського наукового методу: перш ніж робити широкі висновки, він наполягає на ізоляції змінних і пошуку незабрудненої контрольної групи."},sec={{t="Питання чистоти",b="Перші досліди Ларіса Ґірдавдла в Айронфорджі одразу натрапили на перешкоду: слизуни, яких він вивчав, були наскрізь просякнуті темними силами Сквернолісся. Це довело, що слизуни вбирають і відображають риси свого оточення, але залишило вченого без контрольної групи. Щоб зрозуміти первісну природу слизунів, йому потрібні зразки, яких не торкнулися ні демонічна скверна, ні міський бруд."},{t="Слідами первісного слизу",b="Знайти незаражений слиз на Азероті, пошрамованому скверною й війною, нелегко. Слід зрештою веде далеко на південь, до доісторичної западини Кратера Ун'Ґоро, де в ізольованій первісній екосистемі процвітають Клейкі слизуни. Здобуваючи зразки цих диких створінь, шукачі пригод дають Ларісові рідкісний чистий матеріал, щоб він з'ясував, як ці безформні істоти взаємодіють із живою природою Азероту."}},faq={{q="Навіщо Ларісові Ґірдавдлу чисті зразки слизу?",a="Його попередні зразки зіпсувала спотворена енергія Сквернолісся. Щоб перевірити теорію, що слизи пристосовуються до довкілля й віддзеркалюють його, Ларісові потрібні бездоганні зразки з незабрудненого середовища — як чиста основа для порівняння.",al={"навіщо чистий слиз","чистий слиз ларіса","що таке чистий слиз"}},{q="Де водяться чисті слизи?",a="Чисті зразки можна зібрати з клейких слизів, що живуть у пишній первісній глушині Кратера Ун'Ґоро на півдні Калімдору.",al={"де чисті слизи","місце банок зі зразками","де чисті слизи водяться"}},{q="Хто такий Ларіс Ґірдавдл?",a="Це допитливий гномівський дослідник з Айронфорджа, що цілком присвятив себе розгадуванню біологічних таємниць слизів Азерота.",al={"хто такий ларіс","ларіс ґірдавдл лор"}},{q="Чим слизи такі цікаві для дослідників?",a="Слизи мають унікальну біологічну пристосовність: вони легко вбирають і віддзеркалюють магічні, природні й згубні риси земель, де живуть.",al={"чому слизи цікаві","лор слизів"}},{q="Чи це продовження попереднього доручення Ларіса?",a="Так. Раніше Ларіс уже просив слизів, щоб почати дослідження, але перші зразки виявилися сильно зіпсованими демонічною скверною Сквернолісся, тож тепер потрібні незаймані слизи.",al={"попереднє завдання ларіса","що було раніше"}},{q="Що Ларіс збирається робити зі зразками?",a="Він хоче порівняти чисті зразки зі зіпсованими, щоб зрозуміти, як зміни довкілля впливають на живих істот, а отже — і на все населення Азерота.",al={"дослідження слизу ларіса","для чого слиз"}}},fp="30,358,18.415.0,25.423.1,49.245.0,33.139.0,24.150.0,47.160.0,43.173.0,46.177.0"}
P.entries["quest:452"] = {n="Засідка в Пайрвуді",s="«Засідка в Пайрвуді» — важливий удар, який скрадачі смерті влаштовують у проклятому Селі Пайрвуд. Убивши місцеву людську раду, Відступники сподіваються зламати хватку Архімага Аруґала над проклятими мешканцями й послабити його фортецю, що височіє над селом.",h="«Засідка в Пайрвуді» — важливий удар, який скрадачі смерті влаштовують у проклятому Селі Пайрвуд.",kw={"засідка в пайрвуді","село пайрвуд","скрадачка смерті фаерлея","рада пайрвуда","лорд-мер моррісон","архімаг аруґал"},ang={["class:Rogue"]="Засідка — класичне ремесло скрадачів смерті: пробратися у ворожу твердиню, причаїтися й знищити ворожих командирів у самому осередку їхньої влади.",["faction:Horde"]="Розладнавши мережу Аруґалових маріонеток, ви послаблюєте більшу загрозу, що нависає над шляхом Орди через Срібнолісся до південних кордонів.",["race:Undead"]="Для Відступників утвердитися в південному Срібноліссі вкрай важливо, щоб боронити кордони Андерсіті, а знищення Аруґалових підлабузників на крок наближає їх до захоплення Пайрвуда."},sec={{t="Удар по маріонетках",b="Засівши в ратуші Села Пайрвуд, Скрадачка Смерті Фаерлея чатує на сільську верхівку. Архімаг Аруґал усамітнився у Фортеці Шадовфенг, поринувши в темне чаклунство, і покладається на місцеву Раду Пайрвуда як на маріонеток, що тримають лад серед ураженого люду. Фаерлея має намір знищити цю верхівку блискавичною засідкою, сподіваючись, що без посередництва ради дикі воргени, які блукають навколишніми лісами й сільськими вулицями, вирвуться з-під влади Аруґала."},{t="Удар по верхівці",b="Засідка цілить у кожного чинного члена місцевої влади, і вершиною стає смерть Лорда-мера Моррісона. Знищивши радників, коли ті один за одним заходять до зали засідань, Відступники завдають тяжкого удару по ланцюгу управління села. Андерсіті вважає цю різанину не просто помстою, а стратегічною передумовою того, щоб цілком захопити Село Пайрвуд і взяти в облогу божевільного архімага у Фортеці Шадовфенг."}},faq={{q="Хто така Скрадачка Смерті Фаерлея?",a="Скрадачка Смерті Фаерлея — агентка скрадачів смерті, провідної гільдії шпигунства й таємних убивств Відступників. Діючи в тилу ворога, вона закріпилася просто в Селі Пайрвуд, щоб координувати удари по місцевій опорі Архімага Аруґала.",al={"фаерлея","скрадачка смерті фаерлея","хто дає засідку в пайрвуді"}},{q="Чому Відступники хочуть смерті Ради Пайрвуда?",a="Аруґал використовує раду як політичних маріонеток, щоб тримати проклятих селян-людей слухняними й підконтрольними. Відступники вірять, що знищення цих провідників кине Пайрвуд у хаос і оберне воргенів проти Аруґала.",al={"чому вбити раду пайрвуду","мета ради пайрвуду","лор ради пайрвуду"}},{q="Хто очолює Раду Пайрвуда?",a="Раду очолює Лорд-мер Моррісон, що разом із радниками — Смізерсом, Тетчером і Брансвіком — опікується міськими справами, доки на них не влаштовують засідку скрадачі смерті.",al={"мер морісон","мер пайрвуду","хто керує пайрвудом"}},{q="Де відбувається засідка?",a="Засідка відбувається в ратуші Села Пайрвуд, на півдні Срібнолісся, трохи нижче дорогою від Фортеці Шадовфенг.",al={"місце засідки пайрвуд","де фаерлея","ратуша пайрвуду"}},{q="Що пов'язує Раду з Аруґалом?",a="Рада — адміністративний рупор Аруґала. Поки Аруґал сидить замкнений у Фортеці Шадовфенг і ставить свої темні досліди, рада керує селянами, що під покровом ночі обертаються на лютих звірів.",al={"зв'язок ради з аруґалом","чи рада працює на аруґала","аруґал керує пайрвудом"}},{q="Чи звільняє вбивство ради Пайрвуд від прокляття?",a="Ні. Знищення ради позбавляє Аруґала смертних маріонеток, але не знімає вовчого прокляття з селян, і Відступникам доводиться боротися за містечко, повне ворожих некерованих чудовиськ.",al={"чи пайрвуд позбавиться прокляття","чи засідка вилікує воргенів","прокляття знято"}}},fp="15,270,20.530.0,21.461.1,29.277.0,53.236.0,31.171.0,34.166.0,56.242.0,54.207.1"}
P.entries["quest:453"] = {n="Знайти таємничу постать",s="«Знайти таємничу постать» — завдання Альянсу, у якому шукачі пригод вистежують невловимого чужинця, пов'язаного з трагедією на фермі Свена Йорґена. Керуючись підказками Шинкаря Смітса з Даркшира, мандрівники прочісують проклятий ліс на заході в пошуках утікача.",h="«Знайти таємничу постать» — завдання Альянсу, у якому шукачі пригод вистежують невловимого чужинця...",kw={"знайти таємничу постать","тремтій","шинкар смітс","свен йорґен","щоденник","сутінколісся"},ang={["class:Rogue"]="Щоб вистежити наляканого підозрюваного в густому, оповитому тінню лісі, потрібні пильне око й уміння читати сліди, відрізняючи чутки від справжніх слідів.",["faction:Alliance"]="З'ясувати, чому втік Тремтій, — життєво важливо, щоб зрозуміти темряву, яка дедалі більше загрожує південному прикордонню королівства."},sec={{t="Слідом за примарою",b="Після прохання Свена Йорґена з'ясувати, хто та таємнича постать, що втекла з його сплюндрованого хутора, пошуки привели просто до Таверни «Багряний Крук». Шинкар Смітс поділився кількома важливими спостереженнями: утікач був у Даркширі зовсім чужим, надзвичайно знервованим і полохливим, а тоді поспіхом покинув кволі ліхтарі на околиці міста й зник у глушині на заході."},{t="Тремтій без маски",b="Слід чужинця на захід, у темряву, зрештою приводить до самого Тремтія, що тремтить від страху серед небезпек Сутінколісся. Коли йому показують щоденник із зруйнованої ферми, Тремтій падає в нервовому виснаженні й зізнається, що це він автор пошарпаних записів. Він зовсім не розважливий лиходій, а наляканий свідок, що втік від жахіть, які спіткали край, — і натякає, що щоденник уміщує лише уривок усього кошмару."}},faq={{q="Хто ця таємнича постать?",a="Таємнича постать — Джіттерс, полохливий мандрівник, що мимоволі записав моторошні події довкола ферми Свена Йорґена, перш ніж утекти на захід, у ліси.",al={"особа таємничої постаті","хто такий джіттерс","хто незнайомець"}},{q="Куди, за словами Шинкаря Смітса, пішла постать?",a="Смітс каже, що чоловік був чужинцем, мав помітно наляканий вигляд і втік на захід із Даркширу, попри небезпечну глушину.",al={"куди пішов","де джіттерс","яким шляхом на захід"}},{q="Чому Джіттерс утікав від ферми Свена?",a="Джіттерс бачив, як на хутір обрушилися невимовні жахи, і втік, рятуючи життя, нажаханий тим, що те, що знищило родину Свена, прийде й по нього.",al={"чому джіттерс втікав","що сталося на фермі свена","чому джіттерс боїться"}},{q="Що за книжку знайдено на фермі Свена?",a="Це щоденник, який написав Джіттерс; у ньому описано зловісні події перед різаниною на хуторі. Коли йому показують щоденник, Джіттерс визнає, що там лише половина історії.",al={"книга з ферми свена","щоденник джіттерса","що за щоденник"}},{q="Де знайти Джіттерса?",a="Джіттерс ховається в західній глушині Сутінколісся, біля табору на Воронячому Пагорбі, подалі від Даркширу й лісових хижаків.",al={"місце джіттерса","де джіттерс у сутінколіссі","координати джіттерса"}},{q="Що буде, коли Джіттерса знайдено?",a="Зізнавшись, що щоденник писав він, Джіттерс готує повну розповідь про те, що сталося насправді, і відсилає вас із правдою назад до Свена Йорґена.",al={"що далі","після знаходження джіттерса","куди далі"}}},fp="26,291,23.400.0,17.476.1,26.167.1,49.142.0,41.154.1,38.173.1,27.152.1,35.154.1"}
P.entries["quest:454"] = {n="Після засідки",s="Коли напад Темного Заліза зірвав доставку вибухового пороху на південні розкопки Лох Модану, Гулдар ділить обов'язки зі своїм напарником Міраном. Міран не хоче знову ризикувати потрапити в засідку сам, тож йому потрібен надійний супровід, щоб безпечно довезти решту припасів до розкопок.",h="Коли напад Темного Заліза зірвав доставку вибухового пороху на південні розкопки Лох Модану, Гулдар ділить...",kw={"після засідки","гулдар","міран","саен","темне залізо","вибуховий порох","супровід"},ang={["faction:Alliance"]="Відкриті шляхи постачання в Лох Модані — запорука того, що дослідження Ліги триватимуть, а південні перевали лишаться під владою Альянсу.",["profession:Mining"]="Вибуховий порох — живильна кров глибоких підземних розкопок, тож захист цих бочок вкрай важливий для будь-якої серйозної гірничої справи.",["race:Dwarf"]="Захищаючи постачання Айронфорджа від підступних диверсантів Темного Заліза, ви прямо бережете гірські перевали й копальні своєї батьківщини."},sec={{t="Розірваний ланцюжок постачання",b="Возити вибуховий гірничий порох пагорбами Лох Модану ніколи не було просто, але відкрита ворожнеча дворфів Темного Заліза перетворила буденну працю на смертельно небезпечну справу. Після засідки, яку очолив Саен зі спільниками, звичний лад візників Гулдара й Мірана розлетівся на друзки. Бочки розкидані, дорога небезпечна, тож напарники мусять розділитися: Гулдар стереже те, що лишилося, а Міран готується рушати далі з наступним вантажем."},{t="Шлях до розкопок",b="Розкопки по всьому Лох Модану залежать від постійних поставок вибухового пороху, щоб ламати камінь і видобувати реліквії титанів. Міран добре знає, що нова засідка може вигулькнути з-за будь-якого кряжу при дорозі. Знайшовши супутника, перш ніж прив'язувати вантаж, візник сподівається обминути пастки, які Темне Залізо ще тримає в запасі."}},faq={{q="Хто такі Гулдар і Міран?",a="Гулдар і Міран — дворфи-візники, яким доручено перевозити важкі барила вибухового порошку через Лох Модан для місцевих розкопок.",al={"хто такий гулдар","хто такий міран","носії порошку лох модан"}},{q="Чому Гулдар і Міран не можуть їхати разом?",a="Після засідки на шляху вантаж лишився вразливим. Вони розділили обов'язки: Гулдар лишається стерегти решту барил, а Міран рушає вперед із першою партією.",al={"чому розділилися","чому ділять порошок"}},{q="Хто напав на вантаж?",a="Візників підстерегла група ворожих дворфів Темного Заліза на чолі із Саеном, що хотіли зірвати роботу Альянсу й захопити чи знищити гірничу вибухівку.",al={"хто напав на вантаж","хто такий саен"}},{q="Куди Міран везе порошок?",a="Міран везе барила на південні розкопки в Лох Модані, де загону Шукача Айронбенда потрібен вибуховий порошок, щоб розчищати скелі й відкопувати поховані руїни.",al={"куди порошок","призначення міран"}},{q="Чому вибуховий порошок у Лох Модані так пильно стережуть?",a="Вибуховий порошок украй важливий для розкопок Ліги Дослідників, але в чужих руках він становить величезну небезпеку. Лазутчики Темного Заліза, що діють по всьому краю, прагнуть зірвати постачання й похитнути владу Айронфорджа над цими землями.",al={"чому охороняють порошок","важливість вибухового порошку"}},{q="Що буде після розмови з Міраном?",a="Щойно Міран востаннє перевірить віз і вантаж, він просить вас супроводити його дорогою, щоб вантаж дістався розкопок цілим.",al={"наступний крок після засідки","що робить міран"}}},fp="16,289,23.478.0,19.361.0,25.143.0,43.214.0,26.159.0,33.173.0,56.254.0,36.164.0"}
P.entries["quest:4542"] = {n="Послання до Застави Вільного Вітру",s="«Послання до Застави Вільного Вітру» — завдання Орди: віднести нагальні донесення від Сміливця Мунгорна, що стоїть біля прикордонних підйомників, униз, до Тисячі Голок. Лист попереджає Скельного Вартового Лонггорна про дедалі запекліші набіги кентаврів на місцеві каравани. А ще в ньому — перші тривоги щодо підозрілої, відлюдної поведінки сусіднього клану Ґрімтотем.",h="«Послання до Застави Вільного Вітру» — завдання Орди: віднести нагальні донесення від Сміливця Мунгорна, що...",kw={"послання до застави вільного вітру","сміливець мунгорн","скельний вартовий лонггорн","кентаври","ґрімтотем","тисяча голок"},ang={["faction:Horde"]="Застава Вільного Вітру — життєво важлива опора Орди на просторах Тисячі Голок. Підтримувати зв'язок між дозорцями застав і проводом поселення конче потрібно, щоб убезпечити пустельні торгові шляхи.",["race:Tauren"]="Для тауренів кентаври — давні, запеклі вороги ще з часів предків. Застереження Мунгорна — похмуре нагадування, що давні вороги досі полюють на стежках Калімдору, тоді як напруга з відлюдним кланом Ґрімтотем дедалі зростає."},sec={{t="Попередження вниз каньйоном",b="Стоячи на варті біля західних підступів до каньйону, Сміливець Мунгорн пильнує дороги, що спускаються в Тисячу Голок. Коли агресія кентаврів раптом різко зросла, зв'язок між прикордонними вартовими й місцевим проводом став життєво важливим. Мунгорн доручає мандрівним шукачам пригод з Орди віднести нагальне донесення на південний схід — Скельному Вартовому Лонггорну, командирові на столовій горі Застави Вільного Вітру."},{t="Нові небезпеки й неспокійні родичі",b="Отримавши послання, Лонггорн підтверджує, що становище тяжке: нещодавно розбійники-кентаври перехопили й вирізали караван із припасами, і тепер Застава Вільного Вітру конче потребує і відплати, і оборони. Не менше непокоїть і Мунгорнове застереження уникати місцевих тауренів-Ґрімтотемів, чия незвично дивна й ворожа поведінка натякає на глибші розколи, що назрівають на посушливих рівнинах."}},faq={{q="Хто надсилає послання до Застави Вільного Вітру?",a="Термінове послання дає вам Сміливець Мунгорн — тауренський розвідник, що стереже західний вхід до Тисячі Голок.",al={"хто дає завдання","хто дає послання до застави вільного вітру","сміливець мунгорн"}},{q="Хто отримує термінове послання?",a="Послання отримує Скельний Вартовий Лонггорн на вершині високої столової гори, де стоїть Застава Вільного Вітру, на південний схід від Великого Підйомника.",al={"куди здати","місце кліфвочера лонггорна","лідер застави вільного вітру"}},{q="Про що йдеться в терміновому посланні?",a="Послання попереджає Заставу Вільного Вітру про раптове почастішання нападів кентаврів і наскоків на каравани на стежках унизу.",al={"вміст послання","про що послання"}},{q="Чому Сміливця Мунгорна непокоять Ґрімтотеми?",a="Мунгорн зауважує, що сусіди з клану Ґрімтотем поводяться дивно й відчужено з іншими тауренами, тож радить мандрівникам триматися від них подалі.",al={"застереження про ґрімтотемів","чому уникати ґрімтотемів"}},{q="Що буде, коли Лонггорн прочитає послання?",a="Розлючений різаниною нещодавнього каравану з припасами, Скельний Вартовий Лонггорн одразу наказує завдати удару у відповідь місцевим кентаврам — у наступному завданні «Утихомирити кентаврів».",al={"наступне завдання","після послання до застави вільного вітру"}},{q="Як дістатися з дна каньйону до Застави Вільного Вітру?",a="Ідіть головною дорогою каньйоном на схід до підніжжя величезної гори-голки, а тоді підніміться дерев'яним підйомником просто в селище.",al={"як дістатися застави вільного вітру","як піднятися до застави"}}},fp="24,367,25.430.0,28.406.0,39.133.0,32.131.0,36.119.0,50.154.0,46.184.0,53.150.0"}
P.entries["quest:455"] = {n="Прорив крізь Алґаз",s="«Прорив крізь Алґаз» — нагальне військове доручення пробитися крізь Дун Алґаз, важливий гірський перевал між Лох Моданом і Багнокраєм. Орки клану Драконячої Пащі окопалися в тунелях і загрожують перерізати життєву артерію, що з'єднує Айронфордж із Гаванню Менетіл. Шукачам пригод доручено знищити орківський авангард і донести звістку про вторгнення Валстаґові Айронджо.",h="«Прорив крізь Алґаз» — нагальне військове доручення пробитися крізь Дун Алґаз, важливий гірський перевал між...",kw={"прорив крізь алґаз","дун алґаз","драконяча паща","орки","горянин рокґар","гавань менетіл","багнокрай"},ang={["faction:Alliance"]="Гавань Менетіл — головні ворота Альянсу між Східними Королівствами й західними землями; тримати суходільний шлях вільним вкрай важливо для всієї фракції.",["race:Dwarf"]="Очистивши Дун Алґаз, ви захищаєте прадідівські гірські перевали Каз Модану й зберігаєте важливий шлях між Айронфорджем і його західною морською гаванню."},sec={{t="Перерізана артерія",b="Дун Алґаз — єдиний суходільний гірський перевал, що прорізає скелі між Лох Моданом і болотистою улоговиною Багнокраю. Для дворфів Айронфорджа цей кам'яний коридор вкрай важливий для торгівлі, пересування військ і припасів до Гавані Менетіл — головного прибережного порту Альянсу в цьому краї. Якщо перевал упаде, зв'язок Айронфорджа із західними морями буде задушено, а відрізані застави лишаться без дворфійського підкріплення."},{t="Натиск Драконячої Пащі",b="Рештки клану Драконячої Пащі ще від Другої війни тиняються пагорбами й руїнами Багнокраю, але їхній раптовий, злагоджений наступ на Дун Алґаз — це вже рішуче загострення. Замість того щоб сидіти у своїх болотяних схованках, розвідники й вояки Драконячої Пащі захопили тунелі й укріпили перевал. Горянин Рокґар кличе сміливих мандрівників з Альянсу прорвати цю облогу: вбити орків, що наступають, і донести звістку про напад просто до Валстаґа Айронджо в Гавані Менетіл."}},faq={{q="Чому Дун Алґаз такий важливий для Альянсу?",a="Дун Алґаз — єдиний прямий гірський шлях, що з'єднує Лох Модан із Багнокраєм. Він пов'язує серце Каз Модану з Гаванню Менетіл — головним портом Альянсу для морських перевезень.",al={"чому дун алґаз важливий","важливість дун алґаза","чому зачищати перевал"}},{q="Хто такі орки Драконячої Пащі, що захопили перевал?",a="Клан Драконячої Пащі — рештки Старої Орди, що під час Другої війни сумнозвісно поневолили червоних драконів. Після поразки розпорошені загони відступили в Багнокрай, а тепер просунулися на південь, у перевал, щоб захопити стратегічні вузькі місця.",al={"хто такі драконяча паща","чому орки в дун алґазі","лор драконячої пащі"}},{q="Куди веде це доручення?",a="Пробившись крізь перевал і знищивши бійців і розвідників, що його тримають, ви йдете дорогою на північ через Багнокрай і на розвилці звертаєте на захід, до Гавані Менетіл, де доповідаєте Валстаґові Айронджо.",al={"куди йти після прориву крізь алґаз","хто бере звіт","де валстаґ айронджо"}},{q="Чому Валстаґа Айронджо дивує доповідь?",a="Драконяча Паща зазвичай тримається прихованих таборів на болотистих пагорбах Багнокраю. Їхній зухвалий наступ у дворфійські тунелі Дун Алґазу — несподіваний і тривожний перехід до організованої агресії.",al={"реакція валстаґа","чому орки напали на алґаз"}},{q="Хто наказує штурмувати перевал?",a="Удар наказує завдати Горянин Рокґар — дворфійський вартовий на північному кордоні Лох Модану, — щоб не дати оркам закріпитися й відрізати зв'язок з узбережжям.",al={"хто дає завдання","місія горянина рокґара"}},{q="Що далі після цього прориву?",a="Доповідь Валстаґові Айронджо попереджає гарнізон Гавані Менетіл про безпосередню загрозу й відкриває нові нагоди допомогти дворфам у боротьбі з Драконячою Пащею в Багнокраї.",al={"наступне завдання після прориву","що робити в менетілі"}}},fp="18,392,16.475.0,19.509.0,46.206.0,46.258.0,29.208.0,47.209.0,35.200.0,42.200.0"}
P.entries["quest:456"] = {n="Рівновага природи",s="«Рівновага природи» — вступне завдання для щойно пробуджених нічних ельфів у Тінедолі. Консерватор Ілталайн доручає юним шукачам пригод прорідити надмірно розплоджених молодих нічних шаблезубів і будякових вепрів. Завдання знайомить нових героїв із давнім обов'язком калдорей — опікуватися природною злагодою Тельдрассила й берегти її.",h="«Рівновага природи» — вступне завдання для щойно пробуджених нічних ельфів у Тінедолі.",kw={"рівновага природи","консерватор ілталайн","нічні шаблезуби","будякові вепри","тінедол","тельдрассил"},ang={["class:Druid"]="Для майбутніх друїдів це проріджування — прямий урок суворої правди опіки Кола Кенарія: щоб уберегти дику природу, іноді доводиться проливати кров заради цілого.",["class:Hunter"]="Уміння вистежувати й проріджувати агресивну живність — підмурок єднання кожного мисливця зі звірами Калімдору.",["race:NightElf"]="Це завдання — перший крок вашого шляху як дорослого захисника калдорей: ви засвоюєте, що рівновага природи вимагає діяльного втручання й поваги."},sec={{t="Тендітна злагода",b="Тельдрассил може здаватися диким і древнім, але його екосистеми молоді й крихкі. У Тінедолі, захищеному розлогим гіллям Великого Дерева, рясні весняні дощі порушили тонкий лісовий цикл. Деякі види розплодилися понад те, що здатна прогодувати земля, і загрожують оголити долину й ввергнути всю екосистему в голод. Щоб уберегти ліс, потрібна діяльна опіка."},{t="Поклик Консерватора",b="Консерватор Ілталайн наглядає за лісами Тінедола, дбаючи, щоб жодна ланка не взяла гору над іншою. Щоб відвернути масовий голод серед звірів, він посилає юних нічних ельфів у гай проріджувати будякових вепрів і хижих нічних шаблезубів. Це непоказний, але життєво важливий обов'язок, що закладає основу філософії калдорей: злагода з природою вимагає діяльної рівноваги й непростих рішень."}},faq={{q="Навіщо вбивати нічних шаблезубів і кабанів?",a="Рясні весняні дощі спричинили вибух чисельності молодих нічних шаблезубів і будякових кабанів. Тінедол здатен прогодувати лише обмежену кількість звірів, і розрослі стада можуть оголити гай, прирікши на голод і себе, й інших істот.",al={"чому вбивати кабанів","чому вбивати шаблезубів","причина рівноваги природи"}},{q="Хто такий Консерватор Ілталайн?",a="Консерватор Ілталайн — калдорейський охоронець Тінедолу. Його священний обов'язок — стежити за звірами й рослинами гаю, щоб не порушувалася природна злагода.",al={"хто такий ілталайн","хто дає завдання","консерватор ілталайн лор"}},{q="Де відбувається це завдання?",a="Завдання відбувається в Тінедолі — відлюдному лісовому куточку серед гілля Тельдрассилу, Світового Дерева біля узбережжя північного Калімдору.",al={"місце завдання","де тіньовий яр","стартова зона нічних ельфів"}},{q="Що далі після цього доручення?",a="Ілталайн дає вам другу частину проріджування, а також вручає знак вашого класу, що скеровує до першого наставника в Алдрассилі.",al={"завдання далі","наступне завдання в ланцюжку"}}},fp="21,366,18.438.0,22.425.0,51.232.0,30.178.0,33.157.0,43.162.0"}
P.entries["quest:457"] = {n="Рівновага природи",s="Це завдання продовжує зусилля Консерватора Ілталайна зберегти крихку екологію Тінедола: тепер треба прорідити дорослих будякових вепрів і шолудивих нічних шаблезубів. Поки живність Тельдрассила плодиться без упину, захисники нічних ельфів мають утрутитися, щоб надмір хижаків і травоїдів не оголив гілля.",h="Це завдання продовжує зусилля Консерватора Ілталайна зберегти крихку екологію Тінедола: тепер треба прорідити...",kw={"рівновага природи","консерватор ілталайн","нічні шаблезуби","будякові вепри","тінедол","алдрассил"},ang={["class:Druid"]="Друїдське вчення ставить злагоду вище сентиментів: проріджування розрослих зграй береже велике плетиво життя.",["class:Hunter"]="Полювання на прудких шаблезубів і впертих вепрів учить вистежувати й проріджувати — навичок, без яких природу не втримати в межах.",["race:NightElf"]="Для юних нічних ельфів це завдання — найперший урок суворої правди про опіку над дикою природою Тельдрассила."},sec={{t="Тягар опіки",b="Проріджування молодняку стабілізує майбутній ріст, але й дорослі популяції Тінедола становлять безпосередню загрозу для екосистеми Світового Дерева. Консерватор Ілталайн посилає юних захисників глибше в ліс — полювати на дорослих будякових вепрів і старих шолудивих нічних шаблезубів, перш ніж їхній ненаситний апетит вичерпає скінченні запаси рослин і дичини."},{t="Хижак і здобич",b="На північ від Алдрассила ліс змінюється: молодих дитинчат заступають плямисті нічні шаблезуби й агресивні вепри, що риють землю. Хоч убивати диких створінь — похмурий обов'язок, учення калдорей розглядає кероване полювання як неодмінну відповідальність, що береже весь ліс від екологічного краху."}},faq={{q="Чому Консерватор Ілталайн велить проріджувати цих звірів?",a="Без втручання дедалі численніші будякові кабани й нічні шаблезуби позбавили б Тінедол життєво важливих ресурсів, і земля стала б безплідною, нездатною підтримувати життя на гіллі Тельдрассилу.",al={"чому вбивати кабанів і шаблезубів","навіщо рівновага природи","причина полювання"}},{q="Де водяться облізлі нічні шаблезуби й будякові кабани?",a="Вони блукають у північній половині Тінедолу, за гіллям Алдрассила. Шукайте нічних шаблезубів із плямистою шерстю, а не смугастих молодих кошенят, що трапляються ближче до святилища.",al={"де облізлі шаблезуби","місце будякових кабанів","де їх знайти"}},{q="Хто такий Консерватор Ілталайн?",a="Консерватор Ілталайн — доглядач Тінедолу, що пильнує здоров'я першої галявини Тельдрассилу й навчає щойно пробуджених нічних ельфів берегти рівновагу лісу.",al={"хто такий ілталайн","консерватор ілталайн лор"}},{q="Як це узгоджується з віруваннями нічних ельфів про природу?",a="Нічні ельфи шанують природу, але дбайливе господарювання вимагає стримувати надмірне розростання. Якщо дати одному видові розплодитися й заморити голодом інших, це зашкодить усьому лісу, тож проріджування — сумний, але життєво важливий обов'язок.",al={"вірування нічних ельфів про природу","чому друїди вбивають звірів","баланс калдорей"}},{q="Чи це кінець ланцюжка «Рівновага природи»?",a="Це другий і останній крок початкового ланцюжка «Рівновага природи», хоча невдовзі з'являються інші доручення, пов'язані з глибшою, неприроднішою скверною, що непокоїть звірів Тельдрассилу.",al={"чи рівновага природи продовжується","що після рівноваги природи"}},{q="Чому нічних шаблезубів називають облізлими?",a="Це старші, грубіші хижаки, що блукають околицями галявини; через їхню велику кількість Тінедолові ледве вистачає їжі, тож багато з них обшарпані й агресивні.",al={"чому облізлі","що не так із шаблезубами"}}},fp="21,315,23.352.0,17.307.0,57.207.0,58.197.0,30.197.0,54.205.0,47.185.0,43.168.0"}
P.entries["quest:458"] = {n="Захисниця лісу",s="«Захисниця лісу» — вступне завдання в Тінедолі від друїда Мелітара Стаґгелма. Стривожений шепотом лісових духів, Мелітар просить вас розшукати Тариндреллу — невловиму дріаду, яка несподівано повернулася до гаю. Її поява натякає, що під кроною Тельдрассила ворушиться щось тривожне.",h="«Захисниця лісу» — вступне завдання в Тінедолі від друїда Мелітара Стаґгелма.",kw={"захисниця лісу","тариндрелла","дріада","мелітар стаґгелм","тінедол","алдрассил"},ang={["class:Druid"]="Друїди глибоко шанують дріад як рідню в природі; відгукнутися на появу Тариндрелли — ранній поклик зважати на рівновагу Смарагдового Сну й лісів.",["race:NightElf"]="Для юних нічних ельфів, що виходять з Алдрассила, зустріч з однією з доньок Кенарія стає першим безпосереднім обов'язком у збереженні злагоди їхнього молодого Світового Дерева."},sec={{t="Шепіт у долині",b="Навчаючи новачків під гіллям Алдрассила, Мелітар Стаґгелм одержує тривожні знамення від лісових духів. Дріада Тариндрелла, яку шанують як захисницю дикої природи, знову з'явилася в Тінедолі після багатьох років відсутності в лісах Калімдору. Дріади рідко виходять без причини, тож Мелітар побоюється, що природний лад порушено."},{t="У пошуках дріади",b="Керуючись звітом розвідки Вартових, щойно пробуджені захисники вирушають на південний захід від Алдрассила, у довколишні ліси. Зустріч із Тариндреллою підтверджує чуття Мелітара: донька Кенарія справді повернулася, щоб дати раду скверні, яка підступає до кургану й сусідніх галявин."}},faq={{q="Хто дає це завдання?",a="Це завдання щойно пробудженим шукачам пригод дає Мелітар Стаґгелм — нічний ельф-друїд на нижніх помостах Алдрассила в Тінедолі.",al={"хто дає завдання","завдання мелітара"}},{q="Де знайти Тариндреллу?",a="Тариндрелла — у лісі на південний захід від Алдрассила, біля лісових стежок Тінедолу.",al={"місце тариндрелли","де тариндрелла","знайти дріаду"}},{q="Хто така Тариндрелла?",a="Тариндрелла — дріада, одна з безсмертних доньок Кенарія. Дріад шанують як захисниць лісу; вони глибоко пов'язані з його здоров'ям і рідко втручаються безпосередньо, якщо природі не загрожує серйозна небезпека.",al={"хто така тариндрелла","лор тариндрелли","дріада тіньового яру"}},{q="Чому Мелітара непокоїть її повернення?",a="Присутності Тариндрелли не відчували в лісах Калімдору вже багато років. Її раптова поява в щойно вирощеному гіллі Тельдрассилу свідчить, що в гаю щось негаразд.",al={"чому мелітар хвилюється","турбота мелітара стаґгелма"}},{q="Що буде, коли Тариндреллу знайдено?",a="Розмова з Тариндреллою завершує доручення й одразу веде до її прохання про допомогу: вона просить вас розслідувати, що спотворює рослини й звірів Тінедолу.",al={"наступне завдання","що далі","продовження тариндрелли"}},{q="Чи родич Мелітар Стаґгелм Архідруїдові Фандралу Стаґгелму?",a="Мелітар має спільне прізвище з Архідруїдом Фандралом Стаґгелмом, провідником друїдів нічних ельфів у Дарнасусі, хоча про родинний зв'язок між ними нічого не відомо; Мелітар зосереджений на тому, щоб наставляти новачків у Тінедолі.",al={"чи мелітар родич фандрала","чи мелітар родич стаґгелма"}}},fp="22,332,20.372.0,17.314.1,22.148.0,29.106.0,19.222.0,43.198.0,39.182.0,59.238.0"}
P.entries["quest:4581"] = {n="Кейнет Стіллвінд",s="Це завдання посилає гінця Альянсу з Астранаару на схід, до прадавньої застави Лісова Пісня. З донесенням розвідки від Вартової Шіндрелл Свіфтфайр мандрівники шукають друїда Кейнета Стіллвінда, щоб допомогти йому стежити за поширенням порчі в прадавніх лісах.",h="Це завдання посилає гінця Альянсу з Астранаару на схід, до прадавньої застави Лісова Пісня.",kw={"кейнет стіллвінд","лісова пісня","шіндрелл свіфтфайр","донесення","ліс нічної пісні","завдання"},ang={["class:Druid"]="Для друїдів допомога Кейнетові Стіллвінду — основоположне покликання, що безпосередньо підтримує невпинну боротьбу Кола Кенарія за зцілення Ашенвалю від демонічної та стихійної порчі.",["faction:Alliance"]="Шлях із центрального Ашенвалю до східного Лісу Нічної Пісні вкрай важливий, щоб налагодити надійний зв'язок і оборону і від загроз глушини, і від посягань Орди.",["race:NightElf"]="Вартові й мандрівники-калдореї мають спільний обов'язок — тримати відкритими шляхи зв'язку між головними оплотами на кшталт Астранаару й далекими заставами, як-от Лісова Пісня."},sec={{t="Донесення на схід",b="У містечку Астранаар Вартова Шіндрелл Свіфтфайр пильнує західну половину лісу. До неї доходить звістка від друїда Кейнета Стіллвінда, що служить далеко в Лісовій Пісні, на східних околицях Ашенвалю. Глибоко стривожений змінами в поведінці звірів і темними знаменнями на узбережжях і в лісах, Кейнет попросив офіційно оцінити безпеку краю. Свіфтфайр записує свої спостереження в запечатану записку й довіряє її вправному мандрівникові, щоб той безпечно доніс донесення крізь підступний центральний ліс."},{t="Вартові Лісової Пісні",b="Щоб дістатися Лісової Пісні, доведеться здолати глушину Лісу Нічної Пісні, якому загрожують сатири, що наступають, ворожі звірі й вилазки Орди з півдня. У святилищі Лісової Пісні Кейнет Стіллвінд вивчає тендітну рівновагу природних духів Ашенвалю. Розвідка Свіфтфайр підтверджує його похмурі підозри: згубний вплив, що підкрадається лісом, не випадковий і не минущий, і друїдам знадобиться ще допомога, щоб протистояти злу, яке пускає коріння."}},faq={{q="Де знайти Кейнета Стіллвінда?",a="Кейнет Стіллвінд — у Лісовій Пісні, тихому святилищі нічних ельфів у Лісі Нічної Пісні на далекому сході Ашенвалю, на північ від головної дороги.",al={"де кейнет стіллвінд","місце кейнета стіллвінда","знайти кейнета стіллвінда"}},{q="Хто дає це завдання?",a="Завдання дає вартова Шіндрелл Свіфтфайр, що служить у поселенні нічних ельфів Астранаар на заході Ашенвалю.",al={"хто дає завдання","хто починає кейнета стіллвінда","де почати"}},{q="Що в Записці Шіндрелл?",a="У записці — докладне донесення про події на західному узбережжі Ашенвалю й у лісах довкола Астранаару, написане, щоб допомогти Кейнетові Стіллвінду розслідувати неприродну скверну в лісі.",al={"вміст записки шіндрелл","що написала шіндрелл","записка шіндрелл"}},{q="Чому Кейнет Стіллвінд досліджує ліс?",a="Як друїд, Кейнет прагне берегти природну рівновагу. Він боїться, що Ашенвалем шириться темне, всепроникне зло, і йому потрібні польові донесення вартових, щоб простежити, де воно пускає коріння.",al={"чому кейнет досліджує ліс","мотив кейнета стіллвінда","скверна друїдів"}},{q="Чи безпечна Лісова Пісня для мандрівників Альянсу?",a="Сама Лісова Пісня — мирний притулок Альянсу з привітними вартовими й друїдами. Але довколишній Ліс Нічної Пісні повен ворожих звірів і зіпсованих сатирів, тож дорога туди небезпечна.",al={"чи лісова пісня безпечна","місто альянсу лісова пісня","охорона лісової пісні"}},{q="Що буде, коли доставити записку?",a="Переглянувши донесення Шіндрелл, Кейнет Стіллвінд з'ясовує природу скверни в лісі й залучає мандрівників до рішучих дій проти зіпсованих сил, що загрожують краю.",al={"що далі","наступне завдання","продовження кейнета"}}},fp="17,280,22.550.0,23.508.0,35.173.0,21.133.0,28.218.0,50.204.0,43.217.0,39.207.0"}
P.entries["quest:459"] = {n="Захисниця лісу",s="Тариндрелла, дріада, що опікується Тінедолом, прагне з'ясувати, звідки взялися раптова агресія місцевих створінь і зникнення сусідніх фурболґів. Розслідуючи поведінку диких ґреллів і збираючи зразки зіпсутого Моху Скверни, шукачі пригод підтверджують: у корінні Світового Дерева почала гноїтися темна магія.",h="Тариндрелла, дріада, що опікується Тінедолом, прагне з'ясувати, звідки взялися раптова агресія місцевих...",kw={"захисниця лісу","тариндрелла","мох скверни","ґрелли","вузлошкіри","тінедол","доланаар"},ang={["class:Druid"]="Друїдів пов'язують священні узи з духами й дріадами лісу; дослідити заражений Мох Скверни конче потрібно, щоб розпізнати духовну хворобу, яка вразила Світове Дерево.",["race:NightElf"]="Для юних калдорей, що вирушають з Алдрассила, це завдання — раннє й тривожне усвідомлення, що їхня священна нова домівка вразлива до зіпсуття зсередини."},sec={{t="Пошесть на галявині",b="Навіть у відлюдних висотах Тінедола спокійна природа Тельдрассила почала тріскатися. Дріади, як-от Тариндрелла, помітили темний злам, що прокотився лісами. Колись сумирні фурболґи покинули лігва предків і згуртувалися в агресивне плем'я Вузлошкірів, а здичавілі ґрелли та ґреллкіни заполонили лісові стежки."},{t="Заражений ріст",b="Тариндрелла підозрює, що ворожість лісу живить неприродне зіпсуття. Винищуючи зграї ґреллів і збираючи зразки Моху Скверни, ви здобуваєте незаперечний доказ темних чарів, що чіпляються за гілля Тельдрассила. Коли гірку правду підтверджено, Тариндрелла скеровує юних захисників до села Доланаар — на раду з друїдом Атрідасом Бермантлом."}},faq={{q="Хто така Тариндрелла?",a="Тариндрелла — дріада-вартова в глушині Тінедолу. Як донька Кенарія, вона присвятила себе захисту рослин і звірів гаю й попереджає захисників — нічних ельфів, коли скверна загрожує рівновазі.",al={"тариндрелла","хто дає завдання","дріада тіньового яру"}},{q="Що таке Мох Скверни?",a="Мох Скверни — зіпсована поросль, просякнута темною магією, що почала чіплятися до звірів Тінедолу. Він розлючує й спотворює таких істот, як грели, доводячи їх до неприродної агресії.",al={"мох скверни","що таке мох скверни","скверний мох"}},{q="Що сталося з фурболгами Тінедолу?",a="Фурболги, що колись мирно жили в гаю, покинули свої давні оселі. Зіпсовані підступною гниллю, що шириться Тельдрассилом, вони згуртувалися під стягом ворожого племені Вузлошкірів.",al={"таємниця фурболгів","плем'я вузлошкірів","куди зникли фурболги"}},{q="Куди веде це розслідування далі?",a="Переконавшись, що Мох Скверни пустив коріння в Тінедолі, Тариндрелла скеровує мандрівників углиб Тельдрассилу, до поселення Доланаар. Там друїд Атрідас Бермантл досліджує, як ця скверна шириться всім Світовим Деревом.",al={"наступне завдання","куди йти далі","атрідас ведмежа мантія"}},{q="Хто такі грели й грелята?",a="Грели та їхня рідня — пустотливі крихітні лісові духи, що живуть у гіллі Тельдрассилу. Зазвичай вони просто неслухняні шкідники, але під дією згубних впливів, як-от Моху Скверни, стають шалено агресивними.",al={"хто такі грели","грелкіни","що таке грели"}},{q="Звідки на Тельдрассилі скверна?",a="Хоча Тельдрассил виростили, щоб повернути нічним ельфам утрачене безсмертя й дати їм новий притулок, темні сили почали просочуватися в його гілля й звірів, непокоячи друїдів і лісових духів, що мають його берегти.",al={"чому скверна на тельдрассилі","скверна тіньового яру"}}},fp="22,329,21.359.0,14.372.0,19.237.0,17.205.0,44.231.0,40.255.0,29.210.0,40.231.0"}
P.entries["quest:46"] = {n="Винагорода за мурлоків",s="Армія Стормвінда оголосила публічну винагороду за племена мурлоків, що розповзаються східним Лісом Елвінн. Гарнізон розтягнутий до краю, тож Вартовий Томас покладається на мандрівних шукачів пригод: ті мають винищити прибережні табори довкола Озера Кам'яного Кургану та південних річок, поки мурлоки не заполонили ферми й дороги краю.",h="Армія Стормвінда оголосила публічну винагороду за племена мурлоків, що розповзаються східним Лісом Елвінн.",kw={"винагорода","мурлоки","вартовий томас","озеро кам'яного кургану","плавці","ліс елвінн"},ang={["class:Hunter"]="Багнисті береги й зарослі очеретом узбережжя Озера Кам'яного Кургану — ідеальне місце, щоб вправлятися у вистежуванні спритних водяних хижаків, які діють зграєю.",["faction:Alliance"]="Зачищені річки бережуть життєво важливі лінії постачання й сільські садиби між Ґолдширом і кордоном із Редріджем.",["race:Human"]="Для підданих Стормвінда цей контракт — суворе нагадування про те, якою тонкою стала оборона їхнього королівства просто біля серця столиці."},sec={{t="Загроза на річках",b="Західні дороги Лісу Елвінн порівняно безпечні, та у східних водах шириться земноводна навала. Мурлоки-причаєнці та мурлоки-збирачі заклали агресивні прибережні поселення довкола Озера Кам'яного Кургану й уздовж розвилки південних струмків. Те, що спершу здавалося дрібною прикрістю, швидко перетворилося на захоплення територій: озброєні мурлоки нападають на подорожніх і підступають до людських поселень."},{t="Розтягнута оборона",b="Вартовий Томас, що стоїть на східному мосту біля кордону з Горами Редріджу, опиняється між зовнішніми небезпеками й місцевим безладом. Король Варіан Рінн зник, військове командування Стормвінда загрузло в бюрократичному паралічі, тож міські гарнізони рідко отримують підкріплення, про які просять. Маршал Дуґан і місцеві офіцери вдалися до офіційних винагород — платять монетою за відрубані плавці, щоб стримати водяний приплив."}},faq={{q="Чому в Елвінні призначено винагороду за мурлоків?",a="Мурлоки облаштували дедалі більші табори на Озері Кам'яного Кургану й південних струмках на сході Елвінна. Їхні загони-збирачі загрожують сусіднім фермам, дорогам і подорожнім, тож військо Стормвінда платить шукачам пригод, щоб ті прорідили мурлоків.",al={"чому вбивати мурлоків","причина винагороди за мурлоків","навіщо винагорода"}},{q="Хто платить винагороду?",a="Винагороду фінансує військо Стормвінда через командування в Ґолдширі на чолі з Маршалом Дуґаном, а виплачує її мандрівникам Вартовий Томас, що стоїть біля переправи через східну річку.",al={"хто дає нагороду","хто платить винагороду","винагорода армії стормвінда"}},{q="Де мурлочі поселення?",a="Головні колонії розташовані на берегах і острівцях Озера Кам'яного Кургану на півночі, а також уздовж берегів річки на півдні, де розгалужується східний потік.",al={"місця мурлоків елвінн","де мурлоки","мурлоки озера кам'яного кургану"}},{q="Чому вартові Стормвінда не впораються самі?",a="Військо Стормвінда вкрай розпорошене по королівству через політичні чвари, відсутність провідника й розбій. На заставах, як-от міст Вартового Томаса, лише жменька людей, тож вони не можуть вести тривалий наступ на прибережні племена.",al={"чому томасу потрібна допомога","чому вартові не б'ються з мурлоками","нестача вартових елвінн"}},{q="Який доказ вимагає Вартовий Томас?",a="Вартовий Томас просить подерті мурлочі плавці, зняті просто з причаївців і збирачів, що живуть у східних водах Елвінна.",al={"що дропають мурлоки","доказ завдання","мурлочі плавці"}},{q="Чи знає Маршал Дуґан, наскільки серйозна проблема з мурлоками?",a="Так. Вартовий Томас зауважує, що Маршала Дуґана дуже тривожить становище з мурлоками на сході Елвінна, тож добрі звістки про розгромлені поселення вкрай важливі для духу місцевих.",al={"чи дуґан знає про мурлоків","чи ґолдшир знає","реакція дуґана"}}},fp="17,321,25.447.0,18.433.0,43.252.0,29.203.0,41.164.0,54.267.0,49.126.0,66.180.0"}
P.entries["quest:460"] = {n="Спочивай по шматках",s="Завдання «Спочивай по шматках» починається, коли шукач пригод знаходить ожилу відтяту голову Аларіка — колишнього слуги некроманта Тула Рейвенклова на Острові Фенріс. Аларік благає перенести його через Фортецю Фенріс до безіменної могили біля стаєнь, де поховано решту його останків.",h="Завдання «Спочивай по шматках» починається, коли шукач пригод знаходить ожилу відтяту голову Аларіка —...",kw={"спочивай по шматках","аларік","тул рейвенклов","фортеця фенріс","острів фенріс","гнилошкірі гноли"},ang={["class:Mage"]="Зіпсовані захисні чари Тула, що обернули оборонне відвернення на невідворотне прокляття розчленованого нежиття, — суворе застереження про те, що буває, коли чарівну магію викривлює некромантія.",["race:Undead"]="Поборники-Відступники впізнають у підступному чаклунстві Тула Рейвенклова приклад жорстоких жахіть, які чаклуни на боці Погибелі чинили по всьому Лордерону."},sec={{t="Зраджений охоронець",b="До своєї моторошної долі Аларік був головним слугою й особистим охоронцем Тула Рейвенклова — могутнього мага на боці Погибелі, що діяв із Фортеці Фенріс у Срібноліссі. Коли краєм прокотилася Чума Нежиття, Тул пообіцяв захистити Аларіка своїм чаклунством, щоб той не став її жертвою. Натомість викривлені захисні чари назавжди замкнули Аларіка в болісному стані нежиття, а його свідомість лишилася цілою в розрізнених частинах тіла."},{t="Іграшка гнилошкірих",b="Створивши гнилошкірих гнолів — заразивши місцеві зграї некромантським тлінням, — Тул обернувся проти власного охоронця. Некромант відтяв Аларікові голову й кинув її, досі живу й балакучу, диким гнолам на потіху. Гнилошкірі відтягли його тіло до поспіхом викопаної неглибокої могили біля стаєнь фортеці, а голову лишили собі як моторошну іграшку — доки не втрутився чужинець."},{t="Скласти шматки докупи",b="Біля поспіхом розкопаної землі коло стаєнь відтята голова Аларіка возз'єднується з безголовим тулубом. Хоч він досі прикутий до прокляття не-життя, яке сплів довкола нього Тул, повернені частини приносять Аларікові гірку дещицю полегшення."}},faq={{q="Хто такий Аларик?",a="Аларик був старшим слугою й особистим охоронцем Тула Рейвенклова у Фортеці Фенріс. Тул наклав на нього неприродне закляття — нібито щоб уберегти від Чуми нежиття, — але натомість прикував його до вічного нежиття.",al={"хто такий аларик","голова що говорить","говоряща голова срібнолісся"}},{q="Чому Аларикові відтяли голову?",a="Тул Рейвенклов відрубав Аларикові голову невдовзі після того, як завершив свої досліди зі створення гнилошкірих гнолів. Тоді некромант кинув відтяту, але свідому голову Аларика гнолам — на забавку.",al={"чому аларику відтяли голову","хто відтяв голову аларика"}},{q="Де могила Аларика?",a="Його тіло лежить у безіменній, поспіхом викопаній неглибокій могилі на Острові Фенріс, у дворі Фортеці Фенріс, неподалік стаєнь.",al={"де тіло аларика","місце неглибокої могили","де могила на фенрісі"}},{q="Хто такі гнилошкірі гноли?",a="Гнилошкірі гноли — місцеві гноли Острова Фенріс, яких некромантичні досліди Тула Рейвенклова перетворили на гниючі жахіття, уражені нежиттям.",al={"гнилошкірі","гнилошкірі гноли","гноли острова фенріс"}},{q="Хто такий Тул Рейвенклов?",a="Тул Рейвенклов — чарівник-людина й некромант Погибелі, що захопив Фортецю Фенріс посеред Озера Лордамер і зробив її лабораторією, де спотворював гнолів і поширював вплив Погибелі.",al={"тул","тул рейвенклов"}},{q="Що буде, коли знайти могилу?",a="Возз'єднавшись зі своїми рештками, Аларик допомагає вам знайти потаємну нішу з могутнім жезлом, який потім можна віднести даларанському магові Бетору Айсшарду в Андерсіті.",al={"що далі спочивай по шматках","продовження спочивай по шматках"}}},fp="17,285,20.472.0,26.428.0,20.243.1,14.229.0,24.194.0,32.138.0,29.171.0,23.196.0,38.185.1"}
P.entries["quest:461"] = {n="Потаємна ніша",s="Розкопавши балакучі останки Аларіка з неглибокої могили біля Фортеці Фенріс, шукачі пригод повертаються всередину твердині. Ведені спогадами покійного, мандрівники шукають забуту нішу, заховану за запорошеною полицею, щоб дати йому останній спочинок і забрати давню реліквію.",h="Розкопавши балакучі останки Аларіка з неглибокої могили біля Фортеці Фенріс, шукачі пригод повертаються...",kw={"потаємна ніша","аларік","фортеця фенріс","тул рейвенклов","острів фенріс","реліквія"},ang={["class:Mage"]="Потаємна ніша зберігає чарівну спадщину Фортеці Фенріс і ховає артефакти, прямо пов'язані з колишніми даларанськими чарівниками на кшталт Тула Рейвенклова.",["faction:Horde"]="Повертаючи реліквії з серця Фортеці Фенріс, ви підточуєте опору Тула на Острові Фенріс і допомагаєте походові Відступників за Срібнолісся.",["race:Undead"]="Для Відступників мати справу з неспокійними, балакучими останками — звична річ, але Аларікова туга за мирним спочинком серед людських руїн — суворе нагадування про землі, які вони успадкували."},sec={{t="Неспокійне прохання",b="Навіть після смерті Аларік яскраво пам'ятає Фортецю Фенріс у її кращі дні. Радий, що розвідники Орди викопали його з неглибокої, абияк викопаної могили, його кістяк не хоче, щоб його просто віднесли до Гробниці. Натомість він торгується важливими відомостями: у південно-західній вежі фортеці є потаємна ніша, де лежить річ, яку дуже цінували Тул Рейвенклов і його товариші-маги."},{t="Похований у стінах",b="Минаючи гнилошкірих гнолів, що заполонили острівну фортецю, мандрівники несуть останки Аларіка нагору кам'яними коридорами. За запорошеною книжковою полицею на верхніх поверхах ховається таємна схованка, про яку він казав. Коли її відчиняють, Аларік просить лише одного — замурувати його в давній кладці фортеці: він знаходить розраду в тому, щоб спочивати в стінах, де минули найщасливіші дні його життя, — подалі від гризучих щелеп гнолів."}},faq={{q="Хто такий Аларик?",a="Аларик був старшим слугою й охоронцем Тула Рейвенклова у Фортеці Фенріс; Тул відтяв йому голову після створення гнилошкірих гнолів. Його знаходять закопаним біля фортеці в неглибокій могилі, і його оживлений дух допомагає шукачам пригод Орди — в обмін на гідне місце спочинку в улюбленій твердині.",al={"лор аларика","хто такий аларик","чиї це кістки"}},{q="Де розташована потаємна ніша?",a="Потаємна ніша схована в південно-західній вежі Фортеці Фенріс, за непримітною запиленою книжковою шафою на горішньому поверсі.",al={"де пилова полиця","місце ніші","де схована ніша"}},{q="Що сховано в ніші?",a="У прихованій ніші лежить старий жезл, яким колись дорожили Тул Рейвенклов і його давні товариші з Даларану, а також інші пам'ятки, які Аларик лишає тим, хто йому допоміг.",al={"що в ніші","скарб фортеці фенріс","предмет тула"}},{q="Чому Аларик хоче лишитися у Фортеці Фенріс?",a="Аларик вважає час, прожитий у Фортеці Фенріс, найкращими днями свого життя. Замуровані в камені рештки дають йому спокій і захищають від гнолів-падальників, що никають подвір'ями.",al={"чому аларик лишається у фортеці фенріс","місце спочинку аларика"}},{q="Що буде, коли шафу знайдено?",a="Замурувавши Аларика в ніші й забравши жезл, шукачі пригод вирушають назад до Андерсіті, щоб віддати реліквію Беторові Айсшарду.",al={"завдання після потаємної ніші","що робити з паличкою"}},{q="Чому Аларик просить лишити його чоботи?",a="Коли його кістки викопували з неглибокої могили, Аларик жартома наполіг, щоб старі чоботи лишилися в землі: мовляв, вони йому все одно ніколи не пасували.",al={"чоботи аларика","залишити чоботи"}}},fp="16,303,18.412.0,19.443.1,14.318.0,34.140.0,34.179.0,48.220.0,37.148.1,50.167.0"}
P.entries["quest:463"] = {n="Зеленовартовий",s="«Зеленовартовий» — сполучне завдання Альянсу, що веде мандрівників глибше в болота Багнокраю. Посилає їх Перший Помічник Фіцсіммонс із Гавані Менетіл: шукачі пригод вирушають на північний схід, у трясовину, щоб розшукати загадкову істоту, яка, кажуть, живе серед звірів.",h="«Зеленовартовий» — сполучне завдання Альянсу, що веде мандрівників глибше в болота Багнокраю.",kw={"зеленовартовий","ретіель зеленовартовий","перший помічник фіцсіммонс","гавань менетіл","болота","багнокрай"},ang={["class:Druid"]="Звичайні докери вважають Ретіеля болотяною потворою, але друїди одразу впізнають прадавнього охоронця, співзвучного з рівновагою природи.",["race:NightElf"]="Нічні ельфи, що мандрують далеко від Калімдору, знаходять знайомий і втішний відгомін прадавніх охоронців природи навіть у вогкій, багнистій землі Каз Модану."},sec={{t="Чутки з шинку й болотяні байки",b="На пристанях Гавані Менетіл моряки й волоцюги, затамувавши подих, переказують історії про звіра, що причаївся на болоті. Перший Помічник Фіцсіммонс змальовує Зеленовартового як ненажерливу пащу на ногах і застерігає легковірних шукачів: ступиш із сухої дороги — і «старий Зелений» перекусить тебе навпіл. Для портового люду все величезне, що ховається в каламутних водах, — лише ще одна болотяна напасть, що жере людей."},{t="Охоронець боліт",b="Ті, хто наважиться піти за вказівками на схід від розвилки до Дун Модра, переконуються, що шинкові байки геть схибили. Зеленовартовий — зовсім не безмозкий хижак, а Ретіель, височенний прадавній захисник, пов'язаний із диким буянням боліт. Він не пожирає необачних мандрівників — натомість сумує через сплюндровану землю й кличе охочих смертних очистити заражені болота."}},faq={{q="Хто такий Зеленовартовий?",a="Зеленовартовий — це Ретіель, прадавній охоронець природи, що живе в Багнокраї. Моряки з узбережжя вважають його лютим чудовиськом, але насправді це мудрий захисник, що відчуває рослини й звірів.",al={"хто такий зеленовартовий","особа зеленовартового","хто такий ретіель"}},{q="Де знайти Зеленовартового?",a="Ретіель — на болотах на схід від головної дороги, біля розвилки, що веде до Дун Модра, на півночі Багнокраю.",al={"місце зеленовартового","де ретіель","координати зеленовартового"}},{q="Чому Перший Помічник Фіцсіммонс вважає Зеленовартового небезпечним?",a="Фіцсіммонс знає лише чутки й забобони з таверни Гавані Менетіл. Багнокрай кишить звірами, тож моряки вважають, що будь-яка велетенська істота серед крокодилів і хижаків — просто ще один людожер.",al={"чому фіцсіммонс боїться","чи зеленовартовий злий"}},{q="Чого Ретіель хоче від мандрівників?",a="Ретіель шукає звитяжців, що дбатимуть про Багнокрай, який, за його словами, плаче від гнійних ран. Він просить гостей захищати звірів і приборкувати загрози, що розхитують місцеву природу.",al={"чого хоче зеленовартовий","мета ретіеля","чому зустрітися з зеленовартовим"}},{q="Що буде, коли знайти Зеленовартового?",a="Поговоривши з вами, Ретіель визнає, що природа добре про вас відгукується, і дає завдання «Тупіт лап», щоб ви допомогли впоратися з бідами, що спіткали болота.",al={"наступне завдання після зеленовартового","завдання тупіт лап"}},{q="Чи треба в цьому завданні з кимось битися?",a="Ні. Треба лише пережити шлях через Багнокрай і поговорити з Ретіелем у його гаю серед боліт.",al={"бій зеленовартового","чи битися з зеленовартовим"}}},fp="15,275,27.411.0,25.395.1,23.200.0,33.129.0,67.232.0,38.197.0,43.166.0,54.131.0"}
P.entries["quest:464"] = {n="Бойові стяги",s="Капітан Стаутфіст у Гавані Менетіл доручає героям Альянсу вдарити по табору орків Драконячої Пащі на північний схід від містечка й захопити їхні бойові стяги. Рештки орків, розбиті й розпорошені після Другої війни, знову набираються сили на болотах Багнокраю.",h="Капітан Стаутфіст у Гавані Менетіл доручає героям Альянсу вдарити по табору орків Драконячої Пащі на...",kw={"бойові стяги","капітан стаутфіст","драконяча паща","нек'рош","ґрім батол","гавань менетіл"},ang={["class:Warrior"]="Прямий удар по бойовому табору випробовує вашу мужність у бою із загартованими ветеранами Другої війни, які б'ються з безрозсудною лютістю навіть без своїх драконів.",["faction:Alliance"]="Гавань Менетіл — життєво важлива артерія між Стормвіндом, Айронфорджем і північними королівствами; дозволити ворожому таборові орків окопатися поблизу — значить загрожувати всьому морському шляху.",["race:Dwarf"]="Драконяча Паща осквернила прадавню дворфійську твердиню Ґрім Батол і сплямила війною довколишні гори, тож кожен убитий воїн Драконячої Пащі — міра довго відкладеної справедливості."},sec={{t="Рештки Драконячої Пащі",b="Під час Другої війни клан Драконячої Пащі підкорив червоне драконяче плем'я з гірської фортеці Ґрім Батол. Коли їхня мерзенна влада зламалася, визволені дракони з лютою мстивістю обернулися проти поневолювачів і майже вигубили орків. Жменька вцілілих утекла з Ґрім Батола у високі гори на схід від Місця Розкопок Велґара, ховаючись від гніву червоних драконів."},{t="Табір, що росте",b="Хоча Драконячу Пащу давно вважали зламаною назавжди, вона знову дала про себе знати. На північний схід від Гавані Менетіл ці люті вцілілі звели діючий бойовий табір і встромили в болото свої багряні стяги. Розуміючи, як небезпечно мати войовниче військо орків так близько від портового містечка, Капітан Стаутфіст хоче прорідити їхні лави й зірвати їхні горді бойові стяги на знак поразки."},{t="Спадок Некроса",b="Коли стяги здобуто, Стаутфіст розкриває, що цих орків, які знову зібралися докупи, веде Нек'рош — син сумнозвісного чорнокнижника Некроса. Некрос темними чарами керував полоненими червоними драконами, доки та магія не впала, і колишні бранці розшматували його. Тепер його мстивий син очолює вцілілих, одержимий ворожнечею з велетенськими звірами, що вбили його батька."}},faq={{q="Хто такі орки Драконячої Пащі в Багнокраї?",a="Це рештки орківського клану, що під час Другої війни поневолив червоних драконів. Утративши владу над драконами, вони стали жертвами безжального полювання й розпорошилися, а вцілілі втекли з Ґрім Батолу й сховалися в горах і на болотах.",al={"орки драконячої пащі багнокрай","хто такі драконяча паща","орки багнокраю"}},{q="Навіщо Капітанові Стаутфісту їхні бойові стяги?",a="Стаутфіст вважає щойно укріплений табір на північний схід від Гавані Менетіл серйозною загрозою для міста. Він вимагає бойових стягів як речового доказу того, що вояки Альянсу вчинили набіг на табір і послабили бойову силу орків.",al={"навіщо збирати стяги","бойові стяги стаутфіста"}},{q="Що сталося з драконами клану Драконячої Пащі?",a="Коли темна магія, що тримала драконів у полоні, ослабла, червоні дракони обернулися проти своїх поневолювачів. Вони запекло полювали на Драконячу Пащу по всьому Каз Модану й майже винищили клан.",al={"що сталося з драконами","дракони драконячої пащі"}},{q="Хто тепер очолює клан Драконячої Пащі?",a="Їх очолює Нек'рош, син колишнього ватажка Драконячої Пащі Некроса. Нек'рош згуртував уцілілих і присягнувся помститися червоним драконам, що вбили його батька.",al={"лідер драконячої пащі","хто такий нек'рош"}},{q="Де Драконяча Паща ховалася, перш ніж розбити цей табір?",a="Утікши з Ґрім Батолу, уцілілі орки ховалися в скелястих горах на схід від Розкопок Велґара, а тоді спустилися на болота Багнокраю й звели свій табір.",al={"де ховалася драконяча паща","прихисток драконячої пащі"}},{q="Чи пов'язані ці орки Драконячої Пащі з Ордою Тралла?",a="Ні. Ці рештки Драконячої Пащі — незалежні ренегати, що живуть жагою помсти й виживання й діють цілком поза новою Ордою, яку заснував Вождь Тралл у Калімдорі.",al={"чи драконяча паща в орді","драконяча паща і тралл"}}},fp="11,292,25.388.0,19.393.0,20.404.1,43.247.0,50.237.0,46.196.0,33.172.1,57.173.0,56.174.0"}
P.entries["quest:465"] = {n="Гамбіт Нек'роша",s="«Гамбіт Нек'роша» — нагальна ударна місія, яку доручає Капітан Стаутфіст у Гавані Менетіл. Дізнавшись, що Вождь Нек'рош збудував облогові машини, щоб обстріляти беззахисне портове містечко, поки підкріплення відрізані в Дун Алґазі, Альянс посилає сміливих добровольців глибоко в болота, щоб спалити катапульти Драконячої Пащі, перш ніж почнеться штурм.",h="«Гамбіт Нек'роша» — нагальна ударна місія, яку доручає Капітан Стаутфіст у Гавані Менетіл.",kw={"гамбіт нек'роша","вождь нек'рош","катапульти","дворфський трут","капітан стаутфіст","гавань менетіл"},ang={["class:Warrior"]="Штурмувати укріплений ворожий бойовий табір, щоб знищити важку облогову артилерію, — справа для рішучої тактики передової лінії й жорстокого рукопашного бою.",["faction:Alliance"]="Поки Дун Алґаз скований боями, Альянсові доводиться покладатися на відважних добровольців, а не на регулярні війська, щоб зламати бойову машину Драконячої Пащі.",["race:Dwarf"]="Гавань Менетіл — брама дворфів-Бронзбірдів до західного моря; утратити її через облогові машини Драконячої Пащі означало б підрізати морські зв'язки Айронфорджа."},sec={{t="Неминуча облога",b="Поки шукачі пригод з Альянсу билися із загонами Драконячої Пащі, дворфійські розвідники розкрили справжній задум клану. Вождь Нек'рош наглядав за будівництвом справжніх облогових катапульт у болотяних таборах. Його мета зухвала й нищівна: підвести свої бойові машини до Гавані Менетіл, розтрощити мури фортеці й знищити головний морський вузол Альянсу на західному узбережжі."},{t="Відрізані в Дун Алґазі",b="Небезпеку для Гавані Менетіл посилює вузьке місце в Дун Алґазі. Запеклі сутички й активність зеленошкірих на гірському перевалі фактично відрізають низини від головних гарнізонів Айронфорджа. Без негайної допомоги з Каз Модану Капітан Стаутфіст не може виділити загін для оборони околиць, тож диверсія проти катапульт на випередження — єдиний шанс гавані вижити."},{t="Вогонь у таборі",b="Озброєні Дворфським Трутом, розвідники мають прорватися в саме серце табору Драконячої Пащі. Підпаливши громіздкі дерев'яні машини, вони позбавлять Нек'роша артилерії, лишать його воїнів без захисту й без вогневої сили, потрібної, щоб зламати оборону Менетіла, — ще до того, як дійде до двобою з самим воєначальником."}},faq={{q="Хто такий Нек'рош?",a="Нек'рош — безжальний вождь решток клану Драконячої Пащі в Багнокраї. Він готує справжню воєнну кампанію, щоб узяти в облогу Гавань Менетіл.",al={"нек'рош","вождь нек'рош","хто такий нек'рош"}},{q="Чому Гавань Менетіл у такій небезпеці?",a="Місто цілком залежить від морської торгівлі й відрізане від Айронфорджа. Оскільки на перевалах Дун Алґазу точаться бої, підкріплення суходолом прийти не може, і місто не витримає зосередженої облоги.",al={"небезпека менетілу","чому гавань вразлива","загроза менетілу"}},{q="Яка мета цього доручення?",a="Вам треба пронести Дворфський Трут у табір Драконячої Пащі, щоб підпалити й знищити облогові катапульти, перш ніж їх викотять проти Гавані Менетіл.",al={"мета гамбіту","що робити","місія катапульти"}},{q="Хто дає це доручення?",a="Наказ віддає Капітан Стаутфіст — дворфійський офіцер, що координує місцеву оборону гавані й кампанію проти Драконячої Пащі.",al={"хто дає завдання","хто дає гамбіт нек'роша","роль стаутфіста"}},{q="Що йде після знищення катапульт?",a="Коли облогові машини обернуться на попіл, загрозу треба загасити остаточно — вистежити й стратити самого Вождя Нек'роша.",al={"після катапульт","наступне завдання","що далі"}},{q="Чому Айронфордж не може надіслати війська на допомогу Менетілу?",a="Дорога з Лох Модану до Багнокраю пролягає через Дун Алґаз, за який точаться запеклі бої і де чатують засідки ворожих сил, тож надійного сполучення суходолом немає.",al={"перевал дун алґаз","чому немає підкріплення","допомога айронфорджа"}}},fp="17,367,15.415.0,20.398.0,22.310.0,16.169.0,38.240.0,33.170.0,27.139.0,46.147.1,49.160.0"}
P.entries["quest:467"] = {n="Пошуки Стоунґіра",s="Пошуки Стоунґіра — доручення Альянсу, яке скеровує відважних мандрівників до Пілота Стоунґіра на Складі Стілґрила в Дун Мороґу. Запальний водій облогової машини прочув про незвичайний мінерал і шукає сміливця, що роздобуде новий заряд для гармати його танка.",h="Пошуки Стоунґіра — доручення Альянсу, яке скеровує відважних мандрівників до Пілота Стоунґіра на Складі...",kw={"пілот стоунґір","склад стілґрила","танк","руда","дун мороґ","харанос"},ang={["profession:Engineering"]="Інженери, що днями майструють потужну вибухівку, оцінять, як віддано Стоунґір підсилює вогневу міць свого танка.",["profession:Mining"]="Шахтарів, які знаються на незвичайних і горючих породах, чутки Стоунґіра про рідкісну підземну руду зацікавлять одразу.",["race:Dwarf"]="Для дворфійських горян і механіків допомогти товаришеві-пілотові на Складі Стілґрила — гордий обов'язок, адже так удосконалюється арсенал Каз Модану.",["race:Gnome"]="Гномські винахідники легко зрозуміють прагнення Пілота Стоунґіра вивести звичну облогову зброю далеко за межі безпеки."},sec={{t="Задум механіка",b="Дворфійські облогові машини — легендарні витвори інженерії, але їхні водії рідко вміють дати спокій тому, що й так працює. По Айронфорджу й Лох Модану швидко ширяться чутки, що Пілот Стоунґір, який стоїть неподалік від столиці, замислив додати своїй бойовій машині вогню. Хай мандрівників посилає до нього Пілот Лонґбірд чи Горянин Кадрелл — їх просто просять зустрітися з амбітним пілотом і вислухати його пропозицію."},{t="До Складу Стілґрила",b="Пілот Стоунґір облаштував майстерню на Складі Стілґрила — випробувальному майданчику й зборному дворі біля дороги, трохи на схід від Хараноса. Серед брязкоту шестерень і клубів пари Стоунґір виглядає шукачів, досить відважних, щоб полювати на рідкісну вибухову руду, яка, кажуть, піднімає вогневу міць його танка до нових нищівних висот."}},faq={{q="Хто дає це завдання?",a="До Пілота Стоунґіра вас може скерувати або Пілот Лонґбірд в Айронфорджі, або Горянин Кадрелл на дорозі в Лох Модані.",al={"хто дає завдання","хто починає пошуки стоунґіра","де взяти завдання"}},{q="Де знайти Пілота Стоунґіра?",a="Пілот Стоунґір служить на Складі Стілґрила в Дун Мороґу, трохи далі стежкою на північний схід від Хараноса.",al={"місце стоунґіра","де пілот стоунґір","склад стілґрілла стоунґір"}},{q="Що потрібно Пілотові Стоунґіру?",a="Стоунґір обожнює вдосконалювати свою облогову машину й одержимий пошуками рідкісних мінералів, які можуть значно посилити вогневу міць набоїв його танка.",al={"мета стоунґіра","чого хоче стоунґір","що потрібно стоунґіру"}},{q="Яке завдання йде після цього?",a="Коли ви доповідаєте Пілотові Стоунґіру на складі, він дає завдання «Пошуки інцендициту» й посилає вас по нестійку руду до Багнокраю.",al={"наступне завдання","продовження стоунґіра","що після пошуків стоунґіра"}},{q="Чи це завдання лише для Альянсу?",a="Так, Пілот Стоунґір і його зв'язкові — вірні вояки війська Айронфорджа й Альянсу.",al={"чи орда може пошуки стоунґіра","вимога фракції"}},{q="Чому склад цікавиться дикою рудою?",a="Дворфійські інженери й пілоти танків постійно експериментують із новими запальними сумішами, піротехнікою й нестійкими елементами, щоб дати своїм бойовим машинам перевагу над трогами, Темним Залізом і дикими звірами.",al={"навіщо дика руда","порох дворфійського танка"}}},fp="18,285,21.429.0,29.324.0,22.130.0,33.107.0,31.162.0,28.155.0,28.99.0,41.202.0"}
P.entries["quest:468"] = {n="Доповідь горянину Рокґару",s="«Доповідь горянину Рокґару» — завдання Альянсу, що веде шукачів пригод від сторожових постів Лох Модану на північ, до Дун Алґазу. Горянин Кадрелл посилає вправних мандрівників до Рокґара, який збирає важливу експедицію в просяклі водою низовини Багнокраю. Це завдання — ворота, що з'єднують дворфійську батьківщину з північними землями.",h="«Доповідь горянину Рокґару» — завдання Альянсу, що веде шукачів пригод від сторожових постів Лох Модану на...",kw={"доповідь горянину рокґару","горянин рокґар","горянин кадрелл","дун алґаз","багнокрай","лох модан"},ang={["faction:Alliance"]="Утримання Дун Алґазу забезпечує безперебійний суходільний шлях до Гавані Менетіл — головного західного порту Альянсу в Східних Королівствах.",["race:Dwarf"]="Відгукнувшись на заклик товаришів-горян, ви зміцнюєте важливий суходільний зв'язок між серцем Айронфорджа й дворфійськими володіннями в Багнокраї."},sec={{t="Шлях до Північної брами",b="Дун Алґаз — важлива артерія між Лох Моданом і болотистими просторами Багнокраю. Укріплений перевал, вбудований у північний гірський кряж, здавна забезпечує безпечний прохід для торгівлі, гінців і військових загонів між Айронфорджем і поселеннями Альянсу далі на півночі. Напруга на кордонах зростає, тож Горянин Кадрелл пильно стежить за мандрівниками й набирає витривалих добровольців на підсилення північних застав."},{t="Доручення, що пішло шкереберть",b="Горянин Кадрелл посилає новобранців, гадаючи, що на них чекає звичайна розвідка, але в Дун Алґазі все виявляється куди небезпечніше. Дійшовши до північної брами, шукачі пригод бачать, що Горянин Рокґар готується не до мирного розвідувального походу, а до справжнього бою. Вороги, що заполонили перевал, швидко перетворюють просту розвідку на запеклу, безладну боротьбу за прохід."}},faq={{q="Хто наказує доповісти Рокґарові?",a="Це доручення дає Горянин Кадрелл. Він стоїть у Телсамарі через дорогу від Корчми «Міцний Лагер» і стереже головний шлях до гірського перевалу.",al={"хто дає доповідь рокґару","хто дає завдання","завдання кадрелла"}},{q="Де знайти Горянина Рокґара?",a="Горянин Рокґар стоїть на північ дорогою з Лох Модану й стереже вхід до гірських тунелів Дун Алґазу.",al={"місце рокґара","де рокґар","місце горянина рокґара"}},{q="Чому це доручення через Дун Алґаз таке важливе?",a="Дун Алґаз — головний суходільний коридор між Лох Моданом і Багнокраєм. Альянсові життєво важливо тримати прохід вільним, щоб зберегти постачання, військовий зв'язок і безпечний шлях до Гавані Менетіл і далі.",al={"чому дун алґаз","важливість дун алґаза","шлях до вологих земель"}},{q="Що буде після зустрічі з Горянином Рокґаром?",a="Рокґар одразу залучає вас до завдання «Прорив крізь Алґаз»: виявляється, що задумана розвідка переросла в криваву битву за очищення гірських тунелів від ворожих сил.",al={"що після рокґара","продовження рокґара","наступне завдання після рокґара"}},{q="Для шукачів пригод якого рівня це доручення?",a="Це доручення для досвідчених мандрівників приблизно 20–21 рівня, які завершують справи в Лох Модані й готуються вирушити в небезпечний Багнокрай.",al={"рівень завдання рокґара","рівень для дун алґаза","коли йти у вологі землі"}},{q="Чи доступне це завдання персонажам Орди?",a="Ні. Горяни Айронфорджа вірні лише Королю Маґні Бронзбірду й Альянсу, тож узяти завдання можуть тільки шукачі пригод Альянсу.",al={"чи орда може це завдання","доповідь рокґару для орди"}}},fp="29,377,26.479.0,19.428.1,41.167.0,37.132.0,51.228.0,47.202.1,56.163.0,44.149.0"}
P.entries["quest:4681"] = {n="Викинуте на берег",s="«Викинуте на берег» — розслідування, яке розпочинає Ґвенніт Блай'Леґґонд в Обердайні, щоб дослідити загиблих морських тварин на оповитих імлою берегах Темного Узбережжя. Діючи від імені Храму Місяця в Дарнасусі, вона посилає шукачів пригод оглянути скелет велетенської морської черепахи, що лежить під водою на захід від селища. Дослідження має пояснити, чому стільки морських створінь викидаються на берег чи гинуть біля нього.",h="«Викинуте на берег» — розслідування, яке розпочинає Ґвенніт Блай'Леґґонд в Обердайні, щоб дослідити загиблих...",kw={"викинуте на берег","ґвенніт блай'леґґонд","морська черепаха","храм місяця","тельдрассил","світове дерево"},ang={["class:Druid"]="Масова загибель і безладна втеча давніх морських звірів Темного Узбережжя натякають на порчу чи порушення рівноваги природи, що розходиться від вод довкола Тельдрассилу.",["class:Priest"]="Проводячи це розслідування, ви підтримуєте Жриць Елуни з Храму Місяця, які опікуються духовним і природним добробутом півночі Калімдору.",["race:NightElf"]="Обердайн — ворота між Тельдрассилом і материком; докази того, що морські мешканці тікають від вашого нового дому, — тривожне знамення."},sec={{t="Тривожний приплив",b="Імлисті пляжі Темного Узбережжя стали цвинтарем для океанських велетнів. Викинуте на берег громаддя й утоплені левіафани встеляють пісок і мілини, спантеличуючи нічних ельфів Обердайна. Уже оглянувши одне викинуте на берег створіння, Ґвенніт Блай'Леґґонд доручає мандрівникам пірнути у води на захід від пристаней, біля затонулого корабля, щоб оглянути кістки величезної морської черепахи й зібрати докази для Храму Місяця."},{t="Втеча від Світового Дерева",b="Кінцева мета Ґвенніт — зібрати досить речових доказів, щоб подати офіційний звіт Жрицям Елуни в Дарнасусі. Її попередні висновки вказують на глибоко тривожну гіпотезу: ці лагідні морські тварини, можливо, гинуть не випадково, а навмисно тікають від чогось у відкритому морі — можливо, від вод, що оточують сам Тельдрассил."}},faq={{q="Чому на Темне Узбережжя викидає морських істот?",a="Причина досі невідома. Ґвенніт потрібні зразки з викинутих на берег істот, щоб подати звіт до Храму Місяця й продовжити дослідження.",al={"чому черепахи вмирають","викинуті істоти темного узбережжя","чому кити на березі"}},{q="Хто така Ґвенніт Блай'Леґґонд?",a="Ґвенніт Блай'Леґґонд — дослідниця нічних ельфів з Обердайна, що звітує безпосередньо Храмові Місяця в Дарнасусі. Вона описує хвилю мертвих і викинутих на берег морських істот уздовж берегів Темного Узбережжя.",al={"ґвенніт","дослідниця обердайна","хто дає викинуте на берег"}},{q="Де лежить кістяк морської черепахи?",a="Кістяк морської черепахи лежить на дні моря просто на захід від пристані Обердайна, поруч з уламками затонулого судна біля берегів Темного Узбережжя.",al={"місце останків черепахи","де скелет черепахи","кістки морської черепахи"}},{q="До чого тут Храм Місяця?",a="Храм Місяця опікується природними й духовними справами земель нічних ельфів. Ґвенніт потрібні конкретні речові зразки, щоб подати жрицям офіційну доповідь про дивну загибель.",al={"чому дарнасу","роль храму місяця","жриці елуни"}},{q="Чи є ще викинуті на берег істоти?",a="Так. Ґвенніт зауважує, що викинуті істоти розкидані по всьому Темному Узбережжю, і заохочує шукачів пригод обшукати піски й зібрати рештки інших велетнів, що опинилися на мілині.",al={"інші викинуті істоти","більше морських завдань","чудовисько на березі"}},{q="Чим відрізняються два завдання «Викинуте на берег»?",a="Перше посилає вас оглянути істоту, викинуту на сусідній пляж, а продовження — пропливти на захід від пристані й дослідити затоплений кістяк морської черепахи.",al={"викинуте на берег частина 1 і 2","два викинуті на берег","ланцюжок викинутого"}}},fp="13,421,17.452.0,26.368.1,50.158.0,29.222.0,41.151.0,54.205.0,41.183.0,62.180.0"}
P.entries["quest:469"] = {n="Щоденна доставка",s="«Щоденна доставка» — доручення від дворфа-мисливця Ейнара Стоунґріпа, який просить мандрівників, що прямують до Гавані Менетіл, віднести вичинені шкури кроколісків місцевому чинбареві. Не бажаючи стикатися з родинними чварами вдома, Ейнар покладається на шукачів пригод, щоб його постачання не спинялося.",h="«Щоденна доставка» — доручення від дворфа-мисливця Ейнара Стоунґріпа, який просить мандрівників, що прямують...",kw={"щоденна доставка","ейнар стоунґріп","джеймс галлоран","сіда","шкури кроколісків","гавань менетіл"},ang={["faction:Alliance"]="Гавань Менетіл — головна морська брама, що з'єднує володіння Айронфорджа з північними землями, тож звичайні товари на кшталт шкіри кроколісків життєво важливі для спорядження місцевої варти й докерів.",["race:Dwarf"]="Навіть далеко від Айронфорджа дворфи провадять своє ремесло в мокрих низинах — хоча родинні сварки, схоже, страшніші за болотяних звірів."},sec={{t="Неохочий посланець",b="На болотах Ейнар Стоунґріп заробляє на життя полюванням на місцеву звірину, а надто на агресивних кроколісків, що чатують уздовж проток. Шкур у нього вдосталь, але щоб їх доставити, треба вертатися додому, до Гавані Менетіл. Не бажаючи зустрічатися з дружиною, Сідою, коли в їхньому шлюбі настала чорна смуга, Ейнар воліє лишатися в полі й передавати свої згортки мандрівникам."},{t="Торгівля в Менетілі",b="Шкури призначено Джеймсові Галлорану, чинбареві з Гавані Менетіл. Галлоран покладається на постійні поставки від місцевих мисливців, щоб шити чоботи й вичиняти шкіру для купців і моряків, що проходять через порт. Помітивши, що Ейнара не видно вже тиждень, чинбар легко здогадується про подружню сварку за цією доставкою через посередника й міркує, що його власній дружині, мабуть, варто втрутитися й помирити Сіду з чоловіком."}},faq={{q="Чому Ейнар Стоунґріп не доставляє шкури сам?",a="Ейнар зізнається, що його дружина Сіда останнім часом у кепському гуморі. Щоб не потрапити їй під гарячу руку, він вештається в Багнокраї й наймає перехожих мандрівників носити його вантажі до міста.",al={"чому ейнар ховається","проблема з дружиною ейнара","чому ейнар не йде додому"}},{q="Хто такий Джеймс Галлоран?",a="Джеймс Галлоран — чинбар і шкірник із Гавані Менетіл. Він скуповує сирі шкури й хутра в місцевих мисливців, вичинює їх і продає як чоботи й готові шкіряні вироби.",al={"галлоран шкіряр","хто такий галлоран"}},{q="Хто така Сіда?",a="Сіда — дружина Ейнара Стоунґріпа, що живе в Гавані Менетіл. Через її недавній поганий настрій Ейнар і проводить дні на болотах, уникаючи повернення додому.",al={"сіда","дружина ейнара"}},{q="Які шкури перевозять?",a="Вантаж — це в'язка шкур кроколісків, здобутих із великих плазунів, що кишать у трясовинах і протоках Багнокраю.",al={"які шкури","предмети щоденної доставки"}},{q="Чи знає Галлоран, чому Ейнар уникає Гавані Менетіл?",a="Так. Коли ви віддаєте в'язку, Галлоран зауважує, що Ейнар не навідувався майже тиждень, і одразу здогадується, що причина — негаразди із Сідою.",al={"чи галлоран знає","реакція шкіряра"}},{q="Де відбувається ця доставка?",a="Доставка починається в Ейнара Стоунґріпа на дорозі в Багнокраї й завершується в майстерні Джеймса Галлорана в Гавані Менетіл на західному узбережжі.",al={"місце здавання","місце щоденної доставки"}}},fp="14,294,19.419.0,20.429.0,54.184.0,22.178.0,12.166.0,41.139.0,57.157.0,36.158.0"}
P.entries["quest:47"] = {n="Обмін Золотого Пилу",s="«Обмін Золотого Пилу» — одна з перших винагород, яку пропонує Ремі «Двічі» з Ґолдшира. Нервовий посередник платить шукачам пригод за те, щоб вони відбирали сирий золотий пил у кобольдів, які заполонили копальні по всьому Лісі Елвінн. Для мандрівників-початківців це чесний заробіток, та дивні зв'язки Ремі натякають, що за його метушнею криється щось більше за просту роботу з металом.",h="«Обмін Золотого Пилу» — одна з перших винагород, яку пропонує Ремі «Двічі» з Ґолдшира.",kw={"золотий пил","ремі двічі","кобольди","фарґодіп","яшмова копальня","ґолдшир","обмін"},ang={["class:Rogue"]="Притишена манера Ремі та знак від безіменних «партнерів» мають безпомильний запах підпільних синдикатів, що діють під спокійною поверхнею Ґолдшира.",["faction:Alliance"]="Те, що життєво важливі поклади золота й мінералів Елвінну тримають здичавілі кобольди, а не королівські рудокопи, показує, наскільки виснажені військові сили королівства.",["profession:Mining"]="Рудокопи, що обшукують Фарґодіп і Яшмову копальню, знайдуть кобольдів просто на найбагатших мідних жилах, тож без зачистки руди не добути."},sec={{t="Містечко кишень і кайл",b="Ґолдшир стоїть на перехресті Лісу Елвінн, де змішуються купці, міська варта й утомлені подорожні. Серед них — Ремі «Двічі», підозрілий тип, чия невідчепна звичка повторювати власні слова приховує гостре око на зиск. Замість наймати дорогі бригади рудокопів, Ремі користається з мандрівних шукачів пригод, що плинуть через Корчму «Лев'яча Гордість». Його пропозиція проста: заберіть золотий пил, який накопичили місцеві шкідники, і обміняйте його просто на монети."},{t="Здобич кобольдів",b="Кобольди цілком захопили найцінніші підземні розробки Елвінну — Копальню Фарґодіп на півдні та Яшмову копальню на північному сході. Довбаючи темряву заради своїх улюблених свічок і блискучих цяцьок, ці щуроподібні землерийки збирають у торбини крихти й пил неочищеної руди. Відганяти їх — в інтересах королівства, а збирати їхній пил означає перетворити винищення шкідників на прибуткову справу."},{t="Тіні за прилавком",b="Ремі запевняє, що платить щедро з чисто купецьких міркувань, та його винагороди несуть ледь помітне застереження. Отримавши пил, він тицяє помічникам маленький знак від своїх «партнерів». В Елвінні, який дедалі міцніше душать організовані бандити, несплачені каменярі й таємні мережі, що діють у тіні Стормвінда, тихі посередники Ремі можуть мати на це золото плани, які сягають значно далі за звичайну сільську торгівлю."}},faq={{q="Хто такий Ремі \"Двічі\"?",a="Ремі \"Двічі\" — дивакуватий місцевий перекупник, що стоїть біля Корчми «Лев'яча Гордість» у Ґолдширі. Відомий тим, що повторює кінці своїх речень, він скуповує цінні матеріали в мандрівних шукачів пригод і водиться з темними ділками.",al={"ремі двічі","хто дає обмін золотого пилу","ремі в ґолдширі"}},{q="Звідки в кобольдів золотий пил?",a="Кобольди все життя риють ходи в рудних жилах Елвінна — як-от у Копальні Фарґодіп і Яшмовій копальні. Шкрябаючи й довбаючи скелю в пошуках скарбів і свічкового воску, вони збирають у кишенях і торбинках луски й пил сирого золота.",al={"чому в кобольдів золотий пил","звідки золотий пил"}},{q="Де знайти копальні, про які каже Ремі?",a="Кобольдів із золотим пилом найчастіше можна знайти в Копальні Фарґодіп і довкола неї, на південь від Ґолдширу, а також у Яшмовій копальні на північному сході, біля межі з Лісозаготівельним Табором Східної Долини.",al={"де копальні","де кобольди елвінн"}},{q="Чому Стормвінд дозволяє кобольдам хазяйнувати в копальнях?",a="Король Варіан Рінн зник, Дім Вельмож відмовляється виділяти війська для околиць, тож Варта Стормвінда страшенно розпорошена. Місцеві гарнізони не можуть очистити копальні, і там кишать кобольди, а битися доводиться вільним мандрівникам.",al={"чому шахти не охороняють","чому стормвінд втратив шахти"}},{q="Чи йде золотий пил на ковальство чи торгівлю?",a="Сирий золотий пил, який носять кобольди, надто дрібний і нечистий для звичайної роботи в кузні. Натомість його продають як сировину перекупникам на кшталт Ремі, які збирають і очищують його своїми потайними шляхами.",al={"навіщо золотий пил","чи можна переплавити пил"}}},fp="18,350,27.491.0,18.444.0,26.430.1,24.246.0,31.255.0,45.216.0,56.269.0,45.222.0"}
P.entries["quest:470"] = {n="Розкопки в слизі",s="Навідуючись, як завжди, до Гробниці Айронбірда, Сіда злякалася мерзенних слизів, що нишпорять курганами, і кинула в них свою торбу, щоб відволікти. Не наважуючись знову зустрітися з повзучою багнюкою, вона просить відважних шукачів пригод у Гавані Менетіл вистежити істоту, що проковтнула її речі.",h="Навідуючись, як завжди, до Гробниці Айронбірда, Сіда злякалася мерзенних слизів, що нишпорять курганами, і...",kw={"розкопки в слизі","сіда","гробниця айронбірда","слизи","гавань менетіл","багнокрай"},ang={["faction:Alliance"]="Гавань Менетіл — головна артерія Альянсу через підступний Багнокрай, і допомога наляканим мешканцям тримає важливий порт у безпеці й порядку.",["race:Dwarf"]="У Гробниці Айронбірда спочиває шанований дворфійський предок, тож осквернення курганів мерзенними слизами — образа для кожного, хто вірний Бронзбірдам."},sec={{t="Панічний відступ",b="Сіда, мешканка Гавані Менетіл, регулярно вирушає на північний схід Багнокраю, щоб ушанувати Гробницю Айронбірда. Під час останнього візиту вона побачила, що прадавній курган кишить мерзенними сочистими слизами. Запанікувавши від вигляду цих безформних жахіть, вона жбурнула торбу в одного з них. Істота просто поглинула торбу цілком, але ця заминка дала Сіді рівно стільки часу, щоб утекти під захист портового містечка."},{t="Багно Гробниці Айронбірда",b="Місце поховання славетного дворфійського героя Айронбірда лежить біля спірної твердині Дун Модр. Попри шану до цього історичного місця, довколишні болота схильні до скверни й приманюють безформні їдкі слизи, що поглинають кожного, кому не пощастить стати їм на шляху. Сіда не пам'ятає, яка саме потвора проковтнула її цінні речі, тож мандрівникам доведеться обшукати околиці гробниці й прорубатися крізь повзучу пошесть, щоб повернути її мокру торбу."}},faq={{q="Хто така Сіда?",a="Сіда — мандрівниця з Альянсу, що мешкає в Гавані Менетіл. Вона регулярно навідується в Багнокрай до Гробниці Айронбірда, і нещодавно ця звичка обернулася серйозною небезпекою, коли на неї напали ворожі слизи.",al={"сіда","хто дає завдання","хто така сіда"}},{q="Де розташована Гробниця Айронбірда?",a="Гробниця Айронбірда — на північному сході Багнокраю, на південь від Дун Модра. Околиці кам'яного кургану заполонили їдкі болотні слизи.",al={"місце гробниці айронбірда","де айронбірд","де слизи"}},{q="Який слиз проковтнув торбу Сіди?",a="Під час нападу Сіда запанікувала й не може розрізнити цих істот. Будь-який зі слизів, що никають біля Гробниці Айронбірда, може ховати в собі її перетравлені пожитки.",al={"який слиз","слиз із торбою","де торба"}},{q="Навіщо Сіда ходила до Гробниці Айронбірда?",a="Щотижня Сіда навідується до гробниці, щоб ушанувати похованого там стародавнього дворфа, але її мирну традицію урвала несподівана поява слизів.",al={"навіщо сіда ходила до гробниці","щотижневі візити сіди"}},{q="Що буде, коли торбу знайдено?",a="Коли ви повертаєте слизьку торбу до Гавані Менетіл, Сіда витрушує вміст на землю, щоб забрати свої речі. Саму зіпсовану торбу вона вважає надто огидною, щоб лишити собі, тож пропонує очищену торбу шукачеві пригод, що її повернув.",al={"що було в торбі","нагорода торби"}},{q="Чи пов'язано це з дворфами Темного Заліза поблизу?",a="Хоча трохи на північ, у Дун Модрі, точиться боротьба з кланом Темного Заліза, слизи біля Гробниці Айронбірда — дикі болотні хижаки з вогких, гнилих закутків Багнокраю, а не дворфійські вояки.",al={"зв'язок з темним залізом","зв'язок з дун модром"}}},fp="24,293,18.440.0,26.476.0,12.219.0,26.174.0,32.181.0,39.173.0,40.254.1,48.227.0"}
P.entries["quest:471"] = {n="Обов'язки учня",s="«Обов'язки учня» — доручення Альянсу від чинбаря Джеймса Галлорана в Гавані Менетіл. Він послав свого юного учня на болота, а хлопця покалічили велетенські кроколіски, тож тепер Галлоран наймає вправного шукача пригод, щоб довершити небезпечну роботу й поквитатися зі звірами.",h="«Обов'язки учня» — доручення Альянсу від чинбаря Джеймса Галлорана в Гавані Менетіл.",kw={"обов'язки учня","джеймс галлоран","велетенські кроколіски","учень","гавань менетіл","багнокрай"},ang={["class:Hunter"]="Верховні хижаки боліт — грізна здобич, і вистежити дорослих велетенських кроколісків — випробування для слідопита: чи вміє він пробиратися каламутними водами серед агресивних звірів.",["faction:Alliance"]="Гавань Менетіл — життєва артерія між Каз Моданом і рештою Альянсу, тож безпека й самостійність її місцевих ремісників життєво важливі для виживання порту."},sec={{t="Сувора наука",b="Ремісникам у прикордонних портах на кшталт Гавані Менетіл доводиться покладатися на місцеву сировину, але довколишні болота безжальні. Джеймс Галлоран послав свого юного учня на болота знімати шкури з велетенських кроколісків Багнокраю. Коли юнак не повернувся, Галлоран розшукав його й знайшов жахливо покаліченим хижаками."},{t="Шкури й відплата",b="Хоча місцева повитуха вважає, що учень виживе, хлопця скалічено: під час нападу він утратив ногу. Потребуючи поповнити запаси й прагнучи хоч якоїсь відплати звірам, що пошматували того, кого він любить як сина, Галлоран наймає мандрівних шукачів пригод вирушити на північ уздовж узбережжя, минути мурлочі халупи й вистежити велетенських кроколісків."}},faq={{q="Хто такий Джеймс Галлоран?",a="Джеймс Галлоран — шкірник і чинбар із Гавані Менетіл. Його ремесло тримається на шкурах місцевих звірів Багнокраю.",al={"джеймс галлоран","хто дає обов'язки учня","шкіряр менетілу"}},{q="Що сталося з учнем Галлорана?",a="Галлоран послав свого учня на болота добути шкури велетенських кроколісків. Хлопця покалічили хижаки: він утратив ногу, хоча міська повитуха певна, що він виживе.",al={"що сталося з учнем","хто покалічений","нога учня"}},{q="Де водяться велетенські кроколіски?",a="Велетенські кроколіски никають болотами й північним узбережжям Багнокраю, одразу за прибережними мурлочими поселеннями на північ від Гавані Менетіл.",al={"де велетенські кроколіски","місце кроколісків вологих земель","велетенський кроколіск"}},{q="Яке завдання передує цьому дорученню?",a="Цьому завданню передує «Шкури молодих кроколісків», де Галлоран спершу посилає шукачів пригод на менших кроколісків, а потім — на велетенських, що покалічили його учня.",al={"попереднє завдання","завдання перед обов'язками учня","ланцюжок кроколісків"}},{q="Чому Галлоранові й після трагедії потрібні шкури?",a="Галлоранові треба вести справу й виконувати замовлення, але ним рухає й гнів. Він радий, що шукач пригод уполює й уб'є звірів, які скалічили хлопця, якого він любить як сина.",al={"чому галлорану шкури","мотив галлорана"}},{q="Чи пропонує Галлоран узяти мене в учні?",a="Побачивши вашу роботу, Галлоран мимохідь жартує, чи не взяти вас за нового учня, але одразу відкидає цю думку: ви, мовляв, надто старі, і вам явно судилася інша доля.",al={"чи можу стати учнем","пропозиція учнівства"}}},fp="19,296,22.331.0,21.386.0,22.164.0,39.221.0,39.143.0,43.179.0,57.199.0,42.194.0"}
P.entries["quest:472"] = {n="Падіння Дун Модра",s="Дун Модр, північна дворфійська фортеця над Мостом Тандол, упала під жорстоким натиском дворфів Темного Заліза. Тяжко поранений уцілілий у Гавані Менетіл просить шукача пригод з Альянсу вирушити на північ і з'ясувати, чи вижили командир Лонґбрейд Похмурий і хоч якісь рештки гарнізону.",h="Дун Модр, північна дворфійська фортеця над Мостом Тандол, упала під жорстоким натиском дворфів Темного Заліза.",kw={"падіння дун модра","дун модр","лонґбрейд похмурий","гарло барнабі","темне залізо","міст тандол"},ang={["faction:Alliance"]="Падіння Дун Модра перерізає безпечний суходільний шлях між Айронфорджем і діями Альянсу в Аратійському нагір'ї на півночі, лишаючи північний коридор вразливим до диверсій.",["race:Dwarf"]="Різанина горян Айронфорджа й осквернення Дун Модра родичами з південного клану — гірка особиста образа, що вимагає крові у відповідь."},sec={{t="Зламаний північний бастіон",b="Дун Модр здавна був опорою північного Каз Модану, стережучи важливу дорогу через Міст Тандол, що з'єднує Багнокрай з Аратійським нагір'ям. Після засідки на самому мосту гарнізон поспіхом відступив, щоб перегрупуватися за мурами фортеці. Та перш ніж вдалося відновити оборону, сили Темного Заліза вдарили переважною кількістю, вирізали захисників і змусили решту до відчайдушного відступу."},{t="Відчайдушна втеча",b="Гарло Барнабі, молодий вояк серед захисників, упав тяжко пораненим, коли випадкова сокира влучила йому в спину під час хаотичного відступу. Вважаючи його рани смертельними, Лонґбрейд Похмурий і решта вояків прив'язали Барнабі до останнього вцілілого коня й відіслали на південь, до Гавані Менетіл. Барнабі пережив це випробування, але прокинувся в шинку гавані, мучачись провиною вцілілого й геть не знаючи, чи вибрався з різанини живим хоч хтось із його товаришів."},{t="Похмурі рештки",b="Глибоко в північних болотах, біля захопленої фортеці, Лонґбрейд Похмурий досі живий і тримає купку побитих уцілілих. Хоч старий командир з полегшенням чує, що юний Гарло пережив свою тяжку рану, перед ним постає сувора тактична дійсність: Дун Модр міцно в руках Темного Заліза, а його зали зайняли головорізи й диверсанти, що загрожують усьому коридорові між Каз Моданом і людськими землями на півночі."}},faq={{q="Що сталося з Дун Модром?",a="Дун Модр захопили ворожі дворфи Темного Заліза. Гарнізон уже зазнав удару із засідки біля сусіднього Мосту Тандол, і перш ніж він устиг зміцнити оборону в містечку, Темне Залізо пішло на штурм і винищило більшу частину полку захисників.",al={"чому дун модр знищений","хто напав на дун модр","дун модр лор"}},{q="Хто такий Гарло Барнабі?",a="Гарло Барнабі — вояк Айронфорджа з гарнізону Дун Модра, що ледве пережив його падіння. Під час відступу йому в спину влучила кинута сокира, і командир прив'язав його до єдиного вцілілого коня гарнізону й відіслав на південь, до Гавані Менетіл, по лікування.",al={"хто такий гарло барнабі","гарло барнабі лор","поранений солдат у менетілі"}},{q="Де знайти Лонґбрейда Похмурого?",a="Командир Лонґбрейд Похмурий сховався в глушині одразу за захопленим Дун Модром, біля північного шляху, що веде до Мосту Тандол.",al={"де лонґбрейд","місце лонґбрейда","знайти лонґбрейда"}},{q="Чому Дун Модр такий важливий стратегічно?",a="Дун Модр — найпівнічніше поселення й укріплення Багнокраю. Він стереже південні підступи до Мосту Тандол — єдиного суходільного мосту, що з'єднує Каз Модан з Аратійським нагір'ям і Лордероном.",al={"чому дун модр важливий","зв'язок з мостом тандол"}},{q="Хто напав на Дун Модр?",a="Нападники — дворфи Темного Заліза, члени підступного клану з півдня, що просунулися на північ, у Багнокрай, щоб руйнувати такі споруди, як Міст Тандол, і непокоїти землі Айронфорджа.",al={"хто захопив дун модр","темне залізо у вологих землях"}},{q="Що буде, коли знайти Лонґбрейда?",a="Коли ви переконаєтеся, що Лонґбрейд живий, і передасте звістку, що Барнабі вижив, Лонґбрейд залучить вас до похмурого доручення — помститися силам Темного Заліза, що засіли в руїнах Дун Модра.",al={"продовження падіння дун модра","що після падіння дун модра"}}},fp="16,308,25.422.0,18.468.0,16.439.1,26.272.0,21.275.0,36.164.1,40.225.0,34.205.0,37.206.1"}
P.entries["quest:4722"] = {n="Морська черепаха на березі",s="На імлистих, омитих прибоєм берегах Темного Узбережжя лежить туша величезної морської черепахи, яку викинуло на берег, а довкола нишпорять мурлоки-падальники. Хоч рештки вже добряче обгризли, з них ще можна здобути придатні біологічні зразки. Натуралісти Обердайна збирають такі зразки, щоб відіслати їх до Храму Місяця в Дарнасусі для ґрунтовного вивчення.",h="На імлистих, омитих прибоєм берегах Темного Узбережжя лежить туша величезної морської черепахи, яку викинуло...",kw={"морська черепаха на березі","ґвенніт блай'леґґонд","мурлоки сірої імли","храм місяця","дарнасус","темне узбережжя"},ang={["class:Druid"]="Друїди бачать у викинутих на берег морських створіннях і мурлоках-падальниках симптоми порушеної рівноваги на Темному Узбережжі, що вимагає пильного спостереження й зцілення.",["race:NightElf"]="Незрозумілі викиди давніх морських створінь свідчать про глибше збурення у водах Калімдору, і дослідники Обердайна й Дарнасуса вивчають кожного викинутого левіафана."},sec={{t="Левіафан на мілині",b="Довгі береги Темного Узбережжя часто приймають жертв Великого Моря — зокрема величезних давніх морських черепах, яких прибиває до берега після смерті або які викидаються на сушу, втративши орієнтацію. Щойно туша опиняється на березі, вона швидко приваблює падальників. Ворожі мурлоки Сірої Імли влаштували грубі табори довкола скелета цієї черепахи, вирізаючи м'ясо й панцир. Попри їхнє нишпорення, серед решток часто лишаються цілі кістки, шматки панцира чи тканини, придатні для дослідження."},{t="Польові дослідження для Дарнасуса",b="Ґвенніт Блай'Леґґонд, що працює в поселенні Обердайн, — польова дослідниця, яка описує незвичайних морських тварин і природні збурення на узбережжі. Нічні ельфи дивляться на цих викинутих на берег звірів і з шаною, і з науковою цікавістю. Придатні рештки ретельно заносять до каталогу й готують до відправлення вченим у Дарнасус, які хочуть зрозуміти, чому стільки велетнів відкритого моря викидає на берег."}},faq={{q="Чому на Темному Узбережжі стільки викинутих на берег морських істот?",a="Бурхливі води й сильні прибережні течії Темного Узбережжя самі собою виносять на пісок уламки й морських звірів, що помирають. Учені нічних ельфів підозрюють, що морських мешканців жене на мілину якесь неприродне збурення в глибинах, тож місцеві природознавці вивчають кожну тушу, яку викидає на берег.",al={"чому мертва морська черепаха","викинуті істоти темного узбережжя","чому викинуло"}},{q="Кому потрібні рештки морської черепахи?",a="Ґвенніт Блай'Леґґонд — дослідниця нічних ельфів з Обердайна — збирає в шукачів пригод викинуті на берег зразки для природознавців і вчених із Дарнасуса.",al={"кому це здати","ґвенніт обердайн","куди здати рештки черепахи"}},{q="Чому довкола черепахи зібралися мурлоки?",a="Місцеві мурлоки Сірої Імли — пристосуванці, що підбирають усе, що винесе на берег. Викинута велетенська морська черепаха — для них щедре джерело м'яса, міцної шкури й кісток для знарядь і притулків.",al={"мурлоки біля черепахи","падальники сірої мли","табір мурлоків"}},{q="Що буде зі зразками, коли їх отримає Ґвенніт?",a="Ґвенніт пакує придатні зразки тканин і кісток, щоб переправити їх через море до Дарнасуса, де вчені й жриці вивчають їх, стежачи за здоров'ям і поведінкою прибережної природи.",al={"що дарнас робить із рештками","дослідження зразків черепахи"}},{q="Чи це єдина викинута істота на узбережжі?",a="Ні. На довгому узбережжі Темного Узбережжя лежить чимало викинутих морських черепах і велетенських морських звірів, і кілька з них дають зразки для дослідників Обердайна.",al={"інші викинуті тварини","ще мертві черепахи","викинуті на берег істоти"}},{q="Чи священні морські черепахи для нічних ельфів?",a="Нічні ельфи шанують корінних звірів Калімдору як частину природної рівноваги під опікою Елуни й диких богів. Морські черепахи не є окремими божественними втіленнями, але їхні несподівані смерті й викиди на берег сприймають як серйозні тривожні знаки для природи.",al={"чи черепахи нічних ельфів","нічні ельфи і черепахи"}}},fp="18,339,20.466.0,28.445.0,57.302.0,33.169.0,43.209.0,56.204.0,50.168.0,42.250.0"}
P.entries["quest:4723"] = {n="Морське створіння на березі",s="На оповитому туманом березі Краю Імли лежить величезна туша морського молотильника, значно більшого за будь-якого, що водиться на мілинах Темного Узбережжя. Поки місцеві мурлоки обгризають падло, натуралісти Обердайна шукають кісткових зразків, щоб зрозуміти, чому такі колосальні глибоководні звірі викидаються на узбережжя.",h="На оповитому туманом березі Краю Імли лежить величезна туша морського молотильника, значно більшого за...",kw={"морське створіння на березі","молотильник","край імли","ґвенніт блай'леґґонд","дарнасус","приховане море"},ang={["class:Druid"]="Друїди, віддані збереженню природної гармонії, бачать у викинутому на берег левіафані тривожний симптом збурення в живому світі Прихованого Моря.",["race:NightElf"]="Викиди на Темному Узбережжі — тривожна ознака порушеної рівноваги в навколишніх водах, тож натуралісти Обердайна й Дарнасуса розслідують їх, доки не загинуло ще більше морських створінь."},sec={{t="Велетень на мілині",b="Береги Краю Імли звикли до корабельних аварій і викинутого припливом мотлоху, але раптова поява решток величезного молотильника тривожить. Ця істота набагато більша за звичайних місцевих звірів — вона явно прийшла з глибин далеко за спокійними водами Прихованого Моря. Хоч прибережні мурлоки охоче обсідають тушу й бенкетують нею, вони не мають ні сили, ні злагодженості, щоб здолати левіафана такого розміру. Хижак загинув від чогось зовсім іншого, перш ніж його викинуло на берег."},{t="Дослідження в Дарнасусі",b="Ґвенніт Блай'Леґґонд в Обердайні координує польові зусилля, щоб урятувати кістки й біологічні зразки викинутих на берег велетнів Темного Узбережжя. Дослідники нічних ельфів у Дарнасусі сподіваються, вивчивши рештки скелетів і зразки тканин, з'ясувати, що жене цих океанських велетнів на смертоносний пісок — хвороба, глибоководні збурення чи тайна порча."}},faq={{q="Що за звіра викинуло на берег?",a="Це рештки велетенського трешера — морського хижака, набагато більшого за трешерів, яких зазвичай бачать біля пляжів Темного Узбережжя.",al={"яка це істота","що за мертве чудовисько","яка тварина мертва на пляжі"}},{q="Чи вбили його мурлоки?",a="Ні. Хоча мурлоки кишать довкола туші, ласуючи гнилим м'ясом, спостерігачі зауважують, що вони надто слабкі, навіть великою зграєю, щоб уполювати глибоководного велетня таких розмірів.",al={"чи мурлоки вбили молотарку","чи мурлоки вбили морську істоту"}},{q="Чому морські істоти викидаються на берег Темного Узбережжя?",a="Точна причина невідома. Дослідники нічних ельфів підозрюють, що невидимі збурення в океані, хвороба чи порушення природної рівноваги змушують глибоководних мешканців запливати на мілину, де вони опиняються на березі й гинуть.",al={"чому молотарки вмирають","чому істоти викидаються на берег"}},{q="Хто така Ґвенніт Блай'Леґґонд?",a="Ґвенніт Блай'Леґґонд — дослідниця нічних ельфів з Обердайна. Вона збирає кістки й біологічні зразки викинутих на берег істот уздовж Темного Узбережжя, щоб надіслати їх до Дарнасуса для докладного вивчення.",al={"хто така ґвенніт","хто бере кістки в обердайні"}},{q="Куди відсилають зібрані кістки?",a="Описавши й підготувавши зразки в Обердайні, Ґвенніт відсилає їх ученим і природознавцям у столицю, Дарнасус, на анатомічне й магічне дослідження.",al={"куди йдуть кістки","що обердайн робить із кістками"}},{q="Де лежить ця туша?",a="Туша лежить просто на піщаному березі Краю Імли, на західному узбережжі Темного Узбережжя.",al={"місце туші","де викинута морська істота"}}},fp="20,316,23.473.0,20.362.0,42.139.0,24.183.0,59.202.0,29.205.0,35.182.0,30.99.0"}
P.entries["quest:4725"] = {n="Морська черепаха на березі",s="У прибої Темного Узбережжя лежить туша величезної морської черепахи з розбитими ношами на спині, а довкола кишать спритні мурлоки Сірої Імли. На відміну від інших мертвих левіафанів на узбережжі, цю істоту перед загибеллю на піску запрягли зміїсті наги як в'ючну тварину.",h="У прибої Темного Узбережжя лежить туша величезної морської черепахи з розбитими ношами на спині, а довкола...",kw={"морська черепаха на березі","дивно помічена скриня","наги","мурлоки сірої імли","ґвенніт блай'леґґонд","темне узбережжя"},ang={["faction:Alliance"]="Розслідування викинутих на берег створінь дає Вартовим Обердайна важливі відомості — і про навалу мурлоків, і про появу організованих загонів наг.",["race:NightElf"]="В'ючні звірі наг, яких викидає на береги Темного Узбережжя, підтверджують, що давні вороги калдореїв активно зміцнюють плацдарми незатишно близько від Дарнасуса."},sec={{t="Звір у збруї",b="Оповиті імлою береги Темного Узбережжя потерпають від тривожної кількості викинутих на сушу морських велетнів, але саме ця черепаха розповідає куди зловіснішу історію. На її колосальному панцирі закріплено розхитані ноші, покинуті й гниючі в припливі. На відміну від інших викинутих на берег створінь, що загинули від хвороби чи природного виснаження, цього велетня запрягли до служби й пригнали до берега розумні погоничі."},{t="Падальники мілин",b="Туша недовго лишалася в спокої. Місцеві мурлоки Сірої Імли швидко обсіли рештки й облаштували собі кубло серед гниючого м'яса й підібраних дощок. Серед мурлоцького сміття й розбитого остова морських нош лежить ціла, дивно позначена скриня, яку лишили справжні господарі звіра."},{t="Шляхи постачання наг",b="Коли Дивно Помічену Скриню приносять Ґвенніт Блай'Леґґонд в Обердайн, похмура правда стає очевидною. На скрині — знаки наг, а збруя така сама, як на вантажних ношах, якими зміїстий народ переправляє зброю й військове спорядження з океанських глибин. Мертва черепаха — прямий доказ того, що наги готують вторгнення на північ Темного Узбережжя, і знайдений артефакт поспіхом відсилають до Дарнасуса для подальшого вивчення."}},faq={{q="Чому на панцирі морської черепахи стоїть повозка?",a="Повозка належала нагам, які запрягають велетенських морських черепах як в'ючних і облогових тварин. На цих повозках вони перевозять припаси й зброю з глибин на узбережжя Темного Узбережжя.",al={"повозка на черепасі","чому повозка на черепасі","запряжена черепаха"}},{q="Що в повозці?",a="Серед уламків покинутої повозки лежить дивно позначена скриня. Руни на ній свідчать, що вона належить нагам, тож учені Обердайна відсилають її до Дарнасуса на офіційний огляд.",al={"скриня черепахи","дивно помічена скриня","скриня в повозці"}},{q="Чому довкола черепахи зібралися мурлоки?",a="Мурлоки Сірої Імли живуть на узбережжі й раз у раз обшукують уламки кораблів і викинуті туші. Рештки велетенської черепахи вони привласнили як джерело їжі й гніздо.",al={"мурлоки навколо черепахи","мурлоки сірої мли черепаха","чому мурлоки їдять черепаху"}},{q="Хто вивчає викинутих на берег істот на Темному Узбережжі?",a="Ґвенніт Блай'Леґґонд з Обердайна очолює розслідування хвилі викинутих на берег морських істот, описуючи реліквії й дивні матеріали, знайдені на їхніх рештках.",al={"хто вивчає викинутих істот","дослідниця обердайна","роль ґвенніт блай'леґґонд"}},{q="Чим ця черепаха відрізняється від інших викинутих істот Темного Узбережжя?",a="Багатьох інших істот викидає на берег через хвороби, скверну чи лихо в океані, а ця черепаха явно була приручена, навантажена важкою упряжжю з вантажем, і наги навмисно пригнали її до берега.",al={"інші викинуті черепахи","чим ця черепаха інша","таємниця черепах темного узбережжя"}},{q="Що буде з позначеною скринею після Обердайна?",a="Ґвенніт Блай'Леґґонд записує знахідку в Обердайні й відсилає скриню наг до Дарнасуса, де провід ельфів оцінює дедалі більшу загрозу на їхніх північних кордонах.",al={"куди йде скриня","скриня до дарнаса","що обердайн робить зі скринею"}}},fp="18,292,18.443.0,26.318.0,17.446.1,50.206.0,28.200.0,43.167.0,47.167.0,73.206.0,47.174.0"}
P.entries["quest:4727"] = {n="Морська черепаха на березі",s="На північних берегах Темного Узбережжя лежить величезний скелет викинутої на сушу морської черепахи — і, дивна річ, місцеві мурлоки Сірої Імли його не чіпають. Пробу її решток збирають і доставляють Ґвенніт Блай'Леґґонд в Обердайн для Храму Місяця. Натуралісти й жриці прагнуть з'ясувати, чому ці великі океанські створіння викидаються на берег і чому навіть падальники неохоче до них підходять.",h="На північних берегах Темного Узбережжя лежить величезний скелет викинутої на сушу морської черепахи — і...",kw={"морська черепаха на березі","ґвенніт блай'леґґонд","храм місяця","мурлоки сірої імли","обердайн","темне узбережжя"},ang={["class:Druid"]="Друїди пильно стежать за узбережжям, і їх глибоко тривожить, коли падальники на кшталт мурлоків не торкаються мертвих: це може свідчити про протиприродну скверну у водах.",["class:Priest"]="Служити Храму Місяця — означає поширювати співчутливу опіку Елуни на все живе й розслідувати смерті, що порушують гармонію природи.",["race:NightElf"]="Незрозуміла загибель величних морських створінь, яких уникають навіть падальники, свідчить про дедалі більший розлад, що загрожує землям предків калдореїв."},sec={{t="Дивна відсутність",b="Північні береги Темного Узбережжя кишать мурлоками Сірої Імли — істотами, відомими тим, що хижо обгризають усе поживне, що викидає з Прихованого Моря. Та цей величезний черепаховий скелет лежить майже недоторканий. Чи мурлоки просто не помітили здобичі, чи навмисно уникали решток із якоїсь незримої причини — тривожна загадка для тих, хто вивчає природу пляжу."},{t="Дослідження узбережжя",b="В Обердайні Ґвенніт Блай'Леґґонд збирає для Храму Місяця зразки цих викинутих на берег велетнів. Жриці нічних ельфів прагнуть зрозуміти, що тривожить води Темного Узбережжя, і за уламками скелетів визначають, що саме жене давніх мешканців моря на смерть — хвороба, магічна порча чи мерзенні морські хижаки."}},faq={{q="Що це за викинута на берег морська черепаха?",a="Це величезний кістяк стародавньої морської черепахи, викинутий на берег на півночі Темного Узбережжя. Її незвична поява й те, що падальники її не чіпають, роблять її предметом дослідження нічних ельфів.",al={"туша черепахи","скелет морської черепахи","що це за черепаха"}},{q="Чому мурлоки уникають туші?",a="Мурлоки Сірої Імли зазвичай розшматовують будь-яку тушу на пляжі, але ці рештки не чіпають. Ґвенніт Блай'Леґґонд і Храм Місяця підозрюють, що падальників відлякує неприродна скверна чи невидима небезпека, пов'язана зі смертю істоти.",al={"чому мурлоки не їдять її","мурлоки сірої мли черепаха","чому уникають туші"}},{q="Хто така Ґвенніт Блай'Леґґонд?",a="Ґвенніт Блай'Леґґонд — дослідниця нічних ельфів з Обердайна, що збирає польові зразки викинутих на берег морських мешканців Темного Узбережжя для Храму Місяця.",al={"ґвенніт обердайн","кому потрібні рештки черепахи","здати завдання черепахи"}},{q="Чому Храм Місяця цікавлять викинуті на берег морські істоти?",a="Жриці Елуни бережуть рівновагу й дбають про природний світ на півночі Калімдору. Оскільки на Темному Узбережжі незвично багато морських істот гине, Храм аналізує біологічні зразки, щоб з'ясувати, яка недуга вражає моря.",al={"храм місяця черепаха","чому вивчати черепах","морське життя елуни"}},{q="Де лежить саме ця морська черепаха?",a="Ця туша лежить на піщаному північному узбережжі Темного Узбережжя, неподалік земель, де живуть племена мурлоків Сірої Імли.",al={"де черепаха","місце викинутої черепахи","черепаха темне узбережжя"}},{q="Чи є інші викинуті на берег істоти на Темному Узбережжі?",a="Так. Береги Темного Узбережжя всіяні численними викинутими морськими істотами й велетенськими морськими черепахами, і кожна з них спонукає дослідників Обердайна з'ясовувати, чому гинуть велетні океану.",al={"інші викинуті істоти","ще морські черепахи","завдання викинутих істот"}}},fp="18,422,17.401.0,22.356.0,31.200.0,41.278.0,29.170.0,65.262.0,44.140.0,50.191.0"}
P.entries["quest:4728"] = {n="Морське створіння на березі",s="На імлистому березі Темного Узбережжя лежить величезна туша морського ссавця, яку покинули посеред розкопок. Розкидані інструменти й покинута тачка свідчать про експедицію, що раптово урвалася, лишивши зразок спритним мурлокам і цікавим очам мандрівників.",h="На імлистому березі Темного Узбережжя лежить величезна туша морського ссавця, яку покинули посеред розкопок.",kw={"морське створіння на березі","ліга дослідників","ґвенніт блай'леґґонд","храм місяця","мурлоки","темне узбережжя"},ang={["faction:Alliance"]="Ця знахідка показує спільні зусилля Дарнасуса й айронфордзької Ліги Дослідників, що прагнуть описати таємниці Калімдору.",["race:Dwarf"]="Покинуті довкола туші інструменти належать вашим родичам із Ліги Дослідників, яких прогнали з розкопок місцеві мурлоки.",["race:NightElf"]="Храм Місяця глибоко стурбований протиприродною частотою, з якою величезні морські створіння гинуть і викидаються на священні береги Темного Узбережжя."},sec={{t="Перервані розкопки",b="Туша на пісках Темного Узбережжя належить величезному морському ссавцеві — частково випатраному й добряче поточеному морськими бризками. Довкола його гниючого остова розкидано іржаву тачку й покинуті інструменти для розкопок — явний знак, що хтось намагався ґрунтовно дослідити звіра, перш ніж його прогнали чи він поспіхом покинув місце."},{t="Ліга й мурлоки",b="Покинуте спорядження належало дворфським польовим дослідникам Ліги Дослідників, що працюють на Темному Узбережжі. Їхнє вивчення величезної туші раптово обірвалося, коли місцеві мурлоки обсіли місце й забрали викинутого велетня собі на поживу. Ґвенніт Блай'Леґґонд в Обердайні, що діє від імені Храму Місяця, радо приймає будь-які врятовані кісткові зразки, щоб далі вивчати протиприродні викиди, які нівечать узбережжя."}},faq={{q="Що це за істота лежить на пляжі?",a="Це рештки велетенського морського ссавця, викинутого на берег Темного Узбережжя. Вид достеменно не визначено, але туша досить велика, щоб привабити і мурлоків-падальників, і дворфійських дослідників.",al={"хто ця істота на пляжі","що за туша","що тут здохло"}},{q="Хто лишив тут інструменти й тачку?",a="Інструменти лишили дворфи з Ліги Дослідників. Вони облаштували тут розкопки, щоб вивчити викинутого звіра, але ворожі прибережні мурлоки напали на них і прогнали, перш ніж ті встигли закінчити.",al={"хто залишив інструменти","покинута тачка темне узбережжя","хто тут копав"}},{q="Навіщо Ґвенніт Блай'Леґґонд ці кістки?",a="Ґвенніт Блай'Леґґонд збирає зразки для Храму Місяця в Дарнасусі. Нічні ельфи активно досліджують дивне й тривожне явище: величезні морські істоти мертвими опиняються на берегах Темного Узбережжя.",al={"навіщо ґвенніт кістки","храм місяця морська істота","кістки обердайна"}},{q="Чому довкола туші никають мурлоки?",a="Мурлоків привабило величезне частування з м'яса й жиру, тож вони прогнали дворфійських учених, щоб самим обгризати рештки й захищати їх.",al={"мурлоки навколо туші","чому мурлоки тут","мурлоки-падальники"}},{q="Чи офіційно співпрацює тут Ліга Дослідників з Обердайном?",a="Так. Як союзниця в Альянсі, Ліга Дослідників присутня на Темному Узбережжі й співпрацює з місцевою владою нічних ельфів, часто ділячись звітами про свої наукові відкриття й дослідження узбережжя.",al={"ліга дослідників обердайн","дворфи на темному узбережжі","ліга дослідників альянс темне узбережжя"}},{q="Чи є інші викинуті на берег істоти на Темному Узбережжі?",a="Так. Уздовж туманних пляжів Темного Узбережжя викинуло чимало величезних морських звірів і кістяків — ознака того, що у водах біля Калімдору коїться щось недобре.",al={"ще викинуті істоти","інші туші темного узбережжя","кілька викинутих морських істот"}}},fp="20,263,19.355.0,26.441.0,41.207.0,42.209.0,48.236.0,44.162.0,63.233.0,60.181.0"}
P.entries["quest:473"] = {n="Доповідь капітану Стаутфісту",s="«Доповідь капітану Стаутфісту» — військовий наказ Альянсу в Гавані Менетіл. Після перших сутичок із кланом Драконячої Пащі в Дун Алґазі Валстаґ Айронджо посилає випробуваних бійців до фортеці гавані, щоб узгодити глибші оборонні дії. Капітан Стаутфіст командує місцевим гарнізоном і готує прямі удари по оркам, що окопалися по всьому Багнокраю.",h="«Доповідь капітану Стаутфісту» — військовий наказ Альянсу в Гавані Менетіл.",kw={"доповідь капітану стаутфісту","капітан стаутфіст","валстаґ айронджо","драконяча паща","фортеця менетіл","гавань менетіл"},ang={["class:Warrior"]="Валстаґ Айронджо цінує справжню бойову вправність і відсилає досвідчених бійців передової просто до тактичного проводу Капітана Стаутфіста.",["faction:Alliance"]="Гавань Менетіл — головна брама для товарів і підкріплень між південними королівствами й Каз Моданом; утратити дорогу через набіги орків означало б покалічити торгівлю Альянсу.",["race:Dwarf"]="Захист торгового шляху між Гаванню Менетіл і брамами Айронфорджа життєво важливий для безпеки Каз Модану, тож це доручення — суто дворфійська справа."},sec={{t="Загроза ширшає",b="Дворфи-горяни здавна пильнують вузькі гірські перевали Дун Алґазу, але відродження клану Драконячої Пащі не стримати самими лише кордонами Лох Модану. Валстаґ Айронджо розуміє, що ці орки тиснуть назовні, розбивають табори й загрожують усім болотам. Убезпечити перевал — лише перший хід у ширшій кампанії за безпеку дороги до Айронфорджа."},{t="Воєнна Кімната Менетіла",b="Глибоко у Фортеці Менетіл міститься Воєнна Кімната, де Капітан Стаутфіст керує обороною порту Альянсу. Стикаючись із нападами диверсантів Темного Заліза, місцевих звірів і болотяних мурлоків, капітан покладається на вправних добровольців, щоб відбивати зовнішні військові загрози. Рекомендація Валстаґа підтверджує, що ви досить загартовані, аби виконувати прямі накази проти бойової машини Драконячої Пащі."}},faq={{q="Хто посилає мене до Капітана Стаутфіста?",a="Валстаґ Айронджо з Фортеці Менетіл у Гавані Менетіл посилає вас доповісти Капітанові Стаутфісту, коли ви проявите себе в бою з місцевими орками Драконячої Пащі.",al={"хто дає завдання","дає завдання","валстаґ айронджо"}},{q="Де знайти Капітана Стаутфіста?",a="Капітан Стаутфіст — у Фортеці Менетіл, у серці Гавані Менетіл на заході Багнокраю. Він стоїть над тактичними мапами в залі військової ради.",al={"місце стаутфіста","де стаутфіст","штаб менетілу"}},{q="Чому орки Драконячої Пащі — пріоритет для Фортеці Менетіл?",a="Клан Драконячої Пащі тримає давні твердині по всьому Багнокраю й зухвало загрожує торговим шляхам, що з'єднують Гавань Менетіл з Айронфорджем. Коли їхні сили просуваються аж за Дун Алґаз, гарнізон не може не зважати на дедалі більші табори.",al={"чому драконяча паща пріоритет","загроза драконячої пащі","орки у вологих землях"}},{q="Що буде після доповіді Капітанові Стаутфісту?",a="Вислухавши вас, Капітан Стаутфіст одразу залучає вас до наступу на клан Драконячої Пащі й посилає вдарити по їхніх таборах і повалити їхні бойові стяги на болотах.",al={"що далі","наступне завдання","після доповіді стаутфісту"}},{q="Хто такі орки Драконячої Пащі в Багнокраї?",a="Драконяча Паща — рештки Старої Орди, що під час Другої війни прославилися поневоленням червоних драконів у Ґрім Батолі. Хоча Ґрім Батол упав, уцілілі загони досі окопані на болотах, грабують мандрівників і кидають виклик владі Альянсу.",al={"лор драконячої пащі","хто такі драконяча паща","орки вологих земель"}},{q="Чому сили Гавані Менетіл так розпорошені?",a="Гавань Менетіл постійно потерпає від болотних звірів, мурлоків, що наступають, і ворожих дворфів Темного Заліза, які намагаються підточити порт. Гарнізон зайнятий захистом мурів і причалів, тож Капітан Стаутфіст покладається на сторонніх звитяжців, щоб ті громили віддалені застави орків.",al={"оборона менетілу","чому війська зайняті","проблеми гавані"}}},fp="27,382,17.420.0,24.388.0,34.173.0,35.179.0,56.260.0,50.200.0,43.254.0,41.278.0"}
P.entries["quest:4730"] = {n="Морське створіння на березі",s="На продуваному вітрами березі Темного Узбережжя лежать напівз'їдені рештки величезного морського ссавця, а довкола чатують спритні мурлоки. Жриця Ґвенніт Блай'Леґґонд в Обердайні шукає кісткових зразків цих викинутих велетнів, щоб з'ясувати, чому зазвичай сумирні океанські звірі так жорстоко гинуть на піску.",h="На продуваному вітрами березі Темного Узбережжя лежать напівз'їдені рештки величезного морського ссавця, а...",kw={"морське створіння на березі","ґвенніт блай'леґґонд","храм місяця","тельдрассил","мурлоки","темне узбережжя"},ang={["class:Druid"]="Будь-яке порушення поведінки морських тварин — грізне знамення для Кола Кенарія, що вказує на протиприродну пошесть, яка отруює прибережних звірів.",["class:Priest"]="Храм Місяця фінансує це розслідування й наглядає за ним, шукаючи божественного прозріння щодо порчі, яка тривожить води Калімдору.",["faction:Alliance"]="Убезпечуючи береги довкола Обердайна, ви захищаєте важливі морські шляхи Альянсу між Темним Узбережжям, Тельдрассилом і Східними Королівствами.",["race:NightElf"]="Викиди на Темному Узбережжі болісно відгукуються в серцях калдореїв, які шанують гармонію природи й з острахом дивляться, як неспокійнішають води довкола їхнього нового дому — Тельдрассилу."},sec={{t="Моторошна знахідка на березі",b="На півночі, на самотніх пляжах Темного Узбережжя, лежить гниюча, напівз'їдена туша велетенського морського ссавця. Хвилі б'ються об оголені ребра, а незвично люте плем'я мурлоків обгризає кістки дочиста. Це видовище водночас трагічне й тривожне: воно свідчить, що рівновага в океані хитається так само сильно, як і в отруєних лісах углибині суходолу."},{t="Нехарактерний викид",b="За словами жриці Ґвенніт Блай'Леґґонд, створіння, яких викидає на берег, — зазвичай лагідні морські ссавці з вод довкола підніжжя Тельдрассилу. На відміну від агресивних молотильників, ці сумирні звірі ніколи не кидалися несамовито на скелі. Храм Місяця ретельно каталогізує кісткові зразки, щоб з'ясувати, яка мерзенна порча чи прихована загроза жене їх із глибин гинути на узбережжі."}},faq={{q="Що за істоту викинуло тут на берег?",a="Кістяк належить великому лагідному морському ссавцеві, що зазвичай живе в глибоких спокійних водах біля підніжжя Тельдрассилу. Ці велетні від природи мирні й не схильні ні до агресії, ні до того, щоб викидатися на берег.",al={"яка це тварина","що за викинута істота","кістки морського чудовиська"}},{q="Чому морська істота викинулася на берег?",a="Точна причина невідома, але Жриця Ґвенніт Блай'Леґґонд зауважує, що для цього виду таке цілком неприродно. Дослідники нічних ельфів підозрюють, що якесь приховане збурення чи скверна в навколишніх морях збиває істот з пуття або змушує тікати з рідних вод.",al={"чому викинулася на берег","чому морські істоти вмирають","викиди темного узбережжя"}},{q="Хто така Ґвенніт Блай'Леґґонд?",a="Ґвенніт Блай'Леґґонд — жриця, що представляє Храм Місяця в Обердайні. Вона координує дослідження природи узбережжя Темного Узбережжя й збирає кістяки, щоб вивчити недугу, яка вражає місцевих морських мешканців.",al={"хто здає це завдання","хто така ґвенніт","жриця обердайна"}},{q="Чому довкола туші зібралися мурлоки?",a="Мурлоки — пристосуванці, яких привабив викинутий велетень як легке й щедре джерело їжі. Зграя довкола саме цієї туші помітно сильніша й агресивніша за мурлоків, що живуть ближче до Обердайна.",al={"чому мурлоки тут","мурлоки біля кісток","мурлоки на пляжі"}},{q="Де зазвичай живе ця істота?",a="Ці морські ссавці живуть у відкритих водах довкола велетенського гілля й коріння Тельдрассилу й за звичайних обставин рідко наближаються до берегів суходолу.",al={"де вони живуть","середовище морських ссавців","морські істоти тельдрассила"}},{q="Як це пов'язано з іншими викидами на берег на Темному Узбережжі?",a="На берег Темного Узбережжя викинуло кілька морських видів, зокрема хижих трешерів і велетенських морських черепах. Трешери й від природи неспокійні, але те, що на берег викидаються й мирні ссавці, підтверджує: морська аномалія зачіпає всю прибережну природу.",al={"інші викинуті морські істоти","викинута молотарка","викинута морська черепаха"}}},fp="20,314,30.357.0,26.459.0,37.225.0,38.304.0,29.258.0,43.221.0,39.175.0,53.275.0"}
P.entries["quest:4731"] = {n="Морська черепаха на березі",s="Ця туша викинутої на берег морської черепахи на березі Темного Узбережжя несе розбиті ноші й скриню з дивними рунами. На відміну від інших морських створінь, яких викидає на сушу природним шляхом, ця істота, схоже, загинула, служачи в'ючною твариною.",h="Ця туша викинутої на берег морської черепахи на березі Темного Узбережжя несе розбиті ноші й скриню з дивними...",kw={"морська черепаха на березі","наги","ґвенніт блай'леґґонд","храм місяця","ашенваль","темне узбережжя"},ang={["class:Druid"]="Шляхетна морська черепаха, поневолена, щоб тягати бойову зброю, і кинута гнити серед падальників, — яскравий приклад того, як зневажливо й згубно ставляться наги до диких звірів.",["faction:Alliance"]="Дослідивши ці рештки, ви попереджаєте Обердайн і Дарнасус про шляхи постачання наг, що загрожують півночі Калімдору.",["race:NightElf"]="Використання морських створінь як військового транспорту — наруга, що обурює калдореїв, а знайдені сліди допомагають Храму Місяця відстежувати загрози, що сунуть до Ашенвалю."},sec={{t="В'ючний звір",b="Береги Темного Узбережжя всіяні кістками давніх морських створінь, але цей черепаховий скелет розповідає виразно штучну історію. На величезному панцирі закріплено розтрощені рештки погнутих нош. Ця істота загинула не від хвороби чи втрати орієнтації, як інші викинуті на берег, — її загнали на скелі, коли вона тягла вантаж. Серед уламків нош лежить скриня, оздоблена незнайомим зміїстим різьбленням, — лишена серед падальників, що загарбали гниючий панцир."},{t="Вторгнення наг",b="Оглянувши врятовану скриню в Обердайні, Ґвенніт Блай'Леґґонд розпізнає в ній роботу наг. Зміїсті потвори часто запрягають великих морських звірів, щоб переправляти на берег припаси й зброю під час своїх нападів із моря. Зважаючи на те, що рештки лежать на південних берегах Темного Узбережжя, Ґвенніт підозрює, що цей вантажний транспорт загинув, переправляючи спорядження до Ашенвалю, — а це вказує на дедалі ширші амбіції наг на півночі Калімдору."}},faq={{q="Чому в цієї морської черепахи на спині повозка?",a="Повозку на істоту приладнали наги: вони використовують велетенських морських черепах як живих в'ючних тварин, щоб перевозити припаси, зброю й військове спорядження з глибин океану на суходіл.",al={"повозка на черепасі","чому в черепахи віз","упряж морської черепахи"}},{q="Хто зараз живе в рештках?",a="Після смерті черепахи її велетенський панцир захопила зграя сильних мурлоків Сірої Імли, перетворивши видовбану тушу на укріплений прибережний притулок.",al={"хто живе в рештках","мурлоки сірої мли черепаха","що охороняє черепаху"}},{q="Куди нести Дивно Помічену Скриню?",a="Скриню треба принести Ґвенніт Блай'Леґґонд — посланниці Храму Місяця в прибережному поселенні Обердайн.",al={"куди нести скриню","дивно помічена скриня","здати помічену скриню"}},{q="Що означають знаки на скрині?",a="Знаки — це письмо наг. Вони свідчать, що скриня й повозка належали до обозу наг, який рухався вздовж узбережжя — найімовірніше, на південь, до Ашенвалю, — доки не сталося лихо.",al={"лор скрині черепахи","хто зробив помічену скриню","скриня нагів"}},{q="Чому Храм Місяця цікавлять викинуті на берег черепахи?",a="Жриці Елуни досліджують природні й воєнні загрози, що спіткали узбережжя Темного Узбережжя. Знайдені артефакти на кшталт цієї скрині відсилають до Дарнасуса, щоб учені могли простежити пересування ворогів.",al={"чому храм хоче черепах","місія ґвенніт на узбережжі"}},{q="Куди прямувала черепаха перед смертю?",a="Зважаючи на те, де на узбережжі лежить туша, Ґвенніт Блай'Леґґонд підозрює, що наги гнали навантажену істоту на південь — можливо, до Ашенвалю.",al={"куди йшла черепаха","призначення черепахи"}}},fp="18,249,17.515.0,18.488.1,53.185.0,40.155.0,39.149.0,37.193.1,60.216.0,46.175.1"}
P.entries["quest:4732"] = {n="Морська черепаха на березі",s="На побитому вітрами березі Темного Узбережжя з тривожною частотою з'являються вибілені кістки велетенських морських черепах. Дослідження цих трагічних викидів дає Ґвенніт Блай'Леґґонд в Обердайні зразки, щоб з'ясувати, чому вимирають морські мешканці Калімдору.",h="На побитому вітрами березі Темного Узбережжя з тривожною частотою з'являються вибілені кістки велетенських...",kw={"морська черепаха на березі","нордрассил","гора гіджал","тельдрассил","ґвенніт блай'леґґонд","храм місяця"},ang={["class:Druid"]="Трагічні викиди цих давніх мешканців океану — суворий знак порушеної рівноваги природи після битви на Горі Гіджал і раптової появи Тельдрассилу.",["class:Priest"]="Здобуваючи ці рештки для Храму Місяця, ви допомагаєте Сестринству Елуни розпізнати незриму духовну недугу, що шириться водами Калімдору.",["race:NightElf"]="Храм Місяця прагне вшанувати й зрозуміти згасаючих створінь, що колись мирно бавилися під гіллям Нордрассилу."},sec={{t="Берег кісток",b="Оповитий імлою берег Темного Узбережжя всіяний рештками великих левіафанів і величних морських черепах. Багатьох із цих давніх плазунів прибило до мілин, а інші самі виповзли на пісок, щоб загинути. Мурлоки Сірої Імли часто обсідають величезні туші, обгризаючи м'ясо до панцира й кісток, і влаштовують довкола падла грубі табори."},{t="Води, що зникають",b="До Третьої війни морські черепахи буяли у священних водах довкола Гори Гіджал і коріння Світового Дерева — Нордрассилу. Після того як Нордрассил пожертвували, щоб здолати Палаючий Легіон, а біля північного берега Калімдору посадили Тельдрассил, їхня кількість різко впала. Жриці Елуни, як-от Ґвенніт Блай'Леґґонд, вивчають ці прибережні рештки для Храму Місяця, намагаючись з'ясувати, що жене цих лагідних велетнів на смерть — темна магія, мінливе море чи втрата давнього прихистку."}},faq={{q="Чому морські черепахи викидаються на берег Темного Узбережжя?",a="Точна причина лишається для нічних ельфів загадкою. Колись морські черепахи процвітали у водах під Світовим Деревом Нордрассіл. Після знищення Нордрассіла в Третій війні й вирощення Тельдрассилу їх стало значно менше, і багато з них, здається, навмисно закінчують життя на мілинах Темного Узбережжя.",al={"чому черепахи гинуть тут","таємниця черепах темного узбережжя","чому викинуло"}},{q="Хто така Ґвенніт Блай'Леґґонд?",a="Ґвенніт Блай'Леґґонд — учена нічних ельфів і представниця Храму Місяця в Обердайні. Їй доручено описувати й вивчати викинутих на берег морських істот, щоб з'ясувати, чому страждає природа Темного Узбережжя.",al={"хто така ґвенніт","куди здати рештки черепахи","дослідниця обердайна"}},{q="Чому довкола решток черепахи зібралися мурлоки?",a="Місцеві мурлоки Сірої Імли — пристосуванці, що обгризають величезні туші заради їжі й матеріалів. Вони часто ставлять свої прибережні поселення просто біля викинутих морських черепах та інших істот, щоб обдерти їх до кісток.",al={"чому мурлоки на черепасі","падальники сірої мли","табори мурлоків на пляжі"}},{q="Що пов'язує цих черепах із Нордрассілом?",a="За словами нічних ельфів, колись морські черепахи часто й весело хлюпалися в незайманих водах біля підніжжя Гори Гіджал і Світового Дерева Нордрассіл. Жорстоке знищення Нордрассіла глибоко порушило природну рівновагу, і відтоді цих істот бачать дедалі рідше.",al={"зв'язок з нордрассілом","черепахи гіялу","зв'язок черепах з горою гіял"}},{q="Чи має Тельдрассил стосунок до їхнього зникнення?",a="Жрецтво зауважує, що відколи виріс Тельдрассил, морських черепах бачать дедалі менше. Чи нове Світове Дерево змінило прибережні течії, порушило їхні міграції, чи має неприродну ауру, що впливає на морське життя, — це питання, яке активно досліджує Храм Місяця.",al={"вплив тельдрассила на черепах","чому тельдрассил змінив черепах"}},{q="Чи багато викинутих на берег істот на Темному Узбережжі?",a="Так. На довгому узбережжі Темного Узбережжя лежить чимало викинутих морських істот і черепах. Кожна туша дає унікальні зразки кісток і тканин, з яких Ґвенніт Блай'Леґґонд складає картину ширшого природного лиха, що розгортається на березі.",al={"ще завдання викинутих","інші викинуті черепахи","викинуті морські істоти"}}},fp="18,269,17.368.0,16.560.0,53.324.0,29.250.0,51.227.0,52.294.0,55.301.0,53.247.0"}
P.entries["quest:4733"] = {n="Морське створіння на березі",s="Серед скелястих заток Сутінкового Берега в прибої лежить колосальна туша велетенського молотильника. Значно більший за будь-які відомі місцеві екземпляри, він раптово загинув і опинився на мілині — ще одна ланка в тривожній низці глибоководних аномалій, що непокоять нічних ельфів Темного Узбережжя.",h="Серед скелястих заток Сутінкового Берега в прибої лежить колосальна туша велетенського молотильника.",kw={"морське створіння на березі","сутінковий берег","молотильник","ґвенніт блай'леґґонд","храм місяця","приховане море"},ang={["class:Druid"]="Викиди верховних морських хижаків — красномовна ознака природи в біді, що тісно перегукується з ширшими тривогами Кола Кенарія щодо всього Темного Узбережжя.",["class:Priest"]="Ґвенніт Блай'Леґґонд веде дослідження під егідою Храму Місяця, шукаючи рівноваги й божественного прозріння через відчутне наукове вивчення морського світу.",["race:NightElf"]="Незрозуміле зменшення й викиди морських створінь поблизу Тельдрассилу зачіпають за живе калдореїв, які покладаються на Елуну й Храм Місяця, щоб тлумачити такі темні знамення."},sec={{t="Велетень, викинутий на берег",b="Сутінковий Берег на півдні Темного Узбережжя часто всіяний плавником і морським мотлохом, але в цій затоці лежить дещо куди разючіше — рештки величезного молотильника. Хоч падальники й припливи вже почали розтягувати тушу, її масивний скелет значно перевершує будь-якого звичайного хижака з прибережних мілин. Це явно чужинець у цих водах, якого загнала на скелі протиприродна хвороба, втрата орієнтації чи якесь глибше збурення в Прихованому Морі."},{t="Пильність Храму",b="В Обердайні жриці, що представляють Храм Місяця, дуже зацікавилися мертвими велетнями, яких викидає на берег. Ґвенніт Блай'Леґґонд наглядає за збиранням кісткових зразків, щоб з'ясувати, що жене таких глибоководних хижаків на смерть. Колись колосальних молотильників бачили біля коріння Тельдрассилу, але їх ставало дедалі менше, і жриці побоюються, що крихка морська рівновага біля північного узбережжя Калімдору руйнується."}},faq={{q="Що це за звір лежить на березі?",a="Це кістяк величезного трешера — хижого морського звіра. Він у кілька разів більший за звичайних трешерів з узбережжя Темного Узбережжя, тож його поява тут — глибока аномалія.",al={"яка це тварина на березі","велетенська молотарка темного узбережжя","туша чудовиська"}},{q="Звідки ця істота взялася?",a="Жриця Ґвенніт Блай'Леґґонд зауважує, що звірів таких величезних розмірів колись бачили у водах біля Тельдрассилу, але їх стає дедалі менше. На мілинах Темного Узбережжя вони не водяться.",al={"де живуть гігантські молотарки","походження молотарки"}},{q="Чому Храм Місяця вивчає ці туші?",a="Храм Місяця прагне зрозуміти, чому на узбережжя Темного Узбережжя масово викидаються морські істоти. Оглядаючи кістки й рештки, жриці сподіваються з'ясувати, чи то скверна, хвороба, чи зовнішні сили виганяють глибоководних звірів на суходіл.",al={"чому храм місяця вивчає","навіщо ґвенніт кістки","навіщо вивчати викинутих тварин"}},{q="Куди нести кістки?",a="Кістки Морського Створіння треба принести Ґвенніт Блай'Леґґонд — дослідниці нічних ельфів у портовому містечку Обердайн.",al={"куди здати кістки морської істоти","хто бере кістки молотарки"}},{q="Де на узбережжі лежить ця туша?",a="Туша лежить у скелястій затоці на Сутінковому Березі — південній прибережній смузі Темного Узбережжя.",al={"де туша","місце молотарки темне узбережжя","скелет сутінкового узбережжя"}},{q="Чи викидаються на берег Темного Узбережжя інші істоти?",a="Так. По всьому узбережжю Темного Узбережжя викинуло кількох різних морських звірів і велетнів, і дослідники Обердайна продовжують розслідування.",al={"інші викинуті тварини","лінія завдань викинутих істот"}}},fp="20,278,19.481.0,18.480.1,43.199.0,45.229.0,55.260.0,34.124.0,43.101.0,59.173.0"}
P.entries["quest:4736"] = {n="У пошуках Менари Войдрендер",s="Це завдання посилає багатообіцяльних чорнокнижників Альянсу за море, у посушливі Пустки, на пошуки Менари Войдрендер. Працюючи у вежі Страгада Фарсана над Раджетом, Менара пропонує досвідченим знавцям темних мистецтв створити особливі знаряддя й вбрання, що посилять їхню владу над демонічними силами.",h="Це завдання посилає багатообіцяльних чорнокнижників Альянсу за море, у посушливі Пустки, на пошуки Менари...",kw={"менара войдрендер","браєрторн","страгад фарсан","раджет","чорнокнижник","альянс"},ang={["class:Warlock"]="Ця подорож — важливий обряд посвяти у вищі чари, що веде прямо до створення Зачарованої Золотої Кривавої Роби чорнокнижника.",["faction:Alliance"]="Щоб заглибитися в Пустки, доведеться пройти ворожими землями й покластися на хиткий нейтралітет Раджета, аби дістатися вежі Страгада.",["race:Gnome"]="Гномські чорнокнижники, що обачно стримували себе від магічної й демонічної скверни, побачать, що Менара цінує практичний контроль набагато більше, ніж теоретичні забавки.",["race:Human"]="Людським знавцям темних мистецтв, звиклим до прихованих культів Стормвінда й Айронфорджа, доведеться звикати до відносної відкритості відлюдної вершини над Раджетом."},sec={{t="Поклик з Айронфорджа",b="Браєрторн, спільник, що ховається в темніших закутках Айронфорджа, бачить, коли чорнокнижник переріс основи демонології, не піддавшись скверні. Замість того щоб тримати учнів замкненими під горою, він скеровує їх до Калімдору, хвалить їхню дисципліну й радить шукати науки в майстрині, куди вправнішої в практичному ремеслі Скверни."},{t="Прихисток над Раджетом",b="На кручах над гоблінським портом Раджет стоїть самотня вежа Страгада Фарсана. У світі, що глибоко підозріло ставиться до темних чарів, знавці Скверни часто відкидають расові й політичні кордони, щоб вижити. Саме тому Менара Войдрендер живе в притулку Страгада й працює з чорнокнижниками будь-якої приналежності, щоб їхнє небезпечне ремесло лишалося гострим, а викликані демони — надійно зв'язаними."}},faq={{q="Хто дає завдання «У пошуках Менари Войдрендер»?",a="Завдання дає Браєрторн, що діє в тіньовому підпіллі Айронфорджа й опікується чорнокнижниками Альянсу, які досягли достатньої вправності.",al={"хто дає завдання","місце брайєрсторна"}},{q="Де знайти Менару Войдрендер?",a="Менара Войдрендер мешкає у вежі Страгада Фарсана в Пустках, на кручах просто над гоблінським портовим містечком Раджет.",al={"місце менари войдрендер","де менара войдрендер","місце вежі страгада фарсана"}},{q="Чому чорнокнижникові Альянсу доводиться вирушати на землі Орди?",a="Чорнокнижники з потреби часто діють поза звичною вірністю фракціям. Раджет — нейтральний порт, яким керує картель Стімвідл, а вежа Страгада — відлюдний притулок, де ті, хто практикує заборонену магію, можуть збиратися й навчатися подалі від чужих очей.",al={"чому в пустки","чому подорож до ретчета","пустки небезпечні для альянсу"}},{q="Що пропонує Менара наприкінці?",a="Розмова з Менарою відкриває можливість створити могутнє вбрання чорнокнижника — починаючи із завдання зібрати складники для Зачарованої Золотої Кривавої Роби.",al={"чого вчить менара","нагорода завдання","наступне завдання після менари"}},{q="Менара Войдрендер — з Альянсу чи з Орди?",a="Менара Войдрендер ставиться до практиків темних мистецтв нейтрально, хоч би звідки вони були. Сувора й колюча, вона допомагає кожному вишколеному чорнокнижникові, що шукає її настанов.",al={"фракція менари","чи менара дружня"}},{q="Чому чорнокнижники об'єднуються попри расові межі?",a="Як зауважує Менара, демони, яких прикликають чорнокнижники, не розрізняють рас, коли б'ють у відповідь необережних заклиначів. Виживання й влада над Викривленим Нижнім Світом вимагають спільних знань і взаємовиручки, а не фракційних чвар.",al={"єдність чорнокнижників","чому чорнокнижники працюють разом"}}},fp="30,300,24.382.0,25.444.0,54.173.0,37.144.0,63.275.0,39.160.0,39.181.0,47.248.0"}
P.entries["quest:4737"] = {n="У пошуках Менари Войдрендер",s="Зеврост — цинічний наставник чорнокнижників, що причаївся в Тіньовій Розколині Оргріммара, — скеровує досвідчених учнів на пошуки Менари Войдрендер у Пустках. Хоч він і застерігає, що за демонічну скверну неминуче доведеться заплатити, все ж вказує амбітним чорнокнижникам на вправну наставницю, яка вміє створювати могутні магічні шати.",h="Зеврост — цинічний наставник чорнокнижників, що причаївся в Тіньовій Розколині Оргріммара, — скеровує...",kw={"чорнокнижник","менара войдрендер","зеврост","зачарована золота кривава роба","тіньова розколина","раджет","скверна"},ang={["class:Warlock"]="Це завдання — ключовий обряд посвяти для чорнокнижників Орди: під проводом Менари Войдрендер ви створите власну знамениту Зачаровану Золоту Криваву Робу.",["faction:Horde"]="Чорнокнижникам Орди доводиться постійно зносити зневагу шаманів і воїнів старого гарту, а прихисток вони знаходять лише в потаємних закутках на кшталт Тіньової Розколини Оргріммара чи на нейтральній землі біля Раджета."},sec={{t="Застереження в тінях",b="Глибоко під Оргріммаром, у Тіньовій Розколині, чорнокнижники живуть під покровом непевної терпимості. Зеврост — один із найжовчніших наставників темних мистецтв, він охоче глузує з амбітних послушників, що прагнуть майстерності. На його думку, кожен, хто заглиблюється в магію Скверни, лише мчить назустріч власному поневоленню. Він запевняє, що демонічна залежність рано чи пізно цілком опанує чаклуна, і навіть найдисциплінованіший учений стане рабом Викривленого Нижнього Світу."},{t="Шлях до Раджета",b="Попри свої зневажливі пророцтва, Зеврост визнає, що інші чаклуни не поділяють його похмурих поглядів. До Оргріммара дійшли чутки про Менару Войдрендер — вправну чорнокнижницю, що оселилася на кручах над нейтральним гоблінським портом Раджет. Менара шукає здібних учнів, які допоможуть їй виготовити особливі знаряддя, щоб приборкати їхню магічну силу. Для чорнокнижників, які прагнуть удосконалити своє мистецтво, цей поклик стає початком створення легендарної Зачарованої Золотої Кривавої Роби."},{t="Братство з розрахунку",b="Коли мандрівник знаходить Менару високо над Раджетом, справжня природа товариства чорнокнижників постає перед ним у всій повноті. Менара зауважує, що чорнокнижники мусять відкинути расові й культурні чвари та підтримувати одне одного, адже демони, з якими вони укладають угоди, не знають упереджень і не мають жалю до того, хто оступився. Обмін знаннями й виготовлення захисних шат — не шляхетна благодійність, а практична потреба, без якої не вижити серед ворожих сутностей, яких вони прив'язують до своєї служби."}},faq={{q="Хто такий Зеврост?",a="Зеврост — орк, наставник чорнокнижників, що мешкає в Тіньовій Розколині під Оргріммаром. Він украй цинічно ставиться до гонитви за силою скверни й вважає всіх честолюбних чорнокнижників дурнями, приреченими стати рабами демонічного розтління.",al={"зеврост","зеврост лор","хто починає пошуки менари"}},{q="Хто така Менара Войдрендер?",a="Менара Войдрендер — досвідчена чорнокнижниця, що мешкає в Пустках на скелях над гоблінським портом Раджет. Вона наставляє чорнокнижників-початківців, допомагаючи їм збирати рідкісні реагенти для могутніх обрядових роб.",al={"менара войдрендер","де менара войдрендер","хто така менара"}},{q="Чому Зеврост вважає всіх чорнокнижників дурнями?",a="Зеврост переконаний, що магія скверни неминуче розтліває й поневолює кожного, хто намагається нею опанувати. На його думку, жоден практик не має волі уникнути залежності, а гонитва за більшою силою лише пришвидшує падіння.",al={"скверна зеврост","чому зеврост застерігає"}},{q="Де знайти Менару Войдрендер?",a="Менара перебуває в Пустках, на високих пагорбах над прибережним портом Раджет. Чорнокнижникам треба перетнути посушливу савану на схід, щоб дістатися її табору на висоті.",al={"місце менари","знайти менару войдрендер"}},{q="Чому чорнокнижники різних рас працюють разом?",a="Як пояснює Менара, демонічні сили, яких прикликають чорнокнижники, однаково жорстокі до кожного, хто не зміг їх приборкати. Оскільки виживання залежить від бездоганної точності, чорнокнижники раз у раз діляться знаннями й знаряддями попри культурні межі.",al={"солідарність чорнокнижників","чому чорнокнижники гуртуються"}},{q="Що буде, коли знайти Менару Войдрендер?",a="Менара Войдрендер одразу доручає чорнокнижникові зібрати по всьому Азероту рідкісні й могутні матеріали, щоб створити Зачаровану Золоту Криваву Робу — захисне вбрання, налаштоване на енергію скверни.",al={"наступне завдання після менари","чого хоче менара"}}},fp="30,330,23.500.0,19.489.0,22.464.0,15.230.0,25.236.0,46.226.0,37.187.0,51.252.0,45.191.0"}
P.entries["quest:4738"] = {n="У пошуках Менари Войдрендер",s="Чорнокнижника Альянсу, що прагне створити могутнє вбрання, приховані знавці темних мистецтв із Кварталу магів посилають за Велике море шукати Менару Войдрендер. Розташувавшись високо над нейтральним портом Раджет, Менара навчає темних заклиначів по обидва боки фракційних кордонів небезпечного мистецтва зв'язування й створення артефактів.",h="Чорнокнижника Альянсу, що прагне створити могутнє вбрання, приховані знавці темних мистецтв із Кварталу магів...",kw={"менара войдрендер","демізетт клойс","квартал магів","раджет","чорнокнижник","стормвінд"},ang={["class:Warlock"]="Цей обряд посвяти поєднує приховані нори Стормвінда з відкритими рубежами Калімдору й учить, що прагнення влади над демонами стоїть понад смертними фракціями.",["faction:Alliance"]="Ця подорож змушує заклиначів Альянсу покинути звичні східні землі й вирушити в дику глушину Пусток по особливу науку."},sec={{t="Неохоча рекомендація",b="У темних склепах під «Зарізаним Ягням» у Стормвінді наставниця чорнокнижників Демізетт Клойс славиться суворими, безжальними вимогами. Коли молодий чорнокнижник підходить до порогу створення значущих речей сили, Демізетт рідко вірить, що він справді готовий. Проте вище керівництво кабали велить учневі рухатися далі й посилає його далеко від безпечної столиці, щоб він довів свій гарт."},{t="Вежа над Раджетом",b="Мета — посушливі пагорби над гоблінським портом Раджет у Пустках. Там, у кам'яній вежі, Менара Войдрендер тримає свою лабораторію. Далеко від суворих законів Стормвінда й пильних очей Оргріммара, Менара бере учнів незалежно від раси чи політичної приналежності, знаючи, що демони й потойбічні сутності, з якими мають справу чорнокнижники, однаково ненавидять кожну смертну душу."}},faq={{q="Чому чорнокнижника Альянсу посилають аж до Пусток?",a="Мало хто в Альянсі має тайні знання чи свободу, щоб створювати складне вбрання скверни на кшталт Зачарованої Золотої Кривавої Роби. Менара Войдрендер працює у відлюдній вежі над нейтральним портом Раджет — рідкісному притулку, де чорнокнижники будь-якого походження можуть вивчати небезпечні ремесла подалі від столичної варти й інквізиторів.",al={"чому ретчет","чому в пустки","чому менара войдрендер"}},{q="Хто така Демізетт Клойс?",a="Демізетт Клойс — старша наставниця чорнокнижників-людей, що таємно діє під «Зарізаним Ягням» у Кварталі магів Стормвінда. Сувора й ревна охоронниця небезпечних знань, вона посилає учнів до Менари лише з наказу невидимих сил, що спрямовують спільноту чорнокнижників.",al={"лор демізетт клойс","хто починає пошуки менари"}},{q="Чи переймається Менара Войдрендер протистоянням Альянсу й Орди?",a="Ні. Менара відверто пояснює, що чорнокнижники мусять дивитися поверх расових і фракційних меж. Демони й потойбічні сили, яких вони прикликають, однаково люті до кожного, хто схибить, тож спільне виживання й спільні темні мистецтва набагато важливіші за смертні війни.",al={"менара орда чи альянс","чи менара ненавидить альянс"}},{q="Яку річ Менара Войдрендер допомагає створити?",a="Дістатися Менари — перший крок до того, щоб перетворити Мантію Тайн на легендарну Зачаровану Золоту Криваву Робу — могутнє вбрання, просякнуте рідкісними реагентами, майстерним кравецтвом і скутою демонічною енергією.",al={"чого вчить менара","яка роба","завдання крові-роби"}},{q="Чи небезпечна подорож до Раджета для чорнокнижника Альянсу?",a="Пустки — переважно земля Орди, де повно ворожих звірів, кентаврів і патрулів орків. Але сам Раджет — нейтральний порт картелю Стімвідл, тож до вежі Менари можна дістатися, якщо мандрівник з Альянсу триматиметься узбережжя чи безпечно припливе кораблем із Буті Бей.",al={"наскільки небезпечний ретчет","чи пустки безпечні"}},{q="Чому Демізетт Клойс вважає, що гравець не готовий?",a="Демізетт вважає, що створювати речі, просякнуті скверною, — безрозсудство для неперевірених новачків. Артефакти чорнокнижників вимагають суворої дисципліни: найменша помилка у скріпленні реагентів чи демонічних есенцій може знищити самого практика або випустити у світ жахіття.",al={"чому демізетт сумнівається","застереження демізетт"}}},fp="30,323,26.438.0,23.419.0,59.366.0,24.286.0,65.253.0,61.198.0,58.290.0,55.248.0"}
P.entries["quest:4739"] = {n="У пошуках Менари Войдрендер",s="Це завдання посилає багатообіцяльних чорнокнижників Орди з темних кварталів Андерсіті за море, до Раджета. На пагорбі над портом наставниця Менара Войдрендер чекає на тих, хто готовий створити могутнє магічне вбрання.",h="Це завдання посилає багатообіцяльних чорнокнижників Орди з темних кварталів Андерсіті за море, до Раджета.",kw={"менара войдрендер","каал соулріпер","андерсіті","раджет","чорнокнижник","орда"},ang={["class:Warlock"]="Ця подорож знаменує перехід чорнокнижника до вищої практики й відкриває шлях до створення особливого вбрання, налаштованого на енергії Нижнього Світу.",["faction:Horde"]="Це завдання показує, як розрізнені чорнокнижницькі угруповання Орди підтримують підпільну мережу, що охоплює і Лордерон, і Калімдор.",["race:Undead"]="Почавши в похмурих глибинах Андерсіті, чорнокнижники-Відступники мусять вирушити на вибілені сонцем пустища Калімдору, щоб продовжити свої таємні студії."},sec={{t="Поклик із тіні",b="У столиці Відступників, Андерсіті, Каал Соулріпер стежить, як зростає хист його учнів-чорнокнижників. Побачивши, що учень переріс прості прокльони й слуг-бісів, він радить йому шукати особливої науки за Великим морем. Мистецтво влади над демонами не терпить вагань, і лише вправні наставники можуть гарантувати, що чорнокнижник виживе перед мінливими силами Нижнього Світу."},{t="Вежа над Раджетом",b="На високій кручі над гоблінським портом Раджет стоїть вежа Страгада Фарсана. Тут, далеко від суворого ока міської варти, знавці на кшталт Менари Войдрендер збираються, щоб навчати молодших новачків. Чорнокнижники різного походження відкладають племінну й політичну ворожнечу перед суворою правдою свого ремесла: демони, з якими вони торгуються, без жодних упереджень пожеруть і людину, і орка, і Відступника, щойно їхня воля похитнеться."}},faq={{q="Хто дає це завдання?",a="Це завдання дає Каал Соулріпер в Андерсіті. Він бачить, коли чорнокнижник набув досить сили й досвіду, щоб скористатися глибшою наукою Менари Войдрендер.",al={"хто дає завдання","де взяти завдання","місце каала соулрипера"}},{q="Де знайти Менару Войдрендер?",a="Менара мешкає в Пустках, у кам'яній вежі над портовим містечком Раджет, разом зі Страгадом Фарсаном.",al={"де менара","знайти менару войдрендер","місце менари"}},{q="Чому чорнокнижникам Орди доводиться вирушати аж до Пусток?",a="Демонічні мистецтва практикують у відлюдних осередках, де ніхто не втрутиться. Менара Войдрендер навчає й шиє особливі роби у вежі Страгада, де чорнокнижники будь-якого походження вчаться без утручання міської чи церковної влади.",al={"чому ретчет","чому подорож у пустки","чому йти до менари"}},{q="Що буде, коли дістатися Менари Войдрендер?",a="Менара визнає вашу вправність і пропонує допомогти створити Зачаровану Золоту Криваву Робу — так починається ланцюжок завдань, де треба зібрати рідкісні й небезпечні складники по всьому Азероту.",al={"продовження завдання","що дає менара","наступне завдання"}},{q="Чому чорнокнижники різних рас діляться знаннями?",a="Як пояснює Менара, демони не знають жалю й не дивляться на расу, якщо заклинач не зміг їх приборкати. Практична потреба виживати змушує чорнокнижників ділитися прийомами й берегти своє ремесло від спільної катастрофи.",al={"співпраця чорнокнижників","чому чорнокнижники працюють разом","лор чорнокнижників менари"}},{q="Хто такий Страгад Фарсан?",a="Страгад Фарсан — майстер-чорнокнижник, що утримує віддалену кам'яну вежу над Раджетом як притулок і навчальний осередок для тих, хто прагне опанувати демонічні мистецтва подалі від великих твердинь фракцій.",al={"вежа страгада","чия вежа в ретчеті","страгад фарсан"}}},fp="30,231,26.422.0,23.444.0,22.180.0,37.121.0,58.271.0,46.182.0,51.225.0,22.216.0"}
P.entries["quest:474"] = {n="Здолай Нек'роша",s="«Здолай Нек'роша» — кульмінація кампанії Альянсу проти клану Драконячої Пащі в Багнокраї. Коли облогові машини зіпсовано, шукачам пригод наказано власноруч повалити Вождя Нек'роша, щоб убезпечити Гавань Менетіл. Принесена Капітанові Стаутфісту відтята голова вождя ламає загрозу орків для прибережного порту.",h="«Здолай Нек'роша» — кульмінація кампанії Альянсу проти клану Драконячої Пащі в Багнокраї.",kw={"здолай нек'роша","вождь нек'рош","драконяча паща","капітан стаутфіст","гавань менетіл","багнокрай"},ang={["class:Warrior"]="Зійтися з Вождем Нек'рошем у його ж укріпленому бойовому таборі — найвище випробування бойової стійкості проти одного з найлютіших орківських командирів боліт.",["faction:Alliance"]="Безпека Гавані Менетіл захищає головну морську артерію, що пов'язує Айронфордж і Стормвінд із Калімдором і північними водами.",["race:Dwarf"]="Для дворфів Каз Модану Драконяча Паща — незагоєний шрам на кордонах предків. Знищення Нек'роша прямо оберігає дворфійські дороги й західну морську торгівлю Айронфорджа."},sec={{t="Обезголовити Драконячу Пащу",b="Орки Драконячої Пащі здавна терзають болота Каз Модану, окопавшись в укріплених таборах і загрожуючи морським шляхам Гавані Менетіл. Знайшовши й спаливши катапульти клану, захисники боліт б'ють просто в голову змії. Вождь Нек'рош, командир місцевого бойового загону, — остання перепона на шляху до прориву облоги. Його смерть позбавить решту загонів Драконячої Пащі злагодженого проводу."},{t="Безпека гавані",b="Принесена Капітанові Стаутфісту в Гавань Менетіл відтята голова Нек'роша — величезна перемога для гарнізону Айронфорджа. Позбавлена і важкої облогової зброї, і свого вождя, Драконяча Паща дістає удар, від якого навряд чи швидко оговтається. Для обложеного порту, що є головною артерією Альянсу між Лордероном і Каз Моданом, загибель вождя означає, що причали й торгові кораблі вбезпечено від раптового нападу."}},faq={{q="Хто такий Нек'рош?",a="Нек'рош — безжальний вождь решток клану Драконячої Пащі в Багнокраї. Зі своїх таборів він готував напад на Гавань Менетіл з облоговими катапультами, доки не втрутилися шукачі пригод Альянсу.",al={"вождь нек'рош","хто такий нек'рош","нек'рош вологі землі"}},{q="Чому Гавань Менетіл хоче смерті Нек'роша?",a="Нек'рош становив пряму загрозу самому існуванню Гавані Менетіл. Під його проводом Драконяча Паща будувала бойові катапульти, щоб обстрілювати порт і перерізати життєво важливі морські шляхи між Каз Моданом та іншими землями Альянсу.",al={"чому вбити нек'роша","мотиви стаутфіста"}},{q="Хто наказує вбити Нек'роша?",a="Наказ з'являється одразу після того, як ви підпалите катапульти Драконячої Пащі. Відрубану голову вождя зрештою доставляють Капітанові Стаутфісту, що командує обороною Гавані Менетіл.",al={"хто дає здолай нек'роша","куди здати голову нек'роша"}},{q="Що стається з кланом Драконячої Пащі після поразки Нек'роша?",a="Коли катапульти знищено, а вождя вбито, загін Драконячої Пащі втрачає провід і бойовий дух. Окремі недобитки ще никають болотами, але їхній наступ на Гавань Менетіл фактично розгромлено.",al={"драконяча паща після нек'роша","що буде з орками вологих земель"}},{q="Що клан Драконячої Пащі робить у Багнокраї?",a="Клан Драконячої Пащі осів у Багнокраї й сусідніх нагір'ях Ґрім Батолу ще під час Другої війни. Після поразки Орди рештки ренегатів лишилися на болотах, грабуючи торгові шляхи й плекаючи глибоку ненависть до Альянсу й дворфів Каз Модану.",al={"чому драконяча паща у вологих землях","лор драконячої пащі вологих земель"}},{q="Чому Гавань Менетіл така важлива для Альянсу?",a="Гавань Менетіл — єдиний великий морський порт королівства Айронфордж на західному узбережжі. Це головний вузол, звідки перевозять війська, товари й мандрівників через Велике Море до Калімдору й на північ, до Лордерона.",al={"важливість менетілу","стратегічна цінність менетілу"}}},fp="15,336,26.471.0,19.468.0,16.242.0,44.242.0,33.211.0,62.248.1,49.273.0,50.224.0"}
P.entries["quest:4740"] = {n="РОЗШУКУЄТЬСЯ: Муркдіп!",s="«РОЗШУКУЄТЬСЯ: Муркдіп!» — оголошення Альянсу про винагороду, вивішене на дошці біля заїзду в Обердайні. Рада селища вимагає смерті Каламутноглиба — небезпечного ватажка мурлоків, якого звинувачують у вбивстві Вартової нічних ельфів і потопленні торговельних суден біля Темного Узбережжя. Шукачі пригод мусять рушити на південь оповитим імлою узбережжям, виманити розбійника й вершити правосуддя.",h="«РОЗШУКУЄТЬСЯ: Муркдіп!» — оголошення Альянсу про винагороду, вивішене на дошці біля заїзду в Обердайні.",kw={"муркдіп","каламутноглиб","розшукується","обердайн","мурлоки","темне узбережжя"},ang={["faction:Alliance"]="Обердайн — важливий північний торговельний вузол, тож потоплення вантажних кораблів, у якому підозрюють Каламутноглиба, — дошкульний удар по постачанню Альянсу в Калімдорі.",["race:NightElf"]="Для калдореїв, що боронять Темне Узбережжя, смерть Каламутноглиба — це помста за полеглу сестру з Вартових і захист крихкої життєвої артерії, якою є пристані Обердайна."},sec={{t="Загроза на оповитих імлою мілинах",b="Мурлоків Сірої Імли на березі Темного Узбережжя зазвичай вважають просто докукою, але Каламутноглиб перетворив усе на відкриту війну з Обердайном. Згідно з оголошенням про розшук біля міського заїзду, лютий звір безпосередньо винен у загибелі щонайменше однієї Вартової нічних ельфів, а ще його підозрюють у тому, що він пошкодив чи потопив два вантажні судна в прибережних водах. Через дедалі більші морські втрати й набіги на узбережжя Рада селища Обердайн оголосила публічну винагороду, щоб покласти край розлюченому ватажкові мурлоків."},{t="Засідка біля хатин",b="Каламутноглиб не блукає відкритим берегом без діла. Він чатує біля південного узбережжя, коло купки мурлоцьких хатин довкола вогнища. Кожен, хто вдереться до табору, наштовхнеться на злагоджену оборону: хвилі берегобіжців і прибережних повзунів Сірої Імли вириваються з прибою, щоб захистити поселення, а тоді й сам Каламутноглиб виходить зі своїм авангардом, щоб розправитися з непроханими гостями."},{t="Правосуддя за полеглих",b="Повернення до Обердайна з доказом смерті Каламутноглиба — сумна, але необхідна справа для Вартових. Вартова Ґлінда Нал'Шея виплачує винагороду від імені ради. Коли верхівку мурлоків Сірої Імли знищено, мандрівники й кораблі, що йдуть крізь туман Темного Узбережжя, дістають перепочинок від прибережних диверсій."}},faq={{q="Де взяти завдання на винагороду за Муркдіпа?",a="Завдання можна взяти з оголошення про розшук біля заїзду в центрі Обердайна на Темному Узбережжі.",al={"де взяти муркдіпа","початок муркдіпа","плакат розшукується обердайн"}},{q="Чому рада Обердайна призначила винагороду за Муркдіпа?",a="Муркдіп — особливо лютий мурлок, що вбив щонайменше одну вартову нічних ельфів і, як підозрюють, затопив два вантажні судна біля берегів Темного Узбережжя.",al={"чому вбити муркдіпа","що зробив муркдіп","злочини муркдіпа"}},{q="Де знайти Муркдіпа?",a="Муркдіп — далеко на південь від Обердайна на пляжі, де він стереже три мурлочі хижки довкола вогнища.",al={"місце муркдіпа","де муркдіп","табір муркдіпа"}},{q="Чому Муркдіпа немає в мурлочому таборі, коли я приходжу?",a="Муркдіп не стоїть на видноті. Коли ступиш між хижками біля вогнища, з океану хвилями виходять мурлоки Сірої Імли. Муркдіп з'являється з останньою хвилею, коли перших захисників перебито.",al={"муркдіпа немає","поява муркдіпа","як викликати муркдіпа"}},{q="Кому здати завдання, коли Муркдіп мертвий?",a="Доповідайте про смерть Муркдіпа Вартовій Ґлінді Нал'Шеї, що несе службу в Обердайні.",al={"кому здати муркдіпа","здати завдання муркдіпа","місце глінди налші"}},{q="Чи відрізняються мурлоки в цьому таборі від інших мурлоків Темного Узбережжя?",a="Муркдіп командує мурлоками з племені Сірої Імли — зокрема прибережними розвідниками й воїнами, що злагодженими хвилями захищають свій табір біля моря.",al={"мурлоки сірої мли","плем'я муркдіпа","які мурлоки з муркдіпом"}}},fp="17,361,36.540.0,22.387.0,22.324.0,42.117.0,59.168.0,26.134.0,52.218.0,45.96.0,71.160.0"}
P.entries["quest:475"] = {n="Тривожний вітер",s="«Тривожний вітер» — раннє завдання від Атрідаса Бермантла в Тельдрассилі: з'ясувати, чому припинилися звістки із Села Зоряного Вітерця. Великий Наглядач Ґеролас Талветрен стереже неподалік Друїдів Кігтя, що сплять у зимовому сні, і його раптове мовчання підказує, що Світовим Деревом повзе неприродна небезпека.",h="«Тривожний вітер» — раннє завдання від Атрідаса Бермантла в Тельдрассилі: з'ясувати, чому припинилися звістки...",kw={"тривожний вітер","атрідас бермантл","ґеролас талветрен","село зоряного вітерця","друїди кігтя","тельдрассил"},ang={["class:Druid"]="Друїди з глибоким трепетом ставляться до Курганного Лігва Бан'етіл і сплячих, пов'язаних з Ізерою, тож будь-яка загроза їхнім наглядачам — нагальна особиста справа.",["race:NightElf"]="Для нічних ельфів охорона священного спочинку Друїдів Кігтя — запорука збереження тонкої рівноваги їхньої нової домівки на Тельдрассилі."},sec={{t="Мовчазний вартівник",b="У поселеннях на гіллі Тельдрассила звістки зазвичай ходять швидко й розмірено. Атрідас Бермантл покладається на вісті від Ґероласа Талветрена — Великого Наглядача, якому довірено пильнувати Друїдів Кігтя, що спочивають у Курганному Лігві Бан'етіл. Ці сплячі друїди підтримують священну угоду з Ізерою у Смарагдовому Сні, тож їхнє святилище життєво важливе для духовної рівноваги молодого Світового Дерева. Коли звістки зі сходу урвалися, лісовою кроною розлилося тривожне передчуття."},{t="Неспокій у Зоряному Вітерці",b="Атрідас просить мандрівників вирушити лісом на схід, до Села Зоряного Вітерця, і розшукати Ґероласа особисто. Відсутність гінців — не просто недогляд: у хащах заворушилися мерзенне зіпсуття й збурена живність. Діставшись Ґероласа, ви переконуєтеся, що чуття Атрідаса не підвело: на село впало лихо, яке загрожує безпеці сусідніх курганних лігв."}},faq={{q="Хто такий Атрідас Бермантл?",a="Атрідас Бермантл — визначний наглядач нічних ельфів на Тельдрассилі, що пильнує добробут лісу й стежить, щоб ніщо не тривожило притулків його сплячих братів-друїдів.",al={"атрідас бермантл","лор атрідаса","хто дає атрідас"}},{q="Хто такий Ґеролас Талветрен?",a="Ґеролас Талветрен — Великий Охоронець, обраний захищати сплячих Друїдів Кігтя в сусідньому Курганному Лігві Бан'етіл, поки їхні духи блукають Смарагдовим Сном.",al={"ґеролас талветрен","великий вартовий ґеролас","хто такий ґеролас"}},{q="Що таке Курганне Лігво Бан'етіл?",a="Курганне Лігво Бан'етіл — священна підземна печера на Тельдрассилі, де друїди нічних ельфів довго сплять, щоб спілкуватися з Ізерою й виконувати свої угоди в Смарагдовому Сні.",al={"курганне лігво бан'етіл","бан'етіл","що таке бан'етіл"}},{q="Чому Ґеролас не виходив на зв'язок?",a="Ґеролас не міг надсилати звичні донесення, бо Селу Зоряного Вітерця й довколишньому лісу раптом загрозили небезпека й скверна, і він опинився в боротьбі за те, щоб утримати становище.",al={"чому ґеролас мовчав","що сталося з ґероласом","біда в зоряному вітерці"}},{q="Куди веде це завдання далі?",a="Знайдений у Селі Зоряного Вітерця Ґеролас Талветрен відсилає вас назад до Атрідаса Бермантла в Доланаар із тяжкою звісткою про сусідніх фурболгів-Вузлошкірів, яких здолала неприродна скверна, що шириться довкола.",al={"наступне завдання","продовження тривожного вітру","що після тривожного вітру"}},{q="Що за угода з Ізерою, про яку йдеться в завданні?",a="Друїди нічних ельфів поринають у тривалий медитативний сон, щоб блукати Смарагдовим Сном разом із зеленими драконами та Ізерою, оберігаючи незайманий первісний задум природи.",al={"угода з ізерою","друїдська угода ізери","друїди кігтя сплять"}}},fp="18,302,16.513.0,20.392.1,27.190.0,27.198.0,33.181.0,32.200.0,32.215.1,51.177.0"}
P.entries["quest:476"] = {n="Зіпсуття Вузлошкірів",s="«Зіпсуття Вузлошкірів» — нагальне кур'єрське завдання в Тельдрассилі від імені пораненого Великого Наглядача Ґероласа Талветрена. Воно попереджає проводирів нічних ельфів у Доланаарі, що фурболґи Вузлошкіри піддалися демонічному зіпсуттю й захопили Село Зоряного Вітерця. Ця доповідь готує ґрунт для військового й друїдського втручання, щоб скверна не дісталася сплячих друїдів Курганного Лігва Бан'етіл.",h="«Зіпсуття Вузлошкірів» — нагальне кур'єрське завдання в Тельдрассилі від імені пораненого Великого Наглядача...",kw={"зіпсуття вузлошкірів","ґеролас талветрен","атрідас бермантл","урсал гамаїло","мох скверни","село зоряного вітерця","доланаар"},ang={["class:Druid"]="Загроза Курганному Лігву Бан'етіл — питання життя й смерті для Кола Кенарія, адже сплячі брати беззахисні перед зіпсутим плем'ям Вузлошкірів.",["race:NightElf"]="Падіння Села Зоряного Вітерця — трагічне потрясіння: воно доводить, що навіть щойно вирощене Світове Дерево вже вразливе до демонічної скверни, яку нічні ельфи так тяжко викорінювали."},sec={{t="Відчайдушне попередження",b="Ґеролас Талветрен лежить тяжко поранений біля руїн Села Зоряного Вітерця: на нього напали з засідки колишні союзники. Фурболґи Вузлошкіри, яких довго мали за мирних сусідів і опікунів дикої природи, раптово здичавіли. Надто скалічений, щоб самому донести звістку до своїх, Ґеролас довіряє шукачеві пригод чимшвидше передати слово Атрідасові Бермантлу в Доланаар, поки безумство не розповзлося гіллям Тельдрассила ще далі."},{t="Пошесть Моху Скверни",b="Доповідь, доставлена Атрідасові, відкриває тривожну правду: фурболґи не просто стали неспокійними — їх навмисне піддають магії Скверни. Їхній вождь Урсал Гамаїло приборкав зіпсутий Мох Скверни, що гноїться у Світовому Дереві, і ввергнув своє плем'я в кривавий шал. Це відкриття загрожує не лише поселенням на кшталт Зоряного Вітерця — воно безпосередньо ставить під удар сусіднє Курганне Лігво Бан'етіл, де сплячі друїди цілком беззахисні перед знавіснілим плем'ям."}},faq={{q="Що сталося із Селом Зоряного Вітерця?",a="Село Зоряного Вітерця захопили й пограбували фурболги-Вузлошкіри, коли їх зіпсувала магія скверни. Раптовий напад вигнав або вирізав мешканців, а Ґеролас Талветрен опинився в пастці, поранений.",al={"чому зоряний вітерець покинутий","напад на зоряний вітерець","хто знищив зоряний вітерець"}},{q="Чому фурболги-Вузлошкіри стали жорстокими?",a="Їхній вождь, Урсал Гамаїло, почав орудувати злою силою Моху Скверни, знайденого на Тельдрассилі. Темна магічна есенція довела плем'я до неконтрольованого шаленства проти колишніх союзників — нічних ельфів.",al={"чому вузлошкіри жорстокі","божевілля вузлошкірів","чому фурболги нападають"}},{q="Хто такий Ґеролас Талветрен?",a="Ґеролас Талветрен — Великий Охоронець сплячих Друїдів Кігтя з нічних ельфів, на якого напало плем'я Вузлошкірів, коли він ішов до Курганного Лігва Бан'етіл. Надто поранений, щоб дійти до Доланаару, він покладається на мандрівників, щоб ті передали звістку про лихо.",al={"ґеролас","поранений нічний ельф зоряного вітерця"}},{q="Хто такий Атрідас Бермантл?",a="Атрідас Бермантл — впливовий провідник нічних ельфів у Доланаарі. Він відповідає за безпеку краю й допомагає організувати відсіч новим загрозам для Світового Дерева та його мешканців.",al={"атрідас","атрідас бермантл доланаар"}},{q="Чому нічні ельфи тривожаться за Курганне Лігво Бан'етіл?",a="У Курганному Лігві Бан'етіл сплять численні друїди, глибоко занурені в Смарагдовий Сон. Якщо шалені фурболги-Вузлошкіри дістануться курганів, сплячі нічні ельфи будуть цілком беззахисні перед їхнім нападом.",al={"загроза бан'етіл","чому важливе лігво бан'етіл","небезпека сплячих друїдів"}},{q="Що таке Мох Скверни?",a="Мох Скверни — зіпсована органічна поросль, що з'являється на Тельдрассилі, просякнута темною демонічною енергією. Її згубний вплив зводить із розуму місцевих звірів і фурболгів, які до неї торкаються чи нею орудують.",al={"що таке мох скверни","мох скверни тельдрассил"}}},fp="20,418,19.457.0,23.506.1,36.218.0,47.226.0,27.272.0,27.205.0,59.211.0,17.186.0"}
P.entries["quest:4761"] = {n="Тундріс Віндвівер",s="«Тундріс Віндвівер» — завдання Альянсу, що пов'язує розвідку друїда Терентіса серед місцевих фурболгів із проводом Обердайна. Підтвердивши, що сусіднє плем'я Чорнолісся стає дедалі агресивнішим, шукачі пригод мають доповісти безпосередньо старійшині Віндвіверу. Старійшина прагне з'ясувати корінні причини порчі, що спотворює нетрі Темного Узбережжя.",h="«Тундріс Віндвівер» — завдання Альянсу, що пов'язує розвідку друїда Терентіса серед місцевих фурболгів із...",kw={"тундріс віндвівер","терентіс","фурболги чорнолісся","обердайн","старійшина","порча"},ang={["class:Druid"]="Стрімке спотворення місцевих фурболгів і лісових мешканців свідчить про тяжке порушення природної рівноваги, яке не можуть ігнорувати ні союзники Кола Кенарія, ні старійшини селища.",["faction:Alliance"]="Убезпечити Обердайн від ворожих лісових племен украй важливо для безпеки шляхів постачання Альянсу й мандрівників між Калімдором і Тельдрассилом.",["race:NightElf"]="Обердайн — головний порт і опора калдореїв на материковому узбережжі; приносячи відомості старійшині Віндвіверу, ви безпосередньо допомагаєте своєму народові берегти священні нетрі."},sec={{t="Донесення старійшині",b="Після вашої розвідки в зіпсованих таборах фурболгів на Темному Узбережжі друїд Терентіс посилає вас до старійшини селища Обердайн — Тундріса Віндвівера. Поки Терентіс розслідує порчу, що шириться нетрями, Тундріс опікується щоденним добробутом поселення й зважує ширші духовні та природні небезпеки, що загрожують калдореям. Ваше донесення дає проводу явний доказ: фурболги не просто боронять свою територію, а занепадають під дією протиприродної злоби."},{t="Порча на узбережжі",b="Отримавши звістку про табір фурболгів, Тундріс підтверджує, що Обердайн уже якийсь час потерпає від дедалі більшої ворожості місцевих лісових мешканців. Та тривожніша за саму агресію повзуча порча, що вражає ґрунт, рослини й води Темного Узбережжя. Вірячи, що зцілити землю можна, лише знайшовши джерело цієї пошесті, Тундріс береться простежити порчу вгору за течією й залучає здібних союзників дослідити водойми краю."}},faq={{q="Хто такий Тундріс Віндвівер?",a="Тундріс Віндвівер — старійшина Обердайна, мудрий управитель, що опікується врядуванням і щоденними справами містечка. Він тісно співпрацює з вартовими й друїдами, щоб зрозуміти дивну скверну, що шириться Темним Узбережжям, і побороти її.",al={"тундріс віндвівер","старійшина обердайна","хто такий тундріс"}},{q="Чому Терентіс посилає мене до Тундріса?",a="Розвідавши табори фурболгів Чорнолісся, Терентіс вирішує, що треба поінформувати провід містечка. Тундріс Віндвівер має свої здогади, чому звірі й фурболги божеволіють, і йому потрібні відомості з перших рук, щоб організувати відсіч.",al={"чому йти до тундріса","звіт терентіса","звіт обердайна"}},{q="Що відбувається з фурболгами Темного Узбережжя?",a="Місцеві фурболги Темного Узбережжя стають дедалі жорстокішими, піддаючись темній скверні, що спотворює сам ліс. Їхня ворожість — не прості прикордонні суперечки, а наслідок зловісної скверни, що отруює землю.",al={"осквернені фурболги","ворожість фурболгів","чому фурболги злі"}},{q="Куди веде це розслідування далі?",a="Старійшина Віндвівер підозрює, що джерело гнилі несуть води Темного Узбережжя. Він одразу посилає шукачів пригод узяти пробу з Річки Скельного Джерела, щоб з'ясувати, звідки береться забруднення.",al={"наступне завдання","що після тундріса","завдання кліфспрінг"}}},fp="19,387,21.513.0,26.490.0,27.244.0,40.267.0,47.232.0,40.208.0"}
P.entries["quest:4762"] = {n="Річка Кліффспрінг",s="Річка Скельного Джерела — велика водна артерія на півночі Темного Узбережжя, що стрімко псується й загрожує поселенню Обердайн. Тундріс Віндвівер доручає дослідникам Альянсу набрати пробу води під водоспадом біля річкового мосту, щоб підтвердити повзучу пошесть. Тундріс підозрює, що глибше джерело порчі лежить далеко за берегами річки.",h="Річка Скельного Джерела — велика водна артерія на півночі Темного Узбережжя, що стрімко псується й загрожує...",kw={"річка скельного джерела","тундріс віндвівер","сквернолісся","фурболги чорнолісся","край імли","обердайн"},ang={["class:Druid"]="Для друїдів Кола Кенарія бачити, як чисті лісові води смердять від демонічної скверни, — заклик до зброї, щоб очистити поранену природу Темного Узбережжя.",["race:NightElf"]="Обердайн залежить від рівноваги на берегах Темного Узбережжя, і якщо дати гнилі стекти до Краю Імли, під загрозою опиняться домівки й прожиток калдореїв."},sec={{t="Отруєна течія",b="Збігаючи зі східних височин, Річка Скельного Джерела впадає в прибережні мілини біля Краю Імли, трохи на північ від Обердайна. Останнім часом її води почали псуватися, несучи до поселення нічних ельфів протиприродну гниль. Боячись, що стоки отруять навколишні береги й запаси містечка, Тундріс Віндвівер посилає розвідників угору за течією, щоб набрати проби з озерця під водоспадом біля дорожнього мосту."},{t="Корінь у Скверноліссі",b="Місцеві фурболги Чорнолісся влаштували табори вздовж річки й виявляють ознаки тяжкого збурення, але Тундріс підозрює, що вони лише розносять порчу, справжній корінь якої лежить деінде. Він вказує на Сквернолісся як на джерело й передбачає, що проба підтвердить його підозру. Отруєний ліс на сході зазнав ран під час Третьої війни. Щоб очистити воду, доведеться зіткнутися зі зіпсованими фурболгами й очистити давні джерела краю."}},faq={{q="Де набрати пробу води?",a="Ідіть з Обердайна на північ до гирла Річки Скельного Джерела на Краю Імли. Підніміться річкою вглиб суходолу до першого водоспаду, що просто під дорожнім мостом, і наберіть пробу в пробірку з ковбані.",al={"де взяти воду","місце річки кліфспрінг","місце водоспаду"}},{q="Чому Річка Скельного Джерела псується?",a="Тундріс підозрює, що річку можуть отруювати фурболги Чорнолісся, які живуть на її берегах, але вважає, що їхня скверна має глибше коріння. Щоб розібратися, йому потрібна проба води.",al={"чому річка зіпсована","що отруює воду узбережжя","джерело скверни кліфспрінга"}},{q="Хто такий Тундріс Віндвівер?",a="Тундріс Віндвівер — учений і дослідник нічних ельфів з Обердайна. Він вивчає занепад природи, що шириться Темним Узбережжям, і намагається розгадати причини місцевої скверни.",al={"лор тундріса віндвівера","хто дає річку кліфспрінг"}},{q="Чи фурболги винні в отруєнні річки?",a="Тундріс підозрює, що скверну можуть поширювати вони, хоча вважає, що джерело їхньої зіпсутості лежить глибше. Проба води має допомогти йому це з'ясувати.",al={"чи фурболги отруїли воду","скверна фурболгів чорнолісся"}},{q="Як ця річка впливає на Обердайн?",a="Річка Скельного Джерела впадає в море на Краю Імли трохи на північ від містечка. Прибережні течії можуть понести смердючі стоки просто до берегів Обердайна, загрожуючи рибним промислам, рослинам і запасам прісної води.",al={"загроза обердайну","чому обердайн турбується"}},{q="Що буде, коли пробу перевірено?",a="Тундріс дякує вам за пробу й готується далі досліджувати зіпсованих фурболгів Чорнолісся, сподіваючись знайти спосіб очистити їх від скверни.",al={"завдання після річки кліфспрінг","що після річки кліфспрінг"}}},fp="21,357,18.431.0,19.459.1,36.229.0,42.179.1,27.198.0,53.164.1,37.223.0,38.149.1"}
P.entries["quest:4763"] = {n="Осквернене Чорнолісся",s="Ідучи за слідами, знайденими в отруєних водах Річки Скельного Джерела, Тундріс Віндвівер посилає шукачів пригод обірвати темний вплив, що душить плем'я Чорнолісся. Очистивши їхні харчі водою з місячного колодязя, ви виманите їхнього демонічного наглядача на відкрите місце й зламаєте його владу над північним табором.",h="Ідучи за слідами, знайденими в отруєних водах Річки Скельного Джерела, Тундріс Віндвівер посилає шукачів...",kw={"осквернене чорнолісся","ксабраксіс","тундріс віндвівер","фурболги чорнолісся","місячний колодязь","сатири"},ang={["class:Druid"]="Щоб відновити рівновагу, гниль треба вирізати з корінням. Сатир, що спотворює первісних лісових створінь талісманами Скверни, — привід для Кола Кенарія негайно зійтися з Ксабраксісом.",["class:Priest"]="Чиста, відновлювальна благодать Елуни, спрямована крізь воду місячного колодязя, — разючий контраст із тінню й магією Скверни, якими орудує сатир.",["race:NightElf"]="Фурболги були давніми союзниками калдореїв у Війні Прадавніх; бачити, як вони підпадають під владу одвічних ворогів — сатирів, — гірка трагедія, яку нічні ельфи прагнуть виправити."},sec={{t="Прихований господар",b="Нічні ельфи Обердайна довго не могли зрозуміти, чому колись мирні фурболги Чорнолісся так жорстоко обернулися проти сусідів. Розслідування на Річці Скельного Джерела привело до сатирів. Ці давні слуги Палаючого Легіону навмисно маніпулюють плем'ям, спрямовуючи магію Скверни через підступні талісмани, щоб викривити розум фурболгів і довести їх до звірячої люті."},{t="Розбити кайдани",b="Щоб виманити ляльковода на відкрите місце, Тундріс Віндвівер вигадує простий, але дієвий засіб. Якщо зібрати в північному поселенні Чорнолісся звичайні харчі — зерно, плоди й горіхи — і занурити їх у священну воду з місячного колодязя Обердайна, отруєна їжа очищується. Поклавши цю благословенну їжу біля центрального вогнища, можна дати сусіднім фурболгам короткий перепочинок від божевілля — і викрити сатира-розтлителя Ксабраксіса, який у люті виходить боронити своє спотворене панування."}},faq={{q="Чому фурболги Чорнолісся агресивні?",a="Їхній розум отруєно демонічним впливом. Сатири потай засіли біля таборів і спрямовують мерзенну магію крізь зачаровані талісмани, перетворюючи природні інстинкти фурболгів на скажену жорстокість.",al={"чому фурболги злі","чому фурболги ворожі","агресія чорнолісся"}},{q="Хто такий Ксабраксіс?",a="Ксабраксіс — сатир-розтлівач, що наглядає за північним табором фурболгів Чорнолісся. Він діє з тіні, щоб плем'я й далі було в полоні шаленства скверни, і тримає свою владу завдяки Талісману Псування.",al={"лор ксабраксіса","хто такий сатир","бос сатир узбережжя"}},{q="Чи очищення їжі назавжди виліковує фурболгів?",a="Ні. Їжа, просякнута водою місячного колодязя, лише ненадовго розвіює демонічний морок — досить, щоб фурболги згадали про мир, а Ксабраксіс вийшов із тіні. Убити сатира й забрати його талісман — важлива перемога, але Тундріс Віндвівер зауважує, що знайти остаточні ліки для зіпсованих племен буде нелегко.",al={"чи очищення назавжди","чи врятували фурболгів","чи фурболги вилікувані"}},{q="Звідки взялася думка використати воду місячного колодязя?",a="Місячні колодязі — священні водойми, благословенні богинею Елуною, сповнені цілющої магії, що протистоїть скверні й нежиттю. Тундріс Віндвівер дає очисну миску, щоб освячена вода знешкодила демонічні отрути, вплетені в їжу фурболгів.",al={"чому вода колодязя","чаша очищення місячного колодязя"}},{q="Що стається, коли поставити миску з їжею біля вогнища?",a="Фурболги поблизу ненадовго вириваються з кривавого шалу, мирно збираються довкола благословенної їжі й перестають нападати. Розлючений тим, що його маріонетки звільняються від мук, Ксабраксіс одразу з'являється, щоб покарати тих, хто втрутився.",al={"миска біля вогнища","очищення фурболгів"}},{q="Хто такий Тундріс Віндвівер?",a="Тундріс Віндвівер — дослідник нічних ельфів з Обердайна. Він координує зусилля, щоб докопатися до першопричин повзучого занепаду природи на Темному Узбережжі й шаленства, що охопило місцевих звірів.",al={"лор тундріса віндвівера","хто дає завдання"}}},fp="23,308,15.435.0,21.515.1,42.215.0,17.216.0,52.314.1,51.262.0,57.237.1,27.222.0"}
P.entries["quest:4767"] = {n="Вершник вітру",s="«Вершник вітру» — завдання Орди від Елу на Заставі Вільного Вітру в Тисячі Голок. Мріючи самому стати вершником вітрокрила, Елу доручає шукачам пригод видертися на скелясті висоти Високосіду й зібрати яйця диких віверн, щоб поповнити запаси крилатих їздових звірів Орди.",h="«Вершник вітру» — завдання Орди від Елу на Заставі Вільного Вітру в Тисячі Голок.",kw={"вершник вітру","елу","вітрокрили","віверни","високосід","застава вільного вітру"},ang={["class:Hunter"]="Мисливці, обізнані з приборканням і вдачею звірів, оцінять, скільки ризику й точності потрібно, щоб вихопити кладку просто з гнізда хижака, що ревно береже свою територію.",["faction:Horde"]="Віверни — хребет транспортної мережі Орди в Калімдорі, тож поповнення їхніх стаєнь конче важливе для зв'язку й оборони прикордоння.",["race:Tauren"]="Вершники вітрокрилів із Застави Вільного Вітру пишаються своїм умінням літати й вважають догляд за вівернами та їхній вишкіл почесною справою."},sec={{t="Поклик неба",b="По всьому Калімдору Орда покладається на вершників вітрокрилів, що переносять гінців, розвідників і воїнів на величезні відстані. На Заставі Вільного Вітру юний таурен на ім'я Елу прагне стати до їхніх шанованих лав. Оскільки потреби Орди, що розростається, випереджають кількість їздових звірів, Елу доручили допомогти роздобути нових віверн для досвідчених вершників вітрокрилів, тож охочі мандрівники мають нагоду долучитися до цієї життєво важливої справи."},{t="Підйом на Високосід",b="Високосід здіймається на вершинах високих столових гір Тисячі Голок — це найкраще гніздовище диких віверн. Щоб зібрати придатні яйця, треба подолати кручі й зустрітися з дорослими звірами, які ревно патрулюють гнізда. Здобувши ці кладки, Елу сподівається довести свою відданість і почати копітку працю — вигодовувати віверн з рук і вишколювати їх для господарів вітрокрилів Орди."}},faq={{q="Хто дає це завдання?",a="Завдання дає Елу — майбутній вершник вітру, що перебуває на вершині Застави Вільного Вітру в Тисячі Голок.",al={"хто дає завдання вершник вітру","хто починає вершник вітру","місце елу"}},{q="Що потрібно Елу?",a="Елу просить принести йому десять яєць Віверни Високосіда, зібраних просто з гнізд на Високосіді.",al={"цілі вершника вітру","що збирати","яйця віверн"}},{q="Де розташований Високосід?",a="Високосід — піднесене плато столової гори на північний захід від Застави Вільного Вітру, або трохи на південь від Застави Білого Рубежу. Природний схил, позначений тотемним стовпом, веде з дна каньйону нагору, до гнізд.",al={"як дістатися високосіду","вхід високосіду","де яйця віверн"}},{q="Чому Орда збирає яйця диких віверн?",a="Майстрам-вершникам вітру Орди дедалі більше бракує летючих верхових звірів для застав, і розведення в неволі не встигає за попитом. Вирощуючи віверн із диких кладок, приборкувачі можуть вишколювати нових звірів для перевезень і розвідки.",al={"чому збирати яйця віверн","лор яєць віверн"}},{q="Чи ворожі дикі віверни?",a="Так. Дикі віверни ревно стережуть свою територію й виводки й без вагань нападають на кожного, хто наближається до їхніх кладок на Високосіді.",al={"чи віверни нападуть","небезпека віверн"}},{q="Що Елу збирається робити з яйцями?",a="Елу сподівається, що, доставивши яйця, зможе розпочати справжнє навчання вершника вітру — вирощувати цих істот і здружитися з ними, щоб служити Орді в небі.",al={"що елу робить з яйцями","що буде з яйцями"}}},fp="10,269,19.432.0,19.390.0,21.97.0,19.98.0,27.200.0,44.257.0,29.143.0,41.158.0"}
P.entries["quest:477"] = {n="Перетин кордону",s="«Перетин кордону» — шпигунське доручення Жерця Тіні Аллістера в Гробниці: розслідувати таємні дії Даларана в Срібноліссі. Перехоплюючи ящики з припасами для даларанського табору біля Села Пайрвуд, Відступники сподіваються з'ясувати, чому Кірін-Тор так завзято підтримує людський оплот Амбермілл.",h="«Перетин кордону» — шпигунське доручення Жерця Тіні Аллістера в Гробниці: розслідувати таємні дії Даларана в...",kw={"перетин кордону","жрець тіні аллістер","даларан","кірін-тор","амбермілл","село пайрвуд","мапи"},ang={["class:Mage"]="Чаклуни Орди дуже зацікавлені в перехопленні магічних вантажів Даларана, щоб збагнути, які таємниці й захисні чари Кірін-Тор застосовує в Лордероні.",["class:Priest"]="Служачи під проводом Жерця Тіні Аллістера, жерці-Відступники мають пряму руку в захисті володінь Культу Забутої Тіні від суперників — і святих, і чарівних.",["race:Undead"]="Відступники не можуть терпіти неконтрольовану даларанську заставу на своєму південному фланзі — надто таку, що проводить припаси просто під носом у Гробниці."},sec={{t="Припаси на порубіжжі",b="Амбермілл — головна твердиня вцілілого людського опору у східному Срібноліссі, але маги Даларана не лишили його самого. Вози з припасами й чарівним начинням потай вивозять із Передгір'я Гілсбреда й переправляють через Срібнолісся до передових застав і збірних пунктів. Один такий табір постачання стоїть трохи на північ від Села Пайрвуд, і даларанські люди там стежать за дорогою."},{t="Підозри Відступників",b="Жреця Тіні Аллістера й верхівку Відступників у Гробниці тривожить, як завзято Даларан вкладається в Амбермілл. На їхню думку, звичайне провінційне містечко навряд чи варте того, щоб Кірін-Тор ризикував ресурсами й життями глибоко на землях, які заявили Відступники, — хіба що на кону стоїть якась більша стратегічна чи магічна мета. Огляд ящиків дасть Відступникам прямі відомості про те, що Даларан везе на захід."},{t="Що в ящиках",b="Розбивши один із ящиків чарівників, можна знайти більше, ніж звичайні харчі. Серед старанно запакованого чарівного начиння лежить в'язка старих, пожовклих мап Срібнолісся й ширшого західного Лордерона, а з ними — загадковий магічний амулет. Схоже, Даларан займається не звичайним постачанням, а цілеспрямованою картографічною й чарівною розвідкою."}},faq={{q="Чому чарівники Даларану діють у Срібноліссі?",a="Даларан діє з Амбермілла, щоб зберегти присутність людей і Альянсу на заході Лордерона. Жрець Тіні Аллістер підозрює, що Кірін-Тор має глибший прихований задум, ніж просто захищати сільське селище, тож Відступники нападають на їхні шляхи постачання.",al={"чому даларан у срібноліссі","даларан срібнолісся","чому даларан в амбермілл"}},{q="Де стоять ящики Даларану?",a="Ящики стоять у таборі даларанських магів і вартових просто на північ від Села Пайрвуд, осторонь головної дороги.",al={"місце ящиків даларана","де ящики","табір пайрвуд"}},{q="Що в ящику Даларану?",a="Аллістер не знає, що саме перевозить Даларан. Він просить вас забрати вміст ящика з табору на північ від Села Пайрвуд, щоб дослідити його.",al={"вміст ящика","що в скрині"}},{q="Хто такий Жрець Тіні Аллістер?",a="Жрець Тіні Аллістер — впливовий провідник Відступників у Гробниці в Срібноліссі, що керує розвідкою й наступальними ударами проти людських осередків опору та вторгнень Даларану.",al={"жрець тіні аллістер","хто дає перетин кордону"}},{q="Як припаси потрапляють до Срібнолісся?",a="Вантажі везуть возами із земель Даларану в Передгір'ї Гілсбреда через прикордонний перевал у Срібнолісся, а тоді до перевалочних таборів біля Амбермілла й Пайрвуда.",al={"шлях постачання даларана","вози хілсбрада"}},{q="Що йде після цього завдання?",a="Оглянувши ящик, віднесіть знайдене Жерцеві Тіні Аллістеру на дослідження в наступному завданні — «Мапи й руни».",al={"що далі","продовження","наступне завдання"}}},fp="16,343,24.444.0,24.417.0,20.368.1,52.263.0,37.143.0,33.159.1,30.204.0,52.195.0,42.125.1"}
P.entries["quest:4770"] = {n="Дорога додому",s="«Дорога додому» — завдання Орди: урятувати Пао'ку Свіфтмаунтіна, юного таурена-природознавця, що застряг у гніздовищах віверн на Високосіді. Відбившись від своїх і заблукавши під час вивчення небезпечних звірів, Пао'ка потребує супроводу, щоб безпечно спуститися з круч назад до Застави Білого Рубежу.",h="«Дорога додому» — завдання Орди: урятувати Пао'ку Свіфтмаунтіна, юного таурена-природознавця, що застряг у...",kw={"дорога додому","пао'ка свіфтмаунтін","мотеґа фаєрмейн","високосід","віверни","застава білого рубежу"},ang={["faction:Horde"]="Віверни — незамінні союзники й їздові звірі Орди по всьому Калімдору, тож дикі віверни Високосіду становлять неабиякий інтерес і для природознавців, і для стратегів.",["race:Tauren"]="Зв'язок між племенами й старійшинами для тауренів понад усе; глибока відповідальність Мотеґи перед батьком Пао'ки показує тісні громадські обов'язки, що ведуть їхні експедиції."},sec={{t="Природознавець, що схибив",b="Пао'ка Свіфтмаунтін прийшов із Малгору до Тисячі Голок разом зі старійшиною Мотеґою Фаєрмейном, щоб вивчати незвичайну живність дна каньйону та його високих кам'яних стовпів. Гнаний цікавістю й надмірною самовпевненістю, Пао'ка сам прокрався на висоти Високосіду, щоб на власні очі побачити місцевих віверн. Звірі, що ревно бережуть свою територію, прогнали його, і юний дослідник кілька днів просидів у пастці серед круч, наляканий і змушений ховатися."},{t="Стежка вниз кручами",b="Високосід кишить агресивними вівернами, що люто стережуть свої кладки й високі гнізда. Щоб провести Пао'ку на рівну землю, доведеться прорубати шлях просто крізь гніздовища хижаків. Не готовий до відкритого бою, переляканий юнак цілком покладається на мандрівників з Орди, які відбиватимуть зграї віверн, доки він не дістанеться відносно безпечної стежки каньйоном на схід."},{t="Полегшення й розплата",b="Біля підніжжя круч Пао'ка нарешті може безпечно дістатися додому — до Застави Білого Рубежу. Його опікун, Мотеґа Фаєрмейн, приголомшений, дізнавшись, що сталося. Мотеґа пообіцяв батькові Пао'ки, який і так вагався відпускати сина, що наглядатиме за хлопцем під час польових досліджень. Відчувши полегшення, що Пао'ка пережив свою безглузду вилазку, Мотеґа нагороджує рятівників, а сам потай шкодує, що не прикував безрозсудного учня до тотема."}},faq={{q="Хто такий Пао'ка Свіфтмаунтін?",a="Пао'ка Свіфтмаунтін — юний тауренський учень, що прибув до Тисячі Голок разом із Мотеґою Фаєрмейном, щоб описувати й вивчати диких звірів. Юнацький запал завів його на Високосід без нагляду.",al={"пао'ка","пао'ка свіфтмаунтін","хто супроводжуваний"}},{q="Чому Пао'ка ховався на Високосіді?",a="Він сам пішов до гнізд, щоб краще роздивитися місцевих віверн і їхні гнізда. Агресивні звірі напали на нього, і він мусив сховатися, опинившись у пастці на високій столовій горі.",al={"чому пао'ка в високосіді","що сталося з пао'кою","чому він застряг"}},{q="Хто такий Мотеґа Фаєрмейн?",a="Мотеґа Фаєрмейн — тауренський природознавець із Застави Білого Рубежу в Тисячі Голок. Батько Пао'ки доручив йому пильнувати безпеку юнака під час їхньої наукової експедиції.",al={"мотега","хто такий мотега фаєрмейн","нпц здавання"}},{q="Де розташований Високосід?",a="Високосід — піднесена столова гора й місце гніздування віверн на заході Тисячі Голок, трохи на захід від Застави Білого Рубежу й на північний захід від Застави Вільного Вітру.",al={"місце високосіду","де високосід","звідки супроводжувати"}},{q="Де Застава Білого Рубежу?",a="Застава Білого Рубежу — невеликий табір Орди на схід від Високосіду в Тисячі Голок, польова база тауренських природознавців, що вивчають звірів каньйону.",al={"місце білого рубежу","де застава білого рубежу"}},{q="Чи знав Мотеґа, що Пао'ка зник?",a="Ні. Пао'ка потай вирушив на Високосід, нічого не сказавши Мотезі, тож той і гадки не мав, у якій небезпеці його учень, доки ви не повідомили про порятунок.",al={"чи мотега знав","чому мотега не шукав"}}},fp="14,315,29.423.0,23.387.0,20.428.1,28.212.0,35.195.0,23.190.0,27.169.0,25.166.0,36.177.1"}
P.entries["quest:478"] = {n="Мапи й руни",s="«Мапи й руни» — розвідувальна місія Відступників у Срібноліссі. Натрапивши на підозрілий вантаж, що прямував до Амбермілла, шукачі пригод здобувають амулет із рунами й несуть його Жерцеві Тіні Аллістеру в Гробницю для подальшого розслідування.",h="«Мапи й руни» — розвідувальна місія Відступників у Срібноліссі.",kw={"мапи й руни","амулет із рунами","жрець тіні аллістер","даларан","кірін-тор","амбермілл"},ang={["class:Mage"]="Амулет із рунами має характерні візерунки чарів Кірін-Тору, що вказують на особливу даларанську традицію захисних і обережних чарів.",["class:Priest"]="Хоч Жрець Тіні Аллістер орудує грізною магією тіні, ні божественні, ні тіньові науки не годяться, щоб розплутати складні чарівні формули, вирізьблені на амулеті.",["faction:Horde"]="Убезпечуючи Срібнолісся від сил, пов'язаних з Альянсом, як-от Кірін-Тор, ви зберігаєте для Орди важливий коридор постачання через північний Лордерон.",["race:Undead"]="Уцілілі чарівники Даларана тримають застави незатишно близько від земель Андерсіті. Відбирати в них зачаровані талісмани вкрай важливо, щоб уберегти владу Відступників у Срібноліссі."},sec={{t="Прихований вантаж",b="Перехоплюючи постачання довкола Амбермілла, агенти Орди виявляють даларанський ящик, захований на прикордонних шляхах. Замість звичайних припасів у ньому — докладні мапи краю й загадковий амулет із рунами. Розуміючи, якою небезпечною може бути чарівна сила Даларана так близько від їхніх кордонів, розвідники обережно забирають артефакт, щоб не сполохати навколишніх людських вартових."},{t="Шепіт у Гробниці",b="Повернувшись до Гробниці, знайдений амулет показують Жерцеві Тіні Аллістеру. Верхівка Відступників розуміє, що Кірін-Тор діє в Амберміллі з чіткою метою, але що саме вони чаклують, досі незрозуміло. Не здатний сам розгадати могутнє чаклунство, вплетене в руни, Аллістер вирішує порадитися зі знавцями чарівної магії серед нежиті, щоб розплутати змову Даларана."}},faq={{q="Що в ящику Даларану?",a="У ящику — стратегічні мапи Срібнолісся й дивний кулон, укритий рунами. Ці речі свідчать, що чарівники Даларану активно планують маневри довкола містечка Амбермілл.",al={"що було в ящику","вміст скрині даларана","здобич ящика даларана"}},{q="Хто такий Жрець Тіні Аллістер?",a="Жрець Тіні Аллістер — впливовий провідник Відступників у Гробниці. Він керує місцевою розвідкою й координує оборону від ворожих решток людей і агентів Кірін-Тору в Срібноліссі.",al={"хто такий аллістер","жрець тіні аллістер лор"}},{q="Чому Відступників непокоїть Даларан в Амберміллі?",a="Амбермілл — діючий плацдарм Кірін-Тору просто на кордоні земель Лордерона, на які претендують Відступники. Будь-яке перекидання тайних реліквій чи потаємне пересування військ — пряма загроза владі Андерсіті над Срібноліссям.",al={"чому даларан в амбермілл","відступники й даларан"}},{q="Чи може Жрець Тіні Аллістер розгадати кулон?",a="Ні. Аллістер упізнає в артефакті річ даларанських чаклунів, але його чари виходять за межі жрецького хисту, тож він шукає допомоги в того, хто глибше знається на тайній магії.",al={"чи аллістер розгадає руни","чи аллістер прочитає кулон"}},{q="Куди веде це розслідування далі?",a="Розслідування продовжується в завданні «Аналіз Далара», де кулон передають Даларові Донвіверу — знавцеві тайної магії в Гробниці, здатному розібрати чари Кірін-Тору.",al={"наступне завдання","після мап і рун"}},{q="Яке завдання передує «Мапам і рунам»?",a="Це завдання безпосередньо продовжує «Перетин кордону», де Відступники доручають агентові оглянути підозрілі торгові ящики, що надходять до Срібнолісся з кордонів Даларану.",al={"передумова мап і рун","попереднє завдання"}}},fp="14,265,14.410.0,25.408.1,33.200.0,30.237.0,58.254.0,48.198.0,40.185.0,38.174.0"}
P.entries["quest:479"] = {n="Розслідування в Емберміллі",s="Це доручення Відступників від Жерця Тіні Аллістера з Гробниці. Чарівники Даларана плетуть магію в сусідньому містечку Амбермілл, і Відступники мусять зірвати їхні чари й відібрати їхні магічні фокуси, щоб утримати Срібнолісся.",h="Це доручення Відступників від Жерця Тіні Аллістера з Гробниці.",kw={"розслідування в емберміллі","амбермілл","жрець тіні аллістер","кірін-тор","даларан","амулети","срібнолісся"},ang={["class:Mage"]="Маги знають, якої точної злагодженості вимагає великий чарівний обряд, і розуміють, чому розірвання зачарованих фокусів Кірін-Тору зриває їхні чари.",["faction:Horde"]="Убезпечене Срібнолісся захищає західні підступи до Лордерона від застав, пов'язаних з Альянсом і вірних Даларану.",["race:Undead"]="Рештки Кірін-Тору в Амберміллі сидять просто на порозі земель Андерсіті, тож їхні магічні задуми — нестерпна загроза виживанню Відступників."},sec={{t="Загроза зі сходу",b="Людське містечко Амбермілл гніздиться в пагорбах східного Срібнолісся, і його міцно тримають чарівники й оборонці, що присягнули Кірін-Тору з Даларана. Коли маги беруться за великий спільний обряд, сплітаючи магічну енергію, Жрець Тіні Аллістер і його товариш Далар бачать нагальну небезпеку. Якщо дозволити Кірін-Тору безперешкодно спрямовувати свою силу, Відступників можуть зовсім вимести зі Срібнолісся."},{t="Розірвати плетиво",b="Поки Далар провидить і відстежує потоки магії лісом, Аллістер посилає агентів до Амбермілла, щоб ударити просто по чародіях. Даларанські заклиначі, маги та їхні охоронці носять зачаровані амулети, що допомагають зосереджувати й узгоджувати їхнє мистецтво. Знімаючи ці талісмани з убитих чаклунів, ви зриваєте обряд і даєте Гробниці дорогоцінний час, щоб вистежити призвідника, який керує чарівним плетивом."}},faq={{q="Чому Жрець Тіні Аллістер цілить в Амбермілл?",a="Маги Кірін-Тору, що окопалися в Амберміллі, активно спрямовують потужну тайну енергію. Аллістер боїться, що, якщо їхні чари вдадуться, Відступники втратять владу над Срібноліссям.",al={"чому нападати на амбермілл","мотив аллістера","загроза амбермілла"}},{q="Навіщо потрібні Даларанські Кулони?",a="Даларанські заклиначі, маги й захисники носять ці кулони як осередки для своїх чарів. Забравши їх, ви послабите зусилля чарівників і допоможете Аллістерові оцінити, як просуваються магічні задуми Кірін-Тору.",al={"що за даларанські кулони","призначення кулонів","навіщо збирати кулони"}},{q="Де розташований Амбермілл?",a="Амбермілл лежить на східних пагорбах Срібнолісся. Від Гробниці йдіть на південь головним шляхом і звертайте на розвилці на схід — до містечка.",al={"місце амбермілла","як дістатися амбермілла","де амбермілл"}},{q="Хто такий Далар і яка його роль?",a="Далар — маг Відступників, що служить у Гробниці разом із Жерцем Тіні Аллістером; йому доручено вистежити й викрити магічні джерела, що живлять чарівників Даларану в Амберміллі.",al={"хто такий далар","роль далара","далар срібнолісся"}},{q="Що буде, коли кулони здобуто?",a="Зібрані кулони показують, що даларанський обряд уже далеко просунувся; його очолює вправний чарівник, і щоб цілком зупинити чари, доведеться зійтися з ним віч-на-віч.",al={"що далі","продовження розслідувань амбермілла","після кулонів даларана"}},{q="Чому люди Даларану досі в Срібноліссі?",a="До Третьої війни Даларан мав кілька застав і поселень у цьому краї. Навіть після спустошення королівства вцілілі сили Кірін-Тору й далі утримують Амбермілл від Погибелі й Відступників.",al={"чому люди даларана тут","кірін тор срібнолісся","лор амбермілла"}}},fp="24,275,22.436.0,20.432.0,50.198.0,39.190.0,27.167.0,37.190.0,43.171.1,50.219.0"}
P.entries["quest:480"] = {n="Ткач",s="«Ткач» — ударне доручення Жерця Тіні Аллістера в Гробниці: спинити магічну діяльність Даларана в Срібноліссі. Даларанський архімаг Атаерік керує спробою знову пробудити могутній вузол лей-енергії в краї. Убивши архімага й забравши його посох, Відступники зривають таємні задуми Даларана й зміцнюють свою владу над навколишніми землями.",h="«Ткач» — ударне доручення Жерця Тіні Аллістера в Гробниці: спинити магічну діяльність Даларана в Срібноліссі.",kw={"ткач","архімаг атаерік","жрець тіні аллістер","лей-лінії","даларан","амбермілл","срібнолісся"},ang={["class:Mage"]="Керування лей-лініями вимагає глибокого знання чарівної геометрії; загибель Атаеріка показує, наскільки вразливі такі тонкі обряди, коли падає їхній головний провідник.",["class:Priest"]="Жрець Тіні Аллістер керує цією операцією не святими цілющими чарами, а розважливою волею, щоб загасити чарівний каталізатор, перш ніж той розквітне.",["faction:Horde"]="Рештки Даларана й далі ворожі до Орди, тож будь-яке розширення їхньої чарівної мережі — пряма загроза землям Орди на півночі Лордерона.",["race:Undead"]="Живі маги Даларана оскаржують владу Відступників над руїнами Лордерона. Знешкодити їхнього архімага вкрай важливо, щоб убезпечити околиці Гробниці."},sec={{t="Перерізати лей-нитку",b="Після перших розвідок в Амберміллі та стеження за пересуваннями Даларана в Срібноліссі Відступники дізналися про небезпечну новину: чарівники намагаються приборкати й знову пробудити дрімотний вузол лей-енергії. Якщо їх не спинити, доступ до такої зосередженої чарівної сили дасть Даларанові змогу зміцнити свої позиції й загрожуватиме владі Андерсіті над південними околицями Лордерона."},{t="Падіння архімага",b="Жрець Тіні Аллістер розуміє: щоб зруйнувати справу такого розмаху, треба відтяти їй голову. Нею керує Архімаг Атаерік — грізний чарівник, що ховається за захисними чарами й іншими магами. Убивши його й забравши посох, ви розвіюєте зібрану магію, лей-енергія знову поринає в сон, а задуми Кірін-Тору в долині зазнають краху."}},faq={{q="Хто такий Ткач?",a="Ткачем називають Архімага Атаеріка — могутнього даларанського мага в Срібноліссі. Йому доручено сплести докупи й знову пробудити приспану енергію лей-ліній, що пролягають під цим краєм.",al={"хто такий ткач","архімаг атаерік","атаерік ткач"}},{q="Чому Відступники хочуть смерті архімага?",a="Якщо Даларан зуміє підключитися до приспаного вузла лей-енергії, його маги отримають величезне джерело тайної сили просто на порозі Андерсіті. Жрець Тіні Аллістер вважає це нестерпною загрозою незалежності Відступників і наказує швидко вбити архімага, перш ніж вузол запрацює на повну силу.",al={"чому вбити архімага","конфлікт відступників і даларана","чому нападати на даларан"}},{q="Що буде, коли Атаеріка переможено?",a="Коли Атаерік мертвий, а його посох забрано, тайна мережа руйнується. Зібрані чари розвіюються, лей-лінія знову засинає, і Кірін-Тор утрачає головне джерело тайної сили на півдні Срібнолісся.",al={"після ткача","наслідок завдання","що буде з вузлом ліній"}},{q="Хто дає це завдання?",a="Наказ дає Жрець Тіні Аллістер, провідник Відступників у Гробниці в Срібноліссі, проаналізувавши попередні розвідані про присутність Даларану довкола Амбермілла.",al={"хто дає ткача","завдання аллістера","хто дає завдання ткач"}},{q="Яке значення має посох Атаеріка?",a="Посох Архімага Атаеріка — провідник і осередок, через який керують лей-енергією краю. Забравши його, ви гарантуєте, що чари цілком розпадуться, а Аллістер отримає артефакт, який можна вивчити для задумів самих Відступників.",al={"посох атаеріка","призначення посоху архімага","навіщо брати посох"}},{q="Звідки в Срібноліссі взявся Даларан?",a="Попри спустошення Даларану в Третій війні, рештки Кірін-Тору утримують укріплені осередки, застави й тайні досліди в сусідніх землях на кшталт Амбермілла, намагаючись відновити владу й скористатися важливими магічними запасами.",al={"даларан у срібноліссі","чому маги даларана у срібноліссі","амбермілл даларан"}}},fp="10,391,23.407.0,19.392.1,18.211.0,45.312.0,39.235.1,28.201.0,44.256.0,54.258.0"}
P.entries["quest:481"] = {n="Аналіз Далара",s="«Аналіз Далара» — завдання Орди в Срібноліссі, що поєднує шпигування Жерця Тіні Аллістера за Амберміллом із чарівними дослідженнями Далара Донвівера. Знайшовши в даларанському ящику з припасами амулет із рунами, шукачі пригод несуть реліквію Даларові в Гробницю на дослідження. Артефакт показує, що вцілілі маги Даларана збирають значну магічну силу для якоїсь прихованої справи.",h="«Аналіз Далара» — завдання Орди в Срібноліссі, що поєднує шпигування Жерця Тіні Аллістера за Амберміллом із...",kw={"аналіз далара","далар донвівер","жрець тіні аллістер","амулет із рунами","кірін-тор","амбермілл"},ang={["class:Mage"]="Маги-Відступники впізнають в амулеті Кірін-Тору класичне знаряддя для спрямування сили в традиційному даларанському чаротворенні — знак того, що їхні колишні брати готують величезне закликання.",["faction:Horde"]="Зриваючи задуми Кірін-Тору в Срібноліссі, ви оберігаєте Східні Королівства від відроджених магічних сил, пов'язаних з Альянсом.",["race:Undead"]="Для Відступників стежити за діями Даларана в Амберміллі вкрай важливо, щоб уберегти кордони Срібнолісся й захистити Гробницю від ворожого чаклунства."},sec={{t="Вантаж гінця",b="Після набігу на даларанський ящик із припасами в таборі на північ від Села Пайрвуд Жрець Тіні Аллістер отримує амулет із рунами, знайдений під в'язкою старих мап. Розуміючи, що такі чари не в його духовній царині, Аллістер передає реліквію Даларові Донвіверу — знавцеві чарівної магії в Гробниці, який краще здатен розгадати даларанські захисні чари."},{t="Задуми Кірін-Тору",b="Оглянувши амулет, Далар Донвівер визначає його як особливий провідник, якому здавна віддавали перевагу високопоставлені чарівники Кірін-Тору, щоб спрямовувати могутню магічну енергію. Сама кількість таких реліквій, які звозять просто в укріплене містечко Амбермілл, свідчить, що чарівники готують чарівну справу величезного розмаху, і Далар береться зазирнути за їхні захисні чари, щоб розгадати справжні наміри."}},faq={{q="Що таке кулон, укритий рунами?",a="Кулон — тайний артефакт, яким старші маги Кірін-Тору безпечно спрямовують великі обсяги магічної енергії. Те, що його перехопили дорогою, свідчить: Амбермілл постачають могутніми осередками для чарів найвищого рівня.",al={"що таке кулон","лор кулона кірін тор","кулон амбермілла"}},{q="Чому Жрець Тіні Аллістер передає кулон Даларові Донвіверу?",a="Жрець Тіні Аллістер у Гробниці займається здебільшого магією Тіні й розвідкою для Відступників. Кулон — складна тайна реліквія даларанської роботи, тож розібрати його руни й з'ясувати призначення може лише знавець тайної магії на кшталт Далара Донвівера.",al={"чому далар","хто такий далар донвівер","чому слати до гробниці"}},{q="Де Амбермілл і чому Відступники за ним стежать?",a="Амбермілл — укріплене людське містечко на південному сході Срібнолісся, яке утримують маги Даларану. Воно лежить глибоко в землях, на які претендує Леді Сильвана Віндраннер, і становить безпосередню воєнну й магічну загрозу для Відступників, тож за його кордонами пильно наглядають.",al={"чому стежити за амбермілл","маги амбермілла","даларан у срібноліссі"}},{q="Що буде, коли Далар проаналізує кулон?",a="Збагнувши, що Кірін-Тор збирає тайні провідники для великої справи, Далар у наступному завданні, «Наміри Даларана», власною магією зазирає крізь захисні щити Амбермілла, щоб дізнатися, що саме задумали чарівники.",al={"що далі","після аналізу далара","наміри даларана"}},{q="Де знайти Далара Донвівера?",a="Далар Донвівер — у крипті Гробниці, головної твердині Відступників у Срібноліссі при головній дорозі.",al={"де далар","місце далара","далар донвівер срібнолісся"}},{q="Чому Кірін-Тор відкрито діє в Срібноліссі?",a="Амбермілл був володінням Даларану ще до того, як Погибель спустошила Лордерон. Попри падіння столиці й самого Даларану, уцілілі чарівники утримують Амбермілл як діючий оплот і постійно сутичаться з Відступниками, що поширюють свою владу.",al={"чому кірін тор відкрито","присутність даларана у срібноліссі"}}},fp="16,423,17.393.0,22.429.1,35.236.0,69.299.0,58.295.0,46.256.1,36.142.0,60.257.0"}
P.entries["quest:4811"] = {n="Червоний кристал",s="Вартова Ґлінда Нал'Шея з Обердайна доручає мандрівникам перевірити чутки про таємничий червоний кристал, що вріс у східні гори Темного Узбережжя. Поблизу множаться ворожі місячники, яких, схоже, вабить це утворення, тож Вартовим треба з'ясувати, чи аномалія справді існує.",h="Вартова Ґлінда Нал'Шея з Обердайна доручає мандрівникам перевірити чутки про таємничий червоний кристал, що...",kw={"червоний кристал","ґлінда нал'шея","місячники","обердайн","вартові","темне узбережжя"},ang={["class:Druid"]="Друїди мають тісний духовний зв'язок із місячниками та природним ладом Темного Узбережжя, тож згубна сила, що тягне їх до кристала, — нагальна турбота для природи.",["faction:Alliance"]="Обердайн — головний прибережний порт Альянсу на півночі Калімдору; будь-яка загроза, що безкарно збирається в пагорбах, може відрізати цей прихисток від навколишніх нетрів.",["race:NightElf"]="Збудженість місячників — тривожне видовище для калдореїв, які шанують цих створінь як священних підопічних Елуни й природи."},sec={{t="Тривожні зміни в нетрях",b="Поколіннями нічні ельфи Калімдору вважали місячників лагідними, містичними створіннями, тісно пов'язаними з дикою природою. Та останнім часом на схилах на схід від Обердайна швидко розплодилися агресивні зграї. Дехто з прихильників давніх звичаїв і досі шанує місячників, але Вартова Ґлінда Нал'Шея понад усе ставить безпеку містечка й не може ігнорувати дедалі більшу небезпеку. За донесеннями, звірі сходяться до певного місця на східних вершинах."},{t="Аномалія на східній горі",b="Розвідники й мандрівники принесли пошепки звістки про протиприродний червоний кристал, що стирчить із кам'янистого схилу високо над Темним Узбережжям. На оповитому туманом узбережжі дикі чутки ширяться легко, тож Ґлінді потрібен хтось на місці, щоб відрізнити вигадку від правди. Знайдений багряний моноліт підтверджує, що аномалія цілком реальна, і Вартовим лишається гадати, чому місцевих місячників незбагненно вабить до нього і чи не віщує він зловісного впливу на край."}},faq={{q="Що це за червоний кристал на Темному Узбережжі?",a="Це загадкове сяйливе багряне утворення, вросле в східне гірське пасмо над Темним Узбережжям. Спершу вартові знали про його походження небагато — тільки те, що місцевих звірів, особливо місячників, нестримно тягне до нього.",al={"що за червоний кристал","кристал темного узбережжя","червоний камінь обердайн"}},{q="Хто посилає мене шукати червоний кристал?",a="Доручення дає Вартова Ґлінда Нал'Шея з Обердайна. Вона відповідає за захист поселення й хоче з перших рук перевірити чутки про східні гори.",al={"хто дає червоний кристал","завдання глінди налші","хто дає кристал обердайна"}},{q="Чому місячники поводяться агресивно біля кристала?",a="Здавна місячників вважали лагідними й таємничими істотами, але тепер вони стали ревнивими до своєї території й непередбачуваними. Вартова Ґлінда підозрює, що їхня раптова зміна поведінки й дедалі більша кількість безпосередньо пов'язані із силою, яку випромінює загадковий червоний кристал.",al={"чому місячники агресивні","розлючені місячники узбережжя","ворожі місячники"}},{q="Де розташований червоний кристал?",a="Кристал лежить просто на схід від Обердайна, високо на скелястому східному хребті Темного Узбережжя, і довкола нього никають місячники.",al={"де знайти червоний кристал","місце червоного кристала","мапа червоного кристала"}},{q="Чи вважають нічні ельфи кристал небезпечним?",a="Вартова Ґлінда дуже обережна. Вона не певна, чи камінь нешкідливий, чи зловісний, але те, що він збурює й збирає довкола себе диких звірів, — уже безпосередня загроза безпеці Обердайна.",al={"чи кристал поганий","чи червоний кристал злий"}},{q="Що буде, коли кристал знайдено?",a="Доповідь Ґлінді підтверджує чутки. Вона одразу береться з'ясовувати справжню природу кристала — і це веде до спроб очистити його й узяти зразок за допомогою води з місячного колодязя Обердайна.",al={"що після червоного кристала","продовження як спадає вода"}}},fp="15,295,31.466.0,28.464.0,37.253.0,42.200.0,57.260.0,33.141.0,55.204.0,44.197.1"}
P.entries["quest:4812"] = {n="Як спадає вода",s="«Як спадає вода» — завдання Альянсу на Темному Узбережжі, в якому шукачі пригод перевіряють природу таємничого червоного кристала, що стирчить зі східної гірської стіни. Поливаючи його священною водою з місячного колодязя Обердайна, вони намагаються пробити його непрозору оболонку й з'ясувати, звідки він узявся.",h="«Як спадає вода» — завдання Альянсу на Темному Узбережжі, в якому шукачі пригод перевіряють природу...",kw={"як спадає вода","червоний кристал","ґлінда нал'шея","місячний колодязь","сквернолісся","обердайн"},ang={["class:Druid"]="Друїди, що стережуть крихку природу Темного Узбережжя, природно підозріло ставляться до протиприродних чужинських утворень, особливо на кряжі під спотвореним Скверноліссям.",["faction:Alliance"]="Розвідники Альянсу в Обердайні мусять берегти узбережжя від порчі, що сповзає зі східних височин.",["race:NightElf"]="Для калдореїв місячні колодязі — священні джерела життя й розради. Те, що їхня освячена вода стає знаряддям одкровення, показує, наскільки ласка Елуни важлива, щоб розплутувати загрози на їхніх кордонах."},sec={{t="Очистити невідоме",b="Після того як червоний кристал уперше помітили високо на східних скелях Темного Узбережжя, Вартова Ґлінда Нал'Шея вигадує, як безпечно дослідити його склад. Вода місячних колодязів несе потужну божественну й відновлювальну магію, благословенну відданістю нічних ельфів Елуні. Ґлінда міркує, що, якщо облити чужинський моноліт водою з місячного колодязя в Обердайні, це викличе реакцію й прорве дивну непрозору оболонку, не знищивши самого кристала."},{t="Тінь Сквернолісся",b="Тривога Нал'Шеї здебільшого пов'язана з географією. Східний кряж Темного Узбережжя нависає під спотвореними висотами Сквернолісся — лісу, який демонічні енергії викривили під час Третьої війни. Якщо багряний шпиль пов'язаний із порчею Сквернолісся, поводитися з ним надзвичайно ризиковано. Коли священна вода стікає ґратчастою будовою кристала, гудучий камінь на мить стає прозорим — натяк на те, що ув'язнене всередині варто роздивитися ближче."}},faq={{q="Де взяти воду для цього завдання?",a="Воду треба набрати з місячного колодязя в поселенні нічних ельфів Обердайн у порожню пляшечку, яку дає Вартова Ґлінда Нал'Шея.",al={"де місячний колодязь","місце води колодязя","наповнити порожню трубку"}},{q="Чому вода місячного колодязя діє на кристал?",a="У місячних колодязях — освячена, багата на магію вода, благословенна Елуною. Вартова Ґлінда Нал'Шея сподівається, що її очисна сила вступить у реакцію з чужою енергією каменя й розкриє його прихований склад.",al={"чому вода колодязя","магія колодязя на кристал"}},{q="Де розташований червоний кристал?",a="Загадковий червоний кристал лежить біля східної гірської стіни Темного Узбережжя, серед скелястих передгір'їв, що відділяють берег від нагір'я.",al={"місце червоного кристала","де кристал","червоний кристал узбережжя"}},{q="Чому Вартову Ґлінду тривожить Сквернолісся?",a="Сквернолісся лежить просто на схід і вище від Темного Узбережжя; його спустошила демонічна скверна Третьої війни. Оскільки кристал з'явився біля прикордонного хребта, Ґлінда боїться, що він має те саме мерзенне демонічне походження.",al={"чому ґлінду турбує сквернолісся","зв'язок зі скверноліссям"}},{q="Що стається, коли полити кристал водою?",a="Ґлінда сподівається, що сильна вода місячного колодязя відкриє підказку про склад кристала. Як він відгукнеться, ви побачите, коли поллєте його водою.",al={"результат поливання","що буде з кристалом"}},{q="Хто дає завдання «Як спадає вода»?",a="Завдання дає Вартова Ґлінда Нал'Шея в Обердайні — одразу після розвідки в завданні «Червоний кристал».",al={"хто дає завдання","початок як спадає вода"}}},fp="17,295,21.453.0,21.441.1,40.150.0,43.212.0,33.153.0,45.204.0,52.150.1,38.127.0"}
P.entries["quest:4813"] = {n="Уламки всередині",s="«Уламки всередині» — заключне завдання в розслідуванні таємничого червоного кристала, що стирчить зі скель на схід від Обердайна. З очищеною водою з місячного колодязя вас посилають назад на місце, щоб дослідити, що ховається в дивному утворенні, і доповісти Вартовій Ґлінді Нал'Шеї.",h="«Уламки всередині» — заключне завдання в розслідуванні таємничого червоного кристала, що стирчить зі скель на...",kw={"уламки всередині","червоний кристал","ґлінда нал'шея","кістки","місячний колодязь","обердайн"},ang={["class:Druid"]="Таємничий мінерал опирається і природному зношенню, і могутній магії — дивна аномалія на тлі звичної рівноваги дикої природи.",["race:NightElf"]="Гуманоїдні кістки, застиглі в дивному кристалі на гірських межах Ашенвалю й Сквернолісся, вимагають від Вартових, що стережуть Темне Узбережжя, пильної уваги."},sec={{t="Похмуре одкровення",b="Благословенна вода з місячного колодязя змиває каламутну оболонку багряного кристала й відкриває те, що ув'язнене під його гладкою поверхнею. У щільному мінералі застигли кілька дрібних уламків кісток і половина гуманоїдної щелепи. Камінь, що їх оточує, надзвичайно міцний — настільки, що навіть грізні чари навряд чи його розколють. Хай яка сутність чи артефакт породили ці рештки, їх дивовижно відокремлено збережено високо над берегами Темного Узбережжя."},{t="Донесення до Обердайна",b="Повернувшись до Обердайна, ви розповідаєте Вартовій Ґлінді Нал'Шеї про свою тривожну знахідку. Замість остаточних відповідей це одкровення лише додає тривог місцевому проводу нічних ельфів. Ґлінда обіцяє представити знахідки раді містечка, хоча й утішається тим, що дивний кристал стоїть високо на східних скелях, досить далеко від містечка, щоб не становити негайної небезпеки для мешканців."}},faq={{q="Що замкнено в червоному кристалі?",a="Омитий освяченою водою місячного колодязя, кристал стає досить прозорим, щоб розгледіти глибоко всередині кілька уламків кісток і половину щелепи якоїсь людиноподібної істоти.",al={"що в кристалі","що за уламки","які кістки всередині"}},{q="Чи можна розбити кристал, щоб оглянути кістки?",a="Ні. Кристал надзвичайно міцний. Навіть найпотужнішій магії було б майже не до снаги пробити його будову, тож чиї це кістки, лишається загадкою.",al={"чи можна розбити кристал","відкриття червоного кристала"}},{q="Кому доповісти про знахідку?",a="Про знахідку треба доповісти Вартовій Ґлінді Нал'Шеї, що служить у портовому містечку Обердайн.",al={"кому здати уламки всередині","здати завдання","глінда налші"}},{q="Що вартові робитимуть із кристалом?",a="Вартова Ґлінда Нал'Шея збирається повідомити раду Обердайна, щоб та обміркувала можливі дії. Утім, оскільки кристал лежить високо на східних кручах, його не вважають нагальною загрозою.",al={"що буде з кристалом далі","рада обердайна кристал"}}},fp="20,303,17.492.1,22.437.0,39.162.1,52.189.1,34.101.0,45.211.1"}
P.entries["quest:482"] = {n="Наміри Даларана",s="«Наміри Даларана» — завдання в Срібноліссі, у якому Далар Донвівер передає вісті Жерцеві Тіні Аллістеру. Дослідивши амулет із рунами, призначений для Кірін-Тору в Амберміллі, Далар розуміє, що чарівники мають намір черпати силу з дрімотного вузла лей-енергії під містечком, і верхівка Відступників у Гробниці починає планувати контрнаступ.",h="«Наміри Даларана» — завдання в Срібноліссі, у якому Далар Донвівер передає вісті Жерцеві Тіні Аллістеру.",kw={"наміри даларана","далар донвівер","жрець тіні аллістер","лей-лінії","амбермілл","кірін-тор"},ang={["class:Mage"]="Маги-Відступники впізнають методи Кірін-Тору: черпати силу з дрімотних лей-ліній — дієвий спосіб закласти могутній чарівний плацдарм, не тягнучи величезних джерел сили через дику місцину.",["class:Priest"]="Жрець Тіні Аллістер керує обороною Відступників у Гробниці, поєднуючи холодну військову прагматичність із темним ученням Культу Забутої Тіні, щоб викорінювати загрози від живих.",["race:Undead"]="Присутність Даларана так глибоко в Срібноліссі — пряма загроза кордонам Відступників; зупинивши їхній обряд із лей-лініями, ви захистите шляхи між Тірісфалем і південними рубежами."},sec={{t="Приспана іскра",b="Оглядаючи амулет із рунами, знайдений у даларанському ящику з припасами, Далар Донвівер пригадує давнє обстеження Кірін-Тору. Маги обрали Амбермілл не випадково: тихе село стоїть просто над дрімотним вузлом лей-енергії. Щоб пробудити таке підземне сплетіння, потрібні величезні магічні запаси, а зачаровані амулети, які носять чарівники, — ключові складники, що спрямовують і розпалюють цю силу."},{t="Загроза Срібноліссю",b="Відступники не можуть терпіти укріпленої, наповненої силою застави Кірін-Тору, що загрожує південним підступам до Гробниці й Галявин Тірісфалю. Хоч би який великий обряд готували маги, приборкання сирих лей-ліній дасть Даларанові величезну стратегічну перевагу в Лордероні. Далар терміново шле звістку Жерцеві Тіні Аллістеру, щоб виробити задум, який загальмує чарівників, перш ніж їхній обряд буде завершено."}},faq={{q="Що Кірін-Тор намагається зробити в Амберміллі?",a="Чарівники Даларану намагаються знову пробудити приспаний вузол лей-енергії під Амберміллом. Підключившись до цієї тайної жили, вони здобули б величезну силу, щоб закріпитися назавжди й утілювати свої ширші задуми в Срібноліссі.",al={"що кірін тор робить в амбермілл","що роблять маги даларана у срібноліссі","мета амбермілла"}},{q="Чому Далар посилає мене до Жерця Тіні Аллістера?",a="Жрець Тіні Аллістер — старший військовий і духовний провідник Відступників у Гробниці. Далар Донвівер дає тайні знання й дослідження, але тактичні рішення й наступальні заходи проти Даларану — справа Аллістера.",al={"чому далар посилає до аллістера","хто такий аллістер","далар донвівер аллістер"}},{q="Як кулони чарівників пов'язані з їхніми задумами?",a="Щоб пробудити приспаний лей-вузол, потрібні величезні запаси сили. Чарівники Даларану носять зачаровані кулони, що слугують провідниками й сховищами цієї магії. Позбавивши магів кулонів, ви підриваєте їхню здатність завершити пробудження.",al={"кулони чарівників","кулони амбермілла","навіщо збирати кулони"}}},fp="20,349,15.431.0,24.437.0,48.251.0,50.271.0,50.253.0"}
P.entries["quest:4821"] = {n="Чужорідне Яйце",s="Серед тауренів Застави Вільного Вітру ходять чутки про дивне, чужорідне яйце, яке люто стережуть дикі змії на дні каньйону. Гаґар Лайтнінггуф доручає шукачам пригод з Орди розшукати й забрати цей зразок, перш ніж те, що причаїлося всередині, вирветься на волю.",h="Серед тауренів Застави Вільного Вітру ходять чутки про дивне, чужорідне яйце, яке люто стережуть дикі змії на...",kw={"чужорідне яйце","молода арікара","гаґар лайтнінггуф","вітряні змії","застава вільного вітру","тисяча голок"},ang={["class:Hunter"]="Мисливці, обізнані зі звірами Калімдору, одразу збагнуть, що гнізда в каньйоні ховають щось куди первісніше за звичайних пустельних змій.",["faction:Horde"]="Застава Вільного Вітру — головна застава Орди в Тисячі Голок, тож стримати нових верховних хижаків — першочергове завдання для захисту шляхів постачання.",["race:Tauren"]="Живучи над дном каньйону на Заставі Вільного Вітру, таурени покладаються на розуміння тендітної рівноваги живності внизу; чужий чи неприродний зміїний виводок прямо загрожує їхньому дому."},sec={{t="Дивне гніздо",b="До Застави Вільного Вітру дійшла звістка про незвичайне яйце, помічене глибоко в зміїних лігвах, якими поцятковане дно каньйону під високими кам'яними голками. Місцеві змії стережуть яйце, наче власний виводок, і кидаються на кожного мандрівника, що підійде надто близько. Зацікавлений і стривожений тим, що може загрожувати місцевим мисливським угіддям, Гаґар Лайтнінггуф просить сміливих розвідників знайти кладку, проминути повзучих вартових і забрати дивовижу для вивчення."},{t="Народження змієняти",b="Уважно оглянувши принесене яйце, Гаґар бачить, що це далеко не звичайна кладка плазуна. Щойно його беруть у руки, шкаралупа тріскає, і на волю виривається юна крилата потвора — Молода Арікара. Замість нападати, новонароджена істота злітає в небо, тікаючи з дерев'яних помостів Застави Вільного Вітру, — знак того, що у вітрах каньйону ворушаться куди глибші первісні сили."}},faq={{q="Де знайти Чужорідне Яйце?",a="Яйце лежить в одному з кількох зміїних гнізд, розкиданих біля підніжжя скель Тисячі Голок, — особливо на південь і північний схід від Застави Вільного Вітру. Воно лежить просто на дні каньйону серед ворожих місцевих змій.",al={"місце чужорідного яйця","де чужорідне яйце","поява яйця тисяча голок"}},{q="Чому місцеві змії його стережуть?",a="Хоча яйце належить особливому летючому змієві на ім'я Арікара, звичайні змії каньйону інстинктивно захищають його, мов власну кладку, і люто обороняють гніздо від будь-яких цікавих чужинців.",al={"чому змії охороняють яйце","поведінка змій чужорідного яйця"}},{q="Хто такий Гаґар Лайтнінггуф?",a="Гаґар Лайтнінггуф — тауренський розвідник і охоронець на вершині Застави Вільного Вітру в Тисячі Голок. Він стежить за незвичними пересуваннями й загрозами для природи на дні каньйону й координує зусилля Орди, щоб давати раду місцевим звірам.",al={"лор гаґара лайтнінггуфа","хто дає завдання гаґар"}},{q="Що стається, коли доставити яйце?",a="Коли Гаґар береться оглядати яйце, воно тріскається, і з нього вилуплюється Молода Арікара. Крилатий змій на мить лякає Гаґара, а тоді злітає й зникає в небі над Тисячею Голок.",al={"що вилупиться з яйця","що всередині яйця"}},{q="До чого веде це завдання?",a="Доставка яйця починає ланцюжок про Арікару й одразу веде до завдання «Дикі змії», де Гаґар прагне зрозуміти природу дивних крилатих змій, що з'являються в каньйоні.",al={"наступне завдання після чужорідного яйця","наступний крок арікара"}},{q="Чи яйце буквально з іншого світу?",a="Тут «чужорідне» означає щось цілком чуже, неприродне й незнайоме місцевій природі Тисячі Голок, а не істоту, що прилетіла з зірок. Яйце належить легендарному вітряному змієві Арікарі.",al={"чи яйце з іншого світу","чи яйце чужорідне"}}},fp="9,260,14.474.0,21.400.1,33.237.0,39.227.1,27.240.0,38.191.1,29.189.1,38.216.1"}
P.entries["quest:483"] = {n="Реліквії Пробудження",s="«Реліквії Пробудження» — нагальна рятувальна місія: врятувати Друїдів Кігтя, що сплять у Курганному Лігві Бан'етіл. Зіпсуті фурболґи Вузлошкіри захопили священні кургани й загрожують сплячим друїдам, чиї духи блукають Смарагдовим Сном. Без чотирьох особливих ритуальних реліквій сплячих не вдасться безпечно повернути до світу яви.",h="«Реліквії Пробудження» — нагальна рятувальна місія: врятувати Друїдів Кігтя, що сплять у Курганному Лігві...",kw={"реліквії пробудження","друїди кігтя","курганне лігво бан'етіл","вузлошкіри","атрідас бермантл","смарагдовий сон"},ang={["class:Druid"]="Для юних друїдів напад на Бан'етіл — прямий удар по братах із Кола Кенарія. Здобувши реліквії, ви доводите свій обов'язок берегти священний міст між смертною землею і Смарагдовим Сном.",["race:NightElf"]="Осквернення курганного лігва на самому гіллі Тельдрассила підкреслює, з якою тривожною швидкістю зіпсуття спотворює плем'я Вузлошкірів і розхитує рівновагу вашої нової домівки."},sec={{t="Осквернене святилище",b="Курганні лігва — відлюдні святилища, де друїди нічних ельфів лежать у глибокому сні, блукаючи Смарагдовим Сном. На захід від Доланаара звивисті коридори Курганного Лігва Бан'етіл опинилися під навалою зіпсутих фурболґів Вузлошкірів. Доведені до безумства мерзенною скверною, що шириться Тельдрассилом, ці колишні союзники осквернили святилище й загрожують беззахисним сплячим, які й не підозрюють про небезпеку, що нависла над їхніми тілами."},{t="Знаряддя повернення",b="Друїда, що зайшов у Сон, не можна просто розбудити струсом: грубо урвати його сон без належного духовного якоря означає розтрощити розум або назавжди лишити дух у блуканні. Щоб провести тонкий обряд пробудження, Атрідасові Бермантлу потрібні чотири священні реліквії, замкнені у скринях по всьому лігву: Талісман Воронячого Пазура, Чорне Перо, Сапфір Небес і Руна Гніздування. Повернути їх — єдина надія розбудити Друїдів Кігтя, перш ніж Вузлошкіри переріжуть або викрадуть їх усіх."}},faq={{q="Чому друїдів не можна просто розштовхати?",a="Друїдська сплячка — дуже тонкий транс, що поєднує смертне тіло зі Смарагдовим Сном. Якщо будити друїдів неправильно чи без захисних обрядів Реліквій Пробудження, їхня свідомість може назавжди застрягнути в Сні, відірвана від тіла.",al={"чому потрібні реліквії","чому ритуал пробудження","чому реліквії необхідні"}},{q="Хто такі Друїди Кігтя?",a="Це друїди нічних ельфів, налаштовані на сили Авіани: вони здатні обертатися на штормових круків і керувати вітрами. Багато з них поринули в глибоку медитацію в курганних лігвах Тельдрассилу, щоб спілкуватися з духами природи й зцілювати новонароджене дерево.",al={"друїди кігтя","друїди кігтя лор","хто спить у бан'етіл"}},{q="Чому фурболги-Вузлошкіри нападають на курганне лігво?",a="Плем'я Вузлошкірів стало жертвою темної скверни, що поступово отруює звірів і ліси Тельдрассилу. Колись мирні сусіди нічних ельфів, тепер, зі зіпсованим розумом, вони стали жорстокими й наводнюють давні святилища на кшталт Бан'етілу.",al={"чому фурболги в лігві","напади вузлошкірів","чому фурболги агресивні"}},{q="Які чотири реліквії треба повернути?",a="Атрідас Бермантл доручає шукачам пригод зібрати Талісман Воронячого Пазура, Чорне Перо, Сапфір Небес і Руну Гніздування — кожна зберігається у священній скрині в Курганному Лігві Бан'етіл.",al={"які реліквії","потрібні реліквії","назви реліквій"}},{q="Хто такий Атрідас Бермантл?",a="Атрідас — нічний ельф із Доланаару, що стежить за духовним здоров'ям довколишньої глушини й організовує протидію раптовій скверні, яка вразила фурболгів-Вузлошкірів і курганні лігва.",al={"атрідас бермантл","хто дає завдання доланаар"}},{q="Де розташоване Курганне Лігво Бан'етіл?",a="Курганне Лігво Бан'етіл прорите в пагорбах просто на захід від поселення Доланаар на гіллі Тельдрассилу.",al={"місце бан'етіл","де бан'етіл","де лігво"}}},fp="22,369,17.479.0,19.520.0,42.283.0,32.253.0,56.265.0,41.207.0,27.214.0,38.120.0"}
P.entries["quest:484"] = {n="Шкури молодих кроколісків",s="Джеймс Галлоран, знаний чинбар із Гавані Менетіл, наймає мандрівників, щоб ті постачали свіжі шкури молодих болотяних кроколісків. Його вичинені шкури мають попит за морем, тож надійне полювання — основа його ремесла. Постачаючи йому цей м'якший матеріал, ви здобуваєте його довіру й відкриваєте шлях до нових шкіряних доручень.",h="Джеймс Галлоран, знаний чинбар із Гавані Менетіл, наймає мандрівників, щоб ті постачали свіжі шкури молодих...",kw={"шкури молодих кроколісків","джеймс галлоран","кроколіски","гавань менетіл","чинбарство","багнокрай"},ang={["class:Hunter"]="Для мисливців, що мандрують Багнокраєм, прохання Галлорана — звична польова робота: добути чисті шкури місцевих хижаків, не зіпсувавши шкіри.",["faction:Alliance"]="Підтримуючи морську торгівлю Гавані Менетіл, ви бережете безперебійні шляхи постачання й вивезення товарів через Велике Море."},sec={{t="Експорт гавані",b="Гавань Менетіл — важливий морський вузол, що з'єднує Східні Королівства з далекими континентами, але вона також живить жваве місцеве господарство, збудоване на багатствах довколишніх боліт. Джеймс Галлоран налагодив торгівлю з іншими краями, вичиняючи цупкі шкури численних хижих плазунів. Купці й кораблі, що відпливають із Менетіла, везуть шкіряні вироби Галлорана до далеких портів, тож його майстерня повсякчас мусить мати запас товару."},{t="Полювання на болотяний молодняк",b="Досвідчені звіролови на кшталт Ейнара регулярно привозять шкури дорослих звірів, але для особливих розкішних виробів потрібна куди м'якша шкіра, ніж можуть дати дорослі болотяні кроколіски. Щоб заповнити цю нестачу, Галлоран покладається на мандрівних шукачів пригод, які забредуть у мілкі болота просто за частоколом Менетіла. Щоб добути цілі шкури молодих звірів, полювати треба обережно — тоді шкури витримають прискіпливу вичинку Галлорана."}},faq={{q="Хто такий Джеймс Галлоран?",a="Джеймс Галлоран — майстер-чинбар із Гавані Менетіл. Його вичинені шкури кроколісків славляться по всьому світу, і їх регулярно відправляють через Велике Море до чужоземних портів.",al={"лор джеймса галлорана","хто шкіряр","галлоран менетіл"}},{q="Чому Галлоранові потрібні саме шкури молодих кроколісків?",a="Дорослі кроколіски дають міцну, важку шкіру для обладунків, а в молодих шкура набагато м'якша й податливіша. Такі ніжні шкури незамінні для особливих розкішних виробів і тонкої шкіряної роботи, для якої шкури дорослих надто жорсткі.",al={"чому молоді кроколіски","м'якіша шкура","призначення шкур кроколісків"}},{q="Хто такий Ейнар?",a="Ейнар — місцевий мисливець у Багнокраї, що працює безпосередньо з Джеймсом Галлораном. Він раз у раз ходить на болота полювати на диких кроколісків і постачає майстерню в гавані сирими шкурами.",al={"ейнар вологі землі","мисливець ейнар","лор ейнара"}},{q="Де водяться молоді кроколіски?",a="Молоді кроколіски живуть у протоках, очеретах і болотистих мілинах одразу довкола Гавані Менетіл, за міською брамою й причалами.",al={"місця кроколісків","де молоді кроколіски","молоді кроколіски вологих земель"}},{q="Що буде, коли принести шкури Галлоранові?",a="Вражений якістю шкур, Галлоран одразу просить допомогти з іншими справами в його чинбарні й доручає вам звичні обов'язки учня, щоб майстерня працювала далі.",al={"продовження завдання","наступне завдання після шкур","наступна задача галлорана"}},{q="Чому шкіра кроколісків така цінна в Гавані Менетіл?",a="Гавань Менетіл — жвавий торговий порт, що пов'язує Айронфордж і Стормвінд із заморськими землями на кшталт Калімдору. Незвичайні непромокальні болотні шкури, вичинені вправними майстрами, високо цінують купці й моряки, що заходять у гавань.",al={"торгівля шкірою менетіл","цінність шкір кроколісків"}}},fp="21,342,17.508.0,31.463.0,22.181.0,58.246.0,13.196.0,39.145.0,50.201.0,53.240.0"}
P.entries["quest:4841"] = {n="Утихомирити кентаврів",s="«Утихомирити кентаврів» — каральний похід, який оголошує Скельний Вартовий Лонггорн на вершині Застави Вільного Вітру. Маючи завдання усунути загрозу, що збирається під шпилями каньйону, шукачі пригод з Орди вдаряють углиб таборів кентаврів Ґалак на Кручі Розколотого Копита.",h="«Утихомирити кентаврів» — каральний похід, який оголошує Скельний Вартовий Лонггорн на вершині Застави...",kw={"утихомирити кентаврів","кентаври ґалак","круча розколотого копита","скельний вартовий лонггорн","застава вільного вітру","тисяча голок"},ang={["faction:Horde"]="Застава Вільного Вітру — життєво важлива опора Орди, що пов'язує Південні Пустки, Великий Підйомник і мерехтливі солончаки. Лишити войовничих кентаврів під її вежами — наразити на небезпеку кожен караван, що перетинає цей край.",["race:Tauren"]="Для шу'гало табори кентаврів, що підступають до поселення, пробуджують пам'ять про різанину, яка тягнеться поколіннями. Прорідити Ґалаків — питання самого виживання народу."},sec={{t="Загроза на дні каньйону",b="Застава Вільного Вітру на хиткій пустельній столовій горі дає тауренам чудовий огляд дна каньйону Тисячі Голок. Та висота мало важить, коли вороги збираються просто під канатами й підйомниками. Кентаври Ґалак розбили розлогий бойовий табір просто на північ, під стіною каньйону, на Кручі Розколотого Копита, — і прямо загрожують шляхам постачання й пересуванню тауренів між скельними голками."},{t="Відплата й кровопролиття",b="Щоб протистояти дедалі більшій загрозі, Скельний Вартовий Лонггорн посилає вправних мандрівників з Орди безжально прорідити лави Ґалаків. Таурени вірять, що мало просто боронити підйомники: єдиний спосіб уберегти Заставу Вільного Вітру — зламати передовий загін кентаврів у їхньому ж таборі. Знищення розвідників, приборкувачів звірів і містиків-вітроловів має притупити будь-який злагоджений напад на заставу ще до його початку."}},faq={{q="Хто дає завдання «Утихомирити кентаврів»?",a="Завдання дає Скельний Вартовий Лонггорн на вершині Застави Вільного Вітру в Тисячі Голок. Він один із головних захисників застави й стежить за небезпеками, що чатують на довколишніх солончаках і в каньйонах.",al={"хто дає утихомирити кентаврів","хто починає утихомирити кентаврів","кліфвочер лонггорн"}},{q="Де отаборилися кентаври Ґалак?",a="Кентаври Ґалак отаборилися просто на північ від Застави Вільного Вітру, під північною скельною стіною Тисячі Голок, у місцевості, відомій як Круча Розколотого Копита.",al={"місце табору ґалак","де спліттхуф","місце кентаврів"}},{q="Чому таурени хочуть смерті кентаврів?",a="Кентаври здавна ведуть жорстоку винищувальну війну проти кочових тауренів у центральному Калімдорі. Коли клан Ґалак розбив передовий табір просто біля підніжжя Застави Вільного Вітру, Скельний Вартовий Лонггорн вимагає швидкої відплати, щоб уберегти твердиню Орди в пустелі.",al={"чому вбивати кентаврів","конфлікт тауренів і кентаврів","чому помста"}},{q="Яких кентаврів треба вбити?",a="Завдання вимагає вполювати дванадцять розвідників Ґалак, десять приборкувачів Ґалак і шістьох вітрогонів Ґалак із їхнього табору на Кручі Розколотого Копита.",al={"цілі ґалак","яких кентаврів вбити","цілі завдання"}},{q="Що йде після «Утихомирити кентаврів»?",a="Коли ряди Ґалак проріджено, Скельний Вартовий Лонггорн переводить увагу на інші загрози краю й посилає вас у наступне завдання — «Шпигунство Ґрімтотемів».",al={"наступне завдання","що після утихомирити кентаврів","ланцюжок після кентаврів"}},{q="Що передує цьому завданню?",a="Завдання відкривається після доставки в завданні «Послання до Застави Вільного Вітру», яке веде мандрівників просто до Скельного Вартового Лонггорна.",al={"передумова","попереднє завдання","як відкрити утихомирити кентаврів"}}},fp="18,257,28.442.0,25.431.0,39.201.0,36.159.0,42.290.0,39.146.0,47.165.0,43.144.0"}
P.entries["quest:486"] = {n="Урсал Гамаїло",s="«Урсал Гамаїло» — вінець зусиль Атрідаса Бермантла пробудити сплячих Друїдів Кігтя в Тельдрассилі. Щоб розірвати неприродний сон, який скував його братів у Курганному Лігві, треба вбити зіпсутого вождя фурболґів, винного в тому, що їхній поклик урвався.",h="«Урсал Гамаїло» — вінець зусиль Атрідаса Бермантла пробудити сплячих Друїдів Кігтя в Тельдрассилі.",kw={"урсал гамаїло","вузлошкіри","друїди кігтя","атрідас бермантл","ущелина","тельдрассил","смарагдовий сон"},ang={["class:Druid"]="Зберегти священні обряди Смарагдового Сну — понад усе. Втручання Урсала у справи Друїдів Кігтя — тяжке осквернення єднання Кола Кенарія.",["faction:Alliance"]="Убезпечення внутрішніх доріг Тельдрассила й відновлення кола друїдів зміцнює твердиню нічних ельфів, поки вони вливаються до ширшого Альянсу.",["race:NightElf"]="Фурболґи Вузлошкіри колись були давніми союзниками калдорей. Убити їхнього знавіснілого ватажка Урсала — трагічна необхідність, щоб захистити ваших родичів і сплячих друїдів."},sec={{t="Сон, що став жахіттям",b="Друїди Кігтя усамітнилися в Курганному Лігві Бан'етіл, щоб спати й єднатися зі Смарагдовим Сном. Та їхній мирний транс обернувся на в'язницю без виходу. Атрідас Бермантл визначив, що саме фурболґи Вузлошкіри — а надто їхній лютий ватажок Урсал Гамаїло — втрутилися у священний обряд друїдів і лишили їх у пастці між явою і Сном."},{t="Лігво в Ущелині",b="Зібрати Реліквії Пробудження було лише половиною справи. Щоб обряд пробудження Атрідаса пробився крізь духовний туман, що скував друїдів, джерело втручання треба було погасити. Урсал Гамаїло влаштував собі лігво глибоко в Ущелині — запалій, зіпсутій розколині на північ від головної дороги через Тельдрассил. Здолавши фурболґа-воєначальника, ви розриваєте його владу над розумом сплячих."},{t="Симптом глибшої гнилі",b="Хоч смерть Урсала дає Атрідасові змогу провести обряд і врятувати Друїдів Кігтя, вона не лікує недуги Тельдрассила. Як зауважує Атрідас, коли ви повертаєтеся, дикий фурболґ лише діяв під впливом темнішого зіпсуття, що шириться гіллям Світового Дерева. Поразка Урсала звільняє сплячих, але першопричина безумства, яке труїть плем'я Вузлошкірів, і далі чаїться в тіні."}},faq={{q="Хто такий Урсал Гамаїло?",a="Урсал Гамаїло — лютий зіпсований вождь фурболгів-Вузлошкірів, що засів у Розколині на Тельдрассилі. Він утрутився в сон Друїдів Кігтя й замкнув їх у сплячці в Курганному Лігві.",al={"хто такий урсал","урсал лор","бос розколини"}},{q="Чому Урсала треба вбити, щоб розбудити друїдів?",a="Навіть зі священними Реліквіями Пробудження обряд Атрідаса Бермантла не подіє, поки Урсал живий. Мерзенне втручання фурболга діє як духовний якір, що не дає духам друїдів повернутися в тіла.",al={"чому вбити урсала","чому урсал має померти","призначення реліквій пробудження"}},{q="Де знайти Урсала Гамаїла?",a="Урсал має лігво в Розколині — зарослому яру на північний захід від Доланаару вздовж головної стежки, що відгалужується на північ від дороги до Дарнасуса.",al={"місце урсала","де розколина","як знайти урсала"}},{q="Чи смерть Урсала повністю рятує фурболгів-Вузлошкірів?",a="Ні. Смерть Урсала звільняє сплячих друїдів, але Атрідас попереджає, що темна скверна, яка вразила Вузлошкірів і ліси Тельдрассилу, лишається глибоко у Світовому Дереві.",al={"чи фурболгів врятовано","чи ми врятували фурболгів","чи тельдрассил врятовано"}},{q="Хто такі Друїди Кігтя?",a="Друїди Кігтя — гурт друїдів нічних ельфів, відданих тотему штормового крука й настановам Авіани. Вони поринули в глибокий сон у Курганному Лігві, щоб оберігати глушину зсередини Смарагдового Сну.",al={"друїди кігтя","хто спить","яких друїдів врятовано"}},{q="Хто такий Атрідас Бермантл?",a="Атрідас Бермантл — друїд нічних ельфів із Доланаару. Він посилає шукачів пригод повернути викрадені реліквії й знищити Урсала, щоб його братів можна було безпечно розбудити.",al={"атрідас бермантл","хто дає завдання атрідаса","хто дає завдання урсала"}}},fp="16,285,26.408.0,20.400.0,23.413.1,24.223.0,46.247.0,36.149.0,58.193.1,32.216.0,27.176.0"}
P.entries["quest:4865"] = {n="Дикі змії",s="«Дикі змії» — завдання Орди в Тисячі Голок, що пов'язує знахідку дивних чужорідних яєць із прадавніми легендами тауренів. Після тривожного відкриття на Заставі Вільного Вітру Гаґар Лайтнінггуф відсилає шукачів пригод на північний захід, до Мотеґи Фаєрмейна на Заставі Білого Рубежу, щоб протистояти пробудженню Арікари.",h="«Дикі змії» — завдання Орди в Тисячі Голок, що пов'язує знахідку дивних чужорідних яєць із прадавніми...",kw={"дикі змії","арікара","дух помсти","гаґар лайтнінггуф","мотеґа фаєрмейн","застава білого рубежу"},ang={["class:Shaman"]="Неспокій мстивих духів, як-от Арікари, показує тендітну рівновагу стихійних і духовних сил, що населяють столові гори каньйону.",["faction:Horde"]="Щоб тримати шляхи постачання через Тисячу Голок відкритими, треба впоратися з містичними загрозами, які можуть тероризувати дорогу між Великим Підйомником і Фераласом.",["race:Tauren"]="Пробудження Арікари обертає перекази на нагальну кризу й випробовує духовне опікунство тауренів, що боронять Тисячу Голок."},sec={{t="Легенда у плоті",b="Коли в Тисячі Голок почали з'являтися дивні, неприродні яйця, місцеві таурени злякалися лиха для природи. Та, оглянувши знахідки, вони побачили щось куди давніше й зловісніше за звичайних хижаків: ознаки, що вказують на духа помсти Арікару. Приголомшений цим жахливим підтвердженням, Гаґар Лайтнінггуф усвідомлює, що каньйонові загрожує міфічна сила, яку давно вважали лише казкою біля вогнища."},{t="Дорога до Білого Рубежу",b="Розуміючи, що проста оборона тут не допоможе, Гаґар закликає негайно порадитися з Мотеґою Фаєрмейном. Мотеґа, що перебуває на північному заході, на Заставі Білого Рубежу на дні каньйону, — вартовий і духовний провідник, обізнаний із традиційними прикметами Голок. Без його поради Орді не збагнути, як умилостивити чи знищити духа помсти, що пробуджується."}},faq={{q="Хто дає завдання «Дикі змії»?",a="Завдання дає Гаґар Лайтнінггуф на вершині Застави Вільного Вітру в Тисячі Голок — одразу після того, як ви дослідили дивні чужорідні яйця, знайдені по всьому каньйону.",al={"хто дає дикі змії","дає дикі змії","завдання гаґара лайтнінггуфа"}},{q="Де знайти Мотеґу Фаєрмейна?",a="Мотеґа Фаєрмейн — на Заставі Білого Рубежу, невеликому тауренському таборі при дорозі на північний захід від Застави Вільного Вітру, за розвилкою, що веде до Великого Підйомника.",al={"де мотега фаєрмейн","місце мотеґи фаєрмейна","знайти мотеґу"}},{q="Хто чи що така Арікара?",a="Арікара — легендарний дух вітряного змія, що втілює помсту в тауренських переказах; чутки про його появу в Тисячі Голок віщують тяжку духовну й фізичну загрозу для місцевих племен.",al={"що таке арікара","арікара лор","легенда арікари"}},{q="Яке завдання треба виконати перед цим?",a="Спершу треба виконати завдання «Чужорідне Яйце», де ви забираєте незвичайне яйце в диких звірів каньйону й приносите його Гаґарові Лайтнінггуфу на огляд.",al={"передумова диких змій","ланцюжок чужорідного яйця","розблокування диких змій"}},{q="Що буде, коли дістатися Мотеґи Фаєрмейна?",a="Розмова з Мотеґою відкриває завдання «Священний вогонь» — так починається підготовка до обряду, потрібного, щоб зійтися з духом Арікари.",al={"що після диких змій","продовження диких змій","завдання священного вогню"}},{q="Чому Гаґар Лайтнінггуф такий стривожений?",a="Гаґар вважав перекази про Арікару просто казками. Побачивши справжні ознаки того, що дух помсти з'явився в каньйоні, він нажаханий і негайно звертається по мудрість старійшин.",al={"чому гаґар стривожений","гаґар витирає чоло","реакція гаґара"}}},fp="12,308,19.406.0,22.383.0,34.176.0,33.163.0,23.190.0,60.162.0,44.126.0,38.200.0"}
P.entries["quest:487"] = {n="Дорога до Дарнасуса",s="Головна дорога, що з'єднує поселення Доланаар зі столицею нічних ельфів Дарнасусом, перебуває під постійною загрозою зіпсутих фурболґів Вузлошкірів. Місячна Жриця Амара координує розвідників і мандрівників, щоб уберегти цей важливий торговий і поштовий шлях від засідок.",h="Головна дорога, що з'єднує поселення Доланаар зі столицею нічних ельфів Дарнасусом, перебуває під постійною...",kw={"дорога до дарнасуса","місячна жриця амара","вузлошкіри","засідки","доланаар","дарнасус","тельдрассил"},ang={["class:Priest"]="Допомога Місячній Жриці Амарі — служіння Сестринству Елуни, яке дає молодому дереву і духовний провід, і ратний захист.",["faction:Alliance"]="Дарнасус — серце присутності Альянсу на півночі Калімдору; безпечний рух торгівлі й звісток його головним шляхом конче потрібен.",["race:NightElf"]="Вузлошкіри колись були шляхетною ріднею дикої природи; нищити зіпсутих засідників уздовж шляху до Дарнасуса — похмура необхідність, породжена хворобою Тельдрассила."},sec={{t="Життєва артерія в облозі",b="Дорога, що тягнеться на захід від Доланаара до Дарнасуса, — головна сухопутна артерія Тельдрассила. Нею щодня мають рухатися життєво важливі товари, політичні послання й мандрівники, щоб підтримувати зв'язок між столицею і гіллям великого дерева. Оскільки Тельдрассил ще молодий і дикий, безпечні дороги критично важливі для юних громад калдорей."},{t="Загроза Вузлошкірів",b="Плем'я фурболґів Вузлошкірів у Тельдрассилі — уже не мирні лісові мешканці: воно стало жертвою мерзенного зіпсуття. Збожеволілі від хвороби, що мучить гілля Світового Дерева, вони вдаряють назовні з потаємних лігв під хребтами. Нишпорячи вздовж узлісся при дорозі, засідники Вузлошкірів полюють на необачних кур'єрів і мандрівників, перетворюючи мирну лісову прогулянку на смертельний прохід крізь стрій."},{t="Варта Вартових",b="Щоб протистояти засідникам, Місячна Жриця Амара тримає варту за межами Доланаара. Поєднуючи духовний авторитет жрецтва Елуни з військовою пильністю Вартових, вона скеровує здібних шукачів пригод нищити засідників біля їхніх лігв нижче від дороги, щоб забезпечити безпечний шлях до брам Дарнасуса."}},faq={{q="Чому дорога між Доланааром і Дарнасусом така небезпечна?",a="Зіпсовані фурболги-Вузлошкіри облаштували лігва на низьких гребенях нижче дороги. Збожеволілі від скверни, що шириться Тельдрассилом, вони вискакують із хащів і влаштовують засідки на подорожніх, гінців і купців.",al={"чому нападають фурболги","напади вузлошкірів на дорозі","чому дорога небезпечна"}},{q="Хто така Місячна Жриця Амара?",a="Місячна Жриця Амара — інколи її називають повним ім'ям, вартова Амара Найтвокер, — командирка нічних ельфів на західній околиці Доланаару. Вона відповідає за безпеку шляху й координує бойові дії проти загрози Вузлошкірів поблизу.",al={"хто дає дорогу до дарнасуса","амара","хто така амара"}},{q="Чому фурболги-Вузлошкіри агресивні?",a="Фурболги здавна були союзниками й мирними сусідами калдорей. Але плем'я Вузлошкірів на Тельдрассилі спотворила дивна недуга, що вразила Світове Дерево, — їхній розум став жорстоким, і вони нападають на кожного, хто заходить до лісу.",al={"чому вузлошкіри злі","скверна фурболгів тельдрассил","чи вузлошкіри злі"}},{q="Де ховаються нападники?",a="Нападники засіли під кручами й виступами одразу біля головної дороги на захід від Доланаару, звідки з лігв можуть стрибати на подорожніх, що йдуть до Дарнасуса.",al={"де засідка вузлошкірів","знайти нападників","місце лігва нападників"}},{q="Чому Дарнасус не пошле цілий гарнізон вартових очистити дорогу?",a="Вартові розпорошені по всьому Тельдрассилу: вони борються з грелами, зіпсованими деревляниками й загрозами на узбережжі. Офіцерам на кшталт Амари доводиться покладатися на вправних мандрівників і добровольців, щоб тримати внутрішні шляхи вільними.",al={"де вартові","чому вартовим потрібна допомога","патруль дарнасу"}},{q="Чому Амару називають і Місячною Жрицею, і вартовою?",a="У суспільстві калдорей сестринство Елуни й військо вартових тісно переплетені. Провідниці жрецтва часто командують загонами вартових або все життя воювали на передовій.",al={"ранг амари","жриця чи вартова амара","титул амари"}}},fp="21,269,22.385.0,20.418.0,20.319.0,60.230.0,28.272.0,42.264.0,31.172.0,70.246.0,57.234.0"}
P.entries["quest:488"] = {n="Доручення Зенна",s="«Доручення Зенна» — завдання Альянсу від Зенна Фаулгуфа, самотнього сатира, що чаїться на північ від дороги між Тінедолом і Доланааром. Він підбиває завзятих шукачів пригод полювати на місцеву живність і збирати для його невідомих задумів частини звірів, користаючись із довірливості й наївності новачків на Тельдрассилі.",h="«Доручення Зенна» — завдання Альянсу від Зенна Фаулгуфа, самотнього сатира, що чаїться на північ від дороги...",kw={"доручення зенна","зенн фаулгуф","сатир","обман","нічні шаблезуби","тінедол","доланаар"},ang={["class:Druid"]="Друїди присягнули берегти рівновагу природи. Браконьєрство на нічних шаблезубів, сов і павуків на догоду спотвореному створінню зіпсуття — наруга над ученням Кола Кенарія.",["race:NightElf"]="Для юного нічного ельфа виконувати накази сатира — глибока ганьба. Сатири — зрадники предків, зіпсуті Палаючим Легіоном, і допомагати одному з них на гіллі Тельдрассила — злочин проти природи й спадщини калдорей."},sec={{t="Сумнівна угода",b="Мандрівники, що виходять із Тінедола стежкою до Доланаара, можуть натрапити на Зенна Фаулгуфа, який невимушено стоїть під гіллям Великого Дерева. Замість відкритої ворожості сатир обіцяє щедру винагороду й таємниці в обмін на буденні доручення. Він просить шукачів пригод добути ікла нічних шаблезубів, пера сов-стригідів і шовк павуків Вебвуда з навколишніх лісів, змовницьки шепочучи, щоб домовленість лишилася між ними."},{t="Жарт сатира",b="Сатири — давні вороги калдорей, спотворені демонічною магією під час Війни Прадавніх, тож сама присутність Зенна на Тельдрассилі — зухвалість. Довірливі шукачі пригод, виконавши його доручення, швидко виявляють, що з них поглузували. Замість скарбів чи глибоких одкровень Зенн відверто регоче з того, яким легковірним треба бути, щоб служити сатирові, і тішиться, що обдурив наївного чужинця й змусив його зробити брудну роботу."}},faq={{q="Хто такий Зенн Фаулгуф?",a="Зенн Фаулгуф — хитрий сатир, що чатує біля стежки на захід від Тінедолу дорогою до Доланаару. На відміну від більшості сатирів, що нападають, щойно побачать, Зенн улесливими словами й фальшивими обіцянками змушує наївних мандрівників виконувати для нього доручення.",al={"зенн","зенн фаулгуф лор","сатир дає завдання"}},{q="Чому сатир дає завдання на Тельдрассилі?",a="Зенн удає миролюбного, щоб ошукати новачків, які ще не розуміють підступної, зіпсованої природи сатирів. Він користується їхнім завзяттям до роботи й жагою срібла, щоб зібрати реагенти, на які сам не може відкрито полювати, не накликавши гніву вартових.",al={"чому сатир дружній","чому я можу говорити з зенном","сатир на тельдрассилі"}},{q="Що Зенн робить з іклами, пір'ям і шовком?",a="Зенн стверджує, що ці частини — реагенти для його таємничих «справ у лісі». Насправді ж він тішиться владою над смертними й використовує їхню працю для своїх темних цілей, потай глузуючи з їхньої легковірності.",al={"навіщо шовк зенну","реагенти зенна","навіщо частини тварин"}},{q="Чому нічним ельфам не варто довіряти Зеннові Фаулгуфу?",a="Сатири колись були нічними ельфами, яких десять тисяч років тому, під час Війни Прадавніх, перетворила демонічна сила Палаючого Легіону. Вони — давні заприсягнені вороги калдорей і носії скверни, тож будь-яка угода з ними небезпечна й ганебна.",al={"чому ненавидять сатирів","історія нічних ельфів і сатирів","чи сатири злі"}},{q="Що буде після завдання «Доручення Зенна»?",a="Отримавши речі, Зенн відкрито глузує з вас за те, що ви були такі дурні, що послухалися сатира. Усвідомивши обман і ганьбу допомоги такій істоті, шукачі пригод мусять шукати спокути за свою помилку.",al={"після доручення зенна","завдання шукай спокути","що далі після зенна"}},{q="Де знайти Зенна Фаулгуфа?",a="Він на Тельдрассилі, трохи на північ від головної дороги, що веде з Тінедолу на захід, до Доланаару.",al={"місце зенна фаулгуфа","де зенн","мапа зенна"}}},fp="14,313,17.484.0,16.443.1,21.242.0,43.271.0,53.232.0,46.278.0,45.230.1,31.116.0"}
P.entries["quest:4881"] = {n="Змова вбивць",s="«Змова вбивць» — завдання Орди, що починається з перехоплених наказів кентаврів у Тисячі Голок. Накази розкривають, що на таурена Канаті Ґрейклауда в його мисливському таборі біля Застави Білого Рубежу готується напад.",h="«Змова вбивць» — завдання Орди, що починається з перехоплених наказів кентаврів у Тисячі Голок.",kw={"змова вбивць","канаті ґрейклауд","застава білого рубежу","кентаври","накази","тисяча голок"},ang={["faction:Horde"]="Застава Білого Рубежу — невеликий форпост Орди на південний захід від Великого Підйомника, тож від того, чи виживе Канаті, залежить нагляд за Тисячею Голок.",["race:Tauren"]="Ворожнеча з кентаврами глибоко вкорінена в пам'яті тауренів. Захист Канаті Ґрейклауда на Заставі Білого Рубежу — пряме продовження давньої боротьби за те, щоб уберегти рівнини й каньйони Калімдору від агресії кентаврів."},sec={{t="Мисливець на ворожій землі",b="Тисяча Голок здавна була спірним краєм, де панують ворожі між собою клани кентаврів і небезпечна звірина. Коли сміливець-таурен Канаті Ґрейклауд розбив мисливський табір на Заставі Білого Рубежу — невеликій заставі на південний захід від Великого Підйомника, — місцеві кентаври сприйняли це як зухвале вторгнення на свою землю. Замість просто розганяти дичину, кентаври вирішили знищити Ґрейклауда, щоб відбити в Орди охоту просуватися каньйоном далі."},{t="Перехоплені накази",b="Змова виходить на світло, коли мандрівник знаходить письмове розпорядження з планом кентаврів. У записці прямо названо Канаті Ґрейклауда: вона ганить його зухвалість і наказує ударному загонові зійтися на Заставі Білого Рубежу, щоб знищити табір і кожного, хто наважиться піти слідом за ним. Доставлене Канаті послання попереджає мисливця, і він одразу готується дати відсіч нападникам."}},faq={{q="Що це за змова вбивць?",a="Це злагоджена засідка, яку місцеві кентаври готують на Канаті Ґрейклауда — таурена, що облаштував мисливський табір на Заставі Білого Рубежу в Тисячі Голок. Кентаври хочуть його смерті, щоб не дати Орді закріпитися в каньйоні.",al={"огляд змови вбивць","про що це завдання","змова кентаврів"}},{q="Хто такий Канаті Ґрейклауд?",a="Канаті Ґрейклауд — таурен, що облаштував мисливський табір на Заставі Білого Рубежу, невеликому посту на південний захід від Великого Підйомника в Тисячі Голок. Табір так близько до каньйонів кентаврських кланів робить його головною мішенню.",al={"хто такий канаті","канаті ґрейклауд","нпц застави білого рубежу"}},{q="Чому кентаври хочуть убити Канаті?",a="Кентаври вважають присутність Канаті на Заставі Білого Рубежу нестерпним вторгненням у Тисячу Голок. Вони хочуть убити його, щоб знищити мисливський табір і відбити охоту в майбутніх розвідників Орди осідати в краї.",al={"чому вбити канаті","мотив кентаврів","чому кентаври нападають"}},{q="Де Застава Білого Рубежу?",a="Застава Білого Рубежу — невеликий тауренський табір у Тисячі Голок, на дні каньйону на південний захід від Великого Підйомника.",al={"місце застави білого рубежу","де табір канаті","де білий рубіж"}},{q="Чи можуть гравці Альянсу виконати це завдання?",a="Мандрівники з Альянсу теж можуть знайти Записку про Вбивство, але передати попередження не зможуть: Канаті Ґрейклауд — таурен з Орди, і донести звістку йому може тільки Орда.",al={"чи альянс може це","записка про вбивство альянс","здати альянс"}},{q="Що буде, коли Канаті попереджено?",a="Отримавши попередження, Канаті відмовляється тікати. Натомість він готується відбивати напад — і це веде просто до оборони Застави Білого Рубежу, коли прибуває бойовий загін кентаврів.",al={"що далі","наступне завдання","захистити канаті"}}},fp="18,223,25.461.0,22.410.1,31.238.0,24.215.0,39.219.0,25.128.0,41.167.0,36.194.1"}
P.entries["quest:489"] = {n="Шукай спокути!",s="«Шукай спокути!» — завдання, яке в Доланаарі дають шукачам пригод, що дали себе обдурити й зробили брудну роботу за сатира Зенна Фаулгуфа. Рада Лісу вимагає покаяння за шкоду лісовим звірам і посилає вас обхитрити підступного сатира — підсунути йому зіпсуті шишки Скверни.",h="«Шукай спокути!» — завдання, яке в Доланаарі дають шукачам пригод, що дали себе обдурити й зробили брудну...",kw={"шукай спокути","зенн фаулгуф","сатир","рада лісу","шишки скверни","жаба","доланаар"},ang={["class:Druid"]="Друїди вважають рівновагу Тельдрассила священною; полювати на хижаків і падложерів за наказом вигнанця, заплямованого демонами, — пряме порушення заповідей опіки Кола Кенарія.",["race:NightElf"]="Для калдорей допомагати сатирові — глибоке приниження. Сатири — давні вороги, спотворені Палаючим Легіоном під час Війни Прадавніх, тож спокута перед Радою Лісу — справа честі всього народу."},sec={{t="Виправлена помилка",b="Зенн Фаулгуф, самотній сатир, що чаїться одразу за Доланааром, обманом змушує перехожих виконувати його волю. Шукачі пригод, які мимоволі вирізали нічних шаблезубів, сов-стригідів і павуків Вебвуда задля його збочених апетитів, незабаром накликають на себе гостре невдоволення Ради Лісу. Рада не терпить наруги над природою — а надто від власних союзників."},{t="Ціна спокути",b="Хто б не застеріг вас — Сірал Блейдліф, Вартова Кіра Старсонг чи Вартова Шайла Найтбріз, — суть одна: щоб лишатися бажаним гостем на Тельдрассилі, треба загладити провину. Замість іти на Фаулгуфа з голою сталлю, охоронці Доланаара велять вам скористатися його ницою ненажерливістю. Зібравши з лісової підстилки роздуті зіпсуті шишки Скверни, ви пригощаєте нічого не підозрюване створіння його ж мерзенними ліками."},{t="Квакуча відплата",b="Удаючи ще одного вірного посильного, що приніс солодкий гостинець, ви вручаєте Фаулгуфові отруйні шишки. Не здогадуючись про друїдську пастку, що зімкнулася довкола нього, Зенн жадібно поглинає підношення — і тут-таки обертається на безпорадну жабу, позбавлену своїх підлих задумів і принижену перед дикою природою, яку хотів осквернити."}},faq={{q="Чому Рада Лісу на мене гнівається?",a="Ви взялися за попереднє доручення Зенна Фаулгуфа й винищували місцевих звірів — нічних шаблезубів, сов і павуків, — щоб догодити примхам сатира. Рада вважає безглузде вбивство створінь природи оскверненням Тельдрассилу й вимагає спокути, щоб ви зберегли добре ім'я.",al={"чому рада лісу гнівається","навіщо спокута","чому мені потрібна спокута"}},{q="Хто може дати мені це завдання?",a="Це завдання пропонують кілька охоронців у Доланаарі й довкола нього, щойно ви допоможете Фаулгуфу. Можна поговорити із Сіралом Блейдліфом біля північної оселі, з Вартовою Кірою Старсонг у заїзді або з Вартовою Шайлою Найтбріз на західній дорозі.",al={"хто дає завдання","хто починає шукай спокути","де взяти шукай спокути"}},{q="Що таке шишки скверни?",a="Шишки скверни — зіпсоване соснове насіння, що падає з покручених гілок довкола Тельдрассилу. Їх легко впізнати за моторошною зеленою парою, що клубочиться з лушпиння; у них мерзенна магія, яку друїди обертають проти необачних лиходіїв.",al={"шишки скверни","що таке шишка скверни","звідки шишки скверни"}},{q="Навіщо пропонувати шишки скверни Зеннові Фаулгуфу?",a="Рада чекає, що ви провчите Фаулгуфа. Він сприйме зіпсовані шишки за невинний наїдок від того, хто вже раз виконав його доручення.",al={"навіщо давати шишки зенну","закуска фаулгуфа","хитрість зі шишкою"}},{q="Чому сатир живе так близько до Доланаару?",a="Зенн Фаулгуф тримається непомітно на галявині в улоговині одразу за поселенням, ховаючи свою злостиву натуру за фальшивою люб'язністю. Сатири по всьому Калімдору — давні слуги Палаючого Легіону, і присутність Зенна показує, як глибоко скверна проникла в молоде Світове Дерево.",al={"чому зенн біля доланаара","сатир у доланаарі","зенн фаулгуф лор"}},{q="Чи можна пропустити чи покинути це завдання, не зіпсувавши стосунків?",a="Так. Рада Лісу суворо дорікає вам за допомогу Фаулгуфу, але якщо ви не візьмете чи не виконаєте завдання, це не зашкодить вашій репутації в нічних ельфів Дарнасуса.",al={"втрата репутації","чи можна покинути шукай спокути","провалити шукай спокути"}}},fp="16,274,22.393.0,22.426.0,22.331.1,47.287.0,27.247.0,19.236.0,41.153.1,49.292.0,65.204.0"}
P.entries["quest:4904"] = {n="Нарешті вільні",s="«Нарешті вільні» — рятувальна місія на вітряних вершинах Шпиля Темної Хмари. Лакота Віндсонг, тауренка, яку тримає в полоні Арнак Ґрімтотем, потребує захисту, щоб утекти з твердині свого викрадача й повернутися до подруги, Талії Амбергайд, на Заставу Вільного Вітру.",h="«Нарешті вільні» — рятувальна місія на вітряних вершинах Шпиля Темної Хмари.",kw={"нарешті вільні","лакота віндсонг","арнак ґрімтотем","шпиль темної хмари","талія амбергайд","супровід"},ang={["faction:Horde"]="Орда вважає Заставу Вільного Вітру важливою твердинею на півдні Калімдору, тож свавілля й викрадення, які чинять Ґрімтотеми на Шпилі Темної Хмари, — нестерпна загроза для дороги.",["race:Tauren"]="Клан Ґрімтотем і далі показує зневагу до миру й єдності тауренського народу, виявляючи жорстокість у викраденнях і братовбивстві просто на очах у Застави Вільного Вітру."},sec={{t="Жорстоке викрадення",b="Войовнича присутність клану Ґрімтотем у Тисячі Голок не обмежується сутичками за землю. Арнак Ґрімтотем хотів узяти Лакоту Віндсонг за дружину, але коли вона відкинула його залицяння, він обрав насильство. Арнак повернувся вночі, вбив Лакотиного брата, коли той спробував її захистити, і потяг її на Шпиль Темної Хмари."},{t="Втеча зі Шпиля Темної Хмари",b="Шпиль Темної Хмари з його високими дерев'яними підвісними мостами над Тисячею Голок кишить ворожими воїнами-Ґрімтотемами. Супроводжуючи Лакоту, доведеться спускатися вниз, відбиваючи хвилю за хвилею розбійників-Ґрімтотемів, які прагнуть знову схопити її, перш ніж вона дістанеться дна каньйону."},{t="Гірке повернення",b="Безпечно спустившись зі шпиля, Лакота повертається під захист Застави Вільного Вітру. Її подруга, Талія Амбергайд, зустрічає звістку з величезним полегшенням, але й з глибокою скорботою за загиблим братом Лакоти й віддає те, що лишилося з його речей, як знак вдячності тим, хто привів її додому живою."}},faq={{q="Чому Лакоту Віндсонг узяли в полон?",a="Арнак Ґрімтотем хотів одружитися з Лакотою Віндсонг. Коли вона відмовила, він уночі напав на її дім, убив її брата, що її захищав, і силоміць притяг її на Шпиль Темної Хмари.",al={"чому лакоту схопили","хто викрав лакоту","чому арнак забрав лакоту"}},{q="Де розташований Шпиль Темної Хмари?",a="Шпиль Темної Хмари — скупчення високих скельних шпилів, з'єднаних мостами, на півночі Тисячі Голок, трохи на південний схід від Великого Підйомника й на південь від Рейзорфен Даунс.",al={"місце шпиля темної хмари","як дістатися шпиля темної хмари","де лакота"}},{q="Хто такий Арнак Ґрімтотем?",a="Арнак — безжальний член племені Ґрімтотем, що засів на Шпилі Темної Хмари. Крім того, що він викрав Лакоту й убив її брата, він ще й злочинець, якого влада Орди на Заставі Вільного Вітру засудила на смерть.",al={"арнак лор","хто такий арнак","розшукується арнак"}},{q="До кого звернутися після порятунку?",a="Коли Лакоту безпечно виведено зі шпилів на дно каньйону, треба повернутися до Застави Вільного Вітру на високих кручах і поговорити з Талією Амбергайд.",al={"кому здати нарешті вільні","хто тала амберхайд","здати нарешті вільні"}},{q="Чому Ґрімтотеми нападають під час утечі?",a="Розбійники Ґрімтотем, що служать Арнакові, патрулюють висоти Шпиля Темної Хмари й люто нападають на кожного, хто допомагає бранці, яку він хотів узяти за дружину, вирватися на волю.",al={"чому нападають бандити","бандити ґрімтотемів супровід"}},{q="Що сталося з братом Лакоти?",a="Брат Лакоти загинув, захищаючи її від Арнака Ґрімтотема під час викрадення. Згодом Талія віддає його родинні реліквії як нагороду за порятунок його сестри.",al={"брат лакоти","хто загинув рятуючи лакоту","що сталося з братом лакоти"}}},fp="12,261,18.346.0,30.295.0,19.306.0,33.200.0,36.174.0,23.214.0,41.153.0,46.148.0,33.182.0"}
P.entries["quest:491"] = {n="Жезл для Бетора",s="Це завдання завершує сутичку у Фортеці Фенріс: давно загублену реліквію, Плетену Чарівну Паличку, треба повернути Беторові Айсшарду в Андерсіті. Паличку колись створили троє учнів-магів на знак братерства, а потім її сховали, коли Тул Рейвенклов обрав Погибель. Її повернення закриває гірку сторінку минулого Бетора.",h="Це завдання завершує сутичку у Фортеці Фенріс: давно загублену реліквію, Плетену Чарівну Паличку, треба...",kw={"жезл для бетора","плетена чарівна паличка","бетор айсшард","тул рейвенклов","фортеця фенріс","острів фенріс","магічний квартал"},ang={["class:Mage"]="Плетена Чарівна Паличка втілює давню магічну традицію: учні сплітали свої провідники на знак братерства — і ця безтурботність розбилася, коли Погибель розтрощила Даларан і Лордерон.",["race:Undead"]="Для магів-Відступників на кшталт Бетора знайдені артефакти часів до чуми — гірко-солодке нагадування про смертні поривання й про колишніх друзів, які обрали тиранію Короля-Ліча замість власної волі."},sec={{t="Знак розбитого братерства",b="Задовго до того, як Лордерон обернувся на руїни, троє молодих магів сплели свої учнівські палички в єдине знаряддя — Плетену Чарівну Паличку. Вона мала символізувати їхні спільні узи й поривання в магічних мистецтвах. Та коли Тул Рейвенклов присягнув на вірність Королю-Лічу й прийняв Погибель, це братерство розпалося безповоротно. Хоч Тул зненавидів давню дружбу, він не зміг ні знищити паличку, ні стерпіти, щоб вона лишилася в руках колишніх товаришів."},{t="Схована у фортеці",b="Замість віддати паличку чи знищити її, Тул відніс її на Острів Фенріс і сховав на запилюженій потайній полиці у Фортеці Фенріс. Роками ніхто її не торкався, і чари лишалися приспаними: Тул ніколи не пробуджував її магію, бо, як зауважив Бетор, це одразу виказало б її схованку. Повернути її до Магічного Кварталу Андерсіті — означає вернути рідкісну пам'ятку смертної юності Бетора, винесену з лігва зрадника, який не вмів ні любити друзів, ні відпустити їх."}},faq={{q="Що таке Плетена Чарівна Паличка?",a="Плетена Чарівна Паличка — унікальне магічне знаряддя, яке давно створили Тул Рейвенклов і двоє його товаришів-учнів, один з яких — Бетор Айсшард. Кожен поклав свою першу учнівську паличку, і їх сплели докупи як символ дружби й спільного вивчення тайних мистецтв.",al={"плетена паличка","що за паличка","лор палички тула"}},{q="Чому Тул Рейвенклов викрав паличку?",a="Коли Тул перекинувся на бік Короля-Ліча, зв'язок між колегами розпався. Хоча Тул зненавидів дружбу, яку символізувала паличка, він був надто власницьким, щоб розлучитися з реліквією чи лишити її Беторові й іншому товаришеві. Тож він викрав паличку й сховав її на Острові Фенріс.",al={"чому тул вкрав паличку","навіщо красти паличку","вкрадена паличка тула"}},{q="Хто такий Бетор Айсшард?",a="Бетор Айсшард — маг-наставник Відступників, що мешкає в Магічному Кварталі Андерсіті. За життя він був колегою й другом Тула Рейвенклова — до того, як королівство впало, а Тул віддав свою волю Погибелі.",al={"хто такий бетор","бетор айсшард лор","бетор андерсіті"}},{q="Чому Тул не користувався магією Плетеної Чарівної Палички?",a="Якби Тул хоч раз пробудив приспані чари палички, Бетор відчув би відлуння в тайному плетиві. Тул тримав її на забутій полиці у Фортеці Фенріс лише зі злоби й жадібності, так і не скориставшись її силою.",al={"чи тул користувався паличкою","сила палички","чому не користуватися"}},{q="Хто був третім учнем, що допомагав створити паличку?",a="Третім учнем був Ґунтер Арканус: він сплів паличку разом із Бетором і Тулом задовго до Тулової зради.",al={"третій учень","три маги паличка","третій маг"}},{q="Де опинилася паличка, перш ніж її знайшли?",a="Паличку сховали на запиленій полиці в потаємній ніші у Фортеці Фенріс — твердині на Острові Фенріс, де Тул Рейвенклов розгорнув діяльність Погибелі.",al={"де була паличка","схована ніша паличка","паличка фортеці фенріс"}}},fp="14,332,31.518.0,18.487.1,23.286.0,39.297.0,23.219.0,44.249.0,54.120.0,45.172.0"}
P.entries["quest:492"] = {n="Нова чума",s="Це завдання — похмура кульмінація початкових досліджень Аптекаря Йогаана у Бріллі від імені Королівського Аптекарського Товариства. Зібравши по всіх Галявинах Тірісфалю отруту, кров і мерзенні суміші, Йогаан посилає вас у підвал Таверни «Шибеничний Кінець» — випробувати його смертоносне вариво на полоненому дворфі-горянині.",h="Це завдання — похмура кульмінація початкових досліджень Аптекаря Йогаана у Бріллі від імені Королівського...",kw={"нова чума","йогаан","дворф","горянин","отрута","таверна","айронфордж"},ang={["faction:Alliance"]="Доля полоненого горянина показує абсолютну безжальність Відступників до зайд з Альянсу, викритих у Лордероні.",["faction:Horde"]="Поки ваші союзники з Калімдору б'ються за честь і виживання, Відступники йдуть до перемоги через холоднокровну алхімічну війну, що не щадить ні друга, ні ворога.",["race:Dwarf"]="Нещасний бранець утілює далекосяжну присутність Горян Айронфорджа, які ризикують смертю й таємними допитами, щоб наглядати за Галявинами Тірісфалю.",["race:Undead"]="Виконання експерименту Йогаана дає з перших рук побачити безкомпромісну доктрину виживання Відступників і смертоносну працю Королівського Аптекарського Товариства."},sec={{t="Смертельна суміш",b="Увесь час, допомагаючи Аптекарю Йогаану, ви крок за кроком наближали створення смертельної отрути. Королівське Аптекарське Товариство переслідує амбітну й тіньову мету від імені Леді Сильвани Віндраннер: створити нову чуму, яка омине біологію нежиті, та знищить живих. На цьому останньому етапі Йогаан варить те, що евфемістично називає «особливим напоєм», і доручає вам власноруч дати його ув'язненому ворогові Відступників."},{t="Підвал «Шибеничного Кінця»",b="Під Таверною «Шибеничний Кінець» у Бріллі Вартові Смерті тримають вогкий підвал — саморобну камеру для бранців, що чекають на допит чи ліквідацію. Серед них сидить полонений Дворф-Горянин, боєць розвідувальних загонів Айронфорджа, який незаконно проник у Галявини Тірісфалю. Непокірний і спраглий, він радо приймає напій, навіть не підозрюючи про його справжнє алхімічне начиння."},{t="Моторошна демонстрація",b="Отримавши пляшку, горянин охоче п'є, з тугою порівнюючи напій із Солодом Рапсодії й вихваляючись, що дворфійські парові танки вже йдуть його рятувати. Отрута діє майже миттєво і вбиває його на місці. Прощальні слова Йогаана звучать із моторошною ясністю: цей смертельний ковток — лише проба того, що Темна Леді готує решті Азероту."}},faq={{q="Хто такий Аптекар Йогаан?",a="Аптекар Йогаан — член Королівського Аптекарського Товариства в містечку Брілл у Галявинах Тірісфалю. Він керує першими дослідженнями зі створення нової чуми для війни Відступників і наймає шукачів пригод, щоб ті збирали смертоносні реагенти в довколишній глушині.",al={"аптекар йогаан","хто дає нову чуму","блиск йогаана"}},{q="Чому в Бріллі сидить полонений дворф?",a="Горяни Айронфорджа активно розвідують північні королівства, стежачи за пересуваннями Відступників і досліджуючи Чумні Землі. Вартові Смерті схопили цього розвідника в Тірісфалі й замкнули в льоху таверни, доки аптекарі не знайдуть йому застосування.",al={"дворф у льоху","полонений горянин","чому дворф у тірісфалі"}},{q="Що стається, коли дати полоненому напій?",a="Дворф охоче бере кухоль, прагнучи вгамувати спрагу після полону. За мить після першого ковтка отруйне вариво вбиває його на місці — доказ безжальної дієвості останньої Йогаанової формули чуми.",al={"чи дворф помре","результат напою","смерть горянина"}},{q="Яка мета досліджень Нової Чуми?",a="Відступники прагнуть створити нову чуму з наказу Леді Сильвани Віндраннер. Їхня мета — розробити біологічну зброю, досить потужну, щоб знищити і безтямну Погибель, і живі народи, що загрожують їхнім суверенним землям.",al={"мета нової чуми","мета королівського аптекарського товариства","чума темної пані"}},{q="Де знайти Полоненого Горянина?",a="Полонений Горянин сидить унизу, у льоху Таверни «Шибеничний Кінець» у центрі Брілла в Галявинах Тірісфалю.",al={"знайти полоненого дворфа","льох шибеничного кінця","де горянин"}},{q="Чи продовжується ланцюжок після цього дворфа?",a="Цей ланцюжок із чотирьох доручень Аптекаря Йогаана завершується смертю горянина. Але дослідження Нової Чуми лишаються головною справою по всьому Лордерону, і на вас чекають нові випробування в Андерсіті й Гробниці.",al={"наступне завдання","продовження нової чуми","після смерті горянина"}}},fp="12,317,19.467.0,23.389.0,24.367.1,25.277.0,39.263.0,50.226.1,47.243.0,42.138.0,49.258.0"}
P.entries["quest:493"] = {n="Подорож до Передгір'я Гілсбреда",s="«Подорож до Передгір'я Гілсбреда» — доручення гінця Орди, що пов'язує дослідження Відступників у Срібноліссі з їхньою заставою в Таррен Міллі. Отримавши делікатні записи Аптекаря Ренферрела, мандрівник вирушає на південь, у спірне Передгір'я Гілсбреда, щоб доставити важливі біологічні дослідження Аптекареві Лайдону. Це доручення показує, як сильно Леді Сильвана Віндраннер тисне на Королівське Аптекарське Товариство, вимагаючи зброї масового знищення.",h="«Подорож до Передгір'я Гілсбреда» — доручення гінця Орди, що пов'язує дослідження Відступників у Срібноліссі...",kw={"подорож до передгір'я гілсбреда","аптекар ренферрел","аптекар лайдон","таррен мілл","нова чума","срібнолісся","завдання"},ang={["faction:Horde"]="Хоча орки й таурени здебільшого не схвалюють підступних отрут, допомога у встановленні панування Відступників у Гілсбреді зміцнює плацдарм Орди в Східних Королівствах.",["profession:Herbalism"]="Дослідження і Ренферрела, і Лайдона значною мірою спираються на вивчення й збирання заразних, змутованих рослин із земель Лордерону.",["race:Undead"]="Для Відступників доставка цих знахідок — прямий внесок у виживання свого народу й помсту і живим, і Погибелі."},sec={{t="Власна чума",b="Відколи Леді Сильвана Віндраннер вирвалася із залізної хватки Короля-Ліча, вона плекає одну-єдину мету: створити Нову Чуму, що знищить і живих ворогів, і Погибель. Щоб досягти цього, Королівське Аптекарське Товариство працює під невпинним тиском Королеви Баньші. Оскільки лабораторії розкидані далеко одна від одної, дослідники по всьому Лордерону мусять постійно обмінюватися сирими хімічними даними й результатами випробувань, щоб пришвидшити свій зловісний прорив."},{t="Дорога на південь",b="Аптекар Ренферрел, що працює в Гробниці в Срібноліссі, посилає гінців доставити свої останні знахідки колезі, Аптекареві Лайдону. Шлях в'ється на південь крізь тінисті соснові ліси, повз мерехтливий магічний купол Даларана, і спускається до відкритих хвилястих пасовиськ Передгір'я Гілсбреда. Там, під Горами Альтерак, лежить Таррен Мілл — важливий осередок Відступників і плацдарм для їхніх лабораторій."}},faq={{q="Що в знахідках Ренферрела?",a="Знахідки Ренферрела — дослідницькі записи про його досліди з місцевими тваринами, рослинами й біологічними отрутами. Це частини ширшої формули, яку Королівське Аптекарське Товариство складає для своєї омріяної Нової Чуми.",al={"що знайшов ренферрел","дослідження ренферрела","що я доставляю"}},{q="Чому Королівське Аптекарське Товариство так поспішає?",a="Леді Сильвана Віндраннер вимагає негайних результатів. В оточенні ворожих решток людей, фанатичного Багряного Хрестового Походу й мандрівної Погибелі Відступники вірять, що лише рішуча біологічна зброя гарантує їм виживання й помсту Артасові.",al={"чому аптекарі поспішають","чому поспіх з чумою","тиск сильвани"}},{q="Хто такий Аптекар Лайдон?",a="Аптекар Лайдон — старший дослідник Королівського Аптекарського Товариства в Таррен Міллі. Його високо шанують колеги на кшталт Ренферрела; у Передгір'ї Гілсбреда Лайдон керує смертоносними біологічними дослідами, вдосконалюючи штами чуми на місцевих припасах і полонених.",al={"хто такий лайдон","аптекар лайдон лор"}},{q="Де розташований Таррен Мілл?",a="Таррен Мілл лежить на півночі Передгір'я Гілсбреда, на південь від Гір Альтерак і на схід від Срібнолісся. Ідіть головними дорогами на південь від Срібнолісся й на перехресті звертайте на схід — і прийдете просто до поселення.",al={"місце таррен мілл","як дістатися таррен мілл","де хілсбрад"}},{q="Чому Відступники передають знахідки пішими гінцями?",a="Renferrel asks a traveler to carry his written findings from the Sepulcher to Lydon in Tarren Mill. He wants the Society's distant researchers to share their discoveries quickly; he gives no explanation about magical alternatives.",al={"чому пішим гінцем","чому кур'єрська доставка"}},{q="Що буде, коли Лайдон отримає дослідження?",a="Отримавши пакунок, Аптекар Лайдон одразу береться вивчати нотатки Ренферрела, щоб використати їх у власних сумішах, а згодом доручає шукачам пригод випробувати вдосконалені штами на місцевому людському населенні.",al={"що далі після доставки","реакція лайдона"}}},fp="30,484,21.501.0,14.434.0,36.244.0,51.260.0,24.271.0,21.245.0,61.230.0,43.226.1"}
P.entries["quest:494"] = {n="Час завдати удару",s="«Час завдати удару» — розвідувальне доручення Орди, що веде розвідників через кордон Передгір'я Гілсбреда до військового осередку Таррен Мілла. Доставка зашифрованого сигналу Скрадача Смерті Леш Верховному Екзекуторові Дарталії позначає перехід від тихого спостереження до злагоджених наступальних дій проти місцевих людей.",h="«Час завдати удару» — розвідувальне доручення Орди, що веде розвідників через кордон Передгір'я Гілсбреда до...",kw={"час завдати удару","скрадач смерті леш","дарталія","таррен мілл","варіматрас","гілсбред","завдання"},ang={["class:Rogue"]="Таємний спостережний пост Леш і її зашифровані послання відображають ремесло скрадачів смерті — елітної гільдії вбивць і розвідників Андерсіті.",["faction:Horde"]="Це донесення глибше втягує союзників Орди, що не належать до нежиті, у стратегічний конфлікт між Відступниками та південними людськими поселеннями.",["race:Undead"]="Для агентів-Відступників доставка донесення Леш допомагає вберегти східний кордон Лордерону від решток людського Альянсу."},sec={{t="Спостерігачка на кордоні",b="Зі свого місця на узвишші біля кордону між Срібноліссям і Передгір'ям Гілсбреда Скрадач Смерті Леш стежить за пересуваннями людських поселенців і ополчення в долині внизу. Скрадачі смерті — очі й вуха Андерсіті: вони розвідують ворожі поселення, перш ніж туди рушить військо. Не бажаючи ризикувати й покидати свій пост, Леш довіряє мандрівникам Орди передати зібрані відомості далі дорогою до Таррен Мілла."},{t="Зашифрований поклик",b="Послання Леш навмисно туманне: «Крик ворона із заходу кличе». Донесений на схід битими шляхами, цей сигнал повідомляє Верховному Екзекуторові Дарталії, що людська оборона довкола містечка Гілсбред вразлива. Для Дарталії та жахолорда Варіматраса це підтвердження, що настала година підняти сили Відступників і розпочати походи проти людських захисників Гілсбреда."}},faq={{q="Що означає послання Скрадачки Смерті Леш?",a="Фраза «Крик ворона із заходу кличе» — шифроване розвідувальне донесення. Воно повідомляє Верховному Екзекуторові Дарталії, що західні підступи до Гілсбреда погано охороняються й час для негайного наступу настав.",al={"що означає крик ворона","що значить крик ворона","послання леш"}},{q="Хто така Верховний Екзекутор Дарталія?",a="Верховний Екзекутор Дарталія — найвищий воєначальник Відступників у Передгір'ї Гілсбреда. З укріпленого селища Таррен Мілл вона керує наступальними діями проти людей Саутшора й тісно узгоджує стратегію з Варіматрасом в Андерсіті.",al={"хто така дарталія","роль дарталії"}},{q="Чому Леш посилає гінця, а не йде сама?",a="Леш виконує важливу розвідку на західному краю Гілсбреда. Якщо вона покине пост, у спостереженні Відступників з'явиться сліпа пляма, тож термінові донесення вона передає через подорожніх Орди.",al={"чому леш посилає гінця","чому гінці"}},{q="Куди треба доставити це послання?",a="Послання треба нести головною дорогою на схід через Передгір'я Гілсбреда до Таррен Мілла — головної твердині Орди в краї.",al={"куди йти","призначення послання"}},{q="Чому Варіматрас утручається в справи Гілсбреда?",a="Як головний заступник Сильвани Віндраннер і радник-жахолорд, Варіматрас керує значною частиною війська й стратегічного планування Відступників із Королівського Кварталу Андерсіті. Верховний Екзекутор Дарталія втілює його накази на місцевому фронті.",al={"варіматрас хілсбрад","чому варіматрас"}},{q="Що буде, коли послання отримано?",a="Отримавши підтвердження, що Гілсбред вразливий, Дарталія дає дозвіл на рішучі наступальні удари й посилає звитяжців Орди нищити ферми, ополчення й господарство містечка Гілсбред.",al={"що далі","після час завдати удару"}}},fp="14,334,23.463.0,14.413.1,43.229.0,31.284.0,54.230.0,44.148.0,51.271.0,44.213.0"}
P.entries["quest:496"] = {n="Еліксир Страждання",s="У Таррен Міллі Аптекар Лайдон виконує похмуре доручення Королівського Аптекарського Товариства — створювати смертоносні суміші проти живих. Щоб просунути свої моторошні досліди, він наймає мандрівників збирати тваринні складники в довколишньому передгір'ї.",h="У Таррен Міллі Аптекар Лайдон виконує похмуре доручення Королівського Аптекарського Товариства — створювати...",kw={"еліксир страждання","аптекар лайдон","таррен мілл","сірі ведмеді","мохові повзуни","завдання"},ang={["faction:Horde"]="Хоча інші союзники Орди можуть здригнутися від холодної безжальності біологічних дослідів, щоб убезпечити кордон Таррен Мілла від Саутшора, доводиться довіритися алхімічній війні Відступників.",["race:Undead"]="Для агентів-Відступників допомога Лайдонові просуває головну мету Королівського Аптекарського Товариства: створити нищівну зброю, що забезпечить виживання їхнього народу перед живим людством."},sec={{t="Отруйна справа",b="Таррен Мілл — не лише військова твердиня Відступників у Передгір'ї Гілсбреда, а й діяльна дослідницька станція Королівського Аптекарського Товариства. Аптекар Лайдон, що працює серед мальовничої зелені, зневажає незайманий сільський край і мріє побачити людські поселення отруєними й підкореними. Щоб виготовити свій експериментальний «Еліксир Страждання», він потребує місцевих біологічних засобів, відомих своєю силою й заразністю."},{t="Збирання складників",b="Створення алхімічних чум вимагає точних складників. Лайдон посилає мисливців у дикі краї довкола Таррен Мілла збирати язики місцевих Сірих Ведмедів і рідкісний іхор, що виділяють Мохові Повзуни. Перероблені несвятою алхімією, ці органічні рідини стають основою смертоносної суміші, покликаної винищити живих загарбників по всьому Гілсбреду."}},faq={{q="Хто такий Аптекар Лайдон?",a="Аптекар Лайдон — член Королівського Аптекарського Товариства, що працює в Таррен Міллі. Вірний алхімічним традиціям Відступників, він зневажає чисті, живі краєвиди Гілсбреда й присвячує свій час створенню сильних отрут, щоб винищити людей.",al={"аптекар лайдон","хто дає еліксир страждання","лайдон таррен мілл"}},{q="Навіщо Лайдонові ведмежі язики й сукровиця повзунів?",a="Лайдон досліджує заразні вбивчі речовини, щоб варити з них смертоносні суміші. Біологічні властивості язиків Сірих Ведмедів і їдкі виділення мохових повзунів дають нестійку алхімічну основу для його нового Еліксиру Страждання.",al={"навіщо ведмежі язики","навіщо сукровиця повзунів","інгредієнти еліксиру"}},{q="Куди веде це завдання далі?",a="Отримавши основні реагенти, Лайдон змішує їх у пробне вариво. Тоді він вимагає випробувати суміш, щоб перевірити, наскільки смертоносно вона діє на живих.",al={"наступне завдання еліксиру страждання","що після еліксиру страждання"}},{q="Яка мета Королівського Аптекарського Товариства в Гілсбреді?",a="Товариство діє з наказу Леді Сильвани Віндраннер, щоб створити алхімічну чуму, здатну винищити і людство, і Погибель. Таррен Мілл — ідеальна прикордонна застава, щоб збирати біологічний матеріал і випробовувати зразки на місцевих силах Альянсу.",al={"чому аптекарі в хілсбраді","цілі отрути відступників","чума хілсбрада"}},{q="Де водяться потрібні істоти?",a="Сірі Ведмеді блукають по всіх центральних полях і лісах Передгір'я Гілсбреда, а мохові повзуни ховаються в чагарях і перелісках одразу за Таррен Міллом.",al={"де сірі ведмеді","де мохові повзуни","місця ведмедів і павуків"}},{q="Чому в Лайдона такий кепський настрій?",a="Як і багатьом алхімікам-Відступникам, Лайдонові огидні життєва сила, чисте повітря й буйна природа. Радість йому дають лише смерть, розклад і вдала перегонка смертельних отрут.",al={"чому лайдон незадоволений","чисте повітря лайдона"}}},fp="19,250,18.459.0,18.369.0,24.265.0,51.247.0,32.175.1,62.274.0,43.174.0,32.179.0"}
P.entries["quest:4966"] = {n="Захисти Канаті Ґрейклауда",s="«Захисти Канаті Ґрейклауда» — завдання Орди на Заставі Білого Рубежу в Тисячі Голок. Дізнавшись, що кентаври-вбивці полюють на таурена Канаті Ґрейклауда, шукачі пригод мають стати поруч із ним і відбити загін убивць Ґалак.",h="«Захисти Канаті Ґрейклауда» — завдання Орди на Заставі Білого Рубежу в Тисячі Голок.",kw={"захисти канаті ґрейклауда","канаті ґрейклауд","кентаври ґалак","застава білого рубежу","засідка","тисяча голок"},ang={["faction:Horde"]="Застава Білого Рубежу — важливий спостережний пункт у Тисячі Голок, і вберегти живими вартових, як-от Канаті, конче потрібно, щоб забезпечити дії Орди по всьому каньйону.",["race:Tauren"]="Кровна ворожнеча тауренів і кентаврів глибока, тож захистити одноплемінника від підступного вбивства — справа і виживання, і честі."},sec={{t="Викрита засідка",b="Перебуваючи серед високих пісковикових шпилів Застави Білого Рубежу, таурен Канаті Ґрейклауд дізнається з перехоплених наказів кентаврів про змову, спрямовану просто проти нього. Плем'я кентаврів Ґалак, невгамовне у ворожнечі до кочових тауренів та їхніх союзників з Орди, не вдовольняється набігами на шляхи постачання — воно прагне знищити тих, хто осідає в його каньйонах."},{t="Оборона Застави Білого Рубежу",b="Розуміючи, що напад неминучий, і підозрюючи, що ворогів може бути більше, ніж він гадав, Канаті просить мандрівників на заставі битися пліч-о-пліч із ним. Коли вбивці Ґалак завдають удару, Канаті стоїть на своєму, покладаючись на клинки й чари союзників, щоб розбити засідку, перш ніж кентаври здобудуть свою нагороду."}},faq={{q="Хто такий Канаті Ґрейклауд?",a="Канаті Ґрейклауд — таурен, що облаштував мисливський табір на Заставі Білого Рубежу в Тисячі Голок, неподалік каньйонів, які місцеві кентаврські клани вважають своїми.",al={"хто такий канаті","канаті ґрейклауд лор","хто дає завдання"}},{q="Чому кентаври намагаються його вбити?",a="Місцеві кентаври Ґалак вважають тауренів і табори Орди ворогами, що зазіхають на їхні каньйони. Убивши Канаті, кентаври хочуть позбавити каньйон і його мисливського табору, і всіх, хто міг би прийти слідом.",al={"чому кентаври його вбивають","причина вбивства кентаврами","чому змова"}},{q="Де відбувається ця оборона?",a="Засідка відбувається просто на Заставі Білого Рубежу — невеликій заставі, пов'язаній з Ордою, на стежках каньйонів Тисячі Голок.",al={"де цей захист","місце захисту канаті","де засідка"}},{q="Який клан кентаврів нападає на Канаті Ґрейклауда?",a="Убивці належать до племені Ґалак — найпомітнішого кентаврського клану, що населяє каньйони й яри Тисячі Голок.",al={"яке плем'я нападає","хто вбивці","які кентаври"}},{q="Що буде, коли вбивць здолано?",a="Коли вбивць Ґалак перебито, життя Канаті врятовано, а Застава Білого Рубежу в безпеці. Канаті дякує захисникам за те, що стали з ним пліч-о-пліч під час раптового нападу, — і ланцюжок оборони успішно завершується.",al={"що далі","продовження завдання","після захисту канаті"}},{q="Чи б'ється Канаті Ґрейклауд у битві?",a="Так. Канаті не ховається й не тікає: він сам кидається в бій разом із тими, хто відгукнувся на його заклик, і відбиває вбивць, що прийшли покласти край його чатуванню.",al={"чи канаті допомагає","канаті б'ється","чи канаті пасивний"}}},fp="24,233,18.405.0,25.318.0,24.163.0,46.224.0,35.137.0,44.123.0,46.219.1,42.158.0"}
P.entries["quest:498"] = {n="Порятунок",s="«Порятунок» — раннє завдання Орди, яке дає Краск у Таррен Міллі: героям доручено проникнути до Твердині Дурнгольд і визволити полонених орків-розвідників. Добірних розвідників Тралла застали в засідці, коли вони шукали реліквію з минулого Вождя, і тепер вони в полоні безжальних людських злочинців Синдикату.",h="«Порятунок» — раннє завдання Орди, яке дає Краск у Таррен Міллі: героям доручено проникнути до Твердині...",kw={"порятунок","краск","твердиня дурнгольд","синдикат","ґол'дір","друлл","завдання"},ang={["class:Warrior"]="Визволення побратимів із передової з полону зміцнює бойове братерство перед безчесними людськими розбійниками.",["faction:Horde"]="Це завдання позначає один із перших кроків Орди, щоб протидіяти поширенню Синдикату на спірних пагорбах Лордерону.",["race:Orc"]="Вигляд орків-воїнів, закутих у кайдани в Твердині Дурнгольд, ятрить болісну історію таборів інтернування, тож визволити їх — справа глибоко особиста."},sec={{t="Невдала розвідка",b="Вождь Тралл послав до Передгір'я Гілсбреда добірний загін орків-воїнів із наказом потай розвідати дедалі більшу загрозу Синдикату й повернути річ, тісно пов'язану з історією Твердині Дурнгольд. Під проводом Ґол'діра розвідники наблизилися до руїн фортеці. Проте в засідці Синдикат подолав їх самою чисельністю. Воїнові Краскові вдалося вирватися й, кульгаючи, повернутися через річку до Таррен Мілла, а його товаришів Друлла, Тоґ'тара й Ґол'діра живими закували в людські кайдани."},{t="Кайдани серед руїн",b="Дурнгольд береже гіркі спогади для орочого народу: колись тут була ставка таборів інтернування Еделаса Блекмура, де полонених орків доводили до млявості й гладіаторського рабства. Знову бачити своїх воїнів закутими в залізо серед потрісканих кам'яних мурів Дурнгольда — нестерпна образа для Орди. Щоб визволити Друлла й Тоґ'тара, рятівникам доведеться зійтися з тюремниками Синдикату, що тримають ключі від їхніх кайданів, а тоді з'ясувати, що сталося з їхнім командиром-розвідником Ґол'діром."}},faq={{q="Навіщо орків узагалі послали до Твердині Дурнгольд?",a="Вождь Тралл відрядив Ґол'діра з загоном розвідників розслідувати діяльність розбійників Синдикату й забрати з минулого Дурнгольда річ, що має для Вождя велике особисте значення.",al={"навіщо орки у дурнгольд","чому дурнгольд","місія круска"}},{q="Кого рятують із полону?",a="Друлл і Тоґ'тар — орки-розвідники, яких Орда послала під командуванням Ґол'діра. Розбійники Синдикату здолали їх у руїнах і закували в кайдани з ядрами.",al={"хто такий друлл","хто такий тоґтар","хто заручники"}},{q="Де ватажок загону, Ґол'дір?",a="Коли Друлла й Тоґ'тара звільнено, Краск з'ясовує, що їхнього командира, Ґол'діра, відділили від решти загону й Синдикат перевів його в інше, невідоме місце.",al={"де ґол'дір","знайти ґол'діра","що сталося з ґол'діром"}},{q="Хто тримає розвідників у полоні?",a="Їх тримає Синдикат — аристократична злочинна мережа, що діє з руїн Лордерона й Альтерака; у Дурнгольді розвідників безпосередньо стережуть тюремники Синдикату.",al={"хто схопив їх","хто тюремники","хто керує дурнгольдом"}},{q="Куди веде цей ланцюжок завдань?",a="Звільнення розвідників одразу веде до доручення вистежити Синдикат і проникнути до нього, щоб урятувати Ґол'діра, — а зрештою до викриття задумів Лорда Алідена Перенольда й до пам'ятки, що належала Тареті Фокстон.",al={"що далі","після порятунку","ланцюжок порятунку"}},{q="Чому Твердиня Дурнгольд має особливе значення для Орди?",a="У Дурнгольді Еделас Блекмур виростив Тралла як гладіатора й після Другої війни керував системою таборів інтернування Альянсу — доки Тралл не підняв повстання й не зруйнував твердиню.",al={"історія дурнгольду","чому орда дбає про дурнгольд"}}},fp="10,308,26.534.0,19.512.1,58.191.0,35.181.0,37.182.1,34.173.0,33.205.1,58.215.0"}
P.entries["quest:499"] = {n="Еліксир Страждання",s="У Таррен Міллі Аптекар Лайдон варить отруйну суміш, що має просунути зловісну роботу Королівського Аптекарського Товариства. Щоб переконатися в її смертоносності, він наказує негайно випробувати її на живому — на своєму нещасному супутникові поруч.",h="У Таррен Міллі Аптекар Лайдон варить отруйну суміш, що має просунути зловісну роботу Королівського...",kw={"еліксир страждання","умпі","аптекар лайдон","таррен мілл","отрута","завдання"},ang={["class:Druid"]="Друїда може глибоко стривожити, як буденно й безсердечно отруюють безневинне земноводне в ім'я війни Відступників.",["faction:Horde"]="Союзники, що навідуються до Таррен Мілла, на власні очі бачать моторошні, безжальні алхімічні методи Королівського Аптекарського Товариства.",["race:Undead"]="Для Відступників випробування смертоносних отрут — необхідна справа на шляху до виконання наказу Леді Сильвани знищити і Погибель, і живих."},sec={{t="Отруйне випробування",b="Аптекар Лайдон невтомно працює в Таррен Міллі над хімічною зброєю, здатною втілити великі задуми Темної Леді: моровицю, що знищить і живих людей Альянсу, і нежить-потвор Погибелі. Щойно потрібні складники зібрано й настояно, Лайдон змішує мерзенне вариво, яке називає Еліксиром Страждання, і прагне побачити його неприкриту силу, перш ніж застосовувати ширше."},{t="Доля Умпі",b="Замість шукати ворожого бранця чи звіра-втікача, Лайдон звертається просто до істоти поруч. Він велить шукачеві пригод дати свіжозварену отруту своєму помічникові Умпі — безневинній ропусі, що тихо сидить біля його ніг. Одна доза еліксиру миттю виявляється згубною: вона вбиває земноводне на місці, і аптекар задоволений — його смертоносна формула діє саме так, як задумано."}},faq={{q="Хто такий Аптекар Лайдон?",a="Аптекар Лайдон — алхімік Королівського Аптекарського Товариства в поселенні Відступників Таррен Мілл у Передгір'ї Гілсбреда. Цілими днями він удосконалює отрути й алхімічні суміші, що мають знищити ворогів Відступників.",al={"лайдон","хто такий лайдон","аптекар лайдон таррен мілл"}},{q="Хто такий Умпі?",a="Умпі — звичайна жаба, що сидить просто біля робочого столу Аптекаря Лайдона в Таррен Міллі; Лайдон жартома називає її своєю помічницею.",al={"що таке умпі","жаба умпі","хто помічник"}},{q="Навіщо потрібен Еліксир Страждання?",a="Еліксир Страждання — дослідна хімічна зброя, створена, щоб випробувати отруйні формули, які мають знищити і живих людей, і нежить Погибелі, — на користь Леді Сильвани Віндраннер.",al={"що робить еліксир","навіщо еліксир страждання"}},{q="Що стається, коли напоїти Умпі зіллям?",a="Лайдон просить вас дати Умпі скуштувати щойно змішаний еліксир, щоб перевірити, чи діє він так, як задумано. Результат з'ясується під час випробування.",al={"чи умпі помре","що буде з жабою"}},{q="Де відбувається це випробування?",a="Випробування відбувається в містечку Відступників Таррен Мілл на півночі Передгір'я Гілсбреда, просто біля Лайдонового робочого місця.",al={"де лайдон","де знайти умпі"}},{q="Чому Королівське Аптекарське Товариство випробовує отрути на дрібних тваринах?",a="Аптекарі Відступників зазвичай використовують дрібних істот і гризунів для попередніх випробувань, щоб перевірити швидкість і смертоносність своїх хімічних сумішей, перш ніж переходити до польових випробувань на більших цілях чи живих полонених.",al={"чому випробовувати на жабах","тестування аптекарів на тваринах"}}},fp="19,223,12.439.0,16.424.1,24.265.0,12.135.0,47.191.0,46.143.1,32.131.0,68.217.0"}
P.entries["quest:5"] = {n="Бурчання в животі Джіттерса",s="Застрягши в руїнах Воронячого Пагорба, параноїдальний волоцюга Тремтій, що досі харчувався бур'янами й комахами, відчайдушно прагне справжньої їжі. Він благає перехожих шукачів пригод вирушити на схід, до Даркшира, і вмовити Шеф-кухаря Ґруала приготувати гарячу партію його знаменитих Сутінкових Крабових Котлет.",h="Застрягши в руїнах Воронячого Пагорба, параноїдальний волоцюга Тремтій, що досі харчувався бур'янами й...",kw={"бурчання в животі","тремтій","шеф-кухар ґруал","крабові котлети","воронячий пагорб","даркшир"},ang={["faction:Alliance"]="Допомагаючи Тремтієві, ви зближуєтеся з крихкими, знесиленими поселеннями й тими, хто вцілів і чіпляється за життя в темних закутках Сутінколісся.",["profession:Cooking"]="Знамениті Сутінкові Крабові Котлети Шеф-кухаря Ґруала показують, як майстри кухні на прикордонні обходяться місцевими екзотичними інгредієнтами, коли звичайні поставки не доходять до Сутінколісся."},sec={{t="Голод на Воронячому Пагорбі",b="Воронячий Пагорб став кублом ненажерливої нежиті й причаєних звірів, і дивакуватий самітник Тремтій тижнями ховається тут, наче в пастці. Блукаючи напівзруйнованими халупами у вічному мороці, він виживав лише на земляних личинках і диких бур'янах. Позбавлений будь-яких вигод цивілізації, він довів і нерви, і шлунок до останньої межі."},{t="Благання про крабові котлети",b="Прагнучи бодай якогось нагадування про безпеку, Тремтій мріє про приправлені котлети, які готують у Таверні «Багряний Крук» у Даркширі. Він посилає мандрівників проклятою дорогою до Шеф-кухаря Ґруала, сподіваючись, що той погодиться нашвидку приготувати партію Сутінкових Крабових Котлет і вгамувати його люте бурчання в животі."}},faq={{q="Хто такий Джіттерс?",a="Джіттерс — наляканий, підозріливий чоловік, що переховується в зруйнованому селищі на Воронячому Пагорбі на заході Сутінколісся. Він до смерті боїться нежиті, що заполонила край, і постійно живе в страху перед голодом і різаниною.",al={"джіттерс","хто такий джіттерс","де джіттерс"}},{q="Де знайти Шеф-кухаря Ґруала?",a="Шеф-кухар Ґруал працює на кухні Таверни «Багряний Крук» у містечку Даркшир, на сході Сутінколісся.",al={"місце шеф-кухаря ґруала","знайти ґруала","кухар багряного ворона"}},{q="Чому Джіттерс їсть личинок?",a="Відрізаний від цивілізації ордами мандрівної нежиті й хижими воргенами, Джіттерс тижнями сидить у пастці у зруйнованому селищі на Воронячому Пагорбі, не маючи жодних харчів, крім комах і листя, які вдається знайти.",al={"джіттерс їсть жуків","чому їсть личинок","їжа воронячого пагорба"}},{q="Якої страви хоче Джіттерс?",a="Джіттерс мріє про Сутінкові Крабові Котлети — місцевий делікатес, який готує Шеф-кухар Ґруал у Таверні «Багряний Крук».",al={"їжа джіттерса","завдання крабових котлет","чого хоче їсти джіттерс"}},{q="Що буде після розмови з Шеф-кухарем Ґруалом?",a="Шеф-кухар Ґруал охоче приготує страву для Джіттерса, але йому бракує свіжих продуктів, тож він просить шукача пригод зібрати липкі павучі лапки для Сутінкових Крабових Котлет.",al={"після бурчання в животі","наступне завдання джіттерса","завдання шеф-кухаря ґруала"}},{q="Чи можуть гравці Орди виконати це завдання?",a="Ні. І Джіттерс, і містечко Даркшир на боці Альянсу, тож це доручення — лише для шукачів пригод Альянсу.",al={"чи джіттерс лише для альянсу","джіттерс для орди"}}},fp="21,286,22.345.0,21.293.0,15.206.0,28.129.0,28.230.0,28.105.0,44.172.1,38.121.0"}
P.entries["quest:501"] = {n="Еліксир Болю",s="Це доручення Аптекаря Лайдона з Таррен Мілла посилає шукачів пригод з Орди збирати кров гірських левів, щоб зварити нову смертоносну суміш. Воно показує похмуру відданість Королівського Аптекарського Товариства вдосконаленню Нової Чуми й зневагу до буйної природної сили Передгір'я Гілсбреда.",h="Це доручення Аптекаря Лайдона з Таррен Мілла посилає шукачів пригод з Орди збирати кров гірських левів, щоб...",kw={"еліксир болю","кров гірського лева","аптекар лайдон","таррен мілл","нова чума","завдання"},ang={["faction:Horde"]="Союзникам Відступників доводиться миритися з похмурими методами алхіміків Таррен Мілла й допомагати полювати на диких звірів, щоб зміцнити позиції Орди проти сусідніх людських загроз.",["race:Undead"]="Для мандрівників-Відступників збирання складників для Аптекаря Лайдона безпосередньо служить волі Темної Леді й Королівського Аптекарського Товариства, що закріплюють свої права на Лордерон."},sec={{t="Гіркий погляд із Таррен Мілла",b="Служачи в Таррен Міллі, Аптекар Лайдон не знаходить жодної радості в довколишньому краєвиді. Дивлячись у вікно на квітучі луки й свіже гірське повітря Гілсбреда, він сприймає невгасне життя краю як образу. Як і багато хто в Королівському Аптекарському Товаристві, він особисто відданий Леді Сильвані Віндраннер і вдосконаленню Нової Чуми — штучної моровиці, що має принести смерть живим і відплату їхнім ворогам."},{t="Складники для страждань",b="Щоб створити свою найновішу отруйну суміш, Лайдон звертається до місцевих звірів, що нишпорять передгір'ям і схилами в бік Гір Альтерак. Вірячи, що кров гірського лева має особливі властивості, конче потрібні для створення того, що він називає Еліксиром Болю, він посилає агентів у дикі краї по десять флаконів. Зібрана кров стає основою для безперервних хімічних випробувань Товариства на спірному південному фронті."}},faq={{q="Хто дає завдання «Еліксир Болю»?",a="Завдання дає Аптекар Лайдон — алхімік Відступників у поселенні Таррен Мілл у Передгір'ї Гілсбреда.",al={"хто дає еліксир болю","хто починає еліксир болю","завдання аптекаря лайдона"}},{q="Навіщо Аптекареві Лайдону кров гірських левів?",a="Алхімічні дослідження Лайдона свідчать, що кров гірських левів — незамінний реагент для нової смертоносної суміші: еліксиру, що має просунути досліди Королівського Аптекарського Товариства з чумою проти їхніх живих ворогів.",al={"навіщо кров гірських левів","призначення крові лева","навіщо кров"}},{q="Де водяться гірські леви?",a="Гірські леви никають по всіх відкритих полях і пагорбах Передгір'я Гілсбреда, а також на вищих кручах, що ведуть до Гір Альтерак.",al={"де гірські леви","місця гірських левів хілсбрад","фарм крові левів"}},{q="Що за Нову Чуму згадує Лайдон?",a="Нова Чума — біологічна зброя, яку ретельно досліджує й розробляє Королівське Аптекарське Товариство Відступників з наказу Леді Сильвани Віндраннер; вона має знищити і Погибель, і живих.",al={"що за нова чума","чума королівського аптекарського товариства","чума відступників"}},{q="Що далі після цього завдання?",a="Коли ви віддаєте десять пляшечок крові гірських левів, одразу починається наступне доручення: Аптекар Лайдон береться випробовувати свій щойно зварений еліксир.",al={"наступне завдання після еліксиру болю","продовження еліксиру болю","що після еліксиру болю"}},{q="Чому Лайдон зневажає краєвиди Гілсбреда?",a="Як мертвий слуга Темної Леді, Лайдон ненавидить квітучі рослини, свіже повітря й невгамовну живучість краю — йому б хотілося бачити живий світ задушеним отруйними творіннями свого Товариства.",al={"чому лайдон ненавидить хілсбрад","чому лайдон похмурий","цитата лайдона про вікно"}}},fp="14,314,31.477.0,22.426.0,35.138.0,51.232.0,38.160.0,38.222.0,44.159.0,43.207.0"}
P.entries["quest:502"] = {n="Еліксир Болю",s="У цьому завданні Аптекар Лайдон із Таррен Мілла доручає агентам Орди випробувати щойно зварену біологічну суміш, відому як Еліксир Болю. Аптекар-Відступник обирає мимовільним піддослідним Стенлі — домашнього пса Фермера Рея з Полів Гілсбреду.",h="У цьому завданні Аптекар Лайдон із Таррен Мілла доручає агентам Орди випробувати щойно зварену біологічну...",kw={"еліксир болю","стенлі","фермер рей","поля гілсбреду","аптекар лайдон","мутація","завдання"},ang={["class:Hunter"]="Видовище того, як лагідний домашній улюбленець жорстоко перетворюється на дикого змутованого хижака, показує протиприродне збочення звірячої природи алхімією Відступників.",["faction:Horde"]="Союзників Відступників безпосередньо втягують у їхні похмурі хімічні випробування проти сусідніх людських ферм Гілсбреда.",["race:Undead"]="Цей дослід підкреслює безжальну методологію Королівського Аптекарського Товариства, що шукає біологічну зброю для виживання Відступників, не зважаючи на побічні жертви."},sec={{t="Аптекарська наука",b="Працюючи в Таррен Міллі, Аптекар Лайдон ставить досліди на користь Королівського Аптекарського Товариства й Леді Сильвани Віндраннер. Зі свіжої крові, зібраної з місцевих звірів, Лайдон варить нестійку суміш, яку називає Еліксиром Болю. Товариство не покладається лише на теоретичну алхімію: йому потрібні польові дані, щоб спостерігати, як експериментальні отрути й мутагени діють на тіло."},{t="Випробування на Стенлі",b="Щоб перевірити вариво, не насторожуючи людських захисників Гілсбреда, Лайдон посилає своїх агентів до північної ферми на Полях Гілсбреду. Там живе Стенлі — на вигляд безневинний домашній пес Фермера Рея. Підійшовши до нічого не підозрюючого пса з варивом, налитим у відкриту долоню, агент дає йому дозу під виглядом звичайних ласощів."},{t="Жорстока мутація",b="Справжня природа Еліксиру Болю проявляється одразу, щойно пес його ковтає. Замість звичайної смертельної отрути суміш діє як жахливий мутаген: вона вмить спричиняє муки й жорстоко спотворює тіло Стенлі, перетворюючи його на дикого, розлюченого вовка. Звір люто кидається на все довкола, доводячи нестійку дієвість алхімічної формули Лайдона."}},faq={{q="Навіщо потрібен Еліксир Болю?",a="Аптекар Лайдон зварив Еліксир Болю в межах невпинних зусиль Королівського Аптекарського Товариства створити біологічну зброю й потужні мутагени для Леді Сильвани й Відступників.",al={"мета еліксиру болю","навіщо робити еліксир болю","призначення еліксиру лайдона"}},{q="Хто такий Стенлі?",a="Стенлі — пес Фермера Рея, що живе біля великого фермерського будинку на північному краю Полів Гілсбреду.",al={"хто такий стенлі","пес фермера рея","пес стенлі"}},{q="Що стається, коли згодувати Стенлі еліксир?",a="Від еліксиру Стенлі шалено мутує й перетворюється на лютого скаженого вовка, який одразу стає ворожим і нападає.",al={"перетворення стенлі","що еліксир робить із псом","стенлі вовк"}},{q="Де знайти Стенлі?",a="Стенлі бродить біля великого будинку на північній фермі в Полях Гілсбреду, на південний захід від Таррен Мілла.",al={"знайти стенлі","місце стенлі","де пес фермера рея"}},{q="Хто дає завдання випробувати еліксир?",a="Аптекар Лайдон із поселення Відступників Таррен Мілл у Передгір'ї Гілсбреда дає це завдання, коли ви зберете потрібні реагенти.",al={"хто дає завдання випробування","хто дає еліксир болю","завдання аптекаря лайдона"}},{q="Чому зілля випробовують на фермерському псі, а не на людях?",a="Випробування на домашньому улюбленцеві в Полях Гілсбреду — тиха й доступна проба, яка не насторожить одразу міське ополчення чи озброєну варту Гілсбреда щодо природи алхімічного досліду.",al={"чому на псі","чому стенлі","чому отруїти пса"}}},fp="14,290,18.431.0,18.364.0,16.365.1,42.187.0,15.123.0,46.128.1,25.115.0,39.155.0,56.193.0"}
P.entries["quest:5041"] = {n="Припаси для Перехрестя",s="«Припаси для Перехрестя» — доручення Орди від Торка: повернути важливі припаси, захоплені під час набігів шипогривів-Гостроманів. Відбиваючи втрачені ящики з колючих таборів, шукачі пригод допомагають Перехрестю вистояти серед безупинних місцевих сутичок.",h="«Припаси для Перехрестя» — доручення Орди від Торка: повернути важливі припаси, захоплені під час набігів...",kw={"припаси для перехрестя","торк","гостромани","шипогриви","перехрестя","караван"},ang={["faction:Horde"]="Утримання Перехрестя необхідне, щоб поєднувати столиці Орди в Дуротарі й Малгорі; повернення пограбованих вантажів гарантує, що прикордонна застава не лишиться без припасів.",["race:Orc"]="Захищаючи важливі шляхи постачання від злодійкуватих шипогривів, ви виконуєте головний обов'язок — берегти поселення нової Орди, що розростаються."},sec={{t="Рятівна нитка в облозі",b="Перехрестя — центральний вузол подорожей, торгівлі й оборони Орди в Пустках. Щоб такий вузол працював, потрібен постійний потік вантажів із Дуротару й Малгора. Коли на караван із припасами нападають, застава одразу відчуває нестачу харчів, знарядь і зброї, без яких у суворій дикій місцевості не вистояти."},{t="Злодійкуваті шипогриви",b="За нападом стоять шипогриви-Гостромани — місцеві вепроподібні істоти, що оскаржують владу Орди в центральному Калімдорі. Замість того щоб знищити вкрадене, шипогриви затягли важкі ящики до своїх укріплених колючими заростями таборів, щоб забрати собі. Торк доручає надійним воїнам пробратися глибоко на землі Гостроманів і повернути те, що по праву належить Орді."}},faq={{q="Хто дає це завдання?",a="Це завдання дає Торк — офіцер Орди, що відповідає за оборону й справи Перехрестя.",al={"хто дає завдання","завдання торка","хто починає припаси для перехрестя"}},{q="Чому припаси взагалі вкрали?",a="На караван із припасами, що прямував до Перехрестя, напали агресивні шипогриви-Гостромани й потягли ящики до своїх таборів неподалік.",al={"чому вкрали припаси","напад на караван","що сталося з припасами"}},{q="Де шукати вкрадені ящики?",a="Вкрадені ящики з припасами Перехрестя розкидані по землі в таборах шипогривів-Гостроманів на схід і північний схід від Перехрестя.",al={"місця вкрадених ящиків","де припаси","знайти ящики"}},{q="Чому повернути ці припаси так важливо для Торка?",a="Перехрестя — відокремлений і жвавий осередок, оточений ворожими загрозами. Утрачені каравани загрожують щоденній роботі й безпеці застави, лишаючи і вояків, і мандрівників без найнеобхіднішого.",al={"чому важливо торку","важливість перехрестя","значення припасів"}},{q="Що передує цьому завданню?",a="Це завдання йде після «Зірвати напади», де шукачі пригод спершу б'ють по силах Гостроманів, щоб послабити їхній тиск на шляхи Орди.",al={"передумова","попереднє завдання","зірвати напади"}},{q="Хто такі Гостромани?",a="Гостромани — люте плем'я шипогривів, що ревно стереже свою територію в Пустках, зухвало грабує каравани й запекло опирається присутності Орди на їхніх прадавніх землях.",al={"гостроманські шипогриви","хто такі шипогриви","гостромани"}}},fp="27,269,22.350.0,17.399.0,21.99.0,48.142.0,37.156.0,55.211.0,29.152.0,22.178.0"}
P.entries["quest:5043"] = {n="Спритність Аґамаґґана",s="«Спритність Аґамаґґана» — повторюваний обряд кривавих скалок, який пропонує полонений шипогрив Понівечозуб у Таборі Тауражо. Приносячи кришталеві криваві скалки, видобуті з землі Пусток, мандрівники отримують благословення — непохибну прудкість і влучність прадавнього бога-вепра шипогривів.",h="«Спритність Аґамаґґана» — повторюваний обряд кривавих скалок, який пропонує полонений шипогрив Понівечозуб у...",kw={"спритність аґамаґґана","аґамаґґан","понівечозуб","криваві скалки","табір тауражо","розбійник"},ang={["class:Hunter"]="Спритність Аґамаґґана — це передусім непохибна влучність і прудке скрадання, чесноти, які високо цінують стрільці, що мандрують відкритими просторами Калімдору.",["class:Rogue"]="Понівечозуб відверто глузує з прудкості розбійників, які не належать до шипогривів, тож цей обряд — тихе торжество: священну швидкість звіра ви обертаєте проти племен чагарникових степів.",["faction:Horde"]="Сили Орди в Таборі Тауражо терплять присутність Понівечозуба й торги кривавими скалками лише тому, що залишкова сила бога-вепра допомагає їм у важкій кампанії по всіх Пустках.",["race:Tauren"]="Таурени шанують силу прадавніх Древніх, що загинули у Війні Прадавніх, хоча угоди з шипогривом у клітці в Тауражо — непростий компроміс."},sec={{t="Сила кривавих скалок",b="По всіх Пустках із ґрунту стирчать дивні багряні мінерали, відомі як криваві скалки, — особливо поблизу таборів шипогривів і велетенських колючих заростей. Перекази шипогривів кажуть, що ці кристали утворилися з пролитої крові Аґамаґґана — Великого Вепра, одного з Древніх, що загинув у боротьбі з Палаючим Легіоном під час Війни Прадавніх. Навіть замкнений у дерев'яній клітці в Таборі Тауражо, старий шипогрив Понівечозуб досі знає, як пробудити цю дрімотну божественну силу для кожного, хто принесе камені."},{t="Благословення розвідників Вепра",b="Мисливці й розвідники шипогривів пишаються безжальною влучністю й сліпучою прудкістю в чагарниках. За чотири криваві скалки Понівечозуб пробуджує приховану енергію полеглого напівбога й наповнює прохача хижими інстинктами та гнучкою грацією найкращих скрадачів свого народу. Хоч він зневажливо рохкає на чужинців, Понівечозуб дотримується угоди й вплітає силу Аґамаґґана в тимчасовий покрив спритності."}},faq={{q="Хто пропонує Спритність Аґамаґґана?",a="Завдання пропонує Понівечозуб — шипогрив-геомант, якого тримають у клітці в Таборі Тауражо на півдні Пусток. Попри полон в Орди, він охоче торгується з шукачами пригод, які приносять йому Криваві скалки.",al={"хто дає завдання","хто дає спритність аґамаґґана","де понівечозуб"}},{q="Що таке Криваві скалки?",a="Криваві скалки — кристалічні камені, що трапляються по всіх Пустках; здебільшого їх збирають з убитих шипогривів і з мінеральних виходів біля терникових хащ. За переказами шипогривів, вони утворилися тисячоліття тому, коли кров Великого Вепра, Прадавнього Аґамаґґана, просякла землю.",al={"лор кривавих скалок","що таке крива скалка","червоні кристали пусток"}},{q="Чому полонений шипогрив допомагає Орді?",a="Понівечозуб вірний своєму богові Аґамаґґанові й власному виживанню. Хоч він зневажливо пирхає на всіх, хто не шипогрив, але охоче вимінює божественні благословення Аґамаґґана на Криваві скалки — так він може торкатися священної есенції свого божества навіть із ворожої клітки.",al={"чому нам допомагає","мотиви понівечозуба","чому понівечозуб говорить"}},{q="Чи можна отримати це благословення не раз?",a="Так. Цей обряд можна повторювати скільки завгодно. Доки ви приносите Понівечозубові чотири свіжі Криваві скалки, він щоразу знову закликатиме благословення Великого Вепра.",al={"чи повторюване","чи можна повторити","повторюване посилення"}},{q="Хто такий Аґамаґґан?",a="Аґамаґґан — велетенський Прадавній-вепр, що ходив Калімдором у давню міфічну добу. Під час Війни Прадавніх десять тисяч років тому він бився з демонами Палаючого Легіону й загинув. Його кров напоїла Пустки, породивши непрохідні гострі терни й народ шипогривів.",al={"хто такий аґамаґґан","кабан-бог","великий кабан"}},{q="Які ще благословення дає Понівечозуб?",a="Крім спритності, Понівечозуб править обряди на честь інших граней Аґамаґґана. В обмін на Криваві скалки він може дати благословення, що посилюють грубу фізичну силу, мудрість, швидкість бігу й шкуру, товсту, мов гостра шкура.",al={"інші завдання кривавих скалок","інші посилення","нагороди понівечозуба"}}},fp="19,288,25.518.0,27.440.0,31.224.0,22.268.0,48.269.0,45.152.0,18.305.0,46.237.0"}
P.entries["quest:5044"] = {n="Мудрість Аґамаґґана",s="«Мудрість Аґамаґґана» — повторюване завдання Орди, яке пропонує полонений шипогрив Понівечозуб у Таборі Тауражо. Приносячи криваві скалки, зібрані по всіх Пустках, заклиначі можуть долучитися до обрядової магії прадавнього бога-вепра Аґамаґґана.",h="«Мудрість Аґамаґґана» — повторюване завдання Орди, яке пропонує полонений шипогрив Понівечозуб у Таборі...",kw={"мудрість аґамаґґана","аґамаґґан","понівечозуб","криваві скалки","табір тауражо","заклиначі"},ang={["class:Mage"]="Маги, охочі до магічного посилення, оцінять первісну геомантичну силу, яку суть Аґамаґґана спрямовує просто в розум.",["class:Priest"]="Жерцям, що вивчають місцеві вірування, буде цікаво побачити прямий зв'язок між божественною кров'ю Аґамаґґана й обрядами, що зміцнюють розум, — особливу грань первісного богошанування.",["class:Shaman"]="Геомантія шипогривів перегукується зі стихійними покликами шаманізму, тож обряди скалок бога-вепра видаються знайомими, але по-особливому дикими.",["faction:Horde"]="Те, що Орда тримає Понівечозуба в Таборі Тауражо, дає воїнам і містикам вигідну нагоду обернути місцеву магію Пусток проти довколишніх племен шипогривів."},sec={{t="Криваві скалки й прадавня сила",b="Ув'язнений Ордою в Таборі Тауражо шипогрив Понівечозуб обмінює магічні таємниці свого народу на багряні кристали, відомі як криваві скалки. За віруваннями шипогривів, ці скалки викристалізувалися з пролитої крові Аґамаґґана — велетенського напівбога-вепра, що загинув у Війні Прадавніх. Понівечозуб запевняє, що геоманти й шамани його племен покладаються на ці скалки, щоб спрямовувати божественну силу у свої обряди."},{t="Благословення розуму",b="Інші пожертви видобувають зі скалок фізичну стійкість чи прудкість, а обряд Мудрості зосереджений лише на розумі й магічних здібностях. За чотири криваві скалки Понівечозуб закликає духа бога-вепра на користь прохача, бажає йому кмітливості в сутичках, а на прощання похмуро нагадує про смертність."}},faq={{q="Хто такий Аґамаґґан?",a="Аґамаґґан — прадавній напівбог-вепр, що десять тисяч років тому бився з Палаючим Легіоном під час Війни Прадавніх. Він загинув у Пустках, і його кров просякла ґрунт, породивши велетенські тернові лози й кристалічні Криваві скалки.",al={"лор аґамаґґана","хто бог-кабан","давній кабан"}},{q="Чому Понівечозуб готовий допомагати Орді?",a="Понівечозуб — полонений шипогрив, якого тримають у клітці в Таборі Тауражо. Попри люту ненависть його племені до Орди, жага Кривавих скалок і власне виживання переважують вірність, тож він дарує священні племінні благословення в обмін на скалки.",al={"чому понівечозуб допомагає","мотив понівечозуба","полонений шипогрив"}},{q="Що таке Криваві скалки?",a="Криваві скалки — червоні мінеральні утворення, що трапляються по всіх землях шипогривів у Пустках. Легенда шипогривів твердить, що ці кристали утворилися просто з крапель крові, яку пролив напівбог Аґамаґґан, умираючи.",al={"лор кривавих скалок","що таке криваві скалки","червоні скалки пусток"}},{q="Чи можна повторювати цей обряд?",a="Так. Коли Понівечозуб довіриться вам після першої демонстрації Кривавих скалок, він щоразу прийматиме по чотири скалки, якщо ви захочете оновити благословення.",al={"чи мудрість аґамаґґана повторювана","повторні криваві скалки","здати ще раз"}},{q="Чи шанують шамани шипогривів інших божеств?",a="Шипогриви шанують Аґамаґґана понад усіх, вважаючи себе його прямими нащадками. Їхні шамани й геоманти черпають природну магію й владу над землею безпосередньо з його міфічної спадщини та решток.",al={"релігія шипогривів","боги геомантів","поклоніння шипогривів"}},{q="Де, на думку Понівечозуба, може бути наша наступна зустріч?",a="Завершивши обряд, Понівечозуб просить вас розповісти про свою хитрість, коли ви зустрінетеся знову — хоч у цьому смертному житті, хоч у наступному, — визнаючи нескінченне кровопролиття в Пустках.",al={"наступне життя понівечозуба","діалог понівечозуба"}}},fp="19,249,30.435.0,20.355.0,17.245.0,45.254.0,22.222.0,40.178.0,41.216.0,57.208.0"}
P.entries["quest:5045"] = {n="Піднесення духу",s="«Піднесення духу» — обрядове благословення, яке пропонує полонений геомант Гостроманів Понівечозуб у Таборі Тауражо. В обмін на криваві скалки, відібрані в його суперників-Щетиноспинів, Понівечозуб спрямовує прадавню силу Аґамаґґана, щоб зміцнити волю й духовну стійкість звитяжця.",h="«Піднесення духу» — обрядове благословення, яке пропонує полонений геомант Гостроманів Понівечозуб у Таборі...",kw={"піднесення духу","аґамаґґан","понівечозуб","криваві скалки","щетиноспини","табір тауражо"},ang={["class:Priest"]="Жерці впізнають у єднанні шипогривів з Аґамаґґаном сирий, первісний вияв віри й духу, що не поступається впорядкованим обрядам східних церков.",["class:Shaman"]="Шамани розуміють, як глибоко прадавня кров і земні мінерали можуть пов'язати духів землі зі смертним воїном.",["faction:Horde"]="Для мандрівників Орди в Пустках скористатися глибокою племінною ненавистю Понівечозуба до Щетиноспинів — означає перетворити полоненого докучливця на цінну тактичну перевагу."},sec={{t="Сила волі Гостроманів",b="Замкнений у клітці в Таборі Тауражо, старійшина Гостроманів Понівечозуб має глибокі знання про геомантію шипогривів і магію предків. Інші племена можуть хизуватися сирою бойовою люттю, а Понівечозуб неабияк пишається духовною відданістю свого народу творцеві — Великому Вепрові Аґамаґґану. Він учить, що саме незламний дух тримає воїна, коли сама лише сила в бою підводить, і жене звитяжців уперед, коли поразка здається неминучою."},{t="Сила кривавих скалок",b="Щоб викликати це духовне піднесення, Понівечозуб вимагає кривавих скалок — кришталевих уламків, просякнутих прадавньою кров'ю Аґамаґґана, що десять тисяч років тому всоталася в червону землю. Приносячи йому скалки, зібрані по всіх Пустках, а надто відібрані в його ворогів-Щетиноспинів, ви даєте йому той сирий духовний провідник, який потрібен, щоб сплести благословення піднесення духу й зміцнити вашу волю."}},faq={{q="Хто такий Понівечозуб?",a="Понівечозуб — старий шипогрив-Гостроман, якого тримають у дерев'яній клітці в Таборі Тауражо. Хоча він полонений Орди, він готовий ділитися священними геомантичними обрядами в обмін на Криваві скалки, руками мандрівників завдаючи ударів суперницькому племені Щетиноспинів.",al={"лор понівечозуба","хто кабан у клітці","в'язень тауражо"}},{q="Що таке Криваві скалки?",a="Криваві скалки — червоні мінеральні кристали, що утворилися з пролитої крові Прадавнього напівбога Аґамаґґана, який загинув у Пустках під час Війни Прадавніх. У них лишилася потужна магія, яку шамани й геоманти шипогривів використовують для благословень і обрядів.",al={"що таке криваві скалки","лор кривавих скалок","кров аґамаґґана"}},{q="Чому Понівечозуб допомагає шукачам пригод Орди?",a="Понівечозуб плекає гірку ненависть до суперників-Щетиноспинів. Вимінюючи благословення на Криваві скалки, він заохочує сильних шукачів пригод різати Щетиноспинів по всіх Пустках — і так продовжує ворожнечу свого племені навіть із клітки.",al={"чому понівечозуб допомагає","чому шипогрив допомагає орді"}},{q="Що дає благословення «Піднесення духу»?",a="«Піднесення духу» — потужне благословення предків від Понівечозуба, що зміцнює дух і внутрішню стійкість воїна, черпаючи з незгасної життєвої сили Аґамаґґана, щоб надія не згасала навіть у виснажливих сутичках.",al={"піднесення духу посилення","що таке піднесення духу"}},{q="Хто такий Аґамаґґан?",a="Аґамаґґан — велетенський Прадавній-Вепр, що десять тисяч років тому бився з Палаючим Легіоном під час Війни Прадавніх. Шипогриви шанують його як свого творця й вірять, що тернові хащі й червоні Криваві скалки Пусток виросли просто з його полеглого тіла.",al={"аґамаґґан","великий кабан"}},{q="Чи цей обряд — одноразовий обмін?",a="Ні. Доки ви приносите Понівечозубові чотири Криваві скалки, полонений старійшина охоче повторює обряд, щоб оновити благословення, перш ніж ви знову вирушите в пустелю.",al={"повторити піднесення духу","чи піднесення духу повторюване"}}},fp="13,287,26.448.0,25.406.0,19.267.0,22.258.0,44.251.0,40.214.0,17.277.0,32.184.0"}
P.entries["quest:5046"] = {n="Гостра шкура",s="«Гостра шкура» — повторюваний обряд, який пропонує полонений шипогрив Понівечозуб у Таборі Тауражо. Приносячи йому криваві скалки, просякнуті життєвою суттю Древнього бога-вепра Аґамаґґана, воїни й мандрівники можуть отримати могутнє благословення загартованої шкури й стійкості перед боєм.",h="«Гостра шкура» — повторюваний обряд, який пропонує полонений шипогрив Понівечозуб у Таборі Тауражо.",kw={"гостра шкура","аґамаґґан","понівечозуб","криваві скалки","табір тауражо","воїн"},ang={["class:Warrior"]="Бійцям передової, що вирушають у небезпечні колючі хащі південних Пусток, магічна броня й загартована шкура, що пом'якшують важкі удари, стануть у великій пригоді.",["faction:Horde"]="Табір Тауражо — опора Орди проти безупинного наступу шипогривів, і шана полоненого Понівечозуба до Аґамаґґана стає тут у пригоді мандрівникам.",["race:Tauren"]="Мисливці Табору Тауражо пильно стежать за кліткою Понівечозуба: хоч обряди шипогривів і торкаються священної землі Земної Матері, їхні дикі служителі рідко діляться таємницями задарма."},sec={{t="Благословення бога-вепра",b="Шипогриви ведуть свій родовід і силу прямо від Аґамаґґана — Великого Вепра, що загинув у боротьбі з Палаючим Легіоном тисячі років тому. Його кров просякла ґрунти Пусток і затверділа в кришталеві криваві скалки, що досі вібрують прадавньою силою. Хоч шипогриви — заприсяглі вороги Орди, Понівечозуб, замкнений у клітці в Таборі Тауражо, готовий поділитися їхніми священними знаннями в обмін на ці цінні уламки."},{t="Гартування шкури",b="Від природи шипогриви мають товсту шкуру й захисні колючки, але племінні воїни закликають благословення Аґамаґґана — Гостру шкуру, — щоб іще краще захиститися від ворожих клинків і пазурів. Спрямувавши силу чотирьох кривавих скалок, Понівечозуб повторює цей племінний обряд для чужинців і магією зміцнює захист шукача пригод, щоб у дикій глушині його кістки лишалися цілими, а шкура опиралася ранам."}},faq={{q="Хто пропонує обряд «Гостра шкура»?",a="Завдання дає Понівечозуб — ув'язнений шипогрив, якого тримають у дерев'яній клітці в Таборі Тауражо на півдні Пусток. Щойно ви доведете, що знаєтеся на Кривавих скалках, він пропонує різні благословення в обмін на нові скалки.",al={"хто дає гостру шкуру","завдання понівечозуба","хто починає гостру шкуру"}},{q="Що таке Криваві скалки?",a="Криваві скалки — кристалічні утворення, що трапляються по всіх Пустках. За віруваннями шипогривів, вони утворилися з пролитої крові Прадавнього Вепра Аґамаґґана під час Війни Прадавніх і зберігають величезний запас первісної магії.",al={"що таке криваві скалки","лор кривавих скалок","кров аґамаґґана"}},{q="Чому ув'язнений шипогрив допомагає мандрівникам Орди?",a="Понівечозуб — бранець тауренів у Таборі Тауражо. Він зберіг грубу вдачу й вірність своєму богові, але прагне Кривавих скалок і задля них готовий навчати чужинців обрядів шипогривів.",al={"чому понівечозуб допомагає","чому понівечозуб у тауражо","дружній шипогрив"}},{q="Який захист дає «Гостра шкура»?",a="«Гостра шкура» — племінний оберіг, який шипогриви закликають перед битвою. Він потовщує шкіру й зміцнює кістки, посилюючи природний захист надприродною витривалістю Аґамаґґана.",al={"що робить гостра шкура","лор гострої шкури","захисне благословення"}},{q="Чи можна отримати «Гостру шкуру» не раз?",a="Так. Як і всі дари Понівечозуба, «Гостру шкуру» можна отримувати повторно. Щоразу, як ви приносите йому чотири Криваві скалки, він закликає для вас благословення.",al={"чи гостра шкура повторювана","повторити гостру шкуру","скільки разів гостра шкура"}},{q="Де шукати Криваві скалки?",a="Криваві скалки зазвичай здобувають у геомантів, мисливців і воїнів у різних таборах шипогривів, серед тернових хащ і скель по всіх Пустках.",al={"місця кривавих скалок","де взяти криваві скалки","фарм кривавих скалок"}}},fp="9,299,25.464.0,18.398.0,32.224.0,22.246.0,54.209.0,49.204.0,41.162.0,32.156.0"}
P.entries["quest:5061"] = {n="Водяна форма",s="«Водяна форма» — завершальний обряд посвяти для друїдів Альянсу, що вчаться єднати свій дух із глибокими водами. Зібравши розколоті половинки Амулета Морського Лева в Калімдорі та Східних Королівствах і з'єднавши їх у Місячному Гаю, посвячувані повертаються до Дарнасуса, щоб відкрити свою нову подобу.",h="«Водяна форма» — завершальний обряд посвяти для друїдів Альянсу, що вчаться єднати свій дух із глибокими...",kw={"водяна форма","амулет морського лева","матренґіл берволкер","дендрит старблейз","місячний гай","друїд","морський лев"},ang={["class:Druid"]="Це завдання — важлива віха у вашому єднанні з природою: воно дає змогу швидко пересуватися під водою й дихати під її поверхнею скільки завгодно.",["faction:Alliance"]="Пройшовши друїдські випробування, ви даєте Альянсу розвідника, що легко долає озера, ріки й морські береги.",["race:NightElf"]="Для посвячуваних нічних ельфів повернення з позачасових лісів Місячного Гаю до молодої крони Тельдрассилу утверджує їхній обов'язок берегти дику природу Азероту в часи, коли рівновага хитається."},sec={{t="Священний зв'язок із глибинами",b="Для посвячуваного Кола Кенарія зміна подоби — не просто чаклунство, а духовне єднання з дикими образами Азероту. Довівши свою витривалість у темних прибережних глибинах і пройшовши випробування в Місячному Гаю, молоді друїди нічних ельфів отримують від Дендрита Старблейза зібраний Амулет Морського Лева. Принесений назад на Тельдрассил, цей священний знак стає живим доказом того, що посвячуваний шанує природні закони повітря, води й подиху."},{t="Повернення до Дарнасуса",b="У гіллі Ценаріонського Анклаву повернення учня чекає старший наставник друїдів Матренґіл Берволкер. Випробування біля моря — на Темному Узбережжі й у Вестфолі — вимагають неабиякої витривалості й чуйності. Показуючи Берволкерові відновлений амулет, посвячуваний доводить, що його розум і тіло готові скинути смертну шкіру й прийняти прудкий образ морського лева, що дихає під водою."}},faq={{q="Яка мета цього завдання?",a="Це завдання — останній крок у навчанні друїда Альянсу, що опановує Водяну форму. Показавши відновлений Амулет Морського Лева Матренґілу Берволкеру в Дарнасусі, друїд здобуває право навчитися водяної подоби.",al={"навіщо це завдання","мета водяної форми","що дає це завдання"}},{q="Хто відсилає мене назад до Дарнасуса?",a="Дендрит Старблейз, старійшина Кола Кенарія зі священного притулку Місячний Гай, відсилає вас назад на Тельдрассил, коли ви успішно пройдете Випробування Морського Лева.",al={"хто відсилає до дарнасуса","хто дає завдання","дендрит старблейз"}},{q="Хто завершує ваше навчання в Дарнасусі?",a="Матренґіл Берволкер, наставник друїдів у Ценаріонському Анклаві в Дарнасусі, приймає ваш амулет і навчає вас водяної подоби.",al={"здати завдання","хто здає водяну форму","матренґіл берволкер"}},{q="Що таке Амулет Морського Лева?",a="Амулет Морського Лева — священний талісман, складений із двох амулетів випробування, піднятих із глибин біля берегів Темного Узбережжя й Вестфолу. Він — відчутний доказ того, що друїд опанував витривалість і терпіння, властиві морським істотам.",al={"що таке амулет морського лева","амулет"}},{q="Чи виконують друїди Орди саме це завдання?",a="Ні. Друїди-таурени теж проходять випробування в Місячному Гаю, щоб здобути водяну подобу, але їхній шлях веде назад до Турака Рунтотема на столових горах Тандер Блафу, а не до Дарнасуса.",al={"чи таурени можуть це","чи завдання лише для альянсу","версія орди"}},{q="Де в Дарнасусі знайти Матренґіла Берволкера?",a="Матренґіл Берволкер — у Ценаріонському Анклаві, пишному святилищі в північно-західному кварталі Дарнасуса на гіллі Тельдрассилу.",al={"де матренґіл","місце тренера друїдів дарнасу"}}},fp="12,331,29.497.0,19.420.0,34.246.0,32.182.0,41.162.0,36.269.0,36.193.0,44.152.0"}
P.entries["quest:5062"] = {n="Священний вогонь",s="«Священний вогонь» — обряд посвяти Орди, що поєднує зубчасті каньйони Тисячі Голок із висотами Тандер Блафа. Щоб прикликати й прогнати мстивого вітряного змія Арікару, мисливці мають зібрати рідкісну Інцендію-Агаву в Киплячому Ставку, а Маґата Ґрімтотем зачарує її на обрядовий порошок.",h="«Священний вогонь» — обряд посвяти Орди, що поєднує зубчасті каньйони Тисячі Голок із висотами Тандер Блафа.",kw={"священний вогонь","інцендія-агава","киплячий ставок","арікара","маґата ґрімтотем","мотеґа фаєрмейн","шпиль темної хмари"},ang={["class:Shaman"]="Це завдання показує практичне застосування шаманської магії: силу стихій можна вкласти в природну рослину, як-от Інцендія-Агава.",["faction:Horde"]="Випробування для старійшин зміцнюють зв'язки Орди на посушливих рівнинах Калімдору.",["profession:Herbalism"]="Травники мають помітну перевагу, коли шукають колючі кущики Інцендії-Агави, що ховаються під водою Киплячого Ставка.",["race:Tauren"]="Для мисливців-тауренів ушанування духів через обрядове полювання й уміння лавірувати в політиці старійшин на Узвишші Старійшин — основний обряд дорослішання."},sec={{t="Розпалити дух",b="Страхітливого вітряного змія Арікару не вистежиш на дні каньйону — його треба прикликати. Мотеґа Фаєрмейн навчає мисливців готувати священний вогонь життя — прадавнє обрядове полум'я, що служить маяком для звіра-духа. Щоб живити цей вогонь, звичайного хмизу замало: потрібна рідкісна Інцендія-Агава, що росте лише довкола гарячих вод Тисячі Голок."},{t="Киплячий Ставок",b="Інцендія-Агава буяє біля Киплячого Ставка — нагрітого надрами озера під Шпилем Темної Хмари. Щоб зібрати цей колючий сукулент, доведеться витримати пекучу воду й мінливих елементалів пари, що пливуть у тумані. Чимало кущиків росте під водою, тож мисливцеві, якого послали по них, знадобиться неабияка витривалість."},{t="Благословення старійшини",b="Сама лише сира агава не розпалить обрядової жаровні. Зібрані рослини треба віднести високо над рівнинами — на Узвишшя Старійшин у Тандер Блафі. Там стара шаманка Маґата Ґрімтотем своїм мистецтвом розтирає й зачаровує листя на могутній обрядовий порошок — і, судячи з усього, щиро прагне, щоб мстивому звірові кинули виклик."}},faq={{q="Що таке священний вогонь життя?",a="Це обрядове полум'я, яким прикликають мстивого духа-змія Арікару. Не запаливши цього священного вогню, звіра не знайти й не дістати.",al={"священний вогонь","що робить вогонь","навіщо запалювати священний вогонь"}},{q="Де росте Інцендія-Агава?",a="Інцендія-Агава росте в Кипучій Ковбані й довкола неї в Тисячі Голок, біля підніжжя Шпиля Темної Хмари. Чимало цих колючих рослин росте під водою гарячого озера.",al={"де інцендія-агава","де агава","агава біля киплячого басейну"}},{q="Чому Маґата Ґрімтотем має зачарувати агаву?",a="Сирій рослині бракує магічної сили, щоб запалити священний вогонь. Як могутня шаманка, Маґата вплітає в листя стихійну енергію, перетворюючи його на порошок, здатний пробудити приспане полум'я.",al={"чому маґата зачаровує агаву","хто зачаровує агаву","що робить маґата"}},{q="Хто така Арікара?",a="Арікара — грізний вітряний змій, народжений, щоб мститися тим, хто чинить жахливі злочини. Мотеґа Фаєрмейн вважає її появу неминучою небезпекою, проти якої потрібні вправні мисливці.",al={"що таке арікара","арікара лор","бос вітряних змій"}},{q="Хто дає завдання «Священний вогонь»?",a="Завдання дає Мотеґа Фаєрмейн у Тисячі Голок, коли ви допоможете йому з першими дорученнями щодо місцевої зміїної загрози.",al={"хто дає священний вогонь","де почати священний вогонь"}},{q="Чому Маґата всміхається, почувши про Арікару?",a="Маґату тішить чи задовольняє згадка про істоту, народжену лише для того, щоб карати за мерзенні вчинки, — натяк на її темний погляд на помсту й племінну політику.",al={"чому маґата всміхається","реакція маґати","маґата всміхається"}}},fp="11,304,19.399.0,16.346.0,20.319.1,32.149.0,31.180.0,45.211.0,15.201.0,32.132.0,49.170.0"}
P.entries["quest:5064"] = {n="Шпигунство Ґрімтотемів",s="Скельний Вартовий Лонггорн доручає героям Орди проникнути на Шпиль Темної Хмари й дізнатися, що замишляє потайний клан Ґрімтотем. На столову гору навідалися троє невідомих посланців, і після них у гірському селищі лишилося ретельно сховане листування. Розкривши ці таємні записки, ви викриєте задум, що загрожує тауренським поселенням Тисячі Голок.",h="Скельний Вартовий Лонггорн доручає героям Орди проникнути на Шпиль Темної Хмари й дізнатися, що замишляє...",kw={"шпигунство ґрімтотемів","ґрімтотем","шпиль темної хмари","скельний вартовий лонггорн","таємні записки","застава вільного вітру"},ang={["class:Rogue"]="Зібрати три скрині по підвісних мостах і пильно охоронюваних будівлях Шпиля Темної Хмари — ідеальна таємна операція, де скритність винагороджується краще за відкритий бій.",["faction:Horde"]="Застава Вільного Вітру — життєво важлива опора Орди на півдні Калімдору. Будь-які підривні змови серед Ґрімтотемів на Шпилі Темної Хмари загрожують хитким шляхам постачання між Пустками й Танарісом.",["race:Tauren"]="Зрада клану Ґрімтотем болісно вражає тауренів, чиє суспільство цінує гармонію й родинну честь. Дізнатися, що родичі таємно зустрічаються з невідомими змовниками, — загроза всьому, що збудував Кайрн Бладгуф."},sec={{t="Очі на вітрі",b="Застава Вільного Вітру хитко тримається на високих шпилях, і її захисникам доводиться повсякчас озиратися на ворожих родичів. Клан Ґрімтотем здавна тримається напружено й неприязно щодо Орди й чіпляється за свої відокремлені твердині на Шпилі Темної Хмари. Скельний Вартовий Лонггорн помітив зміну в їхній поведінці, коли впродовж кількох тижнів один за одним прибули троє загадкових посланців і таємно радилися з проводом клану. Лонггорн підозрює, що ці посланці принесли накази чи пропозиції союзу, покликані підірвати становище Тандер Блафа в каньйоні."},{t="Проникнення на Шпиль Темної Хмари",b="Шпиль Темної Хмари — укріплена мережа стрімких столових гір, з'єднаних дерев'яними канатними мостами. Щоб проникнути в селище, доведеться пройти повз щільні патрулі ворожих воїнів і шаманів-Ґрімтотемів. Розвідники Лонггорна з'ясували, що загадкові послання замкнено в окремих скринях, розставлених по центральних оселях застави й на зовнішніх кручах. Щоб здобути три таємні записки, доведеться прокрастися чи пробитися через усе селище й вихопити приватне листування клану з-під пильних очей."},{t="Зловісні прикмети",b="Три здобуті записки, принесені Скельному Вартовому Лонггорну, підтверджують найгірші побоювання Застави Вільного Вітру. Листування показує, що Ґрімтотеми не просто погрожують — вони діють разом зі сторонніми агентами, готуючи якийсь крок. Хоч повний розмах їхніх підступів досі оповитий таємницею, Лонггорн негайно береться складати плани, як уберегти застави в каньйоні від раптової зради."}},faq={{q="Хто посилає агентів на зустрічі з Ґрімтотемами?",a="Скельний Вартовий Лонггорн знає лише те, що останніми тижнями на Шпилі Темної Хмари бачили трьох агентів невідомого походження. Хто саме стоїть за ними, суворо приховано в записках, які пильно стережуть.",al={"хто відвідав ґрімтотемів","таємні агенти ґрімтотемів","хто надіслав записки"}},{q="Де розташований Шпиль Темної Хмари?",a="Шпиль Темної Хмари — на заході Тисячі Голок, на південний схід від Великого Підйомника. Позначена синім тотемом стежка веде кручами столової гори до селища, де дерев'яні мости з'єднують кілька високих шпилів.",al={"де шпиль темної хмари","як дістатися шпиля темної хмари","вхід шпиля темної хмари"}},{q="Чому Ґрімтотеми ворожі до інших тауренів?",a="Ґрімтотеми вважають тауренів вищими за всі інші раси й люто відкидають союз Кайрна Бладгуфа з Ордою. Деякі Ґрімтотеми живуть у Тандер Блафі в хиткому мирі, але клани на кшталт тих, що на Шпилі Темної Хмари, відкрито ворогують і з Ордою, і з Альянсом.",al={"чому ґрімтотеми ненавидять орду","ґрімтотеми проти тандер блафа","чи ґрімтотеми злі"}},{q="Хто дає завдання «Шпигунство Ґрімтотемів»?",a="Завдання дає Скельний Вартовий Лонггорн на Заставі Вільного Вітру в Тисячі Голок — але тільки після того, як ви доведете свою надійність, виконавши попередні доручення застави.",al={"хто дає шпигунство ґрімтотемів","дає завдання шпигунства"}},{q="Які завдання треба виконати перед цим?",a="Треба виконати «Послання до Застави Вільного Вітру» й «Утихомирити кентаврів», перш ніж Скельний Вартовий Лонггорн довіриться вам настільки, щоб доручити шпигунську місію проти Ґрімтотемів.",al={"передумови шпигунства ґрімтотемів","як відкрити шпигунство ґрімтотемів","ланцюжок шпигунства ґрімтотемів"}},{q="Що стається, коли здати три таємні записки?",a="Прочитавши їх, Скельний Вартовий Лонггорн приголомшений і називає звістку тривожною. Він визнає, що Застава Вільного Вітру має негайно готувати оборону від того, що задумали Ґрімтотеми.",al={"завершення шпигунства ґрімтотемів","що кажуть записки"}}},fp="16,381,16.574.0,34.512.0,13.410.1,49.216.0,36.216.0,46.303.0,37.166.0,54.181.0,53.213.1"}
P.entries["quest:5088"] = {n="Арікара",s="«Арікара» — кульмінація зловісного доручення, яке дає Маґата Ґрімтотем у Тандер Блафі. Переконана, що прадавній вітряний змій полює на Верховного Вождя Кайрна Бладгуфа, стара шаманка посилає шукачів пригод Орди прикликати й убити звіра на поховальних скелях Тисячі Голок.",h="«Арікара» — кульмінація зловісного доручення, яке дає Маґата Ґрімтотем у Тандер Блафі.",kw={"арікара","маґата ґрімтотем","вітряний змій","кайрн бладгуф","тисяча голок","мотеґа фаєрмейн"},ang={["class:Shaman"]="Шамани помітять тертя між обрядами стихій і політичними інтригами, а також небажання Мотеґи сперечатися з незрівнянною духовною владою Маґати.",["faction:Horde"]="Присягнувши захищати Кайрна Бладгуфа, воїни Орди охоче вирушають до Тисячі Голок, щоб знешкодити будь-яку загрозу шанованому Верховному Вождеві.",["race:Tauren"]="Для тауренів це завдання торкається напруги між прадавніми обрядами предків і політичними змінами під проводом Кайрна Бладгуфа — напруги, на якій завжди вміють грати розважливі Ґрімтотем."},sec={{t="Звір у диму",b="Отримавши очищений Інцендієвий Порошок, Маґата Ґрімтотем зачаровує реактив, щоб той став каталізатором прикликання. Вона застерігає, що прадавні традиції тауренів надто швидко змінилися в новому союзі з Ордою, і це розбудило помсту Арікари — лютого духа вітряного змія. Маґата скеровує героїв на південь, до продуваного вітрами каньйону Тисячі Голок, і велить кинути порошок на обрядове вогнище серед високих поховань Шпиля Темної Хмари."},{t="Сумніви на Заставі Білого Рубежу",b="Убивши змія на поховальній скелі й забравши його шкуру, шукачі пригод приносять рештки на Заставу Білого Рубежу, до Мотеґи Фаєрмейна. Замість полегшення Мотеґа відчуває щиру розгубленість. Йому не віриться, що первісний дух, як-от Арікара, міг затаїти злобу на Кайрна Бладгуфа. Проте, не бажаючи відкрито ставити під сумнів становище Маґати як наймогутнішої шаманки племені, Мотеґа відкладає свої підозри й винагороджує звитяжця за захист вождя."}},faq={{q="Хто така Арікара?",a="Арікара — могутній вітряний змій, якого прикликають на вершині Шпиля Темної Хмари в Тисячі Голок. Маґата Ґрімтотем стверджує, що звіра збудили до помсти сучасні відступи від традиційних тауренських переказів.",al={"що таке арікара","арікара лор","хто змія"}},{q="Чому Маґата Ґрімтотем хоче смерті Арікари?",a="Маґата стверджує, що Арікара полює на Кайрна Бладгуфа, Верховного Вождя тауренів. Вона посилає вас знищити змія за допомогою зачарованого порошку інцендії, перш ніж той загрожуватиме провідникові Тандер Блафу.",al={"мотивація маґати","чому вбити арікару","чому закликати арікару"}},{q="Де священний вогонь, щоб її прикликати?",a="Незапалений священний вогонь життя стоїть на вершині відокремленого шпиля на Шпилі Темної Хмари в Тисячі Голок — високій столовій горі, де місцеві таурени ховають своїх мерців.",al={"місце арікари","де закликати арікару","місце священного вогню життя"}},{q="Чому Мотеґа Фаєрмейн сумнівається в цьому полюванні?",a="Маґата боїться, що Арікара полює на Кайрна, і просить вас принести Мотеґі доказ полювання. Як відгукнеться Мотеґа, з'ясується, коли ви принесете рештки.",al={"реакція мотеґи","чому мотеґа збентежений","чи має сенс арікара проти кайрна"}},{q="Чи справді Кайрнові загрожує Арікара?",a="Маґата каже, що боїться, ніби Арікара полює на Кайрна. Завдання просить вас діяти за її застереженням, але саме цієї небезпеки не підтверджує.",al={"чи справді на кайрна полювали","чи арікара полював на кайрна","чи маґата бреше"}},{q="Яке попереднє завдання в цьому ланцюжку?",a="Це завдання безпосередньо продовжує «Священний вогонь», де шукачі пригод збирають Інцендію-Агаву в Кипучій Ковбані в Тисячі Голок, щоб Маґата Ґрімтотем зачарувала її в порошок інцендії.",al={"передумова арікари","завдання перед арікарою","завдання священного вогню"}}},fp="7,290,20.477.0,24.478.1,15.199.0,45.201.0,47.170.0,45.155.1,42.144.1,41.182.0"}
P.entries["quest:509"] = {n="Еліксир Агонії",s="У Таррен Міллі Аптекар Лайдон наймає шукачів пригод з Орди збирати отруйні гриби на захопленому хуторі в Передгір'ї Гілсбреда. Ці заразні Суцвіття Багнорила — важлива сировина для похмурих хімічних дослідів Королівського Аптекарського Товариства. Отримана суміш має допомогти довготривалому задуму Леді Сильвани знищити і живих, і Погибель.",h="У Таррен Міллі Аптекар Лайдон наймає шукачів пригод з Орди збирати отруйні гриби на захопленому хуторі в...",kw={"еліксир агонії","суцвіття багнорила","хутір нетандера","гноли","аптекар лайдон","таррен мілл","завдання"},ang={["faction:Horde"]="Посланцям Орди в Таррен Міллі доводиться поєднувати допомогу союзникам-Відступникам із тривожною правдою про їхні хімічні досліди.",["profession:Herbalism"]="Травники й збирачі впізнають Суцвіття Багнорила як рідкісний, надзвичайно отруйний гриб, що буйно росте в необробленій землі, отруєній гнолячими таборами.",["race:Undead"]="Для агентів-Відступників допомога Лайдонові — прямий внесок у життєво важливу роботу Королівського Аптекарського Товариства, що боронить Лордерон і від людства, і від Короля-Ліча."},sec={{t="Чума в роботі",b="Поки Погибель спустошує північ, а Альянс чіпляється за містечка на кшталт Саутшора, Відступники шукають власного розважливого розв'язку: створити особливу смертоносну чуму. Працюючи в каплиці-лабораторії Таррен Мілла, Аптекар Лайдон виконує доручення Темної Леді. Хоч сам він цинічно ставиться до нудної алхімічної праці, Лайдон сумлінно збирає потужні органічні отрути в довколишньому краї, щоб варити еліксири, здатні прискорити взаємне знищення ворогів Сильвани."},{t="Поля Хутора Нетандера",b="На південь від Таррен Мілла, на схід від річки, лежить Хутір Нетандера — покинуте людське господарство, яке тепер захопили люті гноли-Багнорили. Серед бруду й занедбаної землі буйно ростуть дивні смердючі гриби, відомі як Суцвіття Багнорила. Ці великі, їдкі на запах наростки містять концентровані органічні отрути, які дуже цінує Королівське Аптекарське Товариство. Щоб їх добути, доведеться прорубатися крізь зграї гнолів або тихо прослизнути повз їхні вбогі табори."}},faq={{q="Хто такий Аптекар Лайдон?",a="Аптекар Лайдон — алхімік Королівського Аптекарського Товариства в Таррен Міллі в Передгір'ї Гілсбреда. Працюючи на Леді Сильвану Віндраннер, він удосконалює смертоносні суміші й розробляє нову чуму, щоб здолати і живих смертних, і Погибель.",al={"лайдон","хто такий лайдон","аптекар лайдон лор"}},{q="Навіщо потрібні Суцвіття Багнорила?",a="Суцвіття Багнорила — отруйні смердючі гриби, яких збирають на Хуторі Нетандера. Аптекар Лайдон використовує їхні сильні природні отруйні властивості як основу для Еліксиру Агонії — частини ширших досліджень Відступників у хімічній і біологічній війні.",al={"суцвіття багнорила","навіщо гриби","використання суцвіття"}},{q="Де розташований Хутір Нетандера?",a="Хутір Нетандера — зарослий хутір на південь від Таррен Мілла, на схід від великої річки, що тече повз Саутшор. Ферму захопили агресивні гноли-Багнорили, які стережуть поля, де ростуть гриби.",al={"місце хутора нетандера","де хутір нетандера","де гноли"}},{q="Навіщо Відступникам нова чума?",a="Леді Сильвана й Відступники шукають зброю, досить потужну, щоб знищити і невблаганну Погибель, і ворожі живі народи Альянсу. Створивши власну чуму, Королівське Аптекарське Товариство прагне забезпечити Відступникам незалежність і виживання в Лордероні.",al={"навіщо чума","причина чуми відступників","чума сильвани"}},{q="Чому Лайдон нарікає, що мусить варити ці еліксири?",a="Лайдон трохи втомлений і похмурий: він зауважує, що люди й Погибель і без сторонньої допомоги охоче вирізають одне одного. Але Леді Сильвана хоче пришвидшити їхнє взаємне знищення, тож він виконує накази й далі варить смертоносні напої.",al={"ставлення лайдона","чому лайдон цинічний"}},{q="Що буде, коли суцвіття зібрано?",a="Отримавши Суцвіття Багнорила, Лайдон береться варити отруйну суміш і невдовзі потребує нових складників і польових випробувань, щоб еліксир набув найвищої смертоносності.",al={"наступне завдання","що після еліксиру агонії"}}},fp="15,377,22.526.0,29.448.0,24.280.0,36.270.0,33.226.0,48.283.0,59.277.0,43.197.0"}
P.entries["quest:513"] = {n="Еліксир Агонії",s="Це доручення несе свіжоприготований Порошок Багнорила Аптекаря Лайдона з Таррен Мілла просто до серця Королівського Аптекарського Товариства в Андерсіті. Головному Аптекареві Фаранеллу потрібна ця рослинна основа, щоб обробити її колоїдом розкладу й посунути далі роботу Відступників над новою чумою.",h="Це доручення несе свіжоприготований Порошок Багнорила Аптекаря Лайдона з Таррен Мілла просто до серця...",kw={"еліксир агонії","порошок багнорила","аптекар лайдон","таррен мілл","головний аптекар фаранелл","аптекаріум","нова чума"},ang={["faction:Horde"]="Орда покладається на землі Відступників, щоб утримати північ Лордерона, і дослідження Королівського Аптекарського Товариства — важлива частина оборони цих уразливих кордонів.",["race:Undead"]="Кожна партія сировини, доставлена Фаранеллу, служить виживанню Відступників і обороні їхньої держави — і від живих, і від Погибелі."},sec={{t="Гонець до столиці",b="У невпинній роботі Королівського Аптекарського Товариства дослідники з околиць часто відсилають свої сирі знахідки до Андерсіті на особливу обробку. Аптекар Лайдон розтер місцеві Суцвіття Багнорила на порошок, але щоб довести його до смертоносної сили, потрібні складні реагенти, які тримають лише в столичній лабораторії."},{t="Нагальність майстра",b="Головний Аптекар Фаранелл працює в Апотекаріумі під величезним тиском. Відступники опинилися між вічною тінню Погибелі на півночі й завзятими людськими поселеннями на півдні, і Леді Сильвана Віндраннер зажадала нової сильнодійної чуми, щоб боронити свій народ. Порошок Лайдона дає Фаранеллу саме той отруйний прорив, якого чекає Темна Леді."}},faq={{q="Навіщо нести Порошок Багнорила до Андерсіті?",a="Аптекареві Лайдону в Таррен Міллі бракує особливих реагентів, щоб завершити цей етап досліду. Головний Аптекар Фаранелл тримає в Апотекаріумі колоїд розкладу, яким треба обробити Порошок Багнорила, перш ніж суміш зможе працювати далі.",al={"чому до андерсіті","місце суміші багнорила","чому нести фаранеллу"}},{q="Хто такий Головний Аптекар Фаранелл?",a="Головний Аптекар Фаранелл очолює Королівське Аптекарське Товариство зі своєї лабораторії в глибинах Андерсіті. Він керує всіма головними хімічними й алхімічними дослідженнями Відступників і звітує безпосередньо Леді Сильвані Віндраннер.",al={"хто такий фаранелл","лор головного аптекаря фаранелла","лідер аптекаріуму"}},{q="Що за нову чуму постійно згадують аптекарі?",a="Нова чума — невпинний проєкт Відступників за наказом Леді Сильвани. Її створюють, щоб знищити і живих, і нежить Погибелі, давши Відступникам абсолютну зброю проти ворогів.",al={"що за нова чума","проєкт чуми відступників","чому нова чума"}},{q="Де знайти Головного Аптекаря Фаранелла?",a="Фаранелл — в Апотекаріумі, південно-західному кварталі Андерсіті, цілком відданому алхімії, варінню отрут і хірургічним дослідам.",al={"де фаранелл","місце фаранелла","місце аптекаріуму"}},{q="Що намагається створити Аптекар Лайдон?",a="Лайдон варить Еліксир Агонії — надзвичайно заразну отруту з рослин Гілсбреда й речовин розкладу, яка має довести дієвість нових штамів у польових умовах.",al={"що створює лайдон","мета еліксиру агонії","експеримент лайдона"}},{q="Чому Королівське Аптекарське Товариство так поспішає?",a="Відступники бачать загрози з усіх боків. Погибель із Нортренду загрожує їх захлеснути, а рештки людського опору невпинно тиснуть із півдня, тож рішуча біологічна зброя потрібна вкрай терміново.",al={"чому поспішати","фаранелл зайнятий","загроза андерсіті"}}},fp="15,304,24.340.0,20.392.0,62.260.0,34.225.0,56.214.0,44.160.0,42.179.0,46.242.0"}
P.entries["quest:5147"] = {n="Розшукується — Арнак Ґрімтотем",s="«Розшукується: Арнак Ґрімтотем» — оголошення Орди про нагороду на Заставі Вільного Вітру, що вимагає стратити жорстокого вигнанця з клану Ґрімтотем. Місцева влада переслідує Арнака за вбивство й викрадення на столових горах над каньйоном.",h="«Розшукується: Арнак Ґрімтотем» — оголошення Орди про нагороду на Заставі Вільного Вітру, що вимагає стратити...",kw={"розшукується","арнак ґрімтотем","шпиль темної хмари","лакота віндсонг","скельний вартовий лонггорн","нагорода"},ang={["faction:Horde"]="Застава Вільного Вітру — життєво важлива опора Орди в Тисячі Голок, і знищення безжальних ренегатів на Шпилі Темної Хмари убезпечує висоти над дном каньйону.",["race:Tauren"]="Для тауренів, вірних Кайрнові Бладгуфу, вистежити Арнака — акт племінного правосуддя: покарати братовбивцю, що зганьбив їхні традиції, викравши Лакоту Віндсонг."},sec={{t="Жахливий злочин",b="Стосунки між тауренами Орди й відлюдним племенем Ґрімтотем завжди напружені, але Арнак зайшов далеко за межі політичних тертів. Затаврований як вигнанець, Арнак убив таурена й викрав сестру загиблого, Лакоту Віндсонг. У відповідь на ці мерзенні вчинки Скельний Вартовий Лонггорн із Застави Вільного Вітру оголосив відкриту нагороду за смерть свавільного таурена."},{t="Шпиль Темної Хмари",b="Арнак сховався на високих кручах Шпиля Темної Хмари — розлогій мережі канатних мостів і таборів на столових горах, які займає клан Ґрімтотем неподалік входу до Рейзорфен Даунс. Разом з Арнаком на цих вітряних висотах опинилася його бранка, Лакота Віндсонг, що чекає порятунку від кожного, хто наважиться пробитися через мости Ґрімтотемів."}},faq={{q="Хто такий Арнак Ґрімтотем?",a="Арнак Ґрімтотем — сумнозвісний таурен-вигнанець, що вчинив убивство й викрав Лакоту Віндсонг. Через його жорстокі злочини Застава Вільного Вітру оголосила винагороду за його голову.",al={"хто такий арнак","арнак ґрімтотем лор","хто той розшукуваний таурен"}},{q="Де знайти Арнака Ґрімтотема?",a="Він — високо на північних кручах Шпиля Темної Хмари в Тисячі Голок; дістатися туди можна звивистою стежкою на південь від Великого Підйомника, а далі високими дерев'яними мостами в бік Рейзорфен Даунс.",al={"де арнак","місце арнака ґрімтотема","як знайти арнака"}},{q="Хто така Лакота Віндсонг?",a="Лакота Віндсонг — таурка, яку Арнак тримає в полоні на Шпилі Темної Хмари. Під час викрадення Арнак убив її брата, і вона лишається в пастці на горі, доки з Арнаком не розберуться.",al={"хто така лакота","історія лакоти віндсонг"}},{q="Хто платить винагороду?",a="Винагородою опікується Скельний Вартовий Лонггорн на Заставі Вільного Вітру. Він нагороджує мандрівників, які принесуть відрубане копито Арнака як доказ того, що таурена-відщепенця покарано.",al={"хто здає арнака","здати нагороду","нагорода кліфвочера лонггорна"}},{q="Чи Арнак офіційно служить племені Ґрімтотем?",a="В оголошенні про винагороду Арнака прямо названо вигнанцем — отже, він діяв поза будь-яким племінним законом. Проте сховався він у твердині Ґрімтотемів на Шпилі Темної Хмари.",al={"чи арнак служить ґрімтотемам","статус племені арнака"}},{q="Який доказ потрібен, щоб отримати винагороду?",a="Мисливці мають відрубати й принести Копито Арнака Скельному Вартовому Лонггорну на Заставі Вільного Вітру, щоб підтвердити його смерть і отримати нагороду.",al={"що принести кліфвочеру","доказ арнака","копито арнака"}}},fp="24,219,16.400.0,18.352.0,23.168.0,35.217.0,23.192.0,29.172.0,52.190.0,43.128.0"}
P.entries["quest:515"] = {n="Еліксир Агонії",s="Це доручення продовжує роботу Королівського Аптекарського Товариства над новою чумою: гонця відсилають з Андерсіті назад до Таррен Мілла. Головний Аптекар Фаранелл збагачує суміш Лайдона власними складниками розкладу й вимагає прибережних реагентів та алхімічних настоянок, щоб запустити смертоносне вариво.",h="Це доручення продовжує роботу Королівського Аптекарського Товариства над новою чумою: гонця відсилають з...",kw={"еліксир агонії","суміш багнорила","аптекар лайдон","головний аптекар фаранелл","таррен мілл","умпі","гілсбред"},ang={["faction:Horde"]="Таррен Мілл живе на межі постійних прикордонних сутичок з Альянсом із Саутшора, і отруйні досліди Лайдона мають схилити рівновагу сил у краї.",["race:Undead"]="Кожен очищений реагент у цьому ланцюжку завдань наближає Королівське Аптекарське Товариство до здійснення волі Леді Сильвани — остаточної зброї проти живих."},sec={{t="Колоїд розкладу",b="Коли польова робота Аптекаря Лайдона дала сильнодійний порошок із Суцвіть Багнорила, зібраних на захопленому гнолами Хуторі Нетандера, він відіслав його просто до Апотекаріуму в Андерсіті. Головний Аптекар Фаранелл, очільник Королівського Аптекарського Товариства, одразу розпізнав похмурий потенціал цього варива. Задоволений його отруйними властивостями, Фаранелл додав до суміші власний особливий колоїд розкладу й пояснив, які каталізатори потрібні, щоб обернути її на справжню зброю."},{t="Каталізатори з узбережжя",b="Щоб пробудити нестійкі заразні речовини, потрібні точні реагенти, які Лайдон має зібрати в Таррен Міллі. Окрім відновної настоянки Сильної Тролячої Крові, що живить і стабілізує реакцію, Фаранелл вимагає органічних складників із південного узбережжя Гілсбреда: луски, здертої зі зміїстих наг Кинджалоспинних, і очей, вирізаних у прибережних мурлоків Подертих Плавців."},{t="Жорстокість у Таррен Міллі",b="У Таррен Міллі Лайдон збавляє час очікування похмурою забавою: раз по раз труїть, заражає й знову оживляє свого нещасного піддослідного з нежиті, Умпі. Збагачена суміш Фаранелла й прибережні каталізатори наближають аптекаря до головної мети — досконалої нової зарази, яку він випустить на живі поселення Гілсбреда."}},faq={{q="Навіщо чумі цілюще зілля тролячої крові?",a="Аптекарські суміші часто містять відновлювальні речовини, щоб підтримувати, живити й швидко мутувати агресивні біологічні збудники. Цілющі властивості Міцної Тролячої Крові не дають отруйним культурам загинути, доки вони не вступлять у реакцію з іншими тканинами.",al={"навіщо чумі кров тролів","призначення крові сильних тролів","еліксир крові тролів чума"}},{q="Де взяти луску Кинджалоспинних?",a="Луску Кинджалоспинних знімають із ворожих наг Кинджалоспинних, що населяють східні пляжі Передгір'я Гілсбреда, на узбережжі на схід від містечка Альянсу Саутшор.",al={"місце луски кинджалоспинних","де луска нагів","де взяти луску"}},{q="Де добути очі Подертих Плавців?",a="Очі Подертих Плавців збирають із мурлоків Подертих Плавців, що живуть племенами на західному узбережжі Передгір'я Гілсбреда, трохи на захід від Саутшора.",al={"місце ока подертих плавців","де подерті плавці","очі мурлоків хілсбрад"}},{q="Хто такий Умпі?",a="Умпі — жаба, яку Аптекар Лайдон тримає в Таррен Міллі як «помічницю». У вільні години Лайдон використовує її як одноразового піддослідного: раз у раз отруює її смертельними отрутами й хворобами, а тоді знову оживлює.",al={"хто такий умпі","умпі хілсбрад","помічник лайдона умпі"}},{q="Чому до цього місцевого проєкту причетний Головний Аптекар Фаранелл?",a="Як очільник Королівського Аптекарського Товариства, Фаранелл наглядає за всіма дослідженнями нових біологічних збудників і чум. Польові аптекарі на кшталт Лайдона надсилають багатообіцяльні знахідки просто Фаранеллові в Андерсіті, щоб той їх удосконалив і схвалив.",al={"чому фаранелл","роль фаранелла","лідер аптекарського товариства"}},{q="Що таке Суміш Багнорила?",a="Це неочищена отруйна суміш, яку Лайдон розтер із Суцвіть Багнорила — смердючих грибів, зібраних на Хуторі Нетандера, де кишать гноли, у Передгір'ї Гілсбреда. Помітивши її незвичну заразність, Лайдон надіслав її до Андерсіті, де Фаранелл поєднав її з колоїдами розкладу, щоб створити ще смертоноснішу заразу.",al={"суміш багнорила","отрута гнолів","порошок багнорила"}}},fp="15,315,18.470.0,24.410.0,22.380.1,63.272.0,39.195.0,37.152.0,12.233.0,65.251.0,29.299.0"}
P.entries["quest:5151"] = {n="Гіперконденсаторна Штукенція",s="Після смертоносної засідки кентаврів на торговий караван у Тисячі Голок гоблін-майстер Візло Берінґшайнер лишився єдиним, хто вцілів. Відчайдушно бажаючи повернути свій найцінніший винахід, він наймає шукачів пригод, щоб ті пробралися до уламків, відімкнули залізну клітку й зірвали штукенцію з шиї грізного хижака, що сидить у ній.",h="Після смертоносної засідки кентаврів на торговий караван у Тисячі Голок гоблін-майстер Візло Берінґшайнер...",kw={"гіперконденсаторна штукенція","візло берінґшайнер","пантера","кентаври","караван","застава білого рубежу"},ang={["class:Hunter"]="Розлючена пантера в розбитому караванному возі — незвично грізний звір, здатний налякати цілий бойовий загін кентаврів-грабіжників.",["faction:Horde"]="Діючи із Застави Білого Рубежу, розвідники й мандрівники Орди повсякчас б'ються з хижими кланами кентаврів, що загрожують шляхам через центральний Калімдор.",["profession:Engineering"]="Гарячкова гонитва Візло за винаходом, призначення якого він сам до пуття не пам'ятає, — яскравий приклад хаотичної філософії спроб і помилок, властивої класичній гоблінській інженерії."},sec={{t="Засідка серед Голок",b="Каравани, що наважуються йти під високими пісковиковими шпилями Тисячі Голок, проходять крізь смертельну небезпеку. Дном каньйону нишпорять ворожі кентаври, що люто боронять свою територію й грабують кожного мандрівника, якому вистачить зухвалості тут пройти. Коли один такий торговий караван розгромили трохи на північ від Застави Білого Рубежу, кентаври вирізали мандрівників і розграбували вози — лише гоблін Візло Берінґшайнер, накульгуючи, дістався безпечного місця."},{t="Несподіваний вартовий",b="У сум'ятті набігу кентаври забрали майже все цінне, але один розбитий віз обійшли десятою дорогою. У міцній перевізній клітці сиділа люта, розлючена пантера, а на її шиї був закріплений найцінніший винахід Візло — гіперконденсаторна штукенція. Злякавшись гаркітливої люті хижака, кентаври лишили клітку цілою, тож Візло мусить довірити ключ відважним найманцям, здатним убити звіра й повернути його пристрій."},{t="Амбіції майстра",b="Як і належить гоблінові, пристрасть Візло до механічних див часто випереджає практичне розуміння. Хоч він і величає гіперконденсаторну штукенцію найкращим своїм творінням і ризикує чужими життями, щоб вирвати її з пазурів верховного хижака, після повернення він зізнається, що йому ще доведеться з нею повозитися, аби з'ясувати, що вона насправді робить."}},faq={{q="Хто такий Візло Берінґшайнер?",a="Візло Берінґшайнер — гоблінський майстер і торговець, що знайшов прихисток на Заставі Білого Рубежу після того, як кентаври напали на його караван на дні каньйону Тисячі Голок і знищили його.",al={"хто такий візло","візло берінґшайнер лор","хто дає візло"}},{q="Чому штукенція висить на шиї в пантери?",a="Під час перевезення чи в метушні кентаврської засідки пристрій опинився закріпленим на шиї звіра в клітці. Пантера була така страхітлива, що кентаври-нападники не наважилися торкнутися клітки — і хижак мимоволі став охоронцем пристрою.",al={"чому штукенція в пантери","намисто пантери","ошийник штукенції"}},{q="Де лежить розбитий караван?",a="Розбитий караван лежить трохи на північ від Застави Білого Рубежу в Тисячі Голок, серед потрощених возів, оточених ворожими таборами кентаврів.",al={"місце каравана","де клітка пантери","місце клітки"}},{q="Чому кентаври не пограбували клітку?",a="За словами Візло, розлючена пантера така люта, що навіть безжальні кентаври-грабіжники тремтіли поруч із нею й воліли лишити звіра замкненим у клітці, ніж ризикувати її відчинити.",al={"чому кентаври не пограбували","кентаври бояться пантери","чому клітка цілу"}},{q="Що насправді робить Гіперконденсаторна Штукенція?",a="Візло називає її своєю найкращою штукенцією, але, отримавши її назад, зізнається, що ще муситиме вивчати її й колупатися в ній, щоб з'ясувати, що ж вона насправді робить.",al={"що робить штукенція","функція гіперконденсатора","що таке штукенція"}},{q="Хто контролює Заставу Білого Рубежу?",a="Застава Білого Рубежу — тауренське поселення, союзне Орді, серед столових гір каньйону; звідти стежать за кентаврами й дають безпечний прихисток мандрівникам Орди.",al={"фракція білого рубежу","чи білий рубіж орди"}}},fp="20,320,21.433.0,20.454.0,19.336.1,27.185.0,43.260.0,37.143.0,37.198.0,47.187.1,29.165.0"}
P.entries["quest:516"] = {n="Лихо Берена",s="«Лихо Берена» — завдання Орди від Жерця Тіні Аллістера з Гробниці. Агенти Відступників прочули про таємне зборище Погибелі в затишній печері в південних пагорбах Срібнолісся, і завдання полягає в тому, щоб розбити його, перш ніж почнеться наступ.",h="«Лихо Берена» — завдання Орди від Жерця Тіні Аллістера з Гробниці.",kw={"лихо берена","жрець тіні аллістер","погибель","печера","срібнолісся","рейвенклов"},ang={["class:Priest"]="Виконуючи накази Жерця Тіні Аллістера, темні чаклуни допомагають утвердити владу Гробниці, винищуючи нежить-суперників.",["faction:Horde"]="Очищення прихованих гнізд Погибелі на кордонах Срібнолісся допомагає втихомирити північний Лордерон для всієї Орди.",["race:Undead"]="Для Відступників викорінення решток Погибелі на кшталт тих, що засіли в Лиху Берена, — справа чистого виживання, що зміцнює їхню владу проти хватки Короля-Ліча, яка досі не відпускає."},sec={{t="Випереджальний удар",b="До Жерця Тіні Аллістера в Гробниці дійшла звістка, що бездумні слуги Короля-Ліча збираються глибоко в південному Срібноліссі. Якщо їх не спинити, ці сили Погибелі стануть нагальною загрозою для дій Відступників по всьому краю. Замість чекати на удар, Аллістер велить розвідникам перехопити ініціативу й знищити орду, що збирається у відлюдному лігві, перш ніж та встигне рушити."},{t="Прихована печера",b="Саме Лихо Берена — маловідома мережа печер, видовбана в пагорбах на південь від Амбермілла, поселення, вірного Даларану. Через підступну місцину печеру легко проґавити: дістатися до неї можна, лише обійшовши південні схили. У її тінях живуть трударі й охоронці Рейвенклова — рештки чуми, що окопалися тут, і їхнє знищення допомагає Відступникам утримати хитку владу над лісом."}},faq={{q="Що таке Лихо Берена?",a="Лихо Берена — відлюдна печера серед гористих пагорбів на півдні Срібнолісся, на південь від Амбермілла. Вона слугує сховищем для решток Погибелі, відомих як нежить Рейвенклова.",al={"що таке лихо берена","де лихо берена","що за печера"}},{q="Хто дає доручення до Лиха Берена?",a="Жрець Тіні Аллістер із Гробниці в Срібноліссі дає це завдання шукачам пригод Орди, дізнавшись, що ворожа нежить готує наступ із печери.",al={"хто дає лихо берена","дає лихо берена","завдання жерця тіні аллістера"}},{q="Чому Відступники нападають на тамтешню нежить?",a="Нежить у Лиху Берена вірна Королю-Лічу й належить до Погибелі. Відступники вирвалися з-під влади Короля-Ліча й активно борються, щоб вичистити зі своїх земель його прислужників, що ще лишилися.",al={"чому вбивати нежить","чому б'ємося з рейвенкловами","чи відступники не нежить"}},{q="Як знайти вхід до печери?",a="Печера захована в пагорбах на південь від Амбермілла. Через круті гребені до входу треба підходити з південного схилу пагорбів, а не просто з півночі.",al={"шлях до лиха берена","місце входу в печеру","де вхід у печеру"}},{q="Які вороги живуть у Лиху Берена?",a="У печері живуть раби Погибелі — трударі й охоронці Рейвенклова, які, схоже, збираються для нападу на сусідні поселення.",al={"моби лиха берена","що всередині лиха берена"}},{q="Яку роль у цьому дорученні відіграє Даларан?",a="Безпосередньої ролі в самому завданні Даларан не відіграє, хоча неподалік, в Амберміллі, сидять чарівники-люди з Даларану. Аллістер згадує їх лише як орієнтир, щоб розвідники знайшли приховану печеру.",al={"зв'язок даларана","зв'язок амбермілл"}}},fp="13,289,19.433.0,15.428.0,22.200.0,41.184.0,48.209.0,41.183.0,35.168.0,44.196.0"}
P.entries["quest:517"] = {n="Еліксир Агонії",s="Це завдання — четвертий розділ невпинної роботи Аптекаря Лайдона над нищівною отрутою Відступників у Таррен Міллі. Коли смертоносний Еліксир Агонії нарешті зварено, Лайдон посилає поборників Орди до Дун Ґарока викрасти барило дворфійського Темного Пива Шіндіґера.",h="Це завдання — четвертий розділ невпинної роботи Аптекаря Лайдона над нищівною отрутою Відступників у Таррен...",kw={"еліксир агонії","дун ґарок","темне пиво шіндіґера","аптекар лайдон","таррен мілл","завдання"},ang={["class:Rogue"]="Непомітно прослизнути переповненими їдальнями Дун Ґарока — майстер-клас потаємного злодійства просто під носом у горян.",["faction:Horde"]="Підрив присутності Альянсу в Дун Ґароку допомагає Таррен Міллу втримати хиткий плацдарм перед невпинними загрозами з півдня.",["race:Dwarf"]="Перетворення традиційного дворфійського пива на посудину для хімічної різанини — глибока образа ремеслу Айронфорджа.",["race:Undead"]="Кожна партія, вдосконалена Лайдоном, наближає Відступників до того, щоб обернути смерть на зброю проти живих ворогів, що зазіхають на Лордерон."},sec={{t="Гірке вариво",b="У вогких закутках Таррен Мілла Аптекар Лайдон невтомно працює на Королівське Аптекарське Товариство й Леді Сильвану. Він зібрав смертоносні складники по всьому Гілсбреду, і його нова суміш готова. Лайдон не хоче марнувати такий потужний штам на дрібних істот на кшталт жаб чи бродячих псів: йому потрібне справжнє, відчутне випробування на живих супротивниках."},{t="Проникнення до Дун Ґарока",b="Для свого досліду Лайдон потребує непомітного засобу доставки. На південь від Гілсбреда дворфи Айронфорджа укріпили твердиню Дун Ґарок. Лайдон посилає агентів Орди проникнути до підземних казарм і їдалень, прослизнути повз дворфійські рушниці й сокири й поцупити цінне барило Темного Пива Шіндіґера."},{t="Рецепт лиха",b="Лайдон має намір підмішати свою смертоносну отруту просто в улюблене пиво дворфів. Щойно еліксир опиниться у викраденому барилі, його можна буде випустити на нічого не підозрюючу ціль під виглядом святкового частунку — і улюблене дворфійське темне пиво стане знаряддям жахливої агонії."}},faq={{q="Хто такий Аптекар Лайдон?",a="Аптекар Лайдон — алхімік Відступників у Таррен Міллі. Представляючи Королівське Аптекарське Товариство, він ставить досліди, щоб створювати смертоносні чуми й еліксири для Королеви Баньші, Леді Сильвани.",al={"лайдон","хто дає завдання","лайдон лор"}},{q="Навіщо Лайдонові барило Стауту Шиндіґґер?",a="Лайдон хоче випробувати готовий Еліксир Агонії на живих цілях. Змішавши отруту з барилом популярного дворфійського елю, він отримує прихований і дієвий спосіб отруїти своїх жертв.",al={"навіщо дворфійське пиво","чому стаут шиндіґґер","навіщо барило"}},{q="Де розташований Дун Ґарок?",a="Дун Ґарок — добре укріплений дворфійський оплот на південному сході Передгір'я Гілсбреда, де горяни й стрільці Айронфорджа стережуть північні інтереси свого королівства.",al={"де дун ґарок","місце дун ґарока","де знайти барило"}},{q="Хто такий Умпі?",a="Умпі — помічниця Аптекаря Лайдона в Таррен Міллі. Лайдон жартома зауважує, що коли в лабораторії відкривають банки з формальдегідом, Умпі помітно нервує.",al={"умпі","хто такий умпі","помічник лайдона"}},{q="Яка кінцева мета Еліксиру Агонії?",a="Еліксир Агонії — дослідна отрута, яку Королівське Аптекарське Товариство створило, щоб винищувати живих; вона служить кампанії Відступників, що прагнуть очистити Лордерон від людських і дворфійських осередків.",al={"що робить еліксир агонії","мета чуми","мета отрути відступників"}},{q="Що далі, коли барило здобуто?",a="Отримавши барило, Лайдон підмішує отруйний еліксир у Стаут Шиндіґґер і доручає вам віднести отруєний ель нічого не підозрюваному піддослідному.",al={"наступне завдання","що після дун ґарока","еліксир частина 5"}}},fp="15,277,13.380.0,22.329.0,21.278.1,24.209.0,46.194.0,27.175.0,12.159.0,49.199.0,41.158.1"}
P.entries["quest:52"] = {n="Захист рубежу",s="«Захист рубежу» — доручення Альянсу, яке Вартовий Томас дає біля східного мосту через річку в Лісі Елвінн. Що ближче до кордону, то рідша військова присутність Стормвінда, і дикі хижаки знахабніли — нападають на подорожніх і робітників Лісозаготівельного Табору Східної Долини. Вартовий Томас шукає здібних шукачів пригод, щоб винищити вовків і ведмедів, які загрожують східному рубежу.",h="«Захист рубежу» — доручення Альянсу, яке Вартовий Томас дає біля східного мосту через річку в Лісі Елвінн.",kw={"захист рубежу","вовки","ведмеді","вартовий томас","східна долина","лісозаготівля","ліс елвінн"},ang={["class:Hunter"]="Вовки й ведмеді, що никають східним Лісом Елвінн, — рання перевірка вміння вистежувати й влучно стріляти по лютій місцевій дичині.",["faction:Alliance"]="Безпечні східні дороги забезпечують постачання деревини зі Східної Долини, що підтримує відбудову й оборону по всіх землях Альянсу."},sec={{t="Оборона, що рідшає",b="Ґолдшир і Долина Нортширу мають помітний гарнізон Стормвінда, а от далекий східний край Лісу Елвінн захищений значно гірше. Вартовий Томас несе варту біля мосту через річку — один із небагатьох чатових між обжитими землями й небезпечними нетрями. Ресурси королівства розтягнуті до краю, тож самотнім вартовим лишається покладатися на добровольців, що проходять повз, аби тримати відкритими життєво важливі шляхи постачання."},{t="Хижа загроза",b="Лісозаготівельний Табір Східної Долини вкрай важливий для постачання деревини до Стормвінда, та рубання дерев на узліссі зводить лісорубів віч-на-віч із місцевою звіриною. Вовки-причаєнці, сірі лісові вовки й молоді лісові ведмеді стають дедалі агресивнішими й блукають біля доріг і лісоскладів. Прорідити їх означає на якийсь час полегшити життя місцевим робітникам, хоч Вартовий Томас підозрює, що звірів до поселень жене якась невидима тривога глибше в лісі."}},faq={{q="Хто дає завдання «Захист рубежу»?",a="Завдання дає Вартовий Томас. Він стоїть на східному мосту при головній дорозі через Ліс Елвінн і стереже межу між глибиною лісу й краєм Східної Долини.",al={"хто дає захист рубежу","хто починає захист рубежу","завдання вартового томаса"}},{q="Чому вовки й ведмеді нападають на прикордоння?",a="Агресивні хижаки раз у раз виходять на дороги й робочі ділянки біля Лісозаготівельного Табору Східної Долини. Вовки й ведмеді від природи ревно стережуть свої угіддя, але Вартовий Томас зауважує, що їх, схоже, розбурхує щось глибше в навколишній глушині й жене до людських осель.",al={"чому ведмеді агресивні","чому вовки нападають на іствейл","напади тварин елвінн"}},{q="Де розташований Лісозаготівельний Табір Східної Долини?",a="Лісозаготівельний Табір Східної Долини лежить на сході Лісу Елвінн, трохи на схід від мосту Вартового Томаса. Він постачає важливу деревину Стормвіндові й прикордонним поселенням.",al={"місце іствейла","де табір лісорубів елвінн","табір іствейл"}},{q="Чому Вартовий Томас стереже міст сам?",a="Постійне військо й міська варта Стормвінда страшенно розпорошені по королівству. На сторожових постах уздовж річок і віддалених перехресть часто стоїть лише один-два вартові, тож із великими загрозами від звірів їм доводиться покладатися на мандрівних шукачів пригод.",al={"чому томас сам","пост вартового томаса","стражники стормвінда іствейл"}},{q="Яких звірів треба прорідити в цьому дорученні?",a="Вам треба вбити вісьмох вовків — нишпорок чи сірих лісових вовків — і п'ятьох молодих лісових ведмедів, що блукають лісами на сході Лісу Елвінн.",al={"цілі захисту рубежу","вовки та ведмеді","які моби для захисту рубежу"}},{q="Що буде, коли звірів проріджено?",a="Доповідь Вартовому Томасу здобуває його вдячність і безпечніший шлях для лісових обозів. Утім, він і далі побоюється, що темна сила, яка розбурхала звірів, може накоїти в лісі ще лиха.",al={"продовження захисту рубежу","здати захист рубежу"}}},fp="20,389,18.434.0,20.498.0,41.186.0,48.288.0,35.155.0,46.294.0,45.152.0,41.219.0"}
P.entries["quest:524"] = {n="Еліксир Агонії",s="«Еліксир Агонії» — кульмінація зловісних дослідів Аптекаря Лайдона з варивами в Таррен Міллі. За дорученням Королівського Аптекарського Товариства Лайдон прагне випробувати смертельну отруту, приховану в краденому дворфійському пиві, на людських бранцях, яких тримають у поселенні.",h="«Еліксир Агонії» — кульмінація зловісних дослідів Аптекаря Лайдона з варивами в Таррен Міллі.",kw={"еліксир агонії","аптекар лайдон","таррен мілл","дарталія","полонені фермери","дун ґарок","завдання"},ang={["faction:Horde"]="Цей похмурий дослід показує темніший, неприкрашений бік діяльності Відступників і випробовує моральну витримку інших рас Орди, що допомагають Таррен Міллу.",["race:Human"]="Різанина беззахисних лордеронських фермерів показує холодну, розважливу безжальність, з якою Відступники ставляться до своїх колишніх живих родичів.",["race:Undead"]="Для Відступників удосконалення отрут Королівського Аптекарського Товариства — понад усе важливе для виживання: будь-якою ціною вберегти Передгір'я Гілсбреда від відродження людей."},sec={{t="Смертоносний урожай",b="По всьому Передгір'ю Гілсбреда Аптекар Лайдон збирає мерзенні складники та дворфійське пиво, поцуплене з гірської фортеці Дун Ґарок. Його мета одна й безжальна: за дорученням Королівського Аптекарського Товариства зварити нове заразне вариво, відоме як Еліксир Агонії. Змішана, ця темна суміш чекає в барилі на вигляд безневинного гірського темного пива, щоб показати свою силу."},{t="Нещасні гості",b="Вартові Смерті в Таррен Міллі нещодавно зігнали місцевих людських фермерів, спершу підозрюючи, що серед них ховається невловимий військовий стратег зі Стормвінда. Коли надійшла звістка, що стратег загинув у Чумних Землях, Верховний Екзекутор Дарталія вирішила, що вцілілі селяни для військової розвідки непотрібні. Замість відпустити їх, вона подарувала їх Лайдонові як піддослідних для його хімічних випробувань."},{t="Випробування варива",b="Отруєне барило заносять нагору до кімнати з бранцями й ставлять на запилений килим перед спраглими полоненими. Змучені спрагою й нічого не знаючи про жорстокість Лайдона, фермери кидаються до барила, щоб напитися. Отрута діє з жахливою швидкістю: за якусь мить після ковтка дворфійського пива нещасні бранці падають і вмирають на місці, доводячи нищівну смертоносність еліксиру."}},faq={{q="Чому фермерів-людей узагалі схопили?",a="Вартові Смерті затримали їх, підозрюючи, що серед них сховався військовий стратег Королівства Стормвінд. Коли стратега знайшли мертвим у Чумних Землях, полонені втратили для Верховного Екзекутора Дарталії будь-яку розвідувальну цінність.",al={"чому схопили фермерів","чому фермери під замком","в'язні таррен мілл"}},{q="Хто такий Аптекар Лайдон?",a="Аптекар Лайдон — член Королівського Аптекарського Товариства Відступників у Таррен Міллі. Він розробляє й випробовує смертоносні пошесті та отрути, що мають винищити живих, часто використовуючи схоплених місцевих як живий матеріал.",al={"лор аптекаря лайдона","хто такий лайдон","лайдон таррен мілл"}},{q="Звідки ель у барилі?",a="Ель викрали просто в дворфів Дун Ґарока — міцної гірської твердині на півдні Передгір'я Гілсбреда. Лайдон підмішав у вкрадене барило свої отруйні реагенти, щоб смертельна отрута здавалася звичайним дворфійським пивом.",al={"звідки ель у барилі","ель дун ґарока","походження барила"}},{q="Що стається, коли доставити отруєне барило?",a="Lydon asks you to set the tainted keg on the rug in the prisoners' room for his experiment.",al={"що буде з фермерами","фермери п'ють барило","результат зараженого варива"}},{q="Хто дозволив використати в'язнів як піддослідних?",a="Верховний Екзекутор Дарталія, командувачка сил Відступників у Таррен Міллі, передала вцілілих в'язнів Аптекареві Лайдону, коли вони стали їй непотрібні для війни.",al={"хто дозволив випробовувати на в'язнях","дарталія і в'язні","роль дарталії"}},{q="Чого Королівське Аптекарське Товариство намагається тут досягти?",a="Королівське Аптекарське Товариство невтомно створює смертоносну пошесть, здатну знищити і Погибель, і живих. Польові досліди на кшталт Еліксиру Агонії випробовують нові способи доставки отрути й визначають, наскільки вона токсична для людського тіла.",al={"цілі аптекарів хілсбрада","навіщо еліксир агонії","випробування скверни відступників"}}},fp="15,256,16.414.0,18.438.1,16.389.1,55.267.0,24.226.0,43.236.0,46.91.1,52.168.0,60.255.0"}
P.entries["quest:5261"] = {n="Іґан Пелтскіннер",s="Це коротке вступне завдання посилає щойно прибулих у Долину Нортширу новобранців поговорити з Іґаном Пелтскіннером, місцевим хутровиком, що працює біля Абатства Нортшира. Хижаків на околицях долини дедалі більше, тож Іґану потрібні здібні шукачі пригод, щоб полювати на лісових вовків і збирати шкури.",h="Це коротке вступне завдання посилає щойно прибулих у Долину Нортширу новобранців поговорити з Іґаном...",kw={"іґан пелтскіннер","хутровик","вовки","шкури","нортшир","помічник віллем"},ang={["faction:Alliance"]="Кожне дрібне завдання в Нортширі допомагає убезпечити рідні землі Стормвінда, поки основна армія королівства розтягнута деінде.",["race:Human"]="Для молодих людей, що виходять із Абатства Нортшира, допомога місцевим ремісникам на кшталт Іґана — найперший урок захисту батьківщини."},sec={{t="Розмова з хутровиком",b="Долина Нортширу може здаватися ідилічною, та її тихі сади й поля межують із дикими лісами, що кишать лісовими вовками. Помічник Віллем часто направляє новобранців за мури абатства до Іґана Пелтскіннера, який працює поруч, на землях абатства. Іґан залюбки дає новачкам роботу: проріджувати агресивні зграї й здобувати цінні шкури для його ремесла."},{t="Клопіт на околицях",b="Вовки, яких довкола Нортширу дедалі більшає, — не просто прикрість: вони загрожують робітникам, послушникам і обозам, що входять у долину й виходять із неї. Направляючи молодих героїв до Іґана, маршали Стормвінда вбивають двох зайців: ближні стежки стають безпечними, а нечисленні вартові гарнізону, які й так мають справу зі зростанням напруги по всьому Лісі Елвінн, лишаються вільними."}},faq={{q="Хто посилає мене до Іґана Пелтскіннера?",a="Помічник Віллем, що стоїть одразу біля входу до Абатства Нортшира, скеровує до Іґана перспективних новобранців, розповівши їм про загрози в долині.",al={"хто дає завдання","хто починає завдання іґана пелтскіннера"}},{q="Де знайти Іґана Пелтскіннера?",a="Іґан Пелтскіннер стоїть біля зовнішніх мурів Абатства Нортшира, ліворуч від головної будівлі, серед своїх сушарок і спорядження.",al={"де іґан","місце іґана пелтскіннера","знайти іґана"}},{q="У чому Іґанові Пелтскіннеру потрібна допомога?",a="Іґан шукає шукача пригод, готового полювати на агресивних лісових вовків, що никають довколишніми лісами, і приносити їхні шкури, — так околиці Нортшира стануть безпечнішими.",al={"чого хоче іґан","навіщо полювати на вовків","мета іґана"}},{q="Чи можна пропустити це завдання й одразу поговорити з Іґаном?",a="Так. Іґан дає своє мисливське доручення кожному, хто до нього підійде. Це завдання-скерування просто дає офіційне знайомство від Помічника Віллема.",al={"чи можна пропустити завдання іґана","вовки через кордон напряму"}},{q="Чому в Долині Нортширу стільки вовків?",a="Долина Нортширу межує з густими дикими лісами, де вільно блукають лісові вовки. Місцевої варти бракує, і вона зайнята іншими загрозами по всьому королівству, тож хижаки розплодилися без жодного стримування.",al={"чому вовків у нортширі багато","проблема вовків елвінн"}},{q="Яке завдання йде після розмови з Іґаном Пелтскіннером?",a="Розмова з Іґаном одразу веде до його прохання полювати на лісових вовків на межі земель абатства й збирати їхні цупкі шкури.",al={"наступне завдання після іґана","що пропонує іґан далі"}}},fp="17,299,23.367.0,24.376.0,46.176.0,35.153.0,43.185.0,51.164.0,50.219.0,50.146.0"}
P.entries["quest:527"] = {n="Битва за Гілсбред",s="«Битва за Гілсбред» — перший удар у поході Відступників, що прагнуть знищити людське поселення Гілсбред. Це доручення Верховний Екзекутор Дарталія дає за наказом Варіматраса: воно спрямоване проти фермерів і господарства на півночі Полів Гілсбреду, щоб перерізати містечку постачання харчів.",h="«Битва за Гілсбред» — перший удар у поході Відступників, що прагнуть знищити людське поселення Гілсбред.",kw={"битва за гілсбред","дарталія","варіматрас","поля гілсбреду","фермер рей","таррен мілл","завдання"},ang={["faction:Alliance"]="Різанина північних хуторян показує жахливу дійсність, з якою стикаються останні людські осередки в Лордероні.",["faction:Horde"]="Хоча Тралл проповідує честь, північний похід із Таррен Мілла відкриває безкомпромісну жорстокість війни Сильвани проти Альянсу.",["race:Undead"]="Для Відступників повернути Лордерон — означає стерти кожен уцілілий осередок живих, які топчуть їхню батьківщину, мов украдену землю."},sec={{t="Заморити опір голодом",b="Таррен Мілл — південне вістря імперії Відступників, що стоїть проти закоріненого людського населення, яке тримається за Передгір'я Гілсбреда. Верховний Екзекутор Дарталія діє за суворими вказівками Варіматраса з Андерсіті. Її стратегія — цілковите виснаження: перш ніж рушити просто на сильно укріплене містечко Гілсбред, вона наказує методично руйнувати його сільське господарство. Удар по північних полях позбавляє людське ополчення життєво важливих припасів і сіє хаос по їхніх хуторах."},{t="Стримувальні дії",b="Ширший похід проти людської присутності в Гілсбреді має похмуру тактичну мету. Поки армії Відступників сковують і виснажують місцевих захисників, Королівське Аптекарське Товариство невтомно працює над новою чумою, здатною винищити і живих, і Погибель. Верховний Екзекутор Дарталія вважає ці перші сутички — і загибель місцевих землевласників, як-от Фермера Рея та Фермера Ґетца, — необхідними кроками, щоб придушити людську заразу, доки та остаточна зброя не буде готова."}},faq={{q="Чому Відступники нападають на простих фермерів?",a="Фермери й наймити з Полів Гілсбреду — господарська основа містечка Гілсбред. Винищуючи робочі руки й убиваючи визначних землевласників на кшталт Фермера Рея й Фермера Ґетца, Відступники відрізають людський гарнізон від харчів і послаблюють оборону перед прямим штурмом.",al={"чому вбивати фермерів","цілі ферм хілсбрада","чому нападати на ферми"}},{q="Хто наказує цей напад?",a="Доручення дає Верховний Екзекутор Дарталія, воєначальниця Відступників у Таррен Міллі. Вона служить під безпосереднім командуванням жахолорда Варіматраса й Леді Сильвани Віндраннер.",al={"хто дає завдання","накази дарталії","хто така дарталія"}},{q="Яка роль Королівського Аптекарського Товариства в цій кампанії?",a="Дарталія зауважує, що звичайна війна проти людей має приборкати живе населення й виграти час, поки аптекарі Відступників розробляють нову чуму, що має знищити ворогів цілком.",al={"чому нова чума","аптекарі хілсбрада","план чуми відступників"}},{q="Де знайти Фермера Рея й Фермера Ґетца?",a="Обидва землевласники господарюють на північній частині Полів Гілсбреду. Фермер Рей зазвичай біля великого фермерського будинку чи на городі одразу на схід від нього, а Фермер Ґетц частіше буває в стодолі, у другому будинку чи на довколишніх ділянках.",al={"знайти фермера рея","знайти фермера ґетца","місце рея і ґетца"}},{q="Що буде після цього набігу?",a="Коли ви з перемогою повертаєтеся до Дарталії, наступ переходить на південні поля й саме містечко Гілсбред, а також відкриваються побічні справи — як-от збирання похмурих трофеїв у завданні «Сувеніри смерті».",al={"продовження битви за хілсбред","що далі","розвиток ланцюжка"}},{q="Чому Дарталія погрожує своїм воякам?",a="Верховний Екзекутор Дарталія вимагає цілковитої дисципліни й безжальності. Будь-яке вагання чи легковажність у війні з Альянсом вона вважає зрадою, за яку карають стратою на місці.",al={"діалог дарталії","дарталія погрожує стратою"}}},fp="19,302,23.523.0,17.505.0,46.318.0,23.197.0,61.208.0,45.258.0,40.201.0,41.198.0"}
P.entries["quest:528"] = {n="Битва за Гілсбред",s="«Битва за Гілсбред» — військове доручення Відступників, яке дає Верховний Екзекутор Дарталія з Таррен Мілла. Після перших ударів по північних людських фермах агентів Орди посилають на південь вирізати селян Гілсбреда, що тікають і шукають прихистку в садах.",h="«Битва за Гілсбред» — військове доручення Відступників, яке дає Верховний Екзекутор Дарталія з Таррен Мілла.",kw={"битва за гілсбред","дарталія","поля гілсбреду","селяни","таррен мілл","завдання"},ang={["faction:Alliance"]="Різанина беззбройних біженців у південних садах підкреслює безжальну тотальну війну, яку Відступники ведуть проти останніх живих підданих Лордерону.",["faction:Horde"]="Таррен Мілл — життєво важливий оплот Орди в передгір'ї. Зламавши Гілсбред, Орда вбереже свої шляхи зв'язку й постачання від вторгнень Альянсу.",["race:Undead"]="Для Відступників ця чистка практична й безкомпромісна: знищення живих робітників позбавляє Альянс харчів і зміцнює владу Темної Леді над південним Лордероном."},sec={{t="Сіяти жах на полях",b="Похід проти людської присутності в Передгір'ї Гілсбреда розгортається з холодною розважливістю. Після того як сили Орди вдарили по північних фермах, поселенням прокотилася паніка. Замість узятися за зброю, багато робітників тікають на південь, у сади й пасовиська Полів Гілсбреду, сподіваючись сховатися від нежиті, що наступає. Верховний Екзекутор Дарталія дивиться на їхній жах не з милосердям, а як на стратегічну нагоду остаточно зламати решту робочих рук і бойовий дух Гілсбреда."},{t="Наступ Темної Леді",b="За прямим наказом із Таррен Мілла поборники Орди полюють на цих утікачів у полях. Позбавлених захисту селян методично знищують, щоб перекрити Гілсбредові постачання харчів і зламати рішучість мирних мешканців. Для Дарталії та Відступників кожна вбита людина дедалі тугіше затягує смертельну петлю довкола вцілілого містечка, щоб Лордерон міцно лишався в руках Відступників."}},faq={{q="Чому Відступники цілять у простих селян?",a="Удар по селянах руйнує господарський хребет, що годує поселення Гілсбред. Убиваючи робітників, що ховаються в південних садах, Верховний Екзекутор Дарталія домагається, щоб містечко ще глибше поринуло в паніку й голод, і остаточне завоювання стало набагато легшим.",al={"чому вбивати селян","чому цілити фермерів","план дарталії щодо селян"}},{q="Хто наказує цей наступ?",a="Верховний Екзекутор Дарталія, командувачка Відступників у Таррен Міллі, керує всією воєнною кампанією проти місцевих людських поселень іменем Леді Сильвани Віндраннер.",al={"хто дає битву за хілсбред 2","хто дає завдання","накази дарталії"}},{q="Звідки втекли ці селяни?",a="Вони втекли з північних ферм Гілсбреда після попередніх ударів Орди. Налякані й беззахисні, вони сховалися серед дерев і пасовищ на півдні Полів Гілсбреду.",al={"звідки селяни","північні ферми хілсбрада"}},{q="Де шукати селян-утікачів?",a="Селяни розпорошені по південних садах і пасовищах Полів Гілсбреду, трохи на південь від головної дороги через передгір'я.",al={"місце селян хілсбрада","де селяни хілсбрада"}},{q="Що далі, коли селян перебито?",a="Коли південні поля спорожніють, Верховний Екзекутор Дарталія розширює кампанію: тепер ціль — Коваль Веррінґтан і кузня, що озброює захисників Гілсбреда, і бій підбирається дедалі ближче до центру містечка.",al={"що далі після селян","наступний крок битви за хілсбред"}},{q="Чому Орда воює тут так безжально?",a="Людське містечко Гілсбред — одна з останніх твердинь Альянсу в Лордероні. Відступники вважають цей край своєю законною землею й прагнуть вигнати чи знищити будь-які осередки Альянсу, що загрожують їхньому південному кордону.",al={"чому орда безжальна","війна відступників і хілсбрада"}}},fp="19,271,27.478.0,23.422.0,47.266.0,24.186.0,35.185.0,40.148.0,38.220.1,45.259.0"}
P.entries["quest:529"] = {n="Битва за Гілсбред",s="Ця операція — важливий етап походу Відступників на підкорення Передгір'я Гілсбреда. Верховний Екзекутор Дарталія наказує знищити місцеву кузню на Полях Гілсбреду, щоб перерізати постачання зброї, якою озброюються вперті люди.",h="Ця операція — важливий етап походу Відступників на підкорення Передгір'я Гілсбреда.",kw={"битва за гілсбред","коваль веррінґтан","кузня","поля гілсбреду","дарталія","партія заліза","завдання"},ang={["faction:Alliance"]="Убивство Веррінґтана й крадіжка заліза позбавляють віддалені ферми Саутшора єдиного засобу самозахисту.",["profession:Blacksmithing"]="Кузня Веррінґтана була живим серцем місцевого опору й довела, що ковадло може бути для армії загарбників не менш небезпечним, ніж полк піхоти.",["race:Undead"]="Для Відступників знищення людської кузні — прагматичний крок до того, щоб убезпечити південні кордони Лордерону й накопичити метал для власної виснаженої війни."},sec={{t="Розбити ковадло",b="Наступ Відступників у Передгір'ї Гілсбреда натрапив на запекліший опір, ніж очікувала Верховний Екзекутор Дарталія. Сільські люди не захотіли просто розбігтися чи скоритися скрадачам смерті й солдатам, посланим із Таррен Мілла. Розвідка з'ясувала, що місцеві селяни б'ються не лише вилами й косами: їх споряджають до війни просто тут, у полях."},{t="Перерізати постачання",b="На південно-західному краю Полів Гілсбреду Коваль Веррінґтан і його учні невтомно працювали біля горна, перетворюючи сиру руду на клинки й обладунки для ополчення. Пославши агента вбити Веррінґтана, вирізати його учнів і захопити їхню партію заліза, Дарталія прагнула підірвати оборону поселення, а метал спрямувати на майбутній штурм Саутшора."}},faq={{q="Чому Верховний Екзекутор Дарталія цілить саме в коваля?",a="Містяни й фермери несподівано вчинили воєнний опір наступові Відступників. Дарталія з'ясувала, що Коваль Веррінґтан і його учні кують зброю для ополчення, перетворюючи звичайних селян на озброєну загрозу.",al={"чому вбивати верринґтана","завдання коваля","завдання верринґтана"}},{q="Де розташована кузня?",a="Кузня стоїть на південно-західному краю Полів Гілсбреду, а довкола працюють учні, стоять вартові й ходять місцеві патрулі.",al={"місце верринґтана","де коваль","кузня хілсбрада"}},{q="Навіщо партія заліза?",a="Дарталія конфіскує залізо для воєнної машини Відступників. Вона хоче скористатися цією захопленою сировиною, щоб викувати зброю й спорядження для задуманого штурму портового містечка Альянсу Саутшор.",al={"що буде із залізом","лор партії заліза"}},{q="Яке місце це посідає в ширшій кампанії «Битва за Гілсбред»?",a="Це третій етап планомірних зусиль Дарталії викорінити людську присутність у передгір'ї: від винищення сільських робітників і фермерів вона переходить до того, щоб позбавити людей проводу, постачання й виробництва.",al={"ланцюжок битви за хілсбред","кампанія дарталії"}},{q="Чи мешканці Полів Гілсбреду — частина війська Альянсу?",a="Хоча за культурою вони пов'язані із Саутшором і Альянсом, мешканці полів — здебільшого місцеві фермери, робітники й містяни, що згуртувалися в імпровізоване ополчення, щоб захистити свої домівки від Відступників.",al={"чи фермери хілсбреду альянс","ополчення хілсбреду"}},{q="Хто наказує завдати цього удару?",a="Верховний Екзекутор Дарталія — воєначальниця, що керує діями Відступників із твердині Таррен Мілл.",al={"хто дає завдання","хто така дарталія"}}},fp="19,249,18.390.0,24.422.0,68.262.0,28.129.0,38.214.0,64.233.0,65.211.0,23.123.0"}
P.entries["quest:532"] = {n="Битва за Гілсбред",s="Цей важливий етап походу Відступників проти володінь довкола Саутшора спрямований проти міської влади Гілсбреда. Під проводом Верховного Екзекутора Дарталії з Таррен Мілла сили Орди вражають Магістрата Бернсайда, його раду та їхні урядові записи, щоб остаточно зруйнувати людське врядування в передгір'ї.",h="Цей важливий етап походу Відступників проти володінь довкола Саутшора спрямований проти міської влади...",kw={"битва за гілсбред","магістрат бернсайд","ратуша","міський реєстр","дарталія","проголошення гілсбреда","завдання"},ang={["faction:Alliance"]="Убивство Магістрата Бернсайда й спалення міського статуту позначають катастрофічне падіння останньої законної місцевої влади Гілсбреда.",["faction:Horde"]="Удар по ратуші підриває здатність Альянсу керувати місцевим ополченням і надійно вбезпечує південне прикордоння Таррен Мілла від людських контрнаступів.",["race:Undead"]="Для Відступників знищення людського врядування в Гілсбреді — і стратегічне розширення, і безжальна відплата живим, що оспорюють кордони Лордерону."},sec={{t="Обезголовити міську раду",b="Навіть зазнавши тяжких утрат на полях і в патрулях, людські захисники Гілсбреда тримаються за рештки своєї цивільної влади. Верховний Екзекутор Дарталія розуміє, що звичайні селяни й ополченці згуртовуються довкола своїх міських очільників. Щоб містечко остаточно впало, агентів Відступників посилають просто до Ратуші — стратити Магістрата Бернсайда й п'ятьох його радників, розірвавши ланцюг командування."},{t="Стерти міський літопис",b="Окрім фізичних убивств, Дарталія прагне цілковитого психологічного й адміністративного руйнування Гілсбреда. Агенти мусять спалити Проголошення Гілсбреда — шанований політичний документ, що символізує статут і гордість поселення. Водночас вони захоплюють міський реєстр, позбавляючи вцілілих прихильників Альянсу офіційних записів і переліку мешканців, а розвідці Андерсіті даючи докладні відомості про місцеве населення."}},faq={{q="Хто наказує завдати цього удару?",a="Верховний Екзекутор Дарталія, командувачка Відступників у Таррен Міллі, готує штурм у межах своєї ширшої кампанії, що має стерти поселення Альянсу з передгір'я.",al={"хто дає завдання","хто дає завдання битви за хілсбред","дарталія хілсбред"}},{q="Хто такий Магістрат Бернсайд?",a="Магістрат Бернсайд — магістрат і політичний провідник людського містечка Гілсбред. Він засідає в ратуші разом зі своїми радниками й тайною магією захищає рештки влади поселення.",al={"магістрат бернсайд","хто такий бернсайд","лідер хілсбреду"}},{q="Що таке Прокламація Гілсбреда?",a="Прокламація Гілсбреда — шанована політична хартія, що зберігається на почесному місці в Ратуші. Вона втілює законне врядування й дух мешканців містечка, тож її знищення — нищівний удар по громадському духу.",al={"що таке прокламація","лор прокламації хілсбреда","знищити прокламацію"}},{q="Навіщо Дарталії міський реєстр?",a="Міський реєстр містить повний перепис і громадські документи населення Гілсбреда. Викравши його, Відступники позбавляють уцілілих людей адміністративної пам'яті й водночас здобувають цінні відомості про те, хто ще лишився в краї.",al={"навіщо дарталії реєстр","міський реєстр хілсбреда","що робить реєстр"}},{q="Де відбувається цей бій?",a="Цілі перебувають у великій будівлі Ратуші та довкола неї в людському поселенні Гілсбред, що лежить на півдні передгір'я між Таррен Міллом і Саутшором.",al={"де магістрат бернсайд","ратуша хілсбреда","де радники"}},{q="Яку роль відіграють радники?",a="Радники Гілсбреда — правлячий орган, що допомагає Магістратові Бернсайду. Це вправні заклиначі, що захищають і внутрішні зали Ратуші, і подвір'я довкола неї.",al={"радники хілсбреда","хто такі радники"}}},fp="19,335,29.444.0,24.472.0,23.179.0,27.221.0,35.223.0,42.237.0,33.182.0,33.185.0"}
P.entries["quest:5321"] = {n="Сплячий пробудився",s="Керлоніан Евершейд, Друїд Пазура, що нещодавно прокинувся, ледве долає сон дорогою до Посту Маестри в Ашенвалі. Отримавши його Ріг Пробудження, мандрівники мусять провести млявого друїда лісовим прикордонням, будити його, коли він засинає, і боронити від диких фурболгів і зловісних культистів.",h="Керлоніан Евершейд, Друїд Пазура, що нещодавно прокинувся, ледве долає сон дорогою до Посту Маестри в...",kw={"сплячий пробудився","керлоніан евершейд","ріг пробудження","ліладріс мунрівер","пост маестри","друїд пазура"},ang={["class:Druid"]="Друїди впізнають тяжку ціну глибокого єднання зі Смарагдовим Сном: тривала сплячка часто лишає пробуджений розум повільним, і йому нелегко повністю отямитися.",["faction:Alliance"]="Безпечний прохід мандрівників між Темним Узбережжям і північним Ашенвалем допомагає підтримувати важливий зв'язок між Обердайном і віддаленими сторожовими постами.",["race:NightElf"]="Для нічних ельфів Керлоніан — знайомий образ недавніх потрясінь їхньої культури: він уособлює тисячі друїдів, що відгукнулися на поклик рогу під час Третьої війни й тепер звикають до денного світла."},sec={{t="Сонний розум",b="Тисячоліттями Друїди Пазура спали в курганах, спілкуючись із дикими духами крізь Смарагдовий Сон. Третя війна вимагала їхнього пробудження, та струсити з себе століття сплячки вдається не кожному. Керлоніан Евершейд вирушив із Темного Узбережжя на південь, до Ашенвалю, на зустріч із Ліладріс Мунрівер, але невдовзі після початку мандрівки його зморила втома. Безпорадний перед раптовими нападами дрімоти серед нетрів, він покладається на латунний Ріг Пробудження й на союзників, що трапляються дорогою, аби не спинятися."},{t="Небезпеки в дорозі",b="Шлях, що з'єднує Темне Узбережжя з Ашенвалем, аж ніяк не спокійний. Поки Керлоніан бреде на південь, його безпорадність накликає агресію навколишніх нетрів. У Сутінковій Долині дорогою нишпорять зіпсовані фурболги Чорнолісся, а далі на південь, в Ашенвалі, у засідках чатують члени тіньового культу Темного Берега. Супровід сонного друїда вимагає пильності, бо Керлоніан просто вкладається спати там, де стоїть, якщо його не розбудити рогом."},{t="Прибуття на заставу",b="Переживши засідки й діставшись Посту Маестри, Керлоніан одразу ж вислизає шукати ще одну зручну латку трави, щоб доспати перерваний сон. Його зв'язкова, Ліладріс Мунрівер, анітрохи не дивується його звичній дрімоті й зустрічає його з лагідним роздратуванням. Боротьба Керлоніана віддзеркалює тривалу розгубленість багатьох друїдів, для яких світ наяву — різкий удар після позачасового спокою Сну."}},faq={{q="Чому Керлоніан раз у раз засинає?",a="Керлоніан Евершейд — Друїд Пазура, що лише нещодавно прокинувся від багатовікової сплячки в Смарагдовому Сні. Повернення до світу неспання лишає багатьох друїдів збентеженими й украй млявими, тож без постійного збудження ззовні він майже не здатен не заснути.",al={"чому керлоніан засинає","чому він сонний","друїд засинає"}},{q="Як розбудити Керлоніана, коли він задрімає?",a="Треба скористатися Рогом Пробудження, який на початку подорожі беруть зі скрині поруч із Керлоніаном. Щоразу, як він засинає дорогою, звук рогу повертає його до тями, і він іде далі.",al={"як розбудити керлоніана","ріг керлоніана","використання рога пробудження"}},{q="Хто чекає на Керлоніана на Пості Маестри?",a="Він іде на зустріч із Ліладріс Мунрівер — ельфійкою з Посту Маестри на півночі Ашенвалю. Вона знає про його хронічну сонливість і просто рада, що він дійшов цілим.",al={"хто така ліладріс","з ким зустрічається керлоніан"}},{q="Які вороги нападають дорогою?",a="Шлях пролягає повз Сутінкову Долину, де на загін влаштовують засідку ворожі фурболги Чорнолісся. Далі на південь, в Ашенвалі, з тіні нападають копачі, адепти й сектанти таємного Темного Пасма.",al={"засідки під час супроводу","що нападає на керлоніана","засідка сутінкової долини"}},{q="Звідки назва «Сплячий пробудився»?",a="Це знамените вітання, яке промовляли Друїди Пазура, коли їх закликали на службу під час Третьої війни, — воно підкреслює природу Керлоніана як пробудженого перевертня.",al={"цитата сплячий пробудився","репліка друїда"}},{q="Що буде з рогом, якщо барися?",a="Ріг Пробудження діє обмежений час, а тоді зникає з ваших речей. Якщо супровід затягнеться чи доведеться починати знову після невдачі, новий ріг треба взяти зі скрині там, де відпочивав Керлоніан.",al={"ріг протермінований","ріг пробудження зник"}}},fp="24,348,17.541.0,20.484.0,22.454.1,39.294.0,42.241.0,47.194.0,34.212.0,58.168.0,46.232.0"}
P.entries["quest:536"] = {n="Уздовж узбережжя",s="«Уздовж узбережжя» — завдання Альянсу, яке дає Лейтенант Фаррен Орінелль у Саутшорі. Глибоко незадоволений переведенням зі Стормвінда на прикордоння, лейтенант варти воліє пити ель, а не патрулювати, тож наймає шукачів пригод, щоб ті вичистили мурлоків-Подертих Плавців, які підступають уздовж Західного Узмор'я.",h="«Уздовж узбережжя» — завдання Альянсу, яке дає Лейтенант Фаррен Орінелль у Саутшорі.",kw={"уздовж узбережжя","фаррен орінелль","саутшор","західне узмор'я","мурлоки","подерті плавці","завдання"},ang={["faction:Alliance"]="Саутшор — головний прибережний оплот Альянсу на півночі, тож навіть дрібна недбалість у гарнізоні загрожує виживанню містечка.",["race:Human"]="Лінощі Орінелля болісно виразно показують контраст між захищеним серцем Стормвінда й суворою боротьбою за виживання північних поселень."},sec={{t="Небажане призначення",b="Лейтенанта Фаррена Орінелля перевели з вилощених кам'яних вулиць міської варти Стормвінда до далекого, просоленого порту Саутшор. Містечко видається йому похмурим, а рибний сморід гавані — нестерпним, тож Орінелль проводить дні за чаркою в місцевому заїзді, а не патрулюючи передову. Коли Маршал Маркус Редпат наказує йому захищати Саутшор від довколишніх небезпек, Орінелль вирішує перекласти свої обов'язки на заїжджих найманців."},{t="Загроза Подертих Плавців",b="Саме завдання стосується Західного Узмор'я — узбережжя, що тягнеться на захід від Саутшора. Хоча Орінелль глузує із загрози «переростків-рибин», плем'я мурлоків Подертих Плавців становить справжню небезпеку для прибережних мандрівок і місцевого судноплавства. Збираючись у тісних таборах уздовж прибою, їхні мисливці припливу й містичні оракули залюбки нападають на кожного, хто відійде надто далеко від міських мурів, тож очищення берега — кривава справа."}},faq={{q="Чому Фаррен Орінелль не розбереться з мурлоками сам?",a="Фаррен вважає Саутшор небажаним засланням після колишнього життя в міській варті Стормвінда. Ображений призначенням і гидуючи прибережним містечком, він воліє сидіти в таверні за елем, ніж лізти в прибій битися з мурлоками, тож платить шукачам пригод, щоб ті робили його роботу.",al={"чому фаррен не впорається","фаррен п'є","чому наймають шукачів пригод"}},{q="Хто такий «старий Редпат», про якого каже Орінелль?",a="Ідеться про Маршала Маркуса Редпата, маршала Саутшора. Редпат відповідає за порядок і оборону в поселенні, що опинилося в облозі, — зокрема й видає військові накази, від яких Лейтенант Орінелль відверто намагається ухилитися.",al={"хто такий редпат","магістрат редпат","командир орінелль"}},{q="Де живуть мурлоки Подертих Плавців?",a="Мурлоки Подертих Плавців живуть на Західному Узмор'ї — прибережних пляжах просто на захід від Саутшора в Передгір'ї Гілсбреда.",al={"де подерті плавці","місце мурлоків хілсбрада","місце західного узбережжя"}},{q="Яких мурлоків треба знищити?",a="Наказ вимагає вбити мисливців припливу Подертих Плавців — передових бійців племені — й оракулів Подертих Плавців, що орудують стихійною й водяною магією, щоб підсилювати родичів.",al={"цілі мурлоків","які мурлоки","приливний мисливець оракул"}},{q="Що буде, коли пляж для Орінелля очищено?",a="Завершивши облаву, Орінелль розуміє, що йому потрібні відчутні докази, щоб задовольнити прискіпливого Маршала Редпата, — і це починає низку доручень зі збирання речових доказів убитих мурлоків.",al={"наступне завдання після уздовж узбережжя","ланцюжок уздовж узбережжя","доказ фаррена далі"}},{q="Мурлоки — справжня загроза чи просто відмовка?",a="Хоча Фаррен глузує з цих істот як із нешкідливих переростків-риб, Подерті Плавці численні, агресивні й живуть незручно близько до причалів Саутшора, загрожуючи торговим шляхам і рибалкам.",al={"чи мурлоки небезпечні в хілсбраді","небезпека мурлоків саутшора"}}},fp="14,293,19.465.0,19.442.0,58.293.0,42.249.0,39.139.0,44.179.0,51.196.1,56.195.0"}
P.entries["quest:539"] = {n="Битва за Гілсбред",s="Цей наказ Верховного Екзекутора Дарталії посилає агентів Орди глибоко в Шахту Лазурової Жили — важливу залізну копальню на південь від Полів Гілсбреду. Усунувши Наглядача Бондса та його робітників, Відступники прагнуть перерізати постачання заліза до збройних складів Альянсу й захопити тунелі для себе.",h="Цей наказ Верховного Екзекутора Дарталії посилає агентів Орди глибоко в Шахту Лазурової Жили — важливу...",kw={"битва за гілсбред","шахта лазурової жили","наглядач бондс","залізна руда","дарталія","саутшор","завдання"},ang={["faction:Horde"]="Порушення головного постачання металу Альянсу в Гілсбреді послаблює тиск на передову Таррен Мілла: людським військам буде важко замінити спорядження.",["profession:Mining"]="Шахта Лазурової Жили — одна з найбагатших залізних копалень передгір'я, тож вона природно стає гарячою точкою для всіх, хто змагається за цінні рудні жили.",["race:Undead"]="Захоплення Шахти Лазурової Жили дає Вартовим Смерті життєво важливе залізо й обертає людську промисловість на озброєння армій Сильвани по всьому Лордерону."},sec={{t="Перерізати постачання заліза",b="Захопивши Міський Реєстр Гілсбреда під час попередніх нападів, Верховний Екзекутор Дарталія визначила Шахту Лазурової Жили як наріжний камінь людської військової витривалості в краї. Копальня працює трохи на південь від спірних полів і безупинно добуває багаті жили залізної руди для зброярів і збройних складів Альянсу. Якщо лишити її неушкодженою, сили Саутшора переозброяться й зміцнять свої гарнізони, і попередні перемоги Таррен Мілла стануть марними."},{t="Недвозначне послання",b="Щоб цілком зупинити видобуток, Дарталія б'є і по керівництву, і по робітниках. Силам Орди наказано усунути Наглядача Бондса — людину, що керує розкопками, — а також значну частину його робітників. Удар у темних штольнях недвозначно повідомляє Саутшорові: ні їхні шляхи постачання, ні відокремлені робітничі табори не сховаються від Відступників."},{t="Здобич для Темної Леді",b="Окрім того, що цей напад позбавляє Альянс воєнних матеріалів, він має для Андерсіті й практичну другорядну мету. Захопивши копальню, сили Сильвани Віндраннер заберуть багаті рудні жили для власних ливарень. Таррен Міллу потрібне безперервне постачання металу, щоб виготовляти зброю й лати для війни по всьому Лордерону, — і колишнє людське надбання стає рушієм завоювань Відступників."}},faq={{q="Чому Шахта Лазурової Жили така важлива для Відступників?",a="Шахта Лазурової Жили постачає високоякісну залізну руду просто до збройових Альянсу. Захопивши її, Відступники позбавляють людські гарнізони на кшталт Саутшора матеріалів для кузень і водночас дають Андерсіті багате джерело металу для спорядження своїх сил.",al={"чому нападати на лазурову жилу","призначення лазурової жили","чому мішень шахта"}},{q="Хто такий Наглядач Бондс?",a="Наглядач Бондс — людина, що керує розробкою Лазурової Жили. Він порядкує гірниками й, опинившись у скруті глибоко в нижніх залах, може покликати на допомогу стійких дворфійських захисників.",al={"наглядач бондс","хто такий бондс","хто керує шахтою"}},{q="Де розташована Шахта Лазурової Жили?",a="Шахта Лазурової Жили врізана в пагорби на південь від Полів Гілсбреду, на захід від Саутшора, на прибережних кручах.",al={"місце лазурової жили","де лазурова жила","як знайти шахту"}},{q="Як Дарталія дізналася про роботу шахти?",a="Дарталія з'ясувала господарське значення шахти й те, що вона діє, переглянувши Міський Реєстр Гілсбреда, який агенти Орди здобули під час попередніх ударів по людських поселеннях.",al={"як дарталія дізналася","реєстр міста шахта","розвідка хілсбреда"}},{q="Що буде, коли Наглядача Бондса вбито?",a="Коли шахту знекровлено, а її багатства призначено Відступникам, Верховний Екзекутор Дарталія посилює наступ і спрямовує Орду на руйнування решти господарства Гілсбреда, підбираючись дедалі ближче до самого Саутшора.",al={"що далі битва за хілсбред","після вбивства бондса","наслідки завдання"}},{q="Чи захищає шахту Альянс?",a="Так. Крім гірників-людей, що працюють у штольнях, Альянс тримає біля входу озброєну варту, а Наглядач Бондс має напоготові глибоко в тунелях міцних дворфійських бійців.",al={"вартові шахти","альянс у лазуровій жилі","дворфи в шахті"}}},fp="19,299,24.454.0,18.389.0,24.402.1,51.235.0,21.187.0,36.121.0,55.191.0,42.247.1,34.187.0"}
P.entries["quest:541"] = {n="Битва за Гілсбред",s="Цей важливий етап походу Відступників у Гілсбреді спрямований проти дворфійської твердині Дун Ґарок. Верховний Екзекутор Дарталія посилає поборників Орди розгромити дворфійський гарнізон, що допомагає місцевим людям, і стратити їхнього командира, Капітана Айронгілла.",h="Цей важливий етап походу Відступників у Гілсбреді спрямований проти дворфійської твердині Дун Ґарок.",kw={"битва за гілсбред","дун ґарок","капітан айронгілл","мур торадіна","дарталія","айронфордж","завдання"},ang={["faction:Horde"]="Удар по Дун Ґароку відрізає важливі військові підкріплення, які Айронфордж надсилає на допомогу обложеним людям Саутшора.",["race:Dwarf"]="Дун Ґарок уособлює непохитну вірність Айронфорджа людським союзникам: він витримує облогу Відступників, щоб утримати північне прикордоння.",["race:Undead"]="Для Відступників знищення дворфійського гарнізону вбезпечує південний схід Лордерону й гарантує, що жоден південний авангард Альянсу не пройде легко крізь Мур Торадіна."},sec={{t="Випробувати Альянс",b="Притиснувши людських фермерів і міське ополчення по всьому передгір'ю, Верховний Екзекутор Дарталія спрямовує лють Таррен Мілла на військовий загін Айронфорджа. Дворфійські війська взялися за зброю на підтримку Саутшора, зміцнюючи людську присутність у Лордероні. Для Дарталії ця солідарність — перешкода, яку треба розтрощити, щоб довести Альянсові: допомога людським решткам принесе тільки спустошення."},{t="Падіння Дун Ґарока",b="Притулений до давніх валів Муру Торадіна на південному сході Гілсбреда, Дун Ґарок — сильно укріплений дворфійський оплот. Щоб узяти заставу штурмом, треба прорвати лави дисциплінованих горян, добірних стрільців і загартованих у боях жерців. Штурм завершується загибеллю Капітана Айронгілла: передове командування Айронфорджа в краї зламане, а вцілілі людські осередки лишаються в ізоляції."}},faq={{q="Чому в Гілсбреді б'ються дворфи?",a="Дворфи Айронфорджа міцно пов'язані з Альянсом і відрядили збройні сили на північ, до Дун Ґарока, щоб допомогти вцілілим людям Саутшора й Гілсбреда протистояти наступу Відступників.",al={"чому дворфи в хілсбраді","дворфи дун ґарок","чому дворфи допомагають людям"}},{q="Де розташований Дун Ґарок?",a="Дун Ґарок — у південно-східному куточку Передгір'я Гілсбреда, збудований просто в основі Муру Торадіна.",al={"місце дун ґарока","де дун ґарок","знайти дун ґарок"}},{q="Хто такий Капітан Айронгілл?",a="Капітан Айронгілл — дворфійський командир гарнізону Дун Ґарока. Завдяки йому горяни в краї діють злагоджено й боєздатно.",al={"капітан айронгілл","хто такий айронгілл","лідер дун ґарока"}},{q="Хто віддає цей наказ?",a="Доручення розгромити дворфійський гарнізон дає Верховний Екзекутор Дарталія, воєначальниця Відступників у Таррен Міллі.",al={"хто дає завдання","дарталія","дарталія хілсбред"}},{q="Що буде, якщо сили Орди тут зазнають невдачі?",a="Верховний Екзекутор Дарталія дає зрозуміти, що невдачі вона не потерпить: кожного, хто не зламає Дун Ґарок, понизять до копача могил у Галявинах Тірісфалю.",al={"що якщо орда зазнає невдачі","загроза дарталії","наслідки"}},{q="Чому Дун Ґарок так важко штурмувати?",a="На відміну від сільського ополчення Гілсбреда, Дун Ґарок обороняють вишколені дворфійські вояки, загони стрільців і жерці Світла, що б'ються щільним строєм у своєму укріпленому підземному й піднесеному бункері.",al={"еліта дун ґарока","чому дун ґарок важкий","оборона дун ґарока"}}},fp="19,270,20.421.0,21.433.0,38.202.0,27.128.0,24.158.0,21.132.0,39.172.0,41.205.0"}
P.entries["quest:543"] = {n="Тіара Перенольде",s="«Тіара Перенольде» — доручення Графа Ремінгтона Ріджвелла, аристократа, що мешкає в Стормвінді. Він наймає шукачів пригод вирушити на північ, до підступних Руїн Альтераку, й повернути загублену королівську реліквію. Колись ця корона належала занепалій династії Альтераку, а нині, кажуть, вона в руках огра-мага.",h="«Тіара Перенольде» — доручення Графа Ремінгтона Ріджвелла, аристократа, що мешкає в Стормвінді.",kw={"тіара перенольде","діадема переноль","ремінгтон ріджвелл","ґрел'борґ скнара","руїни альтераку","огри"},ang={["faction:Alliance"]="Мандрівка на північ, у беззаконні Гори Альтерак, дає агентам Альянсу змогу розчистити край від небезпечних огрів клану Трощихребтів і водночас повернути безцінні історичні артефакти для знаті Стормвінда.",["race:Dwarf"]="Створена майстрами-ювелірами Айронфорджа, тіара уособлює славетну майстерність дворфійських ремісників, чия тонка робота пережила навіть загибель людського королівства.",["race:Human"]="Для людей Альянсу ця тіара — незручне нагадування про зраду Альтераку в Другій війні, коли людські монархи стали на бік Орди проти власних родичів."},sec={{t="Реліквія зруйнованого королівства",b="Діадема Переноль — вишукана реліквія занепалого людського королівства Альтерак. Цю пишну прикрасу виготовили дворфійські майстри-ювеліри в Айронфорджі й оздобили найкращими смарагдами для правлячого роду Перенольде. Та під час Другої війни король Ейден Перенольде зрадив Великий Альянс і перейшов на бік Орківської Орди, що й призвело до занепаду, завоювання й остаточної руїни його королівства. У хаосі, що супроводжував падіння Міста Альтерак, чимало найбільших скарбів королівської династії зникло серед засніжених руїн у Горах Альтерак."},{t="Скнара в руїнах",b="Діадема опинилася не в скарбниці Альянсу й не в королівській гробниці, а в захланних лапах Ґрел'борґа Скнари. Цей огр-маг з огрів клану Трощихребтів, що оселилися в руїнах Альтераку, цілими днями нишпорить серед зруйнованого каміння в пошуках блискучих дрібничок і покинутих багатств. Граф Ремінгтон Ріджвелл, затятий збирач історичних дивовиж зі Стормвінда, дізнається, що діадема вціліла, і наймає відчайдушних найманців пробратися глибоко в землі огрів, порішити скупого громила й повернути безцінну коштовність до його особистої галереї."}},faq={{q="Хто такі Перенольди?",a="Перенольди — королівський рід, що правив північним людським королівством Альтерак. Під час Другої війни король Ейден Перенольд учинив державну зраду, змовившись з Ордою орків-загарбників, щоб уберегти своє королівство. Альянс Лордерона викрив його зраду, і це призвело до воєнної окупації Альтерака, скасування трону й остаточного занепаду королівства в беззаконня й руїну.",al={"дім перенольдів","хто були перенольди","перенольд лор"}},{q="Хто виготовив Діадему Переноль?",a="Діадему викували майстри-ювеліри в дворфійському місті Айронфордж. Зроблена з добірних металів і прикрашена блискучими смарагдами, вона була символом знатності й багатства правлячого дому Альтерака, доки королівство не впало в неласку.",al={"походження діадеми","хто виготовив діадему перенольде"}},{q="У кого тепер діадема?",a="Діадема потрапила до лап Ґрел'борґа Скнари — огра-мага й падальника, що блукає засніженими Руїнами Альтераку на північних пагорбах і жадає стародавніх скарбів, які лишилися від зруйнованого людського міста.",al={"ґрелборґ","у кого діадема перенольде","місце діадеми"}},{q="Навіщо Графові Ремінгтону Ріджвеллу діадема?",a="Граф Ремінгтон Ріджвелл — заможний вельможа й збирач старожитностей зі Стормвінда. Він шукає знамениті артефакти й історичні дивовижі по всьому Азероту, щоб поповнити свою престижну приватну колекцію, і наймає вправних найманців, щоб ті здобували втрачені скарби з небезпечних місць.",al={"мотив ремінґтона ріджвелла","навіщо діадема"}},{q="Де розташовані Руїни Альтераку?",a="Руїни Альтераку лежать у холодних Горах Альтерак на півночі Східних Королівств, на північ від Передгір'я Гілсбреда й краю Дурнгольд. Покинуте місто заполонили ворожі огри-Трощихребти й розбійники Синдикату.",al={"місце руїн альтераку","де альтерак"}},{q="Що буде з діадемою, коли її повернуто?",a="Отримавши заболочену й потьмянілу реліквію, Граф Ріджвелл віддає її фаховим реставраторам, щоб ті очистили й відполірували її, а тоді одразу виставляє як окрасу своєї особистої колекції.",al={"здати діадему","доля діадеми"}}},fp="19,319,27.573.0,22.591.0,29.425.0,29.241.0,24.204.0,50.289.0,39.265.0,47.201.1"}
P.entries["quest:546"] = {n="Сувеніри смерті",s="«Сувеніри смерті» — завдання, яке Вартовий Смерті Самса в Таррен Міллі дає поборникам Орди, що воюють проти людських поселень Передгір'я Гілсбреда. Заздрячи тим, кого посилають на передову, Самса просить принести тридцять людських черепів, здобутих у бою, до своєї моторошної колекції.",h="«Сувеніри смерті» — завдання, яке Вартовий Смерті Самса в Таррен Міллі дає поборникам Орди, що воюють проти...",kw={"сувеніри смерті","вартовий смерті самса","людські черепи","таррен мілл","гілсбред","завдання"},ang={["faction:Alliance"]="Методичне збирання відтятих людських голів показує, яку жорстоку, смертельну загрозу Відступники становлять для вцілілих городян Гілсбреда.",["faction:Horde"]="Похід проти Гілсбреда — прямий наступ Орди, щоб розгромити останні твердині Альянсу в Лордероні й убезпечити північні шляхи постачання Таррен Мілла.",["race:Undead"]="Вартовий Смерті Самса відображає буденну жорстокість і глибоко вкорінену ворожість багатьох Відступників до живих людей, які вважають їх потворами."},sec={{t="Заздрість вартового",b="Поки Верховний Екзекутор Дарталія кидає всю військову міць Відступників на людські поселення Гілсбреда, Вартовий Смерті Самса застряг на варті в Таррен Міллі. Плекаючи гірку заздрість до тих, кого посилають грабувати, палити й нищити, Самса вважає відкриту різанину живих завидним привілеєм, якого позбавлені вартові, прикуті до містечка."},{t="Моторошний трофей",b="Не маючи змоги покинути пост, Самса тішить свою ненависть, збираючи черепи людей Гілсбреда, вбитих у цьому поході. Його прохання про тридцять черепів не служить ні таємному обряду, ні тактичному задуму: це суто особиста забаганка — трофеї війни, в якій він прагне битися власноруч."}},faq={{q="Хто дає це завдання і де його знайти?",a="Доручення дає Вартовий Смерті Самса. Він стоїть на варті в Таррен Міллі — головній твердині Відступників на півночі Передгір'я Гілсбреда.",al={"хто дає завдання","хто дає сувеніри смерті","місце самси"}},{q="Чого хоче Вартовий Смерті Самса?",a="Самса просить тридцять людських черепів із Гілсбреда, знятих із бійців і містян, яких ви вб'єте в боях на Полях Гілсбреду й у містечку Гілсбред.",al={"мета завдання","які предмети потрібні","потрібні черепи"}},{q="Навіщо Самсі людські черепи?",a="Самса — затятий збирач моторошних трофеїв. Застрягши на гарнізонній службі в Таррен Міллі, поки інші ведуть тотальну війну, він збирає черепи, щоб хоч так долучитися до різанини живих.",al={"навіщо самсі черепи","мотивація самси","для чого черепи"}},{q="Коли стає доступним це завдання?",a="Самса звертається до вас лише тоді, коли ви поступите на службу до Верховного Екзекутора Дарталії й виконаєте перший штурм у ланцюжку «Битва за Гілсбред».",al={"вимоги завдання","як відкрити","передумови сувенірів"}},{q="Чи йдуть черепи на алхімію чи магію Відступників?",a="Ні. На відміну від доручень Королівського Аптекарського Товариства, якому потрібні біологічні реагенти для Нової Чуми, прохання Самси суто особисте. Відтяті черепи здаються йому гарними, і він дорожить ними як сувенірами війни.",al={"черепи для аптекарів","магічні черепи","використання в некромантії"}},{q="З яких людей можна взяти черепи?",a="Черепи можуть дати будь-які фермери, селяни, ополченці й захисники з Полів Гілсбреду чи містечка Гілсбред, поки ви воюєте на боці Таррен Мілла.",al={"де фармити черепи","які моби дропають черепи","люди хілсбреда"}}},fp="18,285,14.373.0,17.303.0,49.147.0,32.170.0,33.185.0,38.151.0,50.222.0,32.173.0"}
P.entries["quest:5481"] = {n="Завдання Ґордо",s="Завдання Ґордо — доручення в Галявинах Тірісфалю від Ґордо, мандрівної гидоти, яка намагається збирати трави вздовж дороги до Брілла. Непридатний до тонкої польової роботи, він наймає мандрівників рвати Похмуру Траву й нести її своєму наглядачеві, Молодшому Аптекарю Голланду.",h="Завдання Ґордо — доручення в Галявинах Тірісфалю від Ґордо, мандрівної гидоти, яка намагається збирати трави...",kw={"завдання ґордо","ґордо","гидота","похмура трава","голланд","аптекар"},ang={["profession:Herbalism"]="Для навчених травників це завдання — дрібниця: їхнє чуття легко виявляє зарості Похмурої Трави серед спустошеної трави.",["race:Undead"]="Для новопіднятих Відступників, що виходять із Похоронного Подзвону, це завдання — перша зустріч із незграбною дійсністю праці гидот і гострим норовом Королівського Аптекарського Товариства."},sec={{t="Незграбний робітник",b="Ґордо — гидота, що тупає туди-сюди сільськими дорогами між Похоронним Подзвоном і Бріллом. Гидоти неперевершені в грубому бою і важкому перенесенні, та їхні величезні зшиті руки роблять тонку роботу майже неможливою. Посланий на луки збирати інгредієнти для Королівського Аптекарського Товариства, Ґордо швидко з'ясовує, що його тупі пальці більше чавлять стебел, ніж рвуть, тож він залякуванням чи підкупом змушує перехожих робити нудну роботу замість нього."},{t="Аптекарське роздратування",b="Молодший Аптекар Голланд чекає на доставку на цвинтарі за ратушею Брілла, та доручення йде шкереберть. Ґордо геть неправильно зрозумів наказ і скерував мандрівників збирати нешкідливу Похмуру Траву замість летючого Зілля Приречення, потрібного для алхімічних досліджень. Голланд украй роздратований недолугістю зшитого велетня: він має помилкову доставку за доказ нікчемності гидоти — і одразу доручає гравцеві виправити помилку."}},faq={{q="Хто такий Ґордо?",a="Ґордо — гидота на службі Королівського Аптекарського Товариства. Він ходить луками на захід від Брілла, намагаючись виконати роботу, яку доручив йому господар, Молодший Аптекар Голланд.",al={"хто такий ґордо","ґордо тірісфаль","нпц ґордо","що таке ґордо"}},{q="Чому Ґордо потрібна допомога зі збиранням трав?",a="Руки в Ґордо — величезні незграбні придатки зі зшитої мертвої плоті. Йому просто бракує спритності, щоб зірвати ніжні рослини й не зіпсувати їх, тож він просить мандрівних шукачів пригод із Відступників зібрати їх замість нього.",al={"чому ґордо потрібна допомога","чому ґордо не збере трави","руки ґордо"}},{q="Хто такий господар Голланд?",a="Молодший Аптекар Голланд — алхімік Королівського Аптекарського Товариства, що працює на цвинтарі Брілла. Він наглядає за Ґордо й досліджує місцеві рослини та уражений ґрунт, щоб допомогти воєнним зусиллям Відступників.",al={"господар голланд","хто такий голланд","аптекар голланд"}},{q="Чому Голланд засмучений, коли йому приносять Похмуру Траву?",a="Gordo says Holland wants Gloom Weed and asks you to gather it. Deliver the plants to Junior Apothecary Holland in Brill.",al={"чому голланд сердитий","помилка похмурої трави","не та трава"}},{q="Де росте Похмура Трава?",a="Похмура Трава стелиться низько над землею на диких полях між Похоронним Подзвоном і Бріллом, особливо на відкритих луках на схід від Хутора Соллідена.",al={"де росте похмура трава","місця похмурої трави","знайти похмуру траву"}},{q="Що буде після «Завдання Ґордо»?",a="Holland offers the follow-up assignment Doom Weed in Brill's graveyard.",al={"що далі","продовження завдання ґордо","наступне завдання після ґордо"}}},fp="12,264,16.465.0,23.484.1,13.201.0,41.229.0,22.218.0,54.120.1,30.150.0,43.71.1"}
P.entries["quest:5482"] = {n="Зілля приречення",s="Зілля приречення — завдання від Молодшого Аптекаря Голланда у Бріллі: зібрати отруйне зілля, що проростає біля північних братських могил Тірісфалю. Голланд наймає перехожих шукачів пригод, розчарувавшись у незграбних спробах гидоти Ґордо збирати трави.",h="Зілля приречення — завдання від Молодшого Аптекаря Голланда у Бріллі: зібрати отруйне зілля, що проростає...",kw={"зілля приречення","голланд","братська могила","гноли","трави","брілл"},ang={["faction:Horde"]="Моторошні алхімічні експерименти у Бріллі показують, наскільки інакше діють Відступники порівняно з їхніми шаманськими й кочовими союзниками в Калімдорі.",["profession:Herbalism"]="Звичайні трави ростуть по всіх галявинах, та спотворені різновиди на кшталт Зілля Приречення показують протиприродні зміни рослинності, спричинені чумою Погибелі.",["race:Undead"]="Служба молодшим членам Королівського Аптекарського Товариства — звичний обряд посвяти для щойно пробуджених Відступників, які прагнуть довести свою корисність володінням Сильвани."},sec={{t="Аптекарські амбіції",b="Молодший Аптекар Голланд проводить дослідження від імені Королівського Аптекарського Товариства в поселенні Брілл. Щоб просунути свої експерименти, йому потрібна чимала кількість Зілля Приречення — мерзенної рослини, що вкорінилася у спустошеній землі Галявин Тірісфалю. Переконавшись, що Ґордо нездатен розрізнити потрібні реагенти, Голланд звертається до вправніших рук, щоб урятувати свій урожай."},{t="Жнива на братській могилі",b="Зілля Приречення буяє в місцях, глибоко отруєних смертю і чумою, і густо розростається довкола братської могили просто на північ від цвинтаря Брілла. Збирати його небезпечно через агресивних гнилошкірих гнолів, які нишпорять оскверненими могильними курганами, порпаються в останках і боронять зарослі рови."}},faq={{q="Навіщо Молодшому Аптекареві Голланду зілля приречення?",a="Молодшому Аптекареві Голланду потрібне зілля приречення для алхімічної роботи на Королівське Аптекарське Товариство. Він запевняє, що ця служба безпосередньо допомагає Леді Сильвані Віндраннер, хоча його жадібне завзяття свідчить, що він не менше дбає про власну кар'єру в Товаристві.",al={"навіщо голланду зілля приречення","зілля приречення голланда","призначення зілля приречення"}},{q="Чому Ґордо не збирає трави сам?",a="Ґордо — гидота, якій доручено збирати трави довкола Брілла, але йому бракує розуму, щоб розрізняти рослини. Голланд нарікає, що незграбна істота принесла геть не ті трави, тож аптекареві довелося наймати тямущих шукачів пригод.",al={"чому ґордо не збирає сам","провал завдання ґордо","хто такий ґордо"}},{q="Де росте зілля приречення?",a="Зілля приречення росте серед ураженої рослинності довкола братської могили, просто на північ від цвинтаря під Бріллом. Воно поширюється ґрунтом, сильно отруєним похоронними ровами й чумою, що досі не вивітрилася.",al={"місце зілля приречення","де зілля приречення","бур'яни братської могили"}},{q="Які небезпеки чатують біля заростей зілля приречення?",a="Околиці братської могили заполонили гнилошкірі гноли. Ці дикі, хворобливі падальники люто нападають на кожного, хто підходить до поховань збирати трави.",al={"вороги зілля приречення","вороги братської могили","гноли біля брилла"}},{q="Чому Королівське Аптекарське Товариство цікавлять рослини Тірісфалю?",a="Королівське Аптекарське Товариство постійно вивчає рослини, отрути й змінені пошестю гриби по всіх Галявинах Тірісфалю. Реагенти на кшталт зілля приречення збирають, щоб удосконалювати отрути, шукати алхімічні ліки й розробляти нову зброю для Відступників проти їхніх ворогів.",al={"інтерес аптекарів","аптекарське товариство тірісфаль","збір трав відступників"}},{q="Хто така «Леді», про яку каже Голланд?",a="«Леді» — це Леді Сильвана Віндраннер, Королева Баньші й володарка Відступників. Аптекарі Андерсіті й Брілла часто згадують її ім'я, адже їхні алхімічні зусилля офіційно служать її наказам.",al={"хто така леді","голланд про леді сильвану","леді андерсіті"}}},fp="9,259,20.366.0,22.333.0,50.278.0,43.266.0,26.209.0,45.201.0,66.262.0,39.211.0"}
P.entries["quest:549"] = {n="РОЗШУКУЮТЬСЯ: члени Синдикату",s="Цей указ, вивішений на дошці нагород у Таррен Міллі з повноважень Леді Сильвани, засуджує всіх членів Синдикату на смерть. Відступники прагнуть вичистити розбійників, що збираються в руїнах Твердині Дурнгольд, перш ніж ті загрожуватимуть діям Орди в передгір'ї.",h="Цей указ, вивішений на дошці нагород у Таррен Міллі з повноважень Леді Сильвани, засуджує всіх членів...",kw={"розшукуються члени синдикату","синдикат","твердиня дурнгольд","нагорода","таррен мілл","завдання"},ang={["class:Rogue"]="Синдикат виставляє вправних кишенькових злодіїв і майстрів засідок по всьому Дурнгольду, тож це доручення — пряме зіткнення суперників у мистецтві потайності.",["faction:Horde"]="Твердиня Дурнгольд береже похмурі спогади як фортеця-в'язниця, де колись тримали орків, тож вичистити розбійників, що засіли в її руїнах, — для Орди символічна справа.",["race:Undead"]="Для Відступників позбутися живих решток альтерацької знаті — практична потреба, щоб безроздільно панувати над пагорбами Лордерону."},sec={{t="Постійний смертний вирок",b="Раптова поява Синдикату на південний схід від Таррен Мілла не лишилася непоміченою для Відступників. Замість пропонувати перемовини чи вважати їх просто вигнаною знаттю, Леді Сильвана Віндраннер і її командири бачать у Синдикаті справжню чуму. Оголошення нагороди вимагає негайної смерті й уточнює, що всіх приведених полонених страчать без суду."},{t="Руїни Дурнгольда",b="Колись сумнозвісна фортеця-табір інтернування, Твердиня Дурнгольд нині лежить розтрощена й беззаконна. Розбійники й Вартові Синдикату прокралися на її зруйновані вали й вежі й зробили історичну твердиню своїм осередком. Для Верховного Екзекутора Дарталії очищення руїн від цих озброєних бандитів конче потрібне, щоб убезпечити шлях і захистити південно-східні підступи до Таррен Мілла."}},faq={{q="Хто оголосив винагороду за членів Синдикату?",a="Винагороду оголошено безпосередньою владою Леді Сильвани Віндраннер, а оголошення вивішено на дошці в Таррен Міллі. Докази страти приймає Верховний Екзекутор Дарталія, воєначальниця поселення.",al={"хто призначив винагороду за синдикат","хто хоче смерті синдикату","плакат винагороди"}},{q="Де шукати цих членів Синдикату?",a="Вони збираються серед розтрощеного каміння Твердині Дурнгольд, на південний схід від Таррен Мілла за річкою, а також довкола зруйнованої сторожової вежі трохи на південь від головної фортеці.",al={"де розбійники синдикату","місце синдикату дурнгольд","де шукати вартових"}},{q="Чому Відступники хочуть їхньої смерті, а не полону?",a="Відступники вважають Синдикат підступною наволоччю й озброєною загрозою, що зазіхає на їхні землі. Указ прямо велить негайно страчувати кожного схопленого, тож брати їх у полон зовсім немає сенсу.",al={"чому вбивати синдикат","чому без полонених","дарталія синдикат"}},{q="Що Синдикат робить у Твердині Дурнгольд?",a="Синдикат, що складається переважно з осоромленої альтерацької знаті й найманців, використовує покинуті фортеці, руїни й вежі по всьому Лордерону як бази, звідки нападає на поселення, грабує мандрівників і відбудовує свою зруйновану могутність.",al={"чому синдикат у дурнгольді","мета синдикату хілсбред","окупанти дурнгольду"}},{q="Що буде, коли цих агентів Синдикату прорідити?",a="Коли ряди розбійників і вартових проріджено, Верховний Екзекутор Дарталія оголошує першочергову винагороду за їхнього місцевого ватажка — Барона Вардуса.",al={"яке завдання далі","після розшукуються члени синдикату","наступна винагорода"}}},fp="27,273,26.365.0,22.379.0,46.225.0,42.187.0,55.236.0,46.236.0,54.168.1"}
P.entries["quest:55"] = {n="Морбент Фел",s="Це завдання — остаточна розплата з Морбентом Фелом, некромантом, що засів на висотах над Цвинтарем Воронячого Пагорба. Озброївши героїв зачарованою реліквією Погибель Морбента, скорботний Свен Йорґен посилає їх зламати чародійський захист і покласти край кривавому пануванню некроманта над західним Сутінколіссям.",h="Це завдання — остаточна розплата з Морбентом Фелом, некромантом, що засів на висотах над Цвинтарем Воронячого...",kw={"морбент фел","погибель морбента","свен йорґен","некромант","цвинтар воронячого пагорба","каражан"},ang={["class:Paladin"]="Покарати мерзенного некроманта й очистити Воронячий Пагорб від його протиприродних чарів — істинне покликання лицарів Святого Світла.",["class:Priest"]="Осквернення Цвинтаря Воронячого Пагорба волає про духовне очищення, тож розвіяти чародійський захист Фела — святий обов'язок.",["faction:Alliance"]="Убивши Морбента Фела, ви позбавляєте людей Сутінколісся однієї з найгрізніших загроз, убезпечуєте дорогу й ушановуєте страждання західних поселень на кшталт Воронячого Пагорба."},sec={{t="Гніздо над мерцями",b="Морбент Фел облаштував лігво в покинутому будинку на скелястому хребті трохи на схід від табору Свена, звідки видно весь Цвинтар Воронячого Пагорба. З цієї похмурої висоти некромант насилав хвилі нежиті тероризувати довколишній ліс і оскверняти могили Сутінколісся. Захищений грізною темною магією й оточений вірними слугами-мерцями, він лишався недосяжним для звичайної сталі."},{t="Помста Свена",b="Свен Йорґен збожеволів від горя, коли темні сили вирізали його родину й змусили його переховуватися. Свен знає, що справжні винуватці різанини на його фермі — загадкові Темні Вершники Каражана, але саме мерзенне чаклунство Морбента Фела не дає кошмарові краю скінчитися. Покарати некроманта — єдина відчутна крихта справедливості, що лишилася Свенові на цій проклятій землі."},{t="Погибель Морбента",b="Напасти на Морбента Фела в лоб без надприродної допомоги — самогубство: його захисні чари відбивають звичайні удари. Щоб обійти цей захист, Свен довіряє шукачам пригод Погибель Морбента — зачарований артефакт, створений саме для того, щоб розплести магічний щит некроманта. Щойно його застосовано, бар'єр падає, і Фел стає вразливим для смертельного удару."}},faq={{q="Хто такий Морбент Фел?",a="Морбент Фел — могутній некромант, що керує нежиттю, яка заполонила край довкола Воронячого Пагорба. Він засів у будинку на пагорбі над Цвинтарем Воронячого Пагорба й темним чаклунством захищає себе, мучачи живих Сутінколісся.",al={"лор морбента фела","хто такий морбент фел","передісторія морбента фела"}},{q="Навіщо Погибель Морбента, щоб його вбити?",a="Морбент Фел оточує себе потужними оберегами, що роблять його майже невразливим до звичайної шкоди. Погибель Морбента — зачарована реліквія, викувана саме для того, щоб розвіяти ці захисні чари й зробити його вразливим.",al={"погибель морбента","навіщо погибель морбента","як перемогти морбента фела"}},{q="Що пов'язує Свена Йорґена з Морбентом Фелом?",a="Свен утратив родину й ферму через темні сили, що никають Сутінколіссям. Різанину вчинили таємничі Темні Вершники, але некромантична хватка Морбента Фела на околицях — це те гнійне зло, що отруює захід Сутінколісся, тож він головна ціль Свенової помсти.",al={"чому свен хоче смерті морбента","свен йорґен морбент фел","помста свена"}},{q="Де знайти Морбента Фела?",a="Він мешкає на горішньому поверсі напівзруйнованого будинку на пагорбі просто на схід від табору Свена Йорґена, що височіє над західним боком Цвинтаря Воронячого Пагорба.",al={"місце морбента фела","де морбент фел","будинок морбента"}},{q="Чи Морбент Фел убив родину Свена?",a="Ні. Родину Свена вирізали таємничі Темні Вершники, що шукали Косу Елуни. Але некромантія Морбента Фела отруювала довколишній край і оскверняла могили Сутінколісся, тож без його знищення миру не повернути.",al={"чи морбент убив родину свена","хто вбив родину свена"}},{q="Що буде, коли Морбента Фела вбито?",a="Повернення Погибелі Морбента Свенові приносить згорьованому відлюдникові крихту розради. Хоча невловимі Темні Вершники досі на волі, смерть Фела ламає некромантичну хватку над Воронячим Пагорбом і здобуває шукачеві пригод добру славу по всьому Сутінколіссю.",al={"після морбента фела","кінець завдання","чи свен знайде спокій"}}},fp="11,289,24.408.0,16.390.1,14.367.0,19.237.0,44.233.0,48.301.0,31.166.0,35.250.1,40.258.1"}
P.entries["quest:550"] = {n="Битва за Гілсбред",s="Це завдання завершує кампанію Відступників проти людського містечка Гілсбред. Розбивши місцеві сили Альянсу, ви за дорученням Верховного Екзекутора Дарталії маєте передати офіційну грамоту Варіматрасові в Андерсіті.",h="Це завдання завершує кампанію Відступників проти людського містечка Гілсбред.",kw={"битва за гілсбред","верховний екзекутор дарталія","варіматрас","передгір'я гілсбреда","таррен мілл","королівський квартал","альянс"},ang={["faction:Horde"]="Відкинувши сили Альянсу в Лордероні, ви здобуваєте для Орди важливі землі у Східних Королівствах.",["race:Undead"]="Звіт про перемогу над живими Гілсбреда приносить вам пряму похвалу з Королівського Кварталу й утверджує ваше місце в зростаючій державі Темної Леді."},sec={{t="Вирішальна кампанія",b="Кампанія в Передгір'ї Гілсбреда — жорстока боротьба за південь Лордерона. Низкою ударів, скоординованих із Таррен Мілла, герої Орди знищили в людському містечку і фермерів, і ополчення, і коваля, і місцевий провід. Коли присутність Альянсу зламано, а край закріплено за Відступниками, Верховний Екзекутор Дарталія складає офіційну грамоту, щоб вісті про ці звитяги дійшли до найвищого командування."},{t="Аудієнція в жахолорда",b="Із запечатаною грамотою Дарталії шлях веде просто до Королівського Кварталу Андерсіті, перед очі Варіматраса. Цей жахолорд, що стоїть при Леді Сильвані Віндраннер, наглядає за воєнними діями по всьому Лордерону. Головною загрозою для Темної Леді лишається Погибель, що сходить із північних Чумних Земель, та закріпити південні кордони проти вцілілих людських анклавів для молодої держави Відступників не менш важливо."}},faq={{q="Що це за завдання?",a="Це остання здача в довгому ланцюжку «Битва за Гілсбред». Коли ви виконаєте доручення Верховного Екзекутора Дарталії в Таррен Міллі, вона дає вам запечатаного похвального листа, щоб ви особисто доставили його Варіматрасові в Андерсіті.",al={"фінал битви за хілсбред","останнє завдання хілсбреда","завдання 550"}},{q="Кому здати Запечатану Грамоту Дарталії?",a="Її треба віддати Варіматрасові, що стоїть поруч із Леді Сильваною Віндраннер у Королівському Кварталі Андерсіті.",al={"де варіматрас","здати похвалу","здати лист дарталії"}},{q="Чому Варіматраса цікавить Гілсбред?",a="Як головний воєначальник Темної Леді, Варіматрас керує стратегічною обороною й поширенням влади. Хоча найбільша загроза для Андерсіті — Погибель на півночі, людські поселення на півдні постійно непокоять лінії Відступників. Знищення загрози в Гілсбреді захищає їхній південний кордон.",al={"чому варіматрас","роль варіматраса в хілсбраді"}},{q="Хто така Верховний Екзекутор Дарталія?",a="Верховний Екзекутор Дарталія — старша командувачка Відступників у Таррен Міллі в Передгір'ї Гілсбреда, що керує наступальними діями проти сусіднього людського поселення.",al={"дарталія","хто дав завдання"}},{q="Чи веде це завдання до нових доручень у Гілсбреді?",a="Ні. Доставка грамоти Варіматрасові — офіційне завершення історії «Битва за Гілсбред», і вас нагороджують за те, що ви зламали оборону містечка.",al={"що після битви за хілсбред","що після завдання 550"}},{q="Чому Відступники взагалі напали на Гілсбред?",a="Містечко Гілсбред — один з останніх організованих людських осередків у Лордероні. Пов'язане з Альянсом, воно з його ополченням і близькістю становить безпосередню воєнну загрозу для Таррен Мілла й південних підступів до Андерсіті.",al={"чому напали на хілсбред","хілсбред лор"}}},fp="19,252,19.464.0,27.452.0,19.247.0,51.112.0,42.304.0,31.181.0,54.159.0,61.236.0"}
P.entries["quest:5502"] = {n="Опікун Орди",s="«Опікун Орди» завершує Тиждень Дітей: малого Ґранта повертають Матроні Сиротинця Баттлвейл у Долину Честі в Оргріммарі. Побачивши світ разом зі своїм опікуном, юний сирота мріє й сам стати героєм.",h="«Опікун Орди» завершує Тиждень Дітей: малого Ґранта повертають Матроні Сиротинця Баттлвейл у Долину Честі в...",kw={"опікун орди","ґрант","тиждень дітей","матрона баттлвейл","долина честі","оргріммар"},ang={["faction:Horde"]="Для Орди сила — не лише бойова вправність, а й спільна воля захищати й підтримувати беззахисних, які колись понесуть стяг Вождя.",["race:Orc"]="Культура орків шанує відвагу й честь, і милосердя до осиротілої дитини, як-от Ґранта, втілює ту шляхетність, яку Тралл прагне виховати в новій Орді."},sec={{t="Прощання сироти",b="Після пригод Тижня Дітей Ґрант дякує своєму опікунові за те, що той показав йому більше, ніж він міг собі намріяти. Згадавши, як батьки радили йому не скорятися негодам, він каже, що хоче стати таким самим героєм, як його супутник. Його останнє прохання — повернутися додому й розповісти матроні про їхні спільні мандри."},{t="Додому, у Долину Честі",b="Повернувшись до сиротинця в Долині Честі, шукачі пригод передають свого юного підопічного на опіку Матроні Сиротинця Баттлвейл. Турбота про малечу вважається святим обов'язком нової Орди, адже війна залишила без батьків безліч дітей. Баттлвейл хвалить ваше милосердя як справжню міру героя Орди, а Ґрант на прощання дарує вам улюбленого вихованця, щоб ви пам'ятали дружбу, що зародилася в мандрах."}},faq={{q="Яка мета цього завдання?",a="Це завдання завершує свято Тиждень Дітей для Орди. Поверніть Ґранта й Свисток Сироти Орків Матроні Сиротинця Баттлвейл у Долині Честі.",al={"підсумок опікуна орди","кінець тижня дітей орда"}},{q="Хто такий Ґрант?",a="Ґрант — юний орк із Сиротинця Оргріммара в Долині Честі. На Тиждень Дітей його доручають звитяжцеві Орди, який веде його по Калімдору подивитися на легендарних героїв і величні дива.",al={"хто такий сирота-орк","ґрант лор"}},{q="Що мені віднести матроні?",a="Поверніть Свисток Сироти Орків Матроні Сиротинця Баттлвейл, коли Ґрант буде готовий повернутися додому.",al={"повернути свисток сироти","повернути свисток ґранта"}},{q="Хто опікується сиротами в Оргріммарі?",a="Матрона Сиротинця Баттлвейл керує Сиротинцем Оргріммара в Долині Честі й присвятила життя тому, щоб давати притулок і ростити сиріт війни з Орди.",al={"матрона сиріт орди","хто керує сиротинцем"}},{q="Чому Ґрант хоче повернутися додому?",a="Його мандри на Тиждень Дітей скінчилися, і він хоче розповісти матроні про пригоди й про доброго опікуна, який брав його з собою.",al={"ґрант повертається додому","прощання тижня дітей"}},{q="Чому Тиждень Дітей важливий для Орди?",a="Десятиліття невпинних воєн із демонами, людьми й кентаврами лишили незліченних дітей Орди без родин. Тиждень Дітей — час, коли воїни відступають від поля бою, щоб ушанувати майбутні покоління Дуротару й не тільки.",al={"лор тижня дітей","чому орді сироти"}}},fp="21,218,20.317.0,27.456.0,34.157.0,14.217.0,35.101.0,38.151.0,36.136.0,46.247.0"}
P.entries["quest:5541"] = {n="Набої для Рамблшота",s="У зброяра Геґнара Рамблшота закінчуються дріб і порох для стрільців, що вправляються біля Анвілмару. Ящик із набоями покинуто в засніжених нетрях біля Сивого Лігва, коли голодні вендіго розігнали кур'єра.",h="У зброяра Геґнара Рамблшота закінчуються дріб і порох для стрільців, що вправляються біля Анвілмару.",kw={"рамблшот","набої","порох","зброяр","анвілмар","вендіго","лослор"},ang={["class:Hunter"]="Кожен стрілець у Холодному Хребті добре знає крамницю Геґнара; якщо його полиці повні свіжого пороху й дробу, ви ніколи не вийдете в нетрі з порожньою рушницею.",["profession:Engineering"]="Дворфійські рушниці й міномети вимагають тонко змеленого пороху й однакового дробу, тож запаси Рамблшота конче потрібні місцевим винахідникам і стрільцям.",["race:Dwarf"]="Дворфійське ремесло тримається на непорушному ланцюгу постачання між кузнями Анвілмару та зброярами на передовій, як-от Рамблшот."},sec={{t="Втеча кур'єра",b="Лослор Радж зі Складу Стілґрила підтримує постачання ремісників по всьому Дун Мороґу, та місцева звірина часто втручається. Його остання партія важких набоїв так і не дісталася придорожньої майстерні Геґнара Рамблшота. Отаборившись біля печер, відомих як Сиве Лігво, наляканий кур'єр натрапив на тутешніх вендіго й кинувся навтьоки, покинувши важкий дерев'яний ящик у снігу."},{t="Порох і дріб",b="Геґнар Рамблшот тримає збройну крамницю просто біля головної дороги, що веде від Анвілмару. На галявині перед його кузнею не вщухає рух: стрільці Айронфорджа, горяни та дворфійські мінометні загони приходять пристріляти зброю і повправлятися бойовими набоями. Без постійних ящиків пороху й свинцю від постачальників, як-от Лослор, вишкіл стрільців миттю заходить у глухий кут."}},faq={{q="Де загубили ящик із набоями?",a="Наляканий кур'єр Лослора Раджа впустив вантаж, коли отаборився одразу біля Сивого Лігва — печери, де кишать вендиго, серед засніжених пагорбів на південний захід від Хараноса.",al={"де набої","місце набоїв рамблшота","місце скрині"}},{q="Хто такий Геґнар Рамблшот?",a="Геґнар Рамблшот — дворфійський зброяр, що тримає збройову крамницю при дорозі біля Анвілмара. Він постачає порох, кулі й вогнепальну зброю горянам, мисливцям і облоговим загонам, що вправляються поблизу.",al={"хто такий геґнар","рамблшот","геґнар рамблшот"}},{q="Чому кур'єра прогнали?",a="Кур'єр схибив, отаборившись біля Сивого Лігва — лігва лютих, ревнивих до своєї території вендиго, що блукають пагорбами на південний захід від Хараноса.",al={"чому кур'єр втік","напад вендиго","історія кур'єра"}},{q="Чому в Геґнара Рамблшота скінчилися набої?",a="Дворфійські стрільці й мортирні обслуги безперервно витрачають порох і свинець, вправляючись у стрільбі біля Геґнарової крамниці, тож його товар завжди в ціні.",al={"чому закінчилися набої","у рамблшота немає набоїв"}},{q="Хто такий Лослор Радж?",a="Лослор Радж — дворфійський постачальник інженерного спорядження зі Складу Стілґрила, чия справа постачає набої Геґнарові Рамблшоту.",al={"лослор радж","хто такий лослор"}},{q="Чи псуються набої в снігу?",a="Дворфійські боєприпаси за традицією пакують у важкі, захищені від негоди дерев'яні ящики, щоб чорний порох лишався сухим і готовим спалахнути навіть у лютих хуртовинах Дун Мороґа.",al={"чи набої псуються в снігу","мокрий порох"}}},fp="19,236,18.424.0,15.410.0,30.174.0,25.197.0,31.148.0,43.156.0,20.122.0,44.165.0"}
P.entries["quest:5545"] = {n="Купа клопоту",s="Наглядачка Рейлен із Лісозаготівельного Табору Східної Долини має терміново здати партію деревини, а часу обмаль. Місцеві ведмеді й вовки відігнали її робітників від свіжозрубаного лісу, і цінні в'язки колод лишилися покинутими в північних хащах. Вона покладається на охочих шукачів пригод, які рушать у ліс, що кишить звіриною, і повернуть колоди, поки контракт не втрачено.",h="Наглядачка Рейлен із Лісозаготівельного Табору Східної Долини має терміново здати партію деревини, а часу...",kw={"купа клопоту","наглядачка рейлен","деревина","лісозаготівля","східна долина","вовки","ведмеді"},ang={["class:Hunter"]="Пробиратися гаями, повними хижаків, забирати припаси й давати раду небезпечним звірам — це саме те, на чому ґрунтуються інстинкти виживання слідопита.",["faction:Alliance"]="Деревина зі Східної Долини — запорука того, що відбудова Стормвінда й утримання прикордонних застав триватимуть без дорогих перебоїв у постачанні."},sec={{t="Строк підпирає",b="Лісозаготівельний Табір Східної Долини постачає деревину, конче потрібну для відбудови й оборони Королівства Стормвінд. Вести промислову лісозаготівлю на краю диких земель небезпечно, і Наглядачка Рейлен саме потрапила в халепу. Її бригада відстала від графіка з важливим вантажем зрубаного лісу, і час спливає."},{t="Хижаки серед колод",b="Річ не в нестачі повалених дерев, а в агресивній місцевій звірині. Голодні вовки й ведмеді, що бережуть свою територію на північ від табору, розігнали лісорубів, і ті покинули акуратно перев'язані в'язки дров, розкидані лісом. Міську владу про звірину вже сповістили, та Рейлен не може чекати, поки варта убезпечить місцевість: доводиться наймати мандрівних героїв, щоб ті прошмигнули в ліс і зібрали деревину."}},faq={{q="Хто така Наглядачка Рейлен?",a="Наглядачка Рейлен керує щоденною роботою Лісозаготівельного Табору Східної Долини на сході Лісу Елвінн. Вона наглядає за бригадами лісорубів і стежить, щоб постачання деревини відповідало потребам Стормвінда й місцевих поселень.",al={"наглядачка рейлен","рейлен","наглядачка іствейлу"}},{q="Чому деревина лежить покинута в лісі?",a="Робітники вже зрубали, обтесали й пов'язали колоди в'язками, коли дикі ведмеді й вовки-нишпорки прогнали їх із галявини. Боячись за життя, лісоруби втекли до табору, не забравши вантажу.",al={"чому деревина покинута","деревина в лісі","покинутий ліс"}},{q="Чому Рейлен згадує Помічника Рейнера?",a="Рейлен каже, що звернулася до Помічника Рейнера щодо агресивних хижаків. Цікаво, що Помічник Рейнер служить аж на іншому кінці Лісу Елвінн, у Гарнізоні Вестбрук, — отже, або повідомлення передавали офіційними каналами варти, або місцевої влади в краї катастрофічно бракує.",al={"чому рейлен згадує рейнера","помічник рейнер рейлен","зв'язок рейнера"}},{q="Куди потрібна деревина?",a="Лісозаготівельний Табір Східної Долини постачає деревину по всьому королівству — для відбудови міст, зміцнення частоколів і мостів. Зірвані строки шкодять місцевому господарству й гальмують будівництво по всьому Елвінну.",al={"кому деревина","доставка деревини","призначення деревини"}},{q="Чому лісоруби не можуть зібрати деревину самі?",a="Лісоруби — звичайні робітники, споряджені рубати дерева, а не відбиватися від диких хижаків. Після того як агресивні вовки й ведмеді напали на них і розігнали, ніхто з них не ризикне повертатися в хащі беззбройним.",al={"чому лісоруби налякані","чому не лісоруби","лісоруби і вовки"}},{q="Де шукати в'язки деревини?",a="В'язки зрубаної деревини лежать на землі в лісі просто на північ від Лісозаготівельного Табору Східної Долини, де працювали лісоруби, доки їх не прогнали місцеві звірі.",al={"місце деревини","де в'язки","знайти в'язки"}}},fp="19,381,18.366.0,23.444.0,25.223.0,39.217.0,38.302.0,27.225.0,50.248.0,39.188.0"}
P.entries["quest:555"] = {n="Заспокійливий Черепаховий Суп",s="Шеф-кухар Джессен із Саутшора пишається тим, що готує найкращі страви на північ від Стормвінда, але недавні заворушення відрізали йому постачання свіжого м'яса черепах-клацозубів. Щоб повернути свій знаменитий Заспокійливий Черепаховий Суп до меню таверни, він просить мандрівників, яким не байдужа кулінарія, вирушити до небезпечних північних вод біля Даларана й Озера Лордамер.",h="Шеф-кухар Джессен із Саутшора пишається тим, що готує найкращі страви на північ від Стормвінда, але недавні...",kw={"заспокійливий черепаховий суп","шеф-кухар джессен","саутшор","черепахи-клацозуби","озеро лордамер","кулінарія","завдання"},ang={["faction:Alliance"]="Повернення Саутшорові маленьких радощів допомагає підтримувати бойовий дух містечка, що стоїть самотою проти ворожих розбійників Синдикату й поширення Відступників.",["profession:Cooking"]="Шеф-кухар Джессен ділиться своїм ремеслом лише з колегами-кухарями й винагороджує вас рецептом, щоб ви могли зварити власний Заспокійливий Черепаховий Суп.",["race:Human"]="Для людей, що приїжджають із південних королівств, страви Джессена — рідкісний смак дому й гостинності на неспокійній півночі."},sec={{t="Північний делікатес",b="Саутшор — одне з останніх уцілілих прибережних містечок Альянсу в Лордероні, що гордо тримається за мирне життя серед дедалі гострішого розбрату в краї. Шеф-кухар Джессен запевняє, що його куховарство не поступається жодній таверні на північ від Стормвінда, а відвідувачі нібито приходять аж із Даркшира в Сутінколіссі, тільки щоб скуштувати його фірмову страву — Заспокійливий Черепаховий Суп. Цей наваристий, відновлювальний суп цілком залежить від свіжого м'яса черепах-клацозубів, що водяться в річках і озерах північних гір."},{t="Небезпеки Лордамеру",b="У спокійніші роки Джессен сам добував черепахове м'ясо, ходячи повз магічний купол Даларана до східних берегів Озера Лордамер. Проте дедалі більша напруга, ворожі звірі, Синдикат і вторгнення Відступників зробили пошуки за межами міста смертельно небезпечними для звичайних городян. Щоб казан і далі кипів, а відвідувачі лишалися задоволеними, кухар покладається на озброєних шукачів пригод, готових добувати м'ясо клацозубів, що чатують на берегах річок і північних озер."}},faq={{q="Хто дає завдання «Заспокійливий Черепаховий Суп»?",a="Це прохання дає кухарям-гостям Шеф-кухар Джессен — майстер кулінарії з прибережного містечка Альянсу Саутшор у Передгір'ї Гілсбреда.",al={"хто дає черепаховий суп","де почати черепаховий суп","завдання шефа джессена"}},{q="Чому Шеф-кухарю Джессену потрібна стороння допомога з черепашачим м'ясом?",a="Колись Джессен сам полював на черепах-хапозубів біля Даларану й Озера Лордамер, але через політичні негаразди й хижих звірів край став надто небезпечним, тож йому доводиться наймати шукачів пригод.",al={"чому джессен не дістане м'ясо","чому джессену черепахи"}},{q="Де в краї водяться черепахи-хапозуби?",a="Черепахи-хапозуби живуть уздовж прісноводної річки між Передгір'ям Гілсбреда й Горами Альтерак, а також на берегах Озера Лордамер на північ від Даларану.",al={"місце м'яса черепахи","де хапозуби","де фармити м'ясо черепахи"}},{q="Чи треба знати Кулінарію, щоб узяти це завдання?",a="Так. Шеф-кухар Джессен ділиться цим проханням і своїми кулінарними секретами лише з тими, хто навчався ремесла Кулінарії, хоча певного рівня вміння для цього не треба.",al={"чи потрібна кулінарія","потрібна професія кулінарії","чи кожен може черепаховий суп"}},{q="Чим славиться кухня Саутшора?",a="Шеф-кухар Джессен вихваляється, що в Саутшорі подають найкращі страви на північ від Стормвінда, а по його знаменитий черепаховий суп нібито приїздять гурмани аж із Даркширу.",al={"їжа саутшора","чому джессен відомий","подорож до даркшира за супом"}},{q="На які негаразди нарікає Шеф-кухар Джессен?",a="Гілсбред і Альтерак охопило відкрите протистояння між Відступниками з півночі, розбійниками Синдикату, що никають руїнами, і дикими хижаками, яких зігнало з місць падіння Лордерона, тож мирним мешканцям подорожувати небезпечно.",al={"тривога хілсбреда","чому зараз небезпечно","які негаразди"}}},fp="22,334,19.495.0,18.473.0,48.147.0,61.203.0,46.175.0,47.178.0,35.180.0,39.212.0"}
P.entries["quest:556"] = {n="Кам'яні жетони",s="«Кам'яні жетони» — доручення Орди від Хранителя Бел'варіла в Таррен Міллі: добути магічні знаряддя підкорення в агентів Даларана в краї Альтерак. Відступники прагнуть вивчити таємні методи, якими маги Даларана поневолюють могутніх елементалів і командують ними. Збирання цих бездіяльних жетонів закладає основу для досліджень Мага щодо підкорення стихій.",h="«Кам'яні жетони» — доручення Орди від Хранителя Бел'варіла в Таррен Міллі: добути магічні знаряддя підкорення...",kw={"кам'яні жетони","хранитель бел'варіл","маг войдґлер","даларан","елементалі","таррен мілл","завдання"},ang={["class:Mage"]="Даларанські закликачі славляться тим, що підкоряють елементалів своїй волі; вивчення цих жетонів відкриває, як людські маги прив'язують духів з інших вимірів до матеріальних фокусів.",["class:Shaman"]="Шамани шанують елементалів через взаємні угоди, а даларанські чарівники підкоряють і поневолюють їх таємними жетонами — практика, протилежна духовній злагоді.",["race:Undead"]="Для Відступників Таррен Мілла розгадка таємниць Даларана конче потрібна, щоб уберегти Лордерон від людських чаклунів, що причаїлися просто за фіолетовим куполом."},sec={{t="Таємне підкорення",b="Маги Даларана здавна мають грізну владу над стихійними сутностями: вони використовують особливі провідники й зачаровані фокуси, щоб підкоряти істот з інших вимірів і змушувати їх служити. Саме місто сховане під велетенським фіолетовим куполом, але його агенти й рештки сил патрулюють довколишні землі, покладаючись на елементалів як на робітників і ударні оборонні загони. Маг Войдґлер, дослідник таємної магії, що працює на Відступників у Таррен Міллі, прагне розібрати, яким саме чаклунством Даларан змушує цих істот коритися."},{t="Збирання бездіяльних зразків",b="Замість одразу вимагати потужних і нестійких магічних знарядь, Хранитель Бел'варіл посилає агентів роздобути стерті, вицвілі жетони. Зібравши ці виснажені обереги в даларанців, розставлених на околицях і біля сусіднього табору інтернування, Войдґлер зможе безпечно вивчити залишкові чари, не ризикуючи неконтрольованим ударом з інших планів буття. Ці потерті жетони дають основу теоретичних знань, перш ніж братися за могутніші механізми підкорення."}},faq={{q="Навіщо потрібні кам'яні жетони?",a="Чарівники Даларану виготовляють і носять ці кам'яні жетони як магічні осередки, щоб наказувати елементалям і скоряти їх, змушуючи істот з інших вимірів служити вартовими, чатовими й робітниками.",al={"навіщо кам'яні жетони","чому в магів даларана жетони","що роблять жетони"}},{q="Чому Магові Войдґлеру потрібні саме стерті жетони?",a="Стерті кам'яні жетони зберігають основну магічну матрицю даларанських сковувальних чарів, але їхня активна тайна сила вже вивітрилася. Тож Магові Войдґлеру набагато безпечніше розбирати й вивчати їх, не ризикуючи лютою відплатою елементалів чи вибуховою магічною віддачею під час перших дослідів.",al={"чому стерті жетони","чому не діючі жетони"}},{q="Хто такий Хранитель Бел'варіл?",a="Хранитель Бел'варіл — провідник Відступників у Таррен Міллі в Передгір'ї Гілсбреда. Він керує тактичними діями проти людських сил у краї й допомагає дослідникам на кшталт Мага Войдґлера, роздобуваючи магічні артефакти й ворожі реагенти із сусідніх земель.",al={"бел'варіл","хто дає кам'яні жетони"}},{q="У яких даларанських сил ці жетони?",a="Жетони носять чарівники Даларану та їхні люди, що стоять на прикордонні між заходом Гілсбреда й Горами Альтерак, — особливо біля даларанського магічного купола й сусідніх руїн старого табору для інтернованих орків.",al={"де жетони","місце сил даларана"}},{q="Що буде, коли жетони доставлено?",a="Коли Бел'варіл оглядає неактивні зразки, Маг Войдґлер переходить від теоретичних досліджень до фізичного утримання й доручає роздобути важчі Наручі Скування просто з самих елементалів.",al={"що після кам'яних жетонів","продовження кам'яних жетонів"}},{q="Чому Орда вивчає магію Даларану?",a="Відступники вважають уцілілих магів Даларану прямою загрозою своїм землям і своїй магії в Лордероні. Розгадавши їхні тайні методи, заклиначі Відступників зможуть протидіяти діям Кірін-Тору, захищати кордони й, можливо, обернути сили стихій собі на користь.",al={"чому орда вивчає магію даларана","інтерес відступників до даларана"}}},fp="12,374,18.557.0,24.482.1,35.194.0,55.302.0,24.283.0,50.235.0,46.231.1,42.296.0"}
P.entries["quest:559"] = {n="Доказ Фаррена",s="«Доказ Фаррена» — доручення Альянсу в Саутшорі від Лейтенанта Фаррена Орінелля. Щоб довести своєму начальникові, Маршалові Редпату, що він справді патрулює узбережжя, Фаррен посилає новобранців збирати відтяті голови мурлоків уздовж Західного Узмор'я.",h="«Доказ Фаррена» — доручення Альянсу в Саутшорі від Лейтенанта Фаррена Орінелля.",kw={"доказ фаррена","фаррен орінелль","маршал редпат","голови мурлоків","західне узмор'я","саутшор","завдання"},ang={["faction:Alliance"]="Щоб утримати Саутшор, треба вбезпечити його узбережжя від місцевих хижаків, аби застава могла зосередитися на загрозах Синдикату й Орди.",["profession:Cooking"]="Для кухарів Саутшора, що готують рибу, гидливість Фаррена до морепродуктів незбагненна, хоча бої на пляжі часто дають чималий сирий улов."},sec={{t="Неохоче прохання",b="Після перших прочісувань узбережжя в завданні «Уздовж узбережжя» Лейтенант Фаррен Орінелль опиняється під пильним наглядом Маршала Редпата й міського начальства. Приписати собі очищення берега від місцевих мурлоків — одне, а показати недовірливому начальству незаперечні докази — зовсім інше. Не бажаючи бруднити власних рук моторошною різаниною, Фаррен доручає мандрівним шукачам пригод з Альянсу повернутися на берег і зібрати відчутні докази."},{t="Моторошні докази",b="Завдання веде бійців на захід від Саутшора, уздовж Західного Узмор'я, де на мілинах гніздяться прибережні мурлоки. Лейтенантові потрібно десять відтятих голів мурлоків, щоб задовольнити офіцерів міського гарнізону. Сам Фаррен цих істот ненавидить і зізнається, що огидний вигляд і запах земноводних людей-риб геть відбили йому апетит до головного товару й основної їжі Саутшора."}},faq={{q="Хто такий Лейтенант Фаррен Орінелль?",a="Лейтенант Фаррен Орінелль — міський офіцер Альянсу в Саутшорі. Він залюбки доповідає начальству про успіхи, але брудну й криваву частину охорони узбережжя воліє перекладати на вправних шукачів пригод.",al={"фаррен орінелль","хто дає доказ фаррена","лейтенант фаррен"}},{q="Навіщо Фарренові відрубані голови мурлоків?",a="Маршала Редпата й міську владу не задовольнили прості усні звіти про те, що Західне Узмор'я очищено. Вони вимагали речових доказів загибелі мурлоків, перш ніж офіційно визнати успіх патрулю.",al={"навіщо голови мурлоків","причина доказу фаррена","навіщо збирати голови"}},{q="Де живуть ці мурлоки?",a="Мурлоки живуть на Західному Узмор'ї — прибережних пляжах, що тягнуться просто на захід від Саутшора до кордону зі Срібноліссям.",al={"місце голів мурлоків","де західне узбережжя","місця мурлоків хілсбреда"}},{q="Що буде, коли здати «Доказ Фаррена»?",a="Фаррен просить вас доповісти про загибель мурлоків Маршалові Редпату. Прийнявши докази, Редпат зосереджується на загрозах на Східному Побережжі, а згодом передає Фарренові накази про переведення зі Стормвінда.",al={"наступне завдання після доказу фаррена","ланцюжок фаррена","продовження доказу фаррена"}},{q="Чому Фаррену гидко від мурлоків?",a="Фарренові огидні риби, що ходять на двох ногах. Від їхніх холодних слизьких решток у нього геть відпала охота їсти рибу, і життя в рибальській громаді Саутшора для нього — суцільна мука.",al={"фаррен риба","чому фаррен не любить рибу"}},{q="Хто такий Маршал Редпат?",a="Маршал Редпат — командир оборонних сил містечка Саутшор, що вимагає від молодших офіцерів на кшталт Фаррена Орінелля звіту за безпеку краю.",al={"капітан редпат","хто такий редпат"}}},fp="14,256,18.467.0,15.392.0,34.226.0,42.222.0,32.138.0,45.214.1,39.217.0,23.187.0"}
P.entries["quest:56"] = {n="Нічна Варта",s="Це доручення Командира Алтеї Ебонлок у Даркширі кличе шукачів пригод прорідити лави нежиті, що повстає на сусідньому Цвинтарі Тихих Садів. Покинуте офіційним гарнізоном Стормвінда, місцеве ополчення Даркшира покладається на мандрівних найманців, щоб стримати жахіття, які підступають.",h="Це доручення Командира Алтеї Ебонлок у Даркширі кличе шукачів пригод прорідити лави нежиті, що повстає на...",kw={"нічна варта","алтея ебонлок","цвинтар тихих садів","кістяки","даркшир","сутінколісся"},ang={["class:Paladin"]="Тихі Сади — образа Світла: осквернені могили полеглих містян вимагають освяченої сталі й праведного суду.",["class:Priest"]="Упокоїти цих змучених, неспокійних кістяків — вияв духовного милосердя в краї, що задихається під зловісними прокльонами.",["faction:Alliance"]="Для вірних Альянсові це доручення оголює гірку правду про недбалість Стормвінда: прикордонні жителі змушені проливати кров за власне виживання без королівської допомоги."},sec={{t="Покинуті Короною",b="Колись Сутінколісся стояло під щитом Стормвінда, але коли королівських ресурсів стало бракувати, а столицю охопили політичні чвари, Корона відкликала своїх вояків. Даркшир лишився майже беззахисним перед тінями, що насувалися. У відповідь мешканці лісу створили Нічну Варту — власне ополчення, яке нині очолює Командир Алтея Ебонлок і яке стоїть між проклятим лісом і рештою містян."},{t="Очищення Тихих Садів",b="На південь від Даркшира лежить Цвинтар Тихих Садів — колись мирне місце спочинку, а нині кубло неспокійних кістяків і оживлених чарівників. Нічна Варта небезпечно розпорошена вздовж кордонів Сутінколісся, тож Командир Ебонлок посилає новоприбулих шукачів пригод знищувати кістяків-воїнів і кістяків-магів, доки мерці з цвинтаря не вихлюпнулися на дороги."}},faq={{q="Чому Нічній Варті потрібна стороння допомога?",a="Стормвінд відкликав свій офіційний гарнізон із Сутінколісся, і містечко Даркшир мусить боронитися саме. Нічна Варта — лише місцеве ополчення, якому без допомоги ззовні бракує людей і припасів, щоб відбиватися від навали нежиті по всьому краю.",al={"чому потрібна допомога","чому даркшир слабкий","чому немає вартових"}},{q="Хто така Командир Алтея Ебонлок?",a="Алтея Ебонлок — родичка мера Даркширу, Лорда Елло Ебонлока, і рішуча командирка Нічної Варти. Вона взяла на себе організацію оборони містечка й збирає кожного, хто здатен і готовий стати проти темних загроз Сутінколісся.",al={"хто така алтея","командир ебонлок","алтея ебонлок лор"}},{q="Де розташований Цвинтар Тихих Садів?",a="Цвинтар Тихих Садів лежить трохи на південь від Даркширу. На ньому досі ховають мерців, але він став жертвою темної магії, що просякла Сутінколісся: мертві встають і нападають на подорожніх біля околиць містечка.",al={"місце цвинтаря тихих садів","де цвинтар","де шукати скелетів"}},{q="Які істоти встають у Тихих Садах?",a="Цвинтар заполонили передусім оживлені скелети-воїни й скелети-маги. На відміну від звичайних трупів, ці рештки зберегли залишки бойової вправності й тайної сили, тож становлять смертельну загрозу для простих містян.",al={"яка нежить там","скелети сутінколісся"}},{q="Чи надсилає Стормвінд підкріплення?",a="Ні. Стормвінд відкликав своїх вартових із постів, кинувши віддалене прикордоння Сутінколісся напризволяще.",al={"чи стормвінд допоможе","чи надішле стормвінд війська"}},{q="Чи кладе це доручення край загрозі на цвинтарі?",a="Ні, проріджування скелетів у Тихих Садах — лише перший крок. Нічна Варта стикається з дедалі більшими загрозами глибше в лісі, і, щоб стримати дедалі гіршу скверну в краї, знадобляться нові вилазки.",al={"чи це єдине завдання","ланцюжок нічної варти"}}},fp="15,294,22.441.0,29.371.0,43.267.0,34.254.0,39.225.0,50.218.0,40.138.0,52.211.0"}
P.entries["quest:560"] = {n="Доказ Фаррена",s="«Доказ Фаррена» — коротке доручення в Саутшорі: шукач пригод несе моторошну здобич — голови мурлоків — від Лейтенанта Фаррена Орінелля до Маршала Редпата. Дозволивши іншим виконати криваву роботу на узбережжі, гидливий лейтенант перекладає на них і звітування. Це проміжний крок до визнання в містечку на узбережжі Гілсбреда.",h="«Доказ Фаррена» — коротке доручення в Саутшорі: шукач пригод несе моторошну здобич — голови мурлоків — від...",kw={"доказ фаррена","фаррен орінелль","маршал редпат","голови мурлоків","саутшор","завдання"},ang={["faction:Alliance"]="Кожне дрібне доручення в Саутшорі допомагає тримати головний оплот Альянсу в Лордероні укріпленим проти ворожих сил, що тиснуть із півночі й з моря.",["race:Human"]="Для мандрівників-людей справи з Фарреном і Редпатом відверто показують напружену бюрократію й утому від прикордоння в гарнізоні Гілсбреда."},sec={{t="Гидливий офіцер",b="Лейтенантові Фаррену Орінеллю доручено патрулювати й убезпечувати південне узбережжя Передгір'я Гілсбреда, проте жорстокі реалії прикордонної війни йому не до смаку. Пославши шукача пригод винищити мурлоків, що кишать на пляжах, він гидує навіть торкнутися відтятих голів, принесених як доказ. Замість самому нести мокрі трофеї до командування Саутшора, Фаррен радо спихає доручення назад на того, хто їх приніс."},{t="Доповідь Редпатові",b="На іншому кінці Саутшора Маршал Редпат керує обороною містечка й готовністю війська серед дедалі більших загроз із Таррен Мілла й від диких звірів. Його анітрохи не дивує, що мішок голів мурлоків приносить гонець, а не лейтенант особисто. Розуміючи, що шукач пригод став у Фаррена хлопчиком на побігеньках, Редпат достатньо прагматичний, щоб прийняти допомогу, бо знає: Саутшорові потрібна кожна пара старанних рук, щоб утримати свої кордони."}},faq={{q="Чому Лейтенант Фаррен не доставляє голови мурлоків сам?",a="Лейтенантові Фаррену просто не хочеться тягати мішок, з якого скрапує, повний відрубаних мурлочих голів. Він уже найняв шукача пригод битися замість себе, тож куди зручніше доручити йому й брудну доставку Маршалові Редпату.",al={"чому фаррен не йде сам","навіщо доставляти доказ фаррена","чому посильний"}},{q="Хто такий Маршал Редпат?",a="Маршал Редпат — старший воєначальник Альянсу в Саутшорі. Він керує місцевою обороною, координує міську варту й дає раду різним загрозам, що нависли над людським поселенням у Передгір'ї Гілсбреда.",al={"хто такий редпат","маршал редпат лор","маршал саутшора"}},{q="Куди ця доставка веде далі в ланцюжку?",a="Доставка доказів веде до нових доручень від Маршала Редпата й Лейтенанта Фаррена, а зрештою — до офіційних донесень про розміщення військ і паперів, які відсилають до столиці, Стормвінда.",al={"що далі","наступне завдання доказу фаррена","наступне завдання редпата"}},{q="Чому мурлоки — пріоритет для гарнізону Саутшора?",a="Племена мурлоків густо гніздяться на пляжах узбережжя Гілсбреда. Якщо їх не стримувати, вони грабують прибережні шляхи постачання, непокоять місцевих рибалок і загрожують південним підступам до Саутшора, поки містечко й так зайняте Відступниками на півночі.",al={"чому мурлоки пріоритет","проблема мурлоків саутшора","мурлоки хілсбреда"}},{q="Що Маршал Редпат думає про поведінку Лейтенанта Фаррена?",a="Маршал Редпат добре знає звички Фаррена й сухо зауважує, що гонець став «хлопчиком на побігеньках у Фаррена». Утім, Редпат радий допомозі, бо Саутшорові непереливки й йому придадуться будь-які вправні руки.",al={"думка редпата про фаррена","чи редпат любить фаррена"}},{q="Де в Саутшорі знайти Маршала Редпата?",a="Маршал Редпат — біля центру містечка й будівлі ради в Саутшорі, звідки він наглядає за щоденною обороною поселення.",al={"знайти редпата","де маршал редпат","місце редпата"}}},fp="14,384,19.481.0,17.495.0,63.239.0,23.229.0,54.204.0,53.260.0,63.230.0,47.147.0"}
P.entries["quest:561"] = {n="Доказ Фаррена",s="«Доказ Фаррена» — доручення гінця Альянсу в портовому містечку Саутшор. Діючи від імені Маршала Редпата, шукач пригод доставляє наказ, що велить Лейтенантові Фаррену Орінеллю зосередити свою військову увагу на нагах, які підступають до Східного Побережжя.",h="«Доказ Фаррена» — доручення гінця Альянсу в портовому містечку Саутшор.",kw={"доказ фаррена","маршал редпат","фаррен орінелль","наги","східне побережжя","саутшор","завдання"},ang={["class:Warrior"]="Для солдатів під стягом Альянсу дрібні заздрощі офіцерської політики — знайоме роздратування: бойова доблесть часто стикається з командирськими амбіціями.",["faction:Alliance"]="Ця сутичка дає змогу зазирнути в бюрократичне й кар'єрне суперництво, що тліє в гарнізоні Саутшора: навіть в обложених північних заставах офіцери змагаються за престиж."},sec={{t="Зміна наказів",b="Військове керівництво Саутшора затиснуте навколишніми загрозами, проте Маршал Редпат пильно стежить і за морськими небезпеками на південному узбережжі. Отримавши свіжі відомості про вторгнення наг на Східне Побережжя, Редпат посилає гінця через усе містечко до Лейтенанта Фаррена Орінелля з прямим наказом: облишити другорядні справи, знищити земноводну загрозу й особисто доповідати Маршалові про успіхи."},{t="Суперництво на узбережжі",b="Отримавши послання, Лейтенант Орінелль відкриває приховане тертя між офіцерами гарнізону Саутшора. Замість сумлінно скоритися, Орінелль підозрює, що Редпат хоче скористатися нещодавно переданими відомостями, щоб приписати собі заспокоєння узбережжя. Сповнений рішучості не дати командирові здобути підвищення на поті своїх солдатів, Орінелль одразу починає шукати власного способу запобігти ласки в корони."}},faq={{q="Яка мета цієї доставки?",a="Маршал Редпат хоче перекинути загін Лейтенанта Фаррена Орінелля проти наг, що заполонили Східне Побережжя Гілсбреда, і вимагає, щоб Орінелль доповів йому особисто, щойно буде помітний поступ.",al={"чого хоче редпат","чому слати повідомлення фарену","мета доказу фаррена 3"}},{q="Чому Фаррен Орінелль так гірко сприймає накази Редпата?",a="Орінелль вважає, що Редпат діє на підставі тих самих військових відомостей, які щойно отримали вони обидва. Він боїться, що маршал хоче привласнити собі заслугу за очищення узбережжя й заробити підвищення на важкій праці Орінелля.",al={"суперництво фаррена і редпата","чому орінелль сердитий","підвищення орінелля"}},{q="Де розташоване Східне Побережжя?",a="Східне Побережжя тягнеться вздовж південного морського узбережжя Передгір'я Гілсбреда, на південний схід від Саутшора, де наги, що наступають, облаштували на піску свої мерзенні табори.",al={"місце східного узбережжя","де наги","узбережжя хілсбреда"}},{q="Що далі після доставки цього повідомлення?",a="Після цієї зустрічі Орінелль замість того, щоб чесно скоритися владі Редпата, плете власну інтригу й посилає завзятих гінців уздовж узбережжя, а тоді до вищого командування — у завданні «Курс на Стормвінд!».",al={"що далі","що буде далі","стормвінд далі"}},{q="Хто з провідників бере участь у цій розмові?",a="Маршал Редпат — головний командир гарнізону Саутшора, а Лейтенант Фаррен Орінелль служить під його началом як польовий лейтенант, що відповідає за оборону узбережжя.",al={"хто фаррен і редпат","офіцери саутшора","фаррен орінелль і редпат"}},{q="Чи треба в цьому дорученні битися?",a="Ні. Цей крок — суто доручення з передачі повідомлення між офіцерами Саутшора, хоча стосується воно безпосередньо військової відповіді на ворожих наг на узбережжі.",al={"чи буде бій","чи битися з нагами","бій доказу фаррена"}}},fp="14,268,18.467.0,20.452.1,37.209.0,60.210.0,36.198.0,46.211.1,46.174.0,40.187.0"}
P.entries["quest:562"] = {n="Курс на Стормвінд!",s="Лейтенант Фаррен Орінелль відчайдушно прагне вирватися зі свого посту в Саутшорі й повернутися на південь, до Стормвінда. Почувши, що Верховне Командування Альянсу побоюється дедалі більшої загрози наг, він бачить нагоду для кар'єри й наймає шукача пригод винищити змієподібних, щоб приписати заслугу собі й домогтися переведення.",h="Лейтенант Фаррен Орінелль відчайдушно прагне вирватися зі свого посту в Саутшорі й повернутися на південь, до...",kw={"курс на стормвінд","фаррен орінелль","наги","кинджалоспини","майор семюелсон","саутшор","завдання"},ang={["faction:Alliance"]="Командування Альянсу в Гілсбреді розтягнуте до краю, і звичайні міські вартові виявляються безпорадними перед потворними загрозами на кшталт наг Кинджалоспинів.",["race:Human"]="Для людей, що служать у Лордероні, Саутшор — похмуре нагадування про втрачену північну славу, що разюче контрастує з відбудованою величчю й безпекою Стормвінда на півдні."},sec={{t="Квиток із Саутшора",b="Саутшор стоїть на лезі ножа Лордерону, затиснутий між силами Відступників, розбійниками Синдикату й невпинними морськими потворами. Для Лейтенанта Фаррена Орінелля, звичайного вартового, що звик до міських п'яниць і дрібних бійок у Стормвінді, це призначення — суцільне нещастя. Коли від колишнього наставника надходить звістка, що Верховне Командування Альянсу дедалі більше тривожиться через наг, які підступають до узбереж, Фаррен бачить свою золоту нагоду покинути північ."},{t="Чужа слава на узбережжі",b="Попри високі амбіції, Фаррен відверто визнає своє боягузтво: битися у відкритому бою з лютими сиренами й береговими мисливцями Кинджалоспинів — понад його відвагу й сили. Замість ризикувати шиєю, він наймає шукача пригод прочесати пляжі на південний схід від Саутшора, прорідити лави наг і здобути ті бойові звершення, які потрібні Фарренові, щоб скласти вражаюче донесення Майорові Семюелсону в Стормвінді."}},faq={{q="Чому Фаррен Орінелль хоче вбити наг?",a="Самі наги його не обходять — він хоче вибратися із Саутшора. Від свого наставника Фаррен дізнався, що вище командування Альянсу стурбоване загрозою наг, тож успішні дії проти них — швидкий шлях до підвищення чи переведення назад до Стормвінда.",al={"чому наги","мотив фаррена","чому вбивати наг у саутшорі"}},{q="Чи може Лейтенант Фаррен Орінелль сам битися з нагами?",a="Ні. Фаррен відверто визнає, що він лише міський вартовий, здатний розборонити п'яну бійку в таверні чи заарештувати галасливого жебрака. Люті наги Кинджалоспинні його жахають, тож усю бійку він цілком перекладає на мандрівних шукачів пригод.",al={"чому фаррен не б'ється","чи фаррен слабкий","бойові навички фаррена"}},{q="Де живуть наги Кинджалоспинні?",a="Мисливці-берегові й сирени Кинджалоспинних облаштували табори на узбережжі просто на південний схід від містечка Саутшор і никають берегами Великого Моря в Передгір'ї Гілсбреда.",al={"де наги","місце кинджалоспинних","узбережжя нагів саутшора"}},{q="Хто такий Майор Семюелсон?",a="Майор Семюелсон — колишній наставник Фаррена Орінелля в міській варті Стормвінда. Фаррен складає для нього звіти про знищених наг, сподіваючись, що Семюелсон смикне за потрібні ниточки й домовиться про його переведення назад на південь.",al={"майор семюелсон","семюелсон стормвінд","кому лист"}},{q="Що буде після цього доручення?",a="Коли загрозу наг пригашено, а Фаррен привласнив собі вашу заслугу, він посилає вас на південь, до Фортеці Стормвінда, щоб ви особисто доставили його звіт і прохання про переведення Майорові Семюелсону.",al={"що далі","наступне завдання після курсу на стормвінд","завдання переведення"}},{q="Чому Фаррен так ненавидить Саутшор?",a="Фаррен вважає Саутшор похмурою, небезпечною прикордонною заставою, далекою від цивілізованої безпеки Стормвінда. Між мертвими сусідами й прибережними чудовиськами він гірко називає його «портом, покинутим Світлом».",al={"чому фаррен ненавидить саутшор","легкий порт відступників"}}},fp="13,322,26.475.0,25.402.0,47.272.0,54.243.0,39.195.0,23.229.0,40.184.1,40.215.0"}
P.entries["quest:5621"] = {n="Шати Місяця",s="«Шати Місяця» — вступний обряд служіння для юних жерців нічних ельфів у Доланаарі. Наставниця жерців Лаурна Морнінґлайт доручає посвяченому подбати про Вартову Шаю — поранену захисницю, що патрулює ліси на південь від поселення. Виконання цього обов'язку знаменує офіційне визнання посвяченого в Сестринстві Елуни.",h="«Шати Місяця» — вступний обряд служіння для юних жерців нічних ельфів у Доланаарі.",kw={"шати місяця","жрець","лаурна морнінґлайт","вартова шая","сестринство елуни","доланаар"},ang={["class:Priest"]="Цей обряд показує два стовпи жрецтва: зцілення поранених союзників відновлювальною молитвою і захист їх від майбутньої небезпеки божественними оберегами.",["race:NightElf"]="Для калдорей Сестринство Елуни й Вартові тисячоліттями працюють пліч-о-пліч, захищаючи ліси й народ від навислої темряви."},sec={{t="Священне покликання",b="У гіллі Тельдрассила Сестринство Елуни дбає і про духовне життя калдорей, і про практичний захист їхніх кордонів. Коли Вартова Шая зазнає поранень, патрулюючи небезпечні хащі на південь від Доланаара, наставниця жерців Лаурна Морнінґлайт не може покинути свій пост, щоб допомогти. Натомість вона доручає щойно навченому посвяченому довести свою відданість: загоїти рани Шаї й зміцнити її захисними чарами."},{t="Облачення Сестринства",b="Жерці, що відновлюють сили Вартової Шаї, повертаються до Доланаара по свої перші офіційні шати. Це вбрання засвідчує, що молодий послушник перейшов від класних настанов до практичного, рятівного служіння під благодаттю місяця. У суспільстві калдорей підтримувати Вартових — не просто військове завдання: це акт єднання з Елуною й неодмінний обов'язок заради безпеки Тельдрассила."}},faq={{q="Хто дає завдання «Шати Місяця»?",a="Завдання дає Лаурна Морнінґлайт — наставниця жерців, що мешкає в північній будівлі Доланаару на Тельдрассилі.",al={"хто дає шати місяця","де почати шати місяця","дає шати місяця"}},{q="Кому потрібна допомога в цьому дорученні?",a="Вартовій Шаї — захисниці з нічних ельфів, яку поранено під час патрулювання глушини; вона чекає допомоги трохи на південь від Доланаару.",al={"кому допомагати","місце пораненої вартової","де вартова шая"}},{q="Яка магія потрібна, щоб допомогти Вартовій Шаї?",a="Треба зцілювальною магією загоїти рани Вартової Шаї й накласти захисні чари, що зміцнять її витривалість, а тоді повернутися до Доланаару.",al={"які закляття для шаї","як завершити шати місяця","мета шаї"}},{q="Чи може це завдання взяти будь-який клас?",a="Ні. «Шати Місяця» дають лише жерцям нічних ельфів — як одну з перших віх їхнього духовного навчання.",al={"чи лише для жерців шати місяця","вимога класу шат місяця","чи друїди можуть шати місяця"}},{q="Що символізує роба, яку дають у нагороду?",a="Роба від Лаурни Морнінґлайт — знак посвяти: вона означає, що ви сумлінно послужили Елуні й здобули визнане місце серед місцевого жрецтва.",al={"значення роби шат місяця","лор нагороди роби","значення шат місяця"}},{q="Як це завдання пов'язане із завданням «В ім'я Елуни»?",a="«В ім'я Елуни» — вступний заклик навідатися до наставниці в Доланаарі. Воно не обов'язкове, щоб отримати «Шати Місяця», але після їх виконання його вже не можна завершити.",al={"передумова в ім'я елуни","пропущене в ім'я елуни","порядок завдань жерців доланаара"}}},fp="20,354,16.470.0,27.414.0,42.124.0,32.135.0,46.140.0,30.119.0,36.178.0,66.208.0"}
P.entries["quest:5622"] = {n="В ім'я Елуни",s="«В ім'я Елуни» — обряд переходу для юних жерців нічних ельфів, готових вийти з-під затишного гілля Тінедола. За настановою Жриці Шанди послушники спускаються стежкою до Доланаара, щоб шукати подальших настанов і вишколу в Лаурни Морнінґлайт.",h="«В ім'я Елуни» — обряд переходу для юних жерців нічних ельфів, готових вийти з-під затишного гілля Тінедола.",kw={"в ім'я елуни","жрець","шанда","лаурна морнінґлайт","тінедол","доланаар"},ang={["class:Priest"]="Це завдання — ваш перехід від простих послушницьких студій до повноцінного служіння, що виводить вас на шлях до перших освячених шат.",["race:NightElf"]="Сестринство Елуни — духовне серце й історичний провід суспільства калдорей, тож подорож до Доланаара — глибоко традиційна віха для відданих."},sec={{t="Прощання з галявиною",b="Для посвяченого, що служить Елуні в затишному прихистку Алдрассила, навчання починається з простих молитов і захисних заклинань під пильним оком Жриці Шанди. Та відлюдне життя Тінедола не підготує жрицю чи жерця до сум'яття, що охопило ширший світ. Щойно посвячений виявляє тверду віру й дисципліну, Шанда відсилає його тінистою лісовою стежкою до Доланаара — продовжувати науку."},{t="Крок у жрецтво",b="Прибуття до Доланаара — важлива віха в божественному покликанні нічного ельфа. Там чекає Лаурна Морнінґлайт, шанована жриця, якій доручено готувати учнів до випробувань, що постали перед Тельдрассилом. Окрім поглибленої науки місячного чародійства, прихід до Доланаара готує послушника до перших офіційних шат, що засвідчують його становище в Сестринстві Елуни."}},faq={{q="Хто посилає мене в цю подорож?",a="Жриця Шанда, наставниця жерців нічних ельфів у гіллі Алдрассила в Тінедолі, дає вам цю настанову, коли завершено ваше початкове навчання.",al={"хто дає завдання","хто починає в ім'я елуни","де взяти завдання"}},{q="Куди треба йти, щоб знайти Лаурну Морнінґлайт?",a="Лаурна Морнінґлайт мешкає в Доланаарі — першому великому поселенні на південь від брами Тінедолу на Тельдрассилі. Вона в північній будівлі селища.",al={"місце лаурни морнінґлайт","де доланаар","де морнінґлайт"}},{q="Чи може це завдання взяти будь-який клас?",a="Ні. Це завдання призначене саме для молодих жерців нічних ельфів, що роблять перші кроки в Сестринстві й на службі Елуні.",al={"чи лише для жерців","хто може в ім'я елуни","завдання друїда"}},{q="Що буде після розмови з Лаурною Морнінґлайт?",a="Лаурна Морнінґлайт привітає вас і запропонує випробування «Шати Місяця»: воно перевіряє, чи здатні ви захистити й зцілити поранених захисників, перш ніж отримаєте свої перші офіційні жрецькі шати.",al={"що далі","продовження","завдання шати місяця"}},{q="Чи обов'язкове це завдання, щоб продовжити навчання жерця?",a="Це необов'язкове завдання-скерування. Якщо ви самі прийдете до Доланаару, Лаурна Морнінґлайт однаково запропонує навчання й наступні доручення без цього знайомства.",al={"чи обов'язкове в ім'я елуни","чи можна пропустити","необов'язкове завдання"}},{q="Чому для Сестринства так важливо здобути шати?",a="У культурі нічних ельфів облачення — не просто тканина: це священні символи, що позначають офіційне становище, відданість і готовність нести благословення Богині Місяця на служіння своєму народові.",al={"чому роби важливі","значення шат","стан жриці елуни"}}},fp="17,264,17.441.0,26.398.0,29.166.0,50.172.0,30.142.0,50.194.0,52.189.0,55.201.0"}
P.entries["quest:5623"] = {n="В ім'я Світла",s="«В ім'я Світла» — рання віха для жерців-новачків, що навчаються в Долині Нортширу. Жриця Анетта посилає молодого служителя за межі відлюдного абатства до Ґолдшира. Там на нього чекає Жриця Джозетта, щоб поглибити його духовну дисципліну й повести далі шляхом віри у Святе Світло.",h="«В ім'я Світла» — рання віха для жерців-новачків, що навчаються в Долині Нортширу.",kw={"в ім'я світла","жрець","жриця анетта","жриця джозетта","ґолдшир","святе світло"},ang={["class:Priest"]="Цей обряд посвяти з'єднує ваші затишні студії в Нортширі з живою пастирською працею серед мешканців і гарнізонів Лісу Елвінн.",["faction:Alliance"]="Церква Святого Світла — одна з ключових опор Альянсу: вона плекає відданих цілителів, здатних підтримувати захисників на передовій.",["race:Human"]="Для людей Стормвінда звернутися по настанови до жрецтва в Ґолдширі — важливий крок у підтримці моральної та духовної опори королівства."},sec={{t="Крок за межі Нортширу",b="Абатство Нортшира дає новачкам прихисток і початкову науку, але духовний вишкіл у Церкві Святого Світла вимагає служіння просто серед людей. Щойно посвячений показує основи молитви й божественного зцілення, Жриця Анетта посилає його на південь сонячними дорогами до Ґолдшира. Ця подорож знаменує перехід від відлюдного учня до діяльного парафіяльного служителя серед щоденних випробувань мешканців Елвінну."},{t="Наука в Ґолдширі",b="У Корчмі «Лев'яча Гордість» у Ґолдширі Жриця Джозетта дбає про духовні потреби місцевих і наглядає за послушниками, що зростають у вірі. Джозетта будує просто на підвалинах, закладених в абатстві: перевіряє, чи вміє посвячений розраджувати, оберігати вірних і зцілювати поранених. Під її проводом молодий жрець знайомиться з обов'язками, які чекають на служителів Церкви по всьому королівству."}},faq={{q="Хто дає це завдання і кому доповідати?",a="Завдання дає Жриця Анетта в Абатстві Нортшира: вона посилає вас дорогою до Жриці Джозетти в Ґолдширі.",al={"хто дає в ім'я світла","куди здати","куди здати в ім'я світла"}},{q="Чому жерця так рано відсилають із Нортшира?",a="Нортшир дає основи віровчення Святого Світла, але від молодих служителів чекають, що вони швидко почнуть служити справжнім громадам. Ґолдшир — це вже парафія, де послушник може допомагати звичайним містянам і вартовим під проводом Джозетти.",al={"чому ґолдшир","чому покинути абатство нортширу"}},{q="Де в Ґолдширі знайти Жрицю Джозетту?",a="Жриця Джозетта — у Корчмі «Лев'яча Гордість» у Ґолдширі, де вона служить місцевою наставницею жерців.",al={"де жриця джозетта","знайти джозетту","місце джозетти"}},{q="Що буде після зустрічі з Жрицею Джозеттою?",a="Жриця Джозетта одразу випробовує вашу вправність у наступному завданні «Шати Світла»: треба допомогти пораненому вартовому, а тоді отримати обрядові жрецькі шати.",al={"наступне завдання після в ім'я світла","що далі після в ім'я світла"}},{q="Чи це завдання лише для жерців?",a="Так. Це доручення — офіційне духовне навчання в Церкві Святого Світла, і його дають лише послушникам-жерцям.",al={"чи кожен клас може","чи лише для жерців"}},{q="Яку роль Церква Святого Світла відіграє в Елвінні?",a="Церква дає розраду, духовний провід і зцілення містянам і захисникам, які потерпають від дедалі частіших нападів розбійників і звірів по всьому лісу.",al={"роль церкви світла","жерці елвінну"}}},fp="21,329,26.447.0,21.407.0,45.123.0,51.268.0,50.104.0,45.199.0,36.131.0,59.170.0"}
P.entries["quest:5624"] = {n="Шати Світла",s="«Шати Світла» — раннє випробування для жерців-новачків у Ґолдширі, яке дає Жриця Джозетта. Замість абстрактної перевірки віри церква посилає послушника на схід, до Кришталевого Озера, зцілити й зміцнити пораненого Вартового Робертса. Виконаний обов'язок доводить, що учень опанував зцілення, і приносить йому перші офіційні шати, визнані Церквою Святого Світла.",h="«Шати Світла» — раннє випробування для жерців-новачків у Ґолдширі, яке дає Жриця Джозетта.",kw={"шати світла","жрець","жриця джозетта","вартовий робертс","кришталеве озеро","зцілення","ґолдшир"},ang={["class:Priest"]="Цей обряд посвяти з'єднує богослов'я з класів Нортширу зі службою в полі й нагадує: найвище покликання жерця — зберігати життя союзників на передовій зціленням і зміцнювальними оберегами.",["faction:Alliance"]="Поки армія Стормвінда виснажена й відсутня в місцевих селищах, міська варта значною мірою покладається на допомогу церковних учнів, щоб вистояти перед загрозами.",["race:Human"]="Людська культура глибоко шанує Церкву Святого Світла, тож шати, отримані від жриці містечка, — важлива громадська й духовна віха в житті послушника."},sec={{t="Практичне випробування віри",b="За традиціями Церкви Святого Світла новачків рідко підносять лише за знання доктрини. Жриця Джозетта, що навчає послушників, які прибувають до Ґолдшира з Абатства Нортшира, перевіряє, чи вміє посвячений володіти божественною силою на ділі, перш ніж дати йому офіційне церковне визнання. Коли до містечка доходить звістка, що Вартовий Робертс лежить поранений біля озера на схід від Ґолдшира, Джозетта обертає буденне нещастя на випробування й посилає молодого жерця доглянути його."},{t="Опора королівства",b="Завдання вимагає більшого, ніж просто стулити рану: послушник має загоїти рани вартового відновлювальними молитвами й зміцнити його витривалість благословенням стійкості. У ці неспокійні часи, коли військо Стормвінда розтягнуте до краю, а місцеві гарнізони знемагають від кобольдів і бандитів, Джозетта наголошує: обов'язок жрецтва безпосередньо стосується виживання на війні. Повернутий до служби Вартовий Робертс одразу стає в пригоді містечку, а посвячений доводить, що здатен підтримувати захисників під ударами."},{t="Шати ордену",b="Повернувшись до Корчми «Лев'яча Гордість» після лікування солдата, молодий жрець отримує перше офіційне вбрання. Ці шати — знак схвалення й братерства з боку жрецтва Стормвінда. Носити їх у подальшому навчанні не обов'язково, та вони стоять зримим свідченням того, що церква визнає їхнього власника висвяченим служителем Святого Світла."}},faq={{q="Де знайти Вартового Робертса?",a="Вартовий Робертс — трохи на схід від Ґолдширу, біля берегів Кришталевого Озера. Він відпочиває край дороги біля води, оговтуючись від ран, отриманих на варті.",al={"місце вартового робертса","де вартовий робертс","знайти робертса"}},{q="Які закляття потрібні, щоб виконати це завдання?",a="Треба підлікувати Вартового Робертса закляттям «Мале зцілення» (Ранг 2), щоб відновити його здоров'я, а тоді накласти «Слово Сили: Стійкість», щоб зміцнити його витривалість, і повернутися до Жриці Джозетти.",al={"які закляття потрібні","які закляття на робертса","як зцілити робертса"}},{q="Хто така Жриця Джозетта?",a="Жриця Джозетта — наставниця жерців Церкви Святого Світла в Корчмі «Лев'яча Гордість» у Ґолдширі. Вона опікується молодими послушниками, що покинули Абатство Нортшира, навчаючи їх практичного служіння й божественної магії.",al={"лор джозетти","жриця джозетта ґолдшир","хто дає шати світла"}},{q="Чому Церква дає роби за це доручення?",a="Роби — зовнішній знак того, що Церква Святого Світла офіційно схвалює послушника й підтримує його служіння. Виконавши це практичне зцілення, новачок доводить, що має досить уміння й дисципліни, щоб носити церковні шати.",al={"чому шати світла","лор роби жерця","значення роб церкви"}},{q="Чи можуть інші класи виконати це завдання?",a="Ні. Це завдання — частина вступного ланцюжка для жерців Альянсу, які опанували основні молитви зцілення й захисту.",al={"чи лише для жерців шати світла","чи паладини можуть шати світла","клас жерця"}},{q="Що буде після завдання «Шати Світла»?",a="«Шати Світла» завершують ранню посвяту жерців 4-го рівня в Ґолдширі. Одразу наступного скерування немає, але Жриця Джозетта та інші наставники по всьому королівству пропонуватимуть глибше навчання й нові випробування, коли ви набиратиметеся досвіду.",al={"що після шат світла","продовження шат світла"}}},fp="21,390,25.489.0,20.527.0,22.402.0,31.190.0,48.185.0,25.224.0,49.260.0,38.157.0,52.271.0"}
P.entries["quest:5625"] = {n="Шати Світла",s="«Шати Світла» — ранній обряд переходу для молодих дворфійських жерців у Дун Мороґу. За вказівкою наставника жерців Максана Анвола з Хараноса, посвячуваний має допомогти пораненому горянину одразу за містом, щоб заслужити свої шати.",h="«Шати Світла» — ранній обряд переходу для молодих дворфійських жерців у Дун Мороґу.",kw={"жрець","шати","світло","анвол","харанос","дольф","горянин"},ang={["class:Priest"]="Цей обряд переходу знаменує ваш шлях від неперевіреного новачка до визнаного служителя Святого Світла, якому довіряють життя товаришів на передовій.",["faction:Alliance"]="Святе Світло — духовний хребет Альянсу, що дарує розраду й зцілення на полі бою воїнам, які тримають оборону проти трогів, звірів і гіршого.",["race:Dwarf"]="Горяни Айронфорджа стережуть небезпечні перевали Дун Мороґу; турбота про поранених розвідників, як-от Дольф, зміцнює життєво важливий зв'язок між дворфійською вірою та військовою обороною."},sec={{t="Нагальне випробування",b="За традицією, послушники Святого Світла проходять урочисті випробування, щоб довести, що гідні носити церковні шати. Проте в Хараносі наставник жерців Максан Анвол цінує практичний результат вище за церемонію. Коли місцеві патрулі ледве стримують трогів і диких звірів, теоретичні іспити відходять на другий план, бо справжні захисники стікають кров'ю на снігу."},{t="Допомога горянам",b="Щоб заслужити шати, молодих жерців посилають на південь від міста знайти Горянина Дольфа, пораненого на службі. Зцілюючи рани Дольфа відновлювальними молитвами й зміцнюючи його тіло Словом Сили: Стійкість, посвячуваний доводить, що його відданість напряму обертається виживанням захисників Айронфорджа."},{t="Шати Церкви",b="Коли горянину надано допомогу, Максан Анвол вручає послушнику офіційні шати. Окрім теплого захисту від холоду Дун Мороґу, ці шати слугують видимим знаком сану, сповіщаючи пораненим мандрівникам і місцевій варті, що поряд є служитель Світла, готовий допомогти."}},faq={{q="Яка мета цього завдання?",a="Завдання перевіряє, як жрець-новачок застосовує на практиці свої перші закляття. Замість книжного іспиту наставник Максан Анвол посилає вас знайти пораненого Горянина Дольфа на південь від Хараноса, загоїти його рани й зміцнити його витривалість «Словом сили: Стійкість».",al={"що робити","мета шат світла"}},{q="Хто такий Максан Анвол?",a="Максан Анвол — дворфійський наставник жерців у Хараносі. Практичний і невибагливий, він опікується молодими жерцями, що приходять із Долини Холодного Хребта, і наголошує на прямій, рятівній користі Світла, а не на суворому формальному обряді.",al={"хто такий максан анвол","жрець-тренер хараноса"}},{q="Хто такий Горянин Дольф?",a="Дольф — горянин Айронфорджа, що служить біля Хараноса й зазнав поранень у патрулі. Він чекає на південь від поселення — на ньому новачки й складають практичний іспит: загоюють його рани й дарують Стійкість.",al={"місце дольфа","хто такий дольф"}},{q="Чому жрець отримує за це доручення особливі шати?",a="Облачення й роби наочно показують відданість і становище служителя Святого Світла. І для громади, і для вояків жрець у робі — одразу видно, що це той, хто може дати раду смертельним ранам і дати духовну настанову.",al={"чому жерцям шати","лор жрецьких шат"}},{q="Чому дворфи шанують Святе Світло?",a="Дворфи Айронфорджа перейняли вчення Святого Світла завдяки століттям тісного культурного обміну й союзу з людьми Лордерона й Стормвінда. Дворфійські жерці поєднують традиційну гірську завзятість із побожною шаною до чеснот Світла — милосердя, стійкості й захисту.",al={"лор світла дворфів","чи дворфи вірять у світло"}},{q="Що буде після цього випробування?",a="Максан Анвол заохочує щойно висвяченого послушника вирушати в світ, вправлятися в бойових і допоміжних закляттях і випробовувати свої сили разом з іншими мандрівниками. Складніші випробування в церкві чекають, коли жрець набереться досвіду й сили.",al={"що після шат світла","наступне випробування жерця"}}},fp="21,246,15.353.0,23.345.0,19.304.0,34.274.0,19.237.0,24.223.0,58.268.0,38.304.0,41.237.0"}
P.entries["quest:5626"] = {n="В ім'я Світла",s="«В ім'я Світла» знаменує для молодого жерця обряд переходу від відлюдних тренувальних земель Долини Холодного Хребта до ширших просторів Дун Мороґу. За настановою Бранстока Калдера новіціїв посилають гірським тунелем до Хараноса — продовжити навчання в наставника жерців Максана Анвола. Це знак, що послушник готовий узяти на себе справжню відповідальність і заслужити традиційні шати свого покликання.",h="«В ім'я Світла» знаменує для молодого жерця обряд переходу від відлюдних тренувальних земель Долини Холодного...",kw={"жрець","світло","калдер","анвол","харанос","холодний хребет","шати"},ang={["class:Priest"]="Це завдання — віха для молодих жерців: офіційний випуск із базового вишколу в дієве служіння і здобуття перших шат.",["race:Dwarf"]="Дворфійське жрецтво поєднує духовну відданість із практичною витривалістю, посилаючи послушників просто від вогнищ Холодного Хребта на суворі крижані вітри Дун Мороґу."},sec={{t="Залишаючи Ковадло",b="У відлюдній колисці Долини Холодного Хребта дворфійські жерці починають навчання під пильним оком наставників, як-от Бранстока Калдера. Щойно новачок виявляє достатню відданість і розуміння святої магії, його попередній вишкіл добігає кінця. Замість тримати учнів під захистом Анвілмару, Калдер спрямовує обдарованих за гори, до Хараноса, де потреби служіння та оборони переплітаються з щоденними турботами мешканців Дун Мороґу."},{t="Крок до Хараноса",b="Щоб дістатися Хараноса, треба пройти тунелем Перевалу Холодного Кряжа у продуті вітрами сніги центрального Дун Мороґу. У селищі чекає Максан Анвол — старший жрець, що веде учнів далі за прості молитви. Анвол твердо переконаний: відданість Святому Світлу вимагає рівною мірою моральної чистоти, тілесного гарту й незламної волі. Послушникам, які доведуть свою рішучість під його опікою, Анвол готується вручити перші офіційні шати сану."}},faq={{q="Хто посилає мене в цю подорож?",a="Брансток Калдер, дворфійський наставник жерців в Анвілмарі в Долині Холодного Хребта, посилає вас до Хараноса, щойно ви виявите досить хисту до Святого Світла, щоб навчатися далі.",al={"хто дає завдання","бранстог калдер"}},{q="Хто такий Максан Анвол?",a="Максан Анвол — наставник жерців у гірському селищі Харанос. Він веде жерців, що зростають, і вчить їх гартувати побожність фізичною витривалістю й силою духу.",al={"максан анвол лор","хто такий максан анвол","тренер жерців хараноса"}},{q="Що буде, коли дістатися Максана Анвола?",a="Максан Анвол пропонує довести свою гідність у завданні «Шати Світла»: допомогти пораненим місцевим, а тоді отримати свої перші офіційні жрецькі роби.",al={"наступне завдання","що після в ім'я світла","шати світла"}},{q="Чому жерцям доводиться так рано покидати Долину Холодного Хребта?",a="Долина Холодного Хребта дає лише основи бою й заклинань. Більші громади на кшталт Хараноса стикаються з нагальними господарськими й оборонними загрозами, і там молоді жерці здобувають справжній досвід служіння своєму народові.",al={"чому покидати холодний хребет","чому покидати анвілмар","чому до хараноса"}},{q="Чи отримують таке саме завдання жерці-люди?",a="Жерці-люди в Лісі Елвінн проходять рівноцінний обряд посвяти з тією самою назвою: Жриця Анетта в Нортширі посилає їх до Жриці Джозетти в Ґолдширі.",al={"в ім'я світла людей","версія нортширу"}},{q="Чим тут відрізняється дворфійський погляд на Світло?",a="Дворфи разом із побожністю надають великого значення фізичній силі, волі й практичній витривалості. Як зауважує Максан Анвол, служіння Світлу серед морозних гірських вершин вимагає сили тіла не менше, ніж віри.",al={"вірування дворфів про світло","дворфи і світло"}}},fp="21,430,17.478.0,22.495.0,30.192.0,19.195.0,40.178.0,49.222.0,41.181.0,51.211.0"}
P.entries["quest:5627"] = {n="Зорі Елуни",s="«Зорі Елуни» — важлива віха в єднанні молодого жерця нічних ельфів із Богинею Місяця. Довівши відданість своєму народові, послушники отримують запрошення до Храму Місяця в Дарнасусі, щоб вивчити священні мистецтва, відомі лише Сестринству Елуни.",h="«Зорі Елуни» — важлива віха в єднанні молодого жерця нічних ельфів із Богинею Місяця.",kw={"зорі елуни","жриця алатея","храм місяця","сестринство елуни","Зоряні Скалки","жрець","дарнасус"},ang={["class:Priest"]="Цей обряд позначає розбіжність між жерцями-калдореями та жерцями інших рас: він відкриває зоряні закляття, які дарує лише Богиня Місяця.",["faction:Alliance"]="Жерці людей і дворфів проповідують відданість Святому Світлу, а віра нічних ельфів в Елуну приносить у лави Альянсу давню, самобутню небесну магію.",["race:NightElf"]="Для калдореїв служіння Елуні невіддільне від громадського й культурного життя; відгукнутися на заклик Сестринства — значить подорослішати на службі Тельдрассилу."},sec={{t="Обряд відданості",b="Жерці нічних ельфів черпають святу силу не з широких філософських засад Світла, як люди й дворфи, а просто від своєї богині — Елуни. Коли послушник виявляє непохитну відданість на службі краю, Сестринство в Дарнасусі визнає її. Покликаного до Храму Місяця жерця вважають гідним глибшого єднання й відкривають йому священні закляття, що передаються вже тисячі років."},{t="Дари Богині Місяця",b="Відгукнувшись на поклик Жриці Алатеї, посвячуваний отримує безпосередні настанови у святих таїнствах, властивих лише його народові, — як-от Зоряні Скалки. Ці закляття спрямовують сяйливий небесний гнів і благодать Білої Пані. Отримані настанови означають, що послушник переріс початкове навчання й готовий вирушити за захисний покров Тельдрассилу в ім'я Елуни."}},faq={{q="Яка мета цього завдання?",a="«Зорі Елуни» — це офіційне визнання послушника Сестринством Елуни. Після виконання Жриця Алатея навчає молодого жерця расових заклять нічних ельфів, як-от «Зоряні Скалки», — знак того, що він зростає як обрана посудина Богині Місяця.",al={"завдання зорі елуни","що я отримаю","навіщо це завдання"}},{q="Хто дає завдання «Зорі Елуни»?",a="Завдання завершують у Жриці Алатеї — висвяченої провідниці Сестринства Елуни у величному Храмі Місяця в Дарнасусі.",al={"хто дає зорі елуни","дає зорі елуни","де алатея"}},{q="Чому це завдання лише для нічних ельфів?",a="Обряди, яких навчають у цьому завданні, належать саме Сестринству Елуни — давньому жрецтву, що опікується вірою нічних ельфів. На відміну від інших жрецтв Альянсу, що вивчають всеохопне Святе Світло, жерці калдорей черпають свою особливу магію безпосередньо зі спілкування з Елуною.",al={"чи люди можуть це","чи лише для нічних ельфів","хто може зорі елуни"}},{q="Куди веде це завдання в історії жерця?",a="Це завдання одразу йде після «Повернення додому», яке повертає жерця-початківця, що допомагав по всьому Тельдрассилу, до столиці — по подальші настанови в Храмі Місяця.",al={"що перед зорями елуни","передумова зорі елуни","завдання повернення додому"}},{q="Яку магію Елуна дарує своїм жерцям?",a="Жерці, віддані Елуні, сплітають місячне світло, сяйво зірок і тінь. Особливі обряди на кшталт «Зоряних Скалок» дають калдорейським вірним змогу скликати на ворогів розпечений небесний вогонь, поєднуючи божественний суд із зоряним гнівом.",al={"закляття елуни","магія жриць нічних ельфів","лор Зоряних Скалок"}},{q="Де в Дарнасусі це відбувається?",a="У Храмі Місяця — сяйливому мармуровому святилищі, що височіє над південним кварталом Дарнасуса й слугує релігійним серцем народу калдорей.",al={"місце зорі елуни","де жриця алатея","місце храму місяця"}}},fp="14,264,18.458.0,25.404.0,34.271.0,26.150.0,44.284.0,55.200.0,52.222.0,40.184.0"}
P.entries["quest:5628"] = {n="Повернення додому",s="«Повернення додому» — заклик до молодих жерців нічних ельфів, що забрели аж до людських земель Лісу Елвінн. Жриця Джозетта в Ґолдширі передає нагальне послання з Дарнасуса: новачкові слід повернутися до Храму Місяця, щоб продовжити духовне навчання під проводом Жриці Алатеї.",h="«Повернення додому» — заклик до молодих жерців нічних ельфів, що забрели аж до людських земель Лісу Елвінн.",kw={"повернення додому","жриця джозетта","ґолдшир","ліс елвінн","жриця алатея","храм місяця","жрець"},ang={["class:Priest"]="Кожен жрецький орден має глибоке коріння в традиції; для послушників-калдореїв справжнє просування в місячних обрядах можуть схвалити лише старші жриці Храму Місяця.",["faction:Alliance"]="Взаємна гостинність Церкви Святого Світла в Елвінні та Сестринства Елуни в Дарнасусі показує, як міцнішають узи співпраці між расами Альянсу.",["race:NightElf"]="Мандрувати за море до земель молодих рас — шлях сміливий, але поклик Тельдрассилу й благословення Елуни завжди повертають калдореїв до їхніх священних прихистків."},sec={{t="Звістка в Ґолдширі",b="Нічні ельфи в Лісі Елвінн — рідкісне видовище, і молодий послушник, що мандрує людськими поселеннями, одразу привертає увагу. Коли такий жрець прибуває до Ґолдшира, Жриця Джозетта зустрічає його привітно — і з новиною. Сестра Елуни перетнула континенти, шукаючи молодого вірянина, з нагальним наказом від Храму Місяця: час повертатися до Калімдору й іти далі шляхом свого покликання."},{t="Поклик Храму",b="У серці Дарнасуса височіє Храм Місяця — осердя віри й проводу нічних ельфів. Жриця Алатея та Верховна Жриця Тіранда Віспервінд наглядають за навчанням у Сестринстві й пильно стежать за своїми учнями, навіть коли цікавість заносить їх за море. Посвячуваних, що повернулися, зустрічають із материнською турботою й одразу беруться до глибшого вивчення небесних таїнств Богині Місяця."}},faq={{q="Чому жерця нічних ельфів кличуть із людських земель?",a="Молоді жерці нічних ельфів, що вирушають до Східних Королівств, і далі пов'язані зі своїм священним орденом на Тельдрассилі. Жриця Алатея стежить за їхніми успіхами й кличе назад до Храму Місяця, щойно вони готові вчитися вищих обрядів Елуни.",al={"чому мене кличуть назад","чому повернення додому","завдання жерця ґолдшир"}},{q="Хто така Жриця Джозетта?",a="Жриця Джозетта — наставниця жерців-людей у Корчмі «Лев'яча Гордість» у Ґолдширі. Вона служить Святому Світлу, але шанує послушників-калдорей, що приходять у гості, і стає посередницею, коли посланці з Дарнасуса шукають своїх заблукалих родичів.",al={"хто дає повернення додому","наставниця жерців ґолдшир","жриця джозетта"}},{q="Хто така Жриця Алатея?",a="Жриця Алатея — старша Сестра Елуни, що навчає послушників у Храмі Місяця в Дарнасусі. Тісно співпрацюючи з Верховною Жрицею Тірандою Віспервінд, вона стежить за зростанням і духовною відданістю жерців-початківців нічних ельфів.",al={"хто така алатея","наставниця жерців у храмі","жриця алатея"}},{q="Що буде, коли повернутися до Дарнасуса?",a="Коли ви доповідаєте Жриці Алатеї в Храмі Місяця, вона вітає вас удома й відкриває наступне духовне доручення — завдання «Зорі Елуни», що глибше занурює в священну силу, яку дарує богиня.",al={"що далі","наступне завдання після повернення додому","продовження завдання"}},{q="Чим це відрізняється від звичайного шляху навчання?",a="Це завдання — запасне скерування для жерців нічних ельфів, які вирішили набиратися досвіду в людських землях, як-от у Лісі Елвінн, а не лишатися на Тельдрассилі. Воно повертає їх до расових наставників у Дарнасусі, щоб відкрити особливі жрецькі здібності їхньої раси.",al={"чи всі жерці це роблять","чи це завдання обов'язкове","завдання жерця елвінн"}},{q="Як посланець знайшов послушника аж у Лісі Елвінн?",a="Жриця із Сестринства подолала шлях від Дарнасуса до Східних Королівств і лишила звістку наставникам Альянсу на кшталт Жриці Джозетти в Ґолдширі, щоб ті пильнували мандрівного новачка й скерували його додому.",al={"як вони дізналися де я","хто вистежив мене до ґолдшира"}}},fp="14,308,19.426.0,22.452.0,58.256.0,25.249.0,25.244.0,42.232.0,51.296.0,67.225.0"}
P.entries["quest:5629"] = {n="Повернення додому",s="«Повернення додому» — обряд посвяти для молодих жерців нічних ельфів, що служать на Тельдрассилі. Коли новачки доведуть свою вартість у дикій глушині, їх кличуть до величного Храму Місяця в Дарнасусі, щоб вони постали перед Жрицею Алатеєю та Верховною Жрицею Тірандою Віспервінд.",h="«Повернення додому» — обряд посвяти для молодих жерців нічних ельфів, що служать на Тельдрассилі.",kw={"повернення додому","жриця алатея","тіранда віспервінд","лаурна морнінґлайт","доланаар","храм місяця","жрець"},ang={["class:Priest"]="Цей заклик позначає перехід жерця від звичайного лісового послушника до офіційного служителя Сестринства Елуни, що звітує просто Дарнасусу.",["race:NightElf"]="Для калдореїв відгукнутися на поклик до Храму Місяця — значить поєднатися з корінням своєї культури й постати під пильним поглядом Верховної Жриці Тіранди Віспервінд."},sec={{t="Виклик із Дарнасуса",b="Жерці, що в перші дні служби доглядають поранених і очищають скверну довкола Доланаара, швидко привертають увагу Сестринства Елуни. Наставниця Лаурна Морнінґлайт перестріває найздібніших посвячуваних і пояснює, що Жриця Алатея надіслала звістку з проханням про зустріч. Допомагати місцевим поселенням важливо, але кожен вірянин мусить плекати своє єднання з Місячною Матір'ю й відгукуватися на вищий поклик віри."},{t="У Храмі Місяця",b="Шлях веде за межі гілля Тельдрассилу у велике серце Дарнасуса — до Храму Місяця. Святилище, що здіймається над містом у лагідному сяйві благодаті Елуни, — і найвищий дім молитви, і духовна столиця калдореїв. Запрошення знову ввійти в ці зали означає, що жерця вже вважають не просто недосвідченим учнем, а посвячуваним, якого визнає сам провід жрецтва."},{t="Прихильність Тіранди й Алатеї",b="Коли мандрівники постають перед Жрицею Алатеєю, вона вітає їх тепло, по-материнському. Алатея поділяє пильну гордість проводу: і вона, і Верховна Жриця Тіранда Віспервінд радіють щоразу, коли посвячувані вирушають у непевний зовнішній світ і повертаються неушкодженими. Це повернення додому відкриває глибші священні випробування під безпосереднім наставництвом Алатеї."}},faq={{q="Хто дає завдання «Повернення додому»?",a="Лаурна Морнінґлайт, наставниця жерців у Доланаарі на Тельдрассилі, дає завдання, коли молодий жрець нічних ельфів набуде досить вишколу й досвіду.",al={"хто дає повернення додому","хто видає завдання повернення додому","завдання лаурни морнінґлайт"}},{q="Де знайти Жрицю Алатею?",a="Жриця Алатея — у Храмі Місяця в Дарнасусі, ближче до центру столиці нічних ельфів на Тельдрассилі.",al={"де алатея","де знайти жрицю алатею","жриця храму місяця"}},{q="Чому Жриця Алатея хоче мене бачити?",a="Старійшини й провід Сестринства Елуни помітили вашу віддану службу в глушині Тельдрассилу. Алатея вважає, що ви готові до глибшого навчання й вищих духовних доручень.",al={"чому кличуть до дарнасуса","чому йти до храму місяця"}},{q="Чи може це завдання взяти будь-який клас?",a="Ні. «Повернення додому» створене саме для жерців нічних ельфів як частина їхнього раннього класового розвитку й священної посвяти у вищі обов'язки Сестринства.",al={"чи повернення додому для всіх класів","чи можуть друїди взяти повернення додому","завдання лише для жерців"}},{q="Яке завдання йде після «Повернення додому»?",a="Коли ви доповідаєте Жриці Алатеї й завершуєте це доручення, вона довіряє вам наступне завдання — «Зорі Елуни».",al={"що після повернення додому","продовження повернення додому","наступне завдання"}},{q="Яке значення має Храм Місяця для нічних ельфів?",a="Храм Місяця — головний осередок шанування богині Елуни й правлячий дім, звідки Верховна Жриця Тіранда Віспервінд веде і Сестринство, і народ калдорей.",al={"переказ про храм місяця","місячний храм дарнасуса"}}},fp="14,291,24.448.0,29.439.0,32.370.0,36.170.0,35.143.0,42.204.0,30.165.0,34.127.0,61.204.0"}
P.entries["quest:563"] = {n="Переведення",s="«Переведення» — кульмінація зусиль Лейтенанта Фаррена Орінелля вирватися зі свого посту в Саутшорі. Склавши перебільшений звіт про свої подвиги проти прибережних наг, Фаррен посилає шукача пригод аж до Фортеці Стормвінда, щоб передати документи своєму колишньому наставникові, Майорові Семюелсону.",h="«Переведення» — кульмінація зусиль Лейтенанта Фаррена Орінелля вирватися зі свого посту в Саутшорі.",kw={"переведення","фаррен орінелль","майор семюелсон","фортеця стормвінда","саутшор","завдання"},ang={["faction:Alliance"]="Це доручення показує буденну бюрократичну політику війська Альянсу, де далекі прикордонні гарнізони на кшталт Саутшора стикаються з затишними амбіціями офіцерів, що прагнуть повернутися до Стормвінда.",["race:Human"]="Доставка показує контраст між обложеними людськими біженцями й захисниками, що тримають оборону в Лордероні, і політичними хитрощами у високих залах Фортеці Стормвінда."},sec={{t="Квиток із Саутшора",b="Лейтенант Фаррен Орінелль і не приховує зневаги до свого посту в Передгір'ї Гілсбреда. Застряглий у Саутшорі, далеко від зручностей столиці й під суворим наглядом Маршала Редпата, Фаррен проводить дні, вигадуючи, як перевестися назад на південь. Приписавши собі очищення околиць від наг Кинджалоспинів, він сподівається постати незамінним, загартованим у боях офіцером, гідним підвищення."},{t="Зв'язки у Фортеці",b="Щоб домогтися переведення, не викликавши підозр Маршала Редпата, Фаррен цілком оминає місцевий ланцюг командування. Натомість він покладається на особисті зв'язки з Майором Семюелсоном — старшим офіцером у Фортеці Стормвінда, який колись був його наставником. Звіт, вручений просто в руки Семюелсонові, гарантує, що нібито здобуті звершення Фаррена потраплять на стіл тому, хто має владу переводити особовий склад гарнізонів."},{t="Бюрократія в дії",b="Отримавши досьє у Фортеці Стормвінда, Майор Семюелсон стримано схвалює ініціативу свого колишнього учня щодо загрози наг. Проте військова бюрократія меле повільно. Замість негайно видати наказ про переведення, Семюелсон лише обіцяє розглянути звіт під час звичайного кадрового перегляду наступного місяця, і доля Фаррена в Саутшорі так і висить у повітрі."}},faq={{q="Чому Фаррен Орінелль хоче переведення?",a="Лейтенант Фаррен Орінелль ненавидить службу в Саутшорі, вважаючи віддалену північну заставу нудною, небезпечною й негідною себе. Він прагне повернутися до відносної розкоші й безпеки Стормвінда й хоче скористатися звітами про наг, щоб обґрунтувати переведення.",al={"чому залишити саутшор","мотив фаррена","чому фаррен хоче піти"}},{q="Хто такий Майор Семюелсон?",a="Майор Семюелсон — високопоставлений офіцер у Фортеці Стормвінда, що відповідає за призначення в міській варті. До теперішньої посади він був наставником Лейтенанта Фаррена Орінелля на початку його служби в столиці.",al={"хто такий семюелсон","переказ про семюелсона"}},{q="Чому Фаррен не може доставити звіт сам?",a="Фаррен на дійсній службі в Саутшорі й не може покинути пост без дозволу. До того ж він намагається оминути свого безпосереднього командира, Маршала Редпата, який, найпевніше, заблокував би своєкорисливе прохання про переведення.",al={"чому я маю доставити звіт","чому сам не доставить"}},{q="Чи справді Фаррен сам переміг наг?",a="Ні. Фаррен посилав шукачів пригод убивати наг Кинджалоспинних на Східному Побережжі, а тоді використав їхній успіх у звіті на підтримку свого прохання про переведення.",al={"чи фаррен убив наг","правда у звіті фаррена"}},{q="Чи справді Фаррена переводять назад до Стормвінда?",a="Не одразу. Майор Семюелсон обіцяє лише розглянути звіт на наступному місячному перегляді кадрів. Фаррен лишається в Саутшорі на невизначений час, поки повільно крутяться жорна військової бюрократії королівства.",al={"чи фаррена переведуть","чи спрацює переведення"}},{q="Де знайти Майора Семюелсона?",a="Майор Семюелсон — у Фортеці Стормвінда, твердині в серці Стормвінда, де засідають вище командування й регентська рада.",al={"де семюелсон","де майор семюелсон"}}},fp="12,312,26.432.0,16.435.0,19.386.1,45.274.0,23.217.0,44.226.0,44.157.0,55.245.1,33.140.0"}
P.entries["quest:5630"] = {n="Повернення додому",s="«Повернення додому» — заклик до мандрівних жерців нічних ельфів, що діють далеко від Калімдору, серед засніжених скель Дун Мороґа. Дворфійський наставник жерців Максан Анвол передає новачкові наказ повернутися до Храму Місяця в Дарнасусі й з'явитися до Жриці Алатеї.",h="«Повернення додому» — заклик до мандрівних жерців нічних ельфів, що діють далеко від Калімдору, серед...",kw={"повернення додому","максан анвол","харанос","дун мороґ","жриця алатея","храм місяця","жрець"},ang={["class:Priest"]="Цей обряд посвяти знову пов'язує мандрівних послушників із проводом Сестринства Елуни, щоб відданість Богині Місяця лишалася непохитною навіть у далеких мандрах.",["race:NightElf"]="Для калдорея, що терпить крижані вітри Дун Мороґа, цей заклик — бажане повернення до знайомих святилищ і споконвічних лісів Тельдрассилу."},sec={{t="Заклик через море",b="Нічні ельфи, що вирішили почати свої пригоди поруч із союзниками-дворфами, стикаються з пекучим холодом Дун Мороґа — це вам не спокійні ліси Тельдрассилу. У Хараносі дворфійський наставник жерців Максан Анвол відзначає стійкість ельфа й передає нагальне послання: тут проходила жриця Елуни, що шукала його, з наказом із Дарнасуса негайно повертатися."},{t="Храм Місяця",b="Дорога веде назад до священного гілля Тельдрассилу, просто до Храму Місяця. Там Жриця Алатея знову приймає мандрівника в лоно Сестринства Елуни. З полегшею бачачи, що ще один вірянин неушкодженим повернувся з чужих земель, Алатея швидко готує жерця до наступних обрядів відданості, починаючи із Зір Елуни."}},faq={{q="Хто дає мені це завдання?",a="Повідомлення передає вам Максан Анвол — дворфійський наставник жерців у Хараносі в Дун Мороґу. Він зауважує, що нещодавно тут проходила інша жриця нічних ельфів, яка вас шукала.",al={"хто дає завдання","хто починає повернення додому","максан анвол"}},{q="Куди треба йти, щоб його виконати?",a="Треба повернутися до Дарнасуса на острові Тельдрассил на півночі Калімдору. Жриця Алатея чекає на вас у Храмі Місяця.",al={"де здати завдання","де жриця алатея","куди йти"}},{q="Чому Храм Місяця кличе мене назад?",a="Жриця Алатея й Верховна Жриця Тіранда Віспервінд стежать за зростанням молодих послушників. Алатея хоче переконатися, що ви в безпеці, послухати про ваші мандри під опікою Елуни й розпочати наступний етап вашого духовного навчання — «Зорі Елуни».",al={"чому повернення додому","чому кличуть жерців"}},{q="Що буде після розмови з Жрицею Алатеєю?",a="Коли ви доповідаєте про повернення, Жриця Алатея дає завдання «Зорі Елуни», продовжуючи ваші основні обряди жерця калдорей.",al={"наступне завдання","що далі"}},{q="Звідки нічний ельф у Дун Мороґу на 10-му рівні?",a="Шукачі пригод із нічних ельфів часто перепливають кораблем із Темного Узбережжя до Гавані Менетіл у Східних Королівствах, щоб дослідити землі Альянсу чи мандрувати разом із товаришами-дворфами й гномами.",al={"чому дун мороґ","нічний ельф в айронфорджі"}},{q="Чи доступне це завдання іншим расам?",a="Ні, це завдання призначене саме для жерців нічних ельфів, що навчаються на чужині в дворфійських землях, — воно скеровує їх назад до культурного й духовного дому в Дарнасусі.",al={"чи дворфи можуть взяти повернення додому","хто може взяти це завдання"}}},fp="14,279,24.419.0,22.379.0,27.196.0,37.143.0,46.259.0,51.143.0,51.187.0,39.174.0"}
P.entries["quest:5631"] = {n="Повернення додому",s="«Повернення додому» — жрецьке завдання Альянсу, що кличе обдарованих послушників нічних ельфів, які мандрують чужими краями, назад на Тельдрассил. Брат Джошуа в людських землях передає звістку: Жриця Алатея відкликає молодого жерця до Храму Місяця в Дарнасусі, щоб навчити його глибших таїнств Елуни.",h="«Повернення додому» — жрецьке завдання Альянсу, що кличе обдарованих послушників нічних ельфів, які мандрують...",kw={"повернення додому","брат джошуа","жриця алатея","храм місяця","стормвінд","сестринство елуни","жрець"},ang={["class:Priest"]="Це завдання зміцнює братерство між Церквою Святого Світла й Сестринством Елуни й позначає мить, коли молодий послушник повертається до свого народу, щоб опанувати самобутні обряди калдореїв.",["faction:Alliance"]="Злагоджена співпраця Брата Джошуа у Східних Королівствах і жриць у Дарнасусі показує духовну дипломатію, що тримає Альянс єдиним.",["race:NightElf"]="Для жерців нічних ельфів, що жили серед людей чи дворфів за морем, ця проща — священне повернення додому, до святилищ Тельдрассилу."},sec={{t="Заклик через моря",b="Жерці нічних ельфів часом мандрують до людських володінь, як-от Стормвінда, щоб розділити духовне братерство з Церквою Святого Світла, але найглибші узи пов'язують їх із Сестринством Елуни. Коли Брат Джошуа повідомляє послушникові, що його шукав посланець нічних ельфів, це означає, що час ранніх мандрів скінчився. Рідний храм кличе його до глибшого навчання під проводом найближчого кола Верховної Жриці Тіранди Віспервінд."},{t="Храм Місяця",b="Повернувшись через моря до Дарнасуса, мандрівник потрапляє просто до святині Храму Місяця. Жриця Алатея тепло вітає послушника й радіє, що він безпечно пройшов неспокійним світом. Щасливе повернення молодих учнів тішить і Алатею, і Тіранду, але водночас воно — пролог до вимогливіших духовних випробувань."}},faq={{q="Чому Брат Джошуа дає настанови жерцеві нічних ельфів?",a="Брат Джошуа служить Церкві Святого Світла в людських землях, де молоді жерці Альянсу часто навчаються пліч-о-пліч. Сестра Елуни навідалася до нього саме для того, щоб передати звістку, яка кличе вас назад до Дарнасуса, тож Джошуа й переказує цей заклик.",al={"чому брат джошуа","брат джошуа і нічний ельф","хто посилає мене додому"}},{q="Хто така Жриця Алатея?",a="Жриця Алатея — старша членкиня Сестринства Елуни в Храмі Місяця в Дарнасусі. Тісно співпрацюючи з Верховною Жрицею Тірандою Віспервінд, вона опікується навчанням і зростанням обдарованих жерців нічних ельфів.",al={"жриця алатея","алатея дарнасус","хто така алатея"}},{q="Що буде, коли дістатися Храму Місяця?",a="Коли ви доповідаєте Жриці Алатеї, що щасливо прибули, вона вітає вас удома й починає наступний обряд посвяти — завдання «Зорі Елуни», що поглиблює вашу єдність із Богинею Місяця.",al={"завдання після повернення додому","що далі","завдання зірки елуни"}},{q="Чи може будь-яка раса Альянсу виконати це завдання?",a="Цей заклик призначений для жерців нічних ельфів, що забрели далеко від Калімдору на початку навчання. Він повертає їх на прабатьківщину вивчати расові жрецькі традиції під проводом Сестринства Елуни.",al={"чи це лише для нічних ельфів","чи люди можуть взяти повернення додому","хто може взяти повернення додому"}},{q="Де розташований Храм Місяця?",a="Храм Місяця стоїть у південному кварталі Дарнасуса на гіллі Тельдрассилу. Це і духовне серце культури нічних ельфів, і осідок влади Верховної Жриці Тіранди Віспервінд.",al={"де храм місяця","де знаходиться храм","де алатея"}},{q="Чому Алатея згадує Тіранду Віспервінд?",a="Тіранда Віспервінд — Верховна Жриця Елуни й духовна провідниця нічних ельфів. Старші жриці на кшталт Алатеї діють від її імені, стежачи, щоб усіх новачків, які представляють свою віру на чужині, пильнували й навчали за мірками Тіранди.",al={"чому згадують тіранду","тіранда віспервінд жриця","алатея і тіранда"}}},fp="14,314,21.478.0,22.380.0,64.272.0,25.248.0,51.209.0,36.234.0,40.219.0,45.266.0"}
P.entries["quest:5632"] = {n="Повернення додому",s="«Повернення додому» — заклик до обдарованих жерців нічних ельфів, що служать поза столицею. Жриця Алатея кличе посвячуваних назад до Храму Місяця в Дарнасусі, щоб визнати їхнє зростання в Сестринстві Елуни й дати їм глибші настанови.",h="«Повернення додому» — заклик до обдарованих жерців нічних ельфів, що служать поза столицею.",kw={"повернення додому","жриця алатея","нара мейдерос","храм місяця","сестринство елуни","тіранда віспервінд","жрець"},ang={["class:Priest"]="Цей заклик — важлива віха вашого жрецького шляху: за ранню службу Сестринство Елуни винагороджує вас безпосереднім єднанням і подальшою наукою.",["faction:Alliance"]="Сестринство Елуни — духовне серце нічних ельфів в Альянсі: воно готує вправних цілителів і божественних воїнів, щоб протистояти загрозам по всьому Калімдору.",["race:NightElf"]="Для калдореїв безпечне повернення до Храму Місяця — глибоке повернення додому, що утверджує незмінний культурний і духовний провід служительок Елуни."},sec={{t="Посланець від Сестринства",b="Коли молоді жерці мандрують далекими краями, служачи своєму народові, їхнє духовне зростання не лишається непоміченим. Під час відвідин Нари Мейдерос у Парку Стормвінда прибуває посланець Сестринства Елуни з нагальною звісткою: провідниці ордену чекають посвячуваного в Дарнасусі. Це водночас і перевірка, і обряд визнання — перехід від недосвідченого новачка до діяльного служителя Місячної Матері."},{t="Зустріч у Храмі Місяця",b="Заклик веде мандрівника просто до Жриці Алатеї у вінцевій святині Дарнасуса — Храмі Місяця. Під проводом Верховної Жриці Тіранди Віспервінд Сестринство пильно стежить за своїми розпорошеними членами. Безпечне повернення до храму вшановує і громаду, і богиню: воно показує, що благодать Елуни вела й берегла жерця під час перших випробувань у дикій глушині."}},faq={{q="Чому жриця кличе мене назад до Дарнасуса?",a="Жриця Алатея й Сестринство Елуни стежать за духовним зростанням своїх учнів. Вас кличуть до Храму Місяця, бо ви швидко поступаєте на шляху ордену, — і це веде просто до глибшого навчання й священного благословення.",al={"чому повернення додому","причина заклику","чому йти до алатеї"}},{q="Хто така Жриця Алатея?",a="Жриця Алатея — високопоставлена наставниця Сестринства Елуни в Храмі Місяця. Працюючи під безпосереднім проводом Верховної Жриці Тіранди Віспервінд, вона навчає обдарованих жерців нічних ельфів і посвячує їх у священні обряди.",al={"хто така алатея","переказ про алатею","хто насправді алатея"}},{q="Куди веде цей заклик далі?",a="Доповідь Жриці Алатеї одразу веде до випробування «Зорі Елуни» — давнього жрецького завдання, де ви вчитеся спрямовувати небесну силу богині на захист свого народу.",al={"яке завдання після повернення додому","наступний крок повернення додому","вступ до зірки елуни"}},{q="Хто передає звістку через Нару Мейдерос?",a="Звістку Нарі Мейдерос передав посланець, якого відрядило саме Сестринство Елуни. Орден підтримує зв'язок із жрицями, що служать на чужині, — як-от Нара в Парку Стормвінда, — щоб стежити за своїми послушниками.",al={"хто послав нару","посланниця сестринства"}},{q="Чи отримують цей заклик інші раси чи класи?",a="Ні. Це завдання пов'язане саме з жрецтвом нічних ельфів і Сестринством Елуни. Послушники інших рас і вір звертаються по поступ до власних духовних наставників і священних орденів.",al={"чи не нічні ельфи можуть це взяти","чи це лише для жерців"}},{q="Чому Алатея згадує Тіранду Віспервінд?",a="Тіранда Віспервінд — Верховна Жриця Елуни й найвища провідниця і Сестринства, і уряду нічних ельфів. Алатея працює безпосередньо під її началом у Храмі Місяця, дбаючи, щоб воля й духовні настанови Тіранди сягали кожного послушника.",al={"зв'язок з тірандою","тіранда й алатея"}}},fp="14,253,31.449.0,34.414.0,52.253.0,25.246.0,34.201.0,44.231.0,47.206.0,45.261.0"}
P.entries["quest:5633"] = {n="Повернення додому",s="«Повернення додому» — заклик до жерців нічних ельфів, що мандрують чужими краями й опинилися в Айронфорджі, повернутися до Храму Місяця в Дарнасусі. Посланниця Сестринства розшукувала мандрівних послушників, щоб скерувати їх назад до Жриці Алатеї — на нагальне навчання й духовну службу.",h="«Повернення додому» — заклик до жерців нічних ельфів, що мандрують чужими краями й опинилися в Айронфорджі...",kw={"повернення додому","бренна флінткреґ","айронфордж","жриця алатея","храм місяця","жрець","сестринство елуни"},ang={["class:Priest"]="Це завдання повертає вас із перших мандрів серед союзників Альянсу до духовного дому жрецтва нічних ельфів — Храму Місяця.",["faction:Alliance"]="Співпраця дворфійських священників в Айронфорджі та Сестринства Елуни в Дарнасусі показує, як народи Альянсу злагоджено підтримують мандрівних шукачів пригод.",["race:NightElf"]="Покинути Калімдор заради Східних Королівств — рідкісна подорож для молодого калдорея, але настанови Елуни й жрецтва Тіранди сягають і через Велике Море."},sec={{t="Виклик із гірського міста",b="Навіть мандруючи далеко від Тельдрассилу гомінкими підземними залами Айронфорджа, жерці нічних ельфів лишаються пов'язаними із Сестринством Елуни. Бренна Флінткреґ, дворфійська наставниця жерців у Кварталі містиків, передає послання, залишене жрицею нічних ельфів, що навідувалася до міста. Посланниця шукала молодих учнів у далеких краях і принесла звістку: наставниці чекають їх у столиці негайно."},{t="Храм Місяця",b="Прибувши до Храму Місяця в Дарнасусі, послушники одразу з'являються до Жриці Алатеї. Вітаючи свого учня під пильним поглядом Верховної Жриці Тіранди Віспервінд, Алатея з полегшею радіє, що він безпечно перетнув моря. Нагальний заклик стає порогом до глибшої відданості й відкриває шлях до священних обов'язків, як-от «Зорі Елуни»."}},faq={{q="Хто дає це завдання?",a="Завдання дає Бренна Флінткреґ — дворфійська наставниця жерців у Кварталі містиків Айронфорджа.",al={"хто дає повернення додому","хто видає повернення додому","де бренна фліннтраґ"}},{q="Кому доповідати в Дарнасусі?",a="Треба поговорити з Жрицею Алатеєю в Храмі Місяця в Дарнасусі.",al={"де здати повернення додому","де жриця алатея","здати повернення додому"}},{q="Чому Сестринство кличе жерців назад?",a="Сестринство Елуни пильно стежить за своїми послушниками. Щойно послушник доведе свою вправність на чужині, провід у Дарнасусі кличе його назад для глибшого навчання й священних обрядів, як-от «Зорі Елуни».",al={"чому повернення додому","чому вертатися до дарнасуса"}},{q="Чи доступне це завдання іншим класам?",a="Ні, це завдання призначене саме для жерців нічних ельфів, що на початку своїх пригод вирушили до Дун Мороґа й Айронфорджа.",al={"чи воїни можуть взяти повернення додому","завдання лише для жерців"}},{q="Що буде, коли здати це завдання?",a="Жриця Алатея вітає вас у Дарнасусі й пропонує наступне завдання — «Зорі Елуни», що глибше занурює в науку богині.",al={"наступне завдання після повернення додому","продовження повернення додому"}},{q="Як Бренна знає, що треба вас шукати?",a="Жриця, яку послав сам Храм Місяця, проходила через Айронфордж у пошуках послушників і лишила місцевим наставникам на кшталт Бренни чіткі вказівки скеровувати додому всіх мандрівних нічних ельфів.",al={"звідки бренна мене знає","звістка жриці айронфорджа"}}},fp="14,273,31.415.0,22.389.0,22.104.0,32.94.0,43.227.0,41.135.0,41.145.0,38.207.0"}
P.entries["quest:5634"] = {n="Відчайдушна молитва",s="«Відчайдушна молитва» — обряд посвяти для молодих жерців-людей у Стормвінді. Його дає Верховна Жриця Лаурена в Соборі Світла, і він знаменує відданість послушника справі збереження життя в неспокійних землях Альянсу. Пройшовши це духовне навчання, жерці отримують невідкладне благословення, щоб зцілити власні рани, коли ніщо інше вже не допомагає.",h="«Відчайдушна молитва» — обряд посвяти для молодих жерців-людей у Стормвінді.",kw={"відчайдушна молитва","верховна жриця лаурена","собор світла","жрець","святе світло","зцілення"},ang={["class:Priest"]="Цей обряд позначає ваш перехід від учня-послушника до діяльного служителя Святого Світла, здатного вижити в смертельних випробуваннях у полі.",["faction:Alliance"]="Збереження цілителів на передовій завдяки благословенням на кшталт Відчайдушної молитви вкрай важливе, щоб підтримувати воїнів Альянсу на небезпечних рубежах.",["race:Human"]="Жерці-люди отримують це вчення безпосередньо від верхівки Собору Світла, і це утверджує Стормвінд як головний осередок людської віри."},sec={{t="Благання в темряві",b="Жерців, що служать у Соборі Світла, вчать спрямовувати віру назовні — заступати товаришів, гоїти смертельні рани й карати зло. Та навіть найпобожніші служителі Святого Світла опиняються самі, загнані в кут чи на межі людської витривалості. Відчайдушна молитва — це глибоко особисте, невідкладне єднання зі Світлом, щирий крик про божественне заступництво, коли життя послушника висить на волосині."},{t="Благословення Собору",b="Верховна Жриця Лаурена наглядає за чималою частиною духовенства на Соборній Площі Стормвінда й вирішує, коли послушник довів, що гідний глибших таємниць віровчення. Показавши справжню відданість чеснотам Світла по всьому королівству, новачки-люди отримують цей священний урок не лише як засіб вижити, а й як урочисте підтвердження: їхнє подальше служіння лишається вкрай потрібним королівству."}},faq={{q="Що таке «Відчайдушна молитва»?",a="«Відчайдушна молитва» — невідкладний заклик до Святого Світла, який дано жерцям-людям і дворфам. Вона дає змогу пораненому жерцеві миттєво скликати божественну силу й загоїти власні тяжкі рани, не витрачаючи часу на довгі замовляння.",al={"що робить відчайдушна молитва","навіщо відчайдушна молитва","мета відчайдушної молитви"}},{q="Хто дає цю науку в Стормвінді?",a="Верховна Жриця Лаурена, що служить у величному Соборі Світла на Соборній Площі Стормвінда, передає цю науку, коли послушник виявить досить відданості й досвіду в широкому світі.",al={"хто навчає відчайдушної молитви","де взяти відчайдушну молитву","завдання верховної жриці лаурени"}},{q="Чому жерці отримують саме цю науку?",a="Жерці Святого Світла часто кидаються в небезпеку, щоб допомогти іншим. «Відчайдушна молитва» — священний запобіжник: коли цілителі опиняються покинутими чи тяжко пораненими, їхня віра може зберегти їм життя.",al={"чому жерці отримують відчайдушну молитву","переказ про відчайдушну молитву"}},{q="Чи може тут будь-який шукач пригод навчитися «Відчайдушної молитви»?",a="Ні. Це завдання й ця наука суворо призначені для жерців, налаштованих на вчення Святого Світла, що навчаються під проводом Церкви Світла.",al={"чи кожен може вивчити відчайдушну молитву","чи це завдання лише для жерців"}},{q="Де відбувається цей обряд?",a="У Соборі Світла — височенному духовному серці Альянсу в північному кварталі Стормвінда.",al={"де відчайдушна молитва","де лаурена"}},{q="Чи «Відчайдушна молитва» — лише для жерців-людей?",a="У землях Альянсу «Відчайдушною молитвою» користуються і людське, і дворфійське духовенство, адже обидва народи шанують Святе Світло в тісно споріднених церковних традиціях, осердя яких — Стормвінд і Айронфордж.",al={"чи інші раси отримують відчайдушну молитву","дворф відчайдушна молитва"}}},fp="16,372,18.426.0,24.414.0,40.245.0,36.209.0,46.233.0,47.159.0,32.139.0,44.210.0"}
P.entries["quest:5635"] = {n="Відчайдушна молитва",s="«Відчайдушна молитва» — вступне завдання для молодих жерців Альянсу, що служать Церкві Святого Світла. Виявивши першу відданість і дисципліну в Лісі Елвінн, перспективних послушників викликають до Собору Світла в Стормвінді, щоб продовжити священну науку під проводом Верховної Жриці Лаурени.",h="«Відчайдушна молитва» — вступне завдання для молодих жерців Альянсу, що служать Церкві Святого Світла.",kw={"відчайдушна молитва","верховна жриця лаурена","жриця джозетта","собор світла","жрець","ґолдшир"},ang={["class:Priest"]="Це завдання знаменує ваш офіційний перехід від парафіяльного новачка в Ґолдширі до визнаного учня, якого довірено старшим провідникам Собору Світла.",["faction:Alliance"]="Церква Святого Світла лишається однією з найміцніших культурних і моральних опор, що єднають Альянс у часи грізних загроз.",["race:Human"]="Для людей Святого Світла ступити до височенного Собору Світла — глибоке паломництво, що утверджує ваш обов'язок перед духовним серцем королівства."},sec={{t="Виклик до столиці",b="Жерці-новачки, що служать у віддалених поселеннях Лісу Елвінн, починають свій шлях під проводом місцевих наставників, як-от Жриці Джозетти в Ґолдширі. Коли учень виявляє силу духу й добрі діла, звістка швидко доходить до старшого духовенства в столиці. Визнання приходить у вигляді прямого виклику до величного Собору Світла — духовного серця королівства Стормвінд: настав час узяти на себе офіційні, глибші обов'язки у вірі."},{t="Настанови Верховної Жриці",b="Прибувши до Собору, послушники постають перед Верховною Жрицею Лауреною. Як одна з провідних очільниць Церкви в місті, Лаурена дбає про духовні засади й практичний вишкіл щойно висвячених жерців. Її наука готує вірних до суворих випробувань, що чекають на Альянс, і передає їм важливе знання про чудеса Світла — зокрема про благання про порятунок, відоме серед людей як Відчайдушна молитва."}},faq={{q="Яка мета завдання «Відчайдушна молитва»?",a="Завдання скеровує обдарованих жерців 10-го рівня з Ґолдширу до Собору Світла в Стормвінді й знайомить новачків із Верховною Жрицею Лауреною, щоб ті продовжили своє священне навчання.",al={"завдання відчайдушна молитва","що таке завдання відчайдушна молитва","навіщо відчайдушна молитва"}},{q="Хто дає завдання «Відчайдушна молитва»?",a="Цей заклик дає Жриця Джозетта, наставниця жерців у Корчмі «Лев'яча Гордість» у Ґолдширі, коли ви доведете свою відданість.",al={"хто починає відчайдушну молитву","хто дає відчайдушну молитву"}},{q="Хто така Верховна Жриця Лаурена?",a="Верховна Жриця Лаурена — старша провідниця Церкви Святого Світла, що служить у Соборі Світла в Стормвінді й навчає досвідчених послушників.",al={"хто така лаурена","переказ про верховну жрицю лаурену"}},{q="Де розташований Собор Світла?",a="Собор Світла панує над Соборною Площею в північному кварталі Стормвінда й слугує духовним осередком для жрецтва й паладинів королівства.",al={"де собор світла","де собор у стормвінді"}},{q="Чому завдання називається «Відчайдушна молитва»?",a="Воно відкриває жерцеві глибше навчання в Стормвінді, де жерці-люди за традицією вчаться заклику, відомого як «Відчайдушна молитва», — благання до Світла про негайне рятівне визволення.",al={"чому називається відчайдушна молитва","значення назви відчайдушна молитва"}},{q="Чи отримують це завдання інші раси чи класи?",a="Цей ланцюжок створено для жерців, що виходять із Лісу Елвінн, щоб розпочати вище навчання в столиці, Стормвінді.",al={"чи дворфи можуть взяти завдання відчайдушна молитва","чи відчайдушна молитва лише для жерців"}}},fp="16,314,24.479.0,32.465.0,50.188.0,37.140.0,30.166.0,40.168.0,40.212.0,41.135.0"}
P.entries["quest:5636"] = {n="Відчайдушна молитва",s="«Відчайдушна молитва» — завдання для жерців Альянсу, що скеровує мандрівних служителів Святого Світла назад до Стормвінда. Його починає жриця нічних ельфів Лаурна Морнінґлайт у Доланаарі: вона кличе людських жерців, що гостюють на Тельдрассилі, додому — завершити важливий духовний вишкіл у Верховної Жриці Лаурени.",h="«Відчайдушна молитва» — завдання для жерців Альянсу, що скеровує мандрівних служителів Святого Світла назад...",kw={"відчайдушна молитва","жрець","лаурна морнінґлайт","верховна жриця лаурена","собор світла","стормвінд"},ang={["class:Priest"]="Це завдання — важливий обряд переходу на 10-му рівні: воно повертає жерців до Собору Світла, щоб вивчити особливі расові благословення віри.",["faction:Alliance"]="Виклик свідчить про дедалі тіснішу співпрацю в Альянсі: жриці нічних ельфів охоче узгоджують дії з церковним проводом Стормвінда.",["race:NightElf"]="Хоч нічні ельфи шанують богиню місяця Елуну, Жриця Лаурна Морнінґлайт виявляє ввічливу повагу до чужоземних прихильників Святого Світла, що ходять під гіллям Тельдрассила."},sec={{t="Звістка з дому",b="Відвідуючи прадавнє гілля Тельдрассила, жерці, вірні Святому Світлу, можуть привернути увагу місцевого Сестринства Елуни. У Доланаарі Жриця Лаурна Морнінґлайт стає несподіваною посередницею: вона переказує, що один з ваших побратимів-жерців перетнув континенти, шукаючи вас. Розуміючи нагальність виклику, Лаурна радить вам без зволікань повернутися на батьківщину й дає благословення Елуни разом із добрими побажаннями вашій власній вірі."},{t="Виклик до Стормвінда",b="Дорога веде через Велике Море до величного Собору Світла в самому серці Стормвінда. Там Верховна Жриця Лаурена наглядає за духовним зростанням вірян Альянсу. Послушників, які рано виявили хист, кличуть до неї опанувати глибші таємниці відданості — зокрема рятівне звернення, відоме як Відчайдушна молитва: дар, що дарують лише відданим учням для їхньої найтемнішої години."}},faq={{q="Хто дає завдання «Відчайдушна молитва» на Тельдрассилі?",a="Завдання дає Лаурна Морнінґлайт — наставниця жерців нічних ельфів у Доланаарі на Тельдрассилі. Вона передає термінову звістку, яку лишив жрець, що приходив із ваших рідних земель.",al={"хто дає відчайдушну молитву","хто дає відчайдушну молитву на тельдрассилі","завдання лаурни морнінґлайт"}},{q="Куди веде це завдання?",a="Завдання веде до Собору Світла в Стормвінді, де треба поговорити безпосередньо з Верховною Жрицею Лауреною.",al={"куди йти","здати відчайдушну молитву","де лаурена"}},{q="Чому нічна ельфійка скеровує жерця до Стормвінда?",a="Жерці нічних ельфів шанують Елуну, але жерці з інших народів — люди чи дворфи, — що приходять на Тельдрассил, і далі належать до традицій Святого Світла. Лаурна Морнінґлайт шанобливо ставиться до їхньої віри й передає звістки від церковної ієрархії їхньої батьківщини.",al={"чому нічний ельф посилає до стормвінда","святе світло нічних ельфів"}},{q="Що дають за виконання цього завдання?",a="Доповідь Верховній Жриці Лаурені відкриває глибше духовне наставництво й змогу навчитися «Відчайдушної молитви» — миттєвої цілющої молитви, доступної лише жерцям-людям і дворфам.",al={"нагорода за відчайдушну молитву","яке закляття я отримаю"}},{q="Чи можуть жерці нічних ельфів узяти саме це завдання?",a="Ні. Жерці нічних ельфів шанують Елуну й навчаються «Зоряних Скалок», а не «Відчайдушної молитви». Цей заклик існує саме для жерців-людей, що на ранніх рівнях опинилися в Калімдорі.",al={"чи нічні ельфи можуть взяти відчайдушну молитву","жрець нічний ельф відчайдушна молитва"}},{q="Як повернутися з Тельдрассилу до Стормвінда?",a="Треба пройти через Дарнасус до Селища Рут'теран, сісти на корабель до Обердайна на Темному Узбережжі, перепливти морем на іншому кораблі до Гавані Менетіл у Багнокраї, а тоді йти на південь через Лох Модан, Дун Мороґ і Глибинним трамваєм — до Стормвінда.",al={"як дістатися стормвінда з доланаара","дорога з тельдрассила до стормвінда"}}},fp="16,300,19.476.0,24.457.0,52.185.0,27.129.0,51.279.0,45.188.0,47.204.0,52.254.0"}
P.entries["quest:5637"] = {n="Відчайдушна молитва",s="«Відчайдушна молитва» — обряд посвяти, що кличе перспективних жерців-дворфів із Дун Мороґа до величного Собору Світла в Стормвінді. Верховна Жриця Лаурена викликає молодих послушників, щоб поглибити їхню духовну відданість і відкрити їм особливі святі прийоми. Це перехід жерця від місцевого навчання до ширшого служіння Альянсу.",h="«Відчайдушна молитва» — обряд посвяти, що кличе перспективних жерців-дворфів із Дун Мороґа до величного...",kw={"відчайдушна молитва","верховна жриця лаурена","максан анвол","дун мороґ","собор світла","дворфи"},ang={["class:Priest"]="Це завдання — віха вашого духовного шляху: місток між простим парафіяльним служінням і вищими святими прийомами, яких навчають безпосередньо провідники Церкви.",["faction:Alliance"]="Духовна співпраця Айронфорджа й Стормвінда дає служителям Світла змогу стояти пліч-о-пліч попри межі між расами.",["race:Dwarf"]="Мандрівка до Собору Стормвінда зміцнює спільний духовний завіт між гірським королівством Айронфордж і людським королівством Стормвінд."},sec={{t="Виклик до Собору",b="Жерці, що починають служіння серед снігів Дун Мороґа, згодом переростають науку місцевих наставників, як-от Максана Анвола в Хараносі. Коли послушник виявляє справжній хист, надходить офіційний виклик від самої Верховної Жриці Лаурени. Така пряма увага провідників Собору Світла свідчить, що молодий жрець готовий до глибших таємниць і більшої відповідальності у вірі."},{t="Узи між королівствами",b="Хоч Айронфордж і має власні святі традиції в Кварталі містиків, Церква Святого Світла в Стормвінді — спільне духовне серце і для людей, і для дворфів. Мандрівка на південь Глибинним трамваєм поєднує дворфійських послушників із ширшою церковною спільнотою й зміцнює духовне братерство двох союзних королівств."}},faq={{q="Чому Верховна Жриця Лаурена кличе дворфійських жерців до Стормвінда?",a="Верховна Жриця Лаурена опікується вищим релігійним навчанням у Соборі Світла. Коли місцеві наставники на кшталт Максана Анвола бачать, що послушник опанував основи віри, вони посилають його до Лаурени, щоб навчитися особливих сильних прийомів, як-от «Відчайдушної молитви».",al={"чому лаурена кличе мене","чому жрецю йти до стормвінда","хто така верховна жриця лаурена"}},{q="Що таке «Відчайдушна молитва» в переказах?",a="«Відчайдушна молитва» — невідкладний заклик, який практикує людське й дворфійське духовенство Святого Світла. Опинившись на межі смерті, жрець видає інстинктивний, нагальний поклик віри, що миттєво стягує рани й повертає життєві сили.",al={"переказ про відчайдушну молитву","що таке відчайдушна молитва","як діє відчайдушна молитва"}},{q="Де відбувається це завдання?",a="Заклик починається в Хараносі в Дун Мороґу, де Максан Анвол велить вам вирушати до Стормвінда. Завершується він у Соборі Світла на Соборній Площі Стормвінда, де головує Верховна Жриця Лаурена.",al={"місце завдання","куди йти","де лаурена"}},{q="Чому жрець-дворф навчається в людської Верховної Жриці?",a="Дворфи й люди поділяють ту саму віру в Святе Світло, і цей зв'язок зміцнила Друга війна. Хоча дворфійські жерці часто служать у Кварталі містиків Айронфорджа, Собор Світла в Стормвінді — один із провідних осередків віри, що приймає всіх служителів Світла з Альянсу.",al={"чому людська наставниця для дворфа","церква світла дворфів","світло айронфорджа і стормвінда"}},{q="Як молодому мандрівникові дістатися з Дун Мороґа до Стормвінда?",a="Найшвидший і найбезпечніший шлях — через Містечко Майстрів в Айронфорджі, звідки Глибинний трамвай везе просто під горами до Дворфійського Кварталу Стормвінда.",al={"як дістатися стормвінда","дорога до стормвінда для дворфа","глибинна підземка"}},{q="Хто такий Максан Анвол?",a="Максан Анвол — дворфійський наставник жерців у Хараносі в Дун Мороґу. Він опікується молодими служителями й навчає їх основ, доки вони не стануть досить дисциплінованими, щоб навчатися в старшого церковного проводу в Стормвінді.",al={"переказ про максана анвола","хто дав завдання","наставник жерців у харанос"}}},fp="16,353,26.418.0,21.360.0,67.277.0,37.245.0,33.220.0,60.290.0,60.190.0,19.226.0"}
P.entries["quest:5638"] = {n="Відчайдушна молитва",s="«Відчайдушна молитва» — обряд посвяти для жерців, що зростають у вірі й навідуються до Парку в Стормвінді. Нічна ельфійка, жриця Нара Мейдерос, відправляє послушників через канали до Собору Світла, де їхнє святе навчання продовжує Верховна Жриця Лаурена. Це мить, коли новачок переходить від простої служби до глибшого, особливого єднання зі Святим Світлом.",h="«Відчайдушна молитва» — обряд посвяти для жерців, що зростають у вірі й навідуються до Парку в Стормвінді.",kw={"відчайдушна молитва","жрець","собор світла","лаурена","нара мейдерос","стормвінд"},ang={["class:Priest"]="Цей виклик означає ваше офіційне посвячення у вищі духовні практики й відкриває шлях до опанування рятівного закликання — «Відчайдушної молитви».",["faction:Alliance"]="Співпраця Нари Мейдерос у Парку з духовенством Соборної Площі свідчить про тиху солідарність святих орденів Дарнасуса і Стормвінда.",["race:Human"]="Собор Світла — найголовніше святилище людської віри на півдні Східних Королівств, тож настанови Лаурени — це і культурна, і духовна віха."},sec={{t="Слово в Парку",b="У тихому гаю Парку нічні ельфійки-жриці, як-от Нара Мейдерос, плекають єднання з Елуною посеред метушні Стормвінда. Проте узи віри між духовними наставниками Альянсу долають межі культур. Коли посланець із Соборної Площі шукає обдарованого учня, Нара передає йому виклик зі спокійним підбадьоренням і запевняє, що поклик несе добрі вісті, а не привід для тривоги."},{t="Поклик Собору",b="Перетнувши Соборну Площу й ступивши під високі арки з білого каменю Собору Світла, новачок з'являється до Верховної Жриці Лаурени. Як одна з найстарших духовних провідниць Стормвінда, Лаурена веде молодих послушників далі за прості основи молитви. Вона передає священне закликання, відоме як «Відчайдушна молитва», — особисте благання про божественне втручання, яке вмить загоює тяжкі рани, коли слуга Світла стоїть на краю смерті."}},faq={{q="Хто посилає мене на це завдання?",a="Жриця Нара Мейдерос, служителька з нічних ельфів у кварталі Парк у Стормвінді, передає звістку, що провід Собору вас шукає.",al={"хто дає завдання","хто дає відчайдушну молитву","нара мейдерос"}},{q="Кому доповідати в Стормвінді?",a="Треба поговорити з Верховною Жрицею Лауреною в Соборі Світла на Соборній Площі Стормвінда.",al={"куди йти","здати завдання","хто така лаурена"}},{q="Яке значення має «Відчайдушна молитва»?",a="«Відчайдушна молитва» — важлива наука, якої навчають людське й дворфійське духовенство Святого Світла. Це миттєвий заклик, що скликає божественну благодать і вмить відновлює сили заклинача в мить смертельної небезпеки.",al={"що робить відчайдушна молитва","переказ про здібність жерця","закляття відчайдушна молитва"}},{q="Чому нічна ельфійка скеровує жерців до людського собору?",a="Хоча жриці нічних ельфів шанують Елуну, а не Святе Світло, якому служать люди й дворфи, духовні ордени в Стормвінді підтримують тісний зв'язок і взаємну пошану й передають звістку, коли служителям Альянсу потрібне навчання.",al={"чому нара мейдерос","парк до собору","нічні ельфи елуна стормвінд"}},{q="На якому етапі навчання приходить цей заклик?",a="Цей заклик приходить приблизно на десятому колі досвіду — знак того, що молодий жрець довів на ділі, що готовий до складніших божественних обрядів.",al={"який це рівень","коли я отримаю відчайдушну молитву"}},{q="Де розташований Собор Світла?",a="Собор Світла панує над Соборною Площею в північному кварталі Стормвінда, між Дворфійським Кварталом і Парком.",al={"де собор","де соборна площа"}}},fp="16,409,18.435.0,25.477.0,27.162.0,40.118.0,45.228.0,60.239.0,50.169.0,40.144.0"}
P.entries["quest:5639"] = {n="Відчайдушна молитва",s="Відчайдушна молитва — обряд посвяти для дворфійських жерців, що дорослішають в Айронфорджі. Верховний Жрець Роган посилає послушників Глибинним трамваєм до Стормвінда, де вони продовжать навчання у Верховної Жриці Лаурени. Дорога до величного Собору Світла знаменує перехід посвяченого до глибших таїнств зцілення й виживання.",h="Відчайдушна молитва — обряд посвяти для дворфійських жерців, що дорослішають в Айронфорджі.",kw={"відчайдушна молитва","жрець","верховний жрець роган","верховна жриця лаурена","собор світла","глибинний трамвай"},ang={["class:Priest"]="Ця подорож знаменує, що ви завершили місцеве навчання в Айронфорджі й увійшли до ширшої ієрархії Церкви Святого Світла.",["faction:Alliance"]="Спільне навчання жерців відбиває глибоку духовну єдність і співпрацю церковних установ Айронфорджа й Стормвінда.",["race:Dwarf"]="Для юних дворфів Каз Модану подорож до Стормвінда — перша нагода побачити людську культуру, величну архітектуру й спільну духовну відданість."},sec={{t="Виклик до Стормвінда",b="У кам'яних склепіннях Кварталу містиків Айронфорджа Верховний Жрець Роган опікується дворфійськими посвяченими, відданими Святому Світлу. Коли послушник виявляє досить дисципліни й віри, Роган скеровує його на південний захід, до людського королівства Стормвінд. Жерці-люди й жерці-дворфи підтримують тісні духовні зв'язки, а поглиблене богословське навчання зосереджене у величних залах Стормвінда."},{t="Собор Світла",b="Прибувши підземним Глибинним трамваєм, послушники піднімаються на Соборну Площу. Там, у величному Соборі Світла, Верховна Жриця Лаурена від імені Церкви випробовує кандидатів. Її настанови — про розпачливі благання, до яких жрець мусить удатися в горнилі битви: про заклик до божественного втручання, коли тілесна витривалість зраджує, а смерть уже поруч."}},faq={{q="Хто посилає мене на це завдання?",a="Це завдання дає Верховний Жрець Роган. Він очолює дворфійське духовенство в Залі Таїнств у Кварталі містиків Айронфорджа.",al={"хто дає завдання","хто видає завдання","де роган"}},{q="Куди треба йти, щоб його виконати?",a="Треба вирушити до Собору Світла в серці Соборної Площі в Стормвінді. Верховна Жриця Лаурена чекає в головному святилищі.",al={"де лаурена","де здати","здати в стормвінді"}},{q="Як найкраще дістатися з Айронфорджа до Стормвінда?",a="Найбезпечніший і найшвидший шлях — Глибинний трамвай, інженерне диво, яке збудували гноми. Вхід до нього — у східній частині Айронфорджа, а веде він просто до Дворфійського Кварталу Стормвінда.",al={"як дістатися стормвінда","дорога до стормвінда","де підземка"}},{q="Чому жрець-дворф мусить їхати вчитися до людського міста?",a="Церква Святого Світла глибоко вкорінена в людській традиції, і її головний осередок науки — Собор Світла. Дворфійське й людське жрецтво працюють пліч-о-пліч, ділячись ученням і традиціями по всьому Альянсу.",al={"чому стормвінд","дворф і людська церква","чому лаурена"}},{q="Яку здібність відкриває це навчання?",a="Цей ланцюжок посвячує вас у науку «Відчайдушної молитви» — миттєвої молитви самозбереження, що швидко відновлює здоров'я жерця в разі крайньої потреби.",al={"нагорода за завдання","яке закляття я отримаю","здібність відчайдушна молитва"}},{q="Чи є в цьому завданні бій?",a="Ні. Це суто проща й доручення посланця: треба безпечно дістатися з Айронфорджа до Стормвінда й відрекомендуватися Верховній Жриці Лаурені.",al={"чи буде бій","бій у завданні","завдання з подорожжю"}}},fp="16,346,22.399.0,22.379.0,27.132.0,39.161.0,56.217.0,52.225.0,39.167.0,31.166.0"}
P.entries["quest:5640"] = {n="Відчайдушна молитва",s="«Відчайдушна молитва» — завдання для молодих жерців-людей і жерців-дворфів, що гостюють у Дарнасусі: воно скеровує їх назад до власних духовних традицій у Стормвінді. Жриця Алатея розуміє: нічні ельфи черпають силу від Елуни, а послідовникам Святого Світла слід шукати наставників своєї віри. Завершивши цю подорож, послушник повертається до Верховної Жриці Лаурени в Соборі Світла.",h="«Відчайдушна молитва» — завдання для молодих жерців-людей і жерців-дворфів, що гостюють у Дарнасусі: воно...",kw={"відчайдушна молитва","жриця алатея","верховна жриця лаурена","собор світла","стормвінд","святе світло","жрець"},ang={["class:Priest"]="Це завдання показує, як свята магія в Альянсі поділена між шануванням Елуни й відданістю Святому Світлу, і скеровує молодих послушників назад до їхніх справжніх наставників.",["race:Dwarf"]="Жерці-дворфи, що шанують Святе Світло, тісно пов'язані із собором Стормвінда й вивчають свої найвищі молитви пліч-о-пліч із братами-людьми.",["race:Human"]="Жерцям-людям далеко від дому нагадують, що їхній справжній духовний дім і навчання чекають у Соборі Світла в Стормвінді.",["race:NightElf"]="Нічні ельфійки, сестри Елуни, з чемною шанобою визнають силу чужих вір, але зберігають сувору відданість лише Місячній Матері."},sec={{t="Два шляхи віри",b="Жерці Альянсу черпають силу з докорінно різних священних джерел. У Дарнасусі жрецтво Елуни служить богині місяця, спрямовуючи її лагідне сяйво й небесний гнів. Коли послушники-люди й дворфи потрапляють під гілля Тельдрассилу, наставниці на кшталт Жриці Алатеї чемно визнають цю межу: Алатея шанує Елуну й поважає Святе Світло, але не може навчати іншу расу глибших молитов, пов'язаних із зовсім іншою вірою."},{t="Повернення до Собору",b="Щоб опанувати вміння, народжені з абсолютної віри, — як-от закликати божественне заступництво в найтемнішу годину, — посвячуваним Святого Світла велять вертатися додому. Верховна Жриця Лаурена керує навчанням під високими мармуровими склепіннями Собору Світла в Стормвінді й готова ввести жерців, що повернулися, у глибші обряди їхнього покликання."}},faq={{q="Чому жриця з Дарнасуса посилає мене до Стормвінда?",a="Жриця Алатея навчає шляхів богині місяця Елуни. Оскільки люди й дворфи черпають віру й дива зі Святого Світла, Алатея чемно скеровує їх до наставників їхньої власної традиції — як-от до Верховної Жриці Лаурени в Стормвінді.",al={"чому йти до стормвінда","чому алатея відсилає мене","завдання жерця з дарнасуса до стормвінда"}},{q="Хто така Жриця Алатея?",a="Жриця Алатея — жриця нічних ельфів у Храмі Місяця в Дарнасусі. Вона наставляє тих, хто прагне служити Елуні, і шанобливо радить чужоземним жерцям, що навідуються до Світового Дерева.",al={"переказ про алатею","хто така алатея"}},{q="Хто така Верховна Жриця Лаурена?",a="Верховна Жриця Лаурена — людська духовна провідниця в Соборі Світла в Стормвінді. Вона навчає обдарованих служителів Святого Світла, допомагаючи їм опанувати складні молитви й урочисті обов'язки.",al={"хто така лаурена","верховна жриця лаурена стормвінд"}},{q="Що таке «Відчайдушна молитва» в переказах?",a="«Відчайдушна молитва» — миттєвий заклик по божественну допомогу, коли жрець на межі смерті чи в смертельній небезпеці. Це характерне благання, яке дано вірним служителям Святого Світла, що потребують негайного зцілення.",al={"що таке відчайдушна молитва","переказ про здібність відчайдушна молитва"}},{q="Чи можуть нічні ельфи навчати Святого Світла?",a="Ні. Нічні ельфи шанують майже виключно Елуну й спрямовують її місячну силу. До Святого Світла вони ставляться з дипломатичною пошаною, але не проповідують його й не навчають його особливих молитов, лишаючи це людському й дворфійському жрецтву.",al={"чи нічні ельфи знають світло","елуна чи святе світло"}},{q="Де знайти Верховну Жрицю Лаурену?",a="Верховна Жриця Лаурена — на Соборній Площі Стормвінда, у Соборі Світла, серед інших служителів і паладинів Срібної Длані.",al={"де лаурена","де знайти лаурену"}}},fp="16,401,18.489.0,23.366.0,49.249.0,25.207.0,30.240.0,37.220.0,37.241.0,40.165.0"}
P.entries["quest:5643"] = {n="Тіньова варта",s="«Тіньова варта» — поклик для жерців-тролів із племені Темного Списа, які опинилися далеко від дому, у столиці Відступників Андерсіті. Елталіста бачить, що юний троль доріс до священних обрядів свого племені, і відсилає його назад до Оргріммара. У Долині Духів на нього чекає наставник жерців Ур'кьо, щоб провести на новий важливий щабель духовного захисту.",h="«Тіньова варта» — поклик для жерців-тролів із племені Темного Списа, які опинилися далеко від дому, у столиці...",kw={"жрець","тролі","темний спис","ур'кьо","елталіста","андерсіті","долина духів","лоа"},ang={["class:Priest"]="Цей обряд — визначальна віха на шляху жерця: тут закінчуються спільні для всіх основи святої й тіньової магії та починаються самобутні традиції вашого народу.",["race:Troll"]="Для Темного Списа служіння жерця невіддільне від єднання з лоа й захисту племені — цю спадщину береже Ур'кьо в Долині Духів.",["race:Undead"]="Наставники на кшталт Елталісти шанують самобутні традиції своїх живих союзників: тролі, що навідуються до міста, навчаються у власних старійшин, а не підкоряються доктрині Відступників."},sec={{t="Поклик через континенти",b="Навіть у похмурому Андерсіті узи віри й племінних традицій лишаються міцними. Наставниця жерців Відступників Елталіста уважно стежить за тролями-жерцями, що навідуються до міста, й помічає, коли учень набирає досить сили, щоб пройти випробування свого народу. Замість нав'язувати їм похмуру філософію Культу Забутої Тіні, вона відсилає троля назад через Велике Море — до прадавніх звичаїв його власних старійшин."},{t="Долина Духів",b="Прибувши до Дуротару, жрець прямує до містичної обителі — Долини Духів в Оргріммарі. Там Ур'кьо дбає про духовні потреби й прадавні ритуали племені Темного Списа. Він вітає учня, що повернувся, і готує його до важливого обряду посвяти, який поєднує зв'язок жерця з лоа та практичні чари, що відвертають лихо."}},faq={{q="Хто дає це завдання?",a="Завдання дає Елталіста — наставниця жерців у Воєнному Кварталі Андерсіті. Вона бачить, коли жрець-троль досяг зрілості, потрібної для духовних випробувань його племені.",al={"хто дає завдання","з чого почати","хто дає тіньову варту"}},{q="Чому наставниця з Андерсіті посилає мене до Оргріммара?",a="Жерці Відступників сповідують Культ Забутої Тіні, а тролі Темного Списа черпають духовну силу з лоа й племінних традицій. Елталіста шанує цю відмінність і відсилає молодих жерців-тролів додому, щоб ті вчилися особливих расових мистецтв у власного старійшини.",al={"чому йти до оргріммара","з андерсіті до оргріммара","чому ур'кьо"}},{q="Хто такий Ур'кьо?",a="Ур'кьо — визначний наставник жерців-тролів Темного Списа в Долині Духів в Оргріммарі. Він навчає тролячих духовних звичаїв і обрядів посвяти й опікується учнями.",al={"переказ про ур'кьо","хто такий ур'кьо","наставник жерців ур'кьо"}},{q="Яке значення має здібність «Тіньова варта»?",a="«Тіньова варта» — захисний оберіг, властивий лише жерцям-тролям. Скликаючи тіньових духів і благословення лоа, він з'являється як тіні, що кружляють довкола й б'ють у відповідь кожного ворога, який наважиться напасти на заклинача.",al={"що таке тіньова варта","переказ про закляття тіньова варта","чому це важливо"}},{q="Чи отримують це завдання інші раси?",a="Цей заклик — виключно для жерців-тролів Темного Списа, що опинилися в Андерсіті приблизно на двадцятому колі досвіду. Жерці Відступників мають власні обряди й навчання в Культі Забутої Тіні.",al={"чи нежить може це взяти","чи це лише для тролів","завдання жерців за расою"}},{q="Де в Оргріммарі знайти Ур'кьо?",a="Ур'кьо — у Долині Духів, південному кварталі Оргріммара, відведеному для тролів Темного Списа та їхніх містичних практик.",al={"де ур'кьо","де знайти ур'кьо","знайти ур'кьо"}}},fp="11,383,27.423.0,21.376.0,22.200.0,51.276.0,14.192.0,52.211.0,34.241.0,37.145.0"}
P.entries["quest:5644"] = {n="Ненажерлива чума",s="«Ненажерлива чума» — завдання-посвята для жерців-Відступників, що мандрують далеко від Лордерона. За настановою Майлза Велша, наставника жерців-Відступників у Тандер Блафі, учень вирушає назад за море, до Елталісти в Андерсіті, щоб опанувати один із найвиразніших проявів магії Тіні.",h="«Ненажерлива чума» — завдання-посвята для жерців-Відступників, що мандрують далеко від Лордерона.",kw={"ненажерлива чума","жрець","відступники","майлз велш","елталіста","андерсіті","магія тіні"},ang={["class:Priest"]="Це завдання — важлива віха в навчанні жерця-Відступника: перехід від основ віровчення до моторошних традицій Тіні, властивих лише нежиті.",["faction:Horde"]="Це завдання показує зв'язки — і практичні, і духовні, — що пов'язують далекі осередки Орди в Малгорі безпосередньо з темним серцем Андерсіті.",["race:Undead"]="На відміну від Світла, якому вони служили за життя, жерці-Відступники приймають жорстокі прокляття й магію Тіні, а Ненажерлива чума — уособлення їхньої самобутньої магії."},sec={{t="Поклик додому",b="Перебуваючи в Тандер Блафі, жерці-Відступники, що вдосконалили свою майстерність у божественних і тіньових дисциплінах, проходять оцінку в Майлза Велша — посланця Культу Забутої Тіні серед тауренів. Побачивши, що послушник набрав достатньо сили, Майлз велить йому повернутися до Руїн Лордерона, а не намагається сам відкрити ці вищі таємниці в Калімдорі."},{t="Таємниці Елталісти",b="Під руїнами міста, у Воєнному Кварталі Андерсіті, чекає Елталіста — одна з найвидатніших наставниць жрецтва Відступників. Вона стежить за розвитком послушників, що плетуть тіні, і пильнує, щоб могутню, виснажливу пошесть, відому як Ненажерлива чума, довіряли лише тим, хто здатен керувати її згубною силою, не піддаючись їй."}},faq={{q="Хто посилає мене на це завдання?",a="Майлз Велш, наставник жерців-Відступників в Ставках Видінь під Узвишшям Духів у Тандер Блафі, посилає вас у цю подорож, коли ваші здібності достатньо зміцніють.",al={"хто починає ненажерливу чуму","хто дає ненажерливу чуму","роль майлза велша"}},{q="Де знайти Елталісту?",a="Елталіста — у Воєнному Кварталі Андерсіті, серед тренувальних кіл і темних провідників сили, де збираються жерці Відступників.",al={"де елталіста","де знайти елталісту","здати ненажерливу чуму"}},{q="Чому Майлз Велш не може сам навчити цього закляття?",a="Деякі засадничі таємниці тіньової віри Відступників зберігають для майстрів-наставників на кшталт Елталісти в самому серці Андерсіті. Велш шанує цю ієрархію й відсилає гідних учнів додому на випробування.",al={"чому їхати до андерсіті","чому йти до елталісти","наставниця жерців в андерсіті"}},{q="Що таке «Ненажерлива чума» з погляду переказів?",a="Це руйнівне прокляття, яке практикує Культ Забутої Тіні: воно вражає жертву лютою магічною недугою, що пожирає її життєву силу й відновлює заклинача.",al={"що таке ненажерлива чума","переказ про ненажерливу чуму","хвороба відступників закляття"}},{q="Чи доступне це завдання іншим расам?",a="Ні. Завдання «Ненажерлива чума» пов'язане виключно з жрецтвом Відступників і відображає особливу філософію та магічні практики, що народилися серед мертвих уцілілих Лордерона.",al={"чи тролі можуть взяти ненажерливу чуму","чи орки можуть взяти ненажерливу чуму","чи це завдання лише для нежиті"}},{q="Звідки взагалі наставник-Відступник у Тандер Блафі?",a="Після вступу Відступників до Орди між столицями обмінялися дипломатами й наставниками. Жерці на кшталт Майлза Велша представляють духовні традиції Андерсіті й наставляють Відступників, що мандрують Калімдором.",al={"чому нежить у тандер блафі","відступники в тандер блафі","майлз велш тандер блаф"}}},fp="16,291,14.384.0,26.361.0,28.184.0,29.139.0,46.211.0,49.177.0,39.171.0,62.235.0"}
P.entries["quest:5645"] = {n="Без страху",s="Без страху — виклик-посвята для дворфійських жерців, що кличе обдарованих учнів назад до величних залів Айронфорджа. Верховний Жрець Роган чекає в Кварталі містиків, щоб перевірити їхню дисципліну й передати науку, що відповідає їхній дедалі більшій стійкості.",h="Без страху — виклик-посвята для дворфійських жерців, що кличе обдарованих учнів назад до величних залів...",kw={"без страху","жрець","верховний жрець роган","айронфордж","дворфи","страх"},ang={["class:Priest"]="Цей виклик знаменує ваше повноліття в жрецтві: ви готові опанувати особливі святі прийоми, відточені стійким духовенством Айронфорджа.",["faction:Alliance"]="Жрецькі спільноти Альянсу тісно спілкуються між столицями й посилають послушників через кордони навчатися в майстрів духовенства Айронфорджа.",["race:Dwarf"]="Повертаючись до Рогана, ви вшановуєте притаманне вашому народові поєднання непохитної віри, тілесної стійкості й бойового гарту на службі Святому Світлу."},sec={{t="Виклик до Айронфорджа",b="Жерців, що служать Альянсу далеко від дому, місцеві наставники регулярно посилають звітувати до старшого духовенства свого ордену. Для дворфійських учнів цей шлях веде просто до Верховного Жреця Рогана в серці Кварталу містиків Айронфорджа. Виклик знаменує поворот: прості духовні вправи поступаються глибшому, перевіреному випробуваннями вмінню володіти святою магією."},{t="Випробування стійкості",b="Верховний Жрець Роган не просто навчає літургії: дворфійська традиція бачить у Світлі щит і непохитний оплот у бою. Прийти на це випробування — означає визнати, що посвячений пройшов хрещення вогнем у широкому світі й має досить сили духу, щоб на передовій опанувати сам страх."}},faq={{q="Яка мета цього завдання?",a="Це офіційний заклик від місцевих наставників жерців до Верховного Жерця Рогана в Айронфорджі: досвідчених послушників скеровують на вище навчання, щоб вони здобули особливі духовні дари, які практикує жрецтво міста.",al={"чому йти до рогана","що робить відсутність страху","завдання жерця 20 рівня айронфорд"}},{q="Хто такий Верховний Жрець Роган?",a="Верховний Жрець Роган — старший провідник дворфійського жрецтва в Айронфорджі. Він навчає учнів у Залі Таїнств у Кварталі містиків, наголошуючи на непохитній відданості й бойовій стійкості.",al={"хто такий роган","переказ про верховного жреця рогана"}},{q="Де знайти Верховного Жерця Рогана?",a="Роган — у Залі Таїнств у Кварталі містиків, у західних кварталах Айронфорджа.",al={"де роган","де знайти рогана","як знайти верховного жреця рогана"}},{q="Чому завдання називається «Без страху»?",a="Завдання — це підготовка жерця до «Оберегу від страху», особливого захисного благословення, яке плекають дворфійські служителі Святого Світла, щоб уберегти розум від паніки й надприродного жаху.",al={"значення назви без страху","завдання оберіг від страху"}},{q="Хто посилає жерця до Айронфорджа?",a="Послушників зазвичай посилають їхні місцеві наставники — як-от Верховна Жриця Лаурена в Стормвінді чи Жриця Алатея в Дарнасусі, — щоб учні вшанували свою спадщину чи повчилися під проводом Рогана.",al={"хто починає без страху","хто дає завдання без страху"}},{q="Чи є в цьому завданні бій?",a="Ні. Треба лише дістатися Айронфорджа й поговорити з Верховним Жерцем Роганом, який навчає «Оберегу від страху».",al={"чи треба битися","чи є бій у завданні без страху"}}},fp="14,258,22.369.0,23.326.0,34.231.0,25.202.0,37.112.0,36.203.0,34.221.0,31.103.0"}
P.entries["quest:5646"] = {n="Ненажерлива чума",s="«Ненажерлива чума» — завдання-посвята для жерців-Відступників, які вирушили до Калімдору вчитися в племені Темного Списа. Наставник жерців, троль Ур'кьо з Оргріммара, відсилає здібних учнів-Відступників додому, до Андерсіті, де на них чекає Елталіста, щоб відкрити глибші вчення Культу Забутої Тіні.",h="«Ненажерлива чума» — завдання-посвята для жерців-Відступників, які вирушили до Калімдору вчитися в племені...",kw={"жрець","відступники","ненажерлива чума","елталіста","ур'кьо","андерсіті","культ забутої тіні"},ang={["class:Priest"]="Жерці-Відступники черпають силу з особливих расових доктрин тіні й тління та вчаться перетворювати власні тілесні муки на нищівні прокляття, як-от Ненажерлива чума.",["faction:Horde"]="Спільне навчання жерців, яке ведуть Ур'кьо в Дуротарі та Елталіста в Тірісфалі, показує, як практична співпраця й взаємна повага зв'язують далекі одна від одної столиці Орди.",["race:Undead"]="Повернення до Воєнного Кварталу Андерсіті нагадує вам, що ваша справжня вірність і духовне коріння — під руїнами Лордерона, хоч куди б вас закинули обов'язки перед Ордою."},sec={{t="Обмін вірою",b="Орки й таурени не надто схильні до жрецького служіння, а от тролів Темного Списа й Відступників поєднує в Орді незвичайний богословський зв'язок. В Оргріммарі наставник жерців, троль Ур'кьо, веде тих, кого вабить духовна сила. Та він розуміє, що Відступники зрештою мусять опанувати похмуре мистецтво, властиве лише їхній природі. На знак взаємної поваги між їхніми народами Ур'кьо відсилає мандрівних Відступників назад до Лордерона завершити навчання."},{t="Воєнний Квартал Андерсіті",b="Під руїнами Лордерона, у Воєнному Кварталі Андерсіті, Жриця Елталіста опікується своєю паствою. Жерці-Відступники йдуть самотнім і виснажливим шляхом Культу Забутої Тіні, врівноважуючи болісний для них дотик Святого Світла нищівною силою магії Тіні. Коли учень набуває достатньої вправності, Елталіста кличе його до себе, щоб передати чари, які її народ називає Ненажерливою чумою."}},faq={{q="Хто посилає мене на це завдання?",a="Ур'кьо, наставник жерців-тролів серед духів Оргріммара, дає це завдання жерцям-Відступникам, що досягли двадцятого кола сили.",al={"хто дає завдання","хто починає ненажерливу чуму","де ур'кьо"}},{q="Куди треба йти?",a="Треба перепливти Велике Море до Андерсіті в Галявинах Тірісфалю й знайти Жрицю Елталісту, що опікується навчанням жерців Відступників у Воєнному Кварталі.",al={"де здати","де елталіста","наставниця жерців в андерсіті"}},{q="Чому Ур'кьо відсилає Відступників назад до Лордерона?",a="Ур'кьо дотримується домовленості з Жрицею Елталістою. Тролячі жерці Тіні розуміються на лоа й духах, а Відступники орудують темними мистецтвами, пов'язаними саме з їхньою мертвою природою, тож навчатися мусять безпосередньо у власних провідників.",al={"чому повертатися до андерсіті","чому жрець-троль відсилає мене"}},{q="Яке значення має «Ненажерлива чума»?",a="«Ненажерлива чума» — сильне прокляття, властиве лише Відступникам, що практикують Тінь. Воно вражає цілі руйнівною хворобою й водночас висмоктує їхню життєву силу просто до заклинача.",al={"переказ про ненажерливу чуму","чума жерців відступників"}},{q="Чи можуть інші раси Орди взяти це завдання?",a="Ні. Це завдання пропонують виключно жерцям-Відступникам — як знак їхньої єдності з особливими тіньовими науками батьківщини.",al={"чи тролі можуть це взяти","чи це завдання лише для нежиті"}},{q="Яке місце це посідає у стосунках жерців Орди?",a="Орда покладається на взаємний обмін між знахарями й жерцями-вроковниками Темного Списа в Калімдорі та жерцями Тіні з Відступників у Східних Королівствах: кожні скеровують мандрівників до майстрів, що найкраще пасують до їхньої культури.",al={"тролі й жерці нежиті","переказ про жерців орди"}}},fp="16,324,20.493.0,28.433.0,27.158.0,22.168.0,48.239.0,49.194.0,40.136.0,46.220.0"}
P.entries["quest:5648"] = {n="Шати Духовності",s="Шати Духовності — обряд посвяти для жерців-початківців Орди в Дуротарі, який доручає Тай'джин у Гострому Пагорбі. Новачків посилають у поле знайти й зцілити рани пораненого піхотинця, що стоїть на варті проти вцілілих із Кул Тірасу. Виконавши завдання, жрець здобуває свої перші обрядові шати й офіційне визнання серед духовних служителів Орди.",h="Шати Духовності — обряд посвяти для жерців-початківців Орди в Дуротарі, який доручає Тай'джин у Гострому...",kw={"жрець","тай'джин","шати духовності","гострий пагорб","кор'я","зцілення"},ang={["class:Priest"]="Цей обряд посвяти — головне раннє випробування для жерців Орди в Дуротарі: він підтверджує ваші навички зцілення в полі й дарує перші шати.",["faction:Horde"]="Порятунок Піхотинця Кор'ї напряму зміцнює оборону Гострого Пагорба проти людей Кул Тірасу, що досі окопалися поблизу.",["race:Troll"]="Наставництво Тай'джина вплітає духовність тролівських предків у практичний бойовий обов'язок, щоб молоді воїни Темного Списа своєю вірою захищали союзників."},sec={{t="Випробування цілителя",b="У посушливих чагарях на південь від Гострого Пагорба Орда веде невпинні сутички з рештками війська великого адмірала Дейліна Праудмура. Замість того щоб відправляти майбутніх жерців на відірвані від життя ритуали, наставник-троль Тай'джин перевіряє їхню дисципліну в справжній бойовій медицині. Новачкам доручають розшукати воїтельку, тяжко поранену під час відбиття людських лазутчиків, — це Піхотинець Кор'я, і її рани треба обробити, а сили підкріпити, перш ніж вона згасне."},{t="Шати вірних",b="Повернувши Кор'ю до бойової готовності, молодий жрець доводить, що готовий нести мантію духовної традиції Орди. На знак порятунку захисниці передової Тай'джин дарує Шати Духовності. І для орків-союзників, і для тролів Темного Списа ці шати означають, що їхній носій — не просто учень, який зубрить заклинання, а надійна опора, здатна зберігати життя воїнам Орди в бою."}},faq={{q="Хто така Піхотинка Кор'я і чому їй потрібне зцілення?",a="Піхотинка Кор'я — воїтелька Орди, що стоїть трохи на південь від Гострого Пагорба. Її поранили в сутичці з уцілілими вояками експедиції Адмірала Праудмура з Кул Тіраса, що досі непокоять узбережжя Дуротару.",al={"піхотинка кор'я","хто така кор'я","поранена піхотинка на півдні"}},{q="Де знайти Тай'джин?",a="Тай'джин — на Гострому Пагорбі в Дуротарі. Вона духовна наставниця й наставниця жерців для молодих шукачів пригод Орди, що виходять із Долини Випробувань.",al={"де тай'джин","хто дає шати духовності","наставниця жерців разор гілл"}},{q="Які сили потрібні, щоб зцілити Кор'ю?",a="Жерці мають підлікувати рани Кор'ї закляттям «Мале зцілення» й зміцнити її витривалість благословенням «Слово Сили: Стійкість», а тоді повернутися до Тай'джин.",al={"які закляття застосувати","як виконати шати духовності","закляття кор'ї"}},{q="Чому вояки Кул Тіраса досі воюють у Дуротарі?",a="Після вторгнення й поразки Великого Адмірала Праудмура рештки його флоту розпорошилися по східному узбережжю Дуротару. Вони й далі влаштовують відчайдушні набіги й закріплюються в таких місцях, як Фортеця Тіраґард.",al={"вояки проудмура в дуротарі","чому люди в разор гілл","залишки кул тіраса"}},{q="Яке значення мають шати, які дають у нагороду?",a="Роби від Тай'джин знаменують перехід послушника до справжнього цілителя Орди. Витримавши цю практичну перевірку, учень здобуває право носити облачення свого покликання.",al={"переказ про нагороду шати","навіщо давати мантію","жрецьке облачення разор гілл"}},{q="Яке завдання передує «Шатам Духовності»?",a="Це випробування йде після «В ім'я духовності» — вступного завдання, яке Тай'джин дає, коли жрець пройде достатнє початкове навчання на Гострому Пагорбі.",al={"попереднє завдання","перед шатами духовності","як почати шати"}}},fp="24,382,16.462.0,25.429.0,50.208.0,25.154.0,40.154.0,53.209.0,49.192.0,45.157.0"}
P.entries["quest:5649"] = {n="В ім'я духовності",s="«В ім'я духовності» — основоположний обряд посвяти для молодих жерців Темного Списа, що покидають Долину Випробувань. За наказом Кен'джая новачки вирушають до наставника жерців Тай'джина в Гострий Пагорб і роблять перші справжні кроки за межі усамітненого тренувального лігва назустріч ширшим викликам Дуротару. Ця подорож показує тонку рівновагу, яку Темний Спис тримає між шаною до тролівської спадщини предків і входженням до новоствореної Орди.",h="«В ім'я духовності» — основоположний обряд посвяти для молодих жерців Темного Списа, що покидають Долину...",kw={"жрець","кен'джай","тай'джин","темний спис","гострий пагорб","духовність"},ang={["class:Priest"]="Це завдання знаменує ваш вихід із каньйону новачків до справжнього навчання й перших шат від Тай'джина в Гострому Пагорбі.",["faction:Horde"]="Воно показує, як різні культури співпрацюють у Дуротарі, поєднуючи дикі традиції Островів Відлуння з військовою заставою Гострого Пагорба.",["race:Troll"]="Ця місія відображає напругу, з якою Темний Спис живе щодня: рівновагу між вірністю Орді та збереженням давньої племінної духовності."},sec={{t="Прощання з червоним каньйоном",b="Опанувавши основні обряди під проводом Кен'джая в усамітненій Долині Випробувань, послушники Темного Списа готові залишити тренувальні землі позаду. Звивисті стежки виводять у Дуротар і ведуть просто до поселення на роздоріжжі — Гострого Пагорба. Для молодого жерця ця подорож — важлива віха: від простих вправ на виживання в пилюці до духовної та культурної відповідальності за плем'я."},{t="Стара віра й нові союзи",b="Кен'джай відверто говорить про становище Темного Списа в Орді Тралла. Тролі глибоко цінують вірність орків та їхні уроки честі, та не кожна традиція предків легко вписується під пильним поглядом союзників. Духовні провідники Темного Списа навчають учнів тихо берегти свою спадщину — міцно триматися своєї сутності й водночас служити Орді. Тай'джин у Гострому Пагорбі приймає цих послушників у це глибше розуміння й веде їх до самодостатності та сили громади."}},faq={{q="Хто дає завдання «В ім'я духовності»?",a="Завдання дає Кен'джай — наставник жерців-тролів у Лігві в Долині Випробувань.",al={"хто починає в ім'я духовності","хто дає в ім'я духовності","завдання жерця кен'джай"}},{q="Де знайти Тай'джин?",a="Тай'джин — у казармах на Гострому Пагорбі, на схід від центру містечка при головній дорозі Дуротару.",al={"де тай'джин","де тай джин","знайти тай'джин"}},{q="Які класи можуть узяти це завдання?",a="Це завдання пропонують виключно жерцям-тролям, що починають свій шлях у Дуротарі.",al={"чи це завдання лише для жерців","хто може взяти в ім'я духовності","завдання класу жерця разор гілл"}},{q="Чому Кен'джай наголошує, що деякі традиції треба тримати в таємниці?",a="Кен'джай розуміє: хоч орки — вірні товариші, що цінують честь, не кожен давній тролячий обряд чи звичай вони сприймають прихильно. Він учить молодих жерців шанувати прадавню спадщину стримано, щоб зберегти злагоду в Орді.",al={"чому таємні традиції тролів","орки й тролі релігія","чому практикувати таємно"}},{q="Чого Тай'джин навчає молодого жерця, коли той прибуває?",a="Тай'джин пояснює, що Темний Спис став сильнішим, пристосувавшись до життя в Орді. Замість того щоб чекати й черпати силу просто з полеглих ворогів, плем'я тепер готується заздалегідь і йде в бій уже посиленим.",al={"що каже тай'джин","що тай джин говорить","пристосування дарґспір"}},{q="Яке завдання йде одразу після «В ім'я духовності»?",a="Коли ви здасте це завдання, Тай'джин запропонує «Шати Духовності», що посилає послушника допомогти пораненому воякові Орди в полі.",al={"що після в ім'я духовності","в ім'я духовності продовження","наступне завдання жерця після тай'джин"}}},fp="24,462,22.427.0,28.509.0,45.105.0,25.114.0,35.86.0,58.247.0,54.233.0,56.142.0"}
P.entries["quest:5650"] = {n="Шати Темряви",s="Шати Темряви — засадничий обряд посвяти для молодих жерців Відступників у Бріллі. Темна Клірикиня Берил доручає посвяченим зцілити й зміцнити пораненого Вартового Смерті, перевіряючи їхнє володіння магією підтримки, перш ніж вони зануряться глибше в тіні.",h="Шати Темряви — засадничий обряд посвяти для молодих жерців Відступників у Бріллі.",kw={"шати темряви","берил","жрець","зцілення","вартовий смерті кел","брілл"},ang={["class:Priest"]="Цей обряд утілює філософію жрецтва Відступників: урівноважити похмуру користь Тіні з незамінним обов'язком зміцнювати й зцілювати союзників.",["race:Undead"]="Для Відступників магія зцілення — прагматичне знаряддя виживання, яким підтримують бійців передової на кшталт Вартового Смерті Кела проти гнолів і недобитків Погибелі."},sec={{t="Рівновага темряви і світла",b="Хоч жрецтво Відступників завдячує славою і своєрідністю тіні й темряві, його старійшини визнають незмінну практичну потребу у відновленні. Темна Клірикиня Берил навчає: щоб розуміти темряву, треба розуміти світло й мистецтво зцілення. Жерцю, який прагне лише руйнування, радять натомість вивчати таємну магію; справжнє покликання жрецтва — зміцнювати й берегти товаришів не менше, ніж уражати ворогів."},{t="Обов'язок на цвинтарі",b="Щоб довести майстерність, посвяченого посилають на північ від цвинтаря Брілла — на поміч Вартовому Смерті Келу. Стоячи проти зграй гнолів, що нишпорять поблизу, Кел зазнав поранень, утримуючи рубіж. Загоївши його рани зцілювальними заклинаннями й зміцнивши витривалість захисними чарами, учень доводить, що здатен підтримувати захисників Галявин Тірісфалю, і здобуває від Берил облачення та допуск до вищих таїнств жрецтва."}},faq={{q="Навіщо жерцям-Відступникам цілюща магія, якщо їхня сила йде від темряви?",a="Темна Клірикиня Берил пояснює: хоча жерці Відступників черпають неабияку силу з Тіні, зцілення лишається необхідним. Перш ніж опанувати темряву, послушник мусить зрозуміти допоміжну й відновлювальну магію, щоб захисники Відступників трималися на полі бою.",al={"чому нежить зціляє","цілення жерців відступників","тінь чи світло нежить"}},{q="Хто такий Вартовий Смерті Кел?",a="Вартовий Смерті Кел — вартовий Відступників на північ від цвинтаря в Бріллі. Він захищає місцеві поселення від агресивних зграй гнолів, що никають лісами, і, поранений на службі, потребує допомоги.",al={"переказ про вартового смерті кела","хто такий вартовий смерті кел","поранений вартовий смерті"}},{q="Хто дає це завдання?",a="Завдання дає Темна Клірикиня Берил — наставниця жерців у Бріллі в Галявинах Тірісфалю, — коли ви виконаєте попереднє завдання «В ім'я Темряви».",al={"хто починає шати темряви","хто дає шати темряви"}},{q="Яке облачення дають наприкінці випробування?",a="Берил вручає шиту на замовлення робу як знак становища й досягнення: вона символізує, що жрець опанував основні обов'язки й здобув визнання серед побратимів.",al={"яку мантію дають","нагорода шати жерця"}},{q="З якими загрозами бився Вартовий Смерті Кел?",a="Кела поранили в бою з місцевими гнолами, що заполонили навколишню глушину Галявин Тірісфалю на північ від цвинтаря Брілла.",al={"хто напав на кела","кел і гноли"}},{q="На які темніші сили натякає Темна Клірикиня Берил?",a="Берил натякає на тіньові прийоми, властиві лише жрецтву Відступників, — особливі прояви магії Тіні й розумових мук, яких не практикують жерці інших рас.",al={"унікальні закляття жерців відступників","натяк на темніші сили"}}},fp="20,264,27.460.0,23.433.0,77.263.0,22.212.0,21.158.0,52.170.0,41.134.0,50.174.0"}
P.entries["quest:5651"] = {n="В ім'я Темряви",s="В ім'я Темряви знаменує перехід жерця Відступників від початкових склепів Похоронного Подзвону до поглибленого навчання у Бріллі. За дорученням Темного Клірика Дюстена молодий учень вирушає вчитися в Темної Клірикині Берил — опановувати тонку рівновагу між Святим Світлом і Тінню.",h="В ім'я Темряви знаменує перехід жерця Відступників від початкових склепів Похоронного Подзвону до...",kw={"в ім'я темряви","дюстен","берил","жрець","світло","тінь","брілл"},ang={["class:Priest"]="Це завдання втілює засадничу філософію жрецтва Відступників: володіти і Святим Світлом, і Тінню з холодною розважливістю, а не з релігійним благоговінням.",["race:Undead"]="Шлях від Похоронного Подзвону до Брілла — звична перша вилазка в ширші володіння Відступників; вона показує посвяченим, як їхній народ відбудовується на руїнах Лордерону."},sec={{t="Шлях, прокладений у гнилі",b="Жерці інших рас шанують Святе Світло як незаплямоване джерело моральної чесноти, а Відступники підходять до віри крізь суворий досвід власного нежиття. Як навчає Темний Клірик Дюстен, Відступників викувано у скверні й викинуто, наче падло. Щоб вижити, їм треба розуміти і Світло, і Тінь — без сентиментів. «В ім'я Темряви» виводить нових учнів із замкненого цвинтаря Похоронного Подзвону назустріч ширшій дійсності, що чекає на них у Галявинах Тірісфалю."},{t="Навчання у Бріллі",b="Дорога на північний схід від Похоронного Подзвону веде молодого жерця через критий дерев'яний міст у зруйноване містечко Брілл. Там, у горішніх кімнатах місцевого заїзду, Темна Клірикиня Берил чекає, щоб випробувати рішучість посвяченого. Берил цінує амбіції й холодну практичність понад сліпу відданість і вимагає, щоб жрець Відступників володів божественною силою як зброєю і знаряддям, а не моральною милицею."}},faq={{q="Яка мета цього завдання?",a="Це обряд посвяти для жерців-Відступників, що покидають Похоронний Подзвін. Темний Клірик Дюстен посилає вас до Темної Клірикині Берил у Бріллі, щоб ви продовжили навчання й отримали наступне жрецьке випробування.",al={"що робить це завдання","чому в ім'я темряви","мета в ім'я темряви"}},{q="Навіщо жерцям-Відступникам Світло, якщо вони обрали темряву?",a="Служителі Відступників визнають, що світ тримається на рівновазі Світла й Тіні. Хоча Святе Світло завдає мертвій плоті нестерпного болю, а їхнє походження — у тліні й темряві, вони вивчають обидві сили з практичних міркувань і з потреби.",al={"чому жерці нежиті користуються світлом","переказ про жерців відступників","світло й тінь нежиті"}},{q="Де знайти Темну Клірикиню Берил?",a="Темна Клірикиня Берил — у містечку Брілл на північний схід від Похоронного Подзвону. Вона на другому поверсі Таверни «Шибеничний Кінець» на східному боці поселення.",al={"де темна клірикиня берил","де берил","знайти берил"}},{q="До чого веде це завдання?",a="Розмова з Темною Клірикинею Берил завершує це доручення й відкриває наступне завдання «Шати Темряви», де вона перевіряє, чи вмієте ви лікувати й підтримувати союзників своїми новими вміннями.",al={"що далі","наступне завдання після в ім'я темряви","продовження в ім'я темряви"}},{q="Хто такий Темний Клірик Дюстен?",a="Темний Клірик Дюстен — наставник жерців у Похоронному Подзвоні. Він допомагає щойно пробудженим жерцям-Відступникам зрозуміти своє болісне існування й скористатися своїми духовними силами.",al={"хто дає це завдання","переказ про дюстена","темний клірик дюстен"}},{q="Чому Берил ставить честолюбство вище за віру?",a="Жерці-Відступники вважають традиційну побожну віру недостатньою, адже сили, яким вони поклонялися за життя, їх покинули. Темна Клірикиня Берил чекає, що учні покладатимуться на особисте честолюбство, рішучість і практичну силу, щоб вижити.",al={"що означають слова берил","чому честолюбство а не віра","віра відступників"}}},fp="20,304,20.495.0,20.409.0,34.199.0,63.260.0,34.172.0,31.192.0,27.187.0,43.232.0"}
P.entries["quest:5654"] = {n="Вроки слабкості",s="«Вроки слабкості» — одне з перших завдань-посвят для юних жерців-тролів із племені Темного Списа, які вже довели, чого варті, на Гострому Пагорбі. Тай'джин відсилає учня на північ, до Оргріммара: там він має розшукати Ур'кьо, щоб глибше увійти в духовне коло племені й пізнати темніші мистецтва лоа.",h="«Вроки слабкості» — одне з перших завдань-посвят для юних жерців-тролів із племені Темного Списа, які вже...",kw={"жрець","тролі","вроки слабкості","тай'джин","ур'кьо","гострий пагорб","долина духів","лоа"},ang={["class:Priest"]="На відміну від догм Святого Світла чи Забутої Тіні, жрецтво тролів спирається на глибоке єднання з первісними духами й поєднує племінні вроки з традиційними чарами тіні та зцілення.",["faction:Horde"]="Шлях від Гострого Пагорба до Долини Духів відображає, як культура тролів вростає в укріплені мури столиці Тралла, що невпинно розбудовується.",["race:Troll"]="Цей обряд знаменує ваш перехід від новачка з Гострого Пагорба до визнаного жерця племені Темного Списа, що опановує прадавні прокляття, передані крізь покоління."},sec={{t="Поклик до кола",b="Для молодого жерця-троля в Дуротарі навчання триває в казармах Гострого Пагорба під пильним оком Тай'джин. Щойно послушник опановує основи рівноваги між духовним єднанням і магією тіні, початкове навчання закінчується. Тай'джин спрямовує здібного жерця геть від Гострого Пагорба, на північ через каньйони червоної землі — до столиці Орди, де старші чаклуни опікуються ширшими магічними традиціями племені."},{t="Давні звичаї в Долині Духів",b="В Оргріммарі Темний Спис має власне самобутнє святилище — Долину Духів, віддалену від гуркоту кузень і бойових майданчиків орків. Тут, серед високих тотемів і затінених хатин, на нових учнів чекає старший жрець Ур'кьо. Увійти до його кола означає прийняти прадавні традиції тролів джунглів: шанувати лоа предків і водночас володіти могутніми прокляттями й вроками, що висмоктують силу з ворога в бою."}},faq={{q="Яка мета цього завдання?",a="Завдання знаменує офіційний поступ послушника в жрецтві Темного Списа. Тай'джин посилає жерців-тролів, що зростають, з узбережжя Дуротару до Ур'кьо в Оргріммарі, офіційно приймаючи їх до внутрішнього кола духовних практиків племені.",al={"навіщо це завдання","мета вроків слабкості","що робить завдання вроки слабкості"}},{q="Хто така Тай'джин?",a="Тай'джин — наставниця жерців-тролів у казармах Гострого Пагорба в Дуротарі. Вона веде наймолодших заклиначів Темного Списа крізь перші випробування, а тоді відсилає їх до столиці.",al={"хто дає завдання","переказ про тай'джин","тай'джин"}},{q="Хто такий Ур'кьо?",a="Ур'кьо — старий наставник жерців-тролів у Долині Духів в Оргріммарі. Він керує вищим духовним навчанням і передає жерцям Темного Списа племінні вроки й глибокі обряди предків.",al={"хто такий ур'кьо","наставник жерців ур'кьо","ур'кьо"}},{q="Де Долина Духів?",a="Долина Духів — відокремлений болотистий квартал на заході Оргріммара. Це головна оселя тролів Темного Списа в орківському місті-фортеці, де живуть їхні наставники, стоять їхні житла й тотеми.",al={"де долина духів","де ур'кьо","де знайти ур'кьо"}},{q="На якій магії зосереджене це навчання?",a="Жерці Темного Списа звертаються до «давніх шляхів», черпаючи силу з лоа й прадавніх традицій тролів джунглів. Замість покладатися лише на Святе Світло, яке шанують люди й дворфи, жерці-тролі поєднують цілющу магію духів із виснажливими прокльонами на кшталт «Вроків слабкості».",al={"магія жерців-тролів","що таке давні шляхи","переказ про вроки"}},{q="Чи можуть не-тролі взятися за це завдання?",a="Ні. Це завдання пов'язане саме з культурними традиціями й особливими закляттями тролів Темного Списа. Жерців-нежить скеровують до їхніх власних наставників і тіньових учень у Тірісфалі й Андерсіті.",al={"чи нежить може це взяти","чи це лише для тролів"}}},fp="15,304,23.451.0,37.478.0,34.252.0,15.202.0,14.205.0,31.208.0,47.277.0,36.213.0"}
P.entries["quest:567"] = {n="Небезпечно!",s="Це оголошення нагороди, вивішене на дошці розшуку в Таррен Міллі, засуджує на страту чотирьох відомих мешканців Гілсбреда. Верховний Екзекутор Дарталія оголосила їх небезпечними ворогами Відступників за конкретні вбивства й засідки на обози.",h="Це оголошення нагороди, вивішене на дошці розшуку в Таррен Міллі, засуджує на страту чотирьох відомих...",kw={"небезпечно","розшук","дарталія","таррен мілл","гілсбред","скрадач смерті фрай","завдання"},ang={["class:Rogue"]="Вистежувати прихованих ватажків на ворожій землі — те саме таємне ремесло, яким жив Скрадач Смерті Фрай, за чию смерть мститься це доручення.",["faction:Horde"]="Щоб убезпечити Передгір'я Гілсбреда, треба зламати найзапекліших ватажків людського ополчення й гарантувати безпеку пересувань Орди краєм.",["race:Undead"]="Помста за полеглих Вартових Смерті, Аптекарів і скрадачів смерті — справа похмурої гордості для кожного вірного слуги Темної Леді."},sec={{t="Справа відплати",b="Передова в Передгір'ї Гілсбреда жорстока й особиста. Для Верховного Екзекутора Дарталії та гарнізону Відступників у Таррен Міллі звичайні мешканці Гілсбреда стали смертельно небезпечними бійцями. Оголошення про розшук називає чотирьох конкретних людей, чий опір коштував життя Відступникам і цінних вантажів з Андерсіті."},{t="Цілі Таррен Мілла",b="У списку нагород названо Клерка Горраса Вайтстіда — за вбивство Вартового Смерті Томи, Громадянина Вілкса — за вбивство Аптекаря Елі, Шахтаря Гакетта — за те, що позбавив життя Скрадача Смерті Фрая, і Фермера Калабу — за диверсії проти обозів із припасами, посланих з Андерсіті. Кожна ціль діє з окремого осередку опору Гілсбреда й лишається невловимою серед хаосу ширшого конфлікту."}},faq={{q="Хто оголосив винагороду «Небезпечно!»?",a="Верховний Екзекутор Дарталія, командувачка сил Відступників у Таррен Міллі, оголосила винагороду за чотирьох помітних людей Гілсбреда.",al={"хто оголосив небезпечно","хто дав завдання небезпечно","винагорода дарталії"}},{q="Чому розшукують саме цих людей?",a="Кожен із них завдав удару Відступникам: Клерк Горрас Вайтстід убив Вартового Смерті Тому, Громадянин Вілкс замордував Аптекаря Елі, Шахтар Гакетт убив Скрадача Смерті Фрая, а Фермер Калаба влаштував засідку на важливі припаси з Андерсіті.",al={"чому вони небезпечні","що вони зробили","злочини цілей у гілсбреді"}},{q="Де шукати цілі?",a="Усі четверо засіли в людських поселеннях і на робочих місцях Передгір'я Гілсбреда, ховаючись серед містян, на фермах і в шахтах.",al={"де шукати цілі","місця завдання небезпечно","де гекетт"}},{q="Яка стратегічна мета цього замовлення?",a="Окрім звичайної помсти, знищення цих провідників підриває місцевий людський опір і захищає патрулі та шляхи постачання Відступників між Таррен Міллом і Андерсіті.",al={"навіщо їх убивати","мета винагороди в гілсбреді","стратегія таррен мілл"}},{q="Чи пов'язано це з «Битвою за Гілсбред»?",a="Так. Цілі цієї винагороди живуть саме на тих фермах, у тих шахтах і в тих центрах містечок, які сили Відступників штурмують під час ширшого наступу в «Битві за Гілсбред».",al={"зв'язок з битвою за гілсбред","битва дарталії","наступ на гілсбред"}},{q="Кому здати докази, коли цілі вбито?",a="Докази їхнього знищення треба доставити просто Верховному Екзекуторові Дарталії в Таррен Мілл.",al={"хто завершує небезпечно","здати небезпечно","здати дарталії"}}},fp="10,235,23.338.0,22.381.0,33.142.0,37.241.0,30.144.0,47.175.0,45.160.0,44.91.0"}
P.entries["quest:5672"] = {n="Грація Елуни",s="«Грація Елуни» — обряд визнання для побожних жерців нічних ельфів у Дарнасусі. Довівши свою віру й дисципліну в перших мандрах, жерці постають перед Жрицею Алатеєю, щоб отримати глибші настанови в божественних таїнствах Богині Місяця.",h="«Грація Елуни» — обряд визнання для побожних жерців нічних ельфів у Дарнасусі.",kw={"грація елуни","жриця алатея","храм місяця","сестринство елуни","жрець","дарнасус"},ang={["class:Priest"]="Цей обряд позначає розбіжність між вірою калдореїв і вченням людських та дворфійських священників, що спирається на Світло: ремесло жерця міцно вкорінюється в захисних обіймах Елуни.",["race:NightElf"]="Для калдореїв Грація Елуни — нерозривний зв'язок із давніми традиціями, які береже Сестринство Елуни."},sec={{t="Священне покликання",b="У Храмі Місяця в Дарнасусі Сестринство Елуни веде молодих послушників від перших молитов до володіння місячною магією. Нічні ельфи дивляться на Святе Світло не так, як люди чи дворфи: їхня віра нерозривно пов'язана з Місячною Матір'ю — Елуною. Коли жрець-новачок досягає важливої віхи у своїй відданості, старші наставниці це помічають і визнають учня готовим нести більшу божественну силу."},{t="Благословення Богині Місяця",b="Жриця Алатея надсилає цей заклик від імені Сестринства. Вона визнає, що відданість послушника піднесла його над звичайною паствою, і відкриває йому доступ до традицій, збережених тисячоліттями. Пройшовши обряд, жрець скріплює свій зв'язок з Елуною й опановує особливі захисні обереги та місячні молитви, притаманні лише вірі калдореїв."}},faq={{q="Яка мета цього завдання?",a="Завдання — духовна віха для жерців нічних ельфів. Воно кличе послушника назад до Дарнасуса, щоб Жриця Алатея визнала його зростання й посвятила у вищі расові науки, які дарує Сестринство Елуни.",al={"навіщо грація елуни","що робить грація елуни","мета завдання"}},{q="Хто така Жриця Алатея?",a="Жриця Алатея — шанована наставниця Сестринства Елуни в Дарнасусі. Вона опікується жерцями-калдорей, що зростають, допомагаючи їм поглибити єдність із Богинею Місяця.",al={"роль алатеї","хто дає завдання","хто така алатея"}},{q="Чому цей дар — лише для нічних ельфів?",a="На відміну від жерців-людей чи дворфів, що черпають силу зі Святого Світла, жерці нічних ельфів шанують безпосередньо Елуну. Заклики сестринства — як-от «Грація Елуни» — відображають місячний захист і оборонні чари, які калдорей плекали тисячі років.",al={"чому лише нічні ельфи","переказ про расову здібність","чим відрізняється жрець елуни"}},{q="Де відбувається цей обряд?",a="На заклик відповідають у Дарнасусі — у Храмі Місяця, де збирається й навчає жрецтво міста.",al={"де алатея","місце завдання","храм дарнасуса"}},{q="Чи отримують подібний заклик інші жерці Альянсу?",a="Так. Кожна культура по-своєму підходить до жрецтва: люди й дворфи вивчають засади Святого Світла у власних наставників у Стормвінді й Айронфорджі й здобувають расові науки, відмінні від місячної магії нічних ельфів.",al={"чи люди це отримують","еквівалент для жерця-дворфа","інші раси"}},{q="Про яку міру відданості каже Алатея?",a="Алатея говорить про духовну стійкість і зрілість, здобуті у випробуваннях широкого світу. Виживання, дисципліна й непохитна вірність чеснотам Елуни доводять, що послушник може безпечно спрямовувати сильніші місячні благословення.",al={"який стан досягнуто","розмова з алатеєю","яка відданість"}}},fp="13,277,16.450.0,29.361.0,34.238.0,25.192.0,41.267.0,36.125.0,52.248.0,47.231.0"}
P.entries["quest:5674"] = {n="Грація Елуни",s="«Грація Елуни» — обряд піднесення для жерців нічних ельфів, що набираються сили; він знаменує їхню готовність володіти божественними дарами, властивими лише їхньому народові. З місцевих осель на кшталт Доланаара кандидатів скеровують назад до священного Храму Місяця в Дарнасусі, де вони постають перед Жрицею Алатеєю, щоб довести свою відданість.",h="«Грація Елуни» — обряд піднесення для жерців нічних ельфів, що набираються сили; він знаменує їхню готовність...",kw={"грація елуни","жриця алатея","лаурна морнінґлайт","доланаар","храм місяця","жрець"},ang={["class:Priest"]="Цей обряд — визначальний перехід для жерців нічних ельфів: їхня сутність вкорінюється в самобутній небесній магії Сестринства Елуни, а не в загальних святих практиках.",["race:NightElf"]="Проща до Храму Місяця утверджує центральну роль шанування Елуни в суспільстві калдореїв і кличе далеких послушників додому, у серце Дарнасуса."},sec={{t="Священна віха",b="У Сестринстві Елуни шлях жерця — це більше, ніж опанування звичних молитов зцілення й кари. Набираючись досвіду, послушники доходять порогу, за яким їх визнають готовими прийняти благословення, даровані лише калдореям. Місцеві наставниці, як-от Лаурна Морнінґлайт у Доланаарі, не мають права передавати ці глибші мистецтва, тож скеровують обдарованих учнів назад до культурного й духовного серця свого ордену."},{t="Зустріч у Храмі",b="Завдання веде посвячуваних через Тельдрассил до величного Храму Місяця в Дарнасусі. Там, під поглядом верховного жрецтва, Жриця Алатея оцінює, чи справді прохач готовий прийняти захисне покривало богині. Опанування Грації Елуни символізує справжню зрілість у жрецтві й перекидає місток від сирого хисту до офіційного служіння богині."}},faq={{q="Яка мета цього завдання?",a="Це завдання повертає до Дарнасуса жерців нічних ельфів, що набралися досить практичного досвіду. Це обряд посвяти, що скеровує їх до Жриці Алатеї в Храмі Місяця, щоб пройти випробування й навчитися оборонного мистецтва, відомого як «Грація Елуни».",al={"що робить це завдання","мета завдання грація елуни","навіщо йти до алатеї"}},{q="Хто така Жриця Алатея?",a="Жриця Алатея — високопоставлена наставниця жерців у Храмі Місяця в Дарнасусі. Вона опікується офіційним навчанням і поступом послушників нічних ельфів, стежачи, щоб вони мали духовне зосередження, потрібне для складних расових молитов.",al={"переказ про жрицю алатею","хто така алатея","алатея дарнасус"}},{q="Чому місцеві наставники не можуть навчити цієї здібності?",a="Наставники на заставах, як-от Лаурна Морнінґлайт, ведуть новачків крізь основи, але священні благословення, властиві лише калдорей, сестринство дарує тільки офіційно. Послушники мусять з'явитися в головному осередку ордену в Дарнасусі й пройти перевірку, перш ніж навчитися цих глибших дарів.",al={"чому не вчитися в доланаарі","чому йти до дарнасуса"}},{q="Що насправді означає «Грація Елуни» у вірі калдорей?",a="«Грація Елуни» — це безпосередня захисна опіка Богині Місяця. Сплетена молитвою, вона послаблює удари, що летять у жерця, — відображення того, як Елуна заступає собою своїх вірних звитяжців, коли наближається небезпека.",al={"що таке грація елуни","переказ про грацію елуни"}},{q="Чи можуть жерці інших рас отримати це благословення?",a="Ні. Мистецтво «Грації Елуни» суворо пов'язане з прадавньою вірою й шануванням калдорей. Лише жерців нічних ельфів, що безпосередньо спілкуються з Богинею Місяця, навчають цього заклику.",al={"чи люди можуть вивчити грацію елуни","чи грація елуни лише для нічних ельфів"}},{q="Де починається й закінчується ця подорож?",a="Заклик передає наставниця Лаурна Морнінґлайт у поселенні Доланаар на Тельдрассилі, і послушник вирушає на захід — до Храму Місяця в Дарнасусі.",al={"початок і кінець завдання","куди йти"}}},fp="13,317,18.457.0,22.402.0,34.257.0,25.261.0,43.317.0,61.239.0,49.197.0,38.172.0"}
P.entries["quest:5676"] = {n="Арканний відгук",s="«Арканний відгук» — обряд посвяти для жерців Альянсу в Стормвінді, який проводить Верховна Жриця Лаурена в Соборі Світла. Сягнувши глибшого єднання з вірою, жрець опановує захист від ворожих знавців арканної магії. Це практична оборона Церкви від неприборканого чаклунства й свавільних чарівників.",h="«Арканний відгук» — обряд посвяти для жерців Альянсу в Стормвінді, який проводить Верховна Жриця Лаурена в...",kw={"арканний відгук","жрець","лаурена","собор світла","арканна магія","стормвінд"},ang={["class:Priest"]="Цей обряд розширює ваш тактичний арсенал: ви здобуваєте засоби, щоб гамувати ворожих чаклунів, які черпають силу з мани, коли божественна дипломатія безсила.",["faction:Alliance"]="Поки по всіх Східних Королівствах зростає напруга через свавільні таємні гуртки й темних чаклунів, Альянс покладається на своїх жерців, щоб знешкоджувати магічні загрози.",["race:Human"]="Людські жерці Стормвінда проходять особливе богословське навчання Собору Світла, що поєднує праведну відданість із суворою дисципліною супроти магії."},sec={{t="Щит від арканної магії",b="У залитих сонцем галереях Собору Світла Верховна Жриця Лаурена нагадує послушникам про давню небезпеку — арканну магію. Святе Світло несе зцілення, тепло й божественний лад, а неприборкані магічні енергії мінливі й часто ведуть до скверни чи катастрофи. Щоб вистояти проти чорнокнижників, чаклунів-ізгоїв і магічних звірів, побожних жерців учать: іноді саму віру треба перетворити на дієвий оберіг від чужих чар."},{t="Обернути потік назад",b="«Арканний Відгук» гартує розум і дух, щоб карати ворожих чаклунів за чари, спрямовані проти вірних. Ця наука не просто відбиває магічні залпи — вона повертає арканну енергію до її джерела, випалює запаси мани самого чаклуна й завдає йому муки. Лаурена передає це закляття людським жерцям, що вирушають у широкий світ, аби посланці Собору ніколи не мандрували беззахисними перед чаклунством."}},faq={{q="Яка мета завдання «Арканний відгук»?",a="Завдання знаменує дедалі більшу вправність жерця-людини під опікою Церкви Світла. Верховна Жриця Лаурена навчає його особливого захисного обряду, що протидіє ворожим заклиначам і відплачує їм.",al={"завдання арканний відгук","що таке арканний відгук","навіщо це завдання"}},{q="Хто дає це завдання і де її знайти?",a="Завдання дає Верховна Жриця Лаурена. Вона служить у Соборі Світла — величному духовному осередку Альянсу на Соборній Площі Стормвінда.",al={"хто дає арканний відгук","хто видає завдання арканний відгук","де лаурена"}},{q="Чому Церква Святого Світла вважає тайну магію ворогом?",a="Церква навчає покладатися на моральну ясність, відданість і божественну благодать. Тайна ж магія черпає з нестійких сил, що викликають залежність, — у минулому вони приваблювали демонічні вторгнення й сіяли хаос по всьому Азероту, тож людські жерці вважають неприборкане чаклунство постійною небезпекою.",al={"чому жерці ненавидять аркану","церква проти аркани","чи аркана зла"}},{q="Як задумано діє оберіг «Арканний Відгук»?",a="Закляття огортає жерця аурою відплати. Щойно в оберіг влучає вороже закляття, магія, що налетіла, спричиняє віддачу, яка висмоктує ману нападника й завдає йому фізичного удару.",al={"як діє арканний відгук","переказ про арканний відгук"}},{q="Чи може будь-який жрець навчитися цього в Лаурени?",a="У Стормвінді цієї науки навчають саме жерців-людей як частину їхньої національної церковної традиції — вона відображає особливі бойові настанови, яких навчають у Соборі Світла.",al={"чи дворфи можуть вивчити арканний відгук","хто може отримати арканний відгук","расове закляття жерця"}},{q="Якого рівня очікують від послушника для цього навчання?",a="Жерців кличуть навчатися цього прийому приблизно на двадцятому колі досвіду — коли послушники лишають прості церковні обов'язки й вирушають у небезпечні прикордонні землі.",al={"який рівень для арканного відгуку","вимога до рівня арканного відгуку"}}},fp="15,357,27.450.0,23.448.0,49.239.0,49.175.0,68.296.0,52.222.0,39.202.0,63.185.0"}
P.entries["quest:5677"] = {n="Арканний відгук",s="Арканний відгук — жрецьке завдання, яке Верховний Жрець Роган в Айронфорджі дає послушникам-людям, що гостюють у Каз Модані. Роган відсилає молодого жерця додому, до Собору Світла в Стормвінді, де той отримає науку, що відповідає традиціям людського роду. Це важлива віха: молоді учні починають опановувати прояви віри, властиві саме їхньому народові.",h="Арканний відгук — жрецьке завдання, яке Верховний Жрець Роган в Айронфорджі дає послушникам-людям, що...",kw={"арканний відгук","жрець","верховний жрець роган","верховна жриця лаурена","собор світла","люди"},ang={["class:Priest"]="Це завдання — переломна віха: жерці відкривають для себе, що різні народи спрямовують і виявляють Святе Світло через власні культурні традиції.",["race:Dwarf"]="Дворфійські наставники на кшталт Верховного Жреця Рогана шанують союз із людьми, але особливі обряди Каз Модану зберігають для свого народу.",["race:Human"]="Жерців-людей лагідно відкликають із дворфійських святилищ назад до Стормвінда, щоб вони вкоренилися у священних звичаях Собору Світла."},sec={{t="Лагідна підказка",b="Коли жрець-людина шукає поглибленого духовного навчання в залах Кварталу містиків, Верховний Жрець Роган приймає його шанобливо, але проводить межу. Хоч жерці-дворфи й жерці-люди однаково віддані Святому Світлу, кожен народ плекає власні обряди, практики й захисні молитви. Замість відкривати особливі таємниці Айронфорджа, Роган відсилає людське духовенство до його коріння в Елвінні, щоб воно опанувало самобутню спадщину свого народу."},{t="Повернення до Собору",b="Повернувшись до Стормвінда, послушник звітує Верховній Жриці Лаурені у величному Соборі Світла. Лаурена з полегшенням бачить, що настанови Рогана дійшли до мандрівника, і вітає його саме тоді, коли його молоді сили починають розквітати. Це повернення відкриває шлях до глибшого посвячення в духовні практики королівства Стормвінд і готує жерців обернути Святе Світло проти нових загроз, що обступають державу."}},faq={{q="Чому Верховний Жрець Роган не хоче навчати жерців-людей?",a="Верховний Жрець Роган шанує людських служителів, але дворфійське духовенство має власні обряди й благословення, передані крізь його культурну спадщину. Він вважає, що жерці-люди мусять учитися особливих прийомів, які зберігають їхні власні наставники в Стормвінді.",al={"чому посилають до стормвінда","чому роган не навчає","жрець-дворф не навчає мене"}},{q="Хто така Верховна Жриця Лаурена?",a="Верховна Жриця Лаурена — визначна духовна провідниця й наставниця в Соборі Світла в Стормвінді. Вона опікується зростанням обдарованих жерців-людей і веде їх у навчанні та обрядах середнього рівня.",al={"верховна жриця лаурена","хто така лаурена","наставниця жерців у соборі"}},{q="Де знайти Верховного Жерця Рогана?",a="Верховний Жрець Роган — у Залі Таїнств у Кварталі містиків великого дворфійського гірського міста Айронфордж.",al={"де роган","де верховний жрець роган","знайти рогана"}},{q="Яка мета цього завдання?",a="Це завдання-скерування повертає жерців-людей середнього рівня з дворфійських земель до їхнього головного расового осередку навчання в Соборі Світла, щоб вони могли опанувати особливі духовні прийоми свого народу.",al={"мета завдання арканний відгук","навіщо це завдання","що робить це завдання"}}},fp="15,380,20.477.0,23.446.0,57.267.0,30.223.0,37.131.0,34.219.0"}
P.entries["quest:5678"] = {n="Арканний Відгук",s="«Арканний Відгук» — жрецьке завдання Альянсу, що скеровує жерців-людей, які навчаються в Дарнасусі, додому до Стормвінда. Його дає Жриця Алатея з Храму Місяця, і ця подорож показує глибоку культурну прірву у ставленні до магії між нічними ельфами та Східними Королівствами. Коли послушник повертається до Собору Світла, Верховна Жриця Лаурена готує його до глибшого богословського навчання.",h="«Арканний Відгук» — жрецьке завдання Альянсу, що скеровує жерців-людей, які навчаються в Дарнасусі, додому до...",kw={"арканний відгук","жриця алатея","верховна жриця лаурена","собор світла","стормвінд","арканна магія","жрець"},ang={["class:Priest"]="Ця проща — важливий поріг на вашому духовному шляху й нагадування про гостру філософську розбіжність між сестринством Елуни та догмами Святого Світла.",["race:Human"]="Повернення до Стормвінда приводить вас додому, у серце Церкви Святого Світла, і лишає позаду замкнене в собі, недовірливе жрецтво калдореїв.",["race:NightElf"]="Відверта насторога Жриці Алатеї показує одвічний страх калдореїв: гра молодших смертних рас з арканною силою може обернутися новим лихом."},sec={{t="Неохочий заклик",b="Жриця Алатея опікується жерцями-гостями в спокійних залах Храму Місяця в Дарнасусі. Вона визнає офіційний союз калдореїв із людьми Стормвінда, але має глибокі сумніви щодо людських магічних і духовних практик. Суспільство нічних ельфів вважає арканну силу від природи мінливою й небезпечною — такий погляд виплекали десять тисячоліть скорботи після Війни Прадавніх. Навіть людські божественні обряди, що розмивають межу між сяйвом віри й механікою арканного, помітно непокоять духовенство нічних ельфів."},{t="Повернення до Собору",b="Попри вагання, Алатея шанує узи між расами Альянсу й відпускає послушника-гостя на виклик Собору Світла. Верховна Жриця Лаурена розіслала гінців через моря, щоб зібрати жерців-людей, які набираються сили, на вищу науку. Повертаючись до Стормвінда, послушник лишає позаду осяяні місяцем гаї Елуни й поринає у величні кам'яні святилища та золоте сяйво Святого Світла."}},faq={{q="Чому Жриця Алатея хоче, щоб я покинув Дарнасус?",a="Жриця Алатея виконує заклик ваших зверхників зі Стормвінда, але їй ще й незатишно від людських богословських практик. Вона відверто визнає глибоку недовіру до тайної магії, байдуже, чи має та божественне забарвлення, тож охоче відсилає послушників-людей назад до їхніх величних соборів.",al={"чому алатея відсилає мене","чому повертатися до стормвінда","алатея арканний відгук"}},{q="Чому нічні ельфи не довіряють людській жрецькій магії?",a="Культуру нічних ельфів докорінно визначив катастрофічний Розкол, спричинений десять тисяч років тому безрозсудним тайним чаклунством. Віра калдорей зосереджена на Елуні, і їхні жриці з глибокою підозрою ставляться до будь-якої традиції, що межує з тайними маніпуляціями чи містить їх, — навіть якщо це союзники, які служать Святому Світлу.",al={"чому нічні ельфи ненавидять аркану","недовіра нічних ельфів до аркани","елуна чи святе світло"}},{q="Хто така Верховна Жриця Лаурена?",a="Верховна Жриця Лаурена — визначна духовна провідниця в Соборі Світла в Стормвінді. Вона опікується навчанням і поступом молодих жерців-людей, допомагаючи їм осягати Святе Світло в міру того, як росте їхня сила.",al={"хто така лаурена","верховна жриця лаурена стормвінд"}},{q="До чого веде це завдання?",a="Доповідь Верховній Жриці Лаурені знаменує ваш перехід до вищого навчання жерців-людей у Стормвінді, відкриваючи науку й благословення, властиві лише людським служителям Святого Світла.",al={"що після арканного відгуку","переказ про нагороду арканний відгук"}}},fp="15,405,19.552.0,23.430.0,54.311.0,49.344.0,30.240.0,31.200.0"}
P.entries["quest:5679"] = {n="Ненажерлива чума",s="«Ненажерлива чума» — навчальний обряд для жерців-Відступників, які довели свою відданість тіньовій магії. Жриця Елталіста в Андерсіті передає учневі знання про одне з найстрашніших проклять, що їх плете немертве жрецтво.",h="«Ненажерлива чума» — навчальний обряд для жерців-Відступників, які довели свою відданість тіньовій магії.",kw={"ненажерлива чума","жриця елталіста","воєнний квартал","тінь","жрець","андерсіті","заклинання"},ang={["class:Priest"]="Цей обряд дає жерцям-Відступникам одне з найхарактерніших расових заклинань: ваше виживання напряму залежить від недуги, якою ви вражаєте ворогів.",["faction:Horde"]="Поки інші союзники Орди спираються на духів предків чи рівновагу стихій, Відступники додають до спільного арсеналу безжальні прокляття, схожі на хворобу.",["race:Undead"]="Тіньове мистецтво, подібне до чуми, показує, як далеко Відступники відійшли від традиційної віри Лордерона після Третьої війни."},sec={{t="Прокляття тіні",b="У тьмяних покоях Воєнного Кварталу Жриця Елталіста веде Відступників крізь похмурі мистецтва Тіні. Живі жерці інших народів черпають силу в Святому Світлі чи духах предків, а Відступники викували власне віровчення. Ненажерлива чума — осердя їхньої філософії: завдавати ворогам страждань і водночас вливати відібрану життєву силу у власні тліючі тіла."},{t="Випробування майстерності",b="Елталіста не передає знання про цю чуму легковажно. Заклинання вважають зброєю лютої злоби, покликаною переламати хід боротьби з Погибеллю й Багряним Хрестовим Походом. Навчаючи, Елталіста застерігає учнів відточувати це вміння невпинними вправами й нагадує: тих, хто прагне опанувати темні мистецтва, чекають куди тяжчі випробування."}},faq={{q="Яка мета цього завдання?",a="Завдання — офіційний урок для жерців-Відступників, що досягли досвідченого рівня. Поговоривши з Жрицею Елталістою, жрець навчається закляття «Ненажерлива чума» — характерного тіньового прокляття, властивого лише служителям-нежиті.",al={"навіщо ненажерлива чума","що робить завдання ненажерлива чума","мета ненажерливої чуми"}},{q="Хто така Жриця Елталіста?",a="Жриця Елталіста — наставниця жерців Відступників у Воєнному Кварталі Андерсіті. Вона опікується зростанням молодих заклиначів Тіні й стежить, щоб вони вміло орудували своїми руйнівними благословеннями на користь Відступників.",al={"хто така елталіста","переказ про елталісту","елталіста андерсіті"}},{q="Чи можуть жерці інших рас навчитися «Ненажерливої чуми» в Елталісти?",a="Ні. «Ненажерлива чума» — таємне закляття, доступне лише жерцям-Відступникам. Тролі, люди, нічні ельфи й дворфи спілкуються з іншими духовними силами й мають натомість власні расові науки.",al={"чи тролі можуть вивчити ненажерливу чуму","чи ненажерлива чума лише для нежиті","інші раси ненажерлива чума"}},{q="Кому здати це завдання?",a="Жрицю Елталісту можна знайти у Воєнному Кварталі Андерсіті, серед наставників і служителів-жерців Відступників.",al={"де елталіста","де завдання ненажерлива чума","місце наставниці жерців в андерсіті"}},{q="Чому жерці-Відступники спеціалізуються на чумі й магії Тіні?",a="Через свою мертву природу жерці-Відступники зазнають нестерпного фізичного болю щоразу, як спрямовують Святе Світло. Тож багато хто звертається до вчення Тіні, використовуючи недуги, прокльони й украдену життєву силу, щоб виживати й воювати.",al={"чому жерці відступники володіють чумою і тінню","переказ про жерців нежиті","магія жерців відступників"}},{q="Про які випробування каже Елталіста?",a="Елталіста попереджає, що в міру того, як жрець набирає сили, випробування по всьому Лордерону ставатимуть суворішими. Темна магія привертає небезпечну увагу й смертельних ворогів, тож послушник мусить досконало володіти кожним прокляттям у своєму арсеналі.",al={"які випробування пізніше","майбутні випробування елталісти","які випробування"}}},fp="16,281,21.464.0,17.391.0,34.237.0,29.233.0,67.210.0,30.140.0,62.242.0,39.236.0"}
P.entries["quest:57"] = {n="Нічна Варта",s="Безпосередньо за дорученням Командира Алтеї Ебонлок шукачі пригод вирушають до проклятих курганів Сутінколісся, щоб стримати хвилю неспокійних мерців. Цей похід спрямований проти кістяних жахіть, що видираються з Цвинтаря Тихих Садів і Воронячого Пагорба. Відкинути кістяну навалу конче потрібно, щоб крихкий прихисток Даркшира не поглинула темрява.",h="Безпосередньо за дорученням Командира Алтеї Ебонлок шукачі пригод вирушають до проклятих курганів...",kw={"нічна варта","алтея ебонлок","кістяки","цвинтар тихих садів","воронячий пагорб","даркшир"},ang={["class:Paladin"]="Для Срібної Длані й лицарів Світла протистояти оскверненим мерцям Тихих Садів — святий обов'язок очистити спотворені місця спочинку.",["class:Priest"]="Жерці, що ступають оскверненою землею Воронячого Пагорба, стикаються з неприхованим спотворенням похоронних звичаїв і силою віри дарують змученим душам тихий спочинок.",["faction:Alliance"]="Даркшир — крихкий південно-східний рубіж Альянсу на півдні Східних Королівств. Допомагаючи Нічній Варті, ви не даєте місту остаточно занепасти й зберігаєте його як надійний оплот.",["race:Human"]="Чимало кістяків, що встають із землі Сутінколісся, — предки нині живих мешканців Стормвінда й Даркшира, тож для людей-захисників ця битва глибоко особиста."},sec={{t="Мерці не спочивають",b="Трагічне падіння Сутінколісся — від зеленого краю, що колись звався Брайтвудом, до оповитих туманом сутінків — позбавило його цвинтарі спокою. Командир Алтея Ебонлок, що очолює добровольче ополчення Даркшира — Нічну Варту, — веде нескінченну облогову боротьбу. Без допомоги Стормвінда її сили небезпечно розпорошені. Звістки про оживлених кістяних виродків і жахіття, що повстають із землі, загрожують східним поселенням, тож ополчення мусить вербувати кожного дужого мандрівника, готового ступити в мертві землі."},{t="Проклята земля",b="Похід веде новобранців до двох осередків некромантичного неспокою: Цвинтаря Тихих Садів трохи на південь від міста та величезних зарослих просторів цвинтаря Воронячого Пагорба далеко на заході. Кістяки виповзають із забутих гробниць і неглибоких придорожніх могил, оживлені темною магією, що досі живе в похмурому лісі. Знищення цих виродків дарує знесиленим мешканцям Даркшира життєво потрібний перепочинок, хоча це й нескінченна битва з глибоко вкоріненим злом."}},faq={{q="Чому Нічна Варта покладається на мандрівників, а не на вартових Стормвінда?",a="Стормвінд здебільшого кинув Сутінколісся напризволяще, лишивши оборону краю Командирові Алтеї Ебонлок і її місцевому ополченню з добровольців. Через внутрішні політичні чвари й зниклого короля столиця не надсилає гарнізонів, тож Нічна Варта мусить наймати перехожих шукачів пригод.",al={"чому немає допомоги зі стормвінда","де армія стормвінда","чому даркшир сам"}},{q="Звідки беруться скелети?",a="Скелети-нечисть і кістяні жахіття видираються з освяченої землі Цвинтаря Тихих Садів і розлогого цвинтаря на Воронячому Пагорбі. Темні магічні сили, що просякли ліси, потривожили поховання багатьох століть, піднявши давні рештки як безтямних, лютих вартових.",al={"звідки скелети в сутінковому лісі","чому тут скелети","джерело нежиті в сутінковому лісі"}},{q="Хто очолює Нічну Варту?",a="Нічною Вартою командує Командир Алтея Ебонлок. Вона родичка мера Даркширу, Лорда Елло Ебонлока, і особисто керує обороною містечка й координує дії проти нежиті й чудовиськ Сутінколісся.",al={"хто очолює нічну варту","ватажок нічної варти","хто така алтея ебонлок"}},{q="Чим відрізняються Тихі Сади й Воронячий Пагорб?",a="Цвинтар Тихих Садів лежить одразу на південь від Даркширу й становить безпосередню місцеву загрозу для містечка. Цвинтар на Воронячому Пагорбі, далеко на заході за лісом, — величезне поховання, серце навали нежиті в Сутінколіссі.",al={"тихі сади чи воронячий пагорб","який цвинтар кращий","цвинтарі сутінкового лісу"}},{q="Що буде, коли цих скелетів прорідити?",a="Знищення кістяних жахіть і нечисті — лише один етап кампанії Алтеї. Нічна Варта постійно стежить за загрозами, що наростають по всьому лісу: від гулів і скелетів до небезпечнішої нежиті й зловісних некромантів, що керують нею з глибин Сутінколісся.",al={"що далі нічна варта","ланцюжок нічної варти","після нічної варти 2"}},{q="Чому Даркшир у постійній небезпеці?",a="Колись Сутінколісся було мирною провінцією Королівства Стормвінд на ім'я Світлолісся, але його поглинули магічні сутінки й обсіли тіньові прокляття. Тепер ліси кишать здичавілими воргенами, ненажерливими павуками й неупокоєною нежиттю, і Даркшир лишився останнім оплотом живих людей у краї.",al={"чому сутінковий ліс небезпечний","небезпека даркширу","що прокляло сутінковий ліс"}}},fp="15,389,20.537.0,12.482.0,73.312.0,36.275.0,26.240.0,63.272.0,43.279.0,36.302.0"}
P.entries["quest:5713"] = {n="Один постріл. Один убитий.",s="Несучи нагальне послання до Обердайна, Вартова Айнаша потрапила в засідку ворожого фурболга Мароша Підступного та його зграї слідопитів, які її отруїли. Знерухомлена, поки готує протиотруту, вона покладається на мандрівників поблизу, які мають стримати нападників, щоб вона вижила й виконала свій обов'язок.",h="Несучи нагальне послання до Обердайна, Вартова Айнаша потрапила в засідку ворожого фурболга Мароша...",kw={"один постріл один убитий","вартова айнаша","марош підступний","вартова онаея","пост маестри","фурболги"},ang={["class:Hunter"]="Айнаша показує непохитну рішучість стрільця: вона й далі пускає смертоносні стріли в хащі, навіть знемагаючи від сильної отрути.",["faction:Alliance"]="Очищаючи лісові стежки від агресивних зграй фурболгів, ви забезпечуєте безпечний прохід між Ашенвалем і твердинями Альянсу на півночі.",["race:NightElf"]="Захищаючи Айнашу, ви рятуєте і сестру з Вартових, і важливі донесення, що ходять між заставами Ашенвалю й північчю Темного Узбережжя."},sec={{t="Засідка на лісовій дорозі",b="Стежки північного Калімдору стали підступними, бо порча дедалі глибше вкорінюється серед диких мешканців. Вартова Айнаша прямувала до Обердайна з важливими донесеннями, коли її перехопили ворожі фурболги. На чолі з Марошем Підступним нападники вдарили швидко й уразили розвідницю виснажливою отрутою — вона ледве трималася на ногах і не могла дійти пішки."},{t="Тримати рубіж",b="Айнаша знається на природних засобах, але, щоб приготувати й прийняти протиотруту під лісовим склепінням, потрібен час, якого в переслідуваної розвідниці немає. Поки слідопити Мароша підступають, Айнаша мусить покладатися на мандрівників, що стережуть її, доки вона працює. Попри згасаючі сили, вона тримає лук рівно й прикриває захисників стрілами, пускаючи їх у хащі: ні вона, ні її послання не загинуть у нетрях."},{t="Донесення до Посту Маестри",b="Коли напад відбито, а Мароша вбито, протиотрута повертає Айнаші досить сил, щоб завершити шлях до Обердайна. Щоб застава на півдні, в Ашенвалі, дізналася про агресивних фурболгів, які загрожують шляхам постачання краю, вона просить своїх захисників доповісти безпосередньо Вартовій Онаеї на Посту Маестри."}},faq={{q="Хто така Вартова Айнаша?",a="Вартова Айнаша — розвідниця нічних ельфів, якій доручено переносити важливі послання через кордони Темного Узбережжя й Ашенвалю. Вправна з луком і в лісовому виживанні, вона ледь не загинула від несподіваної засідки з отрутою під час служби.",al={"вартова айнаша","айнаша","хто така айнаша"}},{q="Хто напав на Вартову Айнашу?",a="На неї напала зграя ворожих фурболгів на чолі з Марошем Підступним. Вони отруїли її в першій сутичці, сподіваючись здолати знерухомлену розвідницю, поки вона не оговталася.",al={"хто напав на неї","марош підступний","марош","хто її отруїв"}},{q="Куди йшла Вартова Айнаша?",a="Айнаша прямувала до Обердайна з важливим донесенням, коли Марош і його слідопити заблокували її на дорозі.",al={"куди йшла айнаша","мета подорожі айнаші","лор'данель"}},{q="Чому треба доповісти Вартовій Онаеї?",a="Айнаша мусить негайно поспішати до Обердайна з посланням, тож просить вас вирушити на південь, до Посту Маестри в Ашенвалі, і повідомити Вартову Онаею про ворожість фурболгів.",al={"вартова онаея","чому пост маестри","онаея"}},{q="Чому фурболги в цих краях ворожі?",a="По всьому Темному Узбережжю й Ашенвалю багато племен фурболгів піддалися демонічній скверні й шаленству, що пішли від Третьої війни, і тепер без розбору нападають на вартових і подорожніх.",al={"чому фурболги нападають","ворожість фурболгів","осквернений фурболг"}},{q="Чи б'ється Айнаша під час засідки?",a="Так. Хоча від отрути вона ледве тримається на ногах, вона підтримує свого захисника, прикриваючи його стрілами з лука, поки готує протиотруту.",al={"чи айнаша допомагає","лук айнаші","чи вона б'ється"}}},fp="19,310,25.400.0,16.406.0,24.340.1,24.233.0,30.184.0,37.125.0,39.198.0,41.207.0,37.155.0"}
P.entries["quest:5722"] = {n="Пошуки загубленої торбини",s="«Пошуки загубленої торбини» — доручення Орди, яке дає Рагауро на Узвишші Старійшин у Тандер Блафі. Від імені Старої Відьми Маґати Ґрімтотем він посилає шукачів пригод під Оргріммар, у Провалля Лютого Вогню, знайти рештки Маура Ґрімтотема — посланця, що загинув, натрапивши серед трогів на щось незвичне.",h="«Пошуки загубленої торбини» — доручення Орди, яке дає Рагауро на Узвишші Старійшин у Тандер Блафі.",kw={"пошуки загубленої торбини","рагауро","маґата ґрімтотем","маур ґрімтотем","провалля лютого вогню","троги","тандер блаф"},ang={["faction:Horde"]="Поки Тралл зосереджений на тому, щоб викорінити темних культистів просто під столицею Орди, гучні чутки з Малгору показують, що Ґрімтотеми тихцем переслідують у тій самій печері власні цілі.",["race:Tauren"]="Задуми клану Ґрімтотем часто різко розходяться з відкритим проводом Кайрна Бладгуфа, тож таємна цікавість Маґати до підземних створінь під союзним містом заслуговує на пильну увагу."},sec={{t="Доручення Ґрімтотемів під Оргріммаром",b="Поки Вождь Тралл і його радники зосереджені на Раді Тіней, що ворушиться в Проваллі Лютого Вогню, клан Ґрімтотем переслідує власні таємні інтереси. До Маґати Ґрімтотем на Узвишші Старійшин у Тандер Блафі доходить звістка, що її посланець, Маур Ґрімтотем, спустився в підземну печеру під Оргріммаром, щоб дослідити трогів і спробувати з ними домовитися. Маур так і не повернувся, але ходять чутки, що незадовго до смерті він зробив цікаву знахідку."},{t="Полеглий посланець",b="Від імені Маґати її помічник Рагауро посилає воїнів просто в провалля. Глибоко в тунелях, сповнених лави, неподалік таборів трогів лежить понівечене тіло Маура, люто побите грубими кийками й голими кулаками. Звірі зовсім не зачепили його речей, тож майно таурена й таємниці, які він шукав, лишилися чекати на посланців Маґати."}},faq={{q="Хто посилає шукачів пригод на це завдання?",a="Доручення дає Рагауро — служник Маґати Ґрімтотем на Узвишші Старійшин у Тандер Блафі.",al={"хто дає завдання","хто починає пошуки загубленої торбини","де взяти завдання"}},{q="Хто такий Маур Ґрімтотем?",a="Маур був посланцем племені Ґрімтотем, якого Маґата Ґрімтотем відрядила до Провалля Лютого Вогню розвідати трогів і спробувати з ними порозумітися. Його забили на смерть у глибинах печер.",al={"маур ґрімтотем","ким був маур","що сталося з мауром"}},{q="Чому Маґату Ґрімтотем цікавило Провалля Лютого Вогню?",a="Маґата цікавилася трогами, що заполонили тунелі під Оргріммаром, і послала Маура спробувати з ними порозумітися. Коли Маур, перш ніж загинути, знайшов серед них щось незвичайне, вона захотіла, щоб його знахідку принесли просто їй.",al={"троги маґати","чому маґату цікавить лютий вогонь","чому послали маура"}},{q="Де лежить тіло Маура Ґрімтотема?",a="Тіло Маура лежить глибоко в Проваллі Лютого Вогню під Оргріммаром — забитий, він лежить біля володінь трогів на підземних стежках.",al={"знайти маура","де маур ґрімтотем","де тіло маура"}},{q="Чи обібрали троги Маура після вбивства?",a="Ні. Трогам байдужі багатства, знаряддя й записані папери, тож одяг і торбина Маура лишилися неторканими поруч із його понівеченими рештками.",al={"троги пограбували","чи маура обікрали"}},{q="Що буде, коли знайти тіло Маура?",a="Оглянувши тіло Маура, ви знаходите його торбину, і починається наступне завдання — «Повернення загубленої торбини», де треба доставити його знахідки Маґаті Ґрімтотем у Тандер Блаф.",al={"наступне завдання","наступне завдання після загубленої торбини","що робити з торбиною"}}},fp="30,335,37.466.0,19.397.1,36.106.0,22.189.0,55.237.0,41.132.0,43.138.0,40.170.1"}
P.entries["quest:5723"] = {n="Випробування сили ворога",s="«Випробування сили ворога» — доручення Орди, яке дає Рагауро на Узвишші Старійшин у Тандер Блафі від імені Маґати Ґрімтотем. Після того як невдала дипломатична спроба під Оргріммаром скінчилася різаниною посланців, таурени прагнуть відплати й винищують трогів, що заполонили Провалля Лютого Вогню.",h="«Випробування сили ворога» — доручення Орди, яке дає Рагауро на Узвишші Старійшин у Тандер Блафі від імені...",kw={"випробування сили ворога","рагауро","маґата ґрімтотем","провалля лютого вогню","троги","таурени","оргріммар"},ang={["class:Shaman"]="Троги мають власних грубих шаманів, які орудують первісними стихіями в лавових тунелях, — викривлене дзеркало шляхетних шаманських традицій.",["faction:Horde"]="Це доручення показує єдність усередині Орди: Тандер Блаф не шкодує ні ресурсів, ні воїнів, щоб захистити підвалини Оргріммара.",["race:Orc"]="Хоч доручення дає тауренська верхівка, воно прямо захищає серце орківської столиці від трогів, що риють ходи під містом.",["race:Tauren"]="Кров тауренських дипломатів заплямувала камені Провалля Лютого Вогню, тож цей напад — пряма відплата від імені Узвишшя Старійшин."},sec={{t="Дипломатія проти дикості",b="Коли підземні троги вперше вибралися з вогняних проваль під орківською столицею Оргріммаром, Стара Відьма Маґата Ґрімтотем запропонувала мир. Вона послала в глибини посланців-тауренів, щоб домовитися зі створіннями. Відповідь була жорстокою й миттєвою: троги без вагань порубали делегатів. Вважаючи різанину непрощенною образою тауренам і загрозою, що зростає для всієї Орди, Маґата вирішила відповісти на дикість рішучою силою."},{t="Загроза під Оргріммаром",b="Таурен Рагауро, що діє в Тандер Блафі як посланець Маґати, керує військовою відповіддю. Він посилає воїнів пробратися в Провалля Лютого Вогню, знайти зграї трогів і винищити їхніх бійців передової та шаманів. Ударивши глибоко в підземні володіння трогів, Орда прагне приборкати їх, перш ніж їхні тунелі дадуть їм змогу безперешкодно вилитися на вулиці Оргріммара нагорі."}},faq={{q="Чому завдання в підземелля Оргріммара дають у Тандер Блафі?",a="Завдання йде від тауренського проводу. Маґата Ґрімтотем особисто посилала дипломатів у Провалля Лютого Вогню на перемовини з трогами, а коли тих посланців вирізали, її помічник Рагауро взявся збирати воїнів з Узвишшя Старійшин у Тандер Блафі, щоб за них помститися.",al={"чому тандер блаф","початок завдання в тандер блафі","де рагауро"}},{q="Хто такий Рагауро?",a="Рагауро — таурен, що дає завдання на Узвишші Старійшин у Тандер Блафі. Він діє від імені Маґати Ґрімтотем, організовуючи вилазки в Провалля Лютого Вогню, щоб винищити трогів і повернути реліквії, втрачені під час попередніх невдалих дипломатичних місій.",al={"хто такий рагауро","рагауро","старійшина рагауро"}},{q="Чому Маґата Ґрімтотем намагалася помиритися з трогами?",a="Маґата задумувала це як вияв доброї волі — спробу налагодити стосунки з підземними істотами, а не одразу проливати кров. Але троги виявилися нездатними чи небажаними вести цивілізовану розмову й вирізали її посланців, щойно ті прибули.",al={"чому мир з трогами","маґата і дипломатія з трогами","чому домовлятися з трогами"}},{q="Яких ворогів треба вбити для цього доручення?",a="Вам треба спуститися в Провалля Лютого Вогню під Оргріммаром і вбити трогів Лютого Вогню та шаманів Лютого Вогню, щоб зламати їхні передові лави й послабити їхню чаклунську підтримку.",al={"яких мобів убивати","цілі завдання","троги лютого вогню"}},{q="Чи можна виконати це завдання разом з іншими завданнями в підземеллі?",a="Так. Рагауро дає ще й завдання «Пошуки загубленої торбини», яке посилає шукачів пригод у той самий провал на пошуки решток невдалого дипломатичного загону, тож обидва завдання зручно виконувати одночасно.",al={"інші завдання провалля","завдання загубленої торбини","завдання провалля лютого вогню"}},{q="Звідки беруться троги?",a="Троги вилізли з глибоких вулканічних розломів під Дуротаром. Як зауважує Рагауро наприкінці завдання, Орда досі мало знає про походження цих диких печерних мешканців і чому вони саме тепер почали прориватися вгору, до Оргріммара.",al={"походження трогів у проваллі","звідки беруться троги","чому троги під оргріммаром"}}},fp="27,301,24.496.0,28.421.0,68.293.0,15.246.0,52.282.0,44.183.0,58.219.0,33.252.0"}
P.entries["quest:5724"] = {n="Повернення загубленої торбини",s="Це доручення завершує пошуки Маура Ґрімтотема глибоко в Проваллі Лютого Вогню під Оргріммаром. Знайшовши вбитого таурена, що міцно стискав свою торбу, шукачі пригод мають віднести її Рагауро на Узвишшя Старійшин у Тандер Блафі.",h="Це доручення завершує пошуки Маура Ґрімтотема глибоко в Проваллі Лютого Вогню під Оргріммаром.",kw={"повернення загубленої торбини","маур ґрімтотем","рагауро","маґата ґрімтотем","провалля лютого вогню","тандер блаф"},ang={["faction:Horde"]="Троги й культисти загрожують тунелям під Оргріммаром, а таємна присутність посланців Ґрімтотемів під фортецею Тралла породжує політичні питання без відповідей.",["race:Tauren"]="Клан Ґрімтотем має непрості стосунки з народом Кайрна Бладгуфа, тож будь-яка таємна справа послідовників Маґати в Оргріммарі викликає підозру."},sec={{t="Похмура знахідка",b="Під червоними скелями, у вогняних глибинах Провалля Лютого Вогню, Маур Ґрімтотем загинув жорстокою смертю від рук трогів. Навіть мертвий він міцно обіймав свою особисту торбу, боронячи її вміст до останнього подиху. Вивільнити торбу із задубілих рук — єдиний спосіб дізнатися, що привело члена клану Ґрімтотем у вулканічні печери під столицею Тралла."},{t="Інтерес Маґати",b="Коли торбу приносять Рагауро на Узвишшя Старійшин, стає ясно, що за цим дорученням стояла сама Маґата Ґрімтотем. Рагауро вдячно приймає ношу, шукаючи відповіді, чому один з клану Маґати загинув марно, і видає винагороду, яку схвалила сама Стара Відьма. Що ніс Маур — чи навіщо Маґата послала його в заполонені трогами розколини Оргріммара, — знає лише верхівка клану Ґрімтотем."}},faq={{q="Де знайти Маура Ґрімтотема?",a="Тіло Маура Ґрімтотема лежить глибоко в підземеллі Провалля Лютого Вогню під Оргріммаром, серед ворожих трогів.",al={"тіло маура ґрімтотема","знайти маура ґрімтотема","де маур"}},{q="Кому здати торбину?",a="Сумку Ґрімтотемів треба принести назад Рагауро, що стоїть на Узвишші Старійшин у Тандер Блафі.",al={"здати загублену торбину","де рагауро","здати торбину"}},{q="Що Маур Ґрімтотем робив у Проваллі Лютого Вогню?",a="Рагауро запевняє, що не знає, чому родичеві Маґати довелося безглуздо загинути, але Маґата Ґрімтотем особисто наказала повернути торбину — отже, Маур виконував справу клану.",al={"чому маур був у проваллі","місія маура","що робив маур"}},{q="Що в Сумці Ґрімтотемів?",a="Точний вміст гінцеві так і не розкривають. Маур люто беріг сумку до самої смерті, і її віддають нерозкритою просто Рагауро від імені Маґати.",al={"що було в сумці","вміст торбини"}},{q="Що вбило Маура Ґрімтотема?",a="Маура підстерегли й убили дикі троги, що кишать у тунелях Провалля Лютого Вогню.",al={"як помер маур","хто вбив маура"}},{q="Хто стоїть за цим дорученням?",a="Рагауро — лише зв'язковий на Узвишші Старійшин, а нагорода й наказ ідуть безпосередньо від Старої Відьми Маґати Ґрімтотем.",al={"хто послав рагауро","зв'язок з маґатою"}}},fp="26,255,16.403.0,18.455.1,32.116.0,32.101.0,41.179.0,37.169.0,27.92.0,24.123.0"}
P.entries["quest:5725"] = {n="Сила нищити",s="Це доручення жахолорда Варіматраса в Андерсіті посилає шукачів пригод з Орди глибоко в Провалля Лютого Вогню під Оргріммаром. Леді Сильвана Віндраннер прагне здобути два темні фоліанти, якими володіє демонічний культ Пекучого Клинка, щоб підживити свою тривалу війну проти Погибелі й Короля-Ліча.",h="Це доручення жахолорда Варіматраса в Андерсіті посилає шукачів пригод з Орди глибоко в Провалля Лютого Вогню...",kw={"сила нищити","варіматрас","сильвана віндраннер","пекучий клинок","провалля лютого вогню","закляття тіні","андерсіті"},ang={["class:Warlock"]="Здобути «Закляття Тіні» й «Заклинання з Нижнього Світу» — знайома справа: вирвати небезпечні таємниці Легіону з рук нерозважливих культистів.",["faction:Horde"]="Знищення Пекучого Клинка допомагає вберегти підвалини Оргріммара, навіть якщо магічну здобич потай вивезуть до сховищ Андерсіті.",["race:Undead"]="Для поборників-Відступників переправитися через Велике море й пограбувати підчерев'я Оргріммара — це водночас служба союзові з Ордою й найголовнішому задуму Темної Леді знищити Погибель."},sec={{t="Позичений арсенал",b="Поки орки Тралла зосереджені на тому, щоб викорінити культистів Пекучого Клинка, які ховаються просто під їхньою столицею, Відступники бачать нагоду в окультних запасах культу. Варіматрас за наказом Сильвани Віндраннер посилає своїх людей пробратися в Провалля Лютого Вогню й заволодіти двома демонічними гримуарами: «Закляттями Тіні» та «Заклинаннями з Нижнього Світу». На думку Темної Леді, демонічними дарами куди краще розпорядиться дисциплінована воля Відступників, ніж їх змарнують жалюгідні культисти."},{t="Війна за визволення",b="Коли фоліанти здобуто, Варіматрас відкриває їхнє ширше призначення. Темна магія в них має посилити тривалий похід Сильвани проти Погибелі. Збираючи кожну крихту забороненої сили, Відступники сподіваються зламати хватку Короля-Ліча над Лордероном і цілком визволити решту нежиті з-під його влади над розумом."}},faq={{q="Навіщо Варіматрасові книги з-під Оргріммара?",a="Сектанти Пекучого Клинка в Проваллі Лютого Вогню мають могутні демонічні фоліанти. Леді Сильвана вважає, що ці артефакти Палаючого Легіону — марнотратство в руках простих сектантів, і хоче обернути їхнє темне знання проти Короля-Ліча.",al={"чому варіматрас лютий вогонь","причина завдання з андерсіті","навіщо красти книги"}},{q="Які книги треба зібрати?",a="Треба забрати в сектантів і чорнокнижників Пекучого Клинка дві книги заклять: «Закляття Тіні» й «Заклинання з Нижнього Світу».",al={"які книги","книги сили нищити","книги з провалля лютого вогню"}},{q="Де в Андерсіті знайти Варіматраса?",a="Варіматрас стоїть поруч із Леді Сильваною Віндраннер у Королівському Кварталі Андерсіті.",al={"де варіматрас","де знайти варіматраса","місце здачі"}},{q="Як це пов'язано із загальними цілями Відступників?",a="Сильвана збирає кожне можливе знаряддя для війни з Погибеллю. Заборонені демонічні таємниці дають Відступникам більший магічний важіль, щоб зламати владу Короля-Ліча над нежиттю.",al={"мотивація відступників","навіщо сильвані закляття","змова андерсіті проти короля-ліча"}},{q="Чи знає Тралл, що Відступники забирають ці книги?",a="Поки провід Орди в Оргріммарі зосереджений на тому, щоб вичистити зрадників і демонів з-під своїх вулиць, наказ Варіматраса подано як тиху справу для Темної Леді, а не як офіційне спільне рішення Орди.",al={"чи тралл знає","таємні книги оргріммара й андерсіті","реакція орків на книги тіньової ради"}},{q="Хто такий Пекучий Клинок?",a="Пекучий Клинок — таємна секта Ради Тіней, що діє просто в Проваллі Лютого Вогню під Оргріммаром і практикує темну демонічну магію під самим носом у Вождя.",al={"що таке пекучий клинок","пекучий клинок провалля","культисти провалля"}}},fp="23,288,18.494.0,22.344.0,58.238.0,35.126.0,47.89.0,53.203.0,53.239.0,26.182.0"}
P.entries["quest:5726"] = {n="Приховані вороги",s="«Приховані вороги» — перший розділ розслідування, яке Вождь Тралл веде щодо проникнення культистів у Дуротар. Знаючи, що прибічники демонів діють просто в Орди під носом, Тралл доручає перспективному молодому шукачеві пригод здобути Відзнаку Лейтенанта в Череп-скелі, щоб розпочати таємну операцію.",h="«Приховані вороги» — перший розділ розслідування, яке Вождь Тралл веде щодо проникнення культистів у Дуротар.",kw={"приховані вороги","тралл","палаючий клинок","череп-скеля","відзнака лейтенанта","культисти","дуротар"},ang={["class:Warlock"]="Чорнокнижникам Орди слід ступати обережно: практикуючи мистецтво Скверни під суворим наглядом Тралла, ви маєте викорінити культистів, чия нестримна служба демонам загрожує самому існуванню Оргріммара.",["faction:Horde"]="Це вирішальна мить: сам Вождь Тралл особисто доручає вам захистити серце нової Орди від демонічних підступів.",["race:Orc"]="Для орків, що силкуються позбутися кривавого туману й ганьби демонічного прокляття, полювання на Палаючий Клинок — особиста битва за те, щоб демонічна зараза вдруге не отруїла їхній народ."},sec={{t="Гниль у Дуротарі",b="Поки молода Орда силкується облаштувати надійну домівку в Дуротарі, Вождь Тралл стикається з підступною загрозою, набагато смертоноснішою за набіги кентаврів чи вилазки шипогривів, — зрадою зсередини. Демонічний культ, відомий як Палаючий Клинок, пустив коріння просто під брамами Оргріммара, живлячись залишками демонічної скверни та спрагою темної сили. Тралл розуміє: якщо послати офіційну варту Кор'крон чи відомих командирів, культисти лише розбіжаться й заховаються ще глибше. Йому потрібен хтось, не заплямований гучними зв'язками, — непомітні очі й вуха."},{t="Проникнення до Череп-скелі",b="На схід від Оргріммара лежить Череп-скеля — дика печера, що кишить чорнокнижниками, блукачами Порожнечі й фанатичними культистами. Тралл посилає шукача пригод просто в це кубло з чітким завданням: забрати Відзнаку Лейтенанта в одного з ватажків Палаючого Клинка. Ця емблема — не просто бойовий трофей, а важлива перепустка, що відкриває власникові доступ до таємної ієрархії культу. З нею можна провести глибшу операцію-пастку й з'ясувати, хто з-за лаштунків керує культом."}},faq={{q="Хто дає завдання «Приховані вороги»?",a="Завдання дає сам Вождь Тралл у Долині Мудрості в Оргріммарі — після того, як ви доповісте Орґнілові Соулскару.",al={"хто дає приховані вороги","хто починає приховані вороги","де почати приховані вороги"}},{q="Яка мета завдання «Приховані вороги»?",a="Тралл доручає вам вирушити до Череп-скелі на схід від Оргріммара, перебити сектантів Палаючого Клинка й принести Відзнаку Лейтенанта.",al={"мета прихованих ворогів","що потрібно для прихованих ворогів"}},{q="Чому Тралл просто не пошле добірну варту вичистити Череп-скелю?",a="Тралл боїться, що відкрите військове втручання дасть справжнім змовникам вислизнути й заховати гниль ще глибше. Невідомий шукач пригод може тихцем роздобути знаки розрізнення й проникнути в мережу, не сполохавши високопоставлених зрадників, що смикають за ниточки.",al={"чому тралл потребує мандрівників","чому не послати армію"}},{q="Що таке Череп-скеля?",a="Череп-скеля — відлюдна система печер на східному узбережжі Дуротару, на північний схід від Оргріммара. Це потаємна твердиня й лігво для прикликань секти Палаючого Клинка.",al={"де череп-скеля","що таке печера череп-скеля"}},{q="Навіщо Відзнака Лейтенанта?",a="Відзнака — доказ звання серед сектантів. Тралл хоче скористатися нею, щоб замаскувати свого агента й увести його в лави Палаючого Клинка, аби дізнатися, хто керує їхніми діями.",al={"навіщо відзнака лейтенанта","призначення відзнаки лейтенанта"}},{q="Які ще завдання можна виконати разом із цим?",a="Шукачі пригод, що йдуть до Череп-скелі, часто виконують ще завдання «Череп-скеля», збираючи нашийники сектантів, а з ватажка секти Ґазз'уза можна здобути Око Палаючої Тіні, з якого починається завдання «Палаючі тіні».",al={"завдання череп-скелі","завдання в череп-скелі"}}},fp="14,320,22.586.0,23.509.0,35.146.0,35.145.0,66.266.0,19.185.0,43.198.0,54.199.0"}
P.entries["quest:5727"] = {n="Приховані вороги",s="Після того як у Череп-скелі виявили сліди культу, Вождь Тралл доручає вам проникнути до Палаючого Клинка в самому Оргріммарі. Показавши відзнаку лейтенанта культу чорнокнижникові Ніру Файрблейду, ви перевіряєте його вірність і зриваєте завісу з Ради Тіней, що діє просто під містом.",h="Після того як у Череп-скелі виявили сліди культу, Вождь Тралл доручає вам проникнути до Палаючого Клинка в...",kw={"приховані вороги","ніру файрблейд","тіньова рада","палаючий клинок","тіньова розколина","провалля лютого вогню","тралл"},ang={["class:Warlock"]="Ніру запевняє, що обстоює інтереси чорнокнижників, які прагнуть законного місця в Орді, але його зрада може накликати сувору кару на всіх, хто практикує мистецтво Скверни під владою Тралла.",["faction:Horde"]="Звістка про те, що демонічні культи відкрито діють під самим кам'яним підмурком Оргріммара, загрожує існуванню молодої держави Орди.",["race:Orc"]="Для орків, які прагнуть позбутися спадку кровожерливості й демонічної скверни, відродження Ради Тіней під їхньою столицею — моторошна луна темного минулого на Дренорі."},sec={{t="Хитрість Вождя",b="Замість ударити просто по зловісних силах, що ховаються в Тіньовій Розколині, Тралл обирає хитрість, а не поспіх. Він добре знає, що Ніру Файрблейд удає вірність, а насправді потай служить культистам. Якщо вдарити по Ніру одразу, це лише сполохає його господарів і обірве будь-який слід, що веде вглиб змови. Натомість Тралл дає вам відзнаку, здобуту в культистів у Дуротарі, і просить видати себе за посвяченого, щоб з'ясувати, що відомо Ніру."},{t="Таємний господар Розколини",b="У темних печерах Тіньової Розколини, біля входу до Провалля Лютого Вогню, Ніру Файрблейд швидко ковтає наживку. Вважаючи вас новоспеченим лейтенантом свого ордену, чорнокнижник відверто глузує з необізнаності Тралла. Він розповідає, що Палаючий Клинок і його відгалуження, як-от Пекучий Клинок, — лише прикриття, а насправді вони підкоряються Раді Тіней, яка служить волі Палаючого Легіону. Ніру хвалиться, що змусив Вождя кидати вірних солдатів проти культистів у проваллі, — руками війська самого Тралла він відсіює слабких."}},faq={{q="Чому Тралл лишає Ніру живим, якщо знає, що той зрадник?",a="Тралл щадить Ніру, бо викритий зрадник цінніший за мертвого. Якщо його негайно стратити, Рада Тіней просто замінить його кимось, кого буде важче викрити. Тримаючи Ніру під пильним наглядом, Тралл перетворює чорнокнижника на мимовільне джерело відомостей про рух секти в Оргріммарі.",al={"чому тралл довіряє ніру","чому ніру живий","ніру зрадник"}},{q="Хто такий Ніру Файрблейд?",a="Ніру Файрблейд — орк-чорнокнижник, що мешкає в Тіньовій Розколині. На людях він удає, що допомагає Траллові перевиховувати чорнокнижників на сумлінних слуг Орди. Потай же він очолює секту Палаючого Клинка й плете зраду під містом в ім'я Ради Тіней.",al={"історія ніру","хто такий ніру"}},{q="Що пов'язує Палаючий Клинок і Раду Тіней?",a="Як розкриває Ніру, Палаючий Клинок — не незалежна секта, а рука самої Ради Тіней. Рада тримає кілька підлеглих сект — зокрема Пекучий Клинок у Проваллі Лютого Вогню, — щоб розділяти, обманювати й контролювати честолюбних практиків під верховною владою Палаючого Легіону.",al={"зв'язок палаючого клинка і ради тіней","чи палаючий клинок і рада тіней одне"}},{q="Хто очолює сектантів у Проваллі Лютого Вогню?",a="Секту Пекучого Клинка, що діє в провалі під Оргріммаром, очолюють сатир на ім'я Баззалан і орк-чорнокнижник Джерґош Призивач. Ніру кидає проти них шукачів пригод Тралла, використовуючи сутичку і щоб прорідити вірних Орді, і щоб випробувати своїх підлеглих.",al={"ватажки провалля лютого вогню","ватажки пекучого клинка"}},{q="Як я здобув Відзнаку Лейтенанта?",a="Відзнаку здобуто під час першого Траллового розслідування діяльності секти в Дуротарі — у сектантів Палаючого Клинка, що діють із Череп-скелі.",al={"звідки відзнака лейтенанта","джерело відзнаки"}}},fp="14,322,21.465.0,25.577.1,61.333.1,23.287.1,74.314.1,45.280.0,43.173.0"}
P.entries["quest:5728"] = {n="Приховані вороги",s="«Приховані вороги» — ключове доручення Вождя Тралла: проникнути до підступного культу, що процвітає під Оргріммаром, і знищити його. Обдуривши зрадливого Ніру Файрблейда, який повірив, що ви союзник, Тралл посилає вас у розпечені глибини Провалля Лютого Вогню вбити найвищих ватажків Пекучого Клинка.",h="«Приховані вороги» — ключове доручення Вождя Тралла: проникнути до підступного культу, що процвітає під...",kw={"приховані вороги","тралл","ніру файрблейд","пекучий клинок","баззалан","джерґош призивач","провалля лютого вогню"},ang={["class:Warlock"]="Тралл терпить чорнокнижників, які практикують темні мистецтва заради оборони Орди, але Джерґош і Пекучий Клинок переступили межу — до зрадницького служіння демонічним володарям.",["faction:Horde"]="Демонічне зіпсуття в самому серці Дуротару загрожує всьому, за що боролася нова Орда; очищення Провалля Лютого Вогню вкрай важливе, щоб зберегти здобуту тяжкою ціною незалежність.",["race:Orc"]="Для орків, що прагнуть спокутувати кривавий дурман минулого, викорінити рештки Ради Тіней під Оргріммаром — справа глибокого культурного виживання й честі."},sec={{t="Пухлина під вулицями",b="Оргріммар збудовано як притулок для вільного орківського народу, та в самих його підвалинах досі ховаються старі демонічні кайдани. Під гамірними ринками лежить Тіньова Розколина, звідки шлях веде ще глибше — у підземні тунелі Провалля Лютого Вогню. У цих вулканічних глибинах рештки Ради Тіней, відомі як Пекучий Клинок, набираються сили, практикують темні мистецтва й плетуть змову, щоб захопити владу над молодою Ордою з її ж столиці."},{t="Подвійна гра",b="Прямий напад без розвідки залишив би мережу Ради Тіней цілою. Тралл задумав таємний хід: через вас виманити відомості з Ніру Файрблейда — чорнокнижника з Тіньової Розколини, що вдавав готовність до співпраці. Повіривши у вашу відданість їхній викривленій справі, Ніру мимоволі видав імена підземних ватажків культу: розбещеного сатира Баззалана й чорнокнижника Джерґоша Призивача."},{t="Обезглавити Пекучий Клинок",b="Тралл доручає вам спуститися в Провалля Лютого Вогню й зарубати Баззалана та Джерґоша, кинувши культистів у хаос. Головне — удари мають лишитися непомітними: Ніру не повинен дізнатися, хто вчинив різанину, бо Тралл хоче й далі пильно стежити за чорнокнижником. Знищення цих призвідників струшує весь культ і дає молодому місту Орди дорогоцінний перепочинок."}},faq={{q="Хто наказує вбивство в завданні «Приховані вороги»?",a="Вождь Тралл особисто керує цим дорученням із Долини Мудрості в Оргріммарі, довіряючи вам делікатну шпигунську справу, щоб убезпечити підземелля міста.",al={"хто дає приховані вороги","хто видає приховані вороги","завдання тралла лютий вогонь"}},{q="Чому Тралл просто не стратить Ніру Файрблейда?",a="Тралл воліє тримати Ніру живим під наглядом. Знаючи, хто зрадник, розвідники Вождя можуть стежити за зв'язком Ради Тіней і передбачати майбутні змови, а не дозволяти прихованому наступникові зайняти його місце.",al={"чому не вбити ніру","чому ніру живий","ніру файрблейд зрадник"}},{q="Де знайти Баззалана й Джерґоша Призивача?",a="Обидва ватажки засіли глибоко в Проваллі Лютого Вогню — підземеллі, вхід до якого через Тіньову Розколину в Оргріммарі. Джерґош займає вулканічний виступ і командує сектантами, а сатир Баззалан чатує в піднесеній печері неподалік.",al={"де баззалан","де джерґош","боси провалля лютого вогню"}},{q="Хто такі Пекучий Клинок?",a="Пекучий Клинок — місцева секта, пов'язана з Палаючим Клинком і Радою Тіней. Сектанти поклоняються демонічним силам і практикують магію скверни під Оргріммаром, маючи кінцеву мету — повалити Тралла й знову поневолити Орду.",al={"хто такий пекучий клинок","культ пекучого клинка","палаючий клинок оргріммар"}},{q="Чому сатир на кшталт Баззалана діє під орківським містом?",a="Сатири — давні слуги Палаючого Легіону. Баззалан — демонічний наглядач і підбурювач, що спрямовує смертних сектантів Пекучого Клинка виконувати волю Легіону просто під ногами в Тралла.",al={"чому сатир в оргріммарі","переказ про баззалана","сатир у проваллі лютого вогню"}},{q="Яке місце це завдання посідає в ширшому поході до Провалля Лютого Вогню?",a="«Приховані вороги» — кульмінація Траллового ланцюжка з проникнення. Воно поєднується з кількома іншими завданнями в Проваллі Лютого Вогню й веде гравців до того, щоб одним злагодженим ударом знищити головних босів-гуманоїдів підземелля.",al={"чи приховані вороги в проваллі","ланцюжок завдань провалля","ланцюжок прихованих ворогів"}}},fp="14,323,28.426.0,24.430.1,30.409.2,37.166.0,48.242.1,51.232.0,26.228.0,57.211.0,60.230.0"}
P.entries["quest:5729"] = {n="Приховані вороги",s="«Приховані вороги» — переломний етап розслідування, яке Вождь Тралл веде щодо проникнення культистів в Оргріммар. Знищивши ватажків Палаючого Клинка під містом, ви маєте ще глибше втертися в довіру до Ніру Файрблейда.",h="«Приховані вороги» — переломний етап розслідування, яке Вождь Тралл веде щодо проникнення культистів в...",kw={"приховані вороги","ніру файрблейд","баззалан","джерґош призивач","провалля лютого вогню","тіньова розколина","тралл"},ang={["class:Rogue"]="Це завдання — класична операція з проникнення: знищити мережу агента й одразу стати його найдовіренішою особою.",["class:Warlock"]="Ніру Файрблейд відкрито стоїть серед наставників чорнокнижників у Тіньовій Розколині — це показує, як близько нова Орда Тралла ходить біля темної магії, не піддаючись при цьому відвертій скверні.",["faction:Horde"]="Це завдання підкреслює прагматичну дипломатію й державну мудрість Тралла: він захищає Оргріммар зсередини, покладаючись на контррозвідку, а не лише на грубу силу.",["race:Orc"]="Для орків, які прагнуть позбутися демонічної спадщини старої Орди, викорінити Палаючий Клинок із глибин Оргріммара — необхідна умова захисту власної честі."},sec={{t="Хід Тралла",b="Після вбивства Баззалана й Джерґоша Призивача в Проваллі Лютого Вогню Тралл бачить нагоду. Замість викрити Ніру Файрблейда відразу, Вождь вирішує вести довгу гру. Ніру стривожений раптовою втратою своїх підземних лейтенантів, і в місцевому культі утворилася порожнеча влади. Тралл відсилає вас назад у темні закутки Тіньової Розколини, щоб ви постали перед Ніру надійним союзником, здатним цю порожнечу заповнити."},{t="Ошуканий чорнокнижник",b="Коли ви підходите до Ніру Файрблейда в Тіньовій Розколині, він аж кипить від люті через раптову поразку своїх спільників. Не підозрюючи, що саме той шукач пригод, який стоїть перед ним, і виконав вирок за наказом Тралла, Ніру проклинає «добродіїв», що сплюндрували Провалля Лютого Вогню. Приголомшений стрімким ударом, Ніру поступово втрачає пильність поруч із вами — і це відкриває Траллові змогу стежити за впливом Ради Тіней просто зсередини Оргріммара."}},faq={{q="Чому Тралл не стратить Ніру Файрблейда негайно?",a="Тралл воліє тримати викритого ворога там, де може за ним стежити. Лишаючи Ніру на місці, певного, що його прикриття ціле, Тралл може стежити за зв'язком Палаючого Клинка й простежити їхні зв'язки аж до Ради Тіней, використовуючи гравця як свого агента всередині.",al={"чому пощадити ніру","чому тралл лишає ніру живим","ніру живий"}},{q="Хто такі Баззалан і Джерґош?",a="Баззалан був сатиром, а Джерґош Призивач — орком-чорнокнижником. Діючи глибоко в Проваллі Лютого Вогню під Оргріммаром, вони були польовими ватажками й змовниками секти Палаючого Клинка, доки Тралл не наказав їх убити.",al={"баззалан","джерґош","хто загинув у проваллі"}},{q="Чи розуміє Ніру, що його лейтенантів убили ви?",a="Ні. Ніру вихлюпує лють, вірячи, що їх заскочили й вирізали невідомі агенти Тралла, і геть не підозрює, що шукач пригод, який висловлює йому співчуття й пропонує допомогу, і є тим убивцею.",al={"чи ніру знає","ніру знає хто їх убив"}},{q="Де знайти Ніру Файрблейда?",a="Ніру Файрблейд — у Тіньовій Розколині, підземній печері під серцем Оргріммара, де подалі від решти міста збираються чорнокнижники, розбійники й заклиначі Тіні.",al={"де ніру","знайти ніру","де ніру файрблейд"}},{q="Що таке Палаючий Клинок?",a="Колись це був лютий клан із Дренора, але Палаючий Клинок виродився в демонічну секту, якою маніпулює Рада Тіней. У Калімдорі її рештки прагнуть підточити нову Орду Тралла й повернути демонічне рабство.",al={"палаючий клинок","культ палаючого клинка"}},{q="Що буде після розмови з Ніру?",a="Здобувши довіру Ніру й вислухавши його розпач через утрати в Проваллі Лютого Вогню, ви повертаєтеся до Тралла у Фортецю Ґроммаш, щоб доповісти про успіх і завершити ланцюжок із проникнення.",al={"що далі","продовження завдання"}}},fp="14,264,15.468.0,23.473.1,60.270.0,30.229.0,46.190.0,33.189.0,26.217.0,37.189.1"}
P.entries["quest:5730"] = {n="Приховані вороги",s="«Приховані вороги» — кульмінація операції Вождя Тралла, покликаної проникнути до ковену Палаючого Клинка, що зачаївся в Оргріммарі, і з'ясувати його сили. Здобувши довіру Ніру Файрблейда й повернувшись до Тралла, ви приносите важливі відомості про те, як далеко культ простягнув свої щупальця по Калімдору.",h="«Приховані вороги» — кульмінація операції Вождя Тралла, покликаної проникнути до ковену Палаючого Клинка, що...",kw={"приховані вороги","тралл","ніру файрблейд","тіньова рада","пекучий клинок","ашенваль","шпигунство"},ang={["class:Rogue"]="Це завдання — зразок раннього шпигунського ремесла Орди, де глибоке прикриття, контррозвідка й терпіння важать більше, ніж негайна сутичка.",["class:Warlock"]="Ніру Файрблейд уособлює небезпечний край практики Скверни й показує, як легко темне мистецтво зісковзує з дозволеної державою служби у відверте підкорення Раді Тіней.",["faction:Horde"]="Зрада, викрита в самих межах Оргріммара, доводить, що молода Орда мусить остерігатися давньої демонічної скверни всередині, водночас воюючи із зовнішніми ворогами."},sec={{t="Культ без маски",b="На прохання Вождя Тралла посланець відніс Відзнаку Лейтенанта, здобуту в Череп-скелі, Ніру Файрблейду — чорнокнижникові, що відкрито мешкає в Тіньовій Розколині, — а згодом завдав удару по ватажках Пекучого Клинка глибоко в Проваллі Лютого Вогню. Граючи роль охочого новобранця й носячи відзнаки полеглих культистів, посланець здобуває довіру Файрблейда, і чорнокнижник ненароком розкриває ширшу мережу, що стоїть за його діями."},{t="Шепіт Ради Тіней",b="Вважаючи, що здобув вірного лейтенанта, Ніру Файрблейд визнає, що втрата в Проваллі Лютого Вогню — прикра невдача для Пекучого Клинка, проте запевняє, що великі задуми Ради Тіней лишаються непорушними. Він розповідає, що агенти його господарів діють не лише в Пустках, а й далі — у лісах Ашенвалю. Ця звістка заскочує Тралла зненацька: демонічна змова сягає далеко за межі підземних тунелів столиці."},{t="Пильність Вождя",b="Замість негайно стратити Ніру, Тралл обирає обережний шлях. Поки Ніру не знає, що його викрито, Орда може стежити за його зв'язками й відстежувати щупальця культу в Дуротарі, Пустках і Ашенвалі. Вождь готує своїх розвідників і шпигунів до розслідування в цих краях, розуміючи, що викорінення демонічної скверни потребує точності, а не необачного поспіху."}},faq={{q="Яка мета цього завдання?",a="Треба пройти з Тіньової Розколини до Долини Мудрості в Оргріммарі й поговорити з Вождем Траллом, доповівши, що Ніру Файрблейд розповів про задуми Ради Тіней.",al={"мета прихованих ворогів","що робити в прихованих ворогах 5","здати тралла"}},{q="Чому Ніру Файрблейд мені довіряє?",a="Упродовж ланцюжка «Приховані вороги» ви здобули Відзнаку Лейтенанта в Палаючого Клинка на Череп-скелі й показали її Ніру під виглядом честолюбного новачка секти, переконавши його, що ви — вірний помічник.",al={"чому ніру мені довіряє","обман ніру","проникнення до файрблейда"}},{q="Чому Тралл не заарештує й не стратить Ніру Файрблейда одразу?",a="Живий і нічого не підозрюваний Ніру набагато корисніший. Дозволяючи йому вірити, що прикриття ціле, розвідники Тралла можуть стежити за посланнями Ніру й простежити його зв'язки аж до більших осередків Ради Тіней по всьому Калімдору.",al={"чому ніру живий","чому не вбити ніру","чому тралл лишає ніру"}},{q="Що нового Тралл дізнається з цієї доповіді?",a="Тралл дізнається, що за сектою під Оргріммаром стоїть Рада Тіней і що її агенти активно готують дії і в Пустках, і в лісах Ашенвалю.",al={"що дізнався тралл","рада тіней перелісок","таємниця ніру"}},{q="Чи Палаючий Клинок — те саме, що Пекучий Клинок?",a="Пекучий Клинок — місцева секта, що діє в Проваллі Лютого Вогню під Оргріммаром і є рукою ширшої секти Палаючого Клинка, якою керує демонічна Рада Тіней.",al={"палаючий клинок чи пекучий клинок","культи провалля лютого вогню","різниця між культами"}},{q="Чи продовжується цей ланцюжок десь далі?",a="Тралл велить вам відпочити й обіцяє згодом покликати знову, але жодного завдання, що одразу продовжувало б саме цю лінію таємного проникнення, немає.",al={"продовження прихованих ворогів","наступне завдання після прихованих ворогів","куди тралл посилає далі"}}},fp="14,287,15.454.1,30.485.2,24.412.1,31.184.0,34.223.1,64.212.1,56.182.1,57.188.0,40.157.0"}
P.entries["quest:5761"] = {n="Здолати звіра",s="Ніру Файрблейд, орк-чорнокнижник із Тіньової Розколини в Оргріммарі, посилає шукачів пригод з Орди глибоко в Провалля Лютого Вогню полювати на Тараґамана Голодного. Нібито виконуючи наказ Вождя Тралла, Ніру вимагає серце височенного вартового скверни як доказ падіння демонічного культу.",h="Ніру Файрблейд, орк-чорнокнижник із Тіньової Розколини в Оргріммарі, посилає шукачів пригод з Орди глибоко в...",kw={"здолати звіра","ніру файрблейд","тараґаман голодний","провалля лютого вогню","вартовий скверни","тіньова розколина","оргріммар"},ang={["class:Warlock"]="Працюючи в Тіньовій Розколині поруч із Ніру, чорнокнижники на власні очі бачать, яким хитким канатом є практика магії скверни під пильним поглядом Тралла.",["faction:Horde"]="Викорінити демонічну присутність, що гноїться просто під столицею Орди, — справа негайного виживання міста для кожного народу Оргріммара.",["race:Orc"]="Для орків, що прагнуть струсити спадок демонічного прокляття крові, вартовий скверни й демонічний культ просто під троном Тралла — нестерпна ганьба."},sec={{t="Загроза під містом",b="Під вулицями Оргріммара з червоної землі лежить Провалля Лютого Вогню — розпечена підземна розколина, де кишать троги, звірі й таємні посланці Пекучого Клинка. Нагорі, у Тіньовій Розколині, Ніру Файрблейд видає себе за вірного слугу, якому Тралл доручив очистити цю демонічну гниль. Він прямо вказує на Тараґамана Голодного — велетенського вартового скверни, що стоїть у серці печери, — називаючи демона призвідником підземного культу."},{t="Обман чорнокнижника",b="Принесене Ніру Файрблейдові серце Тараґамана здобуває щедру хвалу й обіцянки, що Тралл буде задоволений. Насправді ж Тараґаман — не справжній ватажок культу, а громило, яким не шкода пожертвувати. Спрямувавши героїв Орди на демона, Ніру дає Траллові показну перемогу, щоб приспати підозри, а справжню верхівку Пекучого Клинка й глибші справи під Оргріммаром ховає від пильнішого ока."}},faq={{q="Хто такий Тараґаман Голодний?",a="Тараґаман Голодний — могутній вартовий скверни, що стоїть на скелястому помості в серці Провалля Лютого Вогню. Ніру Файрблейд називає його ватажком сектантів Пекучого Клинка, що гніздяться під Оргріммаром.",al={"хто такий тараґаман","що таке тараґаман","переказ про тараґамана"}},{q="Хто дає завдання «Здолати звіра»?",a="Завдання дає Ніру Файрблейд у своєму наметі в Тіньовій Розколині — печерному кварталі чорнокнижників Оргріммара.",al={"хто дає здолати звіра","хто видає це завдання","завдання ніру файрблейда"}},{q="Навіщо Ніру серце Тараґамана?",a="Ніру стверджує, що серце потрібне, щоб довести Вождеві Траллу, що демонічну загрозу під Оргріммаром знищено.",al={"навіщо серце","навіщо серце тараґамана","чому ніру хоче серце"}},{q="Чи справді Тараґаман — ватажок Пекучого Клинка?",a="Ніру Файрблейд називає його їхнім ватажком. Тараґаман — грізний вартовий скверни, що живе серед сектантів Пекучого Клинка в серці Провалля Лютого Вогню.",al={"чи тараґаман справжній ватажок","хто веде пекучий клинок","ватажок тараґаман"}},{q="Де знайти Тараґамана?",a="Тараґаман Голодний стоїть на скельному помості, оточеному лавою, у середній частині Провалля Лютого Вогню, серед сектантів Пекучого Клинка.",al={"де тараґаман","де звір","де знайти тараґамана"}},{q="Як це завдання пов'язане з «Прихованими ворогами»?",a="У ланцюжку «Приховані вороги» Тралл розслідує проникнення Ради Тіней до Оргріммара й пильно стежить за Ніру Файрблейдом. Ніру дає це завдання, щоб показати Траллові відчутні успіхи в боротьбі з Пекучим Клинком.",al={"зв'язок з прихованими ворогами","ланцюжок прихованих ворогів","тралл і ніру"}}},fp="17,289,25.472.0,23.417.1,30.204.0,38.115.0,38.122.1,54.153.1,27.145.0,46.226.1"}
P.entries["quest:5762"] = {n="Гемет Несінгварі",s="Це доручення посилає мандрівників за море — із солончаків Калімдору в парні джунглі Долини Стренглторну. Кравел Колбірд, спритний торговець із Перегонів Міражу, доручає шукачам пригод доставити давно запізнілу посилку з особливими припасами славетному мисливцеві на велику дичину Гемету Несінгварі.",h="Це доручення посилає мандрівників за море — із солончаків Калімдору в парні джунглі Долини Стренглторну.",kw={"гемет несінгварі","кравел колбірд","долина стренглторну","набої","сафарі","перегони міражу"},ang={["class:Hunter"]="Доставивши особливі набої просто Гемету Несінгварі, слідопити знайомляться з найславетнішим сафарі на велику дичину в Азероті.",["race:Dwarf"]="Доставка особливих набоїв між двома знайомими пройдисвітами-дворфами показує, як далеко розкидає вихідців з Айронфорджа гонитва за монетою й здобиччю."},sec={{t="Доставка між континентами",b="На сліпучих просторах Мерехтливих Низин торгівля йде жваво, але вантажі часом запізнюються. Зрештою Кравел Колбірд отримує запізнілий ящик, призначений для одного з його заможних покровителів — Гемета Несінгварі. Гемет покинув Тисячу Голок задовго до того, як прибула посилка, але заздалегідь заплатив, щоб її переслали до його мисливського табору в глушині Долини Стренглторну. Не бажаючи сам вирушати в тяжку дорогу, Кравел наймає мандрівних шукачів пригод, готових перетнути океан."},{t="Набої для полювання",b="Розшукавши експедицію Несінгварі на північ від Базового Базового Табору Ґром'ґол, мандрівник дізнається, що лежить у важкому ящику: особливі набої великого калібру, без яких не повалити небезпечних хижаків, що нишпорять джунглями. Гемет одразу впізнає характерну білу кірку солончаків на спорядженні посланця й радіє, що давні зв'язки з хитрим Кравелом принесли його сафарі таку потрібну вогневу міць."}},faq={{q="Де починається й закінчується ця доставка?",a="Доставка починається в Кравела Колбірда на Перегонах Міражу в Мерехтливих Низинах на півдні Тисячі Голок. Завершується вона на іншому краю світу — у таборі експедиції Гемета Несінгварі на півночі Долини Стренглторну, трохи на північ від Ґром'ґола.",al={"початок і кінець завдання","де гемет","куди йти"}},{q="Що в Ящику Кравела?",a="У ящику — набої особливого калібру для зброї на великого звіра. Гемет Несінгварі замовив ці кулі, щоб пробивати товсті шкури найлютіших звірів Стренглторну.",al={"що в ящику","вміст ящика","посилка кравела"}},{q="Чому Кравел не доставив ящик сам?",a="Кравел — заповзятливий дворфійський торговець, зайнятий своїми вкладеннями й оборудками на Перегонах Міражу. Він воліє найняти перехожих шукачів пригод за гроші, які Несінгварі заплатив наперед, ніж кидати свій пост і перепливати моря.",al={"чому кравел найняв когось","чому кравелу потрібна допомога"}},{q="Як Гемет знає, звідки прийшов гонець?",a="Отримавши посилку, Гемет одразу чує й упізнає особливу соляну кірку на одязі гінця й зауважує, що той прийшов просто з Мерехтливих Низин, а не з якоїсь звичайної пустельної куряви.",al={"пустельна сіль","розмова гемета про сіль"}},{q="Які стосунки між Кравелом і Геметом?",a="Гемет — давній і вигідний клієнт Кравела. Кравел шанує Геметові глибокі кишені, а Гемет із теплотою вважає Кравела «старим сухарем» і шахраєм, що завжди щось мутить.",al={"історія кравела й гемета","чи вони знайомі"}},{q="Хто такий Гемет Несінгварі?",a="Гемет Несінгварі — знаменитий дворфійський стрілець, письменник і мисливець на великого звіра, що веде безконечне сафарі небезпечними нетрями Долини Стренглторну.",al={"хто такий гемет","переказ про несінгварі"}}},fp="16,316,27.507.0,23.417.0,39.265.0,30.179.0,44.241.0,48.209.0,51.178.0,24.157.0"}
P.entries["quest:579"] = {n="Бібліотека Стормвінда",s="Глибоко в Королівській Бібліотеці Фортеці Стормвінда головний бібліотекар Доньял Товальд опікується зібранням історичних текстів і хронік різних земель. З наказу юного короля Андуїна Рінна виділено кошти на переписування цих праць для громадян і вчених, які приносять офіційні бібліотечні талони. Так шукачі пригод можуть самі вивчати історію, фракції й легенди Азерота.",h="Глибоко в Королівській Бібліотеці Фортеці Стормвінда головний бібліотекар Доньял Товальд опікується зібранням...",kw={"бібліотека","стормвінд","доньял товальд","андуїн рінн","історія","бібліотечний талон"},ang={["class:Mage"]="Для знавців арканного мистецтва Королівська Бібліотека — важливий світський архів королівства: вона зберігає немагічні історичні хроніки, що доповнюють арканні студії в Кварталі магів.",["faction:Alliance"]="Бібліотека береже спільні тріумфи й трагедії Альянсу Лордерону й нагадує громадянам про історичні узи між людьми, дворфами, гномами та високими ельфами.",["race:Human"]="Відколи під час Першої війни розграбували Старий Стормвінд і загинули незліченні архіви, людські вчені надзвичайно цінують кожну хроніку, що вціліла, поки королівство відбудовувалося, — і дбайливо її переписують."},sec={{t="Королівський наказ про знання",b="Поки Верховний Лорд Болвар Фордрагон і Леді Катрана Престор за відсутності короля Варіана опікуються обороною та придворною політикою, юний король Андуїн спрямовує королівські кошти на освіту. Розуміючи, що знання історії важливе для майбутнього королівства, Андуїн профінансував переписування давніх рукописів та історичних щоденників. Королівська Бібліотека в залах Фортеці Стормвінда — не просто сховище державних таємниць, а й місце, де записані перекази зберігають і копіюють для тих, хто служить короні."},{t="Талони в обмін на книги",b="Переписувати вручну тендітний пергамент — справа, що потребує чимало часу, чорнила й королівського дозволу. Щоб упорядкувати видачу, головний бібліотекар Доньял Товальд приймає офіційні бібліотечні талони, які отримують шукачі пригод і вчені по всіх землях Альянсу. Натомість Товальд видає вірні списки історичних фоліантів — від давньої історії Східних Королівств до розповідей про далекі краї, — що допомагають зрозуміти конфлікти, які вирують за мурами столиці."}},faq={{q="Яка мета завдання «Бібліотека Стормвінда»?",a="Це завдання дає змогу обміняти Бібліотечний Папір у головного бібліотекаря Доньяла Товальда на книги з переказами. Вони розповідають передісторію різних сюжетів Альянсу, людей і земель Азерота.",al={"що робить це завдання","мета завдання бібліотека стормвінда","навіщо це завдання"}},{q="Хто такий Доньял Товальд?",a="Доньял Товальд — бібліотекар, що опікується Королівською Бібліотекою у Фортеці Стормвінда. Він порядкує зібранням писаних історій королівства й виконує наказ короля Андуїна роздавати копії гідним ученим і шукачам пригод.",al={"хто такий доньял товальд","бібліотекар стормвінда","хто дає книги"}},{q="Де взяти Бібліотечний Папір?",a="Бібліотечний Папір дають за певні завдання на землях Альянсу — від учених, магістратів чи урядовців, які винагороджують дослідження й цікавість до широкого світу.",al={"де взяти бібліотечний папір","як отримати бібліотечний папір","джерело бібліотечного паперу"}},{q="Чому юний король Андуїн фінансує бібліотеку?",a="Король Андуїн Рінн особисто дуже цінує науку й освіту. Навіть правлячи дитиною під опікою регента Болвара Фордрагона, він виділив королівські кошти, щоб копії історичних фоліантів королівства стали доступні людям.",al={"чому андуїн піклується про книги","андуїн фінансує бібліотеку","король андуїн і книги"}},{q="Де в Стормвінді бібліотека?",a="Королівська Бібліотека — у Фортеці Стормвінда, величезній твердині, що панує над східною частиною міста. Доньяла Товальда можна знайти всередині серед високих полиць і читальних столів.",al={"де бібліотека стормвінда","де королівська бібліотека","де доньял товальд"}},{q="Чи можна читати отримані книги?",a="Так. Кожна книга з бібліотеки — предмет, який можна прочитати в грі; він дає атмосферу, оповідну передісторію й контекст для різних легенд та історичних подій світу Warcraft.",al={"чи книги читабельні","чи можна відкрити книги","чи книги щось дають"}}},fp="17,403,29.547.0,18.488.0,51.220.0,21.232.0,36.190.0,45.242.0,42.202.0,31.193.0"}
P.entries["quest:58"] = {n="Нічна Варта",s="Це останнє доручення Командира Алтеї Ебонлок посилає шукачів пригод з Альянсу до склепів у східній частині Цвинтаря Воронячого Пагорба. Нічна Варта ледве встигає захищати Даркшир, тож чужинці мусять увійти до гробниць і винищити розносників чуми, що там кишать. Це вершина прямої військової кампанії міської варти, спрямованої на те, щоб стримати навалу нежиті.",h="Це останнє доручення Командира Алтеї Ебонлок посилає шукачів пригод з Альянсу до склепів у східній частині...",kw={"нічна варта","алтея ебонлок","мавзолей","розносники чуми","цвинтар воронячого пагорба","гулі"},ang={["class:Paladin"]="Заражені чумою склепи Воронячого Пагорба — нечестиве глузування зі священних похоронних обрядів, тож очищення його гробниць — важливий обов'язок слуг Святого Світла.",["class:Priest"]="Мерзенна зараза, яку розносять гулі зі східного мавзолею, кидає виклик святості Світла й вимагає очищення і духовного, і тілесного.",["faction:Alliance"]="Королівська Корона в Стормвінді не чує благань Сутінколісся, тож захисники Альянсу мусять самі стати до бою, щоб уберегти вірних підданих від навали нежиті."},sec={{t="Відчайдушне прикордоння",b="Даркшир стоїть майже цілком самотою: армія Стормвінда його покинула, і він покладається лише на власне ополчення — Нічну Варту. Командир Алтея Ебонлок вичерпала свої мізерні сили, охороняючи перехрестя, міський периметр і шляхи постачання. Неспокійні мерці множаться по всьому Сутінколіссю, тож командирці не лишається нічого іншого, як наймати мандрівних звитяжців і нести бій просто в темні закутки Воронячого Пагорба."},{t="Очищення мавзолею",b="Східний мавзолей Цвинтаря Воронячого Пагорба — одне з найнебезпечніших скупчень нежиті в краї. На відміну від відкритих курганів, цей кам'яний склеп кишить розносниками чуми — гулями, що несуть скверну, здатну вразити живих. Двадцять знищених потвор дарують утомленій Нічній Варті дорогоцінний перепочинок і не дозволяють нежиті вдарити по Даркширу злагодженим наступом із заходу."}},faq={{q="Чому Нічна Варта посилає шукачів пригод, а не своїх людей?",a="Сили Нічної Варти розпорошені по всьому Сутінколіссю. Стормвінд не дає жодних офіційних військ, тож Командирові Алтеї Ебонлок ледве вистачає вартових, щоб тримати околиці Даркширу й стежити за дорогами, — для зачистки глибоких укріплених склепів на кшталт Воронячого Пагорба вільних ополченців немає.",al={"чому допомагати даркширу","чому нічній варті потрібна допомога","нічної варти мало"}},{q="Де розташований східний мавзолей?",a="Він у східній частині Цвинтаря Воронячого Пагорба на північному заході Сутінколісся. Вхід веде під землю, до кам'яних склепів, де збираються розносники чуми.",al={"де розносники чуми","де східний мавзолей","де мавзолей"}},{q="Чим небезпечні розносники чуми?",a="Розносники чуми — ненажерливі гулі, що несуть заразний тлін. Якщо їх не стримувати, їхня мерзенна скверна може вийти за межі цвинтаря й заразити вцілілих мешканців Даркширу.",al={"чому вбивати розносників чуми","хто такі розносники чуми"}},{q="Хто така Командир Алтея Ебонлок?",a="Алтея Ебонлок — командирка й провідниця Нічної Варти, а також родичка мера Даркширу, Лорда Елло Ебонлока. Вона організовує оборону Сутінколісся з Даркширу.",al={"хто така алтея","командир ебонлок","хто очолює нічну варту"}},{q="Чи кладе цей ланцюжок край загрозі нежиті в Сутінколіссі?",a="Ні. Проріджування мавзолею послаблює безпосередній тиск на Даркшир, але Воронячий Пагорб і далі кишить нежиттю, а темніші сили по всьому Сутінколіссю й далі збурюють мертвих.",al={"чи врятовано воронячий пагорб","чи даркшир тепер безпечний"}},{q="Яке місце це посідає в ланцюжку «Нічна Варта»?",a="Це третій і останній розділ бойової серії «Нічна Варта» від Командира Ебонлок: від відкритих доріг до околиць цвинтаря, а зрештою — глибоко в мавзолей.",al={"який це ланцюжок","чи це останнє завдання нічної варти"}}},fp="15,358,20.458.0,21.438.0,68.281.0,39.175.0,42.187.0,34.190.0,61.180.0,49.193.0"}
P.entries["quest:5881"] = {n="Виклик резервів",s="«Виклик резервів» — завдання гінця Орди, яке доручають шукачам пригод, що відпочивають у Притулку Сонячної Скелі. Маґґран Ертбайндер посилає вас на південь, на край Пусток, із наказом змінити виснаженого вартового, що стереже Великий Підйомник.",h="«Виклик резервів» — завдання гінця Орди, яке доручають шукачам пригод, що відпочивають у Притулку Сонячної...",kw={"виклик резервів","великий підйомник","ґріш лонґраннер","маґґран ертбайндер","притулок сонячної скелі","вартовий"},ang={["faction:Horde"]="Це доручення показує, як командири Орди розпоряджаються силами на кордонах Калімдору: вони міняють вартових, щоб підтримувати бойовий дух і надійність застав.",["race:Tauren"]="Допомагаючи міняти вартових біля Великого Підйомника, ви підтримуєте життєво важливий прохід, що з'єднує південь Калімдору з широкими землями Тандер Блафа."},sec={{t="Довгоочікувана зміна",b="Навіть у часи відносного добробуту після Третьої війни утримувати гарнізони по всьому центральному Калімдору — важке випробування для сил Орди. У Притулку Сонячної Скелі в Горах Кам'яного Кігтя за постачанням і добробутом вояків наглядає Маґґран Ертбайндер. Розуміючи, що навіть загартовані бійці виснажуються від нескінченної варти, Маґґран відсилає на південь, до Великого Підйомника, наказ про переведення: там далеко від дому стоїть на посту молодий вартовий Ґріш Лонґраннер."},{t="Варта біля Підйомника",b="Великий Підйомник — єдина інженерна артерія, що з'єднує високі плато південних Пусток із вивітреними каньйонами Тисячі Голок унизу. Лист, переданий Ґрішеві, звільняє його від самотньої й одноманітної варти біля механізмів підйомника: нарешті він зможе повернутися до родини, а на зміну стануть свіжі резерви."}},faq={{q="Хто дає це завдання?",a="Завдання дає Маґґран Ертбайндер у Притулку Сонячної Скелі, високо в Горах Кам'яного Кігтя.",al={"хто дає завдання","де взяти виклик резервів","де маґґран"}},{q="Куди доставити лист Маґґрана?",a="Треба віднести Резервний Лист Маґрана на південь через Пустки аж до Великого Підйомника — величезної дерев'яної споруди-підйомника на кордоні, звідки видно Тисячу Голок.",al={"де ґріш лонґраннер","де ґріш","де великий підйомник"}},{q="Чому Ґрішеві Лонґраннеру потрібна заміна?",a="Ґріш довго ніс службу сам, стережучи механізми підйомника. Він давно подав офіційне прохання, щоб його змінили й він міг поїхати додому провідати родину.",al={"історія ґріша","чому ґріш іде","варта на великому підйомнику"}},{q="Чи треба в цьому завданні битися?",a="Битися не треба. Це суто доручення гінця, що має скерувати мандрівників на південь, до Тисячі Голок.",al={"чи треба битися","мирне завдання","завдання гінця"}},{q="Яка фракція дає репутацію за це завдання?",a="Доставка листа Ґрішеві дає репутацію з Тандер Блафом — адже на цьому шляху присутні й порядкують таурени.",al={"репутація за нагороду","яку репутацію дає","репутація тандер блафа"}},{q="Куди веде це завдання далі?",a="Доставка приводить вас просто на вершину Великого Підйомника, звідки можна спуститися підйомниками в каньйони Тисячі Голок і досліджувати нові застави Орди.",al={"наступне завдання","куди йти далі","завдання тисячі голок"}}},fp="23,234,21.467.0,17.366.0,22.102.0,36.185.0,38.180.0,44.111.0,52.134.0,32.174.0"}
P.entries["quest:59"] = {n="Полотняна і шкіряна броня",s="«Полотняна і шкіряна броня» — доручення Вартового Томаса біля східного мосту в Лісі Елвінн. Вражений службою шукача пригод, Томас видає офіційний військовий талон на обладунок, який можна обміняти в місцевої майстрині Сари Тімберлейн. Завдання веде новобранців далі на схід, до Лісозаготівельного Табору Східної Долини, по належне спорядження для захисту королівства.",h="«Полотняна і шкіряна броня» — доручення Вартового Томаса біля східного мосту в Лісі Елвінн.",kw={"броня","талон на обладунок","вартовий томас","сара тімберлейн","східна долина","кравецтво"},ang={["faction:Alliance"]="Спорядження захисників через місцеві замовлення показує, як сільські громади Елвінну тримають Альянс на ходу, попри політичний параліч у столиці.",["profession:Tailoring"]="Армійське замовлення Сари Тімберлейн доводить, що кравецтво — важливе й офіційно підтримуване військове ремесло в королівстві.",["race:Human"]="Служба Вартовому Томасу й торгівля з Сарою Тімберлейн відображають спільні громадські зв'язки, що тримають укупі невеликі садиби Лісу Елвінн."},sec={{t="Знак від вартового",b="Вартовий Томас несе варту на східній переправі через річку в Елвінні, тримаючи кордон проти ворожих мурлоків і мандрівних гнолів. Цінуючи зусилля здібних мандрівників, що допомагають його самотньому посту, він дає їм офіційний Талон на Обладунок Стормвінда замість віддавати спорядження зі своїх убогих польових запасів. Цей талон — військовий реквізиційний документ, який офіційно визнає службу власника короні."},{t="Ткаля Східної Долини",b="За мостом на схід лежить Лісозаготівельний Табір Східної Долини — головна лісозаготівля Елвінну. Саме звідти працює Сара Тімберлейн, яка має офіційне замовлення від армії Стормвінда на виготовлення спорядження з тканини та шкіри. Централізовані арсенали королівства виснажені й розтягнуті до краю, тож такі місцеві майстри, як Сара, незамінні, коли треба спорядити війська й допоміжних розвідників на прикордонні."}},faq={{q="Що таке Талон на Обладунок Стормвінда?",a="Це офіційна військова розписка, яку видають офіцери на кшталт Вартового Томаса. Замість тримати громіздкі комплекти обладунків на віддалених сторожових постах, вартові мають талони, за якими надійні новобранці можуть отримати обладунки, припасовані цивільними майстрами на замовлення війська.",al={"талон на обладунок","стормвіндський талон","що таке талон"}},{q="Хто така Сара Тімберлейн?",a="Сара Тімберлейн — кравчиня й майстриня з Лісозаготівельного Табору Східної Долини. Вона має угоду з військом Стормвінда на виготовлення тканинного й шкіряного спорядження для людей королівства й дозволених допоміжних бійців.",al={"сара тімберлейн","кравчиня східної долини","хто робить обладунок"}},{q="Де розташований Лісозаготівельний Табір Східної Долини?",a="Лісозаготівельний Табір Східної Долини — на крайньому сході Лісу Елвінн. Від посту Вартового Томаса біля мосту через річку йдіть дорогою на схід у лісисту долину, де лісоруби заготовляють деревину для королівства.",al={"де східна долина","як дістатися тімберлейн","де лісозаготівельний табір"}},{q="Чому Вартовий Томас посилає шукачів пригод до Східної Долини?",a="Томас не тримає на своєму пості біля річки запасу готового спорядження. Натомість він винагороджує сміливі вчинки, посилаючи новобранців до Сари Тімберлейн, — так мандрівники потрапляють до Східної Долини й водночас отримують належний захист, щоб боронити Елвінн.",al={"чому вартовий томас посилає","навіщо томас","чому східна долина"}},{q="Чому військо покладається на місцевих кравців?",a="Король Варіан Рінн зник, а військо Стормвінда розпорошене через Дефіас і диких звірів, тож місцеві оборонні пости значною мірою залежать від найнятих у краї робітників, що підтримують постачання.",al={"проблеми постачання стормвінда","чому місцеві ремісники","логістика війська"}},{q="Від кого захищає край Вартовий Томас?",a="Вартовий Томас наглядає за східним кордоном Лісу Елвінн, стережучи міст від набігів річкових мурлоків, хижих звірів і небезпек дикої глушини на межі з Горами Редріджу.",al={"вороги вартового томаса","загрози біля мосту","загрози східного елвінна"}}},fp="23,360,15.429.0,22.402.0,33.259.0,23.223.0,35.202.0,51.242.0,54.211.0,38.202.0"}
P.entries["quest:590"] = {n="Угода з пройдисвітом",s="Угода з пройдисвітом — сутичка з Келвіном Монтеґ'ю в Похоронному Подзвоні. Запропонувавши щойно пробудженим Відступникам роботу з обіцянкою багатства, хитрий розбійник виказує справжні наміри, коли від нього вимагають платню.",h="Угода з пройдисвітом — сутичка з Келвіном Монтеґ'ю в Похоронному Подзвоні.",kw={"угода з пройдисвітом","келвін монтеґ'ю","розбійник","платня","дуель","похоронний подзвін"},ang={["class:Rogue"]="Зустріч із Келвіном Монтеґ'ю дає молодим розбійникам миттєвий урок професійного ризику: нікому не вірте, пильнуйте гаманець і ніколи не дозволяйте іншому пройдисвіту піти з вашою часткою.",["race:Undead"]="Пробудження в Похоронному Подзвоні швидко доводить: смерть не позбавляє людство найдрібніших вад; шахраї з Відступників так само охоче дурять своїх, як і живі розбійники."},sec={{t="Безчесна обіцянка",b="Келвін Монтеґ'ю тиняється біля склепів Похоронного Подзвону, пропонуючи новопіднятим Відступникам на позір легку роботу. Запевняючи, що за доставку листа можна заробити добру монету, Монтеґ'ю посилає зелених шукачів пригод у небезпеку. Та щойно доручення виконано, Монтеґ'ю зручно забуває про обіцяну платню, вдаючи цілковите невідання щодо будь-якої домовленості чи боргу."},{t="Розплата",b="Коли від нього вимагають дотримати слова, Монтеґ'ю показує своє справжнє обличчя. Замість розлучатися зі своїм сріблом він береться за зброю, розраховуючи легко зарубати недосвідченого новачка. Лише добряче відлупцювавши розбійника, його можна змусити поступитися. Ґрунтовно побитий, він викашлює частку монет і відверто визнає, що збрехав про винагороду просто тому, що думав: йому це зійде з рук."}},faq={{q="Чому Келвін Монтеґ'ю нападає, коли в нього просять платню?",a="Келвін Монтеґ'ю — безсовісний розбійник, що й не думав ділитися грошима. Коли йому нагадують про порушену обіцянку, він намагається назавжди змусити помічника замовкнути, аби не платити, гадаючи, що щойно піднятий Відступник буде легкою здобиччю.",al={"чому келвін б'ється","келвін монтеґ'ю ворожий","чому пройдисвіт нападає"}},{q="Де відбувається ця сутичка?",a="Сутичка відбувається просто в Похоронному Подзвоні — зруйнованому селищі на південному заході Галявин Тірісфалю, де вперше прокидаються щойно підняті Відступники.",al={"де келвін монтеґ'ю","місце келвіна монтеґ'ю","де угода з пройдисвітом"}},{q="Чи справді Келвін Монтеґ'ю платить обіцяне?",a="Ні. Переможений у бою, Келвін здається й віддає трохи грошей, але визнає, що це набагато менше, ніж він обіцяв, бо брехав про всю суму від самого початку.",al={"нагорода келвіна","чи келвін платить","чи він збрехав про гроші"}},{q="Як відкривається це друге доручення?",a="Виконавши перше доручення Келвіна Монтеґ'ю з доставкою, поверніться й поговоріть із ним знову, щоб вимагати обіцяних грошей. Щойно ви викриєте його брехню, починається бій.",al={"як отримати частину 2","відкрити бій угоди з пройдисвітом","таємне завдання пройдисвіта"}},{q="Чи гине Келвін Монтеґ'ю, коли його переможено?",a="Ні. Монтеґ'ю здається, перш ніж отримає смертельний удар, рясно хвалить вашу бойову вправність і неохоче розв'язує гаманець, щоб урятувати власну шкуру.",al={"чи я вбив келвіна","чи келвін мертвий","келвін здається"}},{q="Якого уроку ця сутичка навчає нових Відступників?",a="Це ранній практичний урок суворої дійсності Відступників: честі серед нежиті обмаль, слова дешеві, а повагу здобувають лише бойовою силою.",al={"сенс угоди з пройдисвітом","переказ про угоду з пройдисвітом"}}},fp="14,216,22.368.0,16.390.1,55.244.1,41.145.0,51.177.1,33.183.1,39.153.1,54.183.0"}
P.entries["quest:5921"] = {n="Місячний Гай",s="«Місячний Гай» — вступний обряд посвяти для молодих друїдів нічних ельфів, що вчаться єднатися зі священними землями Калімдору. Під проводом Матренґіла Берволкера в Дарнасусі новачки вивчають закляття, яке магічно переносить їх через увесь світ до Місячного Гаю, де в Нічному Притулку на них чекає Дендрит Старблейз. Так починається їхня духовна подорож до опанування сили ведмежої форми.",h="«Місячний Гай» — вступний обряд посвяти для молодих друїдів нічних ельфів, що вчаться єднатися зі священними...",kw={"місячний гай","нічний притулок","хранитель ремулос","дендрит старблейз","телепортація","форма ведмедя","друїд"},ang={["class:Druid"]="Ця подорож — ваше пробудження до друїдської спадщини всього світу: відтепер у вас є вічна ниточка до спокійного серця Кола Кенарія.",["faction:Alliance"]="Дарнасус стоїть за Альянс, але Місячний Гай нагадує друїдам нічних ельфів про давніше, вище покликання, що стоїть понад земними фракціями.",["race:NightElf"]="Покинувши гілля Тельдрассилу заради прадавнього Місячного Гаю, молоді калдореї торкаються батьківщини предків, що вціліла ще з часів до Великого Розколу."},sec={{t="Священний прихисток",b="Місячний Гай стоїть осібно від решти Азероту — це прадавнє святилище, присвячене вченню Кенарія. Під пильною опікою Хранителя Ремулоса його спокійні гаї дарують мир і глибоке єднання з природою. Для молодого друїда навчитися переносити себе через землі до Місячного Гаю закляттям телепортації — важливий крок: відтепер серце друїдської мудрості завжди поруч, хоч би якими далекими були смертні відстані."},{t="Політика Кола",b="Місячний Гай відкритий для всіх, хто йде шляхом дикої природи, але й тут не без напруги. Між Архідруїдом Фандралом Стаґгелмом у Дарнасусі й Хранителем Ремулосом у Місячному Гаю росте розлам щодо опіки над природою та створення Тельдрассилу. Та попри ці філософські тріщини в Колі Кенарія, молодих послушників і далі беззастережно приймають у прихистку Нічного Притулку, щоб вони могли продовжувати священну науку."},{t="Шлях Ведмедя",b="У Нічному Притулку новачок постає перед Дендритом Старблейзом — старійшиною, що веде початківців шляхами Пазура. Перш ніж посвячуваний зможе прийняти мантію ведмедя, він має пройнятися його баченням: витривалістю, люттю й незламним захистом дикої природи. Старблейз приймає кожного нового учня з благоговійною шаною до Батька Кенарія й розпочинає випробування Великого Духа Ведмедя."}},faq={{q="Навіщо друїди вчаться телепортуватися до Місячного Гаю?",a="Телепорт до Місячного Гаю з'єднує друїда безпосередньо із серцем його ордену. Оскільки навчання, спілкування з духами й засідання вищої ради відбуваються в Нічному Притулку, миттєвий духовний провідник дає кожному змогу повернутися, щоб учитися й відновлювати духовні сили.",al={"навіщо телепорт у місячний гай","мета телепорту в місячний гай","чому йти до місячного гаю"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — друїд-старійшина на горішньому поверсі великої оселі в Нічному Притулку. Він опікується новачками, що прибувають до Місячного Гаю, і починає їхні випробування з опанування звіриного світогляду — першим іде первісний дух ведмедя.",al={"роль дендрита старблейза","хто такий дендрит","дендрит старблейз"}},{q="Яка напруга існує між Фандралом Стаґгелмом і Хранителем Ремулосом?",a="Архідруїд Фандрал Стаґгелм очолив вирощування Тельдрассилу без благословення Драконячих Аспектів, обстоюючи для нічних ельфів агресивнішу, націоналістичну позицію. Хранитель Ремулос і прихильники традицій у Місячному Гаю лишаються вірними давнім нейтральним шляхам Кенарія, і це породжує ідейне тертя в Колі Кенарія.",al={"напруга стаґгелма і ремулоса","фандрал проти ремулоса","розкол кола"}},{q="Чи можуть друїди Орди теж навідуватися до Місячного Гаю?",a="Так. Місячний Гай — нейтральний притулок під захистом Хранителя Ремулоса й Кола Кенарія. І нічні ельфи, і таурени-друїди бажані в Нічному Притулку, щоб разом пізнавати дикі шляхи, відклавши фракційну ворожнечу під миром Кенарія.",al={"місячний гай орда","чи таурени можуть бути в місячному гаю","чи місячний гай нейтральний"}},{q="Що буде, коли дістатися Дендрита Старблейза?",a="Коли ви доповідаєте Дендритові Старблейзу, він веде вас до обрядового випробування Великого Духа Ведмедя. Ця духовна зустріч перевіряє вашу рішучість і розуміння, перш ніж вам дозволять опанувати первісну силу ведмедя.",al={"після завдання місячного гаю","наступний крок ведмежа подоба","наступне ведмеже завдання"}},{q="Де в Нічному Притулку знайти Дендрита?",a="Дендрит Старблейз — у головній оселі нічних ельфів біля центру Нічного Притулку; він стоїть на балконі другого поверху, звідки видно все селище.",al={"знайти дендрита старблейза","де дендрит старблейз","де дендрит"}}},fp="9,404,15.446.0,22.424.0,20.412.0,45.299.0,26.243.0,64.338.0,41.247.0,47.229.0,40.160.0"}
P.entries["quest:5922"] = {n="Місячний Гай",s="Це завдання знайомить юного друїда-таурена з Місячним Гаєм — священним прихистком друїдів Кенарія. Під проводом Турака Рунтотема з Тандер Блафа учень учиться долати простори світу наяву, щоб єднатися безпосередньо з прадавніми охоронцями природи.",h="Це завдання знайомить юного друїда-таурена з Місячним Гаєм — священним прихистком друїдів Кенарія.",kw={"місячний гай","друїд","турак рунтотем","нічний притулок","хранитель ремулос","дендрит старблейз","великий дух ведмедя"},ang={["class:Druid"]="Цей обряд посвяти долає відстань між традиційними племінними віруваннями й ширшим ученням Кола Кенарія, відчиняючи двері до прадавніх форм перевтілення.",["faction:Horde"]="Хоч у Калімдорі тліє напруга, друїди Орди знаходять у Місячному Гаю одне з небагатьох місць у світі, де можна мирно зустрітися зі своїми побратимами — нічними ельфами.",["race:Tauren"]="Для учнів-тауренів прибуття до Місячного Гаю — глибоке пробудження: доказ того, що їхні прадавні узи із Земною Матір'ю глибоко співзвучні з ученням Кенарія."},sec={{t="Священний прихисток понад фракціями",b="Місячний Гай стоїть осторонь бурхливої політики Калімдору. Ця прадавня долина під первісним гіллям, яку оберігає Хранитель Ремулос, син Кенарія, — нейтральний прихисток для всіх, хто йде шляхом природи. Нічний ельф чи таурен — кожен друїд, що входить до Нічного Притулку, стає там рівним серед рівних під вічним покровом Кола Кенарія."},{t="Стрибок через Калімдор",b="Щоб сприяти вашому духовному й бойовому зростанню, Турак Рунтотем навчає вас особливого заклинання переміщення, пов'язаного із самою долиною. Прикликаючи містичний зв'язок між друїдами й світом природи, ви долаєте сотні ліг за один удар серця. Цей прихисток стане для вас і залою науки, і незмінним притулком упродовж усієї подорожі."},{t="Пробудження ведмедя",b="Прибувши до Нічного Притулку, ви зустрічаєте Дендрита Старблейза — старшого друїда з нічних ельфів, що чекає на нових учнів. Під його проводом починається перше справжнє випробування вашого покликання: побачити світ очима ведмедя. Щоб прийняти шлях Пазура, треба довести свою силу, відвагу й рівновагу перед Великим Духом Ведмедя."}},faq={{q="Чому таурени можуть навідуватися до притулку нічних ельфів, як-от Місячного Гаю?",a="Місячний Гай — суверенна священна земля під опікою Кола Кенарія на чолі з Хранителем Ремулосом. У її межах відданість природі й Кенарію цілком переважує протистояння Орди й Альянсу, тож таурени й нічні ельфи-друїди мирно навчаються й живуть пліч-о-пліч.",al={"чому таурени в місячному гаю","чи орді можна в місячний гай","чи місячний гай нейтральний"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — друїд-старійшина нічних ельфів у поселенні Нічний Притулок. Він наставляє новачків обох рас, що щойно прибули, і проводить їхні перші випробування, коли вони налаштовуються на давні звірині аспекти.",al={"дендрит старблейз","хто такий дендрит","видавець завдання нічний ельф"}},{q="Хто такий Хранитель Ремулос?",a="Хранитель Ремулос — могутній Хранитель Гаю й син напівбога Кенарія. Він — верховний охоронець Місячного Гаю: пильнує священні кургани, де сплять друїди, і стежить, щоб святість долини лишалася непорушною.",al={"хранитель ремулос","ремулос місячний гай","хто охороняє місячний гай"}},{q="Що буде, коли дістатися Місячного Гаю?",a="Розмова з Дендритом Старблейзом починає ваше випробування Великим Духом Ведмедя. Він посилає вас до оселі духа на північному заході Місячного Гаю, щоб пізнати силу тіла й силу серця — перший крок до таємниць ведмежої подоби.",al={"що робити далі","ведмежий ланцюжок завдань","після завдання місячного гаю"}},{q="Як «Телепорт: Місячний Гай» діє з погляду переказів?",a="Друїди сплітають природну лей-енергію й свій духовний зв'язок із Колом Кенарія, щоб миттєво подолати відстань між тим місцем, де стоять, і серцем Місячного Гаю. Це духовний якір, що дає змогу повертатися по науку й розраду, щойно їх покличуть.",al={"переказ про телепорт у місячний гай","закляття телепорту друїда"}},{q="Де знайти Турака Рунтотема?",a="Турак Рунтотем мешкає на Узвишші Старійшин у Тандер Блафі; він наставляє молодих тауренів, що почули поклик дикої природи, а тоді посилає їх до Місячного Гаю.",al={"де турак рунтотем","де турак"}}},fp="9,253,29.367.0,24.339.0,18.320.1,54.310.0,26.218.0,22.251.0,38.257.0,44.275.0,33.155.0"}
P.entries["quest:5923"] = {n="Почути поклик",s="«Почути поклик» — мить, коли учень-друїд нічних ельфів привертає увагу старшого проводу Кола Кенарія. Покликаний до Дарнасуса на зустріч із Матренґілом Берволкером, молодий посвячуваний ступає на священний шлях до опанування першого звіриного образу — ведмедя.",h="«Почути поклик» — мить, коли учень-друїд нічних ельфів привертає увагу старшого проводу Кола Кенарія.",kw={"почути поклик","матренґіл берволкер","ценаріонський анклав","фандрал стаґгелм","форма ведмедя","друїд","терідран"},ang={["class:Druid"]="Це завдання знаменує ваш офіційний перехід від новачка, що плете закляття коріння й гніву, до справжнього друїда, який змінює подобу й пізнає духів Калімдору.",["faction:Alliance"]="Те, що це завдання можна отримати в Терідрана в Стормвінді, показує, як міцнішає співпраця калдореїв Тельдрассилу з їхніми союзниками-людьми на сході.",["race:NightElf"]="Відгукнувшись на виклик, ви потрапляєте в серце Ценаріонського Анклаву Дарнасуса й ушановуєте тисячолітню традицію калдореїв під пильним оком кола Фандрала Стаґгелма."},sec={{t="Виклик з Анклаву",b="Друїди-новачки, що вдосконалюють своє ремесло на Тельдрассилі чи навчаються в далеких краях на кшталт Стормвінда, рано чи пізно отримують особистий виклик. Наставники — Кал у Доланаарі, Денатаріон у Дарнасусі чи Терідран за Великим Морем — передають, що Матренґіл Берволкер бажає сам наглядати за їхнім навчанням. Як безпосередній помічник Архідруїда Фандрала Стаґгелма, Матренґіл — один із найшанованіших і найобізнаніших наставників серед нічних ельфів, і його увага — певний знак, що учень готовий до справжніх випробувань."},{t="Шлях Ведмедя",b="Зустріч із Матренґілом на верхньому ярусі високої оселі Фандрала Стаґгелма в Ценаріонському Анклаві відчиняє двері до глибших таїнств. Щоб належно служити природі, друїд має навчитися втілювати її живих створінь, а не лише спостерігати за ними. Матренґіл вітає кандидатів звісткою, що їхньою першою великою справою буде прийняти силу, витривалість і дух ведмедя, — і ця подорож поведе їх далеко за межі Тельдрассилу, до священних земель предків."}},faq={{q="Хто посилає мене на це завдання?",a="Цей заклик ви можете отримати від кількох наставників друїдів, щойно наберетеся досить досвіду: від Кала в Доланаарі, Денатаріона в Дарнасусі чи Терідрана в кварталі Парк у Стормвінді.",al={"хто дає завдання","хто починає це","де взяти це завдання"}},{q="Хто такий Матренґіл Берволкер?",a="Матренґіл Берволкер — старший друїд нічних ельфів і безпосередній помічник Архідруїда Фандрала Стаґгелма. Він мешкає в Ценаріонському Анклаві в Дарнасусі й є провідним наставником новачків, що прагнуть опанувати звірині подоби.",al={"матренґіл","хто такий матренґіл","берволкер"}},{q="Де в Дарнасусі знайти Матренґіла Берволкера?",a="Він у Ценаріонському Анклаві в північно-західному кварталі Дарнасуса — чекає на другому поверсі великого живого дерева, що слугує святилищем Архідруїда Фандрала Стаґгелма.",al={"де матренґіл","де знайти матренґіла","де кенарійський анклав"}},{q="До якого навчання веде це завдання?",a="Доповідь Матренґілу починає священне випробування Ведмежої подоби. Він пошле вас через Калімдор до священного притулку Місячний Гай, щоб пізнати силу тіла й серця, потрібну для спілкування з Великим Духом Ведмедя.",al={"що далі","що я отримаю","наступне завдання"}},{q="Чому це завдання можна отримати в Стормвінді?",a="Посланці й друїди нічних ельфів, як-от Терідран, тримають святилище в Парку Стормвінда, щоб допомагати союзникам з Альянсу. Якщо молодий друїд мандрує за морем у Лісі Елвінн, Терідран може передати йому заклик повернутися додому, на Тельдрассил.",al={"завдання стормвінд","терідран","чи можна взяти в стормвінді"}},{q="Чому ведмежу подобу навчають першою?",a="Друїди вважають, що природі потрібні і захисники, і доглядачі. Ведмідь утілює первісну стійкість, фізичну силу й мужність заступати рівновагу від лиха — тож це основна подоба, щоб вижити у випробуваннях небезпечної глушини.",al={"чому ведмежа подоба","переказ про ведмежу подобу друїдів"}}},fp="16,278,26.560.0,20.479.0,27.197.0,29.235.0,52.204.0,38.222.0,38.246.0,52.241.0"}
P.entries["quest:5926"] = {n="Почути поклик",s="«Почути поклик» — завдання, що кличе друїда-новачка на Узвишшя Старійшин у Тандер Блафі для поглибленого особистого навчання. Звістку передають корчмарі й родичі в поселеннях Орди, і вона скеровує охочих до перевтілення до Турака Рунтотема. Ця зустріч відкриває священні випробування, потрібні, щоб опанувати форму й дух ведмедя.",h="«Почути поклик» — завдання, що кличе друїда-новачка на Узвишшя Старійшин у Тандер Блафі для поглибленого...",kw={"почути поклик","друїд","турак рунтотем","узвишшя старійшин","форма ведмедя","коло кенарія","великий дух ведмедя"},ang={["class:Druid"]="Це завдання — перший важливий крок на шляху до опанування звіриних форм, початок священної подорожі до духу й стійкості ведмедя.",["faction:Horde"]="Корчмарі на землях і орків, і тауренів дбають, щоб молоді друїди почули свій поклик, — так Орда зберігає життєво важливий зв'язок із дикою землею.",["race:Tauren"]="Для тауренів навчання в Турака на Узвишші Старійшин підтверджує їхнє глибоке, прадавнє возз'єднання з Колом Кенарія та дикими духами Калімдору."},sec={{t="Слово в корчмі",b="Звістки швидко розлітаються рівнинами Малгору й запиленими вулицями Оргріммара. Почуєте ви її від Корчмарки Гришки серед орків, від Корчмарки Пали в Тандер Блафі чи від Ґеннії Рунтотем у Селі Бладгуф — послання одне: Турак Рунтотем помітив ваші перші успіхи. Коло Кенарія не кличе послідовників легковажно, і це запрошення означає, що дні простого збирання трав і найпростіших чарів принесли вам право на глибше єднання з дикими духами природи."},{t="Коло на Узвишші Старійшин",b="Турак Рунтотем — помічник Верховного Друїда Гамуула Рунтотема: у великому наметі Кола Кенарія на Узвишші Старійшин він веде юних тауренів до обов'язку їхніх предків. Відкриваючи учням ширше розуміння спадщини Кенарія, Турак навчає, що звірі й рослини — і союзники, і доручені під їхню опіку створіння. Зустріч із ним — перший поріг обряду: крок за межі звичайного наставництва назустріч випробуванням тіла й серця, без яких не поєднатися безпосередньо з Великим Духом Ведмедя."}},faq={{q="Хто посилає мене до Турака Рунтотема?",a="Заклик можуть передати кілька різних зв'язкових: Ґеннія Рунтотем у Селі Бладгуф, Корчмарка Пала в Тандер Блафі чи Корчмарка Гришка в Оргріммарі. Кожна з них отримала звістку, що Турак хоче особисто вести ваше навчання.",al={"хто дає почути поклик","хто видає почути поклик","де почати почути поклик"}},{q="Де знайти Турака Рунтотема?",a="Турак мешкає на Узвишші Старійшин у Тандер Блафі. Він живе в помітному наметі Кола Кенарія, поруч з іншими наставниками-друїдами міста.",al={"де турак рунтотем","де турак","як знайти турака"}},{q="Чому цей заклик такий важливий для молодих друїдів?",a="Цей заклик починає ваші офіційні випробування з перевтілення. Турак Рунтотем скеровує вас на священну землю Місячного Гаю, щоб ви пізнали шлях ведмедя й здобули свою першу звірину подобу.",al={"навіщо мені турак","для чого це завдання","завдання друїда 10 рівня орда"}},{q="Хто такий Турак Рунтотем в ієрархії Кола Кенарія?",a="Турак — шанований друїд-таурен і довірений помічник Архідруїда Хамуула Рунтотема. Він славиться терпінням і мудрістю, коли навчає молодих новачків рівноваги природи.",al={"хто такий турак рунтотем","переказ про турака"}},{q="Чи можуть інші класи взяти це завдання?",a="Ні. Це завдання пропонують виключно друїдам, що досягли десятого сезону досвіду, — як обряд посвяти в перевтілення.",al={"чи почути поклик лише для друїдів","чи шаман може взяти це завдання"}},{q="Що буде після розмови з Тураком?",a="Турак вітає вас на службі Кенарію й посилає до священного друїдського притулку Місячний Гай — знайти Дендрита Старблейза й розпочати спілкування з Великим Духом Ведмедя.",al={"що після почути поклик","наступне завдання після турака"}}},fp="16,326,17.516.0,24.497.0,43.242.0,33.149.0,50.184.0,49.181.0,36.151.0,36.176.1"}
P.entries["quest:5931"] = {n="Назад до Дарнасуса",s="Це завдання знаменує повернення друїда-новачка з нічних ельфів зі священних галявин Місячного Гаю до Дарнасуса. Поєднавшись із Великим Духом Ведмедя, посвячуваний повертається до Матренґіла Берволкера в Ценаріонському Анклаві, щоб розпочати практичні випробування зміни подоби.",h="Це завдання знаменує повернення друїда-новачка з нічних ельфів зі священних галявин Місячного Гаю до...",kw={"назад до дарнасуса","великий дух ведмедя","матренґіл берволкер","дендрит старблейз","місячний гай","друїд","форма ведмедя"},ang={["class:Druid"]="Ця подорож — важливий обряд посвяти для молодих друїдів: перехід від теоретичного духовного єднання до справжньої зміни подоби.",["race:NightElf"]="Мандрівка між прадавнім святилищем Місячного Гаю й нещодавно посадженим Світовим Древом Тельдрассилом віддзеркалює рівновагу між тисячолітньою спадщиною калдореїв і їхніми нинішніми обов'язками."},sec={{t="Подорож між святилищами",b="Поєднавшись із Великим Духом Ведмедя в Місячному Гаю, молодий друїд має перекинути місток між позачасовими святилищами природи й неспокійним світом. Дендрит Старблейз відсилає посвячуваного з Нічного Притулку назад до Дарнасуса й довіряє наступний етап навчання місцевим наставникам, що бережуть Тельдрассил."},{t="Шлях Пазура",b="Матренґіл Берволкер чекає в Ценаріонському Анклаві — він береже природу навіть там, де хитається рівновага. Благословення Великого Духа Ведмедя — лише перший крок: Матренґіл готує посвячуваного закріпити цю люту прадавню мудрість у фізичній подобі, пройшовши суворі випробування тіла й серця."}},faq={{q="Навіщо мені повертатися до Дарнасуса?",a="Місячний Гай дарує спілкування з Великим Духом Ведмедя, але ваш безпосередній наставник, Матренґіл Берволкер, мешкає в Ценаріонському Анклаві в Дарнасусі. Він проводить практичні випробування, потрібні, щоб опанувати щойно здобуту силу.",al={"чому повертатися до дарнасуса","чому залишити місячний гай","куди дендрит мене посилає"}},{q="Хто такий Матренґіл Берволкер?",a="Матренґіл Берволкер — досвідчений наставник друїдів нічних ельфів у Ценаріонському Анклаві Дарнасуса. Він спеціалізується на тому, щоб вести молодих новачків Шляхом Пазура й навчати ведмежої подоби.",al={"хто такий матренґіл","переказ про матренґіла","берволкер"}},{q="Як повернутися з Місячного Гаю до Дарнасуса?",a="Майстриня гіпогрифів Сільва Філ'навет на південному заході Нічного Притулку переносить новачків прямим перельотом через море до Дарнасуса.",al={"як залишити нічний притулок","політ назад з місячного гаю","сільва філ'навет"}},{q="Що буде після розмови з Матренґілом?",a="Матренґіл дасть вам перше справжнє випробування мети: зійтися з Лунакло біля Каменя Місячника на схід від Обердайна на Темному Узбережжі, щоб довести, що ваші тіло й серце готові до ведмежої подоби.",al={"наступне завдання після назад до дарнасуса","що далі"}},{q="Що таке Шлях Пазура?",a="Шлях Пазура — друїдська традиція, зосереджена на тому, щоб спрямовувати лють, стійкість і силу ведмедя, втілені через спілкування з давніми первісними духами.",al={"шлях пазура","переказ про пазур друїда"}},{q="Чому Дендрит згадує, що рівновага біля Дарнасуса хитається?",a="Тельдрассил молодий і не має благословення Драконячих Аспектів, тож його гілля вразливе до дивної скверни, шаленства фурболгів і темряви, що насувається, — з усім цим активно борються друїди Ценаріонського Анклаву.",al={"рівновага дарнасуса хитається","тельдрассил осквернений"}}},fp="17,265,29.312.0,20.320.0,37.238.0,29.197.0,46.148.0,41.199.0,29.175.0,59.205.0"}
P.entries["quest:5932"] = {n="Назад до Тандер Блафа",s="«Назад до Тандер Блафа» — важливий обряд посвяти для юних друїдів-тауренів, що повертаються зі священних галявин Місячного Гаю. Поєднавшись із Великим Духом Ведмедя, учень за настановою Дендрита Старблейза вирушає назад на Узвишшя Старійшин, щоб продовжити навчання в Турака Рунтотема.",h="«Назад до Тандер Блафа» — важливий обряд посвяти для юних друїдів-тауренів, що повертаються зі священних...",kw={"назад до тандер блафа","друїд","великий дух ведмедя","дендрит старблейз","турак рунтотем","місячний гай","шлях пазура"},ang={["class:Druid"]="Цей відрізок вашої подорожі пов'язує прадавній відлюдний прихисток Місячного Гаю з продуваними вітрами висотами Тандер Блафа й позначає ваше зростання на Шляху Пазура.",["faction:Horde"]="Знання, принесені з Місячного Гаю, дають Орді могутніх захисників-перевертнів у її лавах на рівнинах Калімдору.",["race:Tauren"]="Повернувшись на Узвишшя Старійшин, ви приносите мудрість прадавніх духів додому, на користь і захист своїх племен у Малгорі."},sec={{t="Братство через кордони",b="Місячний Гай стоїть осторонь фракційних розколів смертного світу: це прихисток, де нічні ельфи й таурени, що практикують магію природи, збираються як Коло Кенарія. Після єднання з Великим Духом Ведмедя наставник із нічних ельфів Дендрит Старблейз відсилає юного таурена назад до свого народу. Хоч нічні ельфи часто вважають тауренів новачками в упорядкованому вченні Кенарія, Старблейз охоче визнає глибоку мудрість і рівновагу, які зберігає Турак Рунтотем."},{t="Повернення на кручі",b="Знову піднявшись на широкі висоти Узвишшя Старійшин у Тандер Блафі, новачок постає перед Тураком Рунтотемом зміненим. Єднання з прадавніми тотемними духами, як-от Великий Дух Ведмедя, глибоко вкорінене в культурі тауренів, проте ступити на Шлях Пазура — серйозне зобов'язання. Коли духовний зв'язок уже викувано, Турак готує друїда втілити здобуту силу й витривалість у дію."}},faq={{q="Чому нічний ельф навчав таурена в Місячному Гаю?",a="Коло Кенарія нейтральне й цілком віддане збереженню природи. У Місячному Гаю політичну ворожнечу між Ордою й Альянсом суворо відкладено, тож старійшини нічних ельфів на кшталт Дендрита Старблейза можуть наставляти молодих друїдів-тауренів.",al={"дендрит старблейз орда","чому нічний ельф-наставник","коло кенарія таурен"}},{q="Хто такий Турак Рунтотем?",a="Турак Рунтотем — шанований друїд-таурен, один із помічників Архідруїда, що служить на Узвишші Старійшин у Тандер Блафі. Він опікується навчанням молодих тауренів, які прагнуть іти шляхом природи й пазура, і є важливим зв'язковим із Колом Кенарія.",al={"роль турака рунтотема","друїдський ватажок на піднесенні старійшин"}},{q="Що молодий друїд зробив перед цим завданням?",a="Перш ніж повернутися до Малгору, новачок вирушив до Місячного Гаю, щоб знайти давній Великий Дух Ведмедя й поспілкуватися з ним, здобувши його благословення й пізнавши духовну суть ведмежої подоби.",al={"що було перед назад до тандер блафа","завдання духу великого ведмедя"}},{q="Як молоді друїди повертаються з Місячного Гаю до Тандер Блафу?",a="Бунтен Плейнсвінд на південному заході Нічного Притулку — майстер польотів, що безпечно переносить друїдів-тауренів назад до Тандер Блафу після їхніх обрядів.",al={"як повернутися з місячного гаю","політ назад з місячного гаю"}},{q="Що далі в навчанні друїда?",a="Після повернення Турак Рунтотем дає новачкові завдання «Тіло й серце» й посилає його на фізичне випробування до Каменя Місячника, там, де Пустки сходяться з Малгором, щоб довести, що він здатен утілити силу духа в справжню звірину подобу.",al={"наступне завдання друїда","після назад до тандер блафа"}},{q="Чому Дендрит Старблейз називає тауренів «молодими на шляхах Кенарія»?",a="Хоча тауренські перекази сягають давнього спілкування з Кенарієм на світанку світу, офіційне друїдство Кола Кенарія розвивали й зберігали нічні ельфи впродовж десяти тисяч років. Таурени лише нещодавно відновили впорядковане навчання під проводом Кола Кенарія.",al={"чи таурени нові друїди","історія тауренів-друїдів кенарій"}}},fp="21,276,20.491.0,20.427.0,51.262.0,23.261.0,52.198.0,64.183.0,40.244.0,72.261.0"}
P.entries["quest:6"] = {n="Винагорода за Ґарріка Педфута",s="«Винагорода за Ґарріка Педфута» — контракт Альянсу на винагороду, виданий Помічником Віллемом біля Абатства Нортшира. Він посилає молодих новобранців вистежити сумнозвісного місцевого злодія, який із відлюдної халупи біля виноградників тероризує фермерів і купців Елвінну.",h="«Винагорода за Ґарріка Педфута» — контракт Альянсу на винагороду, виданий Помічником Віллемом біля Абатства...",kw={"ґаррік педфут","винагорода","злодій","помічник віллем","нортшир","халупа"},ang={["class:Rogue"]="Ґаррік Педфут дає розбійникам перше уявлення про те, як злочинці діють у тіні Елвінну, і показує, що погано прихована схованка притягує швидкі клинки.",["faction:Alliance"]="Розправа з Ґарріком Педфутом — одна з перших прямих послуг, які майбутній шукач пригод Альянсу робить, щоб повернути стабільність Королівству Стормвінд.",["race:Human"]="Для людей, що виросли в королівстві, очистити Нортшир від головорізів на кшталт Педфута — особиста справа захисту священної землі батьківщини та її фермерів."},sec={{t="Пошесть у долині",b="Долину Нортширу колись вважали безпечним прихистком для вишколу новобранців і догляду за священними виноградниками, та нещодавній занепад закону й порядку по всьому Елвінну лишив її беззахисною. У долину прокралися зграї злодіїв, і головоріз на ім'я Ґаррік Педфут швидко став їхнім ватажком. Уже кілька тижнів Ґаррік зі своєю бандою грабує обози, обирає купців на дорогах і залякує місцевих фермерів."},{t="Правосуддя Помічника Віллема",b="Варта Стормвінда розтягнута між захистом столиці й зовнішніх кордонів, тож місцевим маршалам і помічникам лишається покладатися на завзятих добровольців, щоб тримати мир у Нортширі. Помічник Віллем призначає публічну винагороду за голову Ґарріка, аби раз і назавжди позбавити долину його банди. Розправа з Педфутом у його занедбаній халупі на схід від річки — перший удар по ширшому беззаконню, що просочується в серце людських земель."}},faq={{q="Хто такий Ґаррик Педфут?",a="Ґаррик Педфут — бандит і головоріз, що діє в Долині Нортширу. Тижнями він непокоїть місцевих фермерів і влаштовує засідки на купців, зібравши довкола себе невелику ватагу головорізів, щоб застовпити територію біля виноградників.",al={"ґаррик педфут","хто такий ґаррик","педфут"}},{q="Де знайти Ґаррика Педфута?",a="Він засів у невеликій дерев'яній хижці на схід від Абатства Нортшира, за мостом через річку, біля виноградників. Його стережуть спільники-головорізи.",al={"де ґаррик педфут","місце ґаррика","халупа ґаррика"}},{q="Хто оголосив винагороду за Ґаррика?",a="Винагороду оголошує Помічник Віллем, що стоїть біля Абатства Нортшира. Через брак міської варти, щоб пильнувати долину, Віллем наймає мандрівних новобранців, щоб ті віддали розбійника в руки правосуддя.",al={"хто оголосив винагороду за ґаррика педфута","винагорода віллема"}},{q="Чому Стормвінд не посилає регулярних вояків розібратися з ним?",a="Військо Стормвінда перевантажене. Король Варіан Рінн зник, напруга росте по всьому Лісу Елвінн і далі, тож столиця не може виділяти досвідчені гарнізони на кожного дрібного головоріза, і місцевим помічникам доводиться наймати новобранців.",al={"чому вартові не вб'ють ґаррика","де вартові стормвінда"}},{q="Чи діє Ґаррик Педфут сам?",a="Ні. Ґаррик оточив себе невеликою бандою розбійників і грабіжників, що отаборилися довкола його хижки біля виноградників Нортшира, щоб його захищати.",al={"чи ґаррик сам","банда педфута"}},{q="Який доказ вимагає Помічник Віллем?",a="Помічник Віллем вимагає речового доказу, перш ніж виплатити гроші, — а саме принести до Абатства Нортшира відрубану голову Ґаррика Педфута.",al={"доказ смерті ґаррика","голова ґаррика"}}},fp="25,260,22.420.0,23.419.0,23.227.0,35.152.0,33.181.0,63.236.0,33.147.0,38.157.0"}
P.entries["quest:60"] = {n="Кобольдські свічки",s="«Кобольдські свічки» — одне з перших доручень Вільяма Пестла з Корчми «Лев'яча Гордість» у Ґолдширі. Алхімік, що навідався сюди зі своєї крамниці в Стормвінді, шукає густий віск великих свічок, які носять кобольди, що заполонили місцеві копальні Лісу Елвінн. Для шукачів пригод це раннє знайомство з підземними шкідниками, які зазіхають на цінні золоті жили королівства.",h="«Кобольдські свічки» — одне з перших доручень Вільяма Пестла з Корчми «Лев'яча Гордість» у Ґолдширі.",kw={"кобольдські свічки","кобольди","вільям пестл","віск","фарґодіп","яшмова копальня","ґолдшир"},ang={["faction:Alliance"]="Поки королівська армія виснажена внутрішніми політичними чварами, а сили корони відсутні, захист місцевого господарства лягає на добровольців і мандрівних шукачів пригод.",["profession:Mining"]="Зачищаючи кобольдів заради свічок, рудокопи-початківці потрапляють просто на найбагатші мідні й золоті жили Елвінну, покинуті людьми-рудокопами.",["race:Human"]="Повернути захоплені копальні Елвінну й постачати товар стормвіндським ремісникам — ранні обов'язки молодих підданих королівства."},sec={{t="Доручення аптекаря",b="Вільям Пестл разом із братом тримає «Аптеку Пестла» в Торговому Кварталі Стормвінда. Коли вариш ліки, мазі й настої, такої сировини, як віск, завжди бракує. Замість купувати гарні свічки в міських торговців, Пестл помітив, що шкідники, які плюндрують Елвінн, носять на лобі напрочуд важкі грудки лою й воску — бери задарма, якщо знайдеться шукач пригод, готовий їх віддерти."},{t="Копальні Елвінну",b="Кобольди цілком заполонили і Копальню Фарґодіп на південь від Ґолдшира, і Яшмову копальню на північному сході. Ці сопучі підземні створіння цінують свої свічки понад усе: мерехтливе світло веде їх темними штольнями, поки вони риють у пошуках золота й блискучих дрібничок. Відбирати ці свічки означає не лише поповнити алхімічні запаси Пестла, а й потроху вибивати шкідників, що душать дорогоцінні рудні ділянки королівства."}},faq={{q="Навіщо Вільямові Пестлу кобольдські свічки?",a="Вільям Пестл і його брат тримають аптекарську крамницю в Торговому Кварталі Стормвінда. Перетоплений лій і віск із великих свічок вони використовують для запечатування, мазей і різних алхімічних препаратів.",al={"навіщо пестлу свічки","для чого свічки","для чого воскові свічки"}},{q="Де шукати великі свічки?",a="Свічки носять кобольди-робітники, гризуни й копачі, що живуть у копальнях Лісу Елвінн — передусім у тунелях Копальні Фарґодіп на південь від Ґолдширу та Яшмової копальні на сході.",al={"де кобольдські свічки","місця свічок","як отримати великі свічки"}},{q="Чому кобольди такі одержимі свічками?",a="Кобольди живуть у непроглядно темних підземних тунелях і бачать, копаючи, лише завдяки вогникам, прив'язаним до голів. Вони мають забобонний, майже шалений страх перед темрявою й люто захищають свої свічки від кожного, хто намагається їх відібрати.",al={"чому кобольди мають свічки","що означає не бери свічку","переказ про кобольдські свічки"}},{q="Хто такий Вільям Пестл?",a="Вільям Пестл — купець і алхімік-людина зі Стормвінда. Коли він не працює у своїй крамниці в Торговому Кварталі міста, то їздить до Ґолдширу, щоб дешево купувати матеріали в мандрівних шукачів пригод.",al={"хто такий вільям пестл","переказ про вільяма пестла","пестл ґолдшир"}},{q="Чи пов'язане це завдання з іншими негараздами в Елвінні?",a="Так. Навала кобольдів на Копальню Фарґодіп і Яшмову копальню — серйозна економічна загроза для Ґолдширу й Стормвінда. Гірників-людей вигнано, і звільнення тунелів — одне з головних завдань Маршала Дуґана.",al={"проблеми копалень елвінна","чому кобольди в копальнях","загроза кобольдів ґолдшира"}},{q="Чи є в Елвінні інші копальні, захоплені кобольдами?",a="Копальня Фарґодіп і Яшмова копальня — дві головні біля Ґолдширу, але кобольди трапляються й на берегах річок у лісі та далі на схід, до меж Редріджу.",al={"інші копальні кобольдів","список копалень елвінна"}}},fp="14,393,20.450.0,19.454.0,44.223.0,36.205.0,41.253.0,22.204.0,52.216.0,56.187.0"}
P.entries["quest:6001"] = {n="Тіло й серце",s="«Тіло й серце» — завершальне випробування в посвяті молодого друїда нічних ельфів на шлях пазура. За настановою Матренґіла Берволкера в Дарнасусі посвячуваний має вирушити в дикі хащі Темного Узбережжя, викликати охоронця місячників Лунакло й довести, що має і внутрішню стійкість, і бойову силу, — лише тоді він зможе прийняти форму ведмедя.",h="«Тіло й серце» — завершальне випробування в посвяті молодого друїда нічних ельфів на шлях пазура.",kw={"тіло й серце","лунакло","камінь місячника","кенарійський місячний пил","форма ведмедя","обердайн","друїд"},ang={["class:Druid"]="Цей обряд — визначальний поріг раннього друїдського навчання: він перетворює новачка-чарівника на захисника, що змінює подобу й може прийняти могутню форму ведмедя.",["race:NightElf"]="Для нічних ельфів єднання з прадавніми духами звірів і шанування священних каменів на Темному Узбережжі відновлює зв'язок із кенарійськими звичаями, що склалися тисячоліття тому."},sec={{t="Випробування Лунакло",b="Матренґіл Берволкер у Дарнасусі скеровує посвячуваних друїдів нічних ельфів на схід від прибережного поселення Обердайн. Там, у природній печері, де живуть дикі місячники, стоїть прадавній Камінь Місячника. Помазавши цей священний моноліт Кенарійським Місячним Пилом, посвячуваний будить Лунакло — давнього захисника каменя, що кидає виклик кожному, хто прагне успадкувати священну силу пазура."},{t="Сила тіла й серця",b="Прийняти мантію ведмедя — це куди більше, ніж груба сила. Великий Дух Ведмедя дає основи вчення про лютість природи, а випробування з Лунакло перевіряє, чи вистачить посвячуваному стійкості серця, щоб приборкати цю первісну силу й скерувати її. Здолавши охоронця в бою й дослухавшись до мудрості духу, що лишається по ньому, друїд доводить, що готовий приймати форму ведмедя, не втрачаючи себе у звіриних інстинктах."}},faq={{q="Хто такий Лунакло?",a="Лунакло — лютий дух-охоронець із місячників, що живе в печері просто на схід від Обердайна на Темному Узбережжі. Він захищає священний Камінь Місячника й відгукується на заклик новачків, які посипають реліквію Кенарійським Місячним Пилом.",al={"що таке лунакло","переказ про лунакло","бос місячників оберіжина"}},{q="Яка мета цього випробування?",a="Цей обряд посвяти — останнє випробування для новачка з нічних ельфів, що прагне вступити до лав Друїдів Пазура. Здолавши Лунакло, новачок доводить, що має і фізичну стійкість, і душевну врівноваженість, потрібні, щоб перейняти дух і подобу ведмедя.",al={"чому тіло й серце","що робить це завдання","переказ про ведмежу подобу"}},{q="Хто дає це завдання?",a="Матренґіл Берволкер, старійшина-наставник друїдів у Ценаріонському Анклаві в Дарнасусі, дає новачкам це випробування, коли вони поспілкуються з Великим Духом Ведмедя.",al={"хто дає тіло й серце","хто дає завдання ведмежої подоби"}},{q="Що таке Кенарійський Місячний Пил?",a="Кенарійський Місячний Пил — освячений обрядовий порошок, який старійшини дають новачкам. Коли його сиплють на Камінь Місячника, його магічні властивості пробуджують Лунакло й починають обрядовий бій.",al={"що таке місячний пил","переказ про кенарійський місячний пил"}},{q="Де відбувається це випробування?",a="Випробування відбувається в печері на схід від Обердайна на Темному Узбережжі, де довкола давнього різьбленого Каменя Місячника гніздяться дикі місячники.",al={"де камінь місячника","печера місячників оберіжина"}},{q="Що буде, коли Лунакло переможено?",a="Коли істоту здолано, над її тілом з'являється Дух Лунакло, щоб дарувати своє благословення й визнати подвійну силу серця й тіла друїда, перш ніж той повернеться до Дарнасуса.",al={"що буде після вбивства лунакло","дух лунакло"}}},fp="14,353,21.435.0,26.461.1,16.223.0,34.287.0,21.178.0,26.189.0,33.129.0,40.202.1"}
P.entries["quest:6002"] = {n="Тіло й серце",s="«Тіло й серце» — завершальне випробування для юних друїдів-тауренів, які прагнуть опанувати форму ведмедя. За дорученням Турака Рунтотема з Тандер Блафа учень вирушає на межу Малгору й Пусток, щоб прикликати й здолати Лунакло біля Каменя Місячника.",h="«Тіло й серце» — завершальне випробування для юних друїдів-тауренів, які прагнуть опанувати форму ведмедя.",kw={"тіло й серце","форма ведмедя","лунакло","камінь місячника","кенарійський місячний пил","турак рунтотем","друїд пазура"},ang={["class:Druid"]="Цей обряд посвяти долає прірву між ученням Кенарія від нічних ельфів і спадщиною тауренів, дозволяючи вам нарешті проявити люту стійкість форми ведмедя.",["faction:Horde"]="Друїди-таурени приносять на передову Орди життєво важливу стійкість, укорінюючи магічну силу фракції в глибокій опіці над дикою природою.",["race:Tauren"]="Для шу'гало пробудити в собі ведмедя — це і святе єднання з духами природи, і практичний спосіб захистити рівнини Малгору від загроз, що наступають."},sec={{t="Шлях Пазура",b="Щоб справді піти шляхом Друїда Пазура, учні-таурени мусять поєднати духовну переконаність із фізичною стійкістю. Після єднання з Великим Духом Ведмедя в Місячному Гаю навчання друїда перевіряють ділом. Турак Рунтотем, старший наставник друїдів на Узвишші Старійшин у Тандер Блафі, вручає гідним учням Кенарійський Місячний Пил і доручає розшукати священний камінь неподалік посушливого рубежу, де Малгор сходиться з Пустками."},{t="Випробування Лунакло",b="Камінь Місячника, що стоїть на захід від Табору Тауражо, — рідкісне святилище Кенарія на півдні Калімдору. Місячники не водяться на випалених сонцем рівнинах центрального Калімдору, тож присутність звіра-охоронця Лунакло має глибоке значення. Розсипавши місячний пил на прадавньому пам'ятнику, друїд викликає Лунакло на бій. Перемога над звіром доводить, що учень володіє і силою тіла, і ясністю серця, — так він здобуває благословення звіра й відкриває в собі внутрішню сутність ведмедя."}},faq={{q="Яка мета цього випробування?",a="Це завдання — останній крок до Ведмежої подоби для друїдів Орди. Виконавши випробування, ви доводите, що готові стати Друїдом Пазура під проводом Турака Рунтотема.",al={"чому тіло й серце","що робить тіло й серце","що я отримаю від тіла й серця"}},{q="Де розташований Камінь Місячника?",a="Камінь Місячника — у Пустках, на захід від Табору Тауражо, при дорозі, що веде до брами Малгору. Трохи на південь від дороги, за деревом біля самотнього намету, лежить священний камінь.",al={"де камінь місячника","де знайти камінь місячника","місце каменю місячника"}},{q="Хто такий Лунакло?",a="Лунакло — лютий охоронець-місячник, прив'язаний до Каменя Місячника. Прикликаний Кенарійським Місячним Пилом, він перевіряє, чи має друїд первісну завзятість і душевну стриманість, потрібні, щоб орудувати силою ведмедя.",al={"хто такий лунакло","що таке лунакло"}},{q="Що буде, якщо я програю бій із Лунакло?",a="Якщо вас переможуть, Кенарійський Місячний Пил буде витрачено. Треба повернутися до Турака Рунтотема на Узвишші Старійшин у Тандер Блафі по новий мішечок пилу, перш ніж знову пробувати прикликання.",al={"програв лунакло","втратив місячний пил","помер від лунакло"}},{q="Чи місячники — корінні мешканці Пусток?",a="Ні. Як зауважує Турак Рунтотем, місячники не водяться ні в Пустках, ні в Малгорі. Ця істота — неприродне видовище на савані, пов'язане саме з обрядами Кола Кенарія й давніми місцями небесної сили.",al={"місячники в пустках","чому тут місячники","місячники пусток"}},{q="Хто дає завдання «Тіло й серце»?",a="Завдання дає Турак Рунтотем, старший наставник друїдів на Узвишші Старійшин у Тандер Блафі, коли новачок повертається з Місячного Гаю.",al={"хто починає тіло й серце","хто дає тіло й серце"}}},fp="14,256,19.461.0,21.507.0,34.205.0,35.199.0,16.218.0,51.201.0,34.205.0,35.155.0"}
P.entries["quest:6061"] = {n="Приборкання звіра",s="«Приборкання звіра» — основоположний обряд посвяти для молодих мисливців-тауренів у Селі Бладгуф. Під проводом наставника Ява Шарпмейна мисливець вирушає в Малгор, щоб приборкати дорослого довгоступа, і робить перший крок до духовного зв'язку зі створіннями Земної Матері.",h="«Приборкання звіра» — основоположний обряд посвяти для молодих мисливців-тауренів у Селі Бладгуф.",kw={"приборкання","довгоступ","мисливець","яв шарпмейн","село бладгуф","малгор","звір-супутник"},ang={["class:Hunter"]="Цей обряд знаменує перехід від недосвідченого слідопита до справжнього повелителя звірів і вчить вас спілкуватися з тваринами під проводом Земної Матері.",["race:Tauren"]="Приборкання звіра — прадавній звичай, осердя кочового мисливського спадку Малгору, що зміцнює зв'язок між мисливцем і природою."},sec={{t="Священний зв'язок із дикою природою",b="Для тауренів полювання ніколи не зводилося до вбивства звірів заради м'яса й шкур. Прадавні перекази кажуть: здолавши дику звірину Малгору й поєднавшись із нею, мисливець вбирає її дух і наближається до Земної Матері. Приборкання звіра-супутника підносить цей зв'язок ще вище: той, хто міг стати супротивником, обертається на довічного партнера, суголосного з природною рівновагою рівнин."},{t="Перше випробування",b="Яв Шарпмейн починає навчання посвяченого не з лютих верховних хижаків, а зі швидких і сторожких довгоступів, що блукають травами Малгору. Озброєний зачарованим жезлом приборкання, мисливець має стати віч-на-віч із дорослим довгоступом, угамувати його дикі інстинкти й заслужити довіру. Це перше випробування доводить рішучість мисливця й готує його до вибагливіших звірів, які чекають попереду."}},faq={{q="Яка мета цього випробування?",a="Це завдання — перше практичне випробування для мисливців-тауренів, що вчаться мистецтва дружби зі звірами. Приборкавши за допомогою жезла приборкання дорослого рівнинного довгоступа, мисливець пізнає основи духовного й робочого зв'язку зі звірами.",al={"чому приборкувати довгоступа","мета завдання","завдання вихованця таурена"}},{q="Хто дає це завдання і де його знайти?",a="Завдання дає Яв Шарпмейн — наставник мисливців у Селі Бладгуф серед центральних рівнин Малгору.",al={"хто дає завдання","де видавець завдання","де яв шарпмейн"}},{q="Чи лишається дорослий рівнинний довгоступ у мене назавжди?",a="Ні. Звірі, приборкані під час трьох перших випробувань Ява Шарпмейна, — тимчасові напарники для вправ. Коли ви пройдете весь ланцюжок навчання й опануєте приборкання, то зможете вирушити в світ і назавжди приборкати будь-якого придатного супутника.",al={"чи вихованець постійний","чи я лишу довгоступа","лишити звіра після завдання"}},{q="Чому таурени вважають приборкання звірів духовним дійством?",a="Тауренська традиція навчає, що, спілкуючись із дикими істотами й перемагаючи їх, мисливці переймають їхній дух і зливаються з природним світом. Приборкання звіра — це взаємна пошана й єдність із творіннями Земної Матері.",al={"переказ про вихованців таурена","приборкання за землею-матір'ю","чому таурени приборкують звірів"}},{q="Де водяться дорослі рівнинні довгоступи?",a="Дорослі рівнинні довгоступи блукають по всіх хвилястих саванах і долинах довкола Села Бладгуф у Малгорі.",al={"де довгоступи","де рівнинний довгоступ","знайти дорослого довгоступа"}},{q="Що далі після цього завдання?",a="Повернення жезла приборкання Явові Шарпмейну веде до наступного випробування: треба приборкати степового нишпорку, а тоді — агресивного пікірника, і лише потім навчитися постійного приборкання звірів.",al={"що далі","ланцюжок після цього","наступний крок приборкання"}}},fp="16,289,27.405.0,14.390.0,34.268.0,48.125.0,45.233.0,52.239.0,39.118.0,28.198.0"}
P.entries["quest:6062"] = {n="Приборкання звіра",s="Це випробування — перший крок молодого мисливця Орди в мистецтві приборкання звірів. Під проводом ветерана Тотара в Гострому Пагорбі майбутні мисливці за допомогою зачарованого жезла приборкання впокорюють лютого плямистого вепра й пов'язують його з собою.",h="Це випробування — перший крок молодого мисливця Орди в мистецтві приборкання звірів.",kw={"мисливець","тотар","приборкання","вепр","гострий пагорб","улюбленець"},ang={["class:Hunter"]="Цей обряд посвяти — міст між простим стрільцем і справжнім володарем звірів: він відкриває визначальний для мисливця зв'язок зі звіриними супутниками.",["race:Orc"]="Для орків влада над звіром — відображення сили волі й панування над суворою дикою землею їхнього нового дому в Дуротарі.",["race:Troll"]="Мисливці Темного Списа через це навчання налаштовують свій дух на сувору дику природу Калімдору, продовжуючи свої давні традиції вистежування."},sec={{t="Обряд посвяти мисливця",b="Для мисливців-орків і тролів Темного Списа, що зростають у Дуротарі, вижити самотою в дикій природі — лише половина справи. Справжній мисливець, володар дикої землі, має навчитися підкоряти своїй волі саму природу, перетворюючи ворожих звірів на вірних союзників. Наставник мисливців Тотар довіряє новачкам зачарований жезл приборкання й кидає їм виклик: стати віч-на-віч із лютим диким вепром, не вдаючись до смертоносної стріли."},{t="Вепри Дуротару",b="Люті плямисті вепри блукають посушливими чагарями довкола Гострого Пагорба. Хоч вони грубі й злі, їхня витривалість і лють роблять їх ідеальними для першого приборкання. Витримати їхні наскоки й стерпіти їхню агресію, водночас спрямовуючи силу жезла, — для цього потрібні терпіння й залізна рішучість, чесноти, без яких не обійтися жодному слідопитові Орди."}},faq={{q="Яка мета цього випробування?",a="Це перше практичне випробування для молодих мисливців у Дуротарі: воно вчить спрямовувати волю крізь жезл приборкання, щоб скорити дику істоту, а не просто вбити її.",al={"навіщо це завдання","причина приборкання кабана","сенс приборкання звіра"}},{q="Хто дає це завдання?",a="Тотар, наставник мисливців на Гострому Пагорбі, дає це доручення, коли ви доведете свої основні навички виживання в Дуротарі.",al={"хто дає завдання","хто дає приборкання звіра","де взяти завдання кабана"}},{q="Де водяться люті плямисті кабани?",a="Люті плямисті кабани блукають сухими чагарниками одразу за частоколом Гострого Пагорба в центрі Дуротару.",al={"де люті плямисті кабани","місце кабанів","де знайти кабана"}},{q="Чи лишається кабан у мене назавжди після цього завдання?",a="Ні. Кабан, приборканий у цій першій вправі, — лише для тренування. Він іде геть, коли ви повертаєтеся до Тотара, адже, перш ніж утворити тривалий зв'язок, треба продовжити навчання з іншими істотами.",al={"чи лишу кабана","чи кабан постійний вихованець","лишити лютого кабана"}},{q="Що далі після цього доручення?",a="Коли ви повернетеся до Тотара, він перевірить, як ви даєте раду іншим небезпечним хижакам Дуротару — зокрема прибійним повзунам і броньованим скорпідам.",al={"наступне завдання","що після приборкання кабана","наступний крок ланцюжка приборкання"}},{q="Навіщо жезл приборкання, а не чистий інстинкт?",a="Мисливцям-новачкам бракує витонченої духовної й фізичної дисципліни, щоб безпосередньо порозумітися зі звірами. Зачарований жезл приборкання слугує осередком, що допомагає новачкам утверджувати владу над духом дикого звіра, доки вони назавжди не опанують це мистецтво.",al={"навіщо жезл приборкання","що робить жезл","переказ про жезл приборкання"}}},fp="16,222,26.396.0,20.350.0,34.185.0,21.138.0,39.121.0,50.195.0,27.150.0,46.246.0"}
P.entries["quest:6063"] = {n="Приборкання звіра",s="Це завдання — перше випробування на шляху мисливця нічних ельфів до мистецтва звіриного товариства. За настановою Дазалара з Доланаара мисливець-початківець має зачарованим жезлом приборкання встановити зв'язок із диким павуком, що зветься Причаєнець Плетива Лісу. Воно перевіряє, чи здатен мисливець поважати природу й єднатися з нею, а не підкоряти її силою.",h="Це завдання — перше випробування на шляху мисливця нічних ельфів до мистецтва звіриного товариства.",kw={"приборкання звіра","мисливець","дазалар","причаєнець плетива лісу","жезл приборкання","доланаар"},ang={["class:Hunter"]="Цей обряд переходу знаменує перетворення мисливця з самотнього лучника на справжнього партнера дикої природи, пов'язаного з лісовими звірами.",["race:NightElf"]="Відображаючи філософію калдорей, приборкання звірів робить наголос на єднанні й шанобі до природи, а не на підкоренні й пануванні."},sec={{t="Священний зв'язок",b="Для калдорей полювання — не просто вистежування здобичі чи виживання в хащах; це священні стосунки з природою. Наставники мисливців, такі як Дазалар, навчають, що природа незмірно більша за будь-кого зі смертних. Тварини — не в'ючна худоба й не знаряддя, які можна силоміць зігнути під свою волю, а самостійні створіння, що потребують взаємної поваги. Щоб довести готовність до звіра-супутника на все життя, мисливці-новачки мають приборкати первісні інстинкти місцевої живності давніми прийомами, а не грубою силою."},{t="Перше випробування",b="Випробування починаються з велетенських павуків, що заполонили гілля Тельдрассила. Дазалар довіряє мисливцеві особливий жезл приборкання й велить розшукати Причаєнця Плетива Лісу. Заглибившись у тінисті хащі, мисливець має зустрітися з отруйним павуком і встановити з ним чуттєвий зв'язок, витримуючи його напади. Успішно наведений тимчасовий міст між розумами доводить, що мисливець здатен єднатися навіть із моторошними хижаками Світового Дерева, які шурхотять у темряві."}},faq={{q="Навіщо це завдання?",a="Це завдання відкриває низку випробувань, які мають пройти мисливці нічних ельфів, щоб навчитися назавжди приборкувати звірів-супутників. Застосовуючи жезл приборкання до визначених місцевих звірів, мисливці доводять, що мають досить витримки й уміння, аби єднатися з дикими хижаками.",al={"навіщо це завдання","вихованець завдання","що дає приборкання звіра"}},{q="Хто дає це завдання?",a="Дазалар, наставник мисливців, що живе в поселенні Доланаар на Тельдрассилі, пропонує це завдання молодим мисливцям нічних ельфів, які набули достатньо досвіду у своїй справі.",al={"хто дає завдання","де взяти завдання приборкання","хто починає приборкання звіра"}},{q="Яку істоту треба приборкати в цьому випробуванні?",a="Вам належить приборкати Причаєнця Плетива Лісу — одного з отруйних велетенських павуків, що водяться в диких хащах і лісах довкола Доланаару.",al={"якого вихованця приборкати","ціль причаєнець плетива лісу","якого звіра приборкати"}},{q="Чи лишиться Причаєнець Плетива Лісу зі мною назавжди?",a="Ні. Причаєнець Плетива Лісу, якого ви приборкаєте під час цього завдання, — тимчасовий супутник, лише для того, щоб опанувати основи поводження з вихованцем. Щойно ви повернетеся до Дазалара, зв'язок розривається, і ви готуєтеся до наступного випробування.",al={"чи лишу павука","чи причаєнець постійний","лишити вихованця"}},{q="Чому нічні ельфи спершу випробовують мисливців павуками?",a="Причаєнці Плетива Лісу хижі й агресивні, тож суворо перевіряють витримку новачка. Підкоривши павука, що здається чимось неприродним, мисливець доводить, що здатен поєднати свою свідомість із найрізноманітнішими й найворожішими проявами природи.",al={"чому причаєнець плетива лісу","навіщо приборкувати павука","переказ про приборкання павуків"}},{q="Що буде після повернення до Дазалара?",a="Дазалар посилає мисливця перевірити свій зв'язок з іншими тваринами Тельдрассилу — а саме зі Скрадливим Нічним Шаблезубом і Верескуном-стригідом, — і лише тоді дарує вміння приборкувати звірів назавжди.",al={"що далі","після приборкання звіра","наступне випробування"}}},fp="16,332,13.537.0,15.474.0,34.242.0,21.181.0,42.138.0,41.209.0,51.235.0,38.190.1"}
P.entries["quest:6064"] = {n="Приборкання звіра",s="«Приборкання звіра» — перше випробування на шляху дворфійського мисливця до володіння звірами-супутниками в Дун Мороґу. Під проводом Ґріфа Вайлдгарта з Хараноса юні слідопити вчаться втихомирити лютого Великого Скелястого Вепра й зріднитися з ним за допомогою зачарованого жезла приборкання.",h="«Приборкання звіра» — перше випробування на шляху дворфійського мисливця до володіння звірами-супутниками в...",kw={"приборкання","мисливець","вепр","вайлдгарт","жезл","харанос","звір"},ang={["class:Hunter"]="Це завдання — вирішальний поріг, за яким новачок-стрілець стає справжнім володарем звірів, і початок низки випробувань, що відкривають постійних тваринних супутників.",["race:Dwarf"]="Горяни Айронфорджа шанують звірів, здатних витримати пронизливий холод Дун Мороґу; починати з витривалого скелястого вепра — у дусі дворфійської поваги до впертості й стійкості."},sec={{t="Супутник мисливця",b="Доти дворфійські горяни й слідопити покладалися лише на стрілецьку майстерність, пастки та чуття дикої природи. Та справжня душа мисливця — у довічному партнерстві з диким звіром. Ґріф Вайлдгарт, що стоїть біля Ґуральні Тандербрю в Хараносі, наглядає за цим обрядом переходу. Замість вимагати, щоб новачок назавжди прив'язав до себе першого-ліпшого звіра, Ґріф велить йому випробувати терпіння й рішучість на кількох тутешніх видах Дун Мороґу."},{t="Скелястий Вепр",b="Перше випробування зводить слідопита з Великим Скелястим Вепром — одним із витривалих товстошкурих кабанів, що блукають засніженими передгір'ями Дун Мороґу. Укриті щетинистим хутром і жорсткою плоттю, ці звірі вперті й агресивні, тож ідеально підходять для першого випробування волі. Жезлом Приборкання, який дає Ґріф, мисливець має витримати натиск вепра і вгамувати його лють, доки той не скориться."}},faq={{q="Хто проводить це випробування?",a="Випробування дає Ґріф Вайлдгарт, досвідчений наставник мисливців-дворфів, що стоїть біля Ґуральні Тандербрю в Хараносі.",al={"хто дає завдання","хто починає приборкання звіра","де ґріф вайлдгарт"}},{q="Чому спершу треба приборкати Великого Скелястого Вепра?",a="Великі Скелясті Вепри міцні й уперті, але їх повно на засніжених хребтах Дун Мороґа. Підкорити таку витривалу товстошкіру істоту — базова вправа, яка вчить спокійно, але владно поводитися з агресивним звіром.",al={"чому скелястий вепр","якого звіра приборкати","приборкання вепра"}},{q="Чи залишиться цей вепр зі мною назавжди?",a="Ні. Це випробування — лише практика. Зв'язок, викуваний Жезлом Приборкання, тимчасовий: він дає змогу відчути, як це — керувати звіром, перш ніж ви повернете жезл і спробуєте інші види.",al={"чи вепр постійний","лишити скелястого вепра","чи можна лишити вихованця"}},{q="Де знайти Великих Скелястих Вепрів?",a="Великі Скелясті Вепри блукають відкритими сніговими полями й сосновими гаями довкола Хараноса та замерзлими схилами Дун Мороґа.",al={"місця вепрів","де великі скелясті вепри","поява великого скелястого вепра"}},{q="Що далі, після приборкання скелястого вепра?",a="Повернувшись до Ґріфа Вайлдгарта, ви завершуєте цей перший урок і одразу переходите до другого випробування — приборкати Снігового Леопарда.",al={"наступне випробування","що після цього завдання","наступний крок ланцюжка мисливця"}},{q="Як діє Жезл Приборкання?",a="Жезл Приборкання — зачарований інструмент, який наставники мисливців дають новачкам, щоб ті могли спрямувати свою волю й угамувати дикі інстинкти звіра без особливої магічної підготовки чи багаторічного досвіду заклинання звірів.",al={"переказ про жезл приборкання","що таке жезл","як приборкувати"}}},fp="16,251,20.493.0,13.427.0,22.127.0,38.231.0,35.190.0,34.124.0,38.144.0,29.209.0"}
P.entries["quest:6065"] = {n="Шлях мисливця",s="«Шлях мисливця» — важлива віха для молодих мисливців-тауренів у Малгорі, що спрямовує їх до поглибленого навчання дружби зі звірами. Щойно новачки доведуть основи влучності й вистежування, місцеві наставники відсилають їх до Села Бладгуф по пораду до наставника мисливців Ява Шарпмейна. Ця подорож відкриває духовні та практичні випробування, потрібні, щоб приборкати дикого звіра й зріднитися з ним.",h="«Шлях мисливця» — важлива віха для молодих мисливців-тауренів у Малгорі, що спрямовує їх до поглибленого...",kw={"шлях мисливця","яв шарпмейн","село бладгуф","малгор","таурени","приборкання звірів","озеро кам'яного бика"},ang={["class:Hunter"]="Це завдання позначає мить, коли лучник чи стрілець стає справжнім повелителем звірів і робить перший крок до вірного бойового супутника.",["faction:Horde"]="Мисливці Орди значною мірою покладаються на лютих звірів прикордоння як на передових захисників і слідопитів у суворих нетрях Калімдору.",["race:Tauren"]="Для шу'хало вміння приборкувати диких звірів — духовне продовження їхньої шани до природи й творіння Земної Матері."},sec={{t="Обряд посвяти",b="Для кочових шу'хало полювання — священнодійство, а не розвага. Мисливець має розуміти рівновагу природи, шанувати духів рівнин і виявляти повагу до тварин, які годують племена. Коли молодий мисливець доводить, що вміє вижити в дикому краю й володіє луком чи рушницею, старійшини визнають: він готовий піти далі самотнього вистежування. Наказ розшукати досвідчених наставників позначає поріг справжньої зрілості в культурі тауренів."},{t="Дорога до Села Бладгуф",b="Шлях веде новачків через розлогі трави Малгору до Села Бладгуф — осередку громади, що притулився біля Озера Кам'яного Бика. Там чекає Яв Шарпмейн, бувалий ловець, який добре знає норов тутешньої звірини. Розмова з Шарпмейном — не проста формальність: вона засвідчує, що мисливець готовий до непростих випробувань приборкання звірів і до того, щоб учитися єднатися з хижаками, а не лише полювати на них."}},faq={{q="Навіщо завдання «Шлях мисливця»?",a="Це завдання — офіційне запрошення для молодих мисливців-тауренів розпочати випробування з приборкання звірів. Воно скеровує мисливця до Села Бладгуф, до Ява Шарпмейна, який проводить обряди, потрібні, щоб поєднатися зі звіром-супутником.",al={"навіщо це завдання","мета шляху мисливця","початок завдання вихованця мисливця"}},{q="Хто посилає на це завдання?",a="Завдання дають наставники мисливців-тауренів — наприклад, ті, що стоять у Таборі Нарачі, — щойно молодий мисливець набуде достатньо досвіду й опанує основи виживання та стрільби.",al={"хто дає шлях мисливця","завдання наставника мисливців"}},{q="Хто такий Яв Шарпмейн?",a="Яв Шарпмейн — шанований наставник мисливців-тауренів, що живе в Селі Бладгуф. Йому доручено вчити молодих мисливців небезпечного мистецтва: як підійти до диких звірів Малгора, заспокоїти їх і приборкати.",al={"хто такий шарпмейн","роль яв шарпмейна"}},{q="Що буде після виконання цього завдання?",a="Коли ви доповісте Явові Шарпмейну, він розпочне низку випробувань «Приборкання звіра». Мисливцеві доведеться вирушити в дикі краї з жезлом приборкання й угамувати кількох місцевих тварин, перш ніж здобути право навчати постійного супутника.",al={"що далі","наступне завдання після шляху мисливця"}},{q="Чому мисливці-таурени єднаються зі звірами, а не просто полюють на них?",a="За традицією тауренів, звірі — споріднені душі, діти Земної Матері. Звір, із яким поєднався мисливець, — не слуга, а супутник і напарник на полюванні; у цьому втілено взаємну повагу й спільне виживання на рівнинах.",al={"переказ про вихованців таурена","чому таурени приборкують вихованців"}},{q="Чи можуть мисливці інших рас узяти саме це завдання?",a="Ця версія завдання призначена саме для мисливців-тауренів, які навчаються в Малгорі. Інші раси Орди, як-от орки й тролі, отримують відповідні настанови, пристосовані до їхніх рідних земель у Дуротарі.",al={"чи це лише для таурена","чи орки можуть взяти шлях мисливця таурена"}}},fp="17,421,17.483.0,29.455.0,41.243.0,28.201.0,21.207.0,41.250.0,68.203.0,52.228.0"}
P.entries["quest:6068"] = {n="Шлях мисливця",s="Шлях мисливця — обряд посвяти, що скеровує молодих мисливців-орків і тролів до Гострого Пагорба. Під проводом майстра-мисливця Тотара слідопити-початківці опановують життєво важливу науку — підкоряти диких хижаків своїй волі.",h="Шлях мисливця — обряд посвяти, що скеровує молодих мисливців-орків і тролів до Гострого Пагорба.",kw={"мисливець","тотар","шлях мисливця","гострий пагорб","приборкання","дуротар"},ang={["class:Hunter"]="Цей виклик — найважливіший поріг у вашій подорожі: від самотнього стрільця до справжнього володаря звірів.",["faction:Horde"]="Орда покладається на своїх розвідників і слідопитів, які приборкують тутешніх хижаків і перетворюють безжальну природу Дуротару на свою перевагу.",["race:Orc"]="Для орків союз із лютим супутником відлунює давніми традиціями, що сягають вовчих вершників Дренору.",["race:Troll"]="Мисливці Темного Списа вважають уміння приборкувати місцевих рапторів і вепрів необхідним, щоб закріпитися в підступних нетрях Дуротару."},sec={{t="Пробудження мисливця",b="Досі учень-мисливець у Дуротарі покладався лише на власний лук і кмітливість. Вистежування здобичі серед каньйонів червоної глини й суворих чагарів навчає терпіння, та справжня майстерність в Орді вимагає зв'язку з неприборканою звіриною цього краю. Класові наставники бачать, коли учень досить виріс, щоб ступити на цю дорогу, і посилають його просто до Гострого Пагорба."},{t="Майстер у Гострому Пагорбі",b="У Гострому Пагорбі чекає Тотар — мисливець-ветеран, що глибоко знає дику мудрість Дуротару. Тотар — той наставник, який навчає новачків небезпечного ритуалу: впокорити лютих звірів, не зламавши їхнього духу. Зустріч із ним — перший крок до того, щоб ходити дикими землями з вірним супутником поруч."}},faq={{q="Навіщо завдання «Шлях мисливця»?",a="Це вступний виклик, що відправляє мисливців-орків і тролів до Гострого Пагорба, де вони розпочинають навчання з приборкання звірів.",al={"чому шлях мисливця","мета шляху мисливця","що робить це завдання"}},{q="Хто такий Тотар?",a="Тотар — досвідчений мисливець із Гострого Пагорба, який проводить випробування для молодих слідопитів Орди: вони мають навчитися єднатися з дикими звірами й керувати ними.",al={"хто такий тотар","тотар хто він","тотар разор гілл"}},{q="Чому молоді мисливці не можуть приборкувати вихованців одразу?",a="Щоб упоратися з небезпечним хижаком, потрібні глибока дисципліна, терпіння й особливі прийоми приборкання. Поки мисливець не доведе, що має базові навички виживання, спроба підкорити дикого звіра закінчилася б каліцтвом або смертю.",al={"чому немає вихованця на першому рівні","чому мисливці чекають вихованців","коли мисливці отримують вихованців"}},{q="Які раси проходять саме це випробування?",a="Ця версія шляху призначена для орків і тролів Темного Спису, що дорослішають у Дуротарі; мисливці-таурени проходять подібне випробування в Малгорі.",al={"хто отримує це завдання","чи це лише для орків і тролів","які раси це роблять"}},{q="Що буде, коли я доповім Тотарові?",a="Тотар одразу доручає мисливцеві вистежити й підкорити різних місцевих хижаків Дуротару, щоб довести свою вправність у приборканні.",al={"що далі","після шляху мисливця","наступне завдання після тотара"}},{q="Де відбувається це навчання?",a="Випробування зосереджене довкола Гострого Пагорба — головного поселення в центрі Дуротару, між Долиною Випробувань та Оргріммаром.",al={"де разор гілл","де тотар","куди йти"}}},fp="17,222,20.376.0,24.320.0,41.131.0,14.145.0,46.220.0,42.159.0,39.141.0,36.131.0"}
P.entries["quest:6074"] = {n="Шлях мисливця",s="«Шлях мисливця» — обряд переходу для дворфійських мисливців-новачків по всьому Дун Мороґу, щойно вони опанують основи вистежування та стрільби. Місцеві наставники посилають учнів до Ґріфа Вайлдгарта в Харанос, щоб ті почали вчитися мистецтва приборкання диких звірів як постійних супутників.",h="«Шлях мисливця» — обряд переходу для дворфійських мисливців-новачків по всьому Дун Мороґу, щойно вони...",kw={"мисливець","шлях","вайлдгарт","харанос","приборкання","звір","наставник"},ang={["class:Hunter"]="Це завдання знаменує вирішальний перехід від самотнього слідопита до справжнього володаря звірів, здатного керувати дикими хижаками.",["race:Dwarf"]="Дворфійські горяни здавна тримають ведмедів і вепрів як надійних розвідницьких супутників на засніжених вершинах Дун Мороґу."},sec={{t="Справжнє покликання мисливця",b="Доки мисливець не опанує мистецтво єднання зі звіром, він ходить засніженими скелями Дун Мороґу сам, покладаючись лише на сокиру, рушницю чи лук. Наставники, як-от Олмін Бернінґбірд і Трістан Шедоустоун, пильно стежать за учнями, доки ті не виявлять витримки, потрібної, щоб зустріти дикого звіра й не вбити його. Щойно новачок доводить достатню дисципліну, його посилають гірськими дорогами до Хараноса."},{t="Прибути до Ґріфа Вайлдгарта",b="У Хараносі Ґріф Вайлдгарт наглядає за останніми випробуваннями дворфійського мисливства. Приборкати звіра вважають значно складнішим, ніж убити його заради м'яса чи шкури: це потребує терпіння, фізичної витривалості й чуттєвого зв'язку з дикими хижаками гір. Вайлдгарт — брама до цих випробувань, що готує мисливця до виснажливої перевірки сили волі проти найлютішої звірини Дун Мороґу."}},faq={{q="Навіщо це завдання?",a="Це офіційний виклик, що відправляє подорослішого мисливця до Хараноса, де під наглядом Ґріфа Вайлдгарта починаються випробування з приборкання вихованця.",al={"навіщо це завдання","що таке шлях мисливця","початок завдання вихованця мисливця"}},{q="Хто відправляє мене в цю путь?",a="Своїх учнів на це завдання скеровують наставники мисливців — зокрема Олмін Бернінґбірд у Залі Зброї Айронфорджа, Трістан Шедоустоун та Ейнріс Брайтспір.",al={"хто дає завдання","хто дає шлях мисливця","де його взяти"}},{q="Де знайти Ґріфа Вайлдгарта?",a="Ґріф Вайлдгарт стоїть біля Ґуральні Тандербрю в Хараносі, у засніженій долині Дун Мороґа.",al={"де ґріф вайлдгарт","де ґріф","наставник мисливців харанос"}},{q="Навіщо мисливцям наставник, щоб приборкувати звірів?",a="Приборкання диких звірів вимагає особливих прийомів і жезла приборкання, щоб порозумітися з хижаком, не спровокувавши бою на смерть. Ґріф Вайлдгарт навчає цих традицій.",al={"навіщо потрібне навчання приборкання","переказ про приборкання вихованців","чому ще не можу приборкувати"}},{q="Що буде, коли я доповім Ґріфові Вайлдгарту?",a="Ґріф Вайлдгарт одразу перевіряє, з якого ви тіста, і відправляє вас у дикі краї з жезлом приборкання, щоб підкорити кількох різних звірів, які водяться в Дун Мороґу.",al={"наступне завдання","що після шляху мисливця","ланцюжок після цього"}},{q="Чи може будь-який мисливець узяти саме це завдання?",a="Цей виклик призначений для мисливців-дворфів, які діють у Дун Мороґу: він скеровує їх до місцевого наставника в Хараносі.",al={"чи це лише для дворфів","чи нічні ельфи можуть це взяти","обмеження за расою"}}},fp="17,296,23.404.0,27.430.0,34.124.0,26.164.0,32.114.0,45.184.0,47.153.0,40.129.0"}
P.entries["quest:6081"] = {n="Навчання звіра",s="Навчання звіра — завершальний обряд посвяти для молодих мисливців-орків і тролів у Дуротарі. Довівши владу над дикими звірами рівнин, мисливці вирушають із Гострого Пагорба до Оргріммару вчитися в майстра-мисливця Ормака Ґрімшота. Ця подорож навчає новачка доглядати, годувати й відточувати вміння звіриного супутника на все життя.",h="Навчання звіра — завершальний обряд посвяти для молодих мисливців-орків і тролів у Дуротарі.",kw={"мисливець","ормак ґрімшот","оргріммар","долина честі","улюбленець","навчання звіра"},ang={["class:Hunter"]="Це завдання — мить, коли ваш улюбленець стає постійним, надійним союзником, а не скороминущим прикликанням: воно відкриває необхідні вміння «Годування улюбленця» й «Оживлення улюбленця».",["faction:Horde"]="Орда покладається на своїх розвідників і звірів, щоб берегти крихкі кордони Дуротару й Пусток від набігів кентаврів, шипогривів та Альянсу.",["race:Orc"]="Орки вважають зв'язок із мисливським супутником справою воїнської честі й обов'язку — союзом, що гартується в боях на суворих рубежах Дуротару.",["race:Troll"]="Для тролів Темного Списа, що облаштовують новий дім у Калімдорі, уміння порозумітися з дикими створіннями Дуротару життєво важливе для розвідки й виживання на незнайомій землі."},sec={{t="Подорож за межі дикої землі",b="У посушливих каньйонах Дуротару опанувати лук і вистояти проти суворої природи — лише половина обов'язку мисливця. Довівши свою стійкість приборканням лютих вепрів Дуротару, прибійних крабів і броньованих скорпідів, молоді мисливці готові до справжньої відповідальності — опіки над звіром. Тотар, що стоїть у Гострому Пагорбі, посилає їх на північ через яри червоної глини просто до укріплених воріт Оргріммару."},{t="Долина Честі",b="У велелюдній столиці майбутні майстри-слідопити мають розшукати Долину Честі — осередок, де войовничі душі й досвідчені слідопити відточують своє ремесло. Там живе Ормак Ґрімшот, один із найшанованіших майстрів-мисливців Орди. Ормак дивиться крізь зелену юність, щоб побачити, чи має мисливець терпіння не лише командувати звіром, а й підтримувати та плекати його крізь голод, битви та втрати."},{t="Зв'язок із дикою природою",b="Звір, здобутий силою волі, лишається диким, доки між мисливцем і супутником не постане порозуміння. Ормак передає священні традиції, потрібні, щоб берегти цей зв'язок: знання про те, яка їжа живить дух кожної істоти, дисципліну, щоб навчити їх смертоносних прийомів, і духовну зосередженість, щоб оживити полеглого звіра, якщо він впаде, виконуючи обов'язок."}},faq={{q="Хто дає завдання «Навчання звіра»?",a="Тотар, наставник мисливців, що стоїть біля казарм на Гострому Пагорбі, пропонує це завдання, коли ви успішно підкорите всіх трьох звірів-випробувачів у Дуротарі.",al={"хто дає навчання звіра","хто починає навчання звіра","де почати навчання звіра"}},{q="Де знайти Ормака Ґрімшота?",a="Ормак Ґрімшот живе в Долині Честі — східному кварталі столиці Оргріммар, поряд з іншими досвідченими наставниками мисливців і воїнів.",al={"де ормак ґрімшот","знайти ормака ґрімшота","де ормак"}},{q="Чого навчає Ормак Ґрімшот?",a="Ормак навчає, як прищеплювати супутникові активні й пасивні вміння, як годувати вихованця, щоб він лишався відданим і задоволеним, і як оживити його, якщо він загине в бою.",al={"чого я навчуся","навички з нагороди","здібності вихованця мисливця"}},{q="Чому мисливцям-оркам і тролям для цього треба йти до Оргріммара?",a="Місцеві наставники на кшталт Тотара можуть навчити основ виживання в дикій природі, але вищу майстерність володіння звірами бережуть старші розвідники Орди й шановані слідопити на зразок Ормака Ґрімшота в столиці.",al={"чому йти до оргріммара","чому оргріммар","відвідини долини честі"}},{q="Чи виконують саме це завдання інші раси Орди?",a="Ні. Цей обряд призначений для мисливців-орків і тролів, що починають у Дуротарі. Мисливці-таурени проходять схожий ритуал у Малгорі під проводом власних племінних майстрів.",al={"чи таурени можуть це зробити","чи це лише для орків","мисливець нежить"}},{q="Що буде, якщо мисливець не завершить це навчання?",a="Не пройшовши цього навчання, мисливець не зможе годувати свого супутника, як слід його тренувати чи воскрешати, тож будь-який упійманий звір буде нещасним, слабким і зрештою схильним його покинути.",al={"чи потрібно це робити","чи можна пропустити навчання звіра"}}},fp="18,382,31.428.0,19.411.0,21.391.0,40.164.0,32.156.0,42.174.0,62.190.0,48.167.0,60.188.0"}
P.entries["quest:6082"] = {n="Приборкання звіра",s="Це завдання — останнє випробування в основних обрядах посвяти молодого мисливця Орди в Дуротарі. Під проводом мисливця-ветерана Тотара в Гострому Пагорбі майбутній слідопит має зустрітися з небезпечним броньованим скорпідом і приборкати його. Перемога над цим панцирним хижаком доводить владу над дикими звірами й відкриває довічну здатність приборкувати, кликати й відпускати справжнього супутника.",h="Це завдання — останнє випробування в основних обрядах посвяти молодого мисливця Орди в Дуротарі.",kw={"мисливець","тотар","скорпід","приборкання","гострий пагорб","улюбленець"},ang={["class:Hunter"]="Цей обряд посвяти — визначальна віха раннього шляху мисливця: він назавжди відкриває основні вміння приборкувати, кликати й вести звіриних супутників.",["faction:Horde"]="Молоді орки й тролі в Дуротарі мають вистояти проти найлютіших хижаків пустельної землі, щоб заслужити місце справжніх розвідників і годувальників Орди.",["race:Orc"]="Упокорення скорпідів Дуротару вшановує орківську філософію: долати сувору землю незламною волею й воїнською дисципліною.",["race:Troll"]="Мисливці Темного Списа покладаються на гостре чуття й глибокий зв'язок із духами дикої природи, щоб угамувати отруйних хижаків, які вразили б інших."},sec={{t="Останнє випробування",b="Перш ніж мисливцеві дозволять блукати Калімдором із вірним звіриним супутником, він має довести, що здатен приборкати найсуворішу звірину Дуротару. Наставник мисливців Гострого Пагорба Тотар посилає учнів впокорити трьох різних створінь зачарованим жезлом приборкання. Уже випробувавши свою стійкість проти лютих вепрів і прудких прибійних крабів, мисливці мають стати проти броньованого скорпіда — отруйного хижака в товстому панцирі, що втілює витривалість і смертоносну швидкість."},{t="Зв'язок із дикою природою",b="Упокорити броньованого скорпіда — це не просто вбивство, а доказ зосередженості й панування під невпинним натиском. Тотар закликає мисливців наслідувати швидкі, впевнені удари звіра. Повернення до Гострого Пагорба після успішного приборкання отруйного членистоногого доводить, що мисливець має спокійну волю, потрібну, щоб утримувати владу. Коли жезл приборкання повернуто, Тотар передає вроджені прийоми дикої природи, і мисливець може сам шукати й прив'язувати постійного супутника на власний вибір."}},faq={{q="Якого звіра треба приборкати в цьому випробуванні?",a="Вам треба знайти броньованого скорпіда, що блукає посушливими червоними скелями Дуротару, і жезлом приборкання Тотара угамувати його та підкорити.",al={"якого звіра приборкати","цільовий звір","завдання скорпіда"}},{q="Чи залишиться броньований скорпід зі мною після завдання?",a="Ні. Броньований скорпід, приборканий під час випробування, — тимчасовий і зникає, щойно ви повернете навчальний жезл. Зате, виконавши завдання, ви назавжди здобудете вміння приборкувати будь-якого дикого звіра, якого забажаєте.",al={"чи скорпід лишиться","чи я лишу вихованця","скорпід постійний"}},{q="Хто проводить цей обряд посвяти?",a="Тотар, наставник мисливців із Гострого Пагорба в центрі Дуротару, проводить цей обряд посвяти для молодих мисливців-орків і тролів.",al={"хто дає завдання","хто дає приборкання звіра","де тотар"}},{q="Чому Тотар хоче, щоб мисливці приборкали саме броньованого скорпіда?",a="Тотар вважає броньованого скорпіда взірцем для наслідування через його впевнені, стрімкі удари й природну витривалість. Підкоривши такого небезпечного хижака, мисливець доводить, що готовий керувати будь-яким диким звіром.",al={"чому скорпід","навіщо скорпід"}},{q="Яких умінь я навчуся, виконавши це завдання?",a="Це випробування дає основні вміння досвідченого володаря звірів: «Приборкати звіра», «Покликати вихованця» й «Відпустити вихованця».",al={"нагороди","які закляття я отримаю","відкриті навички приборкання"}},{q="Що буде після цього випробування?",a="Коли ви навчитеся приборкувати й кликати власного супутника, Тотар скерує вас тренувати вихованця й дасть наступне завдання — «Навчання звіра», щоб ви опанували, як годувати свого союзника й командувати ним.",al={"наступне завдання","що далі","після приборкання 3"}}},fp="16,359,15.484.0,21.523.0,47.128.0,63.215.0,35.136.0,69.220.0,52.122.0,28.207.0"}
P.entries["quest:6083"] = {n="Приборкання звіра",s="Друге випробування в обряді майстерності молодого мисливця в Дуротарі, яке доручає наставник Тотар у Гострому Пагорбі. Майбутніх мисливців-орків і тролів посилають на узбережжя біля Островів Відлуння приборкати прибійного краба — так їхній зв'язок виходить за межі суходільних звірів до прибережної живності.",h="Друге випробування в обряді майстерності молодого мисливця в Дуротарі, яке доручає наставник Тотар у Гострому...",kw={"мисливець","тотар","прибійний краб","приборкання","острови відлуння","узбережжя"},ang={["class:Hunter"]="Це випробування закладає основну дисципліну, потрібну, щоб керувати захисними звірами, і показує, як природний панцир і впертість створіння доповнюють стрільця.",["race:Orc"]="Для орків, що облаштовують постійний дім у Дуротарі, впокорення витривалої живності узбережжя підкріплює їхню владу над суворим краєм.",["race:Troll"]="Тролі Темного Списа добре знають води біля Островів Відлуння й Села Сен'джин, тож це випробування — зустріч зі знайомою живністю їхнього прибережного притулку."},sec={{t="Зв'язок із узбережжям",b="Упокоривши лютого плямистого вепра, мисливець-початківець дістає від Тотара нове завдання — звернути погляд до моря. Сувора природа Дуротару — це й зубчасті береги, і мілкі рифи, де кишать панцирні ракоподібні. Зустріч із прибійним крабом вимагає терпіння й стійкості, адже ці броньовані краби опираються кожному вторгненню в їхні прибережні володіння."},{t="Продовження волі",b="Тотар навчає, що кожен звір, якого прив'язує мисливець, має стати продовженням його власної сили. Упокорюючи жезлом приборкання водяне створіння, як-от прибійного краба, мисливець учиться поширювати свою владну присутність на різні вдачі й середовища, доводячи готовність до постійних супутників."}},faq={{q="Де водяться прибійні повзуни?",a="Прибійні повзуни снують уздовж східного узбережжя Дуротару, зокрема на мілинах навпроти Села Сен'джин, біля вод, що ведуть до Островів Відлуння.",al={"де прибійний повзун","місця прибійних повзунів","де краби"}},{q="Навіщо приборкувати прибійного повзуна?",a="Тотар доручає приборкати прибійного повзуна, щоб навчити мисливців керувати різними звірами. Опанувавши приборкання панцирної водяної істоти, мисливець розширює свою владу й доводить, що впорається з тваринами з води так само легко, як і з суходолу.",al={"навіщо приборкувати краба","мета завдання прибійного повзуна"}},{q="Чи залишиться прибійний повзун зі мною назавжди?",a="Ні. Звірі, приборкані під час цих перших випробувань, — лише тимчасові навчальні піддослідні, підкорені магією жезла приборкання Тотара. Тільки пройшовши всю низку випробувань, ви назавжди опануєте вміння приборкувати звірів.",al={"чи лишу краба","чи прибійний повзун постійний"}},{q="Хто дає це завдання?",a="Тотар, наставник мисливців із Гострого Пагорба, пропонує це випробування, після того як ви доведете, що здатні приборкати лютого плямистого вепра.",al={"хто дає завдання","хто починає приборкання звіра 2"}},{q="Що буде після приборкання прибійного повзуна?",a="Коли ви повернете жезл Тотарові, він дасть вам третє, останнє випробування — вистежити й приборкати Броньованого Скорпіда, — а тоді навчить вас володіти звірами назавжди.",al={"наступне завдання","що далі в ланцюжку"}},{q="Навіщо жезл приборкання, а не власні навички?",a="Мисливці-новачки ще не виплекали вродженої духовної влади, потрібної, щоб поєднатися з дикими звірами назавжди. Жезл приборкання слугує провідником, що дає змогу початківцям безпечно вчитися спрямовувати свою волю, перш ніж опанувати справжню техніку.",al={"навіщо жезл приборкання","що таке жезл приборкання"}}},fp="16,281,22.353.0,21.318.0,30.166.0,45.230.0,39.219.0,21.126.0,41.179.0,47.241.0"}
P.entries["quest:6084"] = {n="Приборкання звіра",s="Це завдання — друге випробування в посвяті дворфійського мисливця, яке дає Ґріф Вайлдгарт у Хараносі. Навчившись давати раду грубій витривалості скелястого вепра, юний мисливець має опанувати прудкість і смертоносну грацію тутешнього снігового леопарда.",h="Це завдання — друге випробування в посвяті дворфійського мисливця, яке дає Ґріф Вайлдгарт у Хараносі.",kw={"приборкання","леопард","мисливець","вайлдгарт","жезл","харанос"},ang={["class:Hunter"]="Цей обряд переходу вчить дворфійських мисливців-новачків різниці між витривалими улюбленцями на кшталт вепрів і прудкими, агресивними бійцями на кшталт котів.",["race:Dwarf"]="Горяни Каз Модану здавна ділять замерзлі вершини Дун Мороґу зі сніговими леопардами, поважаючи і їхню скрадливість, і смертоносну мисливську вправність."},sec={{t="Урок витонченості",b="Якщо скелясті вепри вчать горянина витримувати неприкриту лють і тримати удар, то Ґріф Вайлдгарт наголошує: справжній мисливець має розуміти різні стилі бою. Він показує учням на південний схід, де нишпорять снігові леопарди Дун Мороґу. Ґріф порівнює цих граційних хижаків із вишукано зробленою рушницею: зовні вражають, та під білосніжними шубами ховають нищівну силу."},{t="Опанування Жезла Приборкання",b="Зачарованим жезлом приборкання мисливець має зустріти дикого леопарда і повернути його мисливські інстинкти на партнерство. Снігові леопарди випробовують спритність, швидкість і гострі рефлекси, а не чисту витривалість. Опанувати такого звіра означає довести, що новачок здатен порозумітися з хижаками, які блискавично б'ють із засніжених скель, — і зробити ще один крок до справжньої влади над дикими звірами."}},faq={{q="Навіщо це завдання?",a="Це другий етап обряду посвяти мисливців-дворфів. Наставник мисливців Ґріф Вайлдгарт вимагає від учнів перевірити свої вміння на різних диких звірах, перш ніж дати їм знання, як назавжди поєднатися зі звірами-супутниками.",al={"навіщо це завдання","завдання снігового леопарда дворф","приборкання звіра 2"}},{q="Де знайти снігових леопардів?",a="Снігові леопарди скрадаються кам'янистими скелями й засніженими схилами на південь і схід від Хараноса в Дун Мороґу.",al={"де сніговий леопард","де сніжні леопарди дун мороґ","місця леопардів"}},{q="Навіщо Ґріф Вайлдгарт посилає приборкувати леопарда?",a="Ґріф вважає, що мисливець має відчути і грубу силу, і витончену спритність. Скелястий вепр покладається на кремезну витривалість, а сніговий леопард навчить мисливця битися пліч-о-пліч зі швидким, моторним і смертоносним бійцем.",al={"чому сніговий леопард","чому ґріф вайлдгарт посилає по леопарда"}},{q="Чи залишиться цей сніговий леопард зі мною назавжди?",a="Ні. Звірі, приборкані під час цих перших випробувань, — тимчасові навчальні напарники, прив'язані магією жезла приборкання. Коли наприкінці ланцюжка завдань Ґріф визнає ваше навчання завершеним, ви назавжди здобудете вміння приборкати будь-якого дикого звіра на свій вибір.",al={"чи лишу снігового леопарда","чи леопард постійний"}},{q="Хто призначає це випробування?",a="Ґріф Вайлдгарт, наставник мисливців-дворфів, що стоїть біля таверни в Хараносі, у Дун Мороґу.",al={"хто дає завдання","видавець завдання","роль ґріфа вайлдгарта"}},{q="Що далі в ланцюжку?",a="Коли ви доведете, що впоралися зі сніговим леопардом, Ґріф відправить вас на третє, останнє випробування — приборкати Ведмедя Крижаний Кіготь, — а тоді офіційно навчить приборкувати й тренувати диких звірів самостійно.",al={"наступне завдання","що після снігового леопарда"}}},fp="16,259,19.416.0,24.396.0,34.251.0,34.110.0,50.228.0,47.254.0,23.91.0,29.204.1"}
P.entries["quest:6085"] = {n="Приборкання звіра",s="Це завдання — останнє випробування в базовому вишколі дворфійського мисливця під проводом Ґріфа Вайлдгарта з Хараноса. Приборкавши зачарованим жезлом агресивного Ведмедя Крижаного Кігтя і зрозумівши його, мисливець доводить владу над чистою грубою силою. Виконання цієї вправи відкриває основні вміння, потрібні, щоб приборкати, покликати й відпустити постійного дикого супутника.",h="Це завдання — останнє випробування в базовому вишколі дворфійського мисливця під проводом Ґріфа Вайлдгарта з...",kw={"приборкання","ведмідь","крижаний кіготь","мисливець","вайлдгарт","жезл","харанос"},ang={["class:Hunter"]="Це завдання — обряд переходу, що перетворює самотнього лучника на справжнього мисливця-приборкувача й відкриває головні вміння приборкувати та прикликати звірів.",["race:Dwarf"]="Ведмеді здавна були знаковими супутниками дворфійських горян, що патрулюють Дун Мороґ, і славляться тим, що не поступаються господарям упертою стійкістю."},sec={{t="Сила дикої природи",b="По всьому Дун Мороґу горяни й розвідники здавна покладаються на витривалих звірів, щоб пережити крижані скелі. Після вправ на прудких і хитрих хижаках майстер-мисливець Ґріф Вайлдгарт ставить перед новачками останню ціль — Ведмідь Крижаний Кіготь. Ці величезні звірі, що нишпорять у снігових заметах на схід від Хараноса, втілюють грубу фізичну міць і невтомну витривалість — якості, які кожен дворфійський мисливець має навчитися підкоряти."},{t="Заслужити супутника",b="Випробування з Жезлом Приборкання — суто навчальні вправи, що показують мисливцям, як дикі інстинкти відгукуються на волю і спокійний намір. Щойно жезл утихомирює ведмедя, тимчасовий зв'язок виконує своє призначення. Повернення знаряддя Ґріфу завершує офіційні випробування, і майстер розкриває довічні таємниці володіння звірами: як умиротворити будь-яке придатне дике створіння і кликати його впродовж цілого життя пригод."}},faq={{q="Якого звіра треба приборкати в цьому завданні?",a="Вам треба розшукати Ведмедя Крижаний Кіготь, що никає замерзлими пагорбами на схід від Хараноса в Дун Мороґу. Жезл Приборкання, який вам дадуть, підкорить звіра, і ви відчуєте, як це — керувати неприборканою грубою силою.",al={"який ведмідь","цільова тварина","ціль приборкання"}},{q="Чи залишиться Ведмідь Крижаний Кіготь зі мною, коли я здам завдання?",a="Ні. Ведмідь, підкорений Жезлом Приборкання, — лише тимчасова перевірка дисципліни й уміння. Щойно ви повернете жезл Ґріфові Вайлдгарту, звір піде, а ви здобудете справжнє вміння приборкувати будь-якого дикого звіра на свій вибір.",al={"чи лишу ведмедя","лишити вихованця","чи ведмідь постійний"}},{q="Де знайти Ґріфа Вайлдгарта?",a="Ґріф Вайлдгарт стоїть біля Ґуральні Тандербрю в Хараносі, у Дун Мороґу, де навчає молодих мисливців стрільби й володіння звірами.",al={"де ґріф","де знайти ґріфа","наставник мисливців харанос"}},{q="Яких умінь я навчуся, пройшовши це випробування?",a="Це останнє випробування навчить вас основних заклинань мисливця: «Приборкати звіра», «Покликати вихованця» й «Відпустити вихованця». Тепер ви можете вирушити у світ і поєднатися з постійним супутником.",al={"нагороди завдання","навички мисливця","нагорода приборкання звіра"}},{q="Що робити після виконання цього завдання?",a="Ґріф відправить вас далі із завданням «Навчання звіра»: ви маєте навчитися як слід годувати, доглядати й навчати нового супутника, щоб він лишався відданим у бою.",al={"наступне завдання","що далі","навчання звіра"}},{q="Чому Ґріф змушує мисливців випробовувати кілька видів звірів?",a="Три випробування знайомлять мисливця-новачка з різними стилями бою — спритністю, хитрістю й грубою силою. Пізнавши ці різні вдачі, горянин зможе обрати найкращого супутника для свого способу полювання.",al={"чому три звіри","мета випробувань","три тварини"}}},fp="16,364,24.446.0,19.439.0,45.200.0,55.227.0,32.168.0,52.198.0,50.177.0,57.223.0"}
P.entries["quest:6086"] = {n="Навчання звіра",s="«Навчання звіра» — завершальний обряд переходу для молодих дворфійських мисливців у Дун Мороґу. Опанувавши мистецтво втихомирення й приборкання диких хижаків серед засніжених скель, слідопити-новачки вирушають у серце Айронфорджа, щоб навчитися годувати, вишколювати й доглядати довічного тваринного супутника.",h="«Навчання звіра» — завершальний обряд переходу для молодих дворфійських мисливців у Дун Мороґу.",kw={"навчання звіра","мисливець","тандерґраніт","зала зброї","айронфордж","супутник","улюбленець"},ang={["class:Hunter"]="Ця віха відкриває саму серцевину мисливського ремесла: уміння належно годувати постійного тваринного супутника, керувати ним і воскрешати його.",["faction:Alliance"]="Володарі звірів Айронфорджа — вагома частина розвідувальних сил Альянсу, що покладаються на вірних супутників із дикої природи, патрулюючи крижані гірські перевали.",["race:Dwarf"]="Дворфи бачать у полюванні давню традицію гірських нетрів Каз Модану й мають ведмедів, вепрів і гірських котів за шанованих партнерів у розвідці та обороні."},sec={{t="З дикої природи до Кузні",b="Довівши свою вправність на диких звірах Дун Мороґу — втихомиривши жезлом приборкання великих скелястих вепрів, снігових леопардів і міцних ведмедів Крижаних Кігтів, — учні-мисливці завершують випробування під пильним оком Ґріфа Вайлдгарта біля Хараноса. Та впіймати дике серце тварини — лише половина зв'язку. Ґріф посилає своїх загартованих вихованців гірським перевалом до Айронфорджа — знайти військовий квартал, відомий як Зала Зброї."},{t="Наука Белії Тандерґраніт",b="У кам'яних склепіннях Зали Зброї Айронфорджа стоїть Белія Тандерґраніт — одна з найшанованіших майстринь дресирування тварин у дворфійському королівстві. Белія передає найважливіше знання, яке перетворює дикого переляканого звіра на запекло відданого партнера. Її наука сягає далеко за прості команди: вона показує молодим мисливцям, як годувати улюбленців, навчати їх нових бойових умінь і навіть повертати їхні душі зі смерті, якщо ті поляжуть, боронячи господаря."},{t="Зв'язок дворфійського мисливця",b="Дворфійська традиція наголошує, що володіння звірами будується на повазі, а не на підкоренні. Белія нагадує кожному молодому мисливцю: тваринний супутник відображає турботу, яку отримує. Якщо звіра добре годувати, поважати й належно вишколювати, він відплатить непохитною відданістю проти трогів, морозних тролів і будь-якої загрози, що зазіхне на Каз Модан."}},faq={{q="Навіщо це завдання?",a="Це завдання — останній крок базового навчання мисливця-дворфа. Воно дає основні знання, потрібні, щоб утримувати постійного бойового вихованця: годувати його, розвивати його вміння, кликати до себе й воскрешати, якщо він загине.",al={"навіщо це завдання","мета навчання звіра","нагорода вихованця мисливця"}},{q="Хто така Белія Тандерґраніт?",a="Белія Тандерґраніт — шанована майстриня-дресирувальниця звірів у Залі Зброї Айронфорджа. Вона старша наставниця дворфійських слідопитів: учить їх дисципліни, харчування звірів і команд, потрібних, щоб приборкані дикі тварини стали союзниками на все життя.",al={"хто така белія","переказ про белію тандерґраніт","наставниця мисливців айронфорд"}},{q="Де знайти Белію Тандерґраніт?",a="Белія Тандерґраніт перебуває в Айронфорджі, у Залі Зброї — військовому крилі міста, де збираються й тренуються воїни, мисливці й паладини з дворфів і гномів.",al={"де белія","де белія тандерґраніт","де зала зброї айронфорд"}},{q="Яких звірів приборкують мисливці-дворфи перед цим навчанням?",a="Під час попередніх випробувань Ґріф Вайлдгарт перевіряє молодих мисливців: вони мають зачарованим жезлом тимчасово угамувати великого скелястого вепра, снігового леопарда й ведмедя Крижаний Кіготь у Дун Мороґу.",al={"яких звірів приборкують","випробування вихованців дворфа","звірі з попередніх завдань"}},{q="Чому мисливці-дворфи мусять годувати своїх вихованців?",a="За звіриною наукою дворфів, тварини-супутники — напарники, а не знаряддя. Якщо не дбати про голод звіра, його настрій псується, а охота битися згасає; ситий же звір запекло відданий і в бою якнайдієвіший.",al={"навіщо годувати вихованця","переказ про задоволеність вихованця","вірність звіра дворфа"}},{q="Хто дає це завдання?",a="Ґріф Вайлдгарт, досвідчений наставник мисливців, що стоїть край дороги на схід від Хараноса в Дун Мороґу, дає це завдання, коли ви успішно пройдете третє випробування з приборкання.",al={"хто починає навчання звіра","роль ґріфа вайлдгарта","хто дає завдання"}}},fp="18,311,26.447.0,32.466.0,25.360.0,34.249.0,28.258.0,37.166.0,67.211.0,41.254.0,21.184.0"}
P.entries["quest:6087"] = {n="Приборкання звіра",s="Це випробування — другий ступінь посвяти мисливця-таурена в мистецтво приборкання звірів. Під проводом наставника мисливців Ява Шарпмейна в Селі Бладгуф новачок має підкорити швидкого й безстрашного степового переслідувача.",h="Це випробування — другий ступінь посвяти мисливця-таурена в мистецтво приборкання звірів.",kw={"приборкання","степовий переслідувач","вовк","яв шарпмейн","село бладгуф","малгор","мисливець"},ang={["class:Hunter"]="Цей обряд посвяти поєднує основи виживання з наступальною злагодженістю і вчить вас битися пліч-о-пліч зі стрімким супутником.",["race:Tauren"]="На відміну від культур, де улюбленців мають лише за робочу худобу, шу'хало бачать у приборканні звіра кування священної спорідненості під пильною ласкою Земної Матері."},sec={{t="Уроки переслідувача",b="Коли молодий мисливець опанував оборонну витривалість дорослого довгоступа, Яв Шарпмейн кидає йому виклик: дивитися далі простого виживання. Степовий переслідувач утілює зовсім іншу філософію полювання — невпинну швидкість, злагодженість зграї та безстрашний натиск. Щоб приборкати такого, треба підійти до хитрого хижака, не збившись із кроку, віддзеркаливши рішучу вдачу самого вовка."},{t="Пліч-о-пліч",b="Для тауренів полювання разом зі звіром ніколи не було ні рабством, ні грубим підкоренням. Яв Шарпмейн наголошує: мисливець і хижак мають битися як одне ціле, пов'язані взаємною повагою та спільним ритмом. Зріднившись зі степовим переслідувачем під відкритим небом Малгору, мисливець учиться доповнювати натиск партнера й рухатися з ним у лад у розпал бою."}},faq={{q="Якого звіра Яв Шарпмейн просить приборкати в цьому випробуванні?",a="Цей другий урок вимагає приборкати степового скрадача — одного з прудких вовків, що никають хвилястими рівнинами Малгора.",al={"якого звіра приборкати","який вихованець наступний","приборкати степового скрадача"}},{q="Чому мисливець-таурен учиться приборкувати вовків?",a="Яв Шарпмейн навчає, що степовий скрадач уособлює швидкість і безстрашність. Поєднавшись із таким хижаком, мисливець переймає саме ці риси й учиться злагоджено атакувати разом зі спритним напарником на полюванні.",al={"чому вовки","переказ про степового скрадача","навіщо приборкувати вовка"}},{q="Де зазвичай водяться степові скрадачі?",a="Степові скрадачі блукають трав'янистими рівнинами центрального й північного Малгора й часто полюють у преріях довкола Села Бладгуф.",al={"де степовий скрадач","де степові скрадачі","знайти степового скрадача"}},{q="Чи залишиться степовий скрадач зі мною після завдання?",a="Ні. Жезл приборкання створює лише тимчасовий зв'язок для навчання. Коли ви пройдете всю низку випробувань, то назавжди здобудете вміння приборкувати будь-якого дикого супутника на свій вибір.",al={"чи лишу вовка","лишити степового скрадача","чи це мій постійний вихованець"}},{q="Хто такий Яв Шарпмейн?",a="Яв Шарпмейн — місцевий наставник мисливців у Селі Бладгуф. Він веде молодих тауренів через духовні й практичні рубежі, які треба подолати, щоб опанувати дику природу Малгора.",al={"хто такий яв","переказ про шарпмейна","яв кривавий копит"}},{q="Що буде після приборкання степового скрадача?",a="Коли Яв Шарпмейн переконається, що ви впоралися з вовком, він відправить вас на третє, останнє випробування ланцюжка — перевірити свою рішучість на потайливому стрімкокрилі.",al={"наступне завдання","що після степового скрадача","третє завдання приборкання"}}},fp="16,233,21.405.0,16.376.0,60.124.0,46.237.0,44.136.0,53.198.0,21.187.0,44.173.0"}
P.entries["quest:6088"] = {n="Приборкання звіра",s="Це випробування — останній урок молодого мисливця-таурена в навчанні у Ява Шарпмейна в Селі Бладгуф. Зріднившись за допомогою жезла приборкання з диким стрімкокрилом, мисливець доводить владу над створіннями повітря й здобуває священну довіру Земної Матері. Виконання цього завдання дарує тривке знання, потрібне, щоб приборкати довічного супутника й керувати ним.",h="Це випробування — останній урок молодого мисливця-таурена в навчанні у Ява Шарпмейна в Селі Бладгуф.",kw={"приборкання","стрімкокрил","яв шарпмейн","село бладгуф","малгор","мисливець","жезл приборкання"},ang={["class:Hunter"]="Це завдання завершує ланцюжок основного навчання, що відкриває постійне приборкання звірів, і позначає перехід від учня до цілком самостійного розвідника дикого краю.",["race:Tauren"]="Для шу'хало зріднення з диким звіром — акт духовного єднання, благословенний Земною Матір'ю, і воно має глибоке культурне значення на всіх рівнинах Малгору."},sec={{t="Влада над небом",b="Коли наземних хижаків пагорбистих рівнин Малгору вже підкорено, Яв Шарпмейн звертає вашу увагу до відкритого неба. Стрімкокрил — лютий гостродзьобий хижий птах, відомий розмашистими піке й грізною поставою. Узяти під владу такого дикого крилатого мисливця — випробування для ваших рефлексів і спокою: доведеться витерпіти його кігті, зачарованим жезлом настроюючи свій дух на його інстинкти."},{t="Дар Земної Матері",b="Для тауренів полювання й дружба з тваринами — передусім духовний шлях, а не просте підкорення. Опанувавши створіння і землі, і неба, ви засвідчуєте рівновагу й повагу, потрібні, щоб ходити рівнинами, не порушуючи природи. Яв Шарпмейн визнає цю зрілість: забирає свій тимчасовий жезл приборкання й передає вам тривкі вміння — кликати, відпускати й назавжди приборкувати супутника на власний вибір."}},faq={{q="Чому для останнього випробування треба приборкати стрімкокрила?",a="Яв Шарпмейн хоче перевірити, як ви впораєтеся з істотами, що живуть у небі. Стрімкокрили атакують гостро й стрімко та мають грізний вигляд; приборкавши такого птаха, мисливець доводить, що дасть раду і з повітряними хижаками, і з наземними звірами, а отже, заслуговує на справжню самостійність.",al={"чому приборкати стрімкокрила","мета приборкання стрімкокрила","чому стрімкокрил"}},{q="Чи залишиться стрімкокрил, якого я приборкаю, зі мною?",a="Ні. Стрімкокрила приборкують тимчасово, жезлом приборкання Ява Шарпмейна, у межах обрядового навчання. Виконавши завдання, ви здобудете справжнє вміння приборкувати будь-якого дикого звіра, якого захочете залишити назавжди.",al={"чи лишу стрімкокрила","чи стрімкокрил мій вихованець","чи можна лишити птаха"}},{q="Хто дає це завдання і де його знайти?",a="Яв Шарпмейн, наставник мисливців у Селі Бладгуф у центрі Малгора, пропонує це завдання як третій і останній крок перших випробувань із приборкання звірів.",al={"хто дає завдання","хто починає це","де яв шарпмейн"}},{q="Що буде, коли я поверну жезл приборкання?",a="Яв Шарпмейн навчить вас власних умінь приборкувати, кликати й відпускати звірів. А ще він скерує вас до Тандер Блафа, щоб ви навчилися як слід тренувати обраного супутника й дбати про нього.",al={"чого я навчуся далі","нагороди за завершення","що після цього завдання"}},{q="Де в Малгорі знайти диких стрімкокрилів?",a="Стрімкокрили кружляють над відкритими луками й краями столових гір по всьому центральному Малгору, часто просто над рівнинами за Селом Бладгуф.",al={"місця стрімкокрилів","де стрімкокрили","знайти стрімкокрила"}},{q="Чому приборкання вихованця вважається в тауренів обрядом посвяти?",a="Таурени бачать у звірах не знаряддя, а таких самих дітей Земної Матері. Щоб поєднатися із супутником, потрібні терпіння, взаємна повага й духовна рівновага, а не сама лише сила.",al={"переказ про мисливців-тауренів","духовний шлях мисливця","зв'язок із землею-матір'ю"}}},fp="16,362,18.438.0,22.453.0,50.249.0,45.209.0,48.161.0,43.207.0,40.132.0,58.199.0"}
P.entries["quest:6089"] = {n="Навчання звіра",s="«Навчання звіра» — завершальний обряд посвяти для молодих мисливців-тауренів у Малгорі. Довівши духовне терпіння й рішучість, потрібні, щоб угамувати диких звірів рівнин, мисливці вирушають до Тандер Блафа опановувати довічну науку: ріднитися з постійним тваринним супутником, годувати його й керувати ним.",h="«Навчання звіра» — завершальний обряд посвяти для молодих мисливців-тауренів у Малгорі.",kw={"навчання звіра","голт тандергорн","узвишшя мисливців","тандер блаф","яв шарпмейн","мисливець","супутник"},ang={["class:Hunter"]="Цей обряд позначає перехід від самотньої боротьби до бою поруч із вірним супутником і завершує ваше основне навчання як охоронця дикого краю.",["race:Tauren"]="Для шу'хало взяти тваринного супутника в бій — священний обов'язок опіки та поваги до творінь Земної Матері."},sec={{t="Шлях до Великого Бескиду",b="Випробувавши свій дух проти небезпечних хижаків Малгору — довгоступів, степових переслідувачів і стрімкокрилів, — мисливці-таурени визнаються гідними справжнього мисливського звання. Яв Шарпмейн, наставник із Села Бладгуф, доручає новачкові подорож на Узвишшя Мисливців у Тандер Блафі. Там стоїть Голт Тандергорн — легендарна постать серед шу'хало, чия слава в єднанні з дикою природою поступається лише його шані до Земної Матері."},{t="Священний зв'язок",b="Для тауренів звір — не проста зброя і не невільник, а партнер, дарований через гармонію з природним світом. Голт Тандергорн передає знання, конче потрібні, щоб підтримувати це партнерство. Мисливець має навчитися не лише спрямовувати бойові інстинкти створіння, а й живити його тіло регулярним годуванням, гоїти його рани й кликати його дух назад, якщо воно впаде, захищаючи свого товариша на рівнинах."}},faq={{q="З ким говорити для цього завдання?",a="Вам треба поговорити з Голтом Тандергорном, майстром-мисливцем на Узвишші Мисливців у Тандер Блафі. Яв Шарпмейн скеровує вас до нього, щойно ви завершите перші випробування з приборкання диких звірів у Малгорі.",al={"здати завдання","хто такий голт тандергорн","де голт"}},{q="Чого вчаться мисливці-таурени, виконавши це завдання?",a="Голт Тандергорн навчає, як тренувати вихованця новим умінням, як годувати супутника, щоб він лишався відданим і задоволеним, і як оживити вихованця, якщо той загине в бою.",al={"які здібності я отримаю","навички з нагороди","чого навчає голт"}},{q="Яке місце це завдання посідає в ланцюжку мисливців-тауренів?",a="Це останнє завдання низки. Воно йде після «Шляху мисливця» і трьох випробувань «Приборкання звіра», під час яких мисливець тимчасово угамовує дорослого рівнинного довгоступа, степового скрадача й стрімкокрила на рівнинах.",al={"ланцюжок мисливців","завдання вихованця мулґор","ланцюжок навчання звіра"}},{q="Чому Голт Тандергорн такий шанований серед мисливців-тауренів?",a="Голт усе життя випробовував себе в сутичках із найлютішими звірами Азероту, керуючи кількома могутніми супутниками й зберігаючи глибокий духовний зв'язок із Земною Матір'ю. Завдяки своїй мудрості він головний наставник молодих мисливців-шу'гало в Тандер Блафі.",al={"переказ про голта тандергорна","хто такий голт"}},{q="Чи можна приборкати постійного вихованця, ще не здавши це завдання?",a="Уміння приборкувати диких звірів ви вже маєте після попереднього випробування, але поки не поговорите з Голтом Тандергорном, не знатимете, як годувати, оживляти чи навчати вмінь обраного супутника.",al={"чи можна приборкати вихованця зараз","коли я отримаю вихованця","чи потрібне навчання звіра"}},{q="Чому в культурі тауренів догляд за вихованцем пов'язаний із Земною Матір'ю?",a="Таурени вважають усіх живих істот дітьми Земної Матері. Мисливець не підкоряє звіра самою силою волі, а укладає з ним духовний союз: мисливець дає їжу й турботу, а тварина натомість — відданість і захист.",al={"переказ про вихованців таурена","земна матір і звірі"}}},fp="18,336,27.484.0,13.429.0,33.201.0,63.180.0,53.226.0,71.272.0,66.194.0,58.257.0"}
P.entries["quest:61"] = {n="Посилка до Стормвінда",s="«Посилка до Стормвінда» — кур'єрське завдання Альянсу, що завершує свічкову справу Вільяма Пестла в Лісі Елвінн. Зібравши великі воскові свічки в місцевих кобольдів, шукачі пригод несуть запаковану посилку дорогою до Торгового Кварталу Стормвінда — братові Вільяма, Морґану Пестлу.",h="«Посилка до Стормвінда» — кур'єрське завдання Альянсу, що завершує свічкову справу Вільяма Пестла в Лісі...",kw={"посилка до стормвінда","вільям пестл","морґан пестл","свічки","ґолдшир","торговий квартал"},ang={["faction:Alliance"]="Нести припаси королівським трактом до Стормвінда — класичний обряд посвяти для молодих героїв Альянсу, що переходять від сільських сутичок до гамірної столиці.",["profession:Herbalism"]="Родинна справа Пестлів тісно пов'язана з місцевими реагентами Елвінну, тож зазирнути до їхньої стормвіндської крамниці — звична річ і для збирачів трав, і для зіллєварів."},sec={{t="Родинна справа",b="Брати Пестли ведуть алхімічну торгівлю між сільськими селищами Лісу Елвінн і гамірними вулицями Стормвінда. Вільям збирає трави, реагенти й сировину в Ґолдширі, а його брат Морґан тримає «Аптеку Пестла» в Торговому Кварталі столиці. Вільяму нелегко покинути свій пост у Корчмі «Лев'яча Гордість», тож він покладається на мандрівників, що прямують до міської брами, аби ті побули кур'єрами."},{t="Від кобольдського воску до столичних зіль",b="У пакунку Вільяма — великі свічки, зібрані в кобольдів із копалень Елвінну. Він і Морґан тримають аптеку в Стормвінді, і Вільям каже, що збирає свічки заради воску. З доставленою посилкою ці припаси потрапляють до Морґана в Торговий Квартал."}},faq={{q="Що в посилці Вільяма?",a="У посилці — свічки, зібрані в кобольдів у Лісі Елвінн. Вільям збирав їх заради воску й запакував для Морґана в «Аптеку Пестла».",al={"вміст посилки","що в посилці","що надіслав вільям"}},{q="Де знайти Морґана Пестла?",a="Морґан Пестл працює в Аптекарні Пестла, що в Торговому Кварталі Стормвінда, за кілька кроків від головної брами.",al={"де морґан пестл","де морґан","знайти морґана пестла"}},{q="Ким доводяться одне одному Вільям і Морґан Пестл?",a="Вільям і Морґан Пестл — брати, які разом ведуть алхімічну справу. Вільям добуває матеріали в Лісі Елвінн, а Морґан порядкує в їхній крамниці в Стормвінді.",al={"брати пестли","хто брат вільяма пестла"}},{q="Чому Вільям не доставить посилку сам?",a="Вільям по вуха в торгівлі й зборі алхімічних інгредієнтів у Ґолдширі. Він воліє наймати мандрівних шукачів пригод, які й так прямують на північ, до брами столиці.",al={"чому вільям не йде до стормвінда","чому найняти гінця"}},{q="Чи справді кобольдячі свічки придатні для алхімії?",a="Вільям каже, що їм із братом свічки потрібні заради воску. Як саме віск використовують в аптеці, завдання не описує.",al={"навіщо кобольдські свічки","кобольдський віск алхімія"}},{q="Що буде після доставки посилки?",a="Ця доставка завершує короткий ланцюжок, що почався зі збору кобольдячих свічок у Лісі Елвінн. Морґан просто платить вам за кур'єрську роботу й запрошує заходити до його крамниці.",al={"що далі після посилки до стормвінда","продовження посилки до стормвінда"}}},fp="21,306,14.433.0,34.261.0,34.157.0,30.135.0,42.172.0,48.189.0,48.143.0,41.182.0"}
P.entries["quest:6101"] = {n="Приборкання звіра",s="Це випробування — другий етап навчання мисливця нічних ельфів приборкувати звірів під проводом Дазалара в Доланаарі. Мисливцям доручають упокорити зачарованим жезлом приборкання нічного шаблезуба-переслідувача, щоб краще відчути мінливе розмаїття диких звірів. Так міцніє порозуміння між дикою природою Тельдрассила й слідопитами-вартовими, що ходять під її гіллям.",h="Це випробування — другий етап навчання мисливця нічних ельфів приборкувати звірів під проводом Дазалара в...",kw={"приборкання звіра","мисливець","дазалар","нічний шаблезуб","переслідувач","доланаар"},ang={["class:Hunter"]="Цей обряд — серцевина науки мисливця: ви вчитеся поважати різні звірині вдачі, перш ніж вам довірять супутника на все життя.",["race:NightElf"]="Нічні шаблезуби глибоко вплетені в історію й культуру калдорей, тож приборкання переслідувача — традиційна віха для місцевих лісових розвідників."},sec={{t="Мінлива природа звірів",b="Перші уроки зосереджені на розумінні основних інстинктів, та Дазалар наголошує: єдина сталість природи — її безнастанна мінливість. Кожен лісовий вид має власну вдачу, і мисливець мусить навчитися відповідно підлаштовувати свою волю. У тіні крони Тельдрассила це означає мати справу зі створіннями хитрими, потайними й куди більш хижими, ніж прості павуки-прядильники."},{t="Упокорення нічного шаблезуба",b="Нічні шаблезуби шановані калдореями як священні хижаки, люті охоронці й потайні супутники Вартових. Для мисливця-новачка спрямувати силу жезла приборкання на нічного шаблезуба-переслідувача означає мати міцні нерви й спокійну владність. Обернувши хижу агресію переслідувача на прихильний зв'язок, мисливець доводить, що здатен владарювати не лише над сумирними чи меншими створіннями лісу."}},faq={{q="Навіщо це завдання?",a="Це проміжне випробування в ланцюжку мисливців нічних ельфів, що відкриває постійне приборкання звірів. Дазалар посилає вас приборкати Скрадливого Нічного Шаблезуба, щоб ви побачили, як відрізняється вдача різних хижаків.",al={"навіщо це завдання","приборкання вихованця 2","мета приборкання нічного шаблезуба"}},{q="Де водяться скрадливі нічні шаблезуби?",a="Скрадливі нічні шаблезуби никають лісовими стежками й підліском на південь від Доланаару, у центрі Тельдрассилу.",al={"де скрадливі шаблезуби","місця скрадачів","де знайти кота"}},{q="Чи залишиться скрадливий нічний шаблезуб моїм постійним вихованцем?",a="Ні. Звір, приборканий жезлом, тимчасовий і слугує лише для практики. Коли ви пройдете всі три випробування й повернете жезл, то навчитеся справжнього приборкання й зможете обрати постійного супутника.",al={"чи лишу нічного шаблезуба","чи можна лишити нічного шаблезуба","чи це мій вихованець назавжди"}},{q="Хто дає це завдання?",a="Дазалар, наставник мисливців у Доланаарі на Тельдрассилі, дає це доручення після того, як ви пройдете перше випробування з приборкання.",al={"хто дає завдання","хто починає це","де дазалар"}},{q="Чому нічні ельфи так глибоко шанують нічних шаблезубів?",a="Нічні шаблезуби тисячоліттями живуть поруч із калдореями як супутники, розвідники й бойові скакуни Вартових і жриць Елуни. Приборкати такого звіра — гордий знак калдорейської майстерності в лісовій справі.",al={"переказ про котів нічних ельфів","чому нічні шаблезуби важливі","лор про нічних шаблезубів"}},{q="Що буде після виконання цього доручення?",a="Дазалар дасть останнє завдання — приборкати ще одну істоту Тельдрассилу, — а тоді навчить природного вміння приборкувати, годувати й доглядати постійних звірів-супутників по всьому Азероту.",al={"наступне завдання","що після скрадливого шаблезуба","наступне випробування мисливця"}}},fp="16,377,29.399.0,23.418.0,34.227.0,39.105.0,60.230.0,21.140.0,48.213.0,38.180.0"}
P.entries["quest:6102"] = {n="Приборкання звіра",s="Це завдання — останнє випробування базового вишколу юного мисливця нічних ельфів. Під проводом Дазалара з Доланаара мисливці мають приборкати хижу сову небес, перш ніж здобути право обрати собі справжнього супутника на все життя.",h="Це завдання — останнє випробування базового вишколу юного мисливця нічних ельфів.",kw={"приборкання звіра","мисливець","дазалар","верескун-стригід","сова","жезл приборкання","доланаар"},ang={["class:Hunter"]="Цей обряд переходу — поріг, за яким мисливець перестає битися сам і укладає довічне партнерство з диким супутником.",["race:NightElf"]="Приборкання корінної живності Тельдрассила відображає шлях калдорей — іти в злагоді з природою, а не гнути її силою."},sec={{t="Влада над кронами",b="Перш ніж завершити початкову науку звірознавства, мисливці нічних ельфів мають досягти злагоди зі створіннями з кожного куточка екосистеми Тельдрассила. Мисливець уже довів свою волю проти звірів підліска, тож тепер Дазалар доручає йому впокорити дух небес; його ціль — Верескун-стригід. Ці пильні хижі птахи гніздяться високо в гіллі на захід від Доланаара, і щоб утихомирити їх зачарованим Жезлом Приборкання, потрібні терпіння й міцні нерви."},{t="Зв'язок мисливця",b="Успіх із Верескуном-стригідом завершує давні уроки єднання мисливців калдорей із природою. Повернувши Дазаларові спорожнілий жезл, учень лишає позаду тренувальні вправи й здобуває повне мистецтво кликати, відпускати й назавжди приборкувати обраних звірів по всьому Азероту."}},faq={{q="Де водяться Верескуни-стригіди?",a="Верескуни-стригіди гніздяться в лісах на захід від Доланаару. Мисливці мають розшукати цих хижих птахів серед крон і коріння довкола поселення, щоб випробувати свій жезл.",al={"де верескуни","де стригід верескун","де сови"}},{q="Хто такий Дазалар?",a="Дазалар — наставник мисливців нічних ельфів у Доланаарі. Він опікується молодими калдореями, які вже опанували основи стрільби з лука й вистежування, і випробовує їх на наземних і небесних звірах, перш ніж дарувати вміння поєднатися зі справжнім звіром-супутником.",al={"роль дазалара","хто навчає приборкання в доланаарі","наставник мисливців доланаар"}},{q="Чи залишиться Верескун-стригід моїм вихованцем?",a="Ні. Верескуни, приборкані під час цього випробування, — тимчасові піддослідні, яких тримає лише магія Жезла Приборкання. Коли випробування здано, жезл повертають, а мисливця вчать приборкувати в дикій природі постійного супутника на власний вибір.",al={"лишити сову","чи верескун постійний","чи лишу цього вихованця"}},{q="Що буде після цього випробування?",a="Дазалар назавжди відкриває вам уміння приборкувати, кликати й відпускати звірів. А ще він скеровує вас на подальше навчання до Дарнасуса — опанувати важливе мистецтво годувати супутника й навчати його в бою.",al={"що далі","після приборкання звіра","кінець завдання вихованця мисливця"}},{q="Чому нічні ельфи приборкують саме сов?",a="Хижі птахи, як-от сови, мають для калдореїв глибоке культурне значення: це пильні нічні мисливці й надійні розвідники. Підкоривши небесну істоту, мисливець доводить, що розуміється на повітряних хижаках так само, як і на наземних звірах.",al={"переказ про сов нічних ельфів","чому сови","чим важливий стригід верескун"}},{q="Чи можуть мисливці після цього завдання обрати будь-якого звіра?",a="Так. Щойно Дазалар навчить постійного приборкання, мисливець вільний шукати будь-якого звіра, якого можна приборкати, — на суші, у воді чи в небі, на Тельдрассилі й далеко за ним.",al={"яких вихованців я можу отримати","вибір першого вихованця","чи можна приборкати будь-якого звіра"}}},fp="16,234,21.463.0,15.320.0,35.165.0,15.244.0,49.250.0,41.205.0,42.245.0,47.160.0"}
P.entries["quest:6103"] = {n="Навчання звіра",s="«Навчання звіра» — завершальний обряд переходу для мисливців-початківців нічних ельфів у Тельдрассилі. Довівши свою майстерність приборканням диких звірів на гіллі, мисливці вирушають до Дарнасуса — вчитися глибших мистецтв догляду й дисципліни улюбленця в Джокасте.",h="«Навчання звіра» — завершальний обряд переходу для мисливців-початківців нічних ельфів у Тельдрассилі.",kw={"навчання звіра","мисливець","джокасте","дазалар","ценаріонський анклав","дарнасус"},ang={["class:Hunter"]="Цей обряд знаменує ваш випуск із новачків-слідопитів у справжні володарі звірів: ви здобуваєте змогу навчати, годувати й оживляти свого супутника.",["race:NightElf"]="Традиція калдорей товаришувати зі звірами будується на повазі й співіснуванні, відображаючи вчення, передані через Дарнасус і Ценаріонський Анклав."},sec={{t="Обряд переходу мисливця",b="Перш ніж мисливець нічних ельфів зможе блукати Калімдором із вірним супутником поруч, йому треба опанувати більше, ніж жезл приборкання. Упокорення дикого створіння доводить базову силу й волю, та ненавчений звір лишається непередбачуваним тягарем. Щойно посвячений показує свої здібності в хащах довкола Доланаара, Дазалар скеровує його вглиб, до Дарнасуса, щоб завершити навчання."},{t="Настанови в Ценаріонському Анклаві",b="У тихих гаях Ценаріонського Анклаву шанована мисливиця Джокасте передає основні мистецтва товариства зі звіром. Вона вчить молодого мисливця, як належно годувати улюбленця, воскрешати його, коли станеться лихо, і плекати його бойові інстинкти тренуванням. Для нічних ельфів ці стосунки вкорінені в глибокій шанобі до природи, а не в простому пануванні."}},faq={{q="Навіщо це завдання?",a="Це завдання завершує перший ланцюжок про вихованців для мисливців нічних ельфів. Воно скеровує вас до Дарнасуса, де ви опануєте основні вміння, потрібні, щоб доглядати й тренувати постійного звіра-супутника.",al={"навіщо це завдання","завдання навчання вихованця нічного ельфа","що дає навчання звіра"}},{q="Де знайти Джокасте?",a="Джокасте мешкає в Дарнасусі, у Ценаріонському Анклаві, що ховається серед велетенських дерев і мисливських осель у північно-західній частині столиці.",al={"де джокасте","місце джокасте","знайти джокасте"}},{q="Хто дає це завдання?",a="Дазалар, наставник мисливців у Доланаарі, пропонує це завдання, коли ви пройдете всі три етапи випробувань із приборкання на Тельдрассилі.",al={"хто дає завдання","хто дає навчання звіра","де дазалар"}},{q="Чого навчає Джокасте?",a="Розмова з Джокасте відкриває основи володіння звірами: як годувати супутника, оживляти його, якщо він полягне в бою, і навчати нових умінь.",al={"які здібності я отримаю","нагороди джокасте","закляття вихованця мисливця"}},{q="Чому нічні ельфи приділяють стільки уваги навчанню вихованців?",a="Мисливці-калдореї вважають своїх вихованців напарниками, а не слухняними знаряддями. Належне навчання й турбота віддзеркалюють головну філософію раси — жити в рівновазі з природою й у благоговінні перед нею.",al={"переказ про мисливців нічних ельфів","чому нічні ельфи навчають звірів"}},{q="Чи доступне це завдання іншим расам?",a="Саме ця подорож до Дарнасуса — лише для мисливців нічних ельфів. Мисливці інших рас проходять рівноцінні обряди навчання у власних расових наставників.",al={"чи дворфи можуть це зробити","чи орда може навчання звіра"}}},fp="18,265,26.403.0,32.383.0,34.188.0,24.149.0,21.135.0,38.161.0,50.175.0,39.151.0"}
P.entries["quest:6121"] = {n="Нові уроки",s="«Нові уроки» — завдання посвяти, яке Матренґіл Берволкер у Дарнасусі дає друїдам Альянсу, що набираються досвіду. Воно скеровує посвячуваних до священного прихистку Місячного Гаю, щоб зустрітися з Дендритом Старблейзом і почати вчитися мистецтва очищення від отрут.",h="«Нові уроки» — завдання посвяти, яке Матренґіл Берволкер у Дарнасусі дає друїдам Альянсу, що набираються...",kw={"нові уроки","матренґіл берволкер","дендрит старблейз","нічний притулок","обердайн","отрута","друїд"},ang={["class:Druid"]="Цей обряд посвяти знаменує ваш перехід від простої зміни подоби й виживання до справжньої опіки над дикою природою: ви вчитеся знімати з неї смертельні пошесті й отрути.",["faction:Alliance"]="Криза, що загрожує Обердайну, показує, наскільки важлива допомога друїдів для захисту хитких північних поселень Альянсу на Темному Узбережжі.",["race:NightElf"]="Це завдання від Ценаріонського Анклаву Дарнасуса безпосередньо пов'язує молодих калдореїв із глибшими обов'язками предків у Місячному Гаю й на Темному Узбережжі."},sec={{t="Дар Кенарія",b="Друїди мають священний зв'язок із живим світом, успадкований через учення й благословення напівбога Кенарія. Серед цих дарів — сила одним простим закляттям очищати від мерзенних отрут. Та такі могутні дари ніколи не дають посвячуваним легковажно. Щоб по-справжньому шанувати дивовижну легкість свого чародійства, молоді друїди мусять спершу зрозуміти, якої виснажливої буденної праці вимагає боротьба з отрутами без прямого втручання природи."},{t="Виклик до Нічного Притулку",b="Матренґіл Берволкер, наставник друїдів у Ценаріонському Анклаві Дарнасуса, велить учневі не вправлятися на місці, а вирушити просто до Місячного Гаю. Там, у тихому селищі Нічний Притулок, Дендрит Старблейз керує ширшими справами Кола Кенарія й готовий доручити новачкові нагальне практичне завдання."},{t="Справжня криза",b="Прибувши до Нічного Притулку, посвячувані дізнаються, що їхнє випробування — не влаштований іспит і не розписаний обряд. Поселення Обердайн на Темному Узбережжі потерпає від хвилі отруєнь тварин, яку місцеві не в змозі зупинити. Дендрит Старблейз доручає новачкові розібратися й допомогти Темному Узбережжю — і кидає його просто в справжню кризу, де на кону життя."}},faq={{q="Хто дає завдання «Нові уроки»?",a="Завдання дає Матренґіл Берволкер, наставник друїдів нічних ельфів у Ценаріонському Анклаві в Дарнасусі.",al={"хто дає нові уроки","хто видає нові уроки","завдання матренґіла берволкера"}},{q="Куди треба вирушити, щоб виконати це завдання?",a="Вам треба дістатися священного друїдського краю — Місячного Гаю — і доповісти Дендритові Старблейзу, який перебуває в мирному поселенні Нічний Притулок.",al={"куди йти","де дендрит старблейз","здати нові уроки"}},{q="Чому друїди спершу мусять навчитися лікувати отруєння, як звичайні люди?",a="Наставники-друїди вважають, що дивовижний дар Кенарія — зцілювати від отрути простим заклинанням — може породити самовдоволення. Змушуючи учнів спершу долати отруєння травами й буденними засобами, вони дбають, щоб друїд по-справжньому шанував тягар і страждання, яких завдає отрута.",al={"чому друїди як звичайні люди","чому лікувати отруєння без магії","урок кенарія про отруту"}},{q="Що за біда в Обердайні?",a="Обердайн потерпає від спалаху тяжких отруєнь тварин на всьому узбережжі Темного Узбережжя. Місцеві нічні ельфи не змогли зцілити цю недугу, тож надіслали прохання про допомогу до Кола Кенарія в Місячному Гаю.",al={"отруєння в оберіжині","що відбувається в оберіжині","отруєння тварин темного узбережжя"}},{q="Якого вміння зрештою навчає цей ланцюжок завдань?",a="Це завдання відкриває ланцюжок «Влада над отрутою», що навчає друїдів важливого заклинання «Зцілення від отрути», яке дає змогу магією очищати союзників від токсинів.",al={"яку нагороду я отримаю","завдання зцілення від отрути","ланцюжок влади над отрутою"}},{q="Чи доступне це завдання друїдам Орди?",a="Ні. «Нові уроки» — це саме альянсівська версія завдання, що починається в Дарнасусі. Друїди-таурени отримують схоже завдання в Тандер Блафі, яке так само скеровує їх до Місячного Гаю вчитися зцілювати від отрути.",al={"нові уроки орда","чи таурени можуть це взяти","нові уроки таурен"}}},fp="12,273,20.462.0,21.348.0,19.409.1,34.120.0,45.147.0,58.296.0,42.236.0,52.157.0,40.227.0"}
P.entries["quest:6122"] = {n="Головне джерело",s="«Головне джерело» — важливий обряд посвяти для молодих друїдів із нічних ельфів, що вчаться розуміти й зцілювати природу. Новачки, яких Дендрит Старблейз посилає з Місячного Гаю, мусять набрати отруєної води біля Водоспаду Скельного Джерела на Темному Узбережжі, щоб допомогти Аланндаріан Найтсонг, натуралістці з Обердайна, зупинити хворобу, що шириться серед лісових оленів.",h="«Головне джерело» — важливий обряд посвяти для молодих друїдів із нічних ельфів, що вчаться розуміти й...",kw={"головне джерело","водоспад скельного джерела","дендрит старблейз","аланндаріан найтсонг","коло кенарія","наги"},ang={["class:Druid"]="Це завдання — частина основоположного друїдського випробування. Зіткнувшись із занепадом природи біля Водоспаду Скельного Джерела й готуючи ліки, ви пробуджуєте духовні й рослинні знання, потрібні, щоб зцілювати отруєння в дикій природі.",["race:NightElf"]="Для калдореїв Обердайна отруєння Водоспаду Скельного Джерела — пряма наруга над лісами предків, що вимагає негайного втручання, аби вберегти невинних створінь краю."},sec={{t="Отруєна життєва артерія",b="Водоспад Скельного Джерела — головне джерело прісної води на півночі Темного Узбережжя. Коли звірі — передусім місцеві олені — почали піддаватися протиприродній, затяжній недузі, Коло Кенарія звернуло увагу на річку. Підозрюючи, що отруєно самі підземні води, Дендрит Старблейз у Місячному Гаю доручає молодим друїдам важливе завдання: дістатися входу до печери під водоспадом і набрати непошкоджену пробу отруєної води."},{t="Тіні біля водоспаду",b="Набрати воду — справа небезпечна. Люті наги облаштувалися в Печері Річки Скельного Джерела й гніздяться біля самих верхів'їв водоспаду. Їхня присутність довкола підземного джерела — пряма загроза кожному, хто розслідує пошесть. Попри небезпеку, лише здобувши незабруднену пробу біля входу до печери, Коло Кенарія зможе дослідити те, що нівечить дику природу."},{t="Глибша недуга",b="Коли пробу приносять Аланндаріан Найтсонг в Обердайн, смердюча вода підтверджує найгірші побоювання Кола. Та дослідження мерзенної рідини відкриває тривожну правду: хоча отруєний водоспад справді головний провідник, що отруює береги річки, уражених оленів бачили далеко за його прямою течією. Вода стає важливим реагентом, щоб почати готувати протиотруту, але Аланндаріан підозрює, що глибша, ширша порча шириться всіма підземними водами Темного Узбережжя."}},faq={{q="Чому Водоспад Скельного Джерела такий важливий для Темного Узбережжя?",a="Водоспад Скельного Джерела — головне природне джерело питної води для півночі Темного Узбережжя. Він живить місцеві струмки, річки, рослини й тварин довкола, тож будь-яка отрута, що потрапить у його витоки, швидко розходиться по всій місцевій природі.",al={"чому важливий водоспад скельного джерела","значення річки скельного джерела","водне джерело темного узбережжя"}},{q="Чому хворіють олені на Темному Узбережжі?",a="Місцеві олені п'ють просто з Водоспаду Скельного Джерела й струмків, які він живить. Якась згубна отрута забруднила воду біля самого джерела, і лісові звірі потерпають від тяжкої виснажливої хвороби.",al={"чому олені хворі","хворі олені темного узбережжя","що отруїло оленів"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — старший наставник друїдів, що живе у священному притулку Місячного Гаю. Він веде друїдів, які здобувають нові щаблі майстерності, стежить за негараздами по всьому Калімдору й спрямовує дії Кола Кенарія, коли природу спіткає лихо.",al={"переказ про дендрита старблейза","хто дав завдання","старблейз місячний гай"}},{q="Хто така Аланндаріан Найтсонг?",a="Аланндаріан Найтсонг — дослідниця природи з нічних ельфів, що перебуває в Обердайні. Стривожена поширенням скверни й стражданнями тварин на Темному Узбережжі, вона звернулася до Кола Кенарія в Місячному Гаю по досвідчену допомогу, щоб дослідити недугу й знайти ліки.",al={"хто така аланндаріан","аланндаріан найтсонг оберіжин"}},{q="Що наги роблять біля Водоспаду Скельного Джерела?",a="Наги з прибережних вод Темного Узбережжя просунулися вглиб суходолу й захопили печери за Водоспадом Скельного Джерела. Через них дістатися до витоків і дослідити воду вкрай небезпечно.",al={"наги біля скельного джерела","чому тут наги","наги водоспаду скельного джерела"}},{q="Якого вміння допомагає навчитися це завдання?",a="Це розслідування — частина випробування «Влада над отрутою». Розпізнавши цю пошесть серед тварин і разом з Аланндаріан Найтсонг виготовивши протиотруту, учні-друїди опановують важливе магічне мистецтво зцілення від отрути.",al={"яке закляття дає це завдання","завдання друїда про отруту","ланцюжок зцілення від отрути"}}},fp="20,354,26.501.0,20.422.0,15.507.1,51.280.0,42.223.0,26.234.0,29.262.0,34.233.0,47.220.0"}
P.entries["quest:6125"] = {n="Влада над отрутою",s="«Влада над отрутою» — завершення випробування, у якому молодий друїд опановує боротьбу з отруєннями. Навчившись власноруч варити трав'яні ліки на Темному Узбережжі, посвячуваний повертається до Дарнасуса, щоб отримати магічне благословення Кола Кенарія й очищати від отрут за власним бажанням.",h="«Влада над отрутою» — завершення випробування, у якому молодий друїд опановує боротьбу з отруєннями.",kw={"влада над отрутою","аланндаріан найтсонг","місячний гриб","земнокорінь","обердайн","очищення","друїд"},ang={["class:Druid"]="Цей обряд посвяти поєднує скромне травництво зі священною цілющою магією й позначає мить, коли друїд отримує силу благодаттю природи знешкоджувати отруту.",["race:NightElf"]="Це випробування в Ценаріонському Анклаві Дарнасуса віддзеркалює шанування рівноваги в калдореїв і їхню урочисту опіку над прадавніми лісами."},sec={{t="Покора учня",b="Перш ніж дати друїдові вроджену магічну здатність очищати від отрут, Коло Кенарія вимагає, щоб посвячувані зрозуміли страждання простого люду. На Темному Узбережжі Аланндаріан Найтсонг доручає молодим друїдам власноруч зібрати Земнокорінь і Місячний Гриб і зварити мазь, щоб зцілити уражених звірів. Цей урок гарантує, що, коли друїд спрямовує силу природи на лікування отруєння, він робить це з глибоким співчуттям до тих, хто мусить боротися з отрутою без допомоги духів."},{t="Повернення до Анклаву",b="Щойно ліки довели свою дієвість в Обердайні, Старблейз відсилає друїда назад через море до Дарнасуса. У гіллі Ценаріонського Анклаву на нього чекає Матренґіл Берволкер. Задоволений тим, як гідно посвячуваний тримався під тиском, Матренґіл урочисто передає йому мистецтво природного очищення й назавжди дарує владу над отрутами. Та випробування приносить і тривожні вісті: сильні отрути в диких землях довкола Обердайна вказують на неприродну пошесть, що порушує тонку рівновагу краю."}},faq={{q="Навіщо це завдання?",a="Це завдання завершує друїдське випробування зі зцілення від отрут. Успішно приготувавши для Дендрита Старблейза в Місячному Гаю й на Темному Узбережжі цілющу суміш, учень повертається до Матренґіла Берволкера в Дарнасусі, щоб навчитися магічного заклинання «Зцілення від отрути».",al={"навіщо влада над отрутою","мета влади над отрутою","завдання зцілення від отрути"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — старший друїд, що перебуває у священному Нічному Притулку в Місячному Гаю. Він веде учнів через духовні випробування, перевіряючи їхнє терпіння й відданість природі, перш ніж відправити назад до власних наставників.",al={"роль дендрита старблейза","хто дає владу над отрутою"}},{q="Хто такий Матренґіл Берволкер?",a="Матренґіл Берволкер — майстер-наставник друїдів у Ценаріонському Анклаві в Дарнасусі. Він опікується зростанням друїдів нічних ельфів серед гілля Тельдрассилу, навчаючи їх подоб, цілющих мистецтв та урочистих обов'язків Кола Кенарія.",al={"переказ про матренґіла берволкера","берволкер дарнасус"}},{q="Чому друїд мусив спершу приготувати ліки власноруч?",a="Дендрит Старблейз навчає, що друїд має розуміти, як отрута виснажує тіло і скільки праці потрібно, щоб вилікувати її без магії. Збираючи звичайні інгредієнти й власноруч допомагаючи хворим, учень вчиться смирення й уміння цінувати дари природи, які ось-ось отримає.",al={"чому готувати трав'яні ліки","урок влади над отрутою"}},{q="Що непокоїть Матренґіла в подіях довкола Обердайна?",a="Матренґіл зауважує, що раптова поява смертельних отрут у дикій природі Темного Узбережжя довкола Обердайна — річ неприродна. Негаразди з місцевими тваринами й рослинами загрожують рівновазі природи й наводять на думку, що на туманному узбережжі діє якась згубна сила.",al={"переказ про отруєння оберіжина","що непокоїть матренґіла"}}},fp="17,269,22.487.0,21.526.0,34.268.0,26.243.0,29.255.0,56.291.0,58.255.0"}
P.entries["quest:6126"] = {n="Нові уроки",s="«Нові уроки» — обряд посвяти для юних друїдів-тауренів, який розпочинає Турак Рунтотем на Узвишші Старійшин у Тандер Блафі. Він скеровує учнів до священного прихистку Місячного Гаю, щоб почати опановувати мистецтво очищення від природних і неприродних отрут. Під проводом нічного ельфа Дендрита Старблейза цей урок замість умовних випробувань ставить учня перед справжньою нагальною бідою — отруєнням.",h="«Нові уроки» — обряд посвяти для юних друїдів-тауренів, який розпочинає Турак Рунтотем на Узвишші Старійшин у...",kw={"нові уроки","друїд","отрута","турак рунтотем","дендрит старблейз","нічний притулок","місячний гай","перехрестя"},ang={["class:Druid"]="Це завдання знаменує ваш перехід від простого перевтілення й сутичок до справжньої опіки над дикою природою й відкриває шлях до опанування заклинання «Зцілення від отрути».",["faction:Horde"]="Поки воїни Орди б'ються з нічними ельфами в Ашенвалі, друїди Орди знаходять безпечний прихисток у Місячному Гаю під священною опікою Кола Кенарія.",["race:Tauren"]="Для тауренів ця мандрівка показує, наскільки глибоко діти Земної Матері відновили зв'язок із ученням Кенарія пліч-о-пліч зі своїми побратимами — нічними ельфами."},sec={{t="Дар Кенарія",b="Друїди мають священний обов'язок оберігати дику природу, і серед іншого Кенарій дарував їм дивовижну здатність одним заклинанням очищати від лютих отрут. Проте таку могутню магію не вручають без належного підґрунтя. Турак Рунтотем наполягає: перш ніж спрямовувати божественну енергію, щоб без зусиль розвіювати пошесті, друїд має зрозуміти, як отрута вражає тіло, і навчитися лікувати її звичайними, земними засобами."},{t="Поклик до Нічного Притулку",b="Здібних послушників не навчають лише на кручах Малгору — їх відсилають на північ священними стежками до Місячного Гаю. Там, у мирному селищі Нічний Притулок, прадавні наставники з нічних ельфів, як-от Дендрит Старблейз, опікуються навчанням і ельфів, і тауренів. Це спільне навчання підкреслює тонке перемир'я, що панує в Колі Кенарія, піднімаючись над політичними чварами, які розділяють Орду й Альянс."},{t="Справжня біда в Пустках",b="Колишні учні відпрацьовували обряди очищення в умовах, що їх контролювали наставники, але Старблейз не має часу на вигадані вправи. Біля Перехрестя в посушливих Пустках спалахнула нестримна хвиля отруєнь звірів. Розпачливе прохання про допомогу з Перехрестя перетворює навчальний обряд посвяти на нагальне польове доручення, і юні друїди мають безпосередньо зіткнутися зі стражданнями диких звірів."}},faq={{q="Хто дає це завдання і де його знайти?",a="Завдання дає Турак Рунтотем, наставник друїдів-тауренів на Узвишші Старійшин у Тандер Блафі. Він кличе учнів, які вже довели свою відданість ученню Кенарія.",al={"хто дає нові уроки","де взяти нові уроки","видавець нових уроків"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — старший друїд нічних ельфів, що живе в Нічному Притулку в Місячному Гаю. Попри ширшу ворожнечу між нічними ельфами й тауренами, він наставляє молодих друїдів обох рас у традиціях Кола Кенарія.",al={"хто такий дендрит","роль дендрита старблейза","хто нічний ельф у місячному гаю"}},{q="Якої сили навчає мене це завдання?",a="Цей ланцюжок завдань розпочинає ваше навчання «Зцілення від отрути». Він учить друїдів розуміти фізичну й магічну природу отрути, щоб очищати від шкідливих недуг союзників і диких істот, про яких вони дбають.",al={"якої здібності я навчуся","яке закляття для цього","завдання лікування отрути"}},{q="Чому таурен має вчитися в нічного ельфа?",a="Коло Кенарія — нейтральне братство, віддане рівновазі природи. Хоча саме нічні ельфи першими впорядкували сучасне друїдство під проводом Кенарія, вони знову прийняли тауренів до ордену й ділять із ними священні місця на кшталт Місячного Гаю, попри війну фракцій.",al={"чому таурен вчиться в нічного ельфа","нічні ельфи таурени друїди","фракція кола кенарія"}},{q="Що діється на Перехресті?",a="Тварин довкола Перехрестя в Пустках косить хвиля тяжких отруєнь, яку місцеві доглядачі не можуть зупинити. Дендрит Старблейз переносить ваше навчання просто в поле: треба знайти джерело біди й виготовити ліки.",al={"проблема перехрестя","що отруює тварин","хвороба перехрестя"}},{q="Як найшвидше дістатися до Місячного Гаю для цього завдання?",a="Як друїд, ви маєте власне заклинання «Телепортація: Місячний Гай», що переносить вас просто до святилища Нічного Притулку, — не треба йти пішки через небезпечні спірні землі.",al={"як дістатися місячного гаю","дорога до нічного притулку","телепорт у місячний гай"}}},fp="12,403,20.427.0,21.458.0,28.418.1,47.199.0,26.236.0,37.234.0,50.276.0,36.257.0,59.191.0"}
P.entries["quest:6127"] = {n="Головне джерело",s="«Головне джерело» — завдання для друїдів Орди, яке дає Дендрит Старблейз у Місячному Гаю. Воно посилає друїдів-новачків на Пік Жахливої Імли на півночі Пусток, щоб набрати зразок отруєної води зі ставка й принести його на Перехрестя, де чекає Тонга Рунтотем. Зразок дає основу, щоб зрозуміти отруту, яка шириться серед місцевої звірини.",h="«Головне джерело» — завдання для друїдів Орди, яке дає Дендрит Старблейз у Місячному Гаю.",kw={"головне джерело","дендрит старблейз","пік жахливої імли","тонга рунтотем","палаючий клинок","друїд"},ang={["class:Druid"]="Цей обряд посвяти — важливий крок на вашому шляху захисника дикої природи: він доводить, що ви вмієте простежити скверну до її джерела й відокремити магічні отрути, перш ніж вони знищать цілий край.",["faction:Horde"]="Перехрестя — серце постачання Орди в Калімдорі, тож неприборкане поширення демонічної пошесті просто в нього під боком — пряма загроза торгівлі й виживанню.",["race:Tauren"]="Пустки — родові землі племен Калімдору; очищення води захищає від демонічної скверни стада газелей, що поколіннями годували ваш народ."},sec={{t="Отруєна гора",b="Пік Жахливої Імли височіє на північний захід від Перехрестя — так високо, що його гірські джерела й ставки впливають на погоду й природну вологу посушливих північних Пусток. На жаль, на його скелях отаборилися демонопоклонники з Палаючого Клинка. Дендрит Старблейз розуміє: мерзенне чаклунство на такій важливій природній висоті може отруїти всю довколишню улоговину."},{t="Пошесть на рівнинах",b="На північній савані бачили хворих газелей, що, спотикаючись, бредуть на північ від головного шляху зі сходу на захід через Перехрестя. Тонга Рунтотем, шукаючи допомоги для місцевих тауренів, звернувся до Кола Кенарія, щоб з'ясувати, що отруює стадо. Вирушивши на пік і здобувши чистий зразок отруєної води, друїди передають у руки Тонги важливий каталізатор, потрібний, щоб дослідити недугу й зварити протиотруту."}},faq={{q="Де взяти пробу води для цього завдання?",a="Воду треба набрати з водойми на самій вершині Піку Жахливої Імли, на північний захід від Перехрестя в Пустках. Дістаньтеся до озерця на вершині, де збираються сектанти Палаючого Клинка, і наберіть води в посудину для проб, яку дав Дендрит Старблейз.",al={"де пробу води","де озерце піку жахливої імли","головне джерело зразок води"}},{q="Чому вода на Піку Жахливої Імли така важлива для Пусток?",a="На висоті Піку Жахливої Імли лежать водойми, що безпосередньо впливають на місцеву погоду й тумани. Коли демонічні сектанти оскверняють ці води, отруйні випари й стоки спливають униз і псують рівнини, а звірі по всій півночі Пусток хворіють.",al={"чому важливий пік жахливої імли","погодне озерце пусток","озерця піку жахливої імли"}},{q="Хто такий Тонга Рунтотем?",a="Тонга Рунтотем — друїд-таурен на Перехресті в Пустках. Глибоко стривожений неприродними недугами, що ширяться серед місцевих газелей, він звернувся до Кола Кенарія в Місячному Гаю по допомогу, щоб розпізнати хворобу й очистити землю.",al={"хто такий тонга","роль тонги рунтотема","друїд перехрестя"}},{q="Хто отруює воду на вершині?",a="Води осквернив Палаючий Клинок — темний культ чорнокнижників-демонопоклонників і прислужників скверни, що захопили звивисті стежки й вершину Піку Жахливої Імли.",al={"хто отруїв воду","сектанти жахливої імли","палаючий клинок жахлива імла"}},{q="Якого вміння навчає цей ланцюжок?",a="Це доручення — частина ширшого обряду «Влада над отрутою» для молодих друїдів Орди, що завершується опануванням духовних і трав'яних знань, потрібних, щоб зцілювати від отрут у польових умовах.",al={"нагорода влади над отрутою","закляття друїда проти отрути","завдання зцілення від отрути пустки"}},{q="Чи можуть друїди Альянсу виконати це завдання?",a="Ні. «Головне джерело» — це саме ординська версія випробування, яка відправляє гравців у Пустки до Тонги Рунтотема. Друїди Альянсу проходять рівноцінний шлях на Темному Узбережжі, щоб здобути вміння очищати від отрут.",al={"аналог для альянсу","чи нічні ельфи можуть головне джерело","завдання альянсу про отруту"}}},fp="20,346,18.429.0,22.428.0,47.253.0,63.265.0,23.253.0,40.184.0,46.185.0,34.232.0"}
P.entries["quest:6128"] = {n="Збір ліків",s="«Збір ліків» — священний обряд посвяти для молодих тауренських друїдів на Перехресті. За дорученням Тонги Рунтотема друїд збирає земнокорінь і міцні роги кодо, щоб приготувати цілющу мазь для отруєних газелей Пусток.",h="«Збір ліків» — священний обряд посвяти для молодих тауренських друїдів на Перехресті.",kw={"збір ліків","тонга рунтотем","земнокорінь","роги кодо","газелі","друїд"},ang={["class:Druid"]="Це доручення — частина важливих випробувань, у яких друїди вчаться виходити за межі смертного травництва й спрямовувати магію природи, щоб напряму очищати від отрут.",["faction:Horde"]="Виконуючи доручення Тонги, ви захищаєте звірину довкола Перехрестя й бережете рівновагу природи навколо цієї серцевинної застави Орди.",["profession:Herbalism"]="Завдання тримається на земляному корені й підкреслює незмінну цінність диких лікувальних коренів, які збирають на кам'янистих схилах савани."},sec={{t="Рецепт полегшення",b="Здобувши зразок води з Піка Жахливої Імли, Тонга Рунтотем потребує сирих реагентів, щоб зварити дієву протиотруту. Природна вода — основа мазі, звичайний земнокорінь дає їй головні цілющі властивості, а мелений ріг кодо — відновну силу, потрібну, щоб вибити отруту з тіла істоти. Для молодого друїда здобути ці складники означає покластися на дари землі й проредити місцевих звірів."},{t="Уроки очищення",b="Алхімія й знання трав — традиційні способи протидіяти окремим отрутам, але кожна отрута зазвичай вимагає точних, особливих ліків. Тонга використовує це клопітке приготування, щоб показати новачкам межі тілесних ліків. Справжня влада над природними отрутами приходить не від нескінченних запасів сушених трав і рогів у торбі, а від прямого налаштування на цілющі енергії природи — глибокий урок, що веде прямо до друїдського мистецтва Зцілення від отрути."}},faq={{q="Які інгредієнти просить Тонга Рунтотем?",a="Тонга просить п'ять пучків земнокореня й п'ять цілих рогів кодо. Земнокорінь дає цілющі властивості трав, а роги — ту життєву силу, що потрібна, аби перебороти отруту, яка вразила місцевих газелей.",al={"предмети збору ліків","які інгредієнти потрібні","матеріали ліків"}},{q="Де знайти роги кодо?",a="Кодо блукають посушливими рівнинами північних і центральних Пусток і часто пасуться біля доріг довкола Перехрестя. Тонга наголошує, що для мазі згодяться лише цілі, міцні роги цих звірів, а не крихкі уламки.",al={"де кодо","де роги кодо","знайти кодо в пустках"}},{q="Чи треба бути травником, щоб добути земнокорінь?",a="Ні, самому володіти травництвом не обов'язково. Травники збирають земнокорінь на кручах і скелястих виступах по всіх Пустках, а друїди, які не вміють його збирати, можуть роздобути його в інших мандрівників або на торгових пунктах.",al={"чи потрібне травництво","земнокорінь без травництва","вимога професії для земнокореня"}},{q="Навіщо Тонга готує звичайну мазь?",a="Тонга готує звичайну протиотруту, щоб лікувати отруєних газелей, які страждають по всій півночі Пусток. А ще цей клопітний процес виготовлення ліків на кожен окремий випадок показує, наскільки вигідніше опанувати природні магічні заклинання очищення.",al={"навіщо протиотрута","мета мазі","чому не магія"}},{q="Хто такий Тонга Рунтотем?",a="Тонга Рунтотем — старший друїд-таурен на Перехресті в Пустках. Він досліджує скверну, що розходиться водами краю, і вчить молодих друїдів берегти рівновагу природи.",al={"хто дає збір ліків","роль тонги рунтотема","хто такий тонга"}},{q="Що буде після збору інгредієнтів?",a="Коли Тонга зварить із реагентів цілющу мазь, він відправить друїда в савану, щоб той намастив нею хворих газелей і випробував ліки, а тоді навчить глибшого мистецтва магічного очищення.",al={"що після збору ліків","наступне завдання після збору ліків","після збору ліків"}}},fp="18,244,19.464.0,20.467.0,46.224.0,34.236.0,49.256.0,40.267.0,23.217.0,45.223.1"}
P.entries["quest:6129"] = {n="Зцілення хворих",s="«Зцілення хворих» — важливе випробування для молодих друїдів Орди: їм доручено лікувати уражену звірину на півночі Пусток. Накладаючи свіжоприготовану трав'яну мазь хворим газелям, новачки показують і практичне польове цілительство, і відданість збереженню природної рівноваги. Виконавши цей обов'язок, вони доводять свою відданість просто Колу Кенарія в Місячному Гаю.",h="«Зцілення хворих» — важливе випробування для молодих друїдів Орди: їм доручено лікувати уражену звірину на...",kw={"зцілення хворих","газелі","тонга рунтотем","дендрит старблейз","коло кенарія","друїд"},ang={["class:Druid"]="Цей обряд зцілення знаменує ваш перехід від учня травництва до діяльного охоронця природи й доводить, що ви готові спрямовувати магію життя проти смертельних отрут.",["faction:Horde"]="Лікуючи уражену звірину біля Перехрестя, тауренські друїди допомагають уберегти важливі мисливські угіддя й шляхи, на яких тримаються позиції Орди в центральному Калімдорі.",["race:Tauren"]="Коли ваш народ відновлює давні зв'язки з Колом Кенарія, зцілення Пусток доводить, що діти Земної Матері — гідні охоронці рівноваги."},sec={{t="Мор на стада",b="На північній савані Пусток газелі на пасовищах почали падати від неприродної недуги. Зібравши земнокорінь і роги кодо для цілющих ліків, Тонга Рунтотем на Перехресті доручає молодому друїдові провести лікування просто в полі. Новачок мусить вирушити на північ від головного перехрестя, знайти десять хворих тварин і допомогти їм, перш ніж гниль глибше пустить коріння в довкіллі."},{t="Благословення Кола",b="Коли мазь розділено, шлях друїда веде назад під тихе гілля Місячного Гаю. Там Дендрит Старблейз визнає співчуття й пильність новачка. Він зауважує, що страждання газелей — лише ознака глибшої, підступної скверни, що підкрадається до дикої природи Калімдору. Доглядаючи найменших звірів, тауренські друїди показують, що шана до Кенарія стоїть понад племінними межами, і здобувають глибші таємниці очищення від отрут і магії природи."}},faq={{q="Де знайти хворих газелей?",a="Хворі газелі блукають посушливими рівнинами північних Пусток, здебільшого на північ від головного торгового шляху зі сходу на захід, що перетинає Перехрестя.",al={"де хворі газелі","місця газелей","газелі пусток"}},{q="Хто дає це завдання?",a="Тонга Рунтотем, друїд-таурен на Перехресті в Пустках, дає це завдання й видає Цілющу Мазь для Тварин, коли ви виконаєте його доручення зі збору реагентів.",al={"хто дає зцілення хворих","хто дає завдання","де тонга рунтотем"}},{q="Кому доповісти, вилікувавши тварин?",a="Завдання здають Дендритові Старблейзу в друїдському святилищі Місячного Гаю — до священного гаю ви дістанетеся телепортацією.",al={"де здати","здати завдання","де дендрит старблейз"}},{q="Чому Колу Кенарія не байдужі Пустки?",a="Коло Кенарія стежить за гармонією землі. Хвороба, що шириться серед диких газелей, — відгомін усеосяжної скверни, яка повзе Калімдором і, якщо її не зупинити, може розхитати природний лад.",al={"чому друїди піклуються про пустки","коло кенарія пустки"}},{q="Яке вміння відкриває цей ланцюжок завдань?",a="Це випробування — друга половина друїдського обряду посвяти, що зрештою дає учневі вміння очищати від отрут і токсинів себе й союзників.",al={"нагорода зцілення від отрути","навіщо це завдання друїду"}},{q="Чи можуть вилікувати газелей не друїди?",a="Ні. Цей ланцюжок завдань — лише для друїдів: це окреме класове випробування під наглядом самого Кола Кенарія.",al={"чи це лише для друїдів","хто може зцілення хворих"}}},fp="15,397,23.459.0,21.483.0,36.158.0,22.180.0,44.140.0,53.218.0,42.180.0,35.122.0"}
P.entries["quest:6130"] = {n="Влада над отрутою",s="«Влада над отрутою» — завершальний обряд у випробуванні юного друїда Орди, що опановує цілющу магію природи. Вилікувавши уражених газелей довкола Перехрестя самими лише трав'яними сумішами, учень повертається до Турака Рунтотема на Узвишшя Старійшин у Тандер Блафі, щоб отримати справжній дар — «Зцілення від отрути».",h="«Влада над отрутою» — завершальний обряд у випробуванні юного друїда Орди, що опановує цілющу магію природи.",kw={"влада над отрутою","друїд","Зцілення від отрути","турак рунтотем","тонга рунтотем","перехрестя","газелі"},ang={["class:Druid"]="Цей обряд посвяти поєднує звичайне травництво Калімдору з вродженою магією природи й назавжди дарує друїдам змогу очищати союзників від отрут.",["faction:Horde"]="Випробування довкола Перехрестя показують, що Орда відіграє дедалі більшу роль в охороні диких просторів центрального Калімдору від неприродної скверни.",["race:Tauren"]="Для учнів-тауренів виконання цього завдання доводить їхню відданість Колу Кенарія й підтримує живою мудрість Земної Матері на Узвишші Старійшин."},sec={{t="Урок страждання",b="Перш ніж дати молодому друїдові вроджену магічну силу очищати від отрут, Коло Кенарія вимагає, щоб він зрозумів, що таке недуга насправді. Дендрит Старблейз відіслав новачка на Перехрестя, де Тонга Рунтотем доручив йому зібрати земні складники для цілющої мазі, приготованої власноруч. Лише лікуючи отруєних газелей Пусток без допомоги духів, учень бачить, як мучаться звичайні створіння в боротьбі з природними й неприродними отрутами."},{t="Повернення на Узвишшя Старійшин",b="Коли випробування завершено, Дендрит відсилає учня назад до Турака Рунтотема — великого наставника друїдів, що живе на Узвишші Старійшин у Тандер Блафі. Турак зауважує, що дивні люті отрути, які з'являються біля Перехрестя, загрожують природній рівновазі рівнин і викликають серйозне занепокоєння. Похваливши учня за витримку під тиском, Турак назавжди передає йому духовне мистецтво зцілення від отрут і доручає берегти живих істот Калімдору."}},faq={{q="Навіщо це завдання?",a="Це завдання завершує випробування друїдів Орди зі зцілення від отрут. Показавши дисципліну й урятувавши страждальних газелей звичайними ліками, учень повертається до Турака Рунтотема, щоб опанувати заклинання «Зцілення від отрути» через друїдське єднання з природою.",al={"навіщо влада над отрутою","що робить це завдання","мета завдання друїда про отруту"}},{q="Де знайти Турака Рунтотема?",a="Турак Рунтотем живе на Узвишші Старійшин у Тандер Блафі — серед наметів і видовбаних гнізд, де друїди-таурени єднаються з природою й навчаються.",al={"де турак рунтотем","де турак","знайти турака рунтотема"}},{q="Хто відправляє друїда назад до Тандер Блафа?",a="Дендрит Старблейз, друїд нічних ельфів із Кола Кенарія, що перебуває у священному притулку Місячного Гаю, відправляє учня назад до наставника, коли той успішно вилікує тварин біля Перехрестя.",al={"хто дає владу над отрутою","видавець завдання","дендрит старблейз"}},{q="Чому Коло Кенарія змусило друїда спершу лікувати звірів власноруч?",a="Дендрит Старблейз наголошує: перш ніж володіти легкою духовною магією, друїд має зрозуміти, що означає лікувати отруту самою працею, у межах смертних можливостей. Відчувши біду вражених істот, учень навчається співчуття й поваги до рівноваги природи.",al={"чому лікувати вручну","чому спершу мазі","урок друїда про отруту"}},{q="Що непокоїть Турака Рунтотема в подіях на Перехресті?",a="Турак глибоко стривожений тим, що тварин Пусток довкола Перехрестя отруюють неприродні, агресивні отрути. Він вважає таке забруднення тяжким порушенням рівноваги землі, яке вимагає пильності й надалі.",al={"турак і перехрестя","перехрестя отрута рівновага"}},{q="Чи доступне це завдання друїдам Альянсу?",a="Друїди Альянсу проходять схоже випробування з тією самою назвою. Тільки замість Турака Рунтотема на Узвишші Старійшин учні з нічних ельфів завершують урок у Матренґіла Берволкера в Дарнасусі.",al={"чи нічні ельфи можуть це взяти","влада над отрутою альянс"}}},fp="17,300,21.494.0,24.465.0,34.271.0,33.158.0,42.206.0,70.273.0,51.234.0,43.215.0"}
P.entries["quest:6181"] = {n="Спішне послання",s="Інтендантові Льюїсу в Сентінел Гіллі терміново потрібні обладунки зі Стормвінда, щоб спорядити Народне ополчення. Вестфол майже не отримує офіційної військової допомоги, тож він відправляє вас до майстра грифонів Тора — доставити термінову заявку до столиці повітрям.",h="Інтендантові Льюїсу в Сентінел Гіллі терміново потрібні обладунки зі Стормвінда, щоб спорядити Народне...",kw={"спішне послання","інтендант льюїс","тор","осрік стренг","грифон","сентінел гілл"},ang={["faction:Alliance"]="Доручення оголює глибокий розрив у постачанні між величною столицею Стормвінда та її знесиленими прикордонними заставами у Вестфолі.",["race:Human"]="Для людей королівства записка Льюїса показує, в якому тяжкому стані провінції Стормвінда, і знайомить із важливими грифоновими шляхами, що пов'язують рідні землі."},sec={{t="Благання через небеса",b="Сентінел Гілл стоїть самотою проти дедалі більшої хвилі розбійників Дефіасу й гнолів, позбавлений прямої військової допомоги від Стормвінда. Інтендант Льюїс покладається на приватні зв'язки в столиці, щоб Народне ополчення мало зброю й обладунки. Спорядження дедалі менше, і його єдина рятівна ниточка — Осрік Стренг, бронник зі Старого Міста. Щоб термінова заявка швидко дійшла до нього, Льюїс просить мандрівників звернутися до майстра грифонів Вестфолу — Тора."},{t="Мережа польотів",b="Грифони дають Королівству Стормвінд неоціненну мережу швидкого сполучення й кур'єрського зв'язку. Тор, що облаштувався в Сентінел Гіллі, опікується повітряним сполученням застави зі столицею. Записка Льюїса, передана Торові, відкриває небесний шлях між Вестфолом і королівським містом і показує, наскільки важливі вершники грифонів для прикордонних гарнізонів, відрізаних від офіційної допомоги."}},faq={{q="Навіщо Інтендантові Льюїсу надсилати записку до Стормвінда?",a="Вестфол майже не отримує військової допомоги від уряду Стормвінда, і Народному ополченню катастрофічно бракує обладунків. Льюїс мусить звернутися до надійного купця в місті, Осріка Стренга, щоб роздобути нове спорядження.",al={"навіщо надсилати записку","навіщо записка льюїса","чому писати до стормвінда"}},{q="Хто такий Осрік Стренг?",a="Осрік Стренг — майстер обладунків, чия крамниця «Обмежений імунітет» розташована в Старому Місті Стормвінда. Коли офіційні канали підводять, він — надійний приватний постачальник Льюїса.",al={"осрік стренг","хто такий осрік","власник обмеженої недоторканності"}},{q="Хто такий Тор?",a="Тор — розпорядник грифонів на Сентінел Гіллі. Він доглядає летючих скакунів, що з'єднують Вестфол зі Стормвіндом, і завдяки ним кур'єри й мандрівники швидко долають шлях.",al={"хто такий тор","політний майстер вестфолу","майстер грифонів тор"}},{q="Чому Стормвінд не надсилає до Вестфолу солдатів і спорядження напряму?",a="Король Варіан Рінн зник, ресурсів бракує, тож керівництво Стормвінда здебільшого занедбало віддалені фермерські землі. Прикордонним заставам на кшталт Сентінел Гілла доводиться виживати завдяки добровольчим ополченням і приватним домовленостям.",al={"чому стормвінд не допомагає","чому стормвінд ігнорує вестфол","де армія"}},{q="Чи може будь-який шукач пригод узятися за це доручення?",a="Це доручення дають саме шукачам пригод-людям, які вже проявили себе у Вестфолі; воно знайомить їх із мережею перельотів королівства на грифонах.",al={"хто може взяти це завдання","завдання лише для людей","чи дворфи можуть це завдання"}},{q="Куди веде це кур'єрське доручення далі?",a="Коли ви віддасте записку Торові, він приготує грифона до перельоту просто в Стормвінд; там ви підете до Дунґара Лонґдрінка, розпорядника грифонів столиці, а тоді розшукаєте Осріка Стренга в Старому Місті.",al={"наступний крок","що після тора","куди йти далі"}}},fp="15,269,23.481.0,18.370.0,62.223.0,20.175.0,12.161.0,67.235.0,39.172.0,42.197.0"}
P.entries["quest:62"] = {n="Копальня Фарґодіп",s="Маршал Дуґан із Ґолдшира доручає розвідникам перевірити повідомлення, що Копальню Фарґодіп захопили кобольди. Копальня лежить на південь від містечка, між фермами Стоунфілдів і Маклурів, і її падіння свідчить про дедалі більшу навалу шкідників по всьому Лісі Елвінн.",h="Маршал Дуґан із Ґолдшира доручає розвідникам перевірити повідомлення, що Копальню Фарґодіп захопили кобольди.",kw={"копальня фарґодіп","кобольди","маршал дуґан","ґолдшир","розвідка","стоунфілди","маклури"},ang={["faction:Alliance"]="Захоплена копальня — ще один виразний знак того, що влада Стормвінда в Елвінні слабне, а місцева варта ледве захищає найнеобхідніше господарство.",["profession:Mining"]="Багаті мідні жили Копальні Фарґодіп життєво важливі для ковалів-початківців, та щоб їх розробляти, доведеться прорубуватися крізь кобольдів, які бережуть свою територію."},sec={{t="Клопіт на південь від Ґолдшира",b="Поки Долина Нортширу давала раду власним шкідникам, до Ґолдшира дійшли тривожні вісті: кобольди захопили ще одне важливе місце. Копальня Фарґодіп, що притулилася між ворогуючими садибами Стоунфілдів і Маклурів на південь від містечка, колись давала королівству камінь і руду. Тепер вогкі тунелі сповнені пронизливого цвірінькання й мерехтіння лойових свічок, і Маршал Дуґан посилає шукачів пригод розвідати глибини й підтвердити найгірше."},{t="Виснажена варта",b="Підтверджена навала лише додає головного болю вартовим Стормвінда. Регулярні війська розтягнуті між обороною від бандитів Дефіас і нападами гнолів, тож варті бракує людей, щоб одразу зачистити копальню. Похмура реакція Дуґана на підтвердження показує, як поступово вислизає з рук контроль над серцем королівства, і він одразу починає тривожитися за інші рудні місця — зокрема за Яшмову копальню на північному сході."}},faq={{q="Де розташована Копальня Фарґодіп?",a="Копальня Фарґодіп лежить майже точно на південь від Ґолдшира в Лісі Елвінн, якраз між садибами Стоунфілдів і Маклюрів.",al={"де фарґодіп","де копальня фарґодіп","карта копальні фарґодіп"}},{q="Хто посилає розвідати Копальню Фарґодіп?",a="Маршал Дуґан, командир Варти Стормвінда в Ґолдширі, доручає розвідати тунелі.",al={"хто дає завдання фарґодіп","завдання маршала дуґана"}},{q="Які істоти захопили копальню?",a="Копальню цілком заполонили кобольди: вони там окопалися, запалили свої свічки й витіснили робітників-людей.",al={"хто у фарґодіпі","які чудовиська у фарґодіпі"}},{q="Чому Маршалові Дуґану потрібні шукачі пригод, щоб перевірити копальню?",a="Варта Стормвінда й так ледве дає раду з місцевими розбійниками, рештками орків і набігами гнолів, тож у Дуґана немає вільних солдатів навіть для того, щоб перевірити звичайні донесення розвідників.",al={"чому розвідувати","чому вартові не йдуть"}},{q="Що буде після розвідки Копальні Фарґодіп?",a="Коли ви доповісте Маршалові Дуґану погані новини, він злякається, що біда поширилася, і відправить вас на північний схід — перевірити ще й Яшмову копальню.",al={"наступне завдання після фарґодіпа","що далі"}},{q="Чому захоплення Копальні Фарґодіп таке важливе?",a="Падіння Фарґодіпу доводить, що навала кобольдів у Нортширі не була поодиноким випадком. Воно показує, як швидко дикі загрози підступають до обжитих фермерських земель просто під брамою Стормвінда.",al={"чому фарґодіп важливий","переказ про копальню фарґодіп"}}},fp="18,257,26.450.0,16.435.0,36.127.0,42.132.0,40.117.0,59.193.0,47.150.1,53.200.0"}
P.entries["quest:6281"] = {n="Далі до Стормвінда",s="Це доручення знайомить шукачів пригод у Вестфолі зі швидкістю й зручністю грифонової мережі Королівства Стормвінд. З терміновою заявкою із Сентінел Гілла мандрівники летять просто до Старого Міста, щоб передати звістку торговцеві Осрікові Стренгу.",h="Це доручення знайомить шукачів пригод у Вестфолі зі швидкістю й зручністю грифонової мережі Королівства...",kw={"далі до стормвінда","тор","осрік стренг","старе місто","грифон","інтендант льюїс"},ang={["faction:Alliance"]="Мережа польотів, яку підтримують майстри грифонів, з'єднує розкидані застави Альянсу й тримає віддалені гарнізони на зв'язку зі столицею.",["race:Human"]="Повернення до Старого Міста показує, наскільки відірваними від політики величного Дому Вельмож почуваються прості городяни й самотні мешканці прикордоння."},sec={{t="На крилах",b="Коли Інтендант Льюїс у Сентінел Гіллі складає заявку, місцевий майстер грифонів Тор пропонує найшвидший шлях геть зі спірних рівнин. За скромну плату мандрівники сідають на одного з навчених грифонів королівства й злітають над курними нивами, над річковим кордоном Лісу Елвінн і над високими білими мурами самого Стормвінда."},{t="Постачання зі Старого Міста",b="Приземлившись у торговому гнізді столиці, гонець вирушає до Старого Міста, щоб знайти Осріка Стренга в його крамниці «Обмежений імунітет». Осрік постачає прикордонню спорядження й припаси, хоча його похмура зустріч показує, як поглиблюється розрив між знесиленим Народним ополченням у Вестфолі й неуважними правителями у Фортеці Стормвінда."}},faq={{q="Навіщо це завдання?",a="Завдання — практичне знайомство з грифонячими маршрутами Альянсу: воно вчить шукачів пригод швидко подорожувати між віддаленими заставами й столицею.",al={"навіщо це завдання","мета завдання","ціль далі до стормвінда"}},{q="Де знайти Осріка Стренга?",a="Осрік Стренг тримає крамницю «Обмежений імунітет» на звивистих вулицях Старого Міста в Стормвінді.",al={"де осрік стренг","знайти осріка стренга","де обмежена недоторканність"}},{q="Навіщо Сентінел Гіллу припаси зі Стормвінда?",a="Народне ополчення на Сентінел Гіллі ледве тримається проти Братства Дефіас і майже не отримує офіційної військової допомоги зі столиці, тож Інтендант Льюїс змушений купувати спорядження просто в цивільних купців.",al={"чому потрібні припаси","проблема постачання вестфолу","спорядження сентінел гілл"}},{q="Хто такий Тор?",a="Тор — розпорядник грифонів Альянсу на Сентінел Гіллі; він відає маршрутами, що з'єднують Вестфол зі Стормвіндом та іншими дружніми осередками.",al={"хто такий тор","майстер грифонів вестфолу","тор вестфол"}},{q="Що в Записці Льюїса?",a="Це термінова заявка Інтенданта Льюїса з переліком спорядження й провіанту, яких конче потребує гарнізон Сентінел Гілла.",al={"записка льюїса","що в записці","вміст записки"}},{q="Що буде після доставки записки?",a="Отримавши заявку, Осрік скеровує вас до стормвіндського розпорядника грифонів Дунґара Лонґдрінка, щоб домовитися про доставку замовлених припасів назад до Вестфолу.",al={"що далі","наступне завдання","після осріка стренга"}}},fp="21,268,11.357.0,21.336.0,34.174.0,30.113.0,52.218.0,12.153.0,27.148.0,39.179.0"}
P.entries["quest:6282"] = {n="Загроза гарпій",s="«Загроза гарпій» — завдання Орди, яке дає Маґґран Ертбайндер у Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Виконуючи покликання тауренів як охоронців землі, шукачі пригод вирушають на південь, у спустошену Обвуглену Долину, щоб прорідити дедалі численніші лави гарпій із ковену Бладф'юрі.",h="«Загроза гарпій» — завдання Орди, яке дає Маґґран Ертбайндер у Притулку Сонячної Скелі в Горах Кам'яного...",kw={"загроза гарпій","гарпії","бладф'юрі","обвуглена долина","маґґран ертбайндер","притулок сонячної скелі"},ang={["class:Druid"]="Викривлена присутність ковену Бладф'юрі оскверняє й без того крихку, сплюндровану вогнем природу Обвугленої Долини.",["class:Shaman"]="На прохання Маґґрана Ертбайндера шамани відгукуються на поклик очистити край від агресивних осквернителів, що порушують природну рівновагу стихій.",["faction:Horde"]="Очищене небо над Обвугленою Долиною зміцнює опору Орди в Притулку Сонячної Скелі проти небезпечних диких сил, що населяють Гори Кам'яного Кігтя.",["race:Tauren"]="Для тауренів знищення Бладф'юрі, що насуваються на їхні землі, — почесний обов'язок, виконання давньої обіцянки предків бути захисниками дикої природи Калімдору."},sec={{t="Захисники землі",b="Таурени з Притулку Сонячної Скелі мають глибокий обов'язок оберігати Гори Кам'яного Кігтя: підтримувати природну рівновагу й захищати мирних мандрівників від небезпек краю. Маґґран Ертбайндер, старійшина й провідник притулку, з дедалі більшою тривогою спостерігає, як невпинно множаться місцеві гарпії. Ковен Бладф'юрі розповзся випаленими пустирями Обвугленої Долини, нападає на звірів, що проходять повз, і перекриває шляхи. Якщо його не спинити, хижі зграї загрожують повністю відрізати Притулок Сонячної Скелі від світу."},{t="Зачистка Обвугленої Долини",b="На південь від Притулку Сонячної Скелі лежить Обвуглена Долина — безлюдна пустка з попелу, випаленої землі й тліючих дерев, що лишилися після нищівних пожеж. Тут, гніздячись високо в обгорілих рештках прадавніх лісів, Бладф'юрі звели собі твердиню. Маґґран доручає воякам Орди вирушити в цю ворожу улоговину й знищити десятки гарпій — засідниць, убивць і крадійок-пернатих. Прорідивши зграю, вони зламають хватку ковену на долині й розчистять шлях до прямого двобою з родом його матріархів."}},faq={{q="Хто дає завдання «Загроза гарпій»?",a="Завдання дає Маґґран Ертбайндер, таурен, що стоїть біля водойми посеред Притулку Сонячної Скелі в Горах Кам'яного Кігтя.",al={"хто дає загрозу гарпій","де взяти загрозу гарпій","завдання маґґрана ертбайндера"}},{q="Де живуть гарпії Бладф'юрі?",a="Гарпії Бладф'юрі населяють Обвуглену Долину — випалений простір просто на південь від Притулку Сонячної Скелі. Гірська стежка позаду Сонячної Скелі веде прямо вниз, у долину.",al={"де гарпії бладф'юрі","місця гарпій бладф'юрі","гарпії обвугленої долини"}},{q="Чому таурени хочуть проріджувати гарпій?",a="Таурени вважають себе охоронцями природної рівноваги Гір Кам'яного Кігтя. Маґґран Ертбайндер боїться, що Бладф'юрі агресивно розселяються Калімдором, нападають на невинних і не дають живим істотам вільно мандрувати цим краєм.",al={"чому вбивати гарпій","конфлікт тауренів і гарпій","чому маґґран ненавидить гарпій"}},{q="Що буде після завдання «Загроза гарпій»?",a="Виконавши «Загрозу гарпій», ви відкриєте наступне завдання — «Родовід Бладф'юрі», у якому Маґґран Ертбайндер посилає вас знищити ватажків ковену Бладф'юрі.",al={"наступне завдання загроза гарпій","продовження загрози гарпій","що після загрози гарпій"}},{q="Це завдання лише для Орди?",a="Так. Завдання пропонують тільки Орді, у поселенні Притулок Сонячної Скелі.",al={"чи альянс може загрозу гарпій","загроза гарпій лише для орди","альянс загроза гарпій"}},{q="Яких гарпій треба вбити?",a="Треба вбити по сім гарпій Бладф'юрі, засадниць Бладф'юрі, убивць Бладф'юрі й розбійниць Бладф'юрі в Обвугленій Долині.",al={"яких гарпій вбивати","типи гарпій обвугленої долини","цілі загрози гарпій"}}},fp="16,288,22.518.0,25.538.0,37.139.0,40.183.0,42.251.0,45.175.0,25.91.0,36.149.0"}
P.entries["quest:6284"] = {n="Арахнофобія",s="«Арахнофобія» — завдання Орди за винагороду: ціль — Бесселет, прадавня велетенська хижачка, що тероризує південь Гір Кам'яного Кігтя. Оголошення біля дороги поблизу Кручі Вітрорізу кличе шукачів пригод у Каньйон Сішир, щоб здобути ікло павучої матріархи для Маґґрана Ертбайндера в Притулку Сонячної Скелі. Поклавши край її владі, ви зробите гірські дороги безпечнішими для нічних мандрівників.",h="«Арахнофобія» — завдання Орди за винагороду: ціль — Бесселет, прадавня велетенська хижачка, що тероризує...",kw={"арахнофобія","бесселет","павучиха","каньйон сішир","маґґран ертбайндер","ікло бесселет"},ang={["class:Hunter"]="Вистежити невловиму велетенську павучиху серед затінених круч Каньйону Сішир — справжнє випробування для гірського мисливця.",["faction:Horde"]="Знищення Бесселет робить безпечнішим шлях до Притулку Сонячної Скелі й захищає життєво важливу опору Орди серед центральних круч Гір Кам'яного Кігтя.",["race:Tauren"]="Маґґран Ертбайндер носить болючий шрам від отрути Бесселет, тож це полювання — справа честі й допомога побратимові, синові землі."},sec={{t="Попередження біля дороги",b="Мандрівники на головному шляху на південь від Кручі Вітрорізу помітять вицвіле оголошення про розшук, що попереджає про небезпеку на заході. Каньйон Сішир і Стежка Павутинника геть кишать восьминогими хижаками. У самому серці цього павутинного лиха сидить Бесселет — незвично велика павучиха помаранчевого кольору, що керує своїм виводком і нападає з засідки на кожного, хто наважиться зійти зі стежки після заходу сонця."},{t="Кривда Ертбайндера",b="Нагороду за Бесселет призначив Маґґран Ертбайндер, таурен із Притулку Сонячної Скелі. У Маґґрана з матріархою особисті рахунки: під час минулої зустрічі він ледь не загинув, коли Бесселет уразила його своїм величезним іклом завдовжки у два фути. Хоч йому й вдалося відбитися й, накульгуючи, дістатися безпечного місця, рана, що досі не загоїлася, постійно нагадує про небезпеку, яка чатує в тінях каньйону. Доручивши шукачеві пригод здобути Ікло Бесселет, Маґґран сподівається убезпечити перевали, щоб торгівля й подорожі до Притулку Сонячної Скелі процвітали без страху."}},faq={{q="Де починається завдання «Арахнофобія»?",a="Завдання починається з оголошення про розшук, вивішеного на західному узбіччі головної дороги в Горах Кам'яного Кігтя, трохи на південь від входу до Кручі Вітрорізу.",al={"де взяти арахнофобію","де оголошення бесселет","як почати арахнофобію"}},{q="Де знайти Бесселет?",a="Бесселет має лігво в Каньйоні Сішир, що трохи на захід від оголошення при дорозі. Вона никає серед свого павучого виводку по обплутаному павутинням дну каньйону.",al={"де бесселет","де знайти бесселет","знайти павучиху бесселет"}},{q="Хто такий Маґґран Ертбайндер?",a="Маґґран Ертбайндер — таурен із Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Він сам пережив отруйний укус Бесселет і призначив нагороду, щоб позбавити каньйон цієї загрози.",al={"хто такий маґґран","роль маґґрана ертбайндера","кому здати арахнофобію"}},{q="Чому Бесселет така небезпечна для краю?",a="Бесселет — надзвичайно велика й безжальна павучиха, що полює в Каньйоні Сішир і на сусідній Стежці Павутинника. Вона та її виводок під покровом ночі нападають на мандрівників, загрожуючи кожному, хто намагається дістатися Притулку Сонячної Скелі.",al={"чому бесселет небезпечна","що зробила бесселет"}},{q="Який доказ потрібен, щоб отримати нагороду?",a="Треба вбити Бесселет і відтяти одне з її величезних іклів, завдовжки зо два фути. Віддавши Ікло Бесселет Маґґранові Ертбайндеру в Притулку Сонячної Скелі, ви отримаєте нагороду.",al={"доказ бесселет","предмет завдання бесселет","що випадає з бесселет"}},{q="Чи доступне це завдання Альянсу?",a="Ні. Нагороду за оголошенням видає Маґґран Ертбайндер у Притулку Сонячної Скелі — таборі Орди, тож «Арахнофобія» доступна лише Орді.",al={"чи альянс може арахнофобію","завдання арахнофобія для альянсу"}}},fp="13,392,20.398.0,27.556.0,41.169.0,29.162.0,27.200.0,45.237.0,43.162.0,40.153.0"}
P.entries["quest:63"] = {n="Поклик води",s="Цей важливий обряд посвяти веде шаманів із Пусток за Велике море, до сплюндрованих берегів Срібнолісся. Щоб здобути право на єднання з духами води, новачок мусить зустрітися з оскверненим елементалем і очистити прадавнє прибережне святилище, сплюндроване чумою Погибелі.",h="Цей важливий обряд посвяти веде шаманів із Пусток за Велике море, до сплюндрованих берегів Срібнолісся.",kw={"поклик води","жаровня вічноджерела","срібнолісся","іслен вотерсір","брайн","шаман"},ang={["class:Shaman"]="Цей обряд доводить, що шаман — не лише той, хто кличе бурі, а й цілитель зламаних земель, покликаний очищати їх від духовної скверни.",["faction:Horde"]="Подорож у Срібнолісся змушує народжених у Калімдорі орків і тауренів на власні очі побачити похмурі, зачумлені злигодні їхніх союзників-Відступників."},sec={{t="Паломництво за море",b="Здобувши під наглядом самітниці Брайн краплі чистої води, шаман повертається на узбережжя Пусток, де чекає Іслен Вотерсір. Тоді Іслен доручає новачкові куди небезпечнішу справу: перенести цю очищену суть за море, на примарне узбережжя Срібнолісся, трохи на захід від притулку Відступників — Гробниці."},{t="Очищення Вічноджерела",b="Обране святилище — Жаровня Вічноджерела, прадавній стихійний фокус, чиї води спотворилися й стали ворожими під впливом чумної скверни Лордерону. Духи води, що жили тут, онімілі й здичавіли. Здолавши осквернену сутність, прив'язану до цього місця, і віддавши полум'ю жаровні і її наручі, і найчистішу воду, шаман розриває лещата помори й викликає неоскверненого духа припливів."}},faq={{q="Чому шаманові доводиться мандрувати аж до Срібнолісся?",a="Іслен Вотерсір вимагає, щоб шамани довели свою владу над скверною, а не лише вивчали спокій. Прибережне святилище на захід від Гробниці стало жертвою чуми Лордерону, тож учень має нагоду зцілити святилище стихій і знову пробудити духів води, які ні з ким іншим говорити не хочуть.",al={"чому йти до срібнолісся","чому подорож через море","чому водне завдання в срібноліссі"}},{q="Що станеться, коли скористатися Жаровнею Вічного Джерела?",a="Коли покласти у вогонь наручі переможеного елементаля разом з останніми краплями найчистішої води, почнеться обряд очищення, якого навчила Іслен. Ця потріскувальна пожертва очищає місцеву водойму й викликає чисте втілення води, готове дати своє благословення.",al={"подія жаровні вічного джерела","що робить жаровня","як очистити озеро"}},{q="Хто оскверняє святилище води в Срібноліссі?",a="Воду спотворила чума, що досі висить над занепалим королівством Лордерон. Скверна, що стікає з пагорбів, отруїла місцеве джерело й перетворила його духів води на здичавілих, ворожих потвор.",al={"хто осквернив святилище","чому прояв осквернений","осквернення води в срібноліссі"}},{q="Що я отримаю, пройшовши це випробування?",a="Очистивши Жаровню Вічного Джерела, ви зможете поспілкуватися з чистим духом води. Віднісши доказ очищення Іслен Вотерсір у Пустки, ви нарешті здобудете Тотем Води й завершите довге випробування «Поклик води».",al={"нагорода поклику води","відкрити тотем води","що я отримаю"}},{q="Де саме розташоване святилище?",a="Святилище стоїть просто на західному узбережжі Срібнолісся, за спустошеним хребтом трохи на захід від Гробниці.",al={"де жаровня вічного джерела","де святилище","координати святилища срібнолісся"}},{q="Хто така Іслен Вотерсір?",a="Іслен Вотерсір — відлюдниця, що єднається зі стихіями й живе на Узбережжі Крамарів Пусток, на південь від Раджета. Вона — шанована духовна провідниця, яка веде молодих шаманів Орди через важкі обряди, потрібні, щоб злагодитися зі стихією води.",al={"хто така іслен","історія іслен вотерсір","наставниця води в пустках"}}},fp="13,295,27.345.0,23.441.1,66.303.0,51.264.0,49.240.0,48.237.0,36.123.0,23.246.0"}
P.entries["quest:6301"] = {n="Цикл переродження",s="«Цикл переродження» — завдання Орди, яке дає Таммра Віндфілд у Притулку Сонячної Скелі: зібрати рідкісне насіння Геї на берегах Озера Міркфаллон. Засмучена тим, яку ціну платять Гори Кам'яного Кігтя за промислову жадобу й нескінченні війни, Таммра хоче благословити ці витривалі зернята шаманською силою, щоб оживити сплюндровану землю гір. Це перший і найважливіший крок у зціленні пораненої дикої природи.",h="«Цикл переродження» — завдання Орди, яке дає Таммра Віндфілд у Притулку Сонячної Скелі: зібрати рідкісне...",kw={"цикл переродження","таммра віндфілд","насіння геї","озеро міркфаллон","земна мати","шаман"},ang={["class:Druid"]="Друїди оцінять, що й тут ідеться про природні цикли та вирощування насіння: відродження мертвої землі прямо перегукується з кенарійським опікуванням природою.",["class:Shaman"]="Зусилля Таммри відбивають шаманське покликання — виправляти порушену рівновагу природи: духи й Земна Мати здатні відновити те, що руйнує промисловий визиск.",["race:Tauren"]="Для шу'гало зцілення пораненої землі Гір Кам'яного Кігтя — духовний обов'язок перед Земною Матір'ю, відповідь на спустошення, яке принесли безрозсудні вирубки й війни між фракціями."},sec={{t="Поранена глушина",b="Вершини Гір Кам'яного Кігтя несуть глибокі рани і від торговельного визиску, і від нескінченних місцевих чвар. Через загарбницькі вирубки й сутички ворожих сил цілі смуги лісу випалено, вирубано дочиста чи обернено на попіл. Для тауренів із Притулку Сонячної Скелі бачити, як стрімко нищиться природа, — тяжка рана. Шамани на кшталт Таммри Віндфілд не лише борються за кожну п'ядь землі, а й звертаються до давнього природного ладу, прагнучи запустити цілющий цикл Земної Матері."},{t="Насіння з Міркфаллону",b="Щоб повернути життя мертвій землі, потрібна надзвичайна життєва сила, і Таммра знаходить її в рідкісному насінні Геї, що росте довкола Озера Міркфаллон. На березі цього озера, на північ від Притулку Сонячної Скелі, біля самої води визрівають міцні насінні коробочки. Хоч довкола чигає чимало небезпек, це насіння має природну витривалість, властиву лише Горам Кам'яного Кігтя. Коли його принесуть, Таммра вливає в кожне зернятко благословення предків, пробуджуючи приховану силу, щоб прискорити ріст для майбутньої праці."}},faq={{q="Навіщо збирати насіння Ґеї?",a="Насіння Ґеї має виняткову природну життєву силу, тож чудово надається для відродження спустошених земель. Таммра Віндфілд збирає його, щоб наповнити благословеннями Земної Матері й шаманською силою — тоді воно швидко проросте й відновить ті частини Кам'яного Кігтя, які зруйнували промисловці й війна.",al={"навіщо насіння ґеї","для чого насіння ґеї","мета циклу переродження"}},{q="Де знайти насіння Ґеї?",a="Насіння Ґеї лежить на березі Озера Міркфаллон, просто на північ від Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Його можна знайти в землі біля самої води по всьому периметру озера.",al={"де насіння ґеї","де знайти насіння ґеї","насіння озера мірквалон"}},{q="Хто така Таммра Віндфілд?",a="Таммра Віндфілд — шаманка-тауренка, що живе в Притулку Сонячної Скелі. Глибоко засмучена тим, як війни й лісозаготівельні синдикати винищили й спустошили Кам'яний Кіготь, вона присвячує себе зціленню землі благословеннями Земної Матері.",al={"хто така таммра","переказ про таммру віндфілд"}},{q="Що робить Таммра, коли отримує насіння?",a="Отримавши десять насінин Ґеї, Таммра заводить священний спів, щоб наповнити зерна шаманською енергією й пришвидшити їхній природний ріст, — тоді їх можна буде посадити в спустошених місцях.",al={"що з насінням","здати цикл переродження"}},{q="Яке завдання йде після «Циклу переродження»?",a="«Цикл переродження» веде просто до завдання «Нове життя», у якому насіння, сповнене сили, несуть у спустошену Обвуглену Долину, щоб знову дати там життя рослинам.",al={"продовження циклу переродження","наступне завдання після циклу переродження","що після циклу переродження"}},{q="Чому землі Кам'яного Кігтя потребують зцілення?",a="Гори Кам'яного Кігтя тяжко постраждали від безперервних війн і суцільних вирубок промислових лісозаготівельників: лишилися випалена земля й понівечені долини, які насилу заростають самі.",al={"чому кам'яний кіготь руйнується","що сталося з кам'яним кігтем"}}},fp="16,429,20.546.0,23.520.0,45.309.0,33.224.0,24.255.0,48.196.0,36.166.0,49.232.0"}
P.entries["quest:631"] = {n="Міст Тандол",s="Після нищівного вибуху, що струсонув північ Багнокраю, Раґ Ґармасон просить мандрівників обшукати зруйновані прольоти Мосту Тандол у пошуках зниклого дворфа-розвідника. Клан Темного Заліза жорстоко напав на Дун Модр, обірвавши зв'язок і лишивши місцевих захисників без підкріплень. Знайти Старого Растлока — перший крок до того, щоб збагнути повний розмах диверсії.",h="Після нищівного вибуху, що струсонув північ Багнокраю, Раґ Ґармасон просить мандрівників обшукати зруйновані...",kw={"міст тандол","раґ ґармасон","старий растлок","дун модр","темне залізо","багнокрай"},ang={["faction:Alliance"]="Міст Тандол — єдиний суходільний шлях постачання, що пов'язує Стормвінд і Айронфордж із силами Альянсу, які тримаються в Араті й Гілсбреді.",["race:Dwarf"]="Руйнування Мосту Тандол — образа дворфійському кам'яному ремеслу й прямий удар по Каз Модану від ненависних родичів із Темного Заліза."},sec={{t="Грім над мостом",b="Нещодавно нищівний вибух розірвав Міст Тандол, розтрощивши величезну кам'яну переправу між Багнокраєм і Аратійським нагір'ям. Вояки-Бронзбірди, що стояли на кордоні, потрапили під удар, коли дворфи Темного Заліза влаштували засідку на Дун Модр. Із порідшалими лавами й обложеними твердинями вцілілі під проводом Лонґбрейда Похмурого змушені вперто й відчайдушно оборонятися від нападників."},{t="Розвідник, посланий на схід",b="Сподіваючись урятувати переправу й з'ясувати, чи лишився придатний шлях на північ, Лонґбрейд відрядив досвідченого розвідника Ебенізера Растлока оглянути східний проліт. Минали дні без жодного донесення, але з Дун Модром в облозі Раґ Ґармасон і гарнізон не мають вояків, щоб послати рятувальний загін у руїни, захоплені ворогом."},{t="Похмура знахідка",b="Вийшовши на розтрощений міст, бачиш, якою ціною обернувся напад Темного Заліза. Старий Растлок не повернувся з розвідки — він загинув серед уламків східного прольоту. Його тіло й пергамент, затиснутий у кулаці, підтверджують найгірше: він натрапив на засідку Темного Заліза, а дворфи Темного Заліза ще не покінчили з цією життєво важливою артерією між Каз Моданом і Лордероном."}},faq={{q="Що таке Міст Тандол?",a="Міст Тандол — колосальна дворфійська споруда, перекинута через прірву між північчю Багнокраю й Аратійським нагір'ям. Це головний суходільний шлях, що з'єднує Каз Модан із північними землями Лордерону.",al={"міст тандол","що таке міст тандол","міст у мокрих землях"}},{q="Хто напав на Міст Тандол?",a="На міст і сусідню заставу Дун Модр напав клан дворфів Темного Заліза. Вони підірвали вибухівку, щоб перервати міст, паралізували переміщення Альянсу й заскочили зненацька оборонців із клану Бронзбірдів.",al={"хто підірвав міст","вибух мосту тандол","хто напав на дун модр"}},{q="Хто такий Старий Растлок?",a="Ебенезер Растлок був надійним дворфійським розвідником на службі в Лонґбрейди Похмурого. Його послали оцінити стан східної частини мосту після вибуху, але під час завдання сили Темного Заліза здолали його й убили.",al={"ебенезер растлок","хто такий растлок","зниклий розвідник"}},{q="Де знайти Раґа Ґармасона?",a="Раґ Ґармасон стоїть біля обложеного поселення Дун Модр, трохи на південь від Мосту Тандол на півночі Багнокраю. Він допомагає керувати обороною, поки гарнізон відрізаний від Айронфорджа.",al={"де раґ ґармасон","місце раґа","видавець у дун модрі"}},{q="Чому Айронфордж не надіслав допомогу до Дун Модра?",a="Раптовий напад, зруйнований міст і облога Дун Модра лишили гарнізон в ізоляції. Оборонців надто мало, щоб відправити гінців чи відрядити загони, тож вони залежать від мандрівних шукачів пригод, які можуть передати звістку.",al={"чому немає підкріплення","допомога айронфорджа мокрим землям","підкріплення дун модра"}},{q="Що буде, коли знайти тіло Растлока?",a="При останках Растлока лежить пергамент, з якого видно, що Кам Діпф'юрі, натхненник нападу, сховав запас вибухівки по той бік мосту. Так починаються спроби знищити схованку, перш ніж вибухівка дістанеться вцілілої частини мосту, а згодом — і пошуки ширшої допомоги через звернення до проводу Альянсу.",al={"наступне завдання після растлока","продовження мосту тандол","після мосту тандол"}}},fp="16,413,21.432.0,17.358.0,14.380.1,25.226.0,30.202.0,21.231.1,31.206.0,43.267.0,46.302.1"}
P.entries["quest:632"] = {n="Міст Тандол",s="Раґ Ґармасон доручає шукачам пригод провідати Старого Ебенізера Растлока — розвідника, якого послали оглянути величезну кам'яну переправу Мосту Тандол і з яким зник зв'язок. Пошуки під арками переправи розкривають обставини його зникнення й загрози північним шляхам постачання.",h="Раґ Ґармасон доручає шукачам пригод провідати Старого Ебенізера Растлока — розвідника, якого послали оглянути...",kw={"міст тандол","накази діпф'юрі","ебенізер растлок","раґ ґармасон","темне залізо","засідка"},ang={["faction:Alliance"]="Міст Тандол — артерія, що прив'язує Айронфордж і Стормвінд до північних твердинь Альянсу, тож знахідка біля тіла Растлока критично важлива для безпеки всього континенту.",["race:Dwarf"]="Те, що сили Темного Заліза діють так далеко на північ від Палючої Ущелини, показує, як глибоко сягає їхнє підступне проникнення, що загрожує побратимам з Айронфорджа."},sec={{t="Останній бій розвідника",b="Командир Лонґбрейд послав Ебенізера Растлока наглядати за цілістю й безпекою Мосту Тандол. Коли зв'язок із розвідником обірвався, одразу запідозрили лихе. Обшукавши закутки під арками, ви знаходите Растлока мертвим: він загинув у лютій засідці, яку з тіні влаштували загарбники з Темного Заліза."},{t="Накази Діпф'юрі",b="Біля стиснутих пальців Растлока знаходять письмові накази з ім'ям Діпф'юрі. Це не випадковий грабіж і не поодинока прикордонна сутичка: пергамент розкриває навмисні операції Темного Заліза, спрямовані на те, щоб розхитати переправу. Доставлений Ґармасонові доказ змінює настрій гарнізону — зі звичайного пошуку на нагальну воєнну оборону."}},faq={{q="Хто такий Ебенезер Растлок?",a="Ебенезер «Старий» Растлок — дворф Альянсу, якого відрядили розвідати Міст Тандол і пильнувати його. Його заскочили зненацька й убили дворфи Темного Заліза, що нишпорили під мостом.",al={"хто такий растлок","старий растлок","ебенезер растлок"}},{q="Хто вбив Растлока?",a="Він потрапив у засідку агентів Темного Заліза, які діяли під Мостом Тандол, виконуючи накази Кама Діпф'юрі.",al={"хто вбив растлока","хто влаштував засідку","тіло растлока"}},{q="Що знаходять при тілі Растлока?",a="Біля його стиснутого кулака лежить пергамент — Накази Діпф'юрі, у яких описано таємні змови Темного Заліза проти життєво важливого північного мосту.",al={"що було в руці","накази діпф'юрі","пергамент на растлоку"}},{q="Хто такий Раґ Ґармасон?",a="Раґ Ґармасон — офіцер Альянсу на південному боці Мосту Тандол у Багнокраї; він відповідає за безпечний рух між дворфійськими землями й північчю.",al={"раґ ґармасон","хто такий ґармасон"}},{q="Чому за Міст Тандол точиться така запекла боротьба?",a="Міст Тандол — єдиний суходільний міст, що з'єднує дворфійські землі Каз Модану й Багнокрай з Аратійським нагір'ям і Лордероном. Утримати його життєво важливо для постачання Альянсу.",al={"чому міст тандол важливий","значення мосту тандол"}},{q="Що буде, коли віддати накази Раґові Ґармасону?",a="Усвідомивши всю серйозність загрози, Раґ Ґармасон посилає вас знищити запас вибухівки Темного Заліза, схований по той бік мосту, в Аратійському нагір'ї, щоб зірвати їхню диверсію.",al={"що буде далі","продовження мосту тандол"}}},fp="16,322,21.358.0,17.380.1,27.191.1,21.123.1,34.141.1,21.184.0,45.196.0,54.184.1"}
P.entries["quest:6321"] = {n="Постачання для Гробниці",s="«Постачання для Гробниці» — доручення з постачання від Вартового Смерті Подріґа в Гробниці в Срібноліссі. Щоб місцевий загін вартових смерті мав чим битися з дикими жахіттями й Погибеллю, що нишпорять лісами, нагальну заявку на зброю треба передати через доглядача кажанів Кароса Разока постачальникам зброї в Андерсіті.",h="«Постачання для Гробниці» — доручення з постачання від Вартового Смерті Подріґа в Гробниці в Срібноліссі.",kw={"постачання для гробниці","вартовий смерті подріґ","карос разок","ґордон вендгем","гробниця","кажани","зброя"},ang={["faction:Horde"]="Налагодити й підтримувати надійні летючі шляхи між залогами й столицями — основа злагодженої військової оборони в спірних краях.",["race:Undead"]="Утримання застав на кшталт Гробниці дає Відступникам змогу поширювати свою силу за межі Галявин Тірісфалю й убезпечувати навколишню дику місцину для Темної Леді."},sec={{t="Озброїти передову",b="Вартовий Смерті Подріґ доповідає, що Гробниця відносно добре забезпечена, але безперервні втрати в Срібноліссі пожирають спорядження з тривожною швидкістю. Між дикими звірами, рештками Погибелі й агресивними місцевими загрозами фронтове спорядження зношується чи лишається на полі після сутичок. За наказом Екзекутора Гадрека Подріґ складає пряму заявку Ґордонові Вендгему — торговцеві зброєю зі столиці. Постійний приплив нових клинків і обладунків вкрай потрібен, якщо Відступники хочуть утримати свої хиткі позиції за межами Галявин Тірісфалю."},{t="Летюча мережа",b="Пересилати важливе листування й військові припаси затуманеними дорогами Срібнолісся пішки — повільно й небезпечно через засідки. Щоб обійти ці небезпеки, Відступники покладаються на приручених, навчених кажанів-кровопивців. Передавши заявку Подріґа доглядачеві кажанів Каросові Разоку, ви долучаєте піхоту до ширшої повітряної мережі постачання Андерсіті — тих летючих шляхів, що прив'язують віддалені залоги просто до столиці Сильвани."}},faq={{q="Навіщо замовлення Подріґа?",a="Вартовий Смерті Подріґ перевірив зброярню Гробниці на доручення Виконавця Гадрека. Провіанту й загального спорядження вистачало, але треба було замінити зброю, зламану чи втрачену в сутичках із Погибеллю та іншими загрозами лісу.",al={"навіщо замовлення подріґа","що таке вимога подріґа","мета постачання гробниці"}},{q="Хто такий Ґордон Вендгем?",a="Ґордон Вендгем — торговець зброєю в Андерсіті. Подріґ адресує заявку саме йому, щоб забезпечити гарнізон новою зброєю.",al={"хто такий ґордон вендгем","ґордон вендгем андерсіті"}},{q="Хто такий Карос Разок?",a="Карос Разок — доглядач кажанів у Гробниці. Він відає сідалом жахливих кажанів, на яких по всьому Лордерону перевозять гінців, розвідників і припаси.",al={"роль кароса разока","хто той кажановодець"}},{q="Чому кажани, а не кур'єри по дорогах?",a="Срібнолісся кишить ворожими звірами, мандрівними загонами Погибелі та іншими небезпечними силами. Кур'єри на дорогах постійно ризикують потрапити в засідку, тож повітряні маршрути на кажанах — найшвидший і найбезпечніший зв'язок з Андерсіті.",al={"чому летіти до андерсіті","чому кажани"}},{q="Які загрози нависли над Гробницею?",a="Гробницю оточують ворожі сили: недобитки нежиті Погибелі, воргени, дикі звірі й місцеві угруповання людей, — тож гарнізон мусить завжди бути напоготові й постійно поновлювати спорядження.",al={"загрози гробниці","чому вартовим смерті потрібна зброя"}},{q="Куди веде це доручення далі?",a="Коли ви доставите замовлення Каросові Разоку, він влаштує вам переліт просто до Андерсіті, де заявку можна передати безпосередньо Ґордонові Вендгему.",al={"яке завдання далі","що після постачання для гробниці"}}},fp="23,328,21.597.0,18.443.0,38.243.0,22.159.0,19.163.0,38.216.0,37.207.0,31.167.0"}
P.entries["quest:6322"] = {n="Майкл Гарретт",s="«Майкл Гарретт» — просте доручення гінця, що поєднує торгівлю в Андерсіті з повітряною мережею Відступників. Забравши припаси, спаковані Ґордоном Вендгемом у Торговому Кварталі, ви маєте віднести ящик доглядачеві кажанів Майклові Гарретту, щоб той відправив вантаж до Склепу. Це завдання показує, як Відступники навченими кажанами-вампірами поєднують столицю із заставами по всьому Лордерону.",h="«Майкл Гарретт» — просте доручення гінця, що поєднує торгівлю в Андерсіті з повітряною мережею Відступників.",kw={"майкл гарретт","ґордон вендгем","ящик гордона","кажани","торговий квартал","склеп","андерсіті"},ang={["faction:Horde"]="Для мандрівників, що прибувають із Калімдору, мережа кажанів Відступників — основний спосіб швидко переміщатися північчю Східних Королівств.",["race:Undead"]="Щоб утримувати присутність Сильвани за межами Галявин Тірісфалю, конче треба розуміти, як працює повітряне постачання, яким опікуються наглядачі на кшталт Майкла Гарретта."},sec={{t="Постачання застав",b="Молоде королівство, вирубане з руїн Лордерона, потребує невпинного постачання. Застави на кшталт Склепу в Срібноліссі дуже залежать від товарів, боєприпасів і харчів, що йдуть з Андерсіті. Ґордон Вендгем пакує потрібні припаси в один ящик у Торговому Кварталі міста, та возити вантажі суходолом крізь отруєні ліси і повільно, і небезпечно: у засідці можуть чекати рештки Погибелі чи дикі звірі."},{t="Крила Відступників",b="Щоб обійти небезпеки на дорогах, Відступники тримають кажанів-вампірів, яких вирощують і доглядають умілі наглядачі. Майкл Гарретт опікується цими крилатими створіннями зі свого сідала в Торговому Кварталі Андерсіті. Передавши йому вантаж, ви забезпечите, що припаси приторочать до кажана й перенесуть просто через пагорби до Срібнолісся, — а нові гінці заразом дізнаються, як столиця тримає зв'язок із віддаленими поселеннями."}},faq={{q="Хто такий Майкл Гарретт?",a="Майкл Гарретт — доглядач кажанів Андерсіті в Торговому Кварталі. Він відає кажанами-вампірами мережі перельотів і влаштовує подорожі та повітряні доставки між столицею Відступників і союзними розпорядниками польотів по всьому Лордерону.",al={"майкл гарретт","майстер кажанів андерсіті","хто такий гарретт"}},{q="Що в Ящику Гордона?",a="У ящику — важливий провіант і польові припаси, які Ґордон Вендгем зібрав у Торговому Кварталі, призначені саме для загонів Відступників у Гробниці в Срібноліссі.",al={"ящик ґордона","які припаси","ящик гробниці"}},{q="Чому кажани, а не вози чи коні?",a="Наземні дороги, що в'ються з Галявин Тірісфалю до Срібнолісся, повні небезпек: там і мандрівні звірі Погибелі, і ворожі люди, і підступна місцевість. Повітряні маршрути на навчених велетенських кажанах набагато швидші й цілком оминають засідки на землі.",al={"чому політ кажанів","чому кажани","літаючі припаси"}},{q="Куди йде вантаж після Майкла Гарретта?",a="Коли Майкл Гарретт отримає Ящик Гордона, вантаж готують до перельоту кажаном просто до розпорядника кажанів у Гробниці в Срібноліссі — так ланцюжок постачання замикається.",al={"наступний крок","після майкла гарретта","куди летять кажани"}},{q="Де в Андерсіті знайти Майкла Гарретта?",a="Він у південно-західній частині Торгового Кварталу — того самого кварталу, де сідають кажани, що прилітають із Гробниці.",al={"де гарретт","знайти кажановодця","де політний майстер андерсіті"}},{q="Чи треба побувати в Гробниці перед цим завданням?",a="Щоб самому полетіти кажаном разом із вантажем, ви маєте заздалегідь поговорити з доглядачем кажанів у Гробниці й відкрити повітряний маршрут; інакше доведеться йти туди пішки.",al={"потрібен маршрут гробниці","чи можна одразу летіти"}}},fp="15,424,22.451.0,21.410.0,23.236.0,26.199.0,40.281.0,49.188.0,48.122.0,60.197.0"}
P.entries["quest:6323"] = {n="Переліт до Андерсіті",s="«Переліт до Андерсіті» знайомить молодих Відступників із повітряною мережею Орди в Лордероні. Везучи запит на зброю з обложеної застави Склеп, гінці летять на жахокажані просто до Торгового Кварталу Андерсіті, щоб поповнити запаси захисників краю.",h="«Переліт до Андерсіті» знайомить молодих Відступників із повітряною мережею Орди в Лордероні.",kw={"переліт до андерсіті","карос разок","ґордон вендгем","жахокажан","склеп","торговий квартал","срібнолісся"},ang={["faction:Horde"]="Розпорядники польотів — сполучна тканина територіального поступу Орди: вони обертають виснажливі переходи глушиною на швидкі тактичні перекидання.",["profession:Blacksmithing"]="Доставивши замовлення Ґордонові Вендгему, коваль бачить сам хребет постачання Лордерона, де кожен шмат заліза тримають гострим і готовим до війни.",["race:Undead"]="Переліт зі Срібнолісся до столиці показує, як далеко простягається й як злагоджено працює мережа Темної Леді: жоден відрізаний гарнізон не лишиться без промислу Андерсіті."},sec={{t="Крила над Срібноліссям",b="Щоб зберігати зв'язок між столицею Відступників і її передовими заставами, потрібен швидкий і надійний транспорт. Карос Разок, доглядач кажанів у Склепі в Срібноліссі, опікується навченими жахокажанами, що переносять гінців і припаси над зараженим краєм. Дорогами никають вороже налаштовані звірі, воргени Місячної Люті й рештки Погибелі, тож піднятися в небо — найбезпечніший і найшвидший спосіб доставити нагальні військові запити до столиці."},{t="Озброїти передову",b="Приземлившись у гамірному Торговому Кварталі Андерсіті, гінець передає запит Подріґа на спорядження просто Ґордонові Вендгему. Цей зброяр Андерсіті, відданий справі Темної Леді, дбає, щоб застави на кшталт Склепу мали справну, готову до бою зброю. Підтримувати ці оборонні осередки конче важливо для молодої держави Відступників, яка закріплює свої кордони проти ворогів довкола."}},faq={{q="Навіщо цей переліт до Андерсіті?",a="Мета — доставити офіційну заявку на зброю від Вартового Смерті Подріґа з Гробниці просто Ґордонові Вендгему, торговцю зброєю з Торгового Кварталу Андерсіті, а заразом навчити нових поборників користуватися мережею перельотів Відступників.",al={"навіщо переліт до андерсіті","мета переліту до андерсіті","призначення наказу подріґа"}},{q="Хто такий Карос Разок?",a="Карос Разок — розпорядник кажанів у Гробниці в Срібноліссі. Він відає сідалом жахливих кажанів, завдяки яким Відступники швидко подорожують і підтримують зв'язок з Андерсіті.",al={"роль кароса разока","хто майстер кажанів гробниці"}},{q="Хто такий Ґордон Вендгем?",a="Ґордон Вендгем — зброяр із Відступників у Торговому Кварталі Андерсіті, поруч із майданчиком, де сідають кажани. Він пишається тим, що зброя в нього завжди чиста, нагострена й готова для передових загонів Леді Сильвани.",al={"ґордон вендгем","де ґордон вендгем"}},{q="Чому Відступники подорожують на кажанах?",a="Жахливі кажани — місцеві нічні хижаки, що добре пасують до осквернених небес Лордерону. Вони стрімко переносять мандрівників над підступними небезпеками внизу — здичавілими воргенами, ворожими гнилошкірими гнолами й Погибеллю.",al={"чому кажани","летючі скакуни відступників"}},{q="Що буде після доставки?",a="Отримавши замовлення, Ґордон Вендгем скеровує кур'єрів до Майкла Гарретта, доглядача кажанів Андерсіті, і так відкривається зворотний маршрут до Гробниці.",al={"що далі","продовження переліту до андерсіті"}},{q="Де в Андерсіті сідає жахливий кажан?",a="Жахливий кажан сідає на піднесене сідало просто посеред Торгового Кварталу Андерсіті, звідки рукою подати до міських ремісників і купців-постачальників.",al={"де сідає кажан андерсіті","де приземляється кажан"}}},fp="21,294,21.489.0,16.446.0,52.261.0,19.198.0,22.239.0,41.202.0,43.166.0,47.181.0"}
P.entries["quest:6324"] = {n="Повернення до Подріґа",s="«Повернення до Подріґа» — завдання з постачання, що завершує мандрівку гінця між Срібноліссям і Андерсіті. Доставивши донесення до столиці, гінець отримує ящик зброї, який має перенести назад до Вартового Смерті Подріґа в Склепі через мережу доглядачів кажанів Відступників.",h="«Повернення до Подріґа» — завдання з постачання, що завершує мандрівку гінця між Срібноліссям і Андерсіті.",kw={"повернення до подріґа","вартовий смерті подріґ","майкл гарретт","карос разок","ящик гордона","склеп","кажани"},ang={["faction:Horde"]="Це завдання показує, як влаштоване постачання, що поєднує Андерсіті з віддаленими заставами на півночі континенту.",["race:Undead"]="Щоб боронити Лордерон і закріпити молоде королівство королеви Сильвани, передові гарнізони конче мають бути озброєні."},sec={{t="Шлях постачання з Андерсіті",b="Застави по всьому Лордерону, щоб діяти, сильно залежать від регулярних поставок з Андерсіті. У Склепі в Срібноліссі вартові смерті відбиваються і від місцевих воргенів, і від решток Даларана, і від уцілілих Погибелі. Забезпечувати віддалені гарнізони свіжою зброєю конче потрібно, щоб край лишався під владою Відступників."},{t="Крила Відступників",b="Майстер кажанів Майкл Гарретт тримає головне сідало в Торговому Кварталі Андерсіті — осередок повітряних подорожей Відступників. Кажани й самі вертаються до столиці, та перш ніж прокласти переліт до далекої застави, вершникам треба домовитися з місцевими доглядачами, як-от Каросом Разоком. Перевезення Ящика Гордона небом Лордерона вчить гінців, як Відступники зв'язують докупи свої розпорошені твердині."}},faq={{q="Що в Ящику Гордона?",a="У ящику — нова зброя, виготовлена в Андерсіті, щоб вартові смерті в Гробниці були як слід озброєні проти навколишніх загроз.",al={"вміст ящика ґордона","що я віддаю подріґу"}},{q="Хто такий Вартовий Смерті Подріґ?",a="Вартовий Смерті Подріґ — воїн Відступників у Гробниці в Срібноліссі, який відає постачанням і обороною місцевого гарнізону.",al={"подріґ","хто такий подріґ"}},{q="Хто такий Майкл Гарретт?",a="Майкл Гарретт — розпорядник кажанів Відступників у Торговому Кварталі Андерсіті, що координує маршрути польотів по всьому Лордерону.",al={"майкл гарретт","майстер кажанів андерсіті"}},{q="Чому перед польотом кудись треба поговорити з розпорядником кажанів?",a="Кажани Відступників самі знають дорогу назад до головного сідала в Андерсіті, але для польотів звідти спершу треба прокласти маршрут із місцевим доглядачем, щоб безпечно дістатися мети.",al={"правила польоту","як працюють кажановоди"}},{q="Чому так важливо постачати Гробницю?",a="Гробниця — головна передова база Відступників у Срібноліссі. Вона тримає їхню військову присутність проти зграй воргенів, загрози з боку Мунрейджів і сил Даларану в цьому краї.",al={"чому гробниця важлива","значення гробниці"}},{q="Хто такий Карос Разок?",a="Карос Разок — розпорядник кажанів у Гробниці в Срібноліссі; він доглядає кажанів, що з'єднують заставу з Андерсіті.",al={"карос разок","майстер кажанів гробниці"}}},fp="16,292,25.353.0,21.419.0,26.156.0,25.154.0,23.151.0,65.183.0,44.178.0,19.143.0"}
P.entries["quest:633"] = {n="Міст Тандол",s="Ця важлива місія Альянсу доручає героям захистити єдиний уцілілий прогін Мосту Тандол. Після підлого вбивства Ебенізера Растлока Раґ Ґармасон розкриває змову зрадника Кама Діпф'юрі: підірвати сховану вибухівку й перерізати життєво важливий зв'язок Айронфорджа з північчю.",h="Ця важлива місія Альянсу доручає героям захистити єдиний уцілілий прогін Мосту Тандол.",kw={"міст тандол","кам діпф'юрі","раґ ґармасон","вибухівка","аратійське нагір'я","темне залізо"},ang={["faction:Alliance"]="Утримати міст конче важливо для безпеки континенту: якщо ця переправа впаде, перекидати війська й ресурси Альянсу в Араті й Лордерон стане незрівнянно небезпечніше.",["profession:Engineering"]="Інженери оцінять нищівну силу схованки Діпф'юрі, приготованої, щоб знести величну дворфійську кладку, гідну титанів.",["race:Dwarf"]="Для синів Айронфорджа оборона Мосту Тандол — захист життєвої артерії Короля Маґні до північних союзників і удар по зрадливих лазутчиках Темного Заліза."},sec={{t="Розкрита змова",b="Після того як у підмурках Мосту Тандол знайдено тіло Ебенізера Растлока, віднайдений документ проливає світло на ще темніші наміри. Підбурювач із Темного Заліза Кам Діпф'юрі, що спланував перше руйнування мосту, ще не закінчив. Обваливши одну з величних кам'яних переправ, його мережа диверсантів заклала другу схованку важкої вибухівки просто за північним кордоном, в Аратійському нагір'ї, щоб довершити справу."},{t="Порятунок життєвої артерії",b="Міст Тандол — головний суходільний коридор, що пов'язує південні королівства Каз Модану й Стормвінда з розтерзаними війною землями півночі. Щоб уберегти цей шлях, Раґ Ґармасон наказує негайно завдати випереджального удару по схованці вибухівки в Араті, перш ніж змовники Діпф'юрі встигнуть пустити її в хід. Підрив вибухівки усуває безпосередню небезпеку й зберігає Айронфорджу доступ на північ, хоча Ґармасонові й досі відчайдушно бракує вояків, щоб боронити пролом."}},faq={{q="Хто такий Кам Діпф'юрі?",a="Кам Діпф'юрі — дворф Темного Заліза, натхненник диверсії на Мосту Тандол. Не вдовольнившись обвалом першої арки, він сховав додаткову вибухівку по той бік прірви, в Аратійському нагір'ї, щоб знищити й решту мосту.",al={"кам діпф'юрі","хто підірвав міст тандол","натхненник мосту тандол"}},{q="Чому Міст Тандол має таке стратегічне значення?",a="Міст — єдина суходільна переправа через величезну прірву між Багнокраєм і Аратійським нагір'ям. Якщо його зруйнують, Альянс утратить головний наземний шлях постачання між Айронфорджем, Стормвіндом і союзниками, що тримаються на півночі Лордерону.",al={"чому міст тандол важливий","переказ про міст тандол"}},{q="Що сталося з Ебенезером Растлоком?",a="Ебенезер Растлок — оборонець Айронфорджа, якого вбили в глибинах під мостом. Саме з його розвідки й паперів, знайдених при тілі, Раґ Ґармасон дізнався про таємну схованку вибухівки Діпф'юрі.",al={"смерть растлока","хто був растлок"}},{q="Де схована вибухівка?",a="Вибухівку сховали по той бік мосту, з боку Аратійського нагір'я, — досить близько, щоб спільники Діпф'юрі могли швидко перенести її до вцілілої частини мосту.",al={"де вибухівка","де сховок вибухівки","місце схованки"}},{q="Хто наказує знищити вибухівку?",a="Раґ Ґармасон, офіцер-дворф, що стоїть біля Мосту Тандол з боку Багнокраю, наказує знайти й знищити схованку, щоб пошанувати жертву Растлока й уберегти решту мосту.",al={"хто починає це завдання","раґ ґармасон"}},{q="Що буде після знищення вибухівки?",a="Безпосередню диверсію зірвано, але Раґ Ґармасон розуміє, що без допомоги його гарнізон не втримає пошкоджений міст довіку. Чекаючи на резерви з Айронфорджа, він надсилає прохання про підкріплення Капітанові Найлсу в табір Альянсу в Притулку на Аратійському нагір'ї.",al={"що далі після мосту тандол","завдання заклик до альянсу"}}},fp="16,308,15.456.0,19.482.1,20.252.0,47.268.0,36.222.1,40.195.0,46.196.0,47.287.1"}
P.entries["quest:634"] = {n="Заклик до Альянсу",s="«Заклик до Альянсу» несе через Міст Тандол до Араті відчайдушне прохання про підкріплення від уцілілих дворфійських захисників Дун Модра. Після різанини гарнізону, яку влаштували лазутчики Темного Заліза, дворфи шукають допомоги в людських сил у Притулку — і з'ясовують, що Альянс розтягнуто понад межі можливого.",h="«Заклик до Альянсу» несе через Міст Тандол до Араті відчайдушне прохання про підкріплення від уцілілих...",kw={"заклик до альянсу","капітан найлс","раґ ґармасон","притулок","стромґард","міст тандол"},ang={["faction:Alliance"]="Ця розмова підкреслює, наскільки розколотим лишається Альянс на півночі Східних Королівств, де місцеві гарнізони ведуть окремі відчайдушні битви без спільних резервів.",["race:Dwarf"]="Для дворфів ця місія показує болючу відрізаність північних гарнізонів на кшталт Дун Модра: навіть давні союзники-люди надто обложені, щоб подати руку допомоги.",["race:Human"]="Мандрівники-люди бачать гірку скорботу Капітана Найлс, яка розривається між вірністю братерству Альянсу й боротьбою за виживання загиблого Стромґарда."},sec={{t="Крик через прірву",b="Після спустошення Дун Модра й диверсії на Мосту Тандол, які вчинили дворфи Темного Заліза, уцілілі дворфи ледве тримаються на північному краю Багнокраю. Поки головні резерви Айронфорджа ще не прибули, Раґ Ґармасон і командир Лонґбрейд звертають погляди на північ, до Аратійського нагір'я. Дізнавшись про табір Альянсу в Притулку, Ґармасон посилає вісника через зруйнований міст — благати Капітана Найлс про негайну військову допомогу."},{t="Біда Стромґарда",b="Діставшись Притулку, посланець бачить сувору дійсність північного Альянсу. Капітан Найлс щиро співчуває воякам Лонґбрейда, але не може виділити жодного бійця. Сам Стромґард лежить у руїнах, заполонений розбійниками Синдикату, огрями-Каменекулаками й тролями-Сухокорими. Уцілілі захисники Стромґарда цілком віддані боротьбі за свою прадідівську столицю. Скута честю й власним відчайдушним становищем, Найлс мусить передати у відповідь, що дворфи біля мосту мають вистояти самі."}},faq={{q="Хто надсилає прохання до Притулку?",a="Раґ Ґармасон, що стоїть біля зруйнованого предмостя Мосту Тандол на межі Багнокраю, надсилає прохання від імені командувача Лонґбрейди та решти оборонців Дун Модра.",al={"хто дає заклик до альянсу","завдання раґа ґармасона","хто просить допомоги"}},{q="Навіщо дворфам допомога з Притулку?",a="Дун Модр упав під раптовим і жорстоким натиском лазутчиків клану Темного Заліза, які також підірвали Міст Тандол. Поки вцілілі чекають на важкі резерви з Айронфорджа, їх надто мало, щоб самотужки відбити поселення й убезпечити переправу.",al={"навіщо дворфам допомога","чому просити притулок","підкріплення дун модра"}},{q="Чому Капітан Найлс відмовляється надіслати солдатів?",a="Капітан Найлс не може виділити жодного вояка, бо королівство Стромґард і саме лежить у руїнах. Людські сили в Притулку цілком зайняті відчайдушною кампанією, щоб відвоювати Стромґард у Синдикату, огрів і лісових тролів.",al={"чому немає допомоги від найлса","чому притулок відмовляє","відповідь капітана найлса"}},{q="Де розташований Притулок?",a="Притулок лежить неподалік головної дороги в центрі Аратійського нагір'я, на північ від переправи через Міст Тандол між Багнокраєм і Араті.",al={"де притулок","де капітан найлс","як знайти притулок"}},{q="Що сталося з Дун Модром?",a="Дун Модр захопив і пограбував клан Темного Заліза, що пробрався горами, аби перерізати суходільний шлях між південними дворфійськими землями й північними володіннями Альянсу.",al={"переказ про дун модр","що сталося з дун модром","хто напав на дун модр"}},{q="Що буде після того, як Капітан Найлс відмовить?",a="Капітан Найлс передає свої жалі командувачеві Лонґбрейді, підтверджуючи, що підкріплення від людей не буде. Вцілілим дворфам біля мосту доведеться покладатися на власну кмітливість, мандрівних шукачів пригод і далекі резерви з Айронфорджа.",al={"що далі після заклику до альянсу","наступне завдання після заклику","продовження ланцюжка"}}},fp="20,349,22.483.0,24.543.0,36.183.0,48.264.0,47.248.0,31.142.0,26.194.0,56.233.0"}
P.entries["quest:6341"] = {n="Дари Тельдрассила",s="«Дари Тельдрассила» — вступне доручення від Несси Шедовсонг у Селищі Рут'теран. Прагнучи порівняти незвичайний розмір і чисельність острівної риби з тією, що ловиться біля материка, вона готує збірку кісток і луски, щоб переслати через протоку на Темне Узбережжя. Передати цей пакунок місцевому доглядачеві гіпогрифів — перший крок до переправи через море в Обердайн.",h="«Дари Тельдрассила» — вступне доручення від Несси Шедовсонг у Селищі Рут'теран.",kw={"дари тельдрассила","несса шедовсонг","селище рут'теран","веспристус","лейрд","гіпогрифи"},ang={["faction:Alliance"]="Шлях між Рут'тераном і Обердайном — важлива транспортна артерія, що з'єднує столицю нічних ельфів з рештою північного Калімдору.",["race:NightElf"]="Для мандрівників із нічних ельфів ця подорож — традиційний перехід із безпечних висот Тельдрассилу на затінені материкові береги Темного Узбережжя."},sec={{t="Дослідження рибалки",b="Під велетенським гіллям Світового Дерева захищені води довкола Селища Рут'теран кишать напрочуд великою й численною морською живністю. Несса Шедовсонг, спостерігаючи за дивовижними уловами місцевих рибалок, хоче з'ясувати, чи ця життєва сила сягає давніх материкових берегів, чи властива лише водам, які живить Тельдрассил. Щоб перевірити свою гіпотезу, вона готує збірку луски й кісток для Лейрда — колеги-торговця рибою з Обердайна по той бік води."},{t="Як переправитися",b="Щоб переправляти вантажі й мандрівників через відкриту протоку між острівним гіллям і материком Калімдору, потрібні надійні крила. Замість відсилати пакунок невеликим човном Несса скеровує мандрівників просто до Веспристуса — селищного майстра гіпогрифів. Передавши йому збірку, мандрівники домовляються про все потрібне, щоб осідлати навченого звіра й доставити зразки просто до пристаней Темного Узбережжя."}},faq={{q="Що намагається з'ясувати Несса?",a="Несса Шедовсонг помітила, що риба з вод довкола Селища Рут'теран надзвичайно велика й рясна. Вона хоче відправити через море зразки кісток і луски, щоб порівняти улов Тельдрассилу з рибою з материкових берегів Темного Узбережжя.",al={"мета несси","навіщо порівнювати рибу","мета дарів тельдрассила"}},{q="Хто в Обердайні отримує зразки риби?",a="Збірка адресована Лейрдові, торговцеві рибою в прибережному селищі Обердайн на материковому березі Темного Узбережжя.",al={"хто отримає збірку несси","лейрд темне узбережжя","торговець рибою оберіжин"}},{q="Чому треба віднести посилку Веспристусові, а не йти просто до Обердайна?",a="Веспристус — розпорядник гіпогрифів у Селищі Рут'теран. Віддавши збірку йому, ви влаштуєте повітряне перевезення й зможете перелетіти на гіпогрифі через море до Темного Узбережжя.",al={"чому веспристус","хто такий веспристус","майстер гіпогрифів рут'теран"}},{q="Де розташоване Селище Рут'теран щодо Тельдрассилу?",a="Селище Рут'теран лежить біля південного підніжжя Тельдрассилу, на рівні моря, і з'єднане з Дарнасусом смарагдовим порталом. Це головна прибережна гавань для кораблів і гіпогрифів, що прибувають до великого дерева й вирушають від нього.",al={"де рут'теран","де несса","як дістатися рут'терана"}},{q="Що буде, коли віддати збірку Веспристусові?",a="Веспристус приймає збірку й пропонує наступне завдання — «Політ до Обердайна»: на спині гіпогрифа ви злетите над протокою просто до Темного Узбережжя.",al={"політ до оберіжина далі","після дарів тельдрассила","що робить веспристус"}},{q="Чи це частина виходу нічних ельфів зі стартової зони?",a="Так. Цей ланцюжок знайомить молодих шукачів пригод із нічних ельфів із маршрутами польотів і веде їх з острівних крон униз, на материковий Калімдор, щоб вони продовжили мандри на Темному Узбережжі.",al={"вихід із тельдрассила","завдання нічного ельфа 10 рівня","переїзд на темне узбережжя"}}},fp="24,405,19.514.0,17.410.0,36.280.0,47.133.0,77.202.0,62.236.0,55.178.0,58.182.0"}
P.entries["quest:6342"] = {n="Політ до Обердайна",s="Це доручення знайомить шукачів пригод, що вирушають із Тельдрассилу, з повітряною мережею сполучення нічних ельфів. На прохання майстра гіпогрифів Веспристуса в Селищі Рут'теран мандрівники летять через море, щоб доставити пакунок із надзвичайно великими морськими зразками Лейрдові в Обердайн.",h="Це доручення знайомить шукачів пригод, що вирушають із Тельдрассилу, з повітряною мережею сполучення нічних...",kw={"політ до обердайна","веспристус","гіпогрифи","селище рут'теран","лейрд","тельдрассил"},ang={["faction:Alliance"]="Гіпогрифи — головна повітряна мережа Альянсу на півночі Калімдору, що з'єднує прибережні застави безпосередньо зі столицею.",["race:NightElf"]="Політ на гіпогрифі до Обердайна — знаковий обряд переходу для молодих калдореїв, що ступають із Тельдрассилу на материк своїх предків."},sec={{t="На крилах до Темного Узбережжя",b="Для багатьох молодих шукачів пригод, що покидають гілля Тельдрассилу, Селище Рут'теран — поріг між прихистком і широким світом. Протокою між острівною гаванню й материком Калімдору курсує звичайний пором, але нічні ельфи так само покладаються на своїх вірних гіпогрифів. Отримавши від Несси Шедовсонг пакунок із рідкісними частинами риби, мандрівники сідають на одного з цих крилатих звірів і відкривають свій найперший шлях польоту — на береги Темного Узбережжя."},{t="Дивний улов",b="Сама доставка дуже цікавить рибалок Темного Узбережжя. Лейрд, що чекає на знахідки Несси на пристанях Обердайна, оглядає улов і знаходить величезні лусочки завбільшки з кулак і щелепу майже вдвічі більшу, ніж у материкових зразків. Острівні води біля підніжжя Світового Дерева, схоже, породжують змінене чи ненормально велике життя — дивина, що натякає на могутню, неспокійну природу самого Тельдрассилу."}},faq={{q="Навіщо цей політ?",a="Подорож — практичний урок, як з'єднувати маршрути польотів між поселеннями, а заразом спосіб доставити Лейрдові в Обердайн зразки незвичайної риби, виловленої біля Селища Рут'теран.",al={"навіщо летіти до оберіжина","мета польоту до оберіжина","навіщо політ"}},{q="Хто надсилає посилку і що в ній?",a="Посилку надсилає рибалка Несса Шедовсонг. У ній — зразки риби з вод довкола Селища Рут'теран, зокрема величезна луска й завелика щелепна кістка.",al={"збірка несси","що в посилці","хто надіслав посилку"}},{q="Чому риба з Тельдрассилу така велика?",a="Лейрд зауважує, що щелепа майже вдвічі більша за звичайну, а луска — завбільшки з кулак. Води довкола Світового Дерева Тельдрассил чомусь роблять живих істот більшими, ніж на материкових берегах Темного Узбережжя.",al={"чому риба велика","розмір риби рут'терана","величезна луска"}},{q="Хто такий Веспристус?",a="Веспристус — розпорядник гіпогрифів у Селищі Рут'теран. Він доглядає скакунів нічних ельфів і влаштовує перельоти через море до материкового Калімдору.",al={"переказ про веспристуса","хто майстер гіпогрифів"}},{q="Хто такий Лейрд?",a="Лейрд — рибалка з нічних ельфів, що живе в Обердайні на Темному Узбережжі. Він вивчає місцеве водяне життя й порівнює материкові улови з тими, що виловлені біля Тельдрассилу.",al={"переказ про лейрда","хто такий лейрд","лейрд темне узбережжя"}},{q="Чи можна дістатися з Рут'терана до Обердайна без польоту?",a="Так. Між причалами Селища Рут'теран і пристанню Обердайна регулярно ходить пором — це альтернатива перельоту на гіпогрифі.",al={"корабель до оберіжина","пором на темне узбережжя","інший шлях до оберіжина"}}},fp="19,272,24.467.0,15.428.0,35.198.0,44.182.0,42.226.0,18.169.0,13.174.0,63.147.0"}
P.entries["quest:6343"] = {n="Повернення до Несси",s="Це завдання посилає молодих мандрівників з Обердайна назад до Селища Рут'теран, щоб передати Нессі Шедовсонг висновки Лейрда. Воно завершує вступне доручення, що вчить шукачів пригод переправлятися між материком Калімдору й Тельдрассилом.",h="Це завдання посилає молодих мандрівників з Обердайна назад до Селища Рут'теран, щоб передати Нессі Шедовсонг...",kw={"повернення до несси","несса шедовсонг","лейрд","кейлайс мунфезер","селище рут'теран","пором"},ang={["faction:Alliance"]="Обердайн і Селище Рут'теран — важливі морські ворота, що пов'язують поселення нічних ельфів на півночі Калімдору з ширшими інтересами Альянсу по всьому Азероту.",["race:NightElf"]="Для нічних ельфів, що вперше вирушають із гілля Тельдрассилу, цей обмін — перше офіційне доручення, яке пов'язує новий острівний прихисток із давнім материком Темного Узбережжя."},sec={{t="Посланець через море",b="Доставивши перші запитання Несси Шедовсонг Лейрдові в Обердайн, мандрівники мають віднести його письмові спостереження назад через воду. Лейрд зауважує разючі відмінності між уловом біля Темного Узбережжя й біля берегів Тельдрассилу й підозрює, що саме велике Світове Дерево змінює місцеве морське життя. Щоб повернутися до Селища Рут'теран, шукачі пригод можуть або найняти політ у майстрині гіпогрифів Кейлайс Мунфезер, або сісти на пором, що регулярно ходить від пристані Обердайна."},{t="Дивні щедроти",b="Отримавши відповідь Лейрда в Селищі Рут'теран, Несса захоплюється помітною різницею в морському житті. Величезна риба біля Світового Дерева — неабияке благо для місцевих рибалок, але її справжня причина лишається для калдореїв відкритим питанням. Несса вирішує поділитися знахідками з односельцями: поки що вона задоволена щедрим уловом, але пильно стежить, які сили насправді за цим стоять."}},faq={{q="Хто дає і хто приймає це завдання?",a="Завдання дає рибалка Лейрд в Обердайні на Темному Узбережжі. Здати його треба Нессі Шедовсонг у Селищі Рут'теран, біля підніжжя Тельдрассилу.",al={"хто дає завдання","де здати","хто видає завдання"}},{q="Як найшвидше повернутися до Селища Рут'теран?",a="Можна або швидко перелетіти гіпогрифом, поговоривши з Кейлайс Мунфезер в Обердайні, або вийти на довгу пристань і сісти на звичайний пасажирський пором до причалів Селища Рут'теран.",al={"як повернутися","дорога до рут'терана","пором чи гіпогриф"}},{q="Навіщо Лейрд вивчає рибу?",a="Лейрд помічає, що морські улови біля Темного Узбережжя разюче відрізняються від тих, що добувають довкола Тельдрассилу. Він підозрює, що бурхливе зростання й особлива енергія Світового Дерева безпосередньо змінюють навколишню живність.",al={"навіщо вивчати рибу","чим відрізняється риба","відповідь лейрда"}},{q="Чи дізнається Несса, чому риба така дивна?",a="Не одразу. Несса відзначає разючу різницю й погоджується, що це варто дослідити, але поки що задовольняється тим, що ділиться звісткою з місцевими й тішиться щедрими уловами.",al={"чому риба велика","таємниця риби тельдрассила"}},{q="Що передує цьому завданню?",a="Це завдання йде одразу після «Польоту до Обердайна», у якому мандрівники вирушають із Селища Рут'теран на Темне Узбережжя з первісним листом Несси до Лейрда.",al={"попереднє завдання","завдання перед цим","політ до оберіжина"}},{q="Навіщо цей ланцюжок завдань?",a="Окрім того, що він розповідає про загадковий вплив Тельдрассилу на місцеву природу, цей ланцюжок доставок — обряд посвяти, що вчить молодих шукачів пригод із нічних ельфів подорожувати між рідним островом і материковим Калімдором кораблем і з розпорядником польотів.",al={"навіщо це завдання","завдання з подорожжю"}}},fp="15,253,26.515.0,16.478.0,36.166.0,51.205.0,31.234.0,48.213.0,29.153.0,40.267.0"}
P.entries["quest:6344"] = {n="Несса Шедовсонг",s="«Несса Шедовсонг» — вступне завдання-доручення від Мідраннула в Дарнасусі. Воно веде молодих шукачів пригод зі Світового Древа вниз, до Селища Рут'теран, на зустріч із торговкою рибальським приладдям Нессою Шедовсонг. Це перший крок, що пов'язує столицю в кронах із берегами й гаванями внизу.",h="«Несса Шедовсонг» — вступне завдання-доручення від Мідраннула в Дарнасусі.",kw={"несса шедовсонг","мідраннул","селище рут'теран","тельдрассил","обердайн","портал","гіпогрифи"},ang={["faction:Alliance"]="Це доручення знайомить із важливою мережею постачання, що пов'язує відрізаний острів Тельдрассил з рештою земель Альянсу в Калімдорі.",["race:NightElf"]="Для шукачів пригод із нічних ельфів ця подорож — традиційний вихід зі спокійних висот Дарнасуса на жваві прибережні шляхи, що поєднують їхній новий дім із давніми берегами Темного Узбережжя."},sec={{t="Доручення за межами крон",b="У Дарнасусі Мідраннул придивляється до мандрівників, що шукають роботи й мети. Коли торговці рибальським приладдям Нессі Шедовсонг треба переправити пакунок через море на Темне Узбережжя, Мідраннул скеровує здібних гінців до узбережжя. Чимало молодих нічних ельфів проводять перші мандри цілком у гіллі Тельдрассилу, а це просте прохання спонукає їх поглянути назовні, на материк."},{t="Спуск до пристані",b="Щоб дістатися Селища Рут'теран, треба ступити крізь сяйливе коріння західного порталу міста біля Храмових Садів. Ця брама спускається крізь Світове Древо до його коренів на рівні океану, де рибальські причали й сідала гіпогрифів пов'язують Тельдрассил з рештою Калімдору. Там Несса Шедовсонг порядкує своєю справою й готує вантажі для портового поселення Обердайн."}},faq={{q="Хто дає це завдання?",a="Завдання дає Мідраннул, що перебуває в Дарнасусі, на Терасі Воїна.",al={"хто дає завдання","де взяти завдання несси шедовсонг","де мідраннул"}},{q="Як дістатися до Селища Рут'теран?",a="Ідіть на захід від Храмових Садів у Дарнасусі. Ступіть у великий сяйний портал у дереві — і миттєво опинитеся внизу, у Селищі Рут'теран біля підніжжя Тельдрассилу.",al={"як дістатися рут'терана","портал рут'теран","вихід із дарнасуса"}},{q="Хто така Несса Шедовсонг?",a="Несса Шедовсонг — ельфійська постачальниця рибальського приладдя на причалах Селища Рут'теран. Вона наглядає за товарами й посилками, що курсують між Тельдрассилом і материковим Темним Узбережжям.",al={"роль несси шедовсонг","що робить несса","несса шедовсонг"}},{q="Куди веде цей ланцюжок завдань?",a="Розмова з Нессою одразу веде до завдання «Дари Тельдрассила», яке знайомить шукачів пригод із розпорядником польотів і дарує їм перший переліт через море до Обердайна.",al={"що після несси шедовсонг","наступне завдання ланцюжка","ланцюжок польотів тельдрассила"}},{q="Чи Несса родичка Маєв Шедовсонг?",a="Хоча в них спільне прізвище Шедовсонг, жодного відомого родинного зв'язку між Нессою, скромною торговкою рибою з пристані, і легендарною наглядачкою Маєв Шедовсонг немає.",al={"несса і маєв","родина шедовсонг","чи несса родичка маєв"}},{q="Чому це доручення важливе для молодих шукачів пригод?",a="Це головний дороговказ, що вчить нових героїв, як вибратися з крони Тельдрассилу, знайти причали внизу й навчитися літати гіпогрифами до материкового Калімдору.",al={"навіщо це завдання","значення завдання"}}},fp="16,310,26.391.0,23.390.0,22.85.0,35.171.0,24.179.0,33.183.0,37.175.0,51.198.0"}
P.entries["quest:6361"] = {n="Оберемок шкур",s="«Оберемок шкур» — вступне доручення з доставки в Пустках, яке дає таурен Джахан Гоквінг на Перехресті. Він просить мандрівників переправити вичинені шкури дичини через центральний Калімдор до Тандер Блафа для шкірників. Доручення знайомить нових гінців Орди із сідалом вітрокрилів на Перехресті й тим, як влаштовані перельоти.",h="«Оберемок шкур» — вступне доручення з доставки в Пустках, яке дає таурен Джахан Гоквінг на Перехресті.",kw={"оберемок шкур","джахан гоквінг","деврак","тандер блаф","вітрокрили","перехрестя"},ang={["faction:Horde"]="Ця доставка показує сполучення між базами Орди в Калімдорі, яке тримається на оркських приборкувачах звірів на кшталт Деврака, що долають відстані між союзними землями.",["race:Tauren"]="Для тауренів-мандрівників це доручення втілює давнє партнерство між мисливцями, що мандрують родовими Пустками, і майстрами, що осіли на великих столових горах Тандер Блафа."},sec={{t="Торгівля через савану",b="Перехрестя — гамірне серце торгівлі й подорожей по всіх Пустках, що поєднує орків, тролів і тауренів на посушливих рівнинах. Мисливці постійно здобувають шкури й м'ясо мандрівних звірів савани, але місцевим заставам бракує майстерень, щоб обробити всю сировину на місці. Джахан Гоквінг збирає шкури з навколишніх полювань і покладається на мандрівників, які доправлять їх на захід, до Тандер Блафа, де майстри-шкірники виготовлять потрібне Орді спорядження."},{t="У небо",b="Нести важкий вантаж пішки суворими стежками Пусток і далі вгору до Малгора — виснажлива подорож, повна засідок шипогривів і хижаків. Щоб пришвидшити торгівлю, Джахан скеровує гінців просто до Деврака, господаря вітрокрилів на Перехресті. Довіривши вантаж Девракові й злетівши на навченій виверні, гонець бачить, яка важлива мережа сполучення поєднує розкидані поселення Орди."}},faq={{q="Хто дає завдання «Оберемок шкур»?",a="Завдання дає Джахан Гоквінг, таурен із Перехрестя в Пустках. Він зібрав шкури місцевих звірів і шукає надійного кур'єра, який допоможе доправити їх до Тандер Блафа.",al={"хто дає оберемок шкур","видавець завдання","де взяти оберемок шкур"}},{q="Кому віднести оберемок шкур?",a="Оберемок треба віднести просто Девракові — орку, господареві вітрокрилів на сідалі Перехрестя. Він відає повітряним сполученням між Перехрестям та іншими головними осередками Орди.",al={"кому віднести шкури","куди нести шкури","з ким говорити"}},{q="Що буде, коли віддати шкури Девракові?",a="Деврак дає наступне завдання: сісти на вітрокрила й доправити вантаж просто до Агану, шкірника, що чекає на високих кручах Тандер Блафа.",al={"наступне завдання","що після оберемка шкур","продовження завдання"}},{q="Навіщо ці шкури везуть до Тандер Блафа?",a="Джахан Гоквінг співпрацює з товаришем на ім'я Агану з Тандер Блафа, який перетворює сирі шкури дичини з Пусток на готові шкіряні обладунки й вироби для тауренів та їхніх союзників з Орди.",al={"чому тандер блаф","шкури агану","для чого шкури"}},{q="Навіщо вітрокрил, а не пішки?",a="Іти пішки через безкраї Пустки й видиратися на величезну столову гору Тандер Блафа — довго й небезпечно. Вітрокрил швидко й безпечно перенесе вас над ворожими звірами савани та зграями шипогривів.",al={"чому летіти на вітрокрилі","політ вітрокрилом"}},{q="Чи потрібен для цього досвід польотів?",a="Це завдання задумане як раннє знайомство шукачів пригод Орди з розпорядниками польотів: воно знайомить вас із сідалом Деврака, щоб ви могли літати на вітрокрилах на далекі відстані.",al={"вимога польоту","чи потрібен маршрут польоту"}}},fp="17,347,24.480.0,19.410.0,38.193.0,42.185.0,46.168.0,48.184.0,40.212.0,49.202.0"}
P.entries["quest:6362"] = {n="Переліт до Тандер Блафа",s="Це завдання відправляє молодих шукачів пригод Орди в перший політ на вітрокрилі над Калімдором. Отримавши вантаж вичинених шкур, мандрівники вирушають із сухого роздоріжжя Пусток, щоб доставити цінні матеріали для шкірництва просто на висоти Тандер Блафа.",h="Це завдання відправляє молодих шукачів пригод Орди в перший політ на вітрокрилі над Калімдором.",kw={"переліт до тандер блафа","вітрокрил","деврак","агану","зброярня геви","шкури","тандер блаф"},ang={["faction:Horde"]="Надійні перельоти на вітрокрилах — запорука того, що віддалені застави в Пустках пов'язані з головними твердинями Дуротару й Малгору.",["race:Tauren"]="Для юних тауренів, що повертаються з Пусток, цей політ — легкий підйом просто на височенні кручі величної столиці їхнього народу."},sec={{t="Крила над саваною",b="Для багатьох мандрівників, що прямують Пустками, переліт, замовлений у Деврака, — перша подорож небом на спині вітрокрила. Ці крилаті виверни забезпечують життєво важливе повітряне сполучення між розкиданими поселеннями молодої Орди, оминаючи небезпечні наземні шляхи, де никають шипогриви й зграї кентаврів."},{t="Шкури для зброярні",b="Вантаж — це в'язка вичинених шкур, приготованих у Пустках і призначених для Агану, майстра, що працює в Зброярні Геви в Тандер Блафі. Агану, що влаштувався просто під великим гніздовищем вітрокрилів на центральній столовій горі, покладається на сировину з мисливських застав на рівнинах, щоб спорядити місцевих воїнів і мисливців."}},faq={{q="Хто дає завдання «Переліт до Тандер Блафа»?",a="Деврак, господар вітрокрилів на Перехресті в Пустках, дає це завдання мандрівникам, які принесли оберемок шкур.",al={"хто дає переліт до тандер блафа","де почати переліт до тандер блафа","де деврак"}},{q="Хто такий Агану і де його знайти?",a="Агану — таурен-ремісник у Зброярні Геви в Тандер Блафі, просто біля підніжжя міського сідала вітрокрилів.",al={"де агану","місце агану","збройова хеви"}},{q="Що перевозять у цій доставці?",a="Ви везете оберемок вичинених шкур із Пусток, які Агану одразу пустить на шкіряні вироби й обладунки.",al={"що я доставляю","оберемок шкур"}},{q="Навіщо вітрокрили, а не пішки?",a="Wind riders fly directly across the Barrens to Thunder Bluff's high mesas, avoiding the longer ground journey into Mulgore and landing at the city's wind rider tower.",al={"чому вітрокрили","користь маршруту польоту"}},{q="Де починається цей ланцюжок доставок?",a="Доставка починається з Джахана Гоквінга на Перехресті, який готує оберемок вичинених шкур у попередньому завданні — «Оберемок шкур».",al={"попереднє завдання","ланцюжок шкур"}},{q="Що далі, після доставки шкур?",a="Отримавши шкури, Агану скеровує мандрівників нагору — до Тала, Господаря Вітрокрилів Тандер Блафа.",al={"наступне завдання","продовження переліту до тандер блафа"}}},fp="21,284,25.339.0,20.343.0,42.141.0,39.134.0,43.148.0,39.166.0,37.143.0,43.127.0"}
P.entries["quest:6363"] = {n="Тал, господар вітрокрилів",s="«Тал, господар вітрокрилів» — просте доручення гінця, що пов'язує шкірників Малгору з торговцями в Пустках. Шкірник Агану довіряє вам пакунок готових шкіряних виробів, який треба відправити повітрям із Тандер Блафа. Доставляючи його просто до Тала, розпорядника польотів на столовій горі, молоді мандрівники Орди знайомляться з мережею перельотів на вітрокрилах.",h="«Тал, господар вітрокрилів» — просте доручення гінця, що пов'язує шкірників Малгору з торговцями в Пустках.",kw={"тал","господар вітрокрилів","агану","джахан гоквінг","перехрестя","вітрокрили","тандер блаф"},ang={["faction:Horde"]="Надійні повітряні шляхи між Пустками й Тандер Блафом дають змогу швидко перекидати підкріплення, товари й послання через центральний Калімдор.",["race:Tauren"]="Вітрокрили, що гніздяться на кручах Тандер Блафа, — життєво важлива ланка, яка вплітає відокремлений народ Кайрна Бладгуфа в ширший союз Орди."},sec={{t="Припаси для Перехрестя",b="Торгівля між Малгором і посушливими чагарниками Пусток життєво важлива для молодої Орди. Агану, шкірник, що продає свої вироби на нижньому узвишші Тандер Блафа, виготовляє міцні шкіряні речі для торгової ятки Джахана Гоквінга на Перехресті. Пішки дорога вниз із круч і через золоті рівнини забирає години, тож торговці покладаються на крилатих гінців, щоб ті переносили крихкі чи термінові пакунки через скелясті перевали."},{t="Господар гніздовища на столовій горі",b="На найвищому центральному ярусі Тандер Блафа Тал доглядає міську зграю вітрокрилів, яких також називають вивернами. Ці розумні звірі зі шкірястими крилами напрочуд добре пристосовані до мінливих висхідних потоків і скелястих вершин Калімдору. Тал організовує перельоти до застав, як-от Перехрестя, дбаючи, щоб гінці й вантажі швидко переміщалися між столицею тауренів і їхніми союзниками-орками."}},faq={{q="Хто такий Тал?",a="Тал — розпорядник польотів Тандер Блафа, що відає сідалом вітрокрилів на центральній столовій горі. Він влаштовує перельоти для мандрівників і кур'єрів до Пусток і далі.",al={"хто такий тал","тал тандер блаф","майстер вітрокрилів тал"}},{q="Хто такий Агану?",a="Агану — таурен-шкірник із Тандер Блафа. Він виготовляє великі партії шкіряних виробів і пакує їх для торговців на заставах по всьому Калімдору, зокрема для Джахана Гоквінга на Перехресті.",al={"агану","хто такий агану","агану тандер блаф"}},{q="Навіщо везти товари на Перехрестя?",a="Перехрестя — життєво важливий торговий і військовий вузол Пусток. Товари, виготовлені в мирному затишку Малгора, як-от шкури й шкіряний одяг, відправляють туди, щоб забезпечити мандрівників, мисливців і патрулі Орди.",al={"чому перехрестя","шкіряні вироби перехрестя","джахан шкіра"}},{q="Чи можу я полетіти з цією посилкою просто на Перехрестя?",a="Полетіти на Перехрестя можна лише тоді, коли ви вже побували в поселенні й познайомилися з Девраком, тамтешнім господарем вітрокрилів. Якщо цей маршрут ще не відкрито, доведеться йти пішки.",al={"чи можна летіти на перехрестя","маршрут тала","як летіти на перехрестя"}},{q="Хто такі вітрокрили?",a="Вітрокрили, яких зазвичай звуть вивернами, — розумні отруйні крилаті хижаки, що живуть у скелях Калімдору. Від часів Третьої війни вони союзники Орди й слугують їй головними летючими скакунами.",al={"віверни","що таке вітрокрил","скакуни тауренів"}},{q="Куди веде це кур'єрське доручення далі?",a="Коли ви доставите товари Талові, він доручить вам узяти вітрокрила й доправити посилку Агану через рівнини до Джахана Гоквінга, що чекає на Перехресті.",al={"наступне завдання","що після тала","куди шкіряні вироби далі"}}},fp="25,339,27.439.0,26.421.0,11.198.0,13.208.0,46.235.0,54.220.0,21.204.0,41.159.0"}
P.entries["quest:6364"] = {n="Повернення до Джахана",s="«Повернення до Джахана» — останній відрізок знайомства з мережею перельотів Орди на вітрокрилах між Малгором і Пустками. Доставивши шкури шкірникові Агану в Тандер Блаф, мандрівники летять на виверні назад на Перехрестя з готовими шкіряними виробами для торговця Джахана Гоквінга.",h="«Повернення до Джахана» — останній відрізок знайомства з мережею перельотів Орди на вітрокрилах між Малгором...",kw={"повернення до джахана","джахан гоквінг","агану","тал","вітрокрили","перехрестя","червоні скелі"},ang={["faction:Horde"]="Повітряні шляхи вітрокрилів між Малгором, Дуротаром і Пустками — життєво важливі артерії, що з'єднують володіння Орди в центральному Калімдорі.",["race:Tauren"]="Торгові ланцюжки між чинбарями Малгору й заставами Пусток показують, як об'єднані племена підтримують ширше освоєння прикордоння Ордою."},sec={{t="Крила над Калімдором",b="Для багатьох мандрівників це доручення — перший досвід польоту на навченому вітрокрилі. Тал, господар вітрокрилів, що оселився на центральній столовій горі Тандер Блафа, влаштовує перельоти над рівнинами центрального Калімдору. Якщо мандрівник уже знайомий із гніздовищем в іншому поселенні — як-от заставою Деврака на Перехресті, — ці крилаті звірі без зусиль долають ліги, які інакше довелося б іти небезпечним суходолом через Червоні Скелі й північ Пусток."},{t="Торгівля Перехрестя",b="Цей рейс гінця має й господарську мету, а не лише навчання польотам. Джахан Гоквінг торгує в гамірному поселенні Перехрестя, де щодня збираються мисливці, розвідники й найманці. Сирі шкури, надіслані до Агану на високі узвишшя Тандер Блафа, перетворюються на міцні обладунки й спорядження, а тоді повертаються повітрям на запилене роздоріжжя Пусток, щоб забезпечити прикордонні зусилля Орди, що невпинно ширяться."}},faq={{q="Хто такий Джахан Гоквінг?",a="Джахан Гоквінг — купець-таурен на Перехресті в Пустках. Він купує й продає шкіряні вироби й покладається на ремісників із Тандер Блафа, які перетворюють сирі шкури звірів на цінне спорядження для мандрівних шукачів пригод.",al={"джахан","переказ про джахана гоквінга","хто такий джахан"}},{q="Чому назад на Перехрестя треба летіти вітрокрилом?",a="Ця подорож показує, як працює мережа польотів. Господарі вітрокрилів, як-от Тал у Тандер Блафі, можуть відправляти кур'єрів і пасажирів лише до поселень, які самі розвідали чи з якими встановили зв'язок, — наприклад, до сідала Деврака на Перехресті.",al={"чому летіти назад","вітрокрил назад","як працюють маршрути польоту"}},{q="Хто такий Агану?",a="Агану — вправний шкірник і білувальник на високих кручах Тандер Блафа. Він приймає сирі шкури від мисливців із Пусток, робить із них готові вироби й відсилає назад на продаж.",al={"агану","агану тандер блаф","хто зробив вироби"}},{q="Хто такий Деврак?",a="Деврак — орк, господар вітрокрилів на Перехресті. Він відає сідалом, що з'єднує Пустки з головними твердинями Орди — Оргріммаром і Тандер Блафом.",al={"деврак","майстер польотів перехрестя","майстер вітрокрилів деврак"}},{q="Чи можна летіти на вітрокрилі, не поговоривши спершу з господарем у місці призначення?",a="Ні. Вітрокрилів можна відправити лише до застав, де мандрівник уже зустрівся з місцевим господарем вітрокрилів і відмітився в нього, — так встановлюється зв'язок між сідалами.",al={"правила польоту","відкрити майстра польотів","чи можна летіти куди завгодно"}},{q="Що буде, коли повернути шкіряні вироби Джаханові?",a="Доставка готових виробів завершує кур'єрський ланцюжок між Малгором і Пустками: мандрівники вже знають, як подорожувати повітрям, і можуть далі допомагати гарнізону й купцям Перехрестя.",al={"продовження завдання","що далі","після повернення до джахана"}}},fp="15,313,19.511.0,26.408.0,22.219.0,58.249.0,13.212.0,14.179.0,74.176.0,56.211.0"}
P.entries["quest:6365"] = {n="М'ясо до Оргріммара",s="«М'ясо до Оргріммара» — коротке вступне доручення з доставки від Зарга на Перехресті. Він просить молодих шукачів пригод — орків і тролів — віднести пакунок добірного м'яса з Пусток господареві вітрокрилів у поселенні, Девракові, і так знайомить їх із перельотами назад до столиці Орди.",h="«М'ясо до Оргріммара» — коротке вступне доручення з доставки від Зарга на Перехресті.",kw={"м'ясо до оргріммара","зарг","деврак","гришка","вітрокрили","оргріммар"},ang={["profession:Cooking"]="Свіже м'ясо з рівнин Пусток для корчми Гришки в Оргріммарі — запорука того, що ситні казани столиці не порожніють для воїнів, які заходять у гості.",["race:Orc"]="Для молодих орків, що покидають Дуротар, щоб полювати в Пустках, доставка пакунка Зарга — швидкий спосіб прокласти повітряний шлях просто назад до столиці Вождя.",["race:Troll"]="Тролі з Темного Спису, що працюють на Перехресті, завдяки цьому дорученню прив'язують нові застави в дикій глушині до шляхів постачання Оргріммара."},sec={{t="Свіжа дичина з Пусток",b="Неосяжні рівнини Пусток рясніють звіриною — від жевр і степових довгоступів до кодо й громоящерів. Зарг приготував кілька добірних шматків як особисту посилку для Гришки, клопітливої корчмарки з Долини Сили в Оргріммарі. Щоб м'ясо лишилося свіжим і не довелося довго брести курною дорогою через Річку Південної Люті в Дуротар, Зарг посилає гінців через Перехрестя просто до сідала вітрокрилів."},{t="Крила над степами",b="Зустріч із Девраком — перше офіційне знайомство молодого воїна Орди з мережею перельотів на вітрокрилах. Співпрацюючи з господарями вітрокрилів, Орда поєднує віддалені застави на кшталт Перехрестя просто зі своєю укріпленою столицею в Оргріммарі. Деврак готує гінця й вантаж до швидкого перельоту над саваною."}},faq={{q="Кому Зарг надсилає це м'ясо?",a="Зарг надсилає шматки м'яса своїй подрузі Гришці — улюбленій усіма корчмарці, що тримає головну таверну в Долині Сили в Оргріммарі.",al={"кому м'ясо","для кого м'ясо","отримувач м'яса від зарга"}},{q="Чому це завдання можуть узяти лише орки й тролі?",a="Це завдання — вступ до польотів для своїх: воно з'єднує орків і тролів Темного Спису з їхньою спільною столицею, Оргріммаром. Тауренів скеровують до Тандер Блафа через завдання «Оберемок шкур», а Відступники отримують «Постачання для Гробниці», що пов'язує їх зі Срібноліссям.",al={"чому таурени не можуть це взяти","завдання з м'ясом нежиті","обмеження за расою"}},{q="Хто такий Деврак?",a="Деврак — орк, господар вітрокрилів на Перехресті в Пустках. Він наглядає за вивернами, які переносять послання, припаси й мандрівників по всьому Калімдору.",al={"деврак перехрестя","хто такий деврак"}},{q="Що буде, коли віддати м'ясо Девракові?",a="Деврак приймає вантаж і влаштовує вам переліт на вітрокрилі до Небесної Вежі Оргріммара, щоб ви віднесли м'ясо Гришці до її корчми, — це наступне завдання, «Переліт до Оргріммара».",al={"наступне завдання після м'яса до оргріммара","що робить деврак"}},{q="Де знайти Зарга?",a="Зарг перебуває на Перехресті — головному торговому осередку Орди на центральному роздоріжжі Пусток.",al={"де зарг","місце зарга"}},{q="Навіщо вітрокрил, а не пішки?",a="Вітрокрили швидко переносять через суворі простори Пусток і річковий каньйон до Дуротару, тож делікатний вантаж на кшталт свіжого м'яса прибуває до Оргріммара, не встигнувши зіпсуватися.",al={"чому летіти до оргріммара","вітрокрил м'ясо"}}},fp="18,286,27.443.0,22.338.0,34.142.0,45.309.0,14.172.0,45.195.0,23.116.0,40.193.0"}
P.entries["quest:637"] = {n="Лист Саллі Баллу",s="Знайдений на потонулому кістяку під розбитими арками Мосту Тандол, цей розмоклий лист містить передсмертні слова дворфійського солдата на ім'я Саллі Баллу. Адресований його дружині Сарі в Айронфорджі, він несе останні думки захисника, що зник у крижаних водах річки під час боїв за міст.",h="Знайдений на потонулому кістяку під розбитими арками Мосту Тандол, цей розмоклий лист містить передсмертні...",kw={"саллі баллу","лист","міст тандол","сара баллу","айронфордж","удова","багнокрай"},ang={["faction:Alliance"]="Лист — зворушливе нагадування про особисту жертву рядових солдатів передової, які бережуть крихкі сухопутні зв'язки між південними й північними землями Альянсу.",["race:Dwarf"]="Для дворфів Айронфорджа повернути останні слова Саллі — означає вшанувати побратима, який поклав життя, обороняючи велику дворфійську кам'яну споруду від північних загроз."},sec={{t="Голос із річкового дна",b="Під масивними кам'яними опорами Мосту Тандол — важливої переправи, що з'єднує Багнокрай з Аратійським нагір'ям, — лежить потонулий кістяк полеглого дворфа. У кістлявій руці він досі стискає пошкоджений водою конверт, який ледве витримує дотик. Написані з болісною ретельністю серед пожеж бою, сторінки починаються ніжним «Моя люба Саро…», зберігаючи голос солдата довго після того, як його забрала вода."},{t="Ціна Мосту",b="Міст Тандол бачив запеклі бої між силами Альянсу та їхніми ворогами — від диверсантів Темного Заліза до розбійницьких ватаг, що зазіхають на прикордоння. Саллі Баллу був одним із багатьох дворфійських солдатів, посланих на північ боронити цю важливу переправу. Коли він загинув під хвилями, його доля лишалася невідомою родині в горах, доки нирець нарешті не дістав його прощальний заповіт."},{t="Удова в Айронфорджі",b="Повернення врятованого листа до Айронфорджа тихо спустошує вдову Саллі, Сару Баллу. Живучи серед гамірних зал дворфійської столиці, вона застигла між горем і крихкою надією, не знаючи, зник її чоловік безвісти чи втрачений назавжди. Побачивши його рукописні слова й дізнавшись про його могилу під водою, вона нарешті змушена зустрітися з гіркою правдою про його смерть."}},faq={{q="Де знайти лист Саллі Баллу?",a="Лист тримає в руці затоплений скелет, що лежить глибоко на дні річки просто під масивними кам'яними опорами Мосту Тандол, який з'єднує Багнокрай з Аратійським нагір'ям.",al={"де лист саллі баллу","де саллі баллу","скелет біля мосту тандол"}},{q="Ким був Саллі Баллу?",a="Саллі Баллу — солдат-дворф Альянсу, що поліг, захищаючи Міст Тандол. Притиснутий під крижаною водою під час боїв за переправу, він устиг написати останній лист своїй дружині Сарі, перш ніж помер.",al={"хто такий саллі","переказ про саллі баллу","ким був саллі баллу"}},{q="Хто така Сара Баллу?",a="Сара Баллу — вдова Саллі, що живе у великій столиці дворфів, Айронфорджі. Вона місяцями чекала звісток про долю чоловіка на північному кордоні.",al={"де сара баллу","хто така сара","місце сари баллу"}},{q="Що буде, коли доставити лист?",a="Отримавши гірке підтвердження смерті Саллі, Сара Баллу поринає в горе й просить увічнити пам'ять про нього — історія триває в наступному проханні в Айронфорджі.",al={"що далі","ланцюжок саллі","після доставки листа"}},{q="Чому лист уцілів під водою?",a="Лист захищав конверт, міцно стиснутий у руці загиблого. Коли його дістають, він уже частково розмоклий і розплився, але кілька сторінок, списаних старанним почерком, ще можна прочитати.",al={"чому лист читабельний","як конверт вцілів"}},{q="Що з реального світу надихнуло це завдання?",a="Завдання — данина пам'яті майорові Саллівану Балу з 2-го Род-Айлендського піхотного полку часів Громадянської війни в США: незадовго до загибелі в першій битві при Булл-Рані він написав дружині знаменитий поетичний прощальний лист.",al={"цікавинки саллі баллу","саллівен баллу","посилання на громадянську війну"}}},fp="21,327,25.455.0,21.403.0,20.428.1,37.197.0,21.214.0,19.167.0,42.203.1,43.229.0,49.228.0"}
P.entries["quest:6381"] = {n="Нове життя",s="«Нове життя» — цілюще завдання Орди від Таммри Віндфілд у Притулку Сонячної Скелі. Зібравши зачароване насіння, ви вирушаєте на захід, у попелясті руїни Обвугленої Долини, щоб посіяти його в родючу землю. Цей обряд має пробудити відродження краю попри ворожих елементалів і гарпій.",h="«Нове життя» — цілюще завдання Орди від Таммри Віндфілд у Притулку Сонячної Скелі.",kw={"нове життя","таммра віндфілд","насіння геї","обвуглена долина","земна мати","відродження"},ang={["class:Druid"]="Друїдам близька місія Таммри: відродження Обвугленої Долини для них — необхідне відновлення тендітної рівноваги природи.",["class:Shaman"]="Шамани розуміють: розлючені вогняні елементалі, що блукають Долиною, не знайдуть спокою, доки не почне загоюватися сама сплюндрована земля.",["profession:Herbalism"]="Травники цінують неабияку силу витривалого насіння, здатного виростити буйну зелень навіть із геть мертвої землі.",["race:Tauren"]="Для тауренів посів зачарованого насіння в поранену землю — духовне єднання із Земною Матір'ю й виконання священного обов'язку зцілювати скалічені краї."},sec={{t="Зцілення випаленої землі",b="Обвуглена Долина — трагічне свідчення недавнього спустошення: її душать кіптява, люті вогняні елементалі й гарпії-стерв'ятники. Таммра Віндфілд не дає краю скоритися руїні. Покладаючись на давню стійкість Земної Матері, вона посилає мандрівників у саме серце почорнілої долини — шукати Купи Землі Геї, клапті родючого ґрунту, що вціліли в пожарищі."},{t="Опора для майбутнього",b="Зачароване насіння Геї, посіяне у випалену землю, виведене так, щоб витримувати рештки стихійної скверни. Пустивши коріння, воно сплітає живу опору, яка опирається тліну й кличе рослини назад у долину. Таммра бачить попереду довге зцілення: коли живе коріння поволі відвоює улоговину, розлючені вогняні духи вгамуються, гарпії втратять своє похмуре гніздовище, а ненаситну лісорозробку Венчурної Компанії зрештою буде вигнано геть."}},faq={{q="Навіщо садити насіння Ґеї?",a="Зачароване насіння Ґеї має вкоренитися в пораненій землі Обвугленої Долини. Воно опирається скверні й закладає перший осередок буйного рослинного життя — основу, на якій ліс поступово відросте й загоїться.",al={"навіщо садити насіння","мета нового життя","що робить насіння ґеї"}},{q="Куди треба вирушити, щоб посадити насіння?",a="Вам треба податися на захід від Притулку Сонячної Скелі, в Обвуглену Долину. Насіння садять у невеликі земляні горбики Ґеї, розкидані по почорнілій улоговині.",al={"де обвуглена долина","де садити насіння ґеї","місця для насіння"}},{q="Хто така Таммра Віндфілд?",a="Таммра Віндфілд — тауренка-природознавиця з Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Вона присвятила себе тому, щоб заспокоювати поранених духів землі й відновлювати місця, сплюндровані люттю стихій і промисловою жадібністю.",al={"хто дає нове життя","видавець таммра","переказ про таммру віндфілд"}},{q="Які загрози чатують в Обвугленій Долині під час садіння?",a="В Обвугленій Долині блукають здичавілі вогняні елементалі, розбурхані недавнім спустошенням, а також агресивні гарпії Бладф'юрі, що гніздяться серед обгорілих дерев.",al={"вороги обвугленої долини","хто нападає в обвугленій долині","небезпеки обвугленої долини"}},{q="Яке завдання передує «Новому життю»?",a="«Нове життя» йде одразу після завдання «Цикл переродження», у якому ви допомагаєте Таммрі зібрати все потрібне для зачарованого насіння Ґеї.",al={"попереднє завдання нового життя","цикл переродження","що веде до нового життя"}},{q="На що Таммра сподівається для Кам'яного Кігтя в майбутньому?",a="Таммра сподівається, що відроджена земля згодом угамує розлючених вогняних елементалів, витіснить хижих гарпій і переживе вирубки Венчурної Компанії, повернувши горам буйний і мирний ліс.",al={"майбутнє кам'яного кігтя","мета таммри","що буде з обвугленою долиною"}}},fp="8,321,26.399.0,25.486.0,47.240.0,41.153.0,24.235.0,50.166.0,33.152.0,58.228.0"}
P.entries["quest:6382"] = {n="Полювання в Ашенвалі",s="«Полювання в Ашенвалі» — настанова, що виводить досвідчених шукачів пригод Орди з посушливих Пусток на північ, у густі ліси Ашенвалю. Джорн Скайсір із Табору Тауражо посилає мандрівників на Заставу Розщепленого Дерева, щоб допомогти Сенані Тандергарт і перевірити своє вміння вистежувати в дикому, спірному краї.",h="«Полювання в Ашенвалі» — настанова, що виводить досвідчених шукачів пригод Орди з посушливих Пусток на...",kw={"полювання в ашенвалі","джорн скайсір","сенані тандергарт","застава розщепленого дерева","мисливці","завдання"},ang={["class:Hunter"]="Перехід із рівнин Калімдору до Ашенвалю — величезна зміна місцевості: під густим лісовим покровом на вас чекають екзотичні звірі, яких можна вистежувати, вивчати й приручати.",["faction:Horde"]="Ашенваль — вкрай важливий стратегічний рубіж: закріпившись тут, Орда отримує деревину й харчі, без яких не обійтися поселенням у Дуротарі та Пустках.",["race:Tauren"]="І Джорн Скайсір, і Сенані Тандергарт ведуть цю мандрівку, вбачаючи в полюванні не просто вбивство, а духовну рівновагу й спосіб ушанувати дику природу."},sec={{t="Під прадавній покров лісу",b="Довівши свою мисливську вправність на вибілених сонцем рівнинах Пусток, мисливці й воїни Орди вирушають на зовсім інше випробувальне поле. Джорн Скайсір бачить, коли мандрівник переріс місцеву дичину, і посилає його на північ, до Ашенвалю. Для молодої Орди ці прадавні ліси — і скарбниця ресурсів, і глибокий політичний та духовний рубіж, який вона мусить навчитися розуміти й здобути."},{t="Застава Розщепленого Дерева",b="Звивиста дорога на північ повз Вал Мор'шан приводить мандрівників до Застави Розщепленого Дерева — укріпленого табору Орди глибоко в лісі. Там тауренська мисливиця Сенані Тандергарт вітає досвідчених прибульців, що шукають суворіших випробувань на виживання. Щоб процвітати в Ашенвалі, Орда покладається на вправних слідопитів, які вміють давати раду не лише агресивним місцевим хижакам, а й ворожим пильним очам захисників лісу."}},faq={{q="Хто посилає мене на «Полювання в Ашенвалі»?",a="Джорн Скайсір, мисливець-таурен із Табору Тауражо на півдні Пусток, дає це завдання, коли ви покажете свою вправність у полюванні на місцевих звірів.",al={"хто дає полювання в ашенвалі","видавець полювання в ашенвалі","завдання йорна скайсіра"}},{q="Де розташована Застава Розщепленого Дерева?",a="Застава Розщепленого Дерева лежить у центрально-східному Ашенвалі. Якщо йти головною дорогою на північ із Пусток повз Вал Мор'шан і далі лісом, укріплена застава буде на північному боці дороги.",al={"де застава розщепленого дерева","де сенані тандергарт","знайти заставу розщепленого дерева"}},{q="Хто така Сенані Тандергарт?",a="Сенані Тандергарт — мисливиця-тауренка із Застави Розщепленого Дерева. Вона керує полюванням по всьому Ашенвалю й навчає новоприбулих шукачів пригод Орди вистежувати найлютіших хижаків і духів прадавнього лісу.",al={"сенані тандергарт","хто така сенані","мисливиця сенані"}},{q="Які ще застави Орди є поблизу в Ашенвалі?",a="Окрім Застави Розщепленого Дерева, Орда тримає Лісозаготівельний Табір Бойової Пісні на сході й Заставу Зорам'гар на далекому західному узбережжі Зорам.",al={"бази орди в ашенвалі","інші табори в ашенвалі"}},{q="Чому Орду цікавить полювання в Ашенвалі?",a="Дикі ліси дають м'ясо, шкури й ресурси, яких бракує посушливим землям Дуротару й Пусток. До того ж сутичка з небезпечними звірами лісу вважається важливим випробуванням волі й духовної сили для воїнів і мисливців Орди.",al={"чому полювання в ашенвалі","мотивація орди в ашенвалі"}},{q="Які випробування йдуть після цієї подорожі?",a="Сенані Тандергарт залучає досвідчених мисливців вистежувати відомих лісових хижаків і посилає їх у хащі полювати на найгрізніших: велетенського ведмедя Урсанґуса, кішку Шадумбру й гіпогрифа Шарпталона.",al={"наступне завдання після полювання","що дає сенані"}}},fp="18,317,23.443.0,17.452.0,35.159.0,35.225.0,27.226.0,50.149.0,52.252.0,36.227.0"}
P.entries["quest:6383"] = {n="Полювання в Ашенвалі",s="«Полювання в Ашенвалі» — давній обряд, за яким наглядає Сенані Тандергарт на Заставі Розщепленого Дерева. Мисливцям Орди кидають виклик: вистежити й здолати трьох легендарних лісових хижаків, що никають прадавнім лісом, — ведмедя Урсанґуса, нічного шаблезуба Шадумбру та лютого гіпогрифа Шарпталона. Це не просто випробування зброєю, а шлях до хитрості, шани й пізнання себе.",h="«Полювання в Ашенвалі» — давній обряд, за яким наглядає Сенані Тандергарт на Заставі Розщепленого Дерева.",kw={"полювання в ашенвалі","сенані тандергарт","урсанґус","шадумбра","шарпталон","завдання"},ang={["class:Hunter"]="Полювання — класичний обряд посвяти: слідопит мусить обнишпорити величезні простори лісу, читати місцевість і зійтися зі звірами, які легко здолають необачного розвідника.",["faction:Horde"]="На противагу руйнівним суцільним вирубкам Бойової Пісні полювання відкриває Орді шлях бойової честі та духовного вкорінення в спірному Ашенвалі.",["race:Tauren"]="Для тауренських мисливців полювання на Урсанґуса, Шадумбру й Шарпталона — вияв споконвічної шани до творіння Земної Матері, де повага до лютості природи врівноважується честю мисливця."},sec={{t="Тауренська традиція в прадавньому лісі",b="Поки Орда закріплюється глибоко в Ашенвалі, духовні науки Земної Матері знаходять голос у Сенані Тандергарт. На відміну від агресивної орківської лісозаготівлі, полювання Сенані ставиться до затінених лісів як до священного випробувального поля. Змагаючись розумом із верховними хижаками лісу, мисливець має поєднатися з неприборканою природою й виплекати тиху покору, без якої в Ашенвалі не вижити."},{t="Три великі звірі",b="Полювання зосереджене на трьох самотніх легендах, що блукають серед гілля. Біля Стежки Глибокого Кігтя бродить Урсанґус — величезний старий ведмідь, чия сила випробовує тілесну витривалість. Далі на схід, на межі біля Притулку Рейнвуд і невловимих сестер-реготух, чатує Шадумбра — потайна нічний шаблезуб, шанована за хитрість. І нарешті, на південь від Застави Розщепленого Дерева кружляє Шарпталон — лютий гіпогриф, чиє панування в кронах лісу завершує випробування."}},faq={{q="Хто починає «Полювання в Ашенвалі»?",a="Полювання очолює Сенані Тандергарт, мисливиця-тауренка в Ашенвалі. Вона кидає виклик мандрівникам Орди, які хочуть довести, що вміють виживати в дикій природі.",al={"видавець полювання в ашенвалі","хто дає полювання","завдання сенані тандергарт"}},{q="Яких звірів треба вистежити?",a="Треба вистежити й убити трьох легендарних хижаків: велетенського ведмедя Урсанґуса, нічну шаблезубу кішку Шадумбру й лютого гіпогрифа Шарпталона.",al={"яких тварин убити","три звірі","цілі полювання в ашенвалі"}},{q="Де знайти Урсанґуса?",a="Урсанґус блукає невеликою ділянкою трохи на захід від Стежки Глибокого Кігтя, серед інших диких ведмедів лісу.",al={"де урсанґус","де ведмідь","знайти урсанґуса"}},{q="Де нишпорить Шадумбра?",a="Шадумбра нишпорить на південь від Притулку Рейнвуд, полюючи біля дороги, де живуть дріади, відомі як Сміхотливі Сестри.",al={"де шадумбра","місце шадумбри","місце шаблезуба"}},{q="Де вистежити Шарпталона?",a="Шарпталон облітає широку територію на південь від Застави Розщепленого Дерева, проносячись між деревами й над галявинами.",al={"де шарпталон","місце шарпталона","місце гіпогрифа"}},{q="Навіщо Сенані Тандергарт посилає мисливців по цих звірів?",a="Сенані задумала полювання як почесне випробування, а не безглузду різанину. Мірячись силами з найсмертоноснішими мешканцями лісу, мисливці мають зрозуміти дику природу й пізнати власну внутрішню силу.",al={"навіщо полювання","мета полювання","переказ про полювання"}}},fp="18,403,39.442.0,22.458.0,30.191.0,36.144.0,29.119.0,28.127.0,32.115.0,61.244.0"}
P.entries["quest:6384"] = {n="Переліт до Оргріммара",s="Це доручення знайомить шукачів пригод Орди з повітряними подорожами Калімдором: ви наймаєте вітрокрила, щоб полетіти з Перехрестя до Оргріммара. Отримавши від Зарга свіжі шматки м'яса, мандрівники приземляються на небесній вежі столиці й несуть пакунок просто Корчмарці Гришці.",h="Це доручення знайомить шукачів пригод Орди з повітряними подорожами Калімдором: ви наймаєте вітрокрила, щоб...",kw={"вітрокрил","переліт","перехрестя","оргріммар","зарг","корчмарка гришка","деврак"},ang={["faction:Horde"]="Переліт на вітрокрилі між Перехрестям і Оргріммаром — головна життєва артерія, що з'єднує серце Пусток з осердям влади Вождя Тралла.",["profession:Cooking"]="Отримавши Заргів подарунок, Гришка не лишає жодних сумнівів щодо своїх кулінарних уподобань: найкращих звірів Калімдору слід подавати з кров'ю, щоб зберегти смак."},sec={{t="Крила над саваною",b="Долати пішки посушливі простори між Перехрестям і червоними скелями Дуротару — виснажлива справа, тож Орда тримає надійну мережу навчених вітрокрилів, які скорочують відстань. Деврак, розпорядник польотів на Перехресті, опікується цими вивернами: він відправляє гінців і мандрівників високо над запиленими стежками каньйонів, щоб важливі донесення й товари швидко потрапляли просто до столиці."},{t="Особлива доставка для Гришки",b="Цей політ — не просто прогулянка задля краєвидів, у ньому є особиста нотка. Зарг із Перехрестя приготував пакунок добірних сирих шматків м'яса для Корчмарки Гришки, що тримає заїзд у Долині Сили в Оргріммарі. Щойно вітрокрил сідає на центральну небесну вежу Оргріммара, до заїзду Гришки лишається кілька кроків. Там вона радо приймає подарунок і з теплотою зауважує, що Зарг таки знає шлях до жіночого серця."}},faq={{q="Навіщо цей переліт?",a="Подорож — практичне знайомство з мережею перельотів Орди на вітрокрилах. Ви платите Девракові за переліт із Перехрестя до Оргріммара, щоб доставити свіже м'ясо від Зарга Корчмарці Гришці.",al={"чому летіти до оргріммара","мета переліту до оргріммара","навіщо м'ясо до оргріммара"}},{q="Де в Оргріммарі сідає вітрокрил?",a="Вітрокрил сідає на Небесній Вежі Оргріммара, що здіймається високо над Долиною Сили. З майданчика вежі пандусами можна спуститися на головну площу, до найближчих торговців і корчми Гришки.",al={"де приземлятися в оргріммарі","місце скайтавера","місце посадки в оргріммарі"}},{q="Хто така Гришка?",a="Корчмарка Гришка тримає гамірну таверну в Долині Сили в Оргріммарі. Вона гостинно приймає втомлених мандрівників у столиці й тепло приятелює із Заргом, який регулярно постачає їй добірне сире м'ясо для кухні.",al={"корчмарка гришка","хто така гришка","де гришка"}},{q="Хто такий Деврак?",a="Деврак — господар вітрокрилів на Перехресті в Пустках. Він доглядає виверн і влаштовує повітряне сполучення між заставою в Пустках, Дуротаром та іншими поселеннями Орди.",al={"деврак перехрестя","хто такий деврак","майстер вітрокрилів перехрестя"}},{q="Чому Зарг надсилає Гришці сире м'ясо?",a="Зарг вважає свіжу дичину з Пусток цінним дарунком. Гришка надзвичайно тішиться ним і зауважує, що добірні шматки з кров'ю — найпевніший шлях до її серця.",al={"м'ясо зарга","чому м'ясо гришці","зарг і гришка"}},{q="Що робити після доставки м'яса?",a="Коли доставку в корчмі завершено, Гришка скеровує мандрівників назад до Небесної Вежі — поговорити з Дорасом, господарем вітрокрилів Оргріммара, і приготуватися до зворотного шляху.",al={"що після переліту до оргріммара","наступне завдання після гришки","куди далі після доставки"}}},fp="17,275,22.394.0,28.423.0,35.215.0,44.198.0,15.239.0,14.197.0,41.165.0,43.180.0"}
P.entries["quest:6385"] = {n="Дорас, господар вітрокрилів",s="Корчмарка Гришка з Оргріммара написала Заргові на Перехресті листа з подякою, і їй потрібен гонець, який доставить його повітрям назад у Пустки. Щоб домовитися про переліт, вона відсилає мандрівників на міську небесну вежу до Дораса — головного господаря вітрокрилів Орди.",h="Корчмарка Гришка з Оргріммара написала Заргові на Перехресті листа з подякою, і їй потрібен гонець, який...",kw={"дорас","вітрокрил","господар вітрокрилів","корчмарка гришка","зарг","оргріммар","долина сили"},ang={["faction:Horde"]="Мережа вітрокрилів з'єднує Оргріммар із ключовими залогами в різних краях і служить тим сухожиллям, що дає молодій Орді змогу перекидати сили й постачати припаси через нетрі Калімдору.",["race:Orc"]="Відколи орки ступили на землі Калімдору, вони встигли зріднитися з місцевими вивернами й покладаються на їхню спритність і силу — і як на крилатих верхових звірів, і як на в'ючних гінців."},sec={{t="Відповідь із гінцем",b="Отримавши свіжу партію м'яса, доставлену повітрям із мисливських угідь Пусток, Корчмарка Гришка складає офіційного листа з подякою м'ясникові Заргу. Не маючи часу самій вирушати суходолом через Дуротар, вона покладається на повітряну поштову мережу, що пов'язує головні поселення Орди в Калімдорі, щоб її послання швидко полетіло назад через прикордоння."},{t="Господар гніздовища",b="Дорас опікується гніздовищем вітрокрилів Оргріммара на вершині польотної вежі в Долині Сили. Його навчені виверни — життєва сила військового зв'язку й постачання Орди: вони долають небезпечну відстань між столицею й віддаленими заставами, як-от Перехрестя, за частку того часу, який забирає піша дорога чи віз, запряжений кодо."}},faq={{q="Хто такий Дорас?",a="Дорас — головний господар вітрокрилів в Оргріммарі. Він відає міськими навченими вивернами й влаштовує перельоти до віддалених осередків Орди по всьому центральному Калімдору.",al={"дорас","хто такий дорас","майстер польотів оргріммара"}},{q="Навіщо Корчмарка Гришка надсилає цього листа?",a="Гришка надсилає письмову подяку Заргові, м'ясникові з Перехрестя, на знак того, що м'ясо щасливо дісталося її таверни в Оргріммарі.",al={"навіщо лист","лист гришки","для чого лист"}},{q="Де знайти Дораса?",a="Дорас стоїть на верхівці центральної льотної вежі над Долиною Сили в Оргріммарі; туди можна піднятися дерев'яними пандусами всередині вежі.",al={"де дорас","місце дораса","знайти дораса"}},{q="Що буде, коли віддати лист Гришки Дорасові?",a="Коли ви поговорите з Дорасом, він приготує вітрокрила, щоб той відніс вас назад до Пусток і ви власноруч передали лист Гришки Заргові на Перехресті.",al={"що далі","після дораса","наступне завдання"}},{q="Хто такий Зарг?",a="Зарг — орк-м'ясник із Перехрестя в Пустках і друг Гришки, якій він надіслав у дарунок добірне м'ясо з Пусток.",al={"зарг","хто такий зарг"}},{q="Навіщо вітрокрили, а не пішки?",a="Подорож суходолом з Оргріммара через Дуротар і за Річку Південної Люті до Пусток — довга й повна небезпек. Приручені вітрокрили дають Орді швидкий і надійний спосіб пересилати розвідників, накази й гінців між поселеннями.",al={"чому летіти","навіщо вітрокрили","переказ про маршрути польоту"}}},fp="27,265,17.382.0,23.322.0,13.191.0,45.170.0,25.140.0,52.159.0,13.139.0,39.255.0"}
P.entries["quest:6386"] = {n="Повернення на Перехрестя",s="Це доручення завершує доставку між Дуротаром і Пустками: ви несете відповідь Гришки назад Заргові на Перехрестя. Воно показує, як вітрокрили стають життєво важливим повітряним хребтом, що пов'язує поселення Орди по всьому Калімдору.",h="Це доручення завершує доставку між Дуротаром і Пустками: ви несете відповідь Гришки назад Заргові на...",kw={"перехрестя","вітрокрил","зарг","гришка","дорас","деврак","пустки"},ang={["faction:Horde"]="Гніздовища вітрокрилів в Оргріммарі та на Перехресті утворюють господарський і транспортний хребет, що з'єднує столицю Орди з небезпечними рівнинами Калімдору.",["race:Orc"]="Ситні шматки свіжої дичини й досі лишаються одним із найкращих знаків прихильності й поваги, які орк-мисливець може піднести обраниці."},sec={{t="Крилате повернення",b="Доставивши добірне м'ясо Гришці в Оргріммар, ви отримуєте її письмову відповідь для Зарга. Дорас, господар вітрокрилів, що оселився на високих кручах Оргріммара, дає вам крилатого звіра до Пусток. Оскільки ви вже познайомилися з Девраком на Перехресті, виверни Дораса знають маршрут, і виснажливий перехід суходолом через Річку Південної Люті обертається стрімким польотом пустельним небом."},{t="Шлюби укладаються в Пустках",b="Сміливе кулінарне залицяння Зарга вдається. Тепла відповідь Гришки підтверджує, що ніщо так не вражає орка, як добрі харчі, — і Зарг, святкуючи, навіть починає мріяти про близьке весілля. А крім романтичного тріумфу, ця подорож відкриває мандрівникові доступ до головного вузла сполучення в Пустках."}},faq={{q="Чому повертатися треба на вітрокрилі?",a="Дорас на цій доставці показує, як працює мережа польотів Орди. Оскільки ви вже бували в Деврака на Перехресті, виверни можуть летіти просто між двома сідалами — це заощаджує час і береже шляхи постачання.",al={"чому летіти назад","потрібен вітрокрил","чи можна пішки"}},{q="Хто така Гришка?",a="Гришка — корчмарка в Долині Сили в Оргріммарі. Зарг надіслав їй добірне м'ясо з Пусток, сподіваючись завоювати її прихильність.",al={"переказ про гришку","хто така гришка","жінка з м'ясом в оргріммарі"}},{q="Чого Зарг хотів, надсилаючи м'ясо до Оргріммара?",a="Зарг хотів позалицятися до Гришки. В орків подарувати ситну, добірну дичину з диких рівнин Пусток вважається величним романтичним жестом.",al={"чому зарг надіслав м'ясо","мотивація зарга","лист зарга"}},{q="Де закінчується це завдання?",a="Завдання завершується на Перехресті в Пустках: там ви віддаєте Лист Ґришки Заргові біля сторожової вежі й стаєнь.",al={"де здати","місце повернення","хто отримає лист гришки"}},{q="Хто такий Дорас?",a="Дорас — господар вітрокрилів на сідалі над Долиною Сили в Оргріммарі; він відає летючими скакунами, що подорожують Калімдором.",al={"дорас вітрокрил","місце дораса","майстер польотів оргріммара"}},{q="Що буде після цього завдання?",a="Ця доставка завершує кур'єрський ланцюжок «М'ясо до Оргріммара». З'єднавши Оргріммар і Перехрестя, ви цілком готові вирушати вглиб Пусток.",al={"продовження ланцюжка","наступне завдання після повернення","продовження м'яса до оргріммара"}}},fp="25,247,15.438.0,27.314.0,44.220.0,15.145.0,51.154.0,26.132.0,13.159.0,30.172.0"}
P.entries["quest:6387"] = {n="Відмінники",s="Наставник гірничої справи Брок Стоунсікер нагороджує здібних молодих учнів у Телсамарі почесними гірничими кайлами. Щоб організувати доставку інструментів з Айронфорджа, він посилає шукачів пригод по допомогу до місцевого майстра грифонів Торґрума Боррелсона.",h="Наставник гірничої справи Брок Стоунсікер нагороджує здібних молодих учнів у Телсамарі почесними гірничими...",kw={"відмінники","брок стоунсікер","торґрум боррелсон","телсамар","почесні кайла","гірнича справа","грифони"},ang={["faction:Alliance"]="Це прохання знайомить мандрівників у Лох Модані з важливою мережею майстрів польотів і повітряних гінців Альянсу.",["profession:Mining"]="Доручення підкреслює повагу дворфів до гірничої справи як до суворого ремесла, де знання каменю й жил заслуговує на відчутне визнання від майстрів-наставників.",["race:Dwarf"]="Для дворфійських шукачів пригод це доручення показує міцний зв'язок між порубіжними поселеннями на кшталт Телсамара й глибокими гірськими залами столиці."},sec={{t="Шана рудокопа",b="У дворфійському містечку Телсамар гірнича справа — більше, ніж ремесло: це наріжний камінь щоденного виживання й дворфійської гордості. Брок Стоунсікер бачить, як крізь його навчання проходять десятки новачків, і муштрує їх у знанні гірських порід і безпеці в тунелях. Тих учнів, що вирізняються з-поміж інших, звичай велить відзначити вишуканим почесним кайлом. Місцеві запаси обмежені, тож по ці кайла доводиться звертатися через увесь Каз Модан, до самого серця Айронфорджа."},{t="У небо",b="Брок не довіряє повільному пішому шляху горами назад через Дун Мороґ, а покладається на повітряну поштову мережу королівства. Торґрум Боррелсон доглядає грифонове сідало біля Телсамара й пропонує швидкий переліт до столиці. Передавши замовлення Брока Торґрумові, ви запускаєте поштовий рейс, що з'єднує навчання на сільському порубіжжі з величними ливарнями дворфійської столиці."}},faq={{q="Хто такий Брок Стоунсікер?",a="Брок Стоунсікер — наставник гірничої справи, що живе в Телсамарі. Він навчає новачків основ копання й роботи з каменем.",al={"брок стоунсікер","хто такий брок","наставник гірників телсамар"}},{q="Навіщо Брокові кайла з Айронфорджа?",a="Брок складає список найкращих учнів-гірників, які заслужили почесні кайла. Щоб видати ці нагороди, замовлення треба доставити Ґолніру Болдерто, торговцеві гірничим приладдям в Айронфорджі.",al={"чому айронфордж","чому кайла","список брока"}},{q="Яку роль у цьому дорученні відіграє Торґрум Боррелсон?",a="Торґрум Боррелсон — розпорядник грифонів Телсамара. Брок велить кур'єрам нести список замовлення йому, щоб той швидко влаштував переліт до Айронфорджа.",al={"торґрум боррелсон","хто такий торґрум","майстер грифонів телсамар"}},{q="Хто отримує список в Айронфорджі?",a="Зрештою список призначений Ґолніру Болдерто в Айронфорджі, який готує урочисті кайла для видатних учнів Брока.",al={"хто отримує список","ґолнір болдерто","контакт айронфорджа"}},{q="Куди веде це доручення далі?",a="Коли ви поговорите з Торґрумом Боррелсоном, він влаштує переліт на грифоні просто до Айронфорджа, щоб ви власноруч передали замовлення Ґолніру Болдерто.",al={"наступний крок","що після відмінників","після списку брока"}},{q="Де відбувається це доручення?",a="Доручення починається й закінчується в поселенні Телсамар серед пологих пагорбів Лох Модану.",al={"місце завдання","де телсамар","де почати відмінників"}}},fp="14,251,13.512.0,19.394.0,25.138.0,41.212.0,52.168.0,35.136.0,33.146.0,32.112.0"}
P.entries["quest:6388"] = {n="Ґріт Турден",s="Це доручення знайомить шукачів пригод із мережею грифонів Айронфорджа: треба віднести в'язку церемоніальних знарядь міському грифонярові. Отримавши від Ґолніра Болдерто Почесні Кайла, гонець мусить доставити їх Ґрітові Турдену, щоб той відправив їх назад до Лох Модану.",h="Це доручення знайомить шукачів пригод із мережею грифонів Айронфорджа: треба віднести в'язку церемоніальних...",kw={"ґріт турден","грифони","почесні кайла","ґолнір болдерто","телсамар","лох модан"},ang={["faction:Alliance"]="Грифонячі сідала Айронфорджа — незамінний транспортний вузол для посланців Альянсу між Дун Мороґом, Лох Моданом і ширшими королівствами.",["profession:Mining"]="Це доручення допомагає учням-шахтарям Брока Стоунсікера в Лох Модані: їхнє ремесло вшановують почесними кайлами, викуваними в столиці.",["race:Dwarf"]="Для дворфів грифони — і предмет родової гордості, і практична потреба: вони пов'язують гірські зали понад підступними вершинами."},sec={{t="Гонець для шахтарів",b="Подолавши шлях із Лох Модану до Великої Кузні, гінці отримують від Ґолніра Болдерто в'язку Почесних Кайл для учнів-шахтарів Брока Стоунсікера. Щоб не тягтися пішки назад гірськими перевалами, Ґолнір радить скористатися дворфійською мережею грифонів і посилає посланця через усе місто до головного айронфорджського грифоняра."},{t="На крилах до Телсамара",b="Ґріт Турден керує грифонячими сідалами у великій гірській залі, що пов'язують Айронфордж із дворфійськими поселеннями по всьому Каз Модану. Турден погоджується влаштувати переліт назад до Торґрума Боррелсона в Телсамарі, якщо шукач пригод уже розвідав шлях і поговорив там із місцевим грифонярем. Це доручення показує новоспеченим героям, яку важливу роль відіграють повітряні гінці, що з'єднують дворфійське королівство в одне ціле."}},faq={{q="Для чого Почесні Кайла?",a="Почесні Кайла — урочисті інструменти, які Ґолнір Болдерто виготовив в Айронфорджі для учнів Брока Стоунсікера, наставника гірничої справи з Телсамара.",al={"почесні кайла","чому почесні кайла","кайла для брока"}},{q="Хто такий Ґріт Турден?",a="Ґріт Турден — головний розпорядник грифонів в Айронфорджі. Він відає маршрутами, що з'єднують столицю дворфів із поселеннями по всьому Каз Модану й далі.",al={"хто такий ґріт турден","майстер грифонів айронфорджа","переказ про ґріта турдена"}},{q="Де в Айронфорджі знайти Ґріта Турдена?",a="Ґріт Турден стоїть біля грифонячого сідала Великої Кузні, неподалік головної центральної вулиці й брами Айронфорджа.",al={"де ґріт турден","де знайти ґріта турдена","майстер польотів айронфорджа"}},{q="Чому спершу треба поговорити з Торґрумом Боррелсоном?",a="Розпорядники грифонів відправляють вершників лише прокладеними маршрутами. Щоб Ґріт Турден міг відправити вершника до Телсамара, мандрівник має спершу встановити зв'язок із Торґрумом Боррелсоном, розпорядником у Лох Модані.",al={"вимога торґрума боррелсона","чому потрібен маршрут телсамара","не можу летіти до телсамара"}},{q="Що буде, коли віддати кайла Ґрітові Турдену?",a="Оглянувши пакунок, Ґріт готує грифона, щоб ви повернулися до Телсамара й передали інструменти просто Брокові Стоунсікеру.",al={"що далі після ґріта турдена","наступне завдання після ґріта турдена"}},{q="Хто посилає вас до Ґріта Турдена?",a="Ґолнір Болдерто, ремісник, що працює біля Великої Кузні в Айронфорджі, дає вам кайла й скеровує до Ґріта.",al={"хто починає ґріта турдена","хто дає це завдання"}}},fp="13,303,24.384.0,24.418.0,32.164.0,21.185.0,44.120.0,50.216.0,53.149.0,31.126.0"}
P.entries["quest:6391"] = {n="Переліт до Айронфорджа",s="Переліт до Айронфорджа — вступне завдання гінця, що відправляє новоспечених шукачів пригод у перший політ на грифоні з Телсамара в Лох Модані до дворфійської столиці. Отримавши від Брока Стоунсікера список найкращих учнів-шахтарів, мандрівник несе депешу просто Ґолнірові Болдерто біля Великої Кузні.",h="Переліт до Айронфорджа — вступне завдання гінця, що відправляє новоспечених шукачів пригод у перший політ на...",kw={"переліт","грифон","брок стоунсікер","ґолнір болдерто","велика кузня","телсамар"},ang={["faction:Alliance"]="Мережа грифонячих перельотів — хребет логістики Альянсу в Каз Модані: вона легко з'єднує прикордонні гарнізони з величною столицею.",["profession:Mining"]="Це завдання показує традицію Гірничої гільдії Глибокої Гори — відзначати й увічнювати гравіюванням здібних шахтарів, що виходять із копалень Лох Модану.",["race:Dwarf"]="Для юних дворфів клану Бронзбірд політ на грифоні до Великої Кузні — гордий обряд посвяти, що пов'язує сільські застави із серцем королівства."},sec={{t="У небо",b="Для багатьох юних горян і мандрівників переліт із Телсамара до Айронфорджа — найперша подорож верхи на грифоні. Цей короткий маршрут, яким опікується Грифоняр Торґрум Боррелсон, проносить мандрівників над засніженими хребтами Дун Мороґа просто до печерної брами гірської фортеці."},{t="Відзнаки Гільдії Глибокої Гори",b="Саме доручення служить Гірничій гільдії Глибокої Гори. Брок Стоунсікер регулярно надсилає з Телсамара звістки про своїх найздібніших учнів-шахтарів. Біля Великої Кузні на них чекає Ґолнір Болдерто, який вирізьблює імена учнів на церемоніальних почесних кайлах — нагорода за сумлінну гірничу справу в каменоломнях і копальнях Лох Модану."}},faq={{q="Де починається й закінчується цей переліт?",a="Подорож починається в розпорядника польотів Торґрума Боррелсона в Телсамарі, у Лох Модані, і приносить вас просто на грифоняче сідало біля Великої Кузні в Айронфорджі.",al={"маршрут польоту","куди летіти","призначення польоту"}},{q="Що таке Список Брока?",a="Список Брока — перелік, складений наставником гірничої справи Броком Стоунсікером у Телсамарі. У ньому записано його найкращих учнів, щоб гільдія в Айронфорджі могла нагородити їх за старанність.",al={"переказ про список брока","хто такий брок","що за папір"}},{q="Хто такий Ґолнір Болдерто?",a="Ґолнір Болдерто — представник Гірничої Гільдії Глибокої Гори при Великій Кузні Айронфорджа. Він отримує списки від місцевих наставників і вирізьблює імена учнів на почесних кайлах.",al={"роль ґолніра","де ґолнір","хто такий ґолнір болдерто"}},{q="Що буде, коли доставити список?",a="Отримавши перелік, Ґолнір скеровує вас до Ґріта Турдена, головного розпорядника грифонів Айронфорджа, — так ви ближче знайомитеся з повітряною мережею королівства.",al={"наступне завдання","що робити після","продовження"}},{q="Навіщо грифон, а не пішки?",a="Хоча гірська дорога й тунелі ведуть просто до брами Айронфорджа, це завдання — практичний урок польотів на грифонах Альянсу: воно показує новим шукачам пригод, як швидко можна перелітати між поселеннями.",al={"чому летіти","чи можна пішки до айронфорджа","чому грифон"}},{q="Що таке почесне кайло?",a="Почесні кайла — урочисті інструменти, які виготовляє Гірнича Гільдія Глибокої Гори, щоб відзначити найкращих учнів гірничої справи, що під проводом місцевих наставників опанували основи копання й геології.",al={"почесні кайла","нагорода кайло","обряд кайла"}}},fp="17,325,19.309.0,33.326.0,37.169.0,21.177.0,25.207.0,40.175.0,37.214.0,25.193.0"}
P.entries["quest:6392"] = {n="Повернення до Брока",s="Доставивши послання Брока Стоунсікера в Айронфордж, ви отримуєте партію Почесних Кайл, які треба віднести назад до Телсамара. Скориставшись дворфійською повітряною мережею, ви сідаєте на грифона в Ґріта Турдена, щоб швидко повернутися через гори.",h="Доставивши послання Брока Стоунсікера в Айронфордж, ви отримуєте партію Почесних Кайл, які треба віднести...",kw={"брок стоунсікер","почесні кайла","ґріт турден","грифон","телсамар","шахтарі"},ang={["profession:Mining"]="Доставлені Почесні Кайла дають найновішим шахтарям Лох Модану необхідне знаряддя й підтримують дворфійську традицію розкопок і розвідки надр.",["race:Dwarf"]="Шлях між Айронфорджем і Телсамаром показує, як грифони Вайлдгаммерів і айронфорджські грифонярі допомагають згуртувати дворфійські твердині."},sec={{t="У небо",b="Велична гірська твердиня Айронфордж покладається на злагоджену мережу грифонячих сідал, щоб підтримувати зв'язок і торгівлю з віддаленими поселеннями на кшталт Лох Модану. Ґріт Турден, айронфорджський грифоняр, керує цими перельотами з головного майданчика міста. Оскільки мандрівник мусить спершу познайомитися з грифонярем гнізда, перш ніж летіти туди, Ґріт переконується, що ви вже поговорили з Торґрумом Боррелсоном у Телсамарі, і лише тоді сідлає грифона для зворотного шляху."},{t="Кайла для учнів",b="Ваша подорож має практичну мету, а не лише знайомить вас із польотами на грифонах: Брокові Стоунсікеру, шанованому наставникові шахтарів у Телсамарі, потрібне нове знаряддя для учнів. Коли Почесні Кайла опиняться в його руках, молоді шахтарі по всій долині зможуть узятися до багатих жил міді й олова, що тягнуться пагорбами довкола озера."}},faq={{q="Хто такий Брок Стоунсікер?",a="Брок Стоунсікер — дворф, наставник гірничої справи в Телсамарі, у Лох Модані. Він навчає молодих гірників добувати руду й камінь із навколишніх пагорбів.",al={"брок стоунсікер","хто такий брок","брок у телсамарі"}},{q="Чому для завершення цього завдання треба летіти на грифоні?",a="Завдання знайомить мандрівників із системою польотів Альянсу. Ґріт Турден пояснює, що грифони можуть віднести вас лише до тих гнізд, де ви вже особисто побували, — наприклад, до сідала Торґрума Боррелсона в Телсамарі.",al={"чому летіти на грифоні","завдання з польотом","політ грифоном"}},{q="Для чого Почесні Кайла?",a="Це щойно викувані гірничі інструменти, які Брок Стоунсікер замовив в Айронфорджі для своїх учнів-гірників, щоб ті працювали на багатих на руду скелях Лох Модану.",al={"почесні кайла","що таке кайла"}},{q="Хто такий Ґріт Турден?",a="Ґріт Турден — розпорядник грифонів Айронфорджа біля Великої Кузні. Він відає польотами зі столиці й до неї по всьому Каз Модану й далі.",al={"ґріт турден","майстер польотів айронфорджа"}},{q="Чи можна просто дійти до Телсамара пішки, а не летіти?",a="Хоча урок задуманий, щоб навчити вас користуватися маршрутами польотів, Брокові Стоунсікеру важливо лише, щоб ви безпечно доставили йому Почесні Кайла в Телсамар, — байдуже, як ви туди дістанетеся.",al={"чи можна пішки назад","чи треба брати грифона"}},{q="Де в Телсамарі знайти Брока?",a="Брок Стоунсікер стоїть просто неба біля кузні й ковадла в Телсамарі, готовий допомогти гірникам, що працюють у Лох Модані.",al={"де брок","місце брока стоунсікера","знайти брока"}}},fp="15,270,19.498.0,20.361.0,25.171.0,55.216.0,32.159.0,21.167.0,52.195.0,36.124.0"}
P.entries["quest:6395"] = {n="Останнє бажання Марли",s="Останнє бажання Марли — раннє завдання Відступників від Послушниці Елрет у Похоронному Подзвоні. Воно просить вас вистежити поневолені Погибеллю рештки Семюела Фіппса, щоб поховати його поруч із убитою ним дружиною Марлою. Завдання відображає прагнення молодого суспільства Відступників шанувати людські зв'язки й відрізнятися від безтямної Погибелі.",h="Останнє бажання Марли — раннє завдання Відступників від Послушниці Елрет у Похоронному Подзвоні.",kw={"останнє бажання марли","марла","семюел фіппс","елрет","поховання","похоронний подзвін"},ang={["class:Priest"]="Наполягання Послушниці Елрет на належному похоронному обряді прямо стосується духовного обов'язку жерців Відступників, які мають справу зі смертністю, горем і оскверненням мертвих Лордерону.",["race:Undead"]="Для новопіднятих Відступників виконати бажання Марли — емоційний якір у колишньому людському житті, доказ того, що співчуття і честь не загинули разом із Лордероном."},sec={{t="Трагічне возз'єднання",b="Перш ніж Третя війна спустошила Лордерон, Марла і Семюел Фіппси жили як чоловік і дружина. Коли їхніми землями прокотилася чума, Семюел піддався заразі й був піднятий безтямним рабом Погибелі. Марлу нежиття оминуло, та від самого Семюела вона втекти не змогла: у безтямному шалі він жорстоко вбив її. Попри загибель від рук чоловіка, в останні миті Марла не тримала зла. Її передсмертне бажання, яке запам'ятала Послушниця Елрет, — спочивати вічно поруч із чоловіком на цвинтарі Похоронного Подзвону."},{t="Повага до мертвих",b="Послушниця Елрет відряджає шукачів пригод із Відступників на північний схід від Похоронного Подзвону — знайти Семюела Фіппса, який досі блукає зруйнованим табором. Покласти край мукам Семюела означає подвійну користь: очистити долину від прислужника Погибелі, що насідає, і принести його тілесні рештки до місця спочинку Марли. Як наголошує Елрет, шана до покійних і повага до їхньої останньої волі — важлива моральна межа, що відділяє щойно звільнених Відступників від безтямної злоби Погибелі."}},faq={{q="Ким була Марла Фіппс?",a="Марла Фіппс жила в Лордероні й пережила першу хвилю чуми нежиття — лише для того, щоб загинути від рук свого чоловіка Семюела, коли той обернувся на безтямного гуля Погибелі. Її останнім бажанням було спочити поруч із ним.",al={"переказ про марлу фіппс","хто така марла","історія марли"}},{q="Хто такий Семюел Фіппс?",a="Семюел Фіппс до чуми був чоловіком Марли. Він піддався Погибелі, утратив розум, скорившись волі Короля-Ліча, і вбив свою дружину. Він блукає зруйнованим табором на північний схід від Похоронного Подзвону, доки його не впокоять шукачі пригод із Відступників.",al={"переказ про семюела фіппса","хто такий семюел фіппс","де семюел фіппс"}},{q="Чому Послушниці Елрет так важливо поховати їх разом?",a="Послушниця Елрет за життя приятелювала з Марлою. Та річ не лише в почуттях: Елрет вірить, що шанувати волю мертвих і гідно поводитися з останками — доказ того, що Відступники зберегли людяність і мораль, а отже, відрізняються від безтямної Погибелі.",al={"чому допомагати марлі","мотив послушниці елрет","чому ховати семюела"}},{q="Чи постала Марла Відступницею?",a="Ні. За словами Послушниці Елрет, нежиття Марлу оминуло. Вона померла звичайною смертю від рук чоловіка й похована на цвинтарі Похоронного Подзвону.",al={"чи марла нежить","чи марла стала відступницею","марла фіппс нежить"}},{q="Де могила Марли?",a="Могила Марли — у першому ряду цвинтаря просто біля головної каплиці Похоронного Подзвону.",al={"місце могили марли","де похована марла","де ховати семюела"}},{q="Де знайти Семюела Фіппса?",a="Семюел Фіппс блукає довкола зруйнованого табору при дорозі, що веде на північний схід від Похоронного Подзвону.",al={"місце семюела фіппса","знайти семюела фіппса","де семюел"}}},fp="17,339,16.550.0,19.517.0,20.225.0,20.235.0,56.265.0,27.162.0,31.96.0,32.97.0"}
P.entries["quest:64"] = {n="Забута реліквія",s="Фермер Фурлброу та його дружина Верна втекли з дому, коли розбійники в масках заполонили їхнє гарбузове поле у Вестфолі. У шаленому поспіху Фурлброу залишив у шафі свого фермерського будинку дорогу серцю родинну реліквію. Повернути кишеньковий годинник — рідкісна нагода врятувати щось особисте з хаосу, що дедалі більше охоплює край.",h="Фермер Фурлброу та його дружина Верна втекли з дому, коли розбійники в масках заполонили їхнє гарбузове поле...",kw={"забута реліквія","фермер фурлброу","кишеньковий годинник","бенні блаанко","верна фурлброу","вестфол"},ang={["faction:Alliance"]="Лихо родини Фурлброу показує, як глибоко занепав громадський лад у житниці королівства, тож мандрівникам Альянсу доводиться братися за справи, які занедбала корона.",["race:Human"]="Для людей Стормвінда бачити чесних фермерів, вигнаних жорстокими розбійниками за день ходу від столиці, — тверезе нагадування про внутрішні негаразди королівства."},sec={{t="Опівнічне вигнання",b="Як і багатьох господарів Вестфолу, Фермера Фурлброу та його дружину Верну вигнали з їхньої землі грубою силою. Розбуджене раптовими криками й насильством серед гарбузових грядок, подружжя мало лише кілька хвилин, щоб зібрати ті небагаті пожитки, які могло забрати, й утекти з ферми. У паніці Фурлброу мусив покинути кишеньковий годинник — подарунок батька Верни в день їхнього весілля, — і той лишився в шафі захопленого фермерського будинку."},{t="Хулігани в полях",b="Гарбузова ферма Фурлброу тепер кишить головорізами Дефіасу, мародерами й злодюжками-пройдисвітами на кшталт Бенні Блаанко, які нишпорять у рештках покинутих домівок. Для звичайних людей повернутися по особисті скарби — вірна смерть. Забравши годинник із шафи серед розгромлених кімнат, шукачі пригод повертають бодай дрібку гідності родині, яка втратила майже все інше через дедалі більше беззаконня."}},faq={{q="Чому кишеньковий годинник такий важливий для Фермера Фурлброу?",a="Кишеньковий годинник — весільний подарунок від батька Верни. Тепер, коли вони стали злиденними біженцями без засобів до життя, годинник — один із небагатьох дорогих серцю зв'язків із колишнім життям і родинною спадщиною.",al={"чому годинник важливий","значення годинника фурлброу","хто дав годинник фурлброу"}},{q="Хто прогнав Фурлброу з їхньої ферми?",a="Уночі ферму захопили розбійники й грабіжники Дефіас. Беззаконня, що охопило Вестфол, змусило багато фермерських родин під загрозою насильства покинути поля й домівки.",al={"хто напав на ферму","хто забрав ферму фурлброу","що сталося з фурлброу"}},{q="Де схований годинник?",a="Годинник лежить у шафі в спальні на садибі Фурлброу — біля гарбузових грядок на захід від придорожнього табору Фурлброу на півночі Вестфолу. Зараз будинок зайняли волоцюги й розбійники Дефіас.",al={"де кишеньковий годинник","знайти годинник","місце шафи"}},{q="Хто такий Бенні Блаанко?",a="Бенні Блаанко — розбійник, що разом зі спільниками з Дефіас тиняється фермерським будинком Фурлброу, грабує покинуте житло й стереже захоплену землю від тих, хто хотів би її повернути.",al={"переказ про бенні блаанко","хто чоловік у будинку"}},{q="Де тепер живуть Фурлброу?",a="Утікши зі своєї землі, Фермер Фурлброу й Верна застрягли край дороги у Вестфолі: вони ховаються біля свого воза й намагаються вижити серед загального занепаду краю.",al={"де фурлброу","де фермер фурлброу"}},{q="Чи надсилає Стормвінд вартових, щоб допомогти повернути такі ферми?",a="Військової присутності Стормвінда у Вестфолі майже немає через політичну байдужість і відсутність проводу в столиці. Народному ополченню на Сентінел Гіллі бракує людей, щоб відвойовувати окремі садиби, тож поселенці цілком беззахисні.",al={"допомога стормвінда вестфолу","чому немає вартових на фермі"}}},fp="22,354,19.491.0,23.440.0,56.214.0,45.197.0,26.226.0,21.190.0,36.174.0,59.275.0"}
P.entries["quest:6401"] = {n="Кая жива",s="«Кая жива» — коротке завдання Орди в Горах Кам'яного Кігтя, що завершує порятунок Каї Флетгуф. Безпечно провівши юну тауренку повз ворожих розбійників-Ґрімтотемів, ви несете радісну звістку про те, що вона жива, її стривоженій тітці Таммрі Віндфілд у Притулок Сонячної Скелі.",h="«Кая жива» — коротке завдання Орди в Горах Кам'яного Кігтя, що завершує порятунок Каї Флетгуф.",kw={"кая жива","кая флетгуф","таммра віндфілд","ґрімтотем","притулок сонячної скелі","макаба флетгуф"},ang={["faction:Horde"]="Гори Кам'яного Кігтя — спірна глушина, де сили Орди розтягнуто до межі; вісті про вцілілих допомагають зберігати єдність між розкиданими таборами.",["race:Tauren"]="Загроза Ґрімтотемів — болючий внутрішній розкол для шу'гало, тож порятунок невинних родичів, як-от Каї, для тауренів — справа глибоко особиста."},sec={{t="Полегшений подих",b="Гори Кам'яного Кігтя повні небезпек, особливо на спірних стежках, де безжально б'є плем'я Ґрімтотем. Коли на їхнє село напали, всі боялися, що юна Кая Флетгуф загинула або потрапила в полон до ренегатів. Те, що вона вижила й урятувалася, — рідкісна мить тріумфу й полегшення серед нескінченних племінних чвар у горах."},{t="До Притулку Сонячної Скелі",b="Щойно Кая в безпеці, Макаба Флетгуф доручає вам віднести звістку просто до Притулку Сонячної Скелі. Там на вісті зі стежок нетерпляче чекає Каїна тітка, Таммра Віндфілд. Звістка про те, що Кая жива й здорова, втішає розбиту родину й ще раз показує, як важливо, що мандрівні герої тримають зв'язок між віддаленими заставами Орди."}},faq={{q="Хто така Кая Флетгуф?",a="Кая Флетгуф — молода тауренка, яка загубилася й опинилася в небезпеці після жорстокого нападу загонів Ґрімтотем, що відкололися, на її поселення в Горах Кам'яного Кігтя.",al={"хто така кая","кая флетгуф","кая"}},{q="Хто така Таммра Віндфілд?",a="Таммра Віндфілд — тітка Каї, що живе в Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Вона боялася, що небога загинула під час нападу Ґрімтотем.",al={"таммра віндфілд","хто така таммра","тітка каї"}},{q="Хто напав на село Каї?",a="На село Каї напав агресивний клан Ґрімтотем — відокремлене угруповання тауренів, відоме тим, що полює і на суперницькі племена, і на мандрівників у горах.",al={"хто напав на каю","напад на село","напад ґрімтотемів"}},{q="Що передує цьому завданню?",a="Це завдання йде одразу після завдання «Захисти Каю» — супроводу, під час якого ви боронете Каю Флетгуф, поки вона тікає від полонителів до безпечного місця.",al={"попереднє завдання","захистити каю","завдання з супроводом"}},{q="Де розташований Притулок Сонячної Скелі?",a="Притулок Сонячної Скелі сховався високо в центральних Горах Кам'яного Кігтя: туди веде головна дорога на захід, а далі вузька гірська ущелина до захищеної улоговини.",al={"місце притулку сонячної скелі","де сонячна скеля","знайти притулок сонячної скелі"}},{q="Чому Макаба Флетгуф посилає мене, а не йде сам?",a="Макаба лишається у своєму таборі біля південно-східного краю Кам'яного Кігтя й покладається на прудкого гінця, щоб той швидко заспокоїв їхню родину в Притулку Сонячної Скелі.",al={"чому макаба залишається","чому посилає мене"}}},fp="12,293,18.381.0,25.362.0,21.161.0,24.149.0,28.181.0,29.143.0,34.175.0,59.155.0"}
P.entries["quest:6421"] = {n="Яр Кам'яного Зсуву",s="Глибоко в Яру Кам'яного Зсуву, що в Горах Кам'яного Кігтя, місцеві кобольди гарячково взялися видобувати рідкісний підземний мінерал — резоніт. Відчуваючи, як наростає напруга в землі, таурен Мор'роґал посилає шукачів пригод з Орди дослідити печери яру й принести зразки мінералу, щоб з'ясувати, що поховано під скелею.",h="Глибоко в Яру Кам'яного Зсуву, що в Горах Кам'яного Кігтя, місцеві кобольди гарячково взялися видобувати...",kw={"яр кам'яного зсуву","резоніт","мор'роґал","кобольди","земляни","титани"},ang={["class:Shaman"]="Шамани, що вслухаються в землю, відчувають неприродний резонанс, який тремтить у скелі, поки кобольди розпечатують реліквії первісного стихійного ремесла титанів.",["profession:Mining"]="Резоніт, що його видобувають кобольди з Яру Кам'яного Зсуву, — не звичайна руда: його основу просякли давні чародійські рештки, лишені підземними будівничими сивої давнини.",["race:Tauren"]="Для тауренів, які шанують Земну Матір, розкопані під горами прадавні споруди титанів — ознака небезпечного порушення природної рівноваги Гір Кам'яного Кігтя."},sec={{t="Напруга в камені",b="Зі свого посту в Притулку Сонячної Скелі таурен Мор'роґал із глибокою тривогою стежить за вершинами Гір Кам'яного Кігтя. Сама земля здається стривоженою: з південного сходу йде неприродне хвилювання. Там, серед круч Яру Кам'яного Зсуву, місцеві кобольди покинули звичайне збиральництво й завзято розкопують рідкісний підземний мінерал — резоніт. Щоб з'ясувати, чому ці забобонні шкідники копають у такому відчайдушному шалі, Мор'роґал кличе розвідників Орди прорватися крізь їхню оборону, спуститися на саме дно печери й принести необроблені зразки мінералу."},{t="Пробудження прадавніх",b="Коли сирий резоніт роздивляються ближче, його справжня природа стає очевидною: кристали гудуть давньою магією землян. Наосліп вгризаючись у глибинний камінь, кобольди пробили прадавній шар світу й відкопали землянина — одну з первісних кам'яних істот, яких титани створили, щоб вимуровувати підземні основи Калімдору. Те, що кобольди мають за звичайну каменоломню, потривожило реліквію первісної історії, і тепер тауренам доводиться втрутитися, перш ніж поховане вирветься на волю."}},faq={{q="Де розташований Яр Кам'яного Зсуву?",a="Яр Кам'яного Зсуву врізається в гори на південний схід від Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Він веде до звивистих печер, які заполонили кобольди Кам'яного Зсуву.",al={"де яр кам'яного зсуву","місце яру кам'яного зсуву","як знайти яр кам'яного зсуву"}},{q="Хто дає завдання «Яр Кам'яного Зсуву»?",a="Завдання дає Мор'роґал, таурен із Притулку Сонячної Скелі — головної застави Орди в Горах Кам'яного Кігтя.",al={"хто починає яр кам'яного зсуву","видавець яру кам'яного зсуву","завдання мор'роґала"}},{q="Що таке Кристали Резоніту?",a="Резоніт — рідкісний мінерал, який трапляється глибоко в печерах Кам'яного Зсуву. На ньому лишилися сліди магії землян, викуваних Титанами, тобто кристали утворилися поблизу підземних реліквій землян.",al={"що таке резоніт","переказ про резоніт","кристали резоніту"}},{q="Чому кобольди так шалено добувають резоніт?",a="Кобольди натрапили на резоніт, коли копали, і в ненаситній гонитві за блискучою рудою вгризлися так глибоко під гори, що потривожили прадавнього землянина, похованого в скелі.",al={"чому кобольди добувають","мета кобольдів яру","змова кобольдів кам'яного кігтя"}},{q="Хто такі земляни за переказами тауренів?",a="За давніми переказами, які пригадує Мор'роґал, земляни — вирубані з каменю істоти, яких давним-давно викували Титани, щоб різьбити й формувати саму кам'яну основу світу.",al={"що таке земляни","земляни і титани","хто такі земляни"}},{q="Що буде після виконання цього завдання?",a="Розпізнавши в Кристалах Резоніту магію землян, Мор'роґал готує зачарований засіб протидії й дає наступне завдання — «Земляни повстають», відправляючи вас назад у печеру протистояти пробудженій загрозі.",al={"наступне завдання після яру кам'яного зсуву","що після яру кам'яного зсуву","продовження яру кам'яного зсуву"}}},fp="19,347,20.608.0,22.489.1,37.181.0,40.125.0,27.225.1,51.193.1,44.165.0,41.225.1"}
P.entries["quest:6441"] = {n="Роги Сатира",s="«Роги сатира» — найманський контракт від мандрівної гоблінки Піксель на Заставі Розщепленого Дерева в Ашенвалі. Угледівши прибуткову торгову нагоду в портовому містечку Раджет, Піксель наймає вправних шукачів пригод Орди, щоб проредити місцеві осередки сатирів і зібрати їхні цінні роги.",h="«Роги сатира» — найманський контракт від мандрівної гоблінки Піксель на Заставі Розщепленого Дерева в...",kw={"роги сатира","піксель","сатири","раджет","сатирнаар","нічний потік","завдання"},ang={["class:Hunter"]="Вистежувати демонічних людиноподібних серед осквернених лісових руїн, як-от Сатирнаар і Нічний Потік, — небезпечне випробування мисливського вміння.",["class:Warlock"]="Сатири сповнені могутньої магії скверни, тож їхні тілесні рештки — цінні дивовижі для тих, хто вивчає демонічну силу.",["faction:Horde"]="Зачищення сатирів у центральному Ашенвалі послаблює небезпечні демонічні осередки, що загрожують хитким шляхам постачання Застави Розщепленого Дерева."},sec={{t="Прибуткова нагода",b="Відпочиваючи на передовому таборі Орди — Заставі Розщепленого Дерева, — заповзятлива гоблінка-мандрівниця на ім'я Піксель помітила вільну нішу на прикордонному ринку. Роги демонічних сатирів Ашенвалю мають великий попит у Раджеті, по той бік Пусток. Не бажаючи ризикувати власною шкурою в сутичках із зіпсованими істотами, Піксель наймає перехожих шукачів пригод, щоб ті зібрали шістнадцять цілих рогів до її повернення на південь."},{t="Лігва зіпсованих",b="Сатири Ашенвалю живуть у розкиданих по прадавньому лісі руїнах, просякнутих скверною, — пам'ятках їхньої зради за часів давнього Розколу. Щоб виконати замовлення Піксель, мисливців посилають до відомих оплотів сатирів — Нічного Потоку, укріпленого табору Сатирнаар і затінених гаїв Ксавіана. Будь-який із цих осередків дасть цінні демонічні трофеї, на які чекають на торгових пристанях Раджета."}},faq={{q="Хто така Піксель?",a="Піксель — заповзятлива гоблінка-мандрівниця, що тимчасово зупинилася на Заставі Розщепленого Дерева в Ашенвалі, перш ніж повернутися на південь, до нейтрального порту Раджет.",al={"хто дає завдання","переказ про піксель","гоблін біля розщепленого дерева"}},{q="Навіщо Раджету роги сатирів?",a="Піксель зауважує, що роги сатирів дорого цінуються в Раджеті: купці, алхіміки й збирачі дивовиж щедро платять за сирі демонічні реагенти й рідкісні матеріали з північних лісів.",al={"чому роги сатирів","для чого роги","роги сатирів раджет"}},{q="Де в Ашенвалі знайти роги сатирів?",a="Сатири населяють кілька осквернених місць в Ашенвалі. Серед відомих осередків — Нічний Потік на північний захід від Застави Розщепленого Дерева, Сатирнаар неподалік головної дороги до Азшари і Ксавіан на північному сході Ашенвалю.",al={"місця сатирів","де знайти сатирів","нічний біг ксавіан сатірнаар"}},{q="Хто такі сатири?",a="Сатири — прадавні нічні ельфи, які тисячі років тому піддалися демонічній скверні Палаючого Легіону. Перетворені на рогатих звірів із роздвоєними копитами, вони служать темним силам і невпинно оскверняють ліс довкола.",al={"що таке сатир","переказ про сатирів","чи сатири демони"}},{q="Чому цю угоду укладають на Заставі Розщепленого Дерева?",a="Застава Розщепленого Дерева — головна твердиня Орди в центральному Ашенвалі. Піксель використовує її як безпечний перепочинок між торговими шляхами й наймає воїнів Орди, які й так воюють із небезпеками лісу.",al={"сатири розщепленого дерева","чому лише орда"}},{q="Чи віддана Піксель Орді?",a="Ні. Піксель — незалежна гоблінська торговка, що шукає зиску. Як і багато гоблінів довкола Раджета, Піксель працює з будь-ким, хто може дати цінний товар, і не зважає на політику фракцій.",al={"чи піксель орда","фракція піксель"}}},fp="11,283,23.425.0,23.430.0,13.161.0,34.200.0,44.204.0,16.231.0,50.226.0,44.206.0"}
P.entries["quest:6442"] = {n="Наги на узбережжі Зорам",s="«Наги на узбережжі Зорам» — завдання Орди, у якому шукачам пригод доручено винищувати агресивних зміїних загарбників на північно-західному узбережжі Ашенвалю. Тролиця Марукай із Застави Зорам'гар прагне втримати спірний берег, відкинувши наг Гнівохвостих від затонулих руїн прадавнього Зорама.",h="«Наги на узбережжі Зорам» — завдання Орди, у якому шукачам пригод доручено винищувати агресивних зміїних...",kw={"наги на узбережжі зорам","марукай","застава зорам'гар","гнівохвості","наги","завдання"},ang={["faction:Horde"]="Утримання Застави Зорам'гар украй важливе для поширення Орди в Ашенвалі, тож очищення берега від наг — справа військового виживання.",["race:Orc"]="Пряма стратегія Марукай — жорстока відсіч — цілком пасує практичній бойовій культурі орків, що тримають прикордонні рубежі."},sec={{t="Хитка опора",b="Присутність Орди на Зорамському Узмор'ї хитка. Оточена ворожими землями нічних ельфів і запеклими лісовими сутичками Ашенвалю, застава забезпечує важливий вихід до моря. Та несподівана поява агресивних наг, що виповзають на берег, загрожує відрізати Орду від моря й захопити невеликий гарнізон, перш ніж його позицію встигнуть як слід укріпити."},{t="Відлуння приреченого Зорама",b="Піщані мілини узмор'я приховують розтрощені рештки Зорама — прадавнього ельфійського міста, яке тисячі років тому поглинув Великий Розкол. Марукай і захисники застави мало знають про те, чому зміїне плем'я Гнівохвостих саме тепер виповзло з глибоких западин, але їхній раптовий інтерес до затонулих руїн не віщує нічого доброго тим, хто ходить по суходолу."},{t="Ціна виживання",b="Марукай дивиться на все крізь призму простого виживання: коли оголено мечі й тризуби, причини не мають значення. Вимагаючи двадцять відтятих голів загарбників-Гнівохвостих, вона прагне самою лише силою відкинути зміїних чудовиськ назад у глибини й утримати берег для Орди."}},faq={{q="Хто дає завдання «Наги на узбережжі Зорам»?",a="Завдання дає Марукай, тролиця Темного Спису із застави Орди Зорам'гар на узбережжі Зорам у північно-західному Ашенвалі.",al={"хто дає наг на узбережжі зорам","видавець завдання","де марукай"}},{q="Яка історія узбережжя Зорам?",a="Тут спочиває прадавнє приречене місто Зорам. Його зруйнувало й поглинуло Велике Море ще за часів Розколу, і тепер його руїни лежать почасти під водою вздовж узбережжя Ашенвалю.",al={"що таке зорам","історія зорам","затоплене місто"}},{q="Чому наги нападають на берег?",a="Гарнізон Орди не знає, чому саме прибуло плем'я Гнівохвостих, — лише те, що ці істоти вийшли з океанських глибин, щоб захопити затонулі руїни й прогнати всіх суходільних мешканців.",al={"чому наги тут","мотив рат-хвостих","мета наг"}},{q="З якими ворогами треба битися в цьому завданні?",a="Треба вбивати наг із племені Гнівохвостих, що повзають пляжами й прибоєм узбережжя Зорам, і зібрати для Марукай двадцять їхніх відтятих голів.",al={"які наги","голови рат-хвостих","цільові вороги"}},{q="Яке завдання йде після «Наг на узбережжі Зорам»?",a="Більше завдань Марукай не дає: вона просто дякує вам і просить, щоб більше таких, як ви, допомогли втримати узбережжя.",al={"наступне завдання","продовження","марукай далі"}},{q="Чому Орді не байдужий цей віддалений пляж?",a="За Ашенваль запекло борються Орда й нічні ельфи. Надійний морський плацдарм на узбережжі Зорам дає Орді стратегічний доступ і шляхи постачання в обхід густих лісів углибині суходолу.",al={"чому орда тут","мета застави зорам'ґар"}}},fp="24,312,21.388.0,22.371.0,21.317.0,45.144.0,44.218.0,37.204.0,48.166.0,44.124.0,48.217.0"}
P.entries["quest:6461"] = {n="Кровопивці",s="«Кровопивці» — мисливське доручення Орди від Ксен'Зілли в Малака'джині, поселенні племені Темного Спису. Місцеві тролі знайшли на схилах Гір Кам'яного Кігтя вдосталь дичини, але запах розібраного м'яса зманив до їхніх таборів зграї хижих глибокомохових павуків.",h="«Кровопивці» — мисливське доручення Орди від Ксен'Зілли в Малака'джині, поселенні племені Темного Спису.",kw={"кровопивці","ксен'зілла","малака'джин","глибокомохові павуки","тролі","темний спис"},ang={["class:Hunter"]="Вистежувати небезпечних хижаків, які полюють краще за мешканців дружніх поселень і не дають їм спокою, — природна справа для вправних слідопитів, що мандрують кручами.",["faction:Horde"]="Малака'джин тримає шлях Орди з північних Пусток у Гори Кам'яного Кігтя; захистивши село, ви вбережете весь південний перевал.",["race:Troll"]="Мисливці Малака'джина — ваші родичі, які прагнуть вибороти собі самодостатній край у суворому нагір'ї Калімдору й не скоритися дикій природі."},sec={{t="Непрохані гості на вечері",b="Тролі, що заснували прикордонну заставу Малака'джин на південному сході Гір Кам'яного Кігтя, прийшли сюди по добре полювання. Скелясті схили справді виявилися щедрими, але м'ясо й дичина, яку вони приносили, незабаром привабили нічних хижаків. Глибокомохові павуки — агресивні членистоногі, що живуть у кручах і каньйонах на півночі, — почали під покровом темряви прокрадатися в табір, щоб поживитися запасами або самих мисливців обернути на здобич."},{t="Зачистка круч",b="Щоб убезпечити табір і вберегти припаси, Ксен'Зілла просить шукачів пригод вистежити хижаків на півночі, у гірських перевалах. Найгустіше глибокомохові повзуни й отрутоплюви кишать довкола скелястих ярів і павутиння Розколини. Прорідивши їх, ви відкинете виводок від меж Малака'джина, і село зможе спати спокійно, не боячись нападу з тіней."}},faq={{q="Хто дає завдання «Кровопивці»?",a="Ксен'Зілла, троль Темного Спису із селища Малака'джин на південному сході Гір Кам'яного Кігтя, дає це завдання мандрівним поборникам Орди.",al={"хто дає кровопивці","видавець кровопивців","завдання ксен'зілли"}},{q="Чому павуки нападають на Малака'джин?",a="Тролі Малака'джина багато полюють на місцеву дичину. Запах свіжої здобичі й в'ялення м'яса вночі приманює павуків Глибокого Моху з гірських перевалів: вони крадуть припаси й полюють на мешканців селища.",al={"чому павуки нападають","напади павуків на малака'джин","чому павуки вторгаються"}},{q="Де водяться павуки Глибокого Моху?",a="Повзуни й отрутоплюї Глибокого Моху никають центральними перевалами й скелями на північ від Малака'джина, а найгустіше вони кишать в обплутаному павутинням яру, відомому як Ущелина.",al={"де павуки глибокого моху","місця павуків глибокого моху","де глибокомохі слизькі"}},{q="Що таке Малака'джин?",a="Малака'джин — табір тролів Темного Спису в Горах Кам'яного Кігтя, біля їхнього південного входу, неподалік кордону з Пустками; це прикордонна мисливська база й застава Орди.",al={"що таке малака'джин","переказ про малака'джин","тролячий поселенець кам'яного кігтя"}},{q="Чи пов'язана з цими павуками більша загроза?",a="Глибоко в Ущелині серед павутиння живе величезна смертоносна павуча матріарх. Попереджувальний знак біля каньйону остерігає мандрівників і закликає збиратися гуртом, щоб її знищити.",al={"великий павук кам'яного кігтя","еліта ущелини павук","матріарх кам'яного кігтя"}},{q="Що буде, коли проріджувати павуків?",a="Коли повзунів і отрутоплюїв стане менше, Малака'джин зможе перевести подих: тролі-мисливці вбережуть запаси м'яса й ходитимуть табором уночі без постійних засідок.",al={"наслідки кровопивців","чи малака'джин безпечний"}}},fp="13,286,22.448.0,18.397.0,35.154.0,41.208.0,39.188.0,19.192.0,48.187.0,42.181.0"}
P.entries["quest:6462"] = {n="Тролячий Оберіг",s="«Тролячий оберіг» — завдання Орди, яке дає троль Темного Спису Міцува на Заставі Зорам'гар в Ашенвалі. Після того як загін тролів-мандрівників потрапив у засідку й загинув від рук фурболгів Будякохутрих, Міцува просить шукачів пригод проникнути в їхнє лігво й повернути священні талісмани, викрадені в загиблих.",h="«Тролячий оберіг» — завдання Орди, яке дає троль Темного Спису Міцува на Заставі Зорам'гар в Ашенвалі.",kw={"тролячий оберіг","міцува","темний спис","будякохутрі","лоа","завдання"},ang={["faction:Horde"]="Вторгнення на землі Будякохутрих — це удар у відповідь лісовим загрозам, що влаштовують засідки на шляхи постачання й мандрівників Орди в Ашенвалі.",["race:Troll"]="Повернути обереги — духовний обов'язок тролів Темного Спису: так священні речі предків вириваються з лап диких фурболгів."},sec={{t="Засідка на караван",b="Застава Зорам'гар — віддалений західний притулок Орди на узбережжі Ашенвалю, тож подорожі лісовими стежками сповнені небезпек. Загін тролів Темного Спису, що йшов до застави, так і не дійшов: на нього жорстоко напало плем'я фурболгів Будякохутрих, що люто стереже свої землі. Міцува сприймає смерть родичів як майбутню зустріч у потойбіччі, але осквернення й крадіжка їхніх священних оберегів — нестерпна образа."},{t="Священні дрібнички",b="У тролячій культурі обереги й талісмани глибоко пов'язані з особистістю, духовним захистом і зв'язком із лоа. Міцува вважає троля без оберега таким самим порожнім і нікчемним, як орка без бойових шрамів. Фурболги Будякохутрі затягли викрадені речі до Твердині Будякохутрих, глибоко в печери за Селом Будякохутрих, і поховали їх у скринях подалі від законних власників."}},faq={{q="Хто дає це завдання і де його знайти?",a="Завдання дає Міцува, троль Темного Спису із Застави Зорам'гар на узбережжі Зорам, на північно-західному березі Ашенвалю.",al={"хто дає завдання","де міцува","хто починає тролячий оберіг"}},{q="Чому тролячі обереги такі важливі для Міцуви?",a="Для тролів священні обереги мають глибоке духовне й культурне значення. Міцува порівнює троля без оберега з орком без бойових шрамів, і те, що ворожі фурболги тримають ці реліквії в себе, вважає обурливою наругою над його загиблими родичами.",al={"важливість оберегів","чому тролячі обереги важливі","значення оберегів"}},{q="Де знайти тролячі обереги?",a="Обереги зберігаються в скринях у Твердині Будякохутрих — глибоких печерах на північному краю Села Будякохутрих, що на північ від поселення нічних ельфів Астранаар.",al={"місця оберегів","де скрині","знайти обереги"}},{q="Хто викрав обереги?",a="Фурболги Будякохутрі напали із засідки й убили родичів Міцуви, коли ті йшли до Застави Зорам'гар, пограбували їхні речі й затягли священні обереги до своїх печер.",al={"хто забрав обереги","винуватці засідки"}},{q="Що сталося з тролями, які несли обереги?",a="Їх убили фурболги Будякохутрі на стежці. Міцува оплакує їх, але вірить, що зрештою возз'єднається з ними в потойбіччі, тож насамперед хоче повернути їхні священні реліквії.",al={"доля каравану","вбиті тролі","рідня міцуви"}},{q="Чи доступне це завдання Альянсу?",a="Ні. Завдання починається на Заставі Зорам'гар і доступне лише гравцям Орди, які допомагають племені Темного Спису.",al={"тролячий оберіг альянс","чи альянс може це"}}},fp="11,292,19.467.0,15.422.0,48.142.0,49.253.0,35.190.0,21.181.0,62.205.0,40.117.0"}
P.entries["quest:647"] = {n="Самогон МакКрила",s="«Самогон МакКрила» — швидке доручення від Фоґґі Маккріла, дворфа, що застряг на зруйнованій частині Мосту Тандол. Перебравши власного міцного трунку й проспавши свою варту, Фоґґі доручає мандрівникові з Альянсу якнайшвидше доставити свіжу партію до Гілсбреда, щоб розрахуватися з давнім боргом перед Броварником Білґером у Саутшорі.",h="«Самогон МакКрила» — швидке доручення від Фоґґі Маккріла, дворфа, що застряг на зруйнованій частині Мосту...",kw={"самогон маккріла","фоґґі маккріл","броварник білґер","саутшор","міст тандол","борг"},ang={["faction:Alliance"]="Цей швидкий суходільний рейс показує життєво важливий зв'язок між Мостом Тандол і Саутшором у Гілсбреді, який тримає Альянс.",["race:Dwarf"]="Дворфи одразу зрозуміють подвійну біду: нестерпне похмілля й несплачений пивоварський борг перед побратимом."},sec={{t="Похмілля вартового",b="Варта на зруйнованому Мосту Тандол — мокра, холодна й сумнозвісно нудна. Фоґґі Маккріл рятується від вогкого холоду власним саморобним самогоном — таким лютим, що його наслідки він порівнює з цілою бригадою облогових машин, що прокотилася йому по черепу. На біду Фоґґі, одна чарка виявилася зайвою — і він знепритомнів просто на посту. Оскільки дворфами, що обороняють міст, командує Лонґбрейд Похмурий, Фоґґі не може собі дозволити ще одного порушення дисципліни."},{t="Наввипередки з часом",b="Клопоти Фоґґі ускладнює давній борг перед Броварником Білґером у Саутшорі. Фоґґі пообіцяв Білґерові партію власного трунку, щоб звести рахунки, але через похмілля й службу він за лічені хвилини від того, щоб не дотримати слова. Покладаючись на грифонів і прудкі ноги, мандрівники мають мчати через Аратійське нагір'я до Саутшора й доставити глечик, поки Білґер не вирішив, що Фоґґі знову втік від свого боргу."}},faq={{q="Хто такий Фоґґі Маккріл?",a="Фоґґі Маккріл — дворф, якого можна знайти на зруйнованій частині Мосту Тандол, куди доходять з боку Аратійського нагір'я. Він славиться надзвичайно міцним саморобним самогоном і на варті надто охоче куштує власний виріб.",al={"фоґґі маккріл","хто такий фоґґі","видавець маккріл"}},{q="Чому ця доставка така термінова?",a="Фоґґі страшенно відстав від графіка, бо напився й заснув на варті. Він мусить до суворого терміну доставити самогон Броварникові Білґеру, щоб погасити давній борг, а на дорогу від Мосту Тандол до Саутшора лишилося ледве чверть години.",al={"чому є таймер","чому 15 хвилин","таймер самогону маккріла"}},{q="Хто такий Броварник Білґер?",a="Броварник Білґер — майстер-пивовар із дворфів, що займається своїм ремеслом у прибережному поселенні Саутшор у Передгір'ї Гілсбреда. Він цінує міцний трунок і має з Фоґґі Маккрілом давню ділову домовленість.",al={"броварник білґер","хто такий білґер","білґер саутшор"}},{q="Як устигнути доставити самогон до Саутшора вчасно?",a="Човен від Мосту до Саутшора не ходить. Найшвидше — податися в Аратійське нагір'я й, якщо ви знаєте цей маршрут, полетіти грифоном із Притулку до Саутшора, а тоді знайти в містечку Броварника Білґера, поки не сплив час.",al={"як доставити самогон","найшвидший шлях до саутшора","маршрут доставки самогону"}},{q="Хто такий Лонґбрейда?",a="Лонґбрейда Похмурий — дворф-командувач, що стоїть під Дун Модром у Багнокраї й очолює оборонців Мосту Тандол. Фоґґі до смерті боїться, що Лонґбрейда дізнається, як він упився до непритомності, коли мав стояти на варті.",al={"капітан лонґбрейда","лонґбрейда менетіл"}}},fp="20,347,18.478.0,24.441.0,22.235.0,31.267.0,26.229.0,53.246.0,17.248.0"}
P.entries["quest:6481"] = {n="Земельники повстають",s="Глибоко в Яру Кам'яного Зсуву шаман Мор'роґал виявляє сплячого землянина на ім'я Ґоґґерок, запечатаного в резонітовій скрині. Побоюючись, що прадавня кам'яна істота може обрушити на Калімдор свою первісну руйнівну силу, він посилає героя розбити скриню й повалити Ґоґґерока, перш ніж той відновить повну міць.",h="Глибоко в Яру Кам'яного Зсуву шаман Мор'роґал виявляє сплячого землянина на ім'я Ґоґґерок, запечатаного в...",kw={"земляни повстають","ґоґґерок","мор'роґал","яр кам'яного зсуву","резоніт","землянин"},ang={["class:Shaman"]="Мор'роґал спрямовує шаманську силу, щоб змінити резонітові кристали й порушити стихійну рівновагу, яка зберігає землянина в скрині.",["faction:Horde"]="Знищивши Ґоґґерока, герої Орди закріплюються серед спірних круч Гір Кам'яного Кігтя й здобувають тривку повагу провідників Тандер Блафа.",["race:Tauren"]="Гори Кам'яного Кігтя — священні мисливські угіддя предків для племен Тандер Блафа, і знешкодження прадавньої руйнівної сутності в глибинах гір захищає землю від загибелі."},sec={{t="Сон у камені",b="Досліджуючи навалу шкідників у Яру Кам'яного Зсуву, розвідники натрапили серед кобольдів на дивну реліквію — резонітову скриню, що випромінювала неземну силу. Мор'роґал, шаман-таурен у Горах Кам'яного Кігтя, збагнув, чим насправді є ця скриня: в'язницею і водночас прихистком для Ґоґґерока, сплячого землянина. Ці первісні кам'яні творіння сильніші за будь-якого смертного воїна, тож Ґоґґерок, що вільно блукає краєм, — загроза самому існуванню цих земель."},{t="Резонітовий Кристал",b="Пробуджений у повній силі землянин обернувся б лихом для Гір Кам'яного Кігтя. Щоб схилити шальки терезів, Мор'роґал змінив суміш принесених йому резонітових кристалів, наповнивши їх шаманською магією. Утворений зачарований кристал має розбити резонітову скриню з такою силою, щоб Ґоґґерок прокинувся різко ослабленим. Воякам Орди лишається розтрощити скриню й повалити ошелешену, титанами створену істоту, перш ніж вона струсить із себе століття заціпеніння."}},faq={{q="Хто такий Мор'роґал?",a="Мор'роґал — шаман-таурен у Горах Кам'яного Кігтя. Він вивчає негаразди в краї й за допомогою магії стихій розбирається з дивними прадавніми артефактами й загрозами, які викопали місцеві паразити.",al={"мор'роґал","хто видає завдання","орк шаман мор'роґал"}},{q="Хто такі земляни?",a="Земляни — прадавні істоти з живого каменю, творіння, які Титани лишили на світанку світу. Глибоко пов'язані із землею й наділені неймовірною фізичною силою, вони тисячоліттями спали, поховані по всьому Калімдору й Східних Королівствах.",al={"що таке земляни","переказ про землян","хто такі земляни"}},{q="Чому Мор'роґал хоче смерті Ґоґґерока?",a="Мор'роґал боїться, що незрівнянна сила пробудженого землянина накличе біду на Кам'яний Кіготь і весь Калімдор. Такі первісні істоти непередбачувані й надзвичайно могутні, тож він вважає, що знищити Ґоґґерока, поки той ослаблений після сну, — єдиний спосіб уберегти землю.",al={"чому вбити ґоґґерока","чи ґоґґерок злий","чому вбивати землян"}},{q="Де знайти Ґоґґерока?",a="Ґоґґерок замурований у резонітовій скрині глибоко в печерах Яру Кам'яного Зсуву, на південному сході Гір Кам'яного Кігтя, серед кобольдів Кам'яного Зсуву, що риють ходи в печерах.",al={"де діжка","місце ґоґґерока","знайти діжку з резонітом"}},{q="Як пробудити Ґоґґерока?",a="Застосуйте Зачарований Кристал Резоніту, який дає Мор'роґал, просто до резонітової скрині в печері. Магічно змінений кристал розколює вмістилище й змушує сплячого землянина вийти назовні.",al={"як призвати ґоґґерока","використати зачарований кристал резоніту","відкрити діжку"}},{q="Що буде після смерті Ґоґґерока?",a="Коли ви повернетеся до Мор'роґала з вісткою про смерть Ґоґґерока, глибокий страх шамана розвіється. Він славить вас як героя, чий подвиг відвернув величезне лихо, і це приносить вам велику шану серед тауренів Тандер Блафа.",al={"історія нагороди","реакція мор'роґала","здати земляни повстають"}}},fp="13,335,18.513.0,20.491.1,17.221.0,19.254.0,38.305.0,26.203.0,27.210.0,37.227.1"}
P.entries["quest:6482"] = {n="Свобода для Руула",s="Глибоко у Твердині Будякохутрих на півночі Ашенвалю замкнений у клітці ведмідь на ім'я Руул чекає порятунку від зіпсованих фурболгів Будякохутрих. Шукачі пригод з Орди можуть допомогти бранцеві пробитися з лігва фурболгів у безпечне місце.",h="Глибоко у Твердині Будякохутрих на півночі Ашенвалю замкнений у клітці ведмідь на ім'я Руул чекає порятунку...",kw={"свобода для руула","руул сноугуф","друїд","будякохутрі","порятунок","завдання"},ang={["class:Druid"]="Полон Руула — повчальне нагадування про ризики блукання дикими землями у звіриній подобі, де зіпсовані місцеві не відрізнять друга від здобичі.",["faction:Horde"]="Кожна душа, врятована із зіпсованих западин північного Ашенвалю, зміцнює хитку заставу Орди — Розщеплене Дерево.",["race:Tauren"]="Порятунок брата з Кола Кенарія, що опинився в біді, і полегшення тривоги його родини на Заставі Розщепленого Дерева шанують узи Земної Матері та Орди."},sec={{t="Друїд у кайданах",b="Мандруючи зіпсованими лісами північного Ашенвалю, друїд Руул Сноугуф у подобі ведмедя забрів надто близько до Твердині Будякохутрих. Зіпсовані фурболги, втративши мудрість предків і ведені дикою підозріливістю, сприйняли перевтіленого таурена за звичайного звіра. Замість поставитися до нього з шаною, вони замкнули його в клітці й морили голодом, виснажуючи його магічні сили, тож тепер він не може сам вирватися."},{t="Утеча з лігва",b="Знесилений голодом і неволею, Руул не може ні змінити подобу, ні сам пробитися крізь печерне поселення фурболгів. Звільнений союзником з Орди, він покладається на свого рятівника, щоб той проклав шлях крізь хвилі ворожих Будякохутрих. Безпечно діставшись околиць Застави Розщепленого Дерева, він ненадовго показує свою справжню тауренську подобу, щоб щиро подякувати, а тоді повертається в глушину відсипатися після виснаження."}},faq={{q="Чому фурболги замкнули Руула Сноугуфа?",a="Руул досліджував ліси у ведмежій подобі. Осквернені фурболги Будякохутрі не впізнали в ньому друїда, сприйняли за дикого звіра й замкнули в клітці, де морили голодом, доки в нього не лишилося сил утекти.",al={"чому руул у пастці","як руула схопили","чому в клітці"}},{q="Хто така Яма Сноугуф?",a="Яма Сноугуф — сестра Руула із Застави Розщепленого Дерева в Ашенвалі. Вона дуже тривожилася, відколи кілька днів тому Руул пішов у ліс і не повернувся.",al={"сестра руула","яма розщепленого дерева","хто така яма"}},{q="Чому Руул не міг просто вийти з ведмежої подоби й утекти?",a="Довгий полон і навмисне голодування, на яке прирекли його фурболги Будякохутрі, тяжко виснажили Руула. Без їжі й сил його запаси природної енергії цілком вичерпалися, і він був безпорадний, доки його не врятували.",al={"чому руул не змінив подобу","пастка для друїда-ведмедя"}},{q="Що буде, коли Руул опиниться в безпеці?",a="Коли ви виведете його з ворожого лігва до меж Застави Розщепленого Дерева, Руул ненадовго повертає собі подобу таурена, щоб подякувати, а тоді знову стає ведмедем і йде шукати тихе місце, щоб виспатися й оговтатися.",al={"куди йде руул","кінцівка руула"}},{q="Чи всі фурболги в Ашенвалі ворожі, як Будякохутрі?",a="Ні. Багато племен фурболгів мають шляхетне коріння й глибокий зв'язок із природою, але Будякохутрі з півночі Ашенвалю піддалися темним, згубним впливам, що зробили їх агресивними й непередбачуваними.",al={"чи всі фурболги злі","осквернення будякохутрих"}},{q="Де відбувається порятунок?",a="Руул ув'язнений у Твердині Будякохутрих — лігві фурболгів у пагорбах на північний захід від Застави Розщепленого Дерева й на північ від Астранаару в Ашенвалі.",al={"де руул","місце руула сноугуфа"}}},fp="15,223,17.433.0,19.421.1,48.238.1,21.176.0,56.235.1,39.229.1,59.215.0,33.145.0"}
P.entries["quest:65"] = {n="Братство Дефіас",s="Це доручення — перший крок до розплутування таємного угруповання, що тероризує Вестфол. Ґраян Стаутмантл із Сентінел Гілла відправляє мандрівників на схід, до Редріджу, — порадитися з темним знайомим, який може знати, де ховаються злодії.",h="Це доручення — перший крок до розплутування таємного угруповання, що тероризує Вестфол.",kw={"братство дефіас","ґраян стаутмантл","вайлі чорний","лейкшир","редрідж","вестфол"},ang={["class:Rogue"]="Стаутмантл розуміє, що звичайна солдатська муштра не зламає злочинного угруповання: потрібен той, хто знається на тінях і вуличних послугах, — і цей шлях веде просто до Вайлі Чорного.",["faction:Alliance"]="Довга дорога з Вестфолу до Редріджу показує, наскільки віддалені землі Стормвінда мусять покладатися одна на одну, поки столиця лишається байдужою."},sec={{t="Загроза в пилюці",b="Вестфол лежить у руїні: його врожаї розграбовано, а землі заполонили розбійники в червоних банданах. Ґраян Стаутмантл і Народне ополчення утримують Сентінел Гілл попри майже безперервні напади, але воюють наосліп. Стаутмантл розуміє: рубаючи поодиноких мародерів, край не врятувати — треба знайти внутрішнє коло угруповання й з'ясувати, хто ним командує."},{t="Знайомий з іншого краю",b="Замість покладатися на офіційні військові канали чи на вельмож Стормвінда, яких тут ніколи не буває, Стаутмантл згадує, хто перед ним у боргу. Він відправляє довірених шукачів пригод повз Елвінн у Гори Редріджу. У тихому приозерному селищі Лейкшир, на горішньому поверсі місцевої корчми, переховується пройдисвіт на ім'я Вайлі Чорний. Він знає підпілля значно краще за будь-якого капітана ополчення, тож саме Вайлі — перша ниточка, що допоможе розплутати схованки Братства."}},faq={{q="Хто такий Ґраян Стаутмантл?",a="Ґраян Стаутмантл — ватажок Народного ополчення, строкатого загону оборони на Сентінел Гіллі у Вестфолі. Поки Стормвінд нехтує прикордонням, він організовує захист небагатьох фермерів і біженців, що там лишилися.",al={"ґраян стаутмантл","хто дає це завдання","видавець вестфол"}},{q="Чому Стаутмантл посилає мене до Лейкшира?",a="Народне ополчення не має інформаторів у підпіллі самого Вестфолу. Стаутмантл просить давньої особистої послуги у Вайлі Чорного, розбійника, що мешкає в корчмі Лейкшира, сподіваючись, що зв'язки в злочинному світі допоможуть з'ясувати, хто веде злодіїв.",al={"чому лейкшир","чому йти до реджриджа","чому вайлі"}},{q="Хто такий Вайлі Чорний?",a="Вайлі Чорний — розбійник, що зупинився на другому поверсі Корчми Лейкшира в Горах Редріджу. Він винен Ґраянові Стаутмантлу послугу, тож через нього зручно дізнаватися підпільні чутки й шукати кримінальні зв'язки.",al={"хто такий вайлі","вайлі лейкшир","вайлі чорний"}},{q="Що таке Братство Дефіас?",a="Братство Дефіас — безжальне злочинне угруповання в червоних масках, що захопило ферми, дороги й покинуті копальні Вестфолу, виганяє поселенців і кидає виклик владі Стормвінда.",al={"братство дефіас","що таке дефіас","бандити з червоними пов'язками"}},{q="Де в Лейкширі знайти Вайлі?",a="Вайлі Чорний — нагорі, на другому поверсі Корчми Лейкшира, що стоїть біля мосту в містечку Лейкшир у Горах Редріджу.",al={"де вайлі","знайти вайлі","місце вайлі"}},{q="Чи доведеться битися в цьому завданні?",a="Ні. Цей перший крок — суто розвідувальний. Ви просто вирушаєте із Сентінел Гілла у Вестфолі через Ліс Елвінн до корчми в Лейкширі, щоб зв'язатися з Вайлі.",al={"чи важке це завдання","бій у завданні братство дефіас","вороги"}}},fp="22,253,22.387.0,22.453.0,25.238.0,43.236.0,23.210.0,31.221.0,36.149.0,35.171.0"}
P.entries["quest:6503"] = {n="Ашенвальські розвідниці",s="«Ашенвальські розвідниці» — завдання Орди на перехоплення дозорів, яке дає Курай'бін в Ашенвалі. Розвідниці нічних ельфів розійшлися від Застави Срібнокрилих, щоб збирати відомості про довколишні табори Орди, тож Орда завдає випереджального удару, щоб приховати оборону застави. Полюючи на цих потайних розвідниць, Орда засліплює місцеві сили Альянсу й відбиває охоту до нових вилазок.",h="«Ашенвальські розвідниці» — завдання Орди на перехоплення дозорів, яке дає Курай'бін в Ашенвалі.",kw={"ашенвальські розвідниці","курай'бін","застава срібнокрилих","розвідка","орда","завдання"},ang={["class:Hunter"]="Щоб вистежити розвідниць, що ховаються в лісовій гущавині, потрібні гостре чуття, загострений нюх слідопита й влучне око.",["class:Rogue"]="Знищення ворожих розвідниць обертає потайність нічних ельфів проти них самих і забезпечує лазутчикам Орди владу над тінями лісу.",["faction:Horde"]="Кожна розвідниця нічних ельфів, убита в Ашенвалі, захищає місцеві табори й лісозаготівлі від злагоджених контрнаступів Альянсу."},sec={{t="Очі в кронах",b="Ліси Ашенвалю лишаються спірним прикордонням, де пильно стежать за кожною стежкою й кожним гребенем. Розвідка тут смертоносна, як сокира, і донесення, що доходять до Курай'біна, підтверджують: розвідниці нічних ельфів, відомі як ашенвальські розвідниці, вислизнули з твердині Альянсу — Застави Срібнокрилих. Діючи в густій глушині на схід від своєї бази й на південь від місцевих володінь Орди, вони никають лісовими стежками, наносячи на мапу укріплення й стежачи за пересуванням військ."},{t="Засліпити Альянс",b="Щоб запобігти злагодженому нападу, Орда покладається на знищення ворожої розвідки, перш ніж та повернеться додому. Полюючи на розвідниць, звитяжці Орди позбавляють командирів Застави Срібнокрилих важливих знань про чисельність військ і оборону периметра застави. Утративши передові очі, нічні ельфи збиті з пантелику й значно менше схильні ризикувати сміливими маневрами в спірних лісах."}},faq={{q="Хто дає завдання «Ашенвальські розвідниці»?",a="Завдання дає Курай'бін, розвідник Орди в Ашенвалі, який організовує стеження за нічними ельфами в лісі й протидію їм.",al={"видавець завдання","хто дає завдання","завдання кураї'біна"}},{q="Де знайти ашенвальських розвідниць?",a="Розвідниці нишпорять лісами на схід від Застави Срібнокрилих і на південь від табору Курай'біна, пробираючись підліском, щоб збирати відомості.",al={"місця розвідниць","де розвідниці","де знайти розвідниць"}},{q="Чому розвідниці загрожують Орді?",a="Розвідниці — передові вивідувачки із Застави Срібнокрилих. Якщо вони нанесуть на мапу табори Орди й порахують її загони, Альянс зможе влаштувати точні набіги на вразливі позиції.",al={"чому вбивати розвідниць","загроза розвідниць","призначення розвідниць"}},{q="Що таке Застава Срібнокрилих?",a="Застава Срібнокрилих — помітний військовий пункт нічних ельфів в Ашенвалі, передова база сил Альянсу, що боронять ліс і протистоять поширенню Орди.",al={"переказ про заставу срібнокрилих","що таке застава срібнокрилих","срібнокрилі альянс"}},{q="Чи це завдання — частина довшої історії?",a="Здебільшого це окреме тактичне завдання, що має послабити розвідку Альянсу на цій ділянці; воно винагороджує бійців, які допомагають Курай'біну вберегти периметр.",al={"ланцюжок завдань","наступне завдання","ланцюжок розвідниць"}},{q="Чи можуть гравці Альянсу виконати це завдання?",a="Ні, це завдання лише для Орди. Курай'бін діє виключно в інтересах передової Орди в Ашенвалі.",al={"чи це лише для орди","версія для альянсу","чи альянс може це"}}},fp="20,388,20.476.0,21.423.0,41.151.0,43.148.0,45.204.0,27.180.0,41.179.0,41.119.0"}
P.entries["quest:6504"] = {n="Загублені сторінки",s="Коли оркиня Ґурда Рейджскар везла щойно придбаний гоблінський подрібнювач із Раджета до Лісозаготівельного Табору Бойової Пісні, раптовий порив вітру вирвав у неї посібник з керування машиною. Застрягши біля Застави Розщепленого Дерева, вона не може запустити це складне інженерне диво, поки не збере розкидані сторінки.",h="Коли оркиня Ґурда Рейджскар везла щойно придбаний гоблінський подрібнювач із Раджета до Лісозаготівельного...",kw={"загублені сторінки","ґурда рейджскар","подрібнювач","посібник","бойова пісня","завдання"},ang={["faction:Horde"]="Кожен подрібнювач, що дістається Лісозаготівельного Табору Бойової Пісні, пришвидшує заготівлю дорогоцінної деревини, потрібної для мурів, хатин і бойових кораблів Дуротару.",["profession:Engineering"]="Майстри добре зрозуміють клопіт Ґурди: керувати збудованим гоблінами подрібнювачем без настанов виробника — найпевніший шлях до катастрофічного вибуху котла.",["race:Orc"]="Ручна праця й воїнські традиції не залишають терпцю на докладну гоблінську паперову тяганину, тож роздратування Ґурди через загублені технічні аркуші цілком зрозуміле."},sec={{t="Порив невдачі",b="Клан Бойової Пісні значною мірою покладається на парові подрібнювачі, куплені в гоблінів із порту Раджет, щоб валити ліс по всьому Ашенвалю. Керувати цими примхливими, гучними штуковинами звичайному орку-воїнові зовсім не просто. Коли Ґурда Рейджскар вирушила на північ із новеньким подрібнювачем, раптовий порив вітру вирвав у неї з рук книжечку з інструкціями й розкидав дванадцять тендітних пергаментних аркушів по всьому лісі."},{t="Сторінки в глушині",b="Буйні вітри перенесли посібник через крони, і окремі сторінки опинилися в руках блукаючих істот, сектантів і лісових мешканців по всьому краю. Без усіх трьох розділів складна машина лишається мертвою брилою сталі з циркулярними пилками, а Ґурда застрягла на дорозі до Застави Розщепленого Дерева й не може стати до лісозаготівель."}},faq={{q="Хто така Ґурда Рейджскар?",a="Ґурда Рейджскар — робітниця Орди, якій доручили перегнати гоблінський шредер із торгового порту Раджет до Ашенвалю, щоб він долучився до робіт у Лісозаготівельному Таборі Бойової Пісні.",al={"ґурда","рейджскар","видавець завдання"}},{q="Навіщо Ґурді інструкція, щоб керувати шредером?",a="Гоблінська інженерія славиться примхливістю й нелогічністю: вибухонебезпечні котли, хитромудрі клапани тиску й складні важелі. Навіть завзятий орк не зможе безпечно керувати цією штуковиною, не прочитавши інструкції від виробника.",al={"навіщо інструкція","чому вона не може керувати","інструкція керування шредером"}},{q="Як сторінки інструкції опинилися по всьому Ашенвалю?",a="Коли Ґурда йшла лісовою дорогою на північ, сильний порив вітру вирвав книжку з її рук. Аркуші розлетілися лісом, і в неї лишилася тільки порожня обкладинка.",al={"як сторінки загубилися","вітер розніс сторінки"}},{q="Куди зрештою має потрапити шредер?",a="Машина призначена для Лісозаготівельного Табору Бойової Пісні, де Орда завзято вирубує ліс, щоб постачати деревину до Оргріммара й Дуротару.",al={"куди йде шредер","призначення шредера бойової пісні"}},{q="Де знайти загублені сторінки?",a="Вітер розніс сторінки далеко й широко, і їх підібрали різні гуманоїди та ворожі мешканці лісу, що блукають Ашенвалем.",al={"де знайти сторінки","хто дає сторінки"}},{q="Чому Орда купує машини в Раджеті?",a="Раджет — найближчий нейтральний порт із діяльними торговими зв'язками з гоблінськими картелями. Орда регулярно купує там спеціальне інженерне обладнання, підривні знаряддя й парові машини, щоб посилити своє військове постачання.",al={"гоблінські машини орди","торгівля орди з раджетом"}}},fp="14,296,18.449.0,23.388.0,22.180.0,64.235.0,61.195.0,42.159.0,37.143.0,51.225.0"}
P.entries["quest:6523"] = {n="Захисти Каю",s="«Захисти Каю» — завдання Орди із супроводу в Горах Кам'яного Кігтя. Знайшовши Каю Флетгуф у полоні ворожих тауренів-Ґрімтотемів, шукачі пригод проводять її небезпечними гірськими стежками до Табору Апараже. Звістка про те, що вона жива, приносить величезне полегшення її стривоженому батькові, Макабі Флетгуфу.",h="«Захисти Каю» — завдання Орди із супроводу в Горах Кам'яного Кігтя.",kw={"захисти каю","кая флетгуф","макаба флетгуф","табір апараже","ґрімтотем","супровід"},ang={["faction:Horde"]="Безпека родин у дорозі зміцнює тяжко здобуті опорні пункти й шляхи постачання Орди в Горах Кам'яного Кігтя.",["race:Tauren"]="Порятунок Каї — пряма допомога родичам, яких розлучила хижа агресія клану Ґрімтотем."},sec={{t="Бранка серед круч",b="У Горах Кам'яного Кігтя таурени мають чимало гірких суперечок, але жодна не така гостра, як ворожнеча довкола віроломного клану Ґрімтотем. Глибоко на ворожій землі Каю Флетгуф схопили й тримали в полоні. Щоб утекти пішки, треба пройти звивистими стежками, обабіч яких чатують хижаки й пильні вороги, тож збройний супровід — її єдина реальна надія дістатися своїх."},{t="Втеча до Табору Апараже",b="Табір Апараже лежить на сході Гір Кам'яного Кігтя, і звідти Кая знає дорогу додому. Вона прямує до табору, певна, що, діставшись його, далі дійде сама. Провівши її стежками, де на кожному кроці засідки, ви не дасте знову схопити її, перш ніж викрадачі помітять, що бранка втекла."},{t="Батькове полегшення",b="Чекаючи вістей біля південно-східного кордону Гір Кам'яного Кігтя, Макаба Флетгуф боїться найгіршого за свою зниклу доньку. Коли гінці приносять підтвердження, що Кая щасливо дісталася Табору Апараже, розпач Макаби змінюється безмежною вдячністю героям, які стали між його дитиною та її викрадачами."}},faq={{q="Хто така Кая Флетгуф?",a="Кая Флетгуф — молода тауренка, яку захопили в полон ворожі загони Ґрімтотем у Горах Кам'яного Кігтя. Вона покладається на мандрівних шукачів пригод Орди, щоб ті визволили її й провели в безпечне місце.",al={"хто така кая","переказ про каю флетгуф","кая"}},{q="Куди треба провести Каю?",a="Каю треба безпечно провести стежками до Табору Апараже на сході Кам'яного Кігтя, звідки вона вже сама знає дорогу додому.",al={"куди вести каю","куди супроводжувати каю","куди йде кая"}},{q="Хто такий Макаба Флетгуф?",a="Макаба Флетгуф — батько Каї, що з тривогою чекає біля південно-східного входу в Гори Кам'яного Кігтя. Він у розпачі через зниклу доньку, доки шукачі пригод не принесуть звістку про її порятунок.",al={"хто такий макаба","переказ про макабу флетгуфа","батько каї"}},{q="Хто захопив Каю?",a="Каю взяли в полон ворожі таурени Ґрімтотем, які мають табори й засідки по всіх скелях Кам'яного Кігтя.",al={"хто забрав каю","хто викрав каю","викрадачі каї"}},{q="Що буде, коли Кая дістанеться Табору Апараже?",a="Щойно Кая дістанеться Табору Апараже, вона далі піде сама, а гравцеві треба повернутися до Макаби Флетгуфа з радісною звісткою, що вона жива.",al={"після захисти каю","що далі після супроводу","продовження захисти каю"}},{q="Чи доступне це завдання гравцям Альянсу?",a="Ні. Родина Флетгуф належить до мирних тауренів, союзників Орди, тож ця рятувальна місія — лише для шукачів пригод Орди.",al={"чи альянс може захисти каю","чи кая лише для орди"}}},fp="12,311,22.400.0,22.295.0,17.322.1,21.195.0,36.131.0,23.190.0,18.115.0,45.162.0,44.137.0"}
P.entries["quest:6541"] = {n="Доповідь Кадраку",s="Торк на Перехресті скеровує вправних бійців Орди на північ, до сторожової вежі Кадрака біля кордону з Ашенвалем. Кадрак керує просуванням Орди в прадавній ліс і готує новобранців до сутичок, що чекають попереду.",h="Торк на Перехресті скеровує вправних бійців Орди на північ, до сторожової вежі Кадрака біля кордону з...",kw={"доповідь кадраку","кадрак","торк","ашенваль","застава розщепленого дерева","перехрестя"},ang={["faction:Horde"]="Це розпорядження знаменує перехід від оборони освоєних земель у Пустках до захисту життєво важливих ресурсних шляхів у спірних лісах на півночі.",["race:Orc"]="Ашенваль — важливе випробувальне поле для орків: тут вони здобувають деревину, потрібну, щоб зміцнити Оргріммар і збудувати тривкий дім у Калімдорі."},sec={{t="Дорога на північ",b="Поки Перехрестя дає раду шипогривам, кентаврам і місцевим розбійникам, ширші територіальні інтереси Орди звернені на північ — до густих лісів Ашенвалю. Торк править за посередника: він скеровує досвідчених бійців, що проявили себе в центральних Пустках, до північної прикордонної вежі, яку тримає Кадрак."},{t="Стратегія рубежу",b="Кадрак наглядає за південними підступами до Ашенвалю й організовує підкріплення для позицій Орди за кордоном. Завдяки новим таборам на кшталт Застави Розщепленого Дерева й застави на Зорамському Березі Орда рішуче зміцнює свою присутність у багатих на деревину лісах, попри запеклий опір місцевих нічних ельфів."}},faq={{q="Хто такий Торк?",a="Торк — орк-офіцер на Перехресті в Пустках. Він допомагає організовувати місцеву оборону й скеровує перспективних шукачів пригод на війну в інших краях, як-от у кампанію в Ашенвалі.",al={"торк перехрестя","хто дає доповідь кадраку","торк пустки"}},{q="Де знайти Кадрака?",a="Кадрак стоїть на північній сторожовій вежі в Пустках, просто біля головної дороги, що веде в ліси Ашенвалю.",al={"місце кадрака","де кадрак","вартова вежа кадрака"}},{q="Чому Орда просувається в Ашенваль?",a="Орді потрібні деревина й ресурси, щоб будувати нові міста в Дуротарі та Пустках. Розширення в Ашенваль дає життєво важливий ліс, хоч і ставить Орду у відкрите протистояння з нічними ельфами.",al={"чому ашенваль","орда в ашенвалі","вторгнення в ашенваль"}},{q="Які застави Орда заснувала в Ашенвалі?",a="Кадрак зауважує, що Орда заснувала Заставу Розщепленого Дерева біля центральної дороги в ліс і ще одну заставу далі на захід, на узбережжі Зорам.",al={"бази орди в ашенвалі","база зорамського узмор'я","розщеплене дерево"}},{q="Що далі, після доповіді Кадракові?",a="Коли ви доповісте Кадракові, він розповість вам про військову ситуацію в краї й доручить зібрати донесення з різних застав Бойової Пісні по всьому Ашенвалю.",al={"після кадрака","наступне завдання після кадрака","що дає кадрак"}},{q="Чи можна отримати це доручення деінде, крім Пусток?",a="Так. Майже такий самий наказ доповісти Кадракові отримують бійці Орди, що діють із Малака'джина в Горах Кам'яного Кігтя.",al={"інше завдання кадрака","завдання кадрака в кам'яному кігті"}}},fp="16,238,14.323.0,17.338.0,13.204.0,24.127.0,40.204.0,53.157.0,37.158.0,69.136.0"}
P.entries["quest:6542"] = {n="Доповідь Кадраку",s="Цей військовий наказ спрямовує воїнів Орди з Малака'джина в Горах Кам'яного Кігтя на сторожовий пост Кадрака на кордоні північних Пусток. Він знаменує перехід від оборони круч до підсилення суперечливої військової кампанії Орди в Ашенвалі. Доповівши Кадраку, вояки стають до лав, щоб підтримати передові табори — Заставу Розщепленого Дерева й Зорамське Узмор'я.",h="Цей військовий наказ спрямовує воїнів Орди з Малака'джина в Горах Кам'яного Кігтя на сторожовий пост Кадрака...",kw={"доповідь кадраку","кадрак","дарн талонґріп","ашенваль","застава розщепленого дерева","бойова пісня"},ang={["faction:Horde"]="Цей наказ залучає вас до ширших воєнних зусиль Вождя: досвідчених прикордонних бійців спрямовують у запеклу боротьбу за багатства Ашенвалю.",["race:Orc"]="Похід в Ашенваль вирішальний для клану Бойової Пісні й для виживання Дуротару, тож пост Кадрака — місце, де молоді орки-воїни доводять, чого варті.",["race:Tauren"]="Дозорці Орди, як-от орк Дарн Талонґріп, безпечно проводять мандрівників через гірські кордони й тримають зв'язок між землями Бладгуфів і північним фронтом Вождя."},sec={{t="Поклик північного фронту",b="На скелястому перевалі Малака'джин орк Дарн Талонґріп пильнує південні й гірські рубежі Орди. Та найбільший військовий тиск — на півночі, у прадавніх лісах Ашенвалю, де Вартові нічних ельфів безперестанку б'ються з лісорубами клану Бойової Пісні. Помічаючи загартованих у боях вояків, що проходять через Гори Кам'яного Кігтя, Дарн відсилає здібних новобранців до сторожової вежі в північних Пустках — допомогти в тривалих походах."},{t="Варта Кадрака",b="Орк Кадрак стоїть просто на північному порозі, де посушлива савана зустрічається із зеленим пологом Ашенвалю, і керує пересуванням військ Орди на спірну землю. Орда завзято закріплюється тут, утримуючи застави і на західному Зорамському Узмор'ї, і на півночі — Заставу Розщепленого Дерева. Кадрак — життєво важливий вузол, через який узгоджують постачання, війська й нагальні донесення вздовж цих обложених лісових рубежів."}},faq={{q="Хто посилає до Кадрака з Кам'яного Кігтя?",a="Дарн Талонґріп, орк із застави Орди Малака'джин у Горах Кам'яного Кігтя, дає це доручення вправним шукачам пригод, що прямують до лісового кордону.",al={"видавець доповіді кадраку","хто починає доповідь кадраку кам'яний кіготь","завдання дарна талонґріпа"}},{q="Де знайти Кадрака?",a="Кадрак стоїть на північній сторожовій вежі в Пустках і стереже головну дорогу, що веде на північ, в Ашенваль.",al={"місце кадрака","де кадрак","знайти кадрака"}},{q="Чому Орда набирає воїнів для Ашенвалю?",a="Орді потрібна деревина, щоб утримувати Оргріммар, і вона збудувала укріплені позиції, як-от на Зорамському Узмор'ї та на Заставі Розщепленого Дерева. Ці зусилля наражаються на запеклий опір корінних нічних ельфів, тож командирам постійно потрібне підкріплення, щоб утримати територію.",al={"чому орда набирає в ашенваль","похід орди в ашенваль","чому битися в ашенвалі"}},{q="Що буде після доповіді Кадракові?",a="Кадрак розповість вам про стратегічну ситуацію в Ашенвалі й доручить доставляти та збирати військові донесення по спірних заставах лісу — у завданні «Донесення Бойової Пісні».",al={"що далі після кадрака","донесення бойової пісні","продовження доповіді кадраку"}},{q="Чим це завдання відрізняється від версії з Пусток?",a="Обидва — завдання-дороговкази до Кадрака на кордоні Ашенвалю. Одне дають у Пустках (на Перехресті), а це — у Горах Кам'яного Кігтя; виконавши будь-яке з них, ви потрапите в сюжет Ашенвалю.",al={"пустки проти кам'яного кігтя кадрак","два завдання доповідь кадраку","дубль завдання кадрака"}},{q="Що таке Зорамське Узмор'я, про яке йдеться в донесенні?",a="Зорамське Узмор'я — прибережна місцевість на північному заході Ашенвалю, на березі Прихованого Моря. Орда збудувала там укріплену заставу на пляжі, щоб підтримувати тактичні переміщення й забезпечити доступ до моря.",al={"що таке зорамське узмор'я","застава зорамського узмор'я","пляжна база ашенвалю"}}},fp="16,398,28.440.0,14.447.0,40.174.0,24.128.0,51.274.0,39.186.0,49.221.0,51.197.0"}
P.entries["quest:6543"] = {n="Донесення Бойової Пісні",s="Це доручення дає Кадрак на прикордонній сторожовій вежі між північними Пустками й Ашенвалем: гінці мають узгодити польову розвідку по всьому спірному лісу. Шукачі пригод доставляють постійні накази й збирають розвіддані з передової від вершників, що стоять поблизу Азшари, на Заставі Розщепленого Дерева й на Зорамському Березі.",h="Це доручення дає Кадрак на прикордонній сторожовій вежі між північними Пустками й Ашенвалем: гінці мають...",kw={"донесення бойової пісні","кадрак","ашенваль","застава розщепленого дерева","застава зорам'гар","азшара"},ang={["class:Hunter"]="Пересування підступними дорогами Ашенвалю перевіряє вміння орієнтуватися й виживати в полі — і серед диких хижаків, і під прицілом прихованих ельфійських лучників.",["faction:Horde"]="Доставка цих донесень — один із перших справжніх кроків молодого воїна Орди в територіальній боротьбі з нічними ельфами на півночі Калімдору.",["race:Orc"]="Для орків підтримка клану Бойової Пісні — справа кланової честі й практична потреба: так деревина й далі надходить на будівництво Оргріммара."},sec={{t="Постачання рубежу",b="Стоячи на укріпленій сторожовій вежі на північному краю Пусток, Кадрак наглядає за рухом вузьким гірським каньйоном, що веде в Ашенваль. Для Орди вільний прохід через цей перевал — справа першорядна: посушливі степи не дадуть Оргріммару тих величезних запасів деревини, яких він потребує, тож клан Бойової Пісні мусить пробиватися глибоко в прадавні ельфійські ліси. Щоб розкидані передові дозори мали припаси й діяли злагоджено, потрібні надійні гінці, здатні ухилятися від засідок нічних ельфів на підступних лісових стежках Ашенвалю."},{t="Очі по всьому Ашенвалю",b="Доручення пролягає дугою через увесь прадавній ліс. На крайньому заході, на туманному узбережжі Зорамського Берега, гонець Бойової Пісні пильнує наг і прибережні загрози поблизу Застави Зорам'гар. Глибше в суходолі, на Заставі Розщепленого Дерева, розвідник керує обороною від безупинних набігів Вартових. Ще далі на схід, на звивистій дорозі до зруйнованих руїн Азшари, вершник стежить за східними підступами. Зібравши донесення з усіх трьох постів, Кадрак отримує цілісну картину пересувань військ нічних ельфів і слабких місць рубежу."}},faq={{q="Де починається це завдання?",a="Завдання починається з Кадрака, орка-офіцера на дерев'яній сторожовій вежі, що стереже гірський перевал на межі північних Пусток і південного Ашенвалю.",al={"видавець завдання","місце кадрака","хто дає донесення бойової пісні","де почати"}},{q="Чому Орда шпигує в Ашенвалі?",a="Орда значною мірою залежить від густих лісів Ашенвалю, щоб будувати й зміцнювати поселення на кшталт Оргріммара. Корінні нічні ельфи запекло боронять свої священні гаї, тож увесь край перетворився на зону бойових дій, де без постійної розвідки не втримати застав і шляхів постачання.",al={"чому орда шпигує","деревина бойової пісні","конфлікт в ашенвалі"}},{q="Де знайти трьох розвідників Бойової Пісні?",a="Бігун Бойової Пісні стоїть на Заставі Зорам'гар на узбережжі Зорам, далеко на північному заході. Розвідник Бойової Пісні — у гарнізоні Застави Розщепленого Дерева біля головної дороги. Передовий Вершник Бойової Пісні патрулює східну дорогу, що веде до кордону з Азшарою.",al={"місця розвідників","де розвідники","місце передового розвідника"}},{q="Хто такі передові вершники Бойової Пісні?",a="Передові вершники Бойової Пісні — розвідники й рейдери орківського клану Бойової Пісні. Славетні своєю лютою кіннотою й тактикою сутичок, вони очолюють поширення Орди, лісозаготівлі й оборону територій у лісах Ашенвалю.",al={"клан бойової пісні","хто передові вершники","клан бойової пісні в ашенвалі"}},{q="Що буде, коли повернути донесення?",a="Отримавши зібрані відомості, Кадрак використовує їх, щоб спланувати пересування загонів, посилити вразливі застави на кшталт Зорам'гару й Розщепленого Дерева і глибше закріпити Орду в лісі.",al={"здати донесення","наступний хід","що робить кадрак"}},{q="Чи безпечна дорога через Ашенваль для недосвідчених гінців?",a="Ні. На головному шляху через Ашенваль часто влаштовують засідки потайливі Вартові нічних ельфів, нападають ворожі звірі — скрадачі й ведмеді, — а також патрулі Альянсу з поселень на кшталт Астранаару.",al={"небезпека ашенвалю","чи безпечна дорога","засідки нічних ельфів"}}},fp="19,333,18.542.0,21.568.0,30.175.0,37.290.0,44.255.0,30.242.0,41.226.0,58.210.0"}
P.entries["quest:6544"] = {n="Напад Торека",s="«Напад Торека» — прямий наліт Орди з диких хащів Ашенвалю на сусідній гарнізон нічних ельфів на Заставі Срібнокрилих. Удар, який веде орк-нальотник Торек за наказом із Застави Розщепленого Дерева, має зламати опір місцевих вартових і вбити їхню командувачку, Дуріель Мунфаєр. Це одна з найзухваліших і найкривавіших сутичок у війні за кордони Ашенвалю.",h="«Напад Торека» — прямий наліт Орди з диких хащів Ашенвалю на сусідній гарнізон нічних ельфів на Заставі...",kw={"напад торека","торек","застава срібнокрилих","дуріель мунфаєр","ертоґ рейджтаск","завдання"},ang={["class:Warrior"]="Жорстокий лобовий ближній бій, що випробовує чисту тілесну витривалість проти досвідчених лучниць-вартових і майстрів клинка.",["faction:Alliance"]="Загибель Дуріель Мунфаєр оголює Заставу Срібнокрилих і ставить під загрозу родові лісові володіння нічних ельфів.",["faction:Horde"]="Для Орди прорватися повз Заставу Срібнокрилих — важливе випробування сили, що послаблює облогу нічних ельфів довкола Застави Розщепленого Дерева.",["race:NightElf"]="Наліт б'є в саме серце передового командування вартових і проливає ельфійську кров під гіллям Ашенвалю."},sec={{t="Удар із тіні",b="Ашенваль охоплений дедалі запеклішою прикордонною війною між лісозаготівельними таборами Орди й місцевими нічними ельфами. Прагнучи прорвати оборонний периметр Альянсу, Торек збирає загін нальотників із Розщепленого Дерева біля самої Застави Срібнокрилих. Не чекаючи контрнаступу, Торек готує лобову атаку, щоб розтрощити оборону застави, перш ніж нічні ельфи встигнуть розгорнути посилений похід на Заставу Розщепленого Дерева."},{t="Захоплення Срібнокрилих",b="Застава Срібнокрилих — укріплений лісовий бастіон, де стоять пильні Вартові Срібнокрилих і люті ельфійські воїни. Головна мета Торека — їхня очільниця, Дуріель Мунфаєр. Убивши Дуріель, нальотники обезголовлять місцеву військову ієрархію нічних ельфів і зможуть доповісти про криваву перемогу командирові Ертоґу Рейджтаску біля Річки Фалфаррен."}},faq={{q="Хто такий Торек?",a="Торек — запальний орк-рейдер із Застави Розщепленого Дерева в Ашенвалі. Лютий і спраглий бою, він очолює загін рейдерів, яким доручено нести війну просто до сил нічних ельфів, що окопалися в лісі.",al={"торек","хто такий торек","орк торек"}},{q="Що таке Застава Срібнокрилих?",a="Застава Срібнокрилих — укріплене поселення нічних ельфів в Ашенвалі. Його стережуть добірні Вартові й воїни, і воно слугує військовим оплотом, звідки стежать за пересуваннями загонів Орди лісовими стежками.",al={"застава срібнокрилих","що таке срібнокрилі"}},{q="Хто така Дуріель Мунфаєр?",a="Дуріель Мунфаєр — командувачка нічних ельфів, що обороняє Заставу Срібнокрилих. Як очільниця гарнізону, вона спрямовує місцевих Вартових проти вторгнень Орди — аж доки рейдери Торека не прориваються до табору, щоб її вбити.",al={"дуріель мунфаєр","дуріель"}},{q="Хто такий Ертоґ Рейджтаск?",a="Ертоґ Рейджтаск — офіцер Орди на Заставі Розщепленого Дерева. Він командир Торека, наглядає за військовими діями в краї й приймає звістки про перемоги над Альянсом.",al={"ертоґ рейджтаск","ертоґ"}},{q="Чому Орда нападає на Заставу Срібнокрилих?",a="Орда й нічні ельфи ведуть запеклу війну за територію по всьому Ашенвалю. Удар по Заставі Срібнокрилих знімає тиск зі шляхів постачання Орди й безпосередньо послаблює мережу оборони Вартових, що стереже глибину лісу.",al={"чому нападати на срібнокрилих","конфлікт ашенвалю зі срібнокрилими"}},{q="Де відбувається цей напад?",a="Наступ починається просто під Заставою Срібнокрилих, на захід від Річки Фалфаррен в Ашенвалі, а завершується всередині самого табору нічних ельфів.",al={"місце нападу торека","де торек"}}},fp="15,390,25.430.0,17.377.0,13.236.0,27.204.0,23.224.1,22.206.0,45.234.0,34.153.0"}
P.entries["quest:6545"] = {n="Оновлене Донесення Гінця Бойової Пісні",s="«Оновлене донесення гінця Бойової Пісні» — завдання Орди зі зв'язку, що поєднує передову оборону Ашенвалю з командирами на кордоні. Донесення, довірене гінцям і новобранцям, описує дедалі більший військовий тиск на розвідників Бойової Пісні, передусім агресію наг, що наступають.",h="«Оновлене донесення гінця Бойової Пісні» — завдання Орди зі зв'язку, що поєднує передову оборону Ашенвалю з...",kw={"донесення гінця","бойова пісня","кадрак","вал мор'шан","наги","завдання"},ang={["faction:Horde"]="На лісовому прикордонні важить кожен воїн, і зв'язок між Пустками й передовими заставами — питання виживання.",["race:Orc"]="Клан Бойової Пісні покладається на завзяття й пильність своїх гінців, щоб утримати землі, здобуті за наказом Вождя Тралла."},sec={{t="Донесення з передової",b="Клан Бойової Пісні тримає по всьому Ашенвалю мережу розвідників і гінців, щоб стежити за довколишніми ворогами й берегти шляхи постачання. Між прикордонними сутичками з вартовими нічних ельфів і суворою природою швидка розвідка — понад усе. Гінці з донесеннями з передової дбають, щоб віддалені гарнізони діяли злагоджено з такими командирами, як Кадрак на Валу Мор'шан."},{t="Загроза наг",b="Орда чекає запеклого опору від нічних ельфів серед дерев, але вартові застав доповідають про дедалі зухваліші напади наг. Ці зміїні загарбники б'ють із водних шляхів і прадавніх руїн, випробовуючи барикади застав і змушуючи захисників відволікатися від лісозаготівель і прикордонних дозорів. Донесення, принесене назад на Вал Мор'шан, б'є на сполох через ці злагоджені напади з води."}},faq={{q="Кому надсилають це донесення?",a="Донесення несуть просто Кадракові, наглядачеві на Валу Мор'шан, на межі Ашенвалю й північних Пусток.",al={"хто отримує донесення","звіт кадрака","куди йде донесення"}},{q="Які загрози згадано в донесенні?",a="Розвідник повідомляє, що застава вистояла під кількома нападами, і наголошує на дедалі більшій загрозі від ворожих наг у сусідніх водах.",al={"що в донесенні","зміст доповіді гінця","напади наг"}},{q="Чому Орда покладається тут на пішохідних гінців?",a="Густе листя, пильні стрільці нічних ельфів і відрізані застави роблять перельоти над частиною Ашенвалю важкими чи надто відкритими. Пішохідні гінці забезпечують швидкий і непомітний зв'язок захищеними стежками.",al={"чому гінці","переказ про гінців бойової пісні","чому не вівернами"}},{q="Хто такі гінці Бойової Пісні?",a="Це розвідники, кур'єри й передові бійці клану Бойової Пісні, яким доручено берегти шляхи постачання й стежити за ворогом на спірних межах лісу.",al={"клан бойової пісні в ашенвалі","хто гінці бойової пісні"}},{q="Де в Ашенвалі нападають наги?",a="Наги влаштували твердині в руїнах уздовж берегів і озер Ашенвалю й часто влаштовують засідки на мандрівників і набіги на сусідні табори.",al={"де наги","наги ашенвалю"}},{q="Яке призначення застави в цих місцях?",a="Застава слугує постом раннього попередження й оборонною опорою: вона не дає ворогам перерізати зв'язок між лісозаготівлями в глибині лісу й Пустками.",al={"чому тут застава","призначення табору орди"}}},fp="21,288,20.419.0,15.446.0,32.153.0,41.157.0,45.206.0,31.170.0,42.139.0,43.172.0"}
P.entries["quest:6546"] = {n="Оновлене Донесення Вершника Бойової Пісні",s="«Оновлене донесення вершника Бойової Пісні» — завдання Орди на доставку, що починається на небезпечних стежках східного Ашенвалю. Самотній розвідник Бойової Пісні довіряє шукачеві пригод важливі відомості про загрози з боку Альянсу поблизу, сатирів, що окопалися в лісі, і наг, що наступають у сусідній Азшарі.",h="«Оновлене донесення вершника Бойової Пісні» — завдання Орди на доставку, що починається на небезпечних...",kw={"донесення вершника","дозорці пісні війни","азшара","наги","сатири","завдання"},ang={["faction:Horde"]="Кожне донесення, що проходить уздовж рубежу Мор'шан, зміцнює хитку опору Орди в буйних лісах Ашенвалю.",["race:Orc"]="Клан Бойової Пісні пишається тим, що стоїть в авангарді, але його розвідники знають: сама відвага не зупинить ворогів, що оточують їх з усіх боків."},sec={{t="Очі на узліссі",b="Східний Ашенваль — спірне прикордоння, де шляхи постачання Орди повсякчас зазнають нападів. Дозорці Пісні Війни тримають пильну завісу по всіх лісах, розвідуючи пересування ворога задовго до того, як нальотники встигнуть ударити по таких заставах, як Вал Мор'шан чи Застава Розщепленого Дерева. Зустріти передового вершника в дозорі — означає опинитися просто на театрі розвідувальних дій, де відомості можуть вирішити, чи втримається укріплення, чи впаде від засідки."},{t="Загрози з усіх обріїв",b="Звіт, складений вершником, малює для Орди похмуру тактичну картину в центральних лісах Калімдору. Окрім повсякчасних сутичок із нічними ельфами та ширшим Альянсом, у східному Ашенвалі кишать хитрі демонічні сатири. На додачу розвідники виявили величезну присутність наг, що розповзаються зруйнованими прибережними землями сусідньої Азшари, і попереджають командирів: Орду майже з усіх боків оточують ворожі сили."}},faq={{q="Що таке Донесення Клану Бойової Пісні?",a="Це розвідувальне донесення, яке написав Передовий Вершник Бойової Пісні, з підсумком розташування ворожих загонів і небезпек краю. У ньому йдеться про загрози від сил Альянсу поблизу, діяльні ковени сатирів на сході Ашенвалю й нещодавно помічені пересування наг в Азшарі.",al={"донесення бойової пісні","що в донесенні","звіт розвідника"}},{q="Хто такий Кадрак?",a="Кадрак — командир Орди на Валу Мор'шан, укріпленій загороді, що стереже північний кордон між Пустками й Ашенвалем. Він приймає розвідників і керує передовими діями в лісі.",al={"хто такий кадрак","де кадрак","здати кадраку"}},{q="Чому згадано наг в Азшарі?",a="Азшара межує безпосередньо зі східним Ашенвалем. Передові вершники стежать за чужими пересуваннями на сусідніх землях, щоб великі вторгнення не заскочили фланги Орди, поки вона воює з нічними ельфами.",al={"зв'язок наг з азшарою","чому згадано азшару","загроза наг азшари"}},{q="Чому схід Ашенвалю такий небезпечний для Орди?",a="Край затиснутий між діяльними загонами Альянсу, прадавніми руїнами сатирів, просякнутими демонічною скверною, і дикими лісовими звірами, тож гінці й патрулі Орди вразливі до засідок з усіх боків.",al={"чому схід ашенвалю небезпечний","загрози ашенвалю","загроза сатирів"}},{q="Хто такі Дозорці Пісні Війни?",a="Дозорці Пісні Війни, або передові вершники, — це передовий загін і розвідувальна кіннота клану Бойової Пісні в Ашенвалі: вони стежать за пересуваннями нічних ельфів, прикривають лісозаготівельні табори й бережуть торгові шляхи.",al={"що таке передові вершники","розвідники бойової пісні","переказ про передових"}},{q="Чому вершник не може доставити донесення сам?",a="Вершникові доручено й далі стежити за стежкою, щоб бачити, як розвиваються ворожі пересування. Якщо він покине свій спостережний пункт, передова осліпне перед несподіваним наступом Альянсу чи сатирів.",al={"чому я доставляю донесення","чому не доставить сам"}}},fp="23,283,26.482.0,24.477.0,27.264.0,14.230.0,38.209.0,56.218.0,30.187.0,50.208.0"}
P.entries["quest:6547"] = {n="Оновлене Донесення Розвідника Бойової Пісні",s="«Оновлене донесення розвідника Бойової Пісні» — завдання Орди зі зв'язку, що поєднує командирів застав на кордонах Ашенвалю з передовими розвідниками, які стежать за спірним лісом. Несучи стратегічні накази Кадрака, гінці дбають, щоб клан Бойової Пісні пильно стежив за нічними ельфами, які влаштовують засідки. Завдання показує, як хитко й ворожо Орда тримається на щойно здобутих землях.",h="«Оновлене донесення розвідника Бойової Пісні» — завдання Орди зі зв'язку, що поєднує командирів застав на...",kw={"донесення розвідника","бойова пісня","кадрак","ашенваль","прикордоння","завдання"},ang={["faction:Horde"]="Кожен гонець, що несе накази між Кадраком і віддаленими розвідниками, допомагає вберегти опору Орди в Ашенвалі від невпинних засідок нічних ельфів.",["race:NightElf"]="Розвідники Бойової Пісні, що причаїлися на кордонах, — це тривале осквернення священних лісів Елуни, яке вартові прагнуть викорінити.",["race:Orc"]="Спадщину клану Бойової Пісні визначає його завзяття в Ашенвалі: він здобуває життєво потрібну деревину, попри ворожість землі та її прадавніх захисників."},sec={{t="Очі в тіні",b="Прикордоння Ашенвалю лишається пороховою бочкою, де жодна сторона не поступається й на крок. Сили Орди під проводом Кадрака дуже покладаються на розпорошених розвідників Бойової Пісні на небезпечних заставах: ті стежать за пересуваннями нічних ельфів і бережуть спірні шляхи постачання. Сам ліс дає природне укриття потайним вартовим Альянсу, тож регулярні звіти й письмові донесення вкрай важливі, щоб відокремлених розвідників не відрізали й не розгромили."},{t="Утримати землю",b="Для клану Бойової Пісні кожен клапоть вирубаного чи зайнятого лісу оплачено кров'ю. Розвідники невпинно стежать за відплатними набігами нічних ельфів, що прагнуть повернути ліси. Накази Кадрака запевняють авангард, що підкріплення й злагоджені дії не припиняються, і розвідники можуть доповісти, що їхні оборонні заходи діють, попри безупинний опір ельфів."}},faq={{q="Хто такий Кадрак?",a="Кадрак — командир Орди на межі Пусток і Ашенвалю. Він керує розвідувальними місіями, обороною кордону й постачанням для клану Бойової Пісні, що просувається в прадавній ліс.",al={"кадрак","хто такий кадрак","роль кадрака"}},{q="Чому розвідники Бойової Пісні так остерігаються нічних ельфів?",a="Нічні ельфи легко зливаються з тінями лісів своїх предків і раптово нападають на патрулі Орди із засідки. Клан Бойової Пісні рубає ліс і заселяє землю, яку ельфи вважають священною, тож розвідникам постійно загрожують смертельні несподівані атаки.",al={"чому боятися нічних ельфів","нічні ельфи в тінях","небезпека ельфів для розвідника"}},{q="Чому за Ашенваль точиться боротьба?",a="Орді потрібні деревина й ресурси Ашенвалю, щоб будувати Оргріммар і забезпечувати поселення в посушливих Пустках і Дуротарі. Корінні нічні ельфи вважають ліс священною землею й завзято воюють, щоб вигнати орківських лісорубів і гарнізони.",al={"чому воюють за ашенваль","війна за ашенваль","конфлікт орди в ашенвалі"}},{q="Яка роль клану Бойової Пісні тут?",a="Клан Бойової Пісні очолює поширення Орди й добування ресурсів в Ашенвалі. Ще під час Третьої війни його привів у ліси Ґром Хеллскрім, і відтоді клан міцно тут закорінився: тримає лісозаготівельні табори й безперестанку б'ється з Вартовими.",al={"клан бойової пісні в ашенвалі","роль бойової пісні"}},{q="Куди йде це донесення, коли дістанеться розвідника?",a="Отримавши оновлені вказівки Кадрака, розвідник надсилає назад звістку про свої успіхи у відбитті ельфійських контратак, щоб провід Орди добре знав, наскільки стійка передова.",al={"хто отримує донесення","звіт кадрака","результат донесення розвідника"}},{q="Чи вдаються плани Орди в Ашенвалі на цей момент?",a="Розвідники на передовій вважають свою оборону успішною: вони втримують укріплені позиції й відбивають удари ельфів, але край і далі лишається запеклим полем бою, де жодна сторона не має цілковитої переваги.",al={"чи орда перемагає в ашенвалі","поступ бойової пісні"}}},fp="20,404,19.450.0,18.405.0,14.224.0,57.279.0,35.261.0,37.283.0,51.212.0,60.242.0"}
P.entries["quest:6548"] = {n="Помсти за моє селище",s="Макаба Флетгуф ледве вижив у жорстокому нападі, коли розбійники з клану Ґрімтотем налетіли на його селище на південному сході Гір Кам'яного Кігтя. Відрізаний від родичів, серед загиблих, він просить мандрівників з Орди завдати удару у відповідь по табору головорізів-Ґрімтотемів і їхніх найманців і помститися за полеглий народ.",h="Макаба Флетгуф ледве вижив у жорстокому нападі, коли розбійники з клану Ґрімтотем налетіли на його селище на...",kw={"помсти за моє селище","макаба флетгуф","ґрімтотем","кайрн бладгуф","помста","гори кам'яного кігтя"},ang={["faction:Horde"]="Орда покладається на відкриті й безпечні перевали між Пустками та Горами Кам'яного Кігтя. Свавільна банда Ґрімтотемів, що вбиває мандрівників і нападає на союзні селища, загрожує шляхам постачання Вождя через гори.",["race:Tauren"]="Зрада клану Ґрімтотем найболючіше вдаряє по мандрівниках-тауренах. Бачити, як шу'гало вирізають свої ж, — гірке нагадування про розкол між кланами й про небезпеку, яку Ґрімтотеми становлять для об'єднаного народу Кайрна."},sec={{t="Кров серед круч",b="Неподалік кордону між Пустками й червонокам'яними перевалами Гір Кам'яного Кігтя стоїть Макаба Флетгуф — єдиний, хто вцілів у жорстокій різанині. Розбійники під темними стягами клану Ґрімтотем налетіли без попередження й вирізали майже всіх у селищі. Хоч Макаба люто оборонявся й поклав кількох нападників, зрештою йому довелося сховатися, не маючи нічого, крім власного життя й люті."},{t="Загроза Ґрімтотемів",b="Ґрімтотеми здавна були непокірною, агресивною скалкою в оці племен тауренів, об'єднаних під проводом Верховного Вождя Кайрна Бладгуфа. На відміну від мирних кочівників, що мандрують Малгором, бойові загони Ґрімтотемів часто наймають безжальних головорізів і найманців, ладних на все, щоб загарбувати землі й нападати на відрізані поселення. Для Макаби тепер нічого не важать ні переговори, ні кревна спорідненість племен: лише кров за кров може вгамувати його горе."}},faq={{q="Хто дав це завдання?",a="Його дає Макаба Флетгуф, таурен, що вцілів і отаборився біля південно-східного перевалу в Гори Кам'яного Кігтя. Він пережив жорстокий розгром свого селища кланом Ґрімтотем і прагне відплати нападникам.",al={"хто дає завдання","макаба флетгуф","хто такий макаба"}},{q="Чому Ґрімтотем нападають на інших тауренів?",a="Клан Ґрімтотем так і не прийняв по-справжньому єдності Орди чи мирного задуму Кайрна Бладгуфа. Затято ревниві до своєї землі, ворожі до чужинців і агресивні, вони відкрито грабують суперницькі поселення, вбивають сторонніх і за допомогою озброєних головорізів і найманців прагнуть панувати над краями на кшталт Кам'яного Кігтя.",al={"чому ґрімтотеми ворожі","таурени нападають на тауренів","переказ про клан ґрімтотем"}},{q="Де нападники Ґрімтотем?",a="Головорізи й найманці Ґрімтотем стоять табором трохи на захід від Макаби Флетгуфа на південному сході Кам'яного Кігтя, серед кам'янистих пагорбів над перевалом.",al={"де мисливці ґрімтотем","табір ґрімтотем","де знайти розбишак"}},{q="Хто такі найманці Ґрімтотем?",a="Клан Ґрімтотем часто доповнює власних воїнів найманими безжальними бійцями й продажними мечами, щоб мати досить сили тероризувати й захоплювати відокремлені поселення.",al={"найманці","найманці ґрімтотем","хто такі найманці"}},{q="Що буде після цього завдання?",a="Коли ви поріжете передових головорізів і найманців, Макаба попросить вас ударити по ватажкові різанини, Ґрундіґу Дарклауду, у наступному завданні «Убий Ґрундіґа Дарклауда».",al={"наступне завдання","що після помсти за селище","убити ґрундіґа дарклауда"}},{q="Де було селище Макаби?",a="Селище Макаби — відокремлений табір тауренів біля прикордонних перевалів на південному сході Кам'яного Кігтя. Набіг Ґрімтотем знищив його вщент, і Макаба — один із небагатьох відомих, хто вцілів.",al={"селище флетгуфа","де було селище","яке селище знищили"}}},fp="17,328,18.429.0,20.448.0,20.222.0,45.297.0,42.185.0,34.212.0,30.187.1,35.214.0"}
P.entries["quest:6561"] = {n="Лиходійство в Блекфатомі",s="«Лиходійство в Блекфатомі» — відчайдушне благання смертельно пораненого вояка Срібного Світанку, що опинився в пастці всередині Чорноглибинних Печер. Шукачі пригод Орди мають покінчити із сутінковим володарем Келрісом — ватажком культу, який влаштовує моторошні криваві жертвоприношення давньому чудовиську в руїнах унизу.",h="«Лиходійство в Блекфатомі» — відчайдушне благання смертельно пораненого вояка Срібного Світанку, що опинився...",kw={"келріс","молот присмерку","чорноглибинні печери","аку'май","срібний світанок","башана рунототем","таелрід"},ang={["class:Druid"]="Осквернення давнього місячного колодязя нічних ельфів культистами-поклонниками Порожнечі та нагами — болісна рана на тілі природного й духовного прихистку Калімдору.",["class:Shaman"]="Неспокій, який посіяли Келріс та Аку'май, ображає рівновагу стихій: чисті підземні води обертаються на гниле ложе тіні й жертвоприношень.",["faction:Horde"]="Для Орди така угода з розвідником Срібного Світанку — рідкісний випадок спільного інтересу перед лицем космічної пошесті, що приносить ранню прихильність Світанку.",["race:Tauren"]="Башана Рунтотем бачить у поразці Келріса важливий захист Земної Матері: світ очищено від мерзоти, що хотіла кинути природний лад у первісний хаос."},sec={{t="Останній відчайдушний опір",b="Розвідник Срібного Світанку Таелрід дістався підземного храму на узбережжі Ашенвалю й натрапив на жахіття, куди страшніші за звичайні набіги наг. Поранений і знесилений у печерах, нічний ельф розуміє, що сам місії не завершить. Щоб його розвідка не загинула разом із ним, він звертається до кожного звитяжця Орди, який наважиться вдарити по темних проводирях, що панують у затоплених залах."},{t="Жертви для глибин",b="Мета завдання — сутінковий володар Келріс, очільник культистів Молота Присмерку, які окопалися в зруйнованому Храмі Місяця. У союзі з місцевими нагами Келріс править темні обряди над оскверненим місячним колодязем і згодовує живих полонених Аку'маю — ненажерній гідрі, звірові Древніх Богів, — у божевільній гонитві за космічною силою та первісним хаосом."},{t="Звістка до Тандер Блафа",b="Срібний Світанок свого часу вважав Келріса загиблим або зниклим, тож підтвердити його смерть украй важливо. Замість того щоб гнати героїв аж до людських земель, Таелрід велить віднести доказ загибелі ватажка культу Башані Рунтотем на Узвишшя Старійшин у Тандер Блафі. Башана, глибоко пов'язана з природною рівновагою Земної Матері, шанує цю перемогу: вона загасила мерзенну порчу, що прагнула втягнути Калімдор у первісну руїну."}},faq={{q="Хто такий сутінковий володар Келріс?",a="Келріс — ватажок сектантів Молота Присмерку, що захопили Чорноглибинні Печери. Срібний світанок вважав його мертвим чи зниклим, а він тим часом потай набирався сили, приносячи живі жертви прадавній гідрі Аку'май в оскверненому місячному колодязі.",al={"келріс","хто такий келріс","сутінковий володар келріс"}},{q="Що член Срібного світанку робить у Чорноглибинних Печерах?",a="Срібний Вартовий Таелрід прийшов дослідити загрозу, що зростала в зруйнованому храмі нічних ельфів. Здоланий мешканцями печер і смертельно ослаблений, він застряг там і мусить покладатися на шукачів пригод, щоб ті виконали його обов'язок і знищили Келріса.",al={"страж срібного світанку телріт","чому телріт тут","срібний світанок у чорноглибинних печерах"}},{q="Що таке Аку'май?",a="Аку'май — жахлива прадавня багатоголова гідра, яку вважають первісним слугою Древніх Богів. Вона спала під затонулими руїнами й прокинулася, коли глибинна підземна скверна отруїла священні води храму, а тепер пожирає полонених, яких їй приводить Молот Присмерку.",al={"аку'май","хто такий аку'май","переказ про аку'мая"}},{q="Чому завдання треба здати Башані Рунтотем?",a="Таелрід скеровує поборників Орди до Башани Рунтотем на Узвишші Старійшин у Тандер Блафі. Башана, охоронниця рівноваги Земної Матері, підтримує зв'язок із тими, хто протистоїть прадавньому злу, і вважає поклоніння Келріса Древнім Богам огидною пошестю для Калімдору.",al={"башана рунтотем","чому тандер блаф","де здати лиходійство в блекфатомі"}},{q="Що сталося з руїнами Чорноглибинних Печер?",a="Колись давно цей підземний комплекс був священним храмом місячної богині Елуни. Катастрофічні потрясіння й прадавня темрява, що просочилася з надр, осквернили величний місячний колодязь, і затонулі святилища захопили наги й сектанти кінця світу для свого темного володаря Аку'май.",al={"історія чорноглибинних печер","руїни храму елуни","чому печери осквернені"}},{q="Чого прагне тут культ Молота Присмерку?",a="Молот Присмерку прагне, поклоняючись Древнім Богам, повернути світ у добу первісного хаосу. Келріс шукає особистої влади через темне єднання й кидає невинних у глибини, щоб здобути прихильність прадавніх сутностей.",al={"мотиви молота присмерку","чому культ у печерах","цілі келріса"}}},fp="20,291,22.427.0,22.381.0,21.422.1,28.273.0,54.252.0,16.279.0,43.278.0,48.281.0,52.231.0"}
P.entries["quest:6562"] = {n="Клопоти в Глибинах",s="«Клопоти в Глибинах» — заклик про допомогу, що летить із Гір Кам'яного Кігтя до далеких берегів Ашенвалю. Цунаман посилає шукачів пригод Орди до троля-вченого Дже'ню Санкреа на Заставу Зорам'гар і попереджає, що узбережжям блукають небезпечні сили.",h="«Клопоти в Глибинах» — заклик про допомогу, що летить із Гір Кам'яного Кігтя до далеких берегів Ашенвалю.",kw={"дже'ню санкреа","цунаман","застава зорам'гар","зорамське узмор'я","чорноглибинні печери","ашенваль"},ang={["class:Shaman"]="Неспокій під хвилями Зорамського Узмор'я загрожує рівновазі місцевих духів води, тож очистити цю гнилизну зможе лише той, хто має духовне прозріння.",["faction:Horde"]="Утримати Заставу Зорам'гар украй важливо, щоб захистити західний фланг Калімдору і від сил нічних ельфів, і від жахіть узбережжя.",["race:Troll"]="Відгукнувшись на поклик Дже'ню Санкреа, родичі з племені Темного Списа дістають чудову нагоду допомогти одному з найкращих своїх учених розкрити давні таємниці Калімдору."},sec={{t="Поклик до узбережжя",b="Серед посушливих скель Гір Кам'яного Кігтя Цунаман розуміє: темний гул на півночі вимагає уваги. Він доручає вправним мандрівникам Орди перейти до Ашенвалю — прадавнього лісу нічних ельфів — і зв'язатися з Дже'ню Санкреа. Той стоїть на Заставі Зорам'гар на далекому західному краю, відомому як Зорамське Узмор'я, і зіткнувся з дедалі грізнішою небезпекою, з якою без сторонньої допомоги не впоратися."},{t="Дорога до Зорамського Узмор'я",b="Дістатися західного берега Ашенвалю для мандрівників Орди — аж ніяк не дрібниця. Хоч крізь перевали Кручі Вітрорізу, де хазяйнують гобліни, хоч рушаючи на північ із Пусток — усе одно доведеться заходити у ворожий ліс, який запекло стережуть Вартові нічних ельфів. Далеко за густими кронами, на омитому бурями березі Зорамського Узмор'я, самотня застава чіпляється за життя й вдивляється в темні води неподалік."},{t="Шепіт під хвилями",b="На березі Дже'ню Санкреа відкриває, що корінь лиха — у підземному храмі Чорноглибинних Печер. Під товщею води зібралися давня порча, мерзенні водяні елементалі й культисти Молота Присмерку, які кличуть стародавнє зло назад у світ. Дже'ню покладається на звитяжців, що прибувають на узбережжя: лише вони можуть спуститися під воду й протистати первісному жахові, розбудженому в затоплених залах."}},faq={{q="Хто дає завдання «Клопоти в Глибинах»?",a="Завдання дає Цунаман у Горах Кам'яного Кігтя. Він розуміє, що союзникам на узбережжі Ашенвалю потрібне підкріплення, і скеровує мандрівних шукачів пригод Орди до моря.",al={"хто дає клопоти в глибинах","видавець завдання","цунаман"}},{q="Де знайти Дже'ню Санкреа?",a="Дже'ню Санкреа перебуває на Заставі Зорам'гар на узбережжі Зорам, на далекому західному березі Ашенвалю.",al={"де дже'ню","місце дже'ню санкреа","застава зорам'ґар"}},{q="Як дістатися з Кам'яного Кігтя до Застави Зорам'гар?",a="Можна йти на північний схід через Кручу Вітрорізу в Ашенваль або зробити гак на схід через Пустки й увійти в ліс із півдня. Із центрального Ашенвалю прямуйте точно на захід, доки не вийдете до відкритих вод узбережжя Зорам.",al={"шлях до ашенвалю","як дістатися зорамського узмор'я","дорога з кам'яного кігтя в ашенваль"}},{q="Які клопоти досліджує Дже'ню?",a="Дже'ню Санкреа стежить за сусідніми руїнами Чорноглибинних Печер, де сектанти й зіпсовані водяні істоти будять прадавні жахіття під поверхнею.",al={"що відбувається на зорамському узмор'ї","чому дже'ню потрібна допомога"}},{q="Яке завдання йде після «Клопотів у Глибинах»?",a="Розмова з Дже'ню Санкреа одразу веде до завдання «Сутність Аку'Май», яке відправляє шукачів пригод у Чорноглибинні Печери по сапфірово-синю сутність стихій.",al={"наступне завдання","продовження клопотів у глибинах"}},{q="Чому шлях через Ашенваль вважають небезпечним?",a="Ашенваль — володіння нічних ельфів, які запекло опираються будь-якому вторгненню Орди. Мандрівники в лісі ризикують наткнутися на ворожих вартових і невловимих засідників.",al={"небезпека ашенвалю","загроза нічних ельфів"}}},fp="20,265,22.435.0,24.425.0,24.420.1,41.195.0,32.121.0,51.230.0,37.161.0,40.162.0,57.194.0"}
P.entries["quest:6563"] = {n="Сутність Аку'Май",s="Дже'ню Санкреа на Заставі Зорам'гар помітив, що наги з Чорноглибинних Печер видобувають у підземеллях могутні сапфірові друзи. Стурбований їхніми магічними властивостями та енергією стихії води, шаман доручає шукачам пригод Орди забрати самоцвіти, перш ніж їх обернуть на зло.",h="Дже'ню Санкреа на Заставі Зорам'гар помітив, що наги з Чорноглибинних Печер видобувають у підземеллях могутні...",kw={"сапфіри аку'мая","дже'ню санкреа","наги","застава зорам'гар","духи води","чорноглибинні печери"},ang={["class:Shaman"]="Те, що Дже'ню Санкреа прочитав у кристалах, вказує на неспокійних духів води, ув'язнених у них, — тихе попередження, що під храмом спотворюють сили стихій.",["faction:Horde"]="Опорний пункт Орди на Заставі Зорам'гар у небезпеці; не давши сусідським нагам заволодіти сирою магічною силою, ви допоможете вберегти табір на березі.",["race:Troll"]="Дже'ню Санкреа — уважний містик із племені Темного Списа, який покладається на спілкування з духами та мудрість предків, щоб розібратися в дивних загрозах Калімдору."},sec={{t="Загроза в глибинах",b="На оповитих туманом берегах Зорамського Узмор'я шаман із племені Темного Списа Дже'ню Санкреа наглядає за давніми руїнами калдореїв, які тепер заполонили зловісні сили. Глибоко в затоплених залах Чорноглибинних Печер наги взялися добувати яскраві сапфірові нарости, що проростають на вологих стінах. Відчуваючи, що зміїсті загарбники хочуть приборкати цю мінливу силу, Санкреа прагне перехопити здобич, доки їхні задуми не здійснилися."},{t="Духи води й тайна сила",b="Сапфіри Аку'мая — аж ніяк не звичайні самоцвіти: вони бринять відлунням стихії, і в них тримаються духи води. У руках умілих чаклунів такі провідники можуть живити небезпечні тайні обряди чи посилювати вплив тіньової гідри Аку'мая, чия темна присутність просочує весь підземний храм. Якщо забрати ці друзи, наги втратять безцінний реагент, а узбережжя вбережеться від некерованої магії стихій."}},faq={{q="Хто дає це завдання?",a="Завдання дає Дже'ню Санкреа, шаман-троль Темного Спису із Застави Зорам'гар на узбережжі Зорам у північно-західному Ашенвалі.",al={"хто дає завдання","хто починає сутність аку'май","де дже'ню санкреа"}},{q="Навіщо нагам Сапфіри Аку'Май?",a="Їхній задум поки невідомий, але сапфіри мають потужну енергію стихії води й чисту магічну силу, тож для чаклунства наг це надзвичайно небезпечні реагенти.",al={"навіщо нагам сапфіри","для чого кристали","призначення сапфірів"}},{q="Де знайти скупчення сапфірів?",a="Вони вкривають стіни й дно печер у зовнішніх тунелях і затоплених проходах Чорноглибинних Печер, одразу за зруйнованим підземним входом на узбережжі Зорам.",al={"де знайти сапфіри","місце сапфірів аку'май","появи кристалів"}},{q="Що таке Аку'май?",a="Аку'май — жахлива триголова гідра, що живе глибоко в затоплених руїнах храму. Сектанти Молота Присмерку їй поклоняються, а інші бояться її як улюбленого вихованця Древніх Богів.",al={"хто такий аку'май","що таке аку'май","аку'май"}},{q="Чи треба вбивати когось із ватажків підземелля для цього завдання?",a="Ні. Скупчення сапфірів ростуть на стінах печер у перших затоплених тунелях, ще до зустрічі з головними ватажками Чорноглибинних Печер.",al={"чи потрібна повна група","чи можна сапфіри соло","вимога босів"}},{q="Чи пов'язане це завдання з іншими історіями?",a="Так. Воно йде після «Клопотів у Глибинах» і є частиною розслідування Дже'ню Санкреа про темряву й діяльність сектантів, що загніздилися в Чорноглибинних Печерах.",al={"ланцюжок завдань","попередні завдання","клопоти в глибинах"}}},fp="22,287,22.461.0,30.455.0,21.143.0,46.181.0,38.169.0,16.183.0,52.144.0,47.168.0"}
P.entries["quest:6564"] = {n="Вірність Прадавнім Богам",s="«Вірність Прадавнім Богам» — завдання Орди, що починається з розмоклого послання, знайденого в наг у Чорноглибинних Печерах. Віднісши записку Дже'ню Санкреа на Заставу Зорам'гар, ви розкриваєте зловісну змову з обрядом, що розгортається глибоко в затоплених руїнах Чорноглибинних Печер.",h="«Вірність Прадавнім Богам» — завдання Орди, що починається з розмоклого послання, знайденого в наг у...",kw={"вірність прадавнім богам","древні боги","чорноглибинні печери","аку'май","лорґус джетт","молот присмерку","завдання"},ang={["class:Shaman"]="Підкорення духів водяних елементалів у обрядових кристалах — тяжке збочення природної рівноваги, яке треба негайно виправити.",["faction:Horde"]="Викрита записка Лорґуса Джетта допомагає вберегти Заставу Зорам'гар від Молота Присмерку та його союзників-наг, що загрожують опорі Орди на західному узбережжі Ашенвалю.",["race:Troll"]="Допомагаючи своєму родичеві з Темного Спису Дже'ню Санкреа, ви викриваєте прадавні вселенські сутності, чиє повернення загрожувало б кожному племені Азерота."},sec={{t="Нашкрябана заява",b="Б'ючись із нагами в Чорноглибинних Печерах, розвідники Орди знаходять вологу зім'яту записку, списану гарячковим почерком. Нашкрябаний пергамент містить настанови для жриць наг: їм наказано збирати кристали водяних елементалів. Це зовсім не випадкове мародерство — кристали збирають, щоб живити закликання водних чаклунів-наг, які гуртують стихійні сили заради значно темнішої мети."},{t="Шепіт глибин",b="Знайдені накази розкривають, що наги прагнуть використати стихійну силу кристалів, щоб умилостивити й цілком закликати Аку'мая — жахливу гідру, улюбленицю прадавніх вселенських володарів. Записка зухвало проголошує, що це провістить повернення «найвеличнішої доби» світу — доісторичного панування Древніх Богів. Отримавши пергамент на Заставі Зорам'гар, містик Темного Спису Дже'ню Санкреа впізнає автора цієї змови — сектанта Молота Присмерку Лорґуса Джетта."}},faq={{q="Що таке Волога Записка?",a="Волога Записка — знайдені накази, які написав сектант Молота Присмерку Лорґус Джетт. У них жрицям наг велено збирати кристали, сповнені сили стихій, щоб посилити своїх аквамантів і викликати жахливого слугу Аку'май.",al={"волога записка","що в записці","переказ про записку"}},{q="Хто такий Дже'ню Санкреа?",a="Дже'ню Санкреа — провидець і вчений із тролів Темного Спису на Заставі Зорам'гар в Ашенвалі. Як представник Земляного Кільця, він досліджує розлад стихій і прадавні загрози, що постають із сусідніх руїн Чорноглибинних Печер.",al={"дже'ню санкреа","хто такий дже'ню","видавець застави зорам"}},{q="Хто такий Лорґус Джетт?",a="Лорґус Джетт — шаман-людина з культу Молота Присмерку, що діє в Чорноглибинних Печерах, де сектанти в союзі з нагами. Він наглядає за добуванням кристалів стихій, щоб посилити ритуали наг і знову пробудити темні прадавні жахіття.",al={"лорґус джетт","хто написав записку","ватажок наг зорам"}},{q="Що таке Аку'май?",a="Аку'май — велетенська триголова гідра, що живе в затоплених глибинах Чорноглибинних Печер. Тісно пов'язана з первісною темрявою Древніх Богів, ця істота шанована і культом Молота Присмерку, і нагами Чорноглибинних Печер.",al={"аку'май","хто такий аку'май","переказ про аку'мая"}},{q="Навіщо наги збирають водяні кристали?",a="Духи водяних елементалів, ув'язнені в кристалах, дають чисту силу аквамантам наг. Висмоктуючи цю магію стихій, вони сподіваються задобрити Аку'май і зібрати досить сили, щоб наблизити повернення Древніх Богів.",al={"навіщо наги кристали","стихійні кристали наг","кристали аквамантів"}},{q="Куди веде цей ланцюжок завдань?",a="Доставка записки Дже'ню Санкреа одразу веде до наступного доручення — вистежити й стратити Лорґуса Джетта, щоб зірвати ритуальні задуми культу в Чорноглибинних Печерах.",al={"що після вірності прадавнім богам","вірність прадавнім богам частина 2","наступне завдання"}}},fp="26,282,23.413.0,20.494.1,22.235.0,22.236.0,19.248.0,16.251.0,43.226.0,33.186.1"}
P.entries["quest:6565"] = {n="Вірність Прадавнім Богам",s="«Вірність Прадавнім Богам» — завдання Орди: шукачі пригод мають знищити Лорґуса Джетта в глибинах Чорноглибинних Печер. Його доручає провидець із племені Темного Списа Дже'ню Санкреа на Заставі Зорам'гар, щоб зірвати плани культистів Молота Присмерку, які прагнуть пробудити давні сили руйнування. Убивство Лорґуса — прямий удар по таємній діяльності культу під узбережжям Ашенвалю.",h="«Вірність Прадавнім Богам» — завдання Орди: шукачі пригод мають знищити Лорґуса Джетта в глибинах...",kw={"лорґус джетт","молот присмерку","древні боги","дже'ню санкреа","чорноглибинні печери","застава зорам'гар"},ang={["class:Shaman"]="Молот Присмерку прагне розв'язати лють стихій на служіння хаотичним Древнім Богам, тож викорінити його — першочергова справа для тих, хто разом із Земляним Кільцем присягнув берегти рівновагу стихій.",["faction:Horde"]="Знищивши Лорґуса Джетта, ви убезпечите околиці Застави Зорам'гар і захистите відрізаний табір Орди на узбережжі Ашенвалю від підступних задумів культистів.",["race:Troll"]="Допомагаючи Дже'ню Санкреа, ви вшановуєте мудрість шанованого провидця Темного Списа, який далеко від Островів Відлуння боронить первісних духів Азероту."},sec={{t="Загроза під Зорам'гаром",b="Застава Орди Зорам'гар, що примостилася на березі Ашенвалю, неспокійно стежить за Чорноглибинними Печерами. Затоплений храмовий комплекс став розсадником темного чаклунства: його заполонили наги, спотворені звірі й закутані в плащі фанатики Молота Присмерку. Дже'ню Санкреа, провидець Земляного Кільця, що стоїть на узбережжі, розуміє: культисти не шанують ні природної рівноваги, ні духів землі. Натомість вони присягають служити Древнім Богам — потворним сутностям хаосу, переможеним у прадавні часи, чий лиховісний дотик досі відчутний у забутих куточках Азероту."},{t="Кінець Лорґуса Джетта",b="Дже'ню доручає звитяжцям Орди проникнути в підземні руїни й вистежити Лорґуса Джетта, одного з ключових ватажків культу. Лорґус діє глибоко в кам'яних переходах між залами велетенської черепахи Ґаму-Ри та водяного елементаля Барона Аквеніса. Сам Дже'ню надто кволий, щоб іти в сиру темряву, тож смерть Лорґуса вкрай потрібна, аби обірвати темні обряди, які культист затівав під хвилями Ашенвалю."},{t="Відвернути хаос",b="Зі смертю Лорґуса Джетта нагальну загрозу обрядів для узбережжя стримано, але Дже'ню визнає, що Молот Присмерку далеко не викорінено. Тихе проникнення культу в давні святі місця свідчить про ширшу, підступну небезпеку, яка прагне ні багато ні мало повного повернення Древніх Богів. Для Орди в Зорам'гарі смерть Лорґуса — це дорогоцінний час, виграний у ворога, що ховається в тінях світу."}},faq={{q="Хто такий Лорґус Джетт?",a="Лорґус Джетт — один із чільних ватажків сектантів Молота Присмерку, що осіли в Чорноглибинних Печерах. Він керує обрядами культу, які мають наблизити повернення й панування Древніх Богів.",al={"лорґус джетт","хто такий лорґус","переказ про лорґуса джетта"}},{q="Де в Чорноглибинних Печерах знайти Лорґуса Джетта?",a="Лорґус Джетт патрулює затоплені коридори Чорноглибинних Печер, а саме переходи між залою Ґаму-Ра й вівтарем Барона Аквеніса.",al={"місце лорґуса джетта","де лорґус","знайти лорґуса джетта"}},{q="Хто такий Дже'ню Санкреа?",a="Дже'ню Санкреа — провидець із тролів Темного Спису, пов'язаний із Земляним Кільцем; він стоїть на Заставі Зорам'гар на узбережжі Зорам в Ашенвалі й стежить за розладом стихій і скверною в Чорноглибинних Печерах.",al={"дже'ню санкреа","хто дає вірність прадавнім богам","дже'ню"}},{q="Чому Дже'ню не байдужий Молот Присмерку?",a="Як провидець, що прагне збагнути природу й рівновагу стихій, Дже'ню бачить у Молоті Присмерку загрозу самому існуванню світу. Культ служить Древнім Богам — хаотичним прадавнім сутностям, чиє повернення зруйнувало б гармонію світу.",al={"чому битися з молотом присмерку","земляне кільце прадавні боги"}},{q="Хто такі Древні Боги?",a="Древні Боги — первісні істоти хаосу й руйнування, що панували над Азеротом у далекому минулому, доки їх не здолали й не поховали. Культ Молота Присмерку відкрито їм поклоняється й змовляється зламати їхні печаті та повернути їхнє згубне владарювання.",al={"переказ про прадавніх богів","хто такі прадавні боги","істоти хаосу"}},{q="Чому Дже'ню Санкреа не може сам убити Лорґуса Джетта?",a="Дже'ню визнає, що надто кволий і слабкий, щоб сам-один подолати небезпеки Чорноглибинних Печер, тож покладається на вправних поборників Орди, а сам із застави стежить за збуреннями в царині духів і стихій.",al={"чому дже'ню не йде","чи дже'ню слабкий"}}},fp="26,413,28.592.0,18.482.0,17.443.1,19.195.0,52.170.0,22.217.0,49.232.0,22.254.0,50.224.0"}
P.entries["quest:6571"] = {n="Припаси Бойової Пісні",s="«Припаси Бойової Пісні» — масштабне завдання Орди з постачання, яке дає Лок Окарр на Заставі Розщепленого Дерева. Щоб Лісозаготівельний Табір Бойової Пісні працював, треба повернути важливе лісорубське спорядження, розкидане по ворожих землях фурболгів і сатирів, а також забрати вантажі з далеких гоблінських портів.",h="«Припаси Бойової Пісні» — масштабне завдання Орди з постачання, яке дає Лок Окарр на Заставі Розщепленого...",kw={"припаси бойової пісні","лок окарр","линви","олія","пиляльні леза","сокири","завдання"},ang={["faction:Horde"]="Поширення Орди в Дуротарі цілком залежить від деревини, яку здобуває клан Бойової Пісні. Повертаючи ці знаряддя, ви безпосередньо зміцнюєте підвалини Оргріммара.",["profession:Engineering"]="Гоблінські складники цього вантажу показують, на якому важливому механічному ланцюгу постачання — від пиляльних лез Піксель до мастила для парових двигунів — тримається вирубка прадавніх лісів.",["race:Orc"]="Шанувати спадщину клану Бойової Пісні в Ашенвалі — означає тримати його сокири гострими, а табори забезпеченими, попри безупинні напади лісових мешканців."},sec={{t="Хай пилки крутяться",b="Похід клану Бойової Пісні за прадавньою деревиною Ашенвалю потребує безупинного потоку важких знарядь. Інтенданти Орди на Заставі Розщепленого Дерева повсякчас стикаються з перебоями в постачанні. Лок Окарр відповідає за те, щоб лісозаготівельний табір мав усе потрібне, але місцеві вантажі розсипалися під нападами місцевих звірів і демонічних сектантів, і робота лишилася без найважливішого спорядження."},{t="Розірваний ланцюг постачання",b="Здобути потрібне обладнання — справжнє випробування, що охоплює чималу частину Калімдору й сягає навіть за море. Циркулярні пиляльні леза чекають у гоблінки-кур'єрки Піксель просто на Заставі Розщепленого Дерева, а скриню важких сокир доведеться забрати в Начальника Пристані Лозґіла аж у Буті Бей. Решту необхідного доведеться вирвати просто з рук ворогів: міцні лісорубські линви захопили ворожі фурболги Гнилолісу й Будякохутрі, а бочки машинної олії Бойової Пісні викрали сатири Нічного Потоку, Сатирнаару й Ксавіана, щоб живити свої блюзнірські обряди."}},faq={{q="Які Припаси Бойової Пісні потрібні?",a="Локові Окарру потрібні чотири важливі речі: партія Пиляльних Лез Бойової Пісні, яку тримає в себе гоблінка Піксель, ящик Сокир Бойової Пісні, відправлений до Буті Бею, міцна Линва Лісоруба, яку поцупили місцеві фурболги, і бочки Олії Бойової Пісні, вкрадені сатирами Ашенвалю.",al={"список припасів бойової пісні","які предмети потрібні","потрібні припаси"}},{q="Хто такий Лок Окарр?",a="Лок Окарр — орк із Застави Розщепленого Дерева, що відповідає за доставку матеріалів до Лісозаготівельного Табору Бойової Пісні. Затримки йому не пробачать, тож він наймає мандрівних шукачів пригод Орди, щоб повернути розкидані вантажі.",al={"переказ про лока окарра","хто дає припаси бойової пісні","видавець розщепленого дерева"}},{q="Чому Орда везе спорядження з Буті Бею?",a="Орда покладається на нейтральні торгові мережі на кшталт картелю Стімвідл, щоб завозити спеціальні вироби, яких Дуротар і Пустки не можуть легко кувати у великих кількостях. Важкі лісорубні сокири, замовлені через гоблінські канали, ідуть через морські торгові осередки на кшталт Буті Бею, перш ніж дістатися Ашенвалю.",al={"чому буті бей","відправка сокир з буті бею","інструменти стімвідлів"}},{q="Навіщо сатирам Олія Бойової Пісні?",a="Не для машин: сатири, що населяють руїни на кшталт Сатирнаару, Нічного Потоку й Ксавіана, пускають украдену промислову олію на темні, осквернені обряди на честь Палаючого Легіону й скверни, що розповзається зі Сквернолісся.",al={"переказ про олію сатирів","чому у сатирів олія","ритуали олії бойової пісні"}},{q="Які фурболги вкрали Линву Лісоруба?",a="Линву Лісоруба відбили із засідки й забрали фурболги з племен Гнилолісу й Будякохутрих. Обидва племена запекло ворожі до суцільних вирубок, які Орда веде по всьому Ашенвалю.",al={"хто вкрав линву","переказ про линву фурболгів","линва будякохутрого"}},{q="Чому Лісозаготівельний Табір Бойової Пісні такий важливий для Орди?",a="Посушливі землі Дуротару майже не дають придатної для будівництва деревини. Клан Бойової Пісні відрядили на буйні прикордонні землі Ашенвалю саме для того, щоб рубати величезні дерева, потрібні для будівництва Оргріммара й розбудови військової сили Орди.",al={"чому збирати в ашенвалі","значення лісозаготівлі бойової пісні","орки рубають дерева"}}},fp="16,290,25.415.0,27.573.0,39.246.0,19.252.0,51.303.0,35.229.0,38.197.0,53.269.0"}
P.entries["quest:6581"] = {n="Пиляльні Леза Бойової Пісні",s="«Пиляльні леза Бойової Пісні» — доручення Орди на Заставі Розщепленого Дерева для лісозаготівельної кампанії клану Бойової Пісні. Щоб здобути важкі пиляльні леза, привезені з Раджета, шукачам пригод доведеться укласти неофіційну угоду з кур'єркою Піксель, яка вимагає особистого захисту, перш ніж віддати вантаж. Виконавши її умову, ви забезпечите обладнання, без якого лісопилки Орди в Ашенвалі не гудітимуть.",h="«Пиляльні леза Бойової Пісні» — доручення Орди на Заставі Розщепленого Дерева для лісозаготівельної кампанії...",kw={"пиляльні леза","піксель","смертоносний мушкетон","бойова пісня","раджет","завдання"},ang={["faction:Horde"]="Лісозаготівельні табори в Ашенвалі — опорний хребет розбудови Оргріммара, тож кожна доставка обладнання вкрай важлива для виживання Орди на Калімдорі.",["profession:Engineering"]="Смертоносний Мушкетон, якого вимагає Піксель, — звичний виріб умілих майстрів, і він показує, як гоблінська та інша інженерія рухає постачання на передовій.",["race:Orc"]="Клан Бойової Пісні під проводом Ґроммаша Хеллскріма поставив свою гордість на вирубку Ашенвалю; підтримувати оберти його промислових лез — означає шанувати незламну опору клану в лісі."},sec={{t="Хитрий обмін кур'єрки",b="Лісоруби Бойової Пісні в Ашенвалі цілком залежать від привізних важких машин, щоб прорубуватися крізь прадавню деревину глибокого лісу. Піксель успішно доставила вантаж спеціальних пиляльних лез просто з гоблінського порту Раджет на Заставу Розщепленого Дерева, але не збирається віддавати їх задарма. У небезпечній глушині Ашенвалю монета важить небагато, а особиста безпека — значно більше. Тож замість золота Піксель хоче обміняти важкі пиляльні леза на надійний Смертоносний Мушкетон, щоб убезпечити себе в небезпечних мандрах ворожими землями."},{t="Постачання для війни",b="Густі ліси Ашенвалю дуже цінні для Орди, якій гостро бракує деревини на посушливих рівнинах Дуротару й Пусток. Та вирубка прадавніх гаїв-охоронців швидко тупить звичайні сокири, тож без викуваних гоблінами промислових лез не обійтися. Вантаж Піксель безпосередньо живить роботу лісозаготівельних таборів Бойової Пісні, щоб Орда й далі могла будувати застави й бойові машини, попри запеклий опір нічних ельфів."}},faq={{q="Хто така Піксель і чому в неї пиляльні леза?",a="Піксель — кур'єрка, що зараз перебуває на Заставі Розщепленого Дерева; вона привезла партію промислових пиляльних лез просто з гоблінського порту Раджет. Вона притримує вантаж, доки не роздобуде надійну зброю для власного захисту.",al={"хто така піксель","піксель розщепленого дерева","гінець з пилками"}},{q="Чому Піксель хоче Смертоносний Мушкетон, а не золото?",a="Подорож через Пустки й углиб земель нічних ельфів в Ашенвалі надзвичайно небезпечна. Знаючи, що чатує на дорозі, Піксель ставить власний захист вище за гроші й вимагає вогнепальну зброю роботи інженера, щоб убезпечити свої мандри.",al={"чому мушкетон","торгівля піксель зброєю","чому хоче зброю"}},{q="Чому ці пиляльні леза такі важливі для Орди?",a="Орді потрібні величезні обсяги деревини, щоб будувати укріплення й бойові машини по всьому Калімдору. Звичайні різальні знаряддя швидко тупляться об прадавні залізні дерева Ашенвалю, тож привезені механічні пиляльні леза життєво важливі для лісорубних машин клану Бойової Пісні.",al={"чому леза потрібні","значення лісозаготівлі бойової пісні","чому припаси бойової пісні"}},{q="Звідки взялися пиляльні леза?",a="Пиляльні леза виготовили в Раджеті, нейтральному гоблінському порту на східному узбережжі Пусток, і відправили звідти, а потім суходолом доправили на Заставу Розщепленого Дерева.",al={"походження пиляльних лез","леза раджета","звідки леза"}},{q="Яке місце це завдання посідає в лісозаготівлях Бойової Пісні?",a="Це завдання — частина ширших зусиль зібрати Припаси Бойової Пісні для лісозаготівельних таборів в Ашенвалі. Повернувши пиляльні леза від Піксель, ви виконуєте одну з ключових вимог постачання, без яких лісозаготівлі Орди не втриматися.",al={"ланцюжок припасів бойової пісні","попередник пиляльних лез"}},{q="Чи будь-хто може зробити зброю, яку хоче Піксель?",a="Смертоносний Мушкетон виготовляють вправні інженери з мідних трубок, мідних болтів, дерев'яного ложа й шкіри, хоча кур'єри й воїни часто вимінюють його на місцевих ринках чи в інших шукачів пригод.",al={"як отримати мушкетон","джерело мушкетона","інженерна зброя"}}},fp="18,421,25.614.0,24.461.0,50.244.0,57.244.0,51.275.0,46.173.0,58.237.0,39.210.0"}
P.entries["quest:66"] = {n="Легенда про Сталвана",s="«Легенда про Сталвана» починається в Даркширі з лиховісного видіння міської віщунки Мадам Єви. Стривожена знаменням, що віщує смерть її онуці Аліссі, Єва звертається до карт і видінь у трансі — і дізнається одне-єдине ім'я: Сталван. Щоб розплутати цю нитку жаху, вона посилає мандрівників переглянути міські записи в Ратуші Даркшира.",h="«Легенда про Сталвана» починається в Даркширі з лиховісного видіння міської віщунки Мадам Єви.",kw={"легенда про сталвана","мадам єва","алісса","писар долтрі","ратуша даркшира","знамення"},ang={["class:Priest"]="Жерці, що ходять темними шляхами Даркшира, зважають на духовні застереження, тож моторошні знамення смерті від Мадам Єви — нагальна справа пастирського обов'язку.",["faction:Alliance"]="Сутінколісся бореться без регулярної підтримки армії Стормвінда, тож шукачі пригод з Альянсу часто допомагають міським старійшинам і захищають вразливі родини, як-от родину Мадам Єви."},sec={{t="Видіння смерті",b="У вічному мороці Сутінколісся Мадам Єва — місцева віщунка Даркшира, що тлумачить знамення й ворожить на картах стривоженим містянам. Прокинувшись від страшного неспокою, Єва звернулася до своєї ворожильної колоди — і витягла карту Смерті для своєї юної онуки Алісси. Поринувши в глибокий темний транс, щоб пробитися крізь морок, вона дізналася лише одну підказку: ім'я Сталван. Нажахана тим, що це знамення може означати для її родини й міста, вона просить вправних шукачів пригод піти за цією ниткою, доки не сталося лихо."},{t="Розпитати в ратуші",b="Єва знає: щоб дізнатися правду про Сталвана, треба зазирнути в писану історію Даркшира. Вона посилає шукачів пригод через площу до Ратуші Даркшира, до Писаря Долтрі — міського хранителя книг обліку й громадських архівів. Долтрі опікується запорошеними документами містечка, тож лише він може з'ясувати, чи був Сталван колишнім мешканцем, заїжджим мандрівником — чи чимось значно зловіснішим, похованим у минулому Сутінколісся."}},faq={{q="Хто така Мадам Єва?",a="Мадам Єва — ворожка й провидиця, що живе в Даркширі. Вона ворожить на картах і в трансі, щоб угледіти знамення майбутнього, і відчуває магічні збурення, що прокочуються Сутінколіссям.",al={"мадам єва","хто така єва","ворожка даркширу"}},{q="Чому Мадам Єві потрібна допомога?",a="Мадам Єві було жахливе видіння: її онука Алісса в смертельній небезпеці. Їй випала карта Смерті, а в трансі вона почула лише ім'я «Сталван», тож вона шукає допомоги, щоб дослідити загрозу.",al={"чому почати сталвана","видіння єви","чому допомагати єві"}},{q="Хто такий Писар Долтрі?",a="Писар Долтрі — міський архіваріус у Ратуші Даркшира. Він веде міські книги, реєстри й історичні документи, тож про незнайомі імена найкраще питати саме в нього.",al={"писар долтрі","долтрі","хто міський писар"}},{q="Що таке Ратуша Даркшира?",a="Ратуша Даркшира — адміністративний осередок містечка: тут сидять місцеві урядовці, зберігаються історичні записи й розташований штаб Нічної Варти.",al={"ратуша даркширу","ратуша сутінкового лісу"}},{q="Хто така Алісса?",a="Алісса — юна онука Мадам Єви, що живе в Даркширі. Ворожіння Єви показало, що над Аліссою нависло смертельне знамення, пов'язане з кимось на ім'я Сталван.",al={"алісса","онука мадам єви"}},{q="Куди веде це розслідування далі?",a="Розмова з Писарем Долтрі відкриває міські записи й давні розпити, з яких починається довге розслідування по всьому Сутінколіссю й сусідніх краях, щоб дізнатися історію й долю Сталвана.",al={"наступний крок сталвана","що каже долтрі"}}},fp="21,363,17.562.0,22.470.0,18.192.0,30.244.0,20.208.0,28.162.0,14.163.0,40.181.0"}
P.entries["quest:6608"] = {n="Ти надто добрий.",s="«Ти надто добрий» — завдання Орди від Лумака, наставника рибальства в Оргріммарі, яке він дає рибалці, що переріс звичайне навчання. Лумак відсилає свого вправного учня розшукати друга-людину Ната Паґла, що отаборився на відлюдному березі Багна Пилоброду. Це завдання знаменує перехід від звичайних уроків до вимогливого мистецтва справжнього майстра-рибалки.",h="«Ти надто добрий» — завдання Орди від Лумака, наставника рибальства в Оргріммарі, яке він дає рибалці, що...",kw={"рибальство","лумак","нат паґл","багно пилоброду","оргріммар","острів терамор","дружба"},ang={["faction:Horde"]="Це завдання показує, що й посеред війни фракцій часом зав'язується дружба через лінію фронту — завдяки нешкідливому ремеслу й спільним захопленням.",["race:Orc"]="Навіть у войовничій твердині Оргріммара Лумак доводить, що терпіння, добрий гумор і глибока повага до природи можуть допомогти оркові знайти друзів по той бік лінії фронту."},sec={{t="Межа Лумака",b="Лумак — головний наставник рибальства в Оргріммарі, що в Долині Честі, але навіть цей терплячий орк визнає, коли учень зрівнявся з ним у знанні вудки й котушки. Замість удавати, ніби має ще чого навчити, Лумак щиро зізнається, що рибалка став «надто добрий» для звичайних уроків. Щоб здобути ранг майстра, треба шукати за міськими мурами й за межами власного народу."},{t="Несподівана дружба",b="Попри тліючу ворожнечу між Ордою та Альянсом у Калімдорі, рибальство нерідко долає розбрат там, де дипломатія безсила. Лумак скеровує мандрівників до свого давнього знайомого, Ната Паґла, наполегливо застерігаючи, що людину не можна ні кривдити, ні їсти. Нат отаборився на острівці на південь від Острова Терамор у Багні Пилоброду й радо не зважає на політику, поки риба клює."}},faq={{q="Хто посилає мене на це завдання?",a="Лумак, наставник риболовлі, що стоїть біля води в Долині Честі в Оргріммарі, дає вам це завдання, коли ваше вміння риболовлі досить високе, щоб перейти вище рівня експерта.",al={"хто дає ти надто добрий","видавець лумак","де взяти ти надто добрий"}},{q="Де знайти Ната Паґла?",a="Нат Паґл живе на острівці біля узбережжя Багна Пилоброду, на південь від людського поселення Острів Терамор.",al={"де нат паґл","місце ната паґла","знайти ната паґла"}},{q="Звідки в орка друг-людина?",a="Рибалок по всьому Азероту часто єднає взаємна повага, що вища за війну фракцій. Лумак і Нат Паґл здружилися суто на ґрунті риболовлі, визнаючи пристрасть одне одного попри запеклу ворожнечу між орками й людьми.",al={"дружба лумака і ната паґла","чому нат паґл дружить з орком"}},{q="Що буде, коли я поговорю з Натом Паґлом?",a="Розмова з Натом Паґлом відкриває його вимогливе випробування для майстрів: вам доведеться мандрувати Азеротом і ловити рідкісну рибу, перш ніж він особисто навчить вас далі.",al={"чого навчає нат паґл","ремісниче рибальство завдання"}},{q="Чи безпечно Орді проходити через Терамор?",a="Ні, Терамор — місто-фортеця, яку пильно стереже Альянс. Шукачам пригод Орди доводиться обходити місто чи пробиратися узбережжям, щоб дістатися острова Ната й не накликати гніву вартових Терамора.",al={"чи орда може через терамор","дістатися ната паґла за орду"}},{q="Чому Лумак не може сам навчати мене далі?",a="Лумак навчив вас усього, що знав. Справжня майстерність у риболовлі потребує знань Ната Паґла, якого всюди вважають найлегендарнішим рибалкою відомого світу.",al={"чому лумак не вчить далі","експерт до майстра рибальство орда"}}},fp="13,350,14.413.0,22.406.0,27.165.0,27.118.0,36.227.0,39.176.0,44.197.0,41.164.0"}
P.entries["quest:6611"] = {n="Гайда до Ґаджетцана!",s="«Гайда до Ґаджетцана!» — мандрівка кухарів Орди, які прагнуть вийти за межі того, чого можуть навчити наставники столиці. За порадою Замджі з Оргріммара охочі кухарі вирушають на південь Калімдору, до Танарісу, щоб розшукати дивакуватого гобліна-м'ясника Дірджа Квіккліва. Це завдання-провідник знаменує перехід до справжньої майстерності в кулінарії.",h="«Гайда до Ґаджетцана!» — мандрівка кухарів Орди, які прагнуть вийти за межі того, чого можуть навчити...",kw={"кулінарія","ґаджетзан","дірдж квікклів","замджа","танаріс","кухар","картель стімвідл"},ang={["faction:Horde"]="Оргріммар покладається на сторонніх фахівців, як-от нейтральних гоблінів-кухарів, щоб його ремісники виходили за межі звичних племінних страв.",["profession:Cooking"]="Це завдання — віха, коли кухар переростає столичних наставників і мусить вирушити в небезпечні нетрі, щоб навчатися в справжнього майстра."},sec={{t="Кухар переростає Оргріммар",b="У Проході кухарка-троль Замджа годує незліченних воїнів і мандрівників, що проходять крізь червоні каньйони Дуротару. Та коли відданий кухар засвоює кожен рецепт і кожен прийом, яких може навчити Замджа, наставниця визнає поразку. Передавши все своє кулінарне моджо, вона відсилає досвідченого учня на південь, до пісків Танарісу: далі вести талановитого кухаря може лише справжній знавець дивного й екзотичного м'яса."},{t="М'ясник у пустелі",b="Пункт призначення — Ґаджетзан, торговий осередок на паровій тязі, яким керує картель Стімвідл. Там, у галасливій міській корчмі, хазяйнує Дірдж Квікклів. Гоблін із незвичайним смаком і без жодної кулінарної гидливості, Дірдж уславився на весь Калімдор тим, що перетворює страхітливу пустельну живність — а часом і клапті шкіри — на ситні страви, здатні підтримати сили загартованих шукачів пригод."}},faq={{q="Хто посилає мене до Ґаджетзана?",a="Замджа, тролиця-наставниця кулінарії рівня експерта, що стоїть біля вогнищ Проходу в Оргріммарі, дає це завдання кухарям, які опанували все, що вона знає.",al={"хто посилає до ґаджетзана","видавець завдання","завдання замджі"}},{q="Чому Замджа відсилає мене геть?",a="Замджа вичерпала всі рецепти й кулінарні прийоми, яких може навчити. Щоб досягти майстерного рівня кулінарії, вона скеровує обдарованих кухарів до Дірджа Квіккліва в Танарісі — ексцентричного знавця, що славиться вмінням готувати їстівні страви з найсуворіших пустельних інгредієнтів.",al={"чому ґаджетзан","чому дірдж квікклів","майстер кулінарії"}},{q="Хто такий Дірдж Квікклів?",a="Дірдж Квікклів — гоблін-м'ясник і наставник кулінарії майстерного рівня в корчмі Ґаджетзана. Він славиться крутою вдачею, дивними теоріями харчування — як-от що в старих шкіряних чоботях є білок — і майстерністю в найвишуканішій екзотичній кухні з дикої природи.",al={"дірдж","дірдж ґаджетзан"}},{q="Чи потрібне це завдання, щоб опанувати майстерну кулінарію?",a="Ні. Це завдання — лише дороговказ, що скеровує гравців Орди до Танаріса. Кухар із достатнім умінням може сам вирушити до Ґаджетзана й поговорити з Дірджем Квіккливом, не маючи рекомендації від Замджі.",al={"чи потрібне це завдання","хлібні крихти кулінарії","чи обов'язкове"}},{q="Де розташований Ґаджетзан?",a="Ґаджетзан — обнесена мурами пустельна застава картелю Стімвідл у північних пісках Танаріса, далеко на півдні материка Калімдор, нижче від Тисячі Голок.",al={"місце ґаджетзана","де дірдж"}},{q="Чи справді Замджа чогось учиться, коли я повертаюся?",a="Хоча Замджа жартома вимагає, щоб ви повернулися й навчили її, коли станете найкрутішим кухарем в окрузі, вона й далі лишається наставницею рівня експерта в Оргріммарі й підтримує свої вогнища для наступних поколінь мандрівників.",al={"чи замджа вчиться кулінарії","навчити замджу"}}},fp="20,356,25.422.0,25.395.0,27.158.0,29.269.0,24.267.0,48.224.0,27.179.0,51.206.0"}
P.entries["quest:6621"] = {n="Король Гнилолісу",s="«Король Гнилолісу» — військовий удар Орди, замовлений Каранґом Амаккаром на Заставі Зорам'гар. Прагнучи приборкати зіпсованих фурболгів Гнилолісу на південний схід від Астранаару, звитяжці Орди встромляють бойовий прапор просто на вершину священного тотемного пагорба племені, щоб виманити й стратити їхнього ватажка — Вождя Мурґута.",h="«Король Гнилолісу» — військовий удар Орди, замовлений Каранґом Амаккаром на Заставі Зорам'гар.",kw={"король гнилолісу","вождь мурґут","каранґ амаккар","село зеленолапів","фурболги","завдання"},ang={["class:Shaman"]="Спотворені тотеми й агресія Гнилолісу свідчать про невщухлий духовний розлад, що мучить споконвічні племена Ашенвалю після вторгнення Палаючого Легіону.",["faction:Horde"]="Каранґ Амаккар відкрито показує бойову перевагу, щоб залякати ворожі племена Ашенвалю й убезпечити центральні стежки для обозів Орди.",["race:Orc"]="Встромити прапор, щоб викликати ворожого ватажка на двобій, — класична орківська війна, де сила й рішуча сутичка важать більше, ніж затяжні перестрілки."},sec={{t="Показ сили",b="Поки нічні ельфи силкуються стримати зіпсовані племена Ашенвалю, Орда відповідає на загрозу розважливою агресією. Каранґ Амаккар із Застави Зорам'гар розуміє: хоч плем'я Гнилолісу й не може зрівнятися чисельністю з північними Будякохутрими, його неприборкана лють — прихована небезпека на південній дорозі. Не чекаючи засідок на дозори Орди, Каранґ наказує випереджально показати бойову перевагу й зламати волю племені."},{t="Осквернення й виклик",b="Удар спрямовано на Село Зеленолапів на північний схід від Озера Містраль. Каранґ виготовляє племінний бойовий прапор, який треба встромити просто в середину тотемного пагорба Гнилолісу, — непрощенна образа для духів предків і гордості племені. Захисники-фурболги у відчаї кидаються на пагорб, щоб зірвати зневажливий стяг, і змушують Вождя Мурґута вийти й обстояти свою честь у відкритому бою. Здобутий особистий тотем Мурґута розбиває провід племені й утверджує перевагу Орди в цьому краї."}},faq={{q="Хто наказує вбити Вождя Мурґута?",a="Каранґ Амаккар, орк із Застави Зорам'гар на західному узбережжі Ашенвалю, дає це доручення після того, як дослідив сусідніх фурболгів Будякохутрих.",al={"видавець короля гнилолісу","хто дає короля гнилолісу","завдання каранґа амаккара"}},{q="Де розташоване Село Зеленолапів?",a="Село Зеленолапів лежить на південний схід від поселення нічних ельфів Астранаар, на північний схід від Озера Містраль, трохи на південь від головного східного шляху Ашенвалю.",al={"де село зеленолапів","місце гнилолісу","де поставити прапор каранґа"}},{q="Навіщо Орда встромляє прапор у тотемний пагорб?",a="Встромити Прапор Каранґа просто в священний тотемний пагорб племені — навмисна провокація. Наруга над святинею змушує Гнилоліс у люті кинутися в бій, а Вождя Мурґута — битися відкрито, щоб не втратити свого становища.",al={"чому ставити прапор","призначення прапора на пагорбі","чому кидати виклик мурґуту"}},{q="Хто такі фурболги Гнилолісу?",a="Гнилоліс — одне з кількох племен фурболгів Ашенвалю, що після Третьої війни поринули в безумство й скверну. Хоч їх менше, ніж Будякохутрих, вони й далі жорстокі й ворожі до чужинців.",al={"що таке гниліліс","переказ про плем'я гнилолісу","хто вождь мурґут"}},{q="Що дає повернення Тотема Мурґута?",a="Тотем Вождя Мурґута, принесений на Заставу Зорам'гар, доводить, що вождя переможено. Без ватажка й зі зганьбленим священним пагорбом уцілілі фурболги Гнилолісу залякані й уникають нових сутичок з Ордою.",al={"призначення тотема мурґута","що буде після смерті мурґута"}},{q="Як це завдання пов'язане з попередніми розслідуваннями про фурболгів?",a="Це доручення йде одразу після завдання «Між каменем і Будякохутрими». Розібравшись із північним племенем Будякохутрих, Каранґ звертає погляд на південь, щоб завчасно розгромити Гнилоліс, перш ніж той почне злагоджені набіги.",al={"між каменем і будякохутрим","попередник короля гнилолісу"}}},fp="21,312,15.490.0,25.511.0,37.180.0,34.158.0,53.240.0,31.222.0,47.227.0,64.229.0"}
P.entries["quest:6623"] = {n="Травматологія Орди",s="«Травматологія Орди» — поклик, що скеровує вправних цілителів Орди до Гаммерфолла в Аратійському нагір'ї. Доктор Ґреґорі Віктор, головний лікар травматологічної служби Орди, шукає й перевіряє вмілі руки, здатні рятувати життя під шаленим тиском. Відгукнувшись на цей поклик, лікар потрапляє просто в похмуру й небезпечну дійсність польової хірургії на передовій.",h="«Травматологія Орди» — поклик, що скеровує вправних цілителів Орди до Гаммерфолла в Аратійському нагір'ї.",ang={["class:Priest"]="Божественна магія загоює рани миттєво, але звичайне медичне сортування вчить важливої дисципліни: визначати, кого ще можна врятувати, коли мана висохла до останньої краплі.",["faction:Horde"]="Військова міць Орди значною мірою тримається на загартованих польових хірургах, які латають бійців і повертають їх у стрій у жорстоких прикордонних сутичках, як-от в Аратійській Улоговині."},sec={{t="Поклик із Гаммерфолла",b="У Долині Духів в Оргріммарі орк Арнок, наставник першої допомоги, повідомляє вправним цілителям, що на них звернув увагу сам Доктор Ґреґорі Віктор. Віктор очолює травматологічну службу Орди в укріпленій заставі Гаммерфолл, що ховається серед спірних пагорбів Аратійського нагір'я. Арнок бачить у цьому поклику не просто наказ, а вершину професійного зростання для кожного польового хірурга."},{t="Жорстока робота польового сортування",b="Діставшись Гаммерфолла, новачки розуміють, що служба тут далеко не затишна. Віктор працює серед безперервних сутичок із Лігою Аратора та місцевими ворожими силами, і до нього потоком везуть поранених бійців, рейдерів і розвідників. Головний лікар не гає часу на люб'язності: новобранцям одразу наказують перевдягнутися в робочий одяг і довести, чого вони варті, під час жорсткого й швидкого сортування поранених."}},faq={{q="Що таке Травматологія Орди?",a="Травматологія Орди — окрема медична й хірургічна служба передової Орди. Нею керує Доктор Ґреґорі Віктор із Гаммерфолла, а її члени спеціалізуються на польовій медицині, сортуванні поранених і лікуванні тяжких бойових ран серед хаосу.",al={"фракція травматологія орди","що таке травматологія орди","хто травматологія орди"}},{q="Хто посилає мене на це доручення?",a="Виклик дає Арнок, орк-наставник першої допомоги в Долині Духів в Оргріммарі. Служити під проводом Доктора Ґреґорі Віктора він вважає найвищою честю, про яку може мріяти польовий лікар-початківець.",al={"quest giver horde trauma","who starts horde trauma","krenk choplimb","arnok"}},{q="Де знайти Доктора Ґреґорі Віктора?",a="Доктор Ґреґорі Віктор працює в лазареті Гаммерфолла — головної твердині Орди на північному сході Аратійського нагір'я.",al={"доктор ґреґорі віктор","де віктор","лікар гаммерфолла"}},{q="Що буде, коли я доповім у Гаммерфоллі?",a="Щойно ви прибудете, Доктор Віктор звелить вам перевдягтися в робочий одяг для наступного завдання — «Сортування поранених». На вас чекає напружене випробування: треба визначити черговість і вилікувати солдатів, яким швидко гіршає, перш ніж вони помруть від ран.",al={"що після травматології орди","наступне завдання після травматології","завдання сортування"}},{q="Чому Гаммерфоллу так бракує польових лікарів?",a="Гаммерфолл оточений ворогами в Араті: тут не вщухають сутички з людськими загонами, агентами Синдикату й місцевими звірами. Поранені безперервно прибувають до табору, і нечисленні лікарі бази працюють на межі сил.",al={"чому гаммерфоллу бракує лікарів","медична ситуація гаммерфолла"}},{q="Чи можуть гравці Альянсу взятися за це доручення?",a="Ні. Травматологія Орди — лише для членів Орди. В Альянсу є рівноцінне медичне випробування, яке проводить Доктор Ґустаф ВанГаузен у твердині Острів Терамор.",al={"чи альянс може травматологію орди","версія для альянсу травматології"}}},fp="12,389,25.427.0,37.419.0,21.279.0,32.206.0,39.149.0,43.262.0,48.240.0,42.180.0"}
P.entries["quest:6625"] = {n="Травматологія Альянсу",s="Травматологія Альянсу — виклик, що скеровує досвідчених польових лікарів на Острів Терамор у Багні Пилоброду. Наставники з першої допомоги в столицях Альянсу запрошують умілих цілителів навчатися в Доктора Ґустафа ВанГаузена, головного лікаря добірного медичного корпусу Альянсу.",h="Травматологія Альянсу — виклик, що скеровує досвідчених польових лікарів на Острів Терамор у Багні Пилоброду.",kw={"травматологія альянсу","перша допомога","ґустаф вангаузен","острів терамор","багно пилоброду","лікар"},ang={["faction:Alliance"]="Травматологія Альянсу дбає, щоб бійці на передовій у Калімдорі й Східних Королівствах мали вмілих польових лікарів, здатних під вогнем рятувати важкопоранених.",["race:Dwarf"]="Наставники на кшталт Нісси Файрстоун в Айронфорджі охоче шукають біля Великої Кузні здібних цілителів, щоб ті представляли найкращі медичні таланти Альянсу в Тераморі."},sec={{t="Поклик на передову",b="Коли лікар опановує основи, яких навчають у великих містах Альянсу, місцеві наставники вже мало що можуть йому дати. Про тих, хто виявляє винятковий хист до голки, бинтів і сортування поранених, звістку надсилають просто Докторові Ґустафу ВанГаузену. З прикордонної твердині на Острові Терамор ВанГаузен керує Травматологією Альянсу — організацією, що рятує життя в найжорстокіших зонах бойових дій Калімдору й поза ним."},{t="Дорога до Терамора",b="Наставники на кшталт Нісси Файрстоун в Айронфорджі вважають особистий виклик від ВанГаузена винятковою честю. На Острів Терамор постійно тиснуть місцеві загрози, сутички й суворі умови дикого краю, тож поранені вояки прибувають безперервним потоком. Щоб дістатися до лікарні ВанГаузена, доводиться довго плисти морем до Багна Пилоброду, і лише найвитриманіші польові хірурги можуть сподіватися пройти його суворі перевірки."}},faq={{q="Що таке Травматологія Альянсу?",a="Травматологія Альянсу — добірна медична служба, що відповідає за складну польову медицину й сортування поранених по всьому Альянсу. Очолює її головний Лікар Ґустаф ВанГаузен, і вона береться за тяжкі рани, з якими не впорається звичайна польова перев'язка.",al={"переказ про травматологію альянсу","хто травматологія альянсу"}},{q="Хто посилає на це завдання?",a="Наставники першої допомоги Альянсу, як-от Нісса Файрстоун біля Великої Кузні в Айронфорджі, відправляють обдарованих цілителів, щойно ті досягнуть вершини звичайного навчання.",al={"хто дає травматологію альянсу","видавець першої допомоги айронфорджа"}},{q="Куди треба вирушити?",a="Вам треба дістатися людської портової фортеці Острів Терамор на східному узбережжі Багна Пилоброду, на материку Калімдор.",al={"де ванґаузен","куди йти травматологія альянсу"}},{q="Хто такий Доктор Ґустаф ВанГаузен?",a="Доктор Ґустаф ВанГаузен — головний лікар Травматології Альянсу. Він працює у військовій лікарні в Тераморі, і його вважають одним із найбільших знавців невідкладної медицини й хірургічного сортування в Альянсі.",al={"ґустаф ванґаузен","головний лікар ванґаузен"}},{q="Що буде після доповіді Докторові ВанГаузену?",a="Коли ви прибудете до Терамора, ВанГаузен влаштує кандидатам суворе практичне випробування з сортування поранених: треба рятувати хвилю за хвилею вмирущих солдатів, і лише тоді він прийме вас до вищих лав польової медицини.",al={"що після травматології альянсу","наступне завдання сортування"}},{q="Чому лікарня в Тераморі, а не в Стормвінді чи Айронфорджі?",a="Терамор — діяльний прикордонний гарнізон серед ворожих боліт, небезпечних звірів і сутичок за землю. Тяжкопоранені вояки прибувають сюди безперервно, тож це ідеальне місце для напруженого навчання травматології.",al={"чому лікарня в тераморі","чому пилові болота"}}},fp="15,307,19.448.0,21.468.0,24.252.0,28.178.0,28.143.0,31.221.0,49.217.0,71.240.0"}
P.entries["quest:6627"] = {n="Випробування знань",s="«Випробування знань» — випробування розуму й історичної пам'яті, яке призначає відлюдник Брауґ Дімспіріт у Горах Кам'яного Кігтя. Здобувши прадавній том «Спадок Аспектів», мандрівники мають довести, що розуміють давню історію, відповівши на запитання Брауґа. Тих, хто не вчитався в текст, раптово відкидає через увесь Калімдор.",h="«Випробування знань» — випробування розуму й історичної пам'яті, яке призначає відлюдник Брауґ Дімспіріт у...",kw={"випробування знань","брауґ дімспіріт","спадок аспектів","нелтаріон","табір тауражо","аспекти-дракони"},ang={["class:Mage"]="Маги визнають телепортаційний оберіг Брауґа водночас і вражаючим, і каральним: відлюдники Гір Кам'яного Кігтя володіють давньою магією, щоб навчати розуму недбалих учнів.",["faction:Horde"]="Випробування Орди в Калімдорі вимагають більшого, ніж груба сила: і від воїнів, і від шаманів чекають розуміння давніх ран і драконячих сил, що сформували континент.",["race:Tauren"]="Це випробування втілює тауренську шану до мудрості предків і давньої історії, щоб молоді герої не йшли наосліп, не знаючи рівноваги світу."},sec={{t="Випробування мудрості",b="Випробування знань — частина ширшої низки випробувань, що починаються в Дорна Плейнстокера у Вивітреному Закутку, — зміщує увагу з виживання в бою чи сліпої довіри на розуміння давнього минулого світу. Брауґ Дімспіріт, що живе серед круч Гір Кам'яного Кігтя, вимагає від шукачів знайти давні тексти й по-справжньому засвоїти знання з їхніх сторінок."},{t="Спадок Аспектів",b="Урок присвячено створенню й розподілу Аспектів-драконів, а надто доленосній угоді, укладеній задовго до Великого Розколу. Брауґ перевіряє, що шукач запам'ятав про Охоронця Землі, Нелтаріона, чиє падіння в божевілля й зрада змінили обличчя Азероту. Тих, хто не шанує історію, не пускають далі шляхом мудрості."},{t="Ціна здогадок",b="Брауґ не терпить пустих здогадок. Шукача, що відповість неправильно, миттю виганяє містична сила — і він опиняється за багато миль, у Таборі Тауражо на півдні Пусток. Щоб повернути собі місце, доведеться довго чвалати назад угору, до Гір Кам'яного Кігтя, й удруге постати перед прискіпливим відлюдником."}},faq={{q="Яка правильна відповідь на запитання Брауґа Дімспіріта?",a="Брауґ питає, хто такий Вартовий Землі, описаний у книзі «Спадок Аспектів». Правильна відповідь — Нелтаріон, Чорний Аспект, який згодом обернеться проти інших драконів.",al={"відповідь брауґу","відповідь випробування знань","запитання про спадщину аспектів"}},{q="Що буде, якщо відповісти неправильно?",a="Якщо назвати Брауґові не те ім'я, магія миттю вижене вас геть — просто до Табору Тауражо в Пустках. Доведеться пройти весь шлях назад до його скелі в Горах Кам'яного Кігтя, щоб спробувати знову.",al={"неправильна відповідь випробування знань","провалив випробування знань","телепорт у тауражо"}},{q="Хто такий Брауґ Дімспіріт?",a="Брауґ Дімспіріт — старий відлюдник із Гір Кам'яного Кігтя, який перевіряє знання й обізнаність у переказах для Орди, продовжуючи низку духовних випробувань, що почалася в Тисячі Голок.",al={"брауґ дімспіріт","хто дає випробування знань"}},{q="Як це пов'язано з випробуваннями в Тисячі Голок?",a="Випробування почалося з Дорна Плейнстокера в Обвітреному Закутку в Тисячі Голок — з «Випробування віри». Дорн перевіряє тілесну й духовну довіру, а тоді посилає гідних учнів по всьому Калімдору, щоб інші мудрі старійшини перевірили їхній розум, рішучість і силу.",al={"зв'язок з дорном рівнинним","ланцюжок випробування віри"}},{q="Про яку книгу питає Брауґ?",a="Запитання перевіряє, як ви зрозуміли «Спадок Аспектів» — прадавній трактат про те, як титани благословили п'ятьох Великих Аспектів-драконів берегти Азерот.",al={"яка книга в брауґа","спадщина аспектів"}},{q="Куди веде цей ланцюжок завдань далі?",a="Склавши Брауґів іспит про Аспектів-драконів, ви переходите до дальших випробувань із давньої історії: шукачам доведеться обнишпорити далекі краї в пошуках загублених записів і знань предків.",al={"що після випробування знань","наступне завдання випробування знань"}}},fp="12,361,17.381.0,21.371.0,22.317.1,49.193.0,39.226.0,23.203.0,56.265.0,38.171.0,38.192.0"}
